window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EST"]={"book":"EST","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֖י בִּ⁠ימֵ֣י אֲחַשְׁוֵר֑וֹשׁ ה֣וּא אֲחַשְׁוֵר֗וֹשׁ הַ⁠מֹּלֵךְ֙ מֵ⁠הֹ֣דּוּ וְ⁠עַד־כּ֔וּשׁ שֶׁ֛בַע וְ⁠עֶשְׂרִ֥ים וּ⁠מֵאָ֖ה מְדִינָֽה׃","wa⁠yĕhi֖y bi̇⁠ymé֣y ʼàẖaşĕ̌wér֑wòş̌ h֣ẇʼ ʼàẖaşĕ̌wér֗wòş̌ ha⁠mò̇lékĕ֙ mé⁠hò֣ḋẇ wĕ⁠ʻad-k̇֔ẇş̌ şě֛baʻ wĕ⁠ʻeşĕ̂ri֥ym ẇ⁠méʼá֖h mĕdiynáֽh׃"],[1,2,"בַּ⁠יָּמִ֖ים הָ⁠הֵ֑ם כְּ⁠שֶׁ֣בֶת ׀ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ עַ֚ל כִּסֵּ֣א מַלְכוּת֔⁠וֹ אֲשֶׁ֖ר בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָֽה׃","bȧ⁠yá̇mi֖ym há⁠hé֑m kĕ̇⁠şě֣beţ ׀ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ ʻa֚l ki̇sé֣̇ʼ malĕkẇţ֔⁠wò ʼàşě֖r bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yráֽh׃"],[1,3,"בִּ⁠שְׁנַ֤ת שָׁלוֹשׁ֙ לְ⁠מָלְכ֔⁠וֹ עָשָׂ֣ה מִשְׁתֶּ֔ה לְ⁠כָל־שָׂרָ֖י⁠ו וַ⁠עֲבָדָ֑י⁠ו חֵ֣יל ׀ פָּרַ֣ס וּ⁠מָדַ֗י הַֽ⁠פַּרְתְּמִ֛ים וְ⁠שָׂרֵ֥י הַ⁠מְּדִינ֖וֹת לְ⁠פָנָֽי⁠ו׃","bi̇⁠şĕ̌na֤ţ şá̌lwòş̌֙ lĕ⁠málĕk֔⁠wò ʻáşá֣̂h mişĕ̌ţė֔h lĕ⁠kál-şá̂rá֖y⁠w wa⁠ʻàbádá֑y⁠w ẖé֣yl ׀ pá̇ra֣s ẇ⁠máda֗y haֽ⁠pȧrĕţĕ̇mi֛ym wĕ⁠şá̂ré֥y ha⁠mĕ̇diyn֖wòţ lĕ⁠pánáֽy⁠w׃"],[1,4,"בְּ⁠הַרְאֹת֗⁠וֹ אֶת־עֹ֨שֶׁר֙ כְּב֣וֹד מַלְכוּת֔⁠וֹ וְ⁠אֶ֨ת־יְקָ֔ר תִּפְאֶ֖רֶת גְּדוּלָּת֑⁠וֹ יָמִ֣ים רַבִּ֔ים שְׁמוֹנִ֥ים וּ⁠מְאַ֖ת יֽוֹם׃","bĕ̇⁠harĕʼòţ֗⁠wò ʼeţ-ʻò֨şěr֙ kĕ̇b֣wòd malĕkẇţ֔⁠wò wĕ⁠ʼe֨ţ-yĕqá֔r ţi̇pĕʼe֖reţ gĕ̇dẇlá̇ţ֑⁠wò yámi֣ym rabi̇֔ym şĕ̌mwòni֥ym ẇ⁠mĕʼa֖ţ yֽwòm׃"],[1,5,"וּ⁠בִ⁠מְל֣וֹאת ׀ הַ⁠יָּמִ֣ים הָ⁠אֵ֗לֶּה עָשָׂ֣ה הַ⁠מֶּ֡לֶךְ לְ⁠כָל־הָ⁠עָ֣ם הַ⁠נִּמְצְאִים֩ בְּ⁠שׁוּשַׁ֨ן הַ⁠בִּירָ֜ה לְ⁠מִ⁠גָּ֧דוֹל וְ⁠עַד־קָטָ֛ן מִשְׁתֶּ֖ה שִׁבְעַ֣ת יָמִ֑ים בַּ⁠חֲצַ֕ר גִּנַּ֥ת בִּיתַ֖ן הַ⁠מֶּֽלֶךְ׃","ẇ⁠bi⁠mĕl֣wòʼţ ׀ ha⁠yá̇mi֣ym há⁠ʼé֗lėh ʻáşá֣̂h ha⁠mė֡lekĕ lĕ⁠kál-há⁠ʻá֣m ha⁠ni̇mĕẕĕʼiym֩ bĕ̇⁠ş̌ẇşǎ֨n ha⁠bi̇yrá֜h lĕ⁠mi⁠gá֧̇dwòl wĕ⁠ʻad-qátá֛n mişĕ̌ţė֖h şǐbĕʻa֣ţ yámi֑ym bȧ⁠ẖàẕa֕r gi̇nȧ֥ţ bi̇yţa֖n ha⁠mėֽlekĕ׃"],[1,6,"ח֣וּר ׀ כַּרְפַּ֣ס וּ⁠תְכֵ֗לֶת אָחוּז֙ בְּ⁠חַבְלֵי־ב֣וּץ וְ⁠אַרְגָּמָ֔ן עַל־גְּלִ֥ילֵי כֶ֖סֶף וְ⁠עַמּ֣וּדֵי שֵׁ֑שׁ מִטּ֣וֹת ׀ זָהָ֣ב וָ⁠כֶ֗סֶף עַ֛ל רִֽצְפַ֥ת בַּהַט־וָ⁠שֵׁ֖שׁ וְ⁠דַ֥ר וְ⁠סֹחָֽרֶת׃","ẖ֣ẇr ׀ kȧrĕpȧ֣s ẇ⁠ţĕké֗leţ ʼáẖẇz֙ bĕ̇⁠ẖabĕléy-b֣ẇẕ wĕ⁠ʼarĕgá̇má֔n ʻal-gĕ̇li֥yléy ke֖sep wĕ⁠ʻaṁ֣ẇdéy şé֑̌ş̌ miṫ֣wòţ ׀ záhá֣b wá⁠ke֗sep ʻa֛l riֽẕĕpa֥ţ bȧhat-wá⁠şé֖̌ş̌ wĕ⁠da֥r wĕ⁠sòẖáֽreţ׃"],[1,7,"וְ⁠הַשְׁקוֹת֙ בִּ⁠כְלֵ֣י זָהָ֔ב וְ⁠כֵלִ֖ים מִ⁠כֵּלִ֣ים שׁוֹנִ֑ים וְ⁠יֵ֥ין מַלְכ֛וּת רָ֖ב כְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wĕ⁠haşĕ̌qwòţ֙ bi̇⁠kĕlé֣y záhá֔b wĕ⁠kéli֖ym mi⁠ké̇li֣ym ş̌wòni֑ym wĕ⁠yé֥yn malĕk֛ẇţ rá֖b kĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[1,8,"וְ⁠הַ⁠שְּׁתִיָּ֥ה כַ⁠דָּ֖ת אֵ֣ין אֹנֵ֑ס כִּי־כֵ֣ן ׀ יִסַּ֣ד הַ⁠מֶּ֗לֶךְ עַ֚ל כָּל־רַ֣ב בֵּית֔⁠וֹ לַ⁠עֲשׂ֖וֹת כִּ⁠רְצ֥וֹן אִישׁ־וָ⁠אִֽישׁ׃","wĕ⁠ha⁠şĕ̇̌ţiyá֥̇h ka⁠dá֖̇ţ ʼé֣yn ʼòné֑s ki̇y-ké֣n ׀ yisȧ֣d ha⁠mė֗lekĕ ʻa֚l ká̇l-ra֣b bé̇yţ֔⁠wò la⁠ʻàş֖̂wòţ ki̇⁠rĕẕ֥wòn ʼiyş̌-wá⁠ʼiֽyş̌׃"],[1,9,"גַּ֚ם וַשְׁתִּ֣י הַ⁠מַּלְכָּ֔ה עָשְׂתָ֖ה מִשְׁתֵּ֣ה נָשִׁ֑ים בֵּ֚ית הַ⁠מַּלְכ֔וּת אֲשֶׁ֖ר לַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃ס","gȧ֚m waşĕ̌ţi֣̇y ha⁠mȧlĕká̇֔h ʻáşĕ̂ţá֖h mişĕ̌ţé֣̇h náşǐ֑ym bé֚̇yţ ha⁠mȧlĕk֔ẇţ ʼàşě֖r la⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃s"],[1,10,"בַּ⁠יּוֹם֙ הַ⁠שְּׁבִיעִ֔י כְּ⁠ט֥וֹב לֵב־הַ⁠מֶּ֖לֶךְ בַּ⁠יָּ֑יִן אָמַ֡ר לִ֠⁠מְהוּמָן בִּזְּתָ֨א חַרְבוֹנָ֜א בִּגְתָ֤א וַ⁠אֲבַגְתָא֙ זֵתַ֣ר וְ⁠כַרְכַּ֔ס שִׁבְעַת֙ הַ⁠סָּ֣רִיסִ֔ים הַ⁠מְשָׁ֣רְתִ֔ים אֶת־פְּנֵ֖י הַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","bȧ⁠ẏwòm֙ ha⁠şĕ̇̌biyʻi֔y kĕ̇⁠t֥wòb léb-ha⁠mė֖lekĕ bȧ⁠yá֑̇yin ʼáma֡r li֠⁠mĕhẇmán bi̇zĕ̇ţá֨ʼ ẖarĕbwòná֜ʼ bi̇gĕţá֤ʼ wa⁠ʼàbagĕţáʼ֙ zéţa֣r wĕ⁠karĕkȧ֔s şǐbĕʻaţ֙ ha⁠sá֣̇riysi֔ym ha⁠mĕşá֣̌rĕţi֔ym ʼeţ-pĕ̇né֖y ha⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,11,"לְ֠⁠הָבִיא אֶת־וַשְׁתִּ֧י הַ⁠מַּלְכָּ֛ה לִ⁠פְנֵ֥י הַ⁠מֶּ֖לֶךְ בְּ⁠כֶ֣תֶר מַלְכ֑וּת לְ⁠הַרְא֨וֹת הָֽ⁠עַמִּ֤ים וְ⁠הַ⁠שָּׂרִים֙ אֶת־יָפְיָ֔⁠הּ כִּֽי־טוֹבַ֥ת מַרְאֶ֖ה הִֽיא׃","lĕ֠⁠hábiyʼ ʼeţ-waşĕ̌ţi֧̇y ha⁠mȧlĕká֛̇h li⁠pĕné֥y ha⁠mė֖lekĕ bĕ̇⁠ke֣ţer malĕk֑ẇţ lĕ⁠harĕʼ֨wòţ háֽ⁠ʻami֤̇ym wĕ⁠ha⁠şá̇̂riym֙ ʼeţ-yápĕyá֔⁠ḣ kiֽ̇y-twòba֥ţ marĕʼe֖h hiֽyʼ׃"],[1,12,"וַ⁠תְּמָאֵ֞ן הַ⁠מַּלְכָּ֣ה וַשְׁתִּ֗י לָ⁠בוֹא֙ בִּ⁠דְבַ֣ר הַ⁠מֶּ֔לֶךְ אֲשֶׁ֖ר בְּ⁠יַ֣ד הַ⁠סָּרִיסִ֑ים וַ⁠יִּקְצֹ֤ף הַ⁠מֶּ֨לֶךְ֙ מְאֹ֔ד וַ⁠חֲמָת֖⁠וֹ בָּעֲרָ֥ה בֽ⁠וֹ׃","wa⁠ţĕ̇máʼé֞n ha⁠mȧlĕká֣̇h waşĕ̌ţi̇֗y lá⁠bwòʼ֙ bi̇⁠dĕba֣r ha⁠mė֔lekĕ ʼàşě֖r bĕ̇⁠ya֣d ha⁠sá̇riysi֑ym wa⁠yi̇qĕẕò֤p ha⁠mė֨lekĕ֙ mĕʼò֔d wa⁠ẖàmáţ֖⁠wò bá̇ʻàrá֥h bֽ⁠wò׃"],[1,13,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ לַ⁠חֲכָמִ֖ים יֹדְעֵ֣י הָֽ⁠עִתִּ֑ים כִּי־כֵן֙ דְּבַ֣ר הַ⁠מֶּ֔לֶךְ לִ⁠פְנֵ֕י כָּל־יֹדְעֵ֖י דָּ֥ת וָ⁠דִֽין׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ la⁠ẖàkámi֖ym yòdĕʻé֣y hֽá⁠ʻiţi֑̇ym ki̇y-kén֙ dĕ̇ba֣r ha⁠mė֔lekĕ li⁠pĕné֕y ká̇l-yòdĕʻé֖y dá֥̇ţ wá⁠diֽyn׃"],[1,14,"וְ⁠הַ⁠קָּרֹ֣ב אֵלָ֗י⁠ו כַּרְשְׁנָ֤א שֵׁתָר֙ אַדְמָ֣תָא תַרְשִׁ֔ישׁ מֶ֥רֶס מַרְסְנָ֖א מְמוּכָ֑ן שִׁבְעַ֞ת שָׂרֵ֣י ׀ פָּרַ֣ס וּ⁠מָדַ֗י רֹאֵי֙ פְּנֵ֣י הַ⁠מֶּ֔לֶךְ הַ⁠יֹּשְׁבִ֥ים רִאשֹׁנָ֖ה בַּ⁠מַּלְכֽוּת׃","wĕ⁠ha⁠qá̇rò֣b ʼélá֗y⁠w kȧrĕşĕ̌ná֤ʼ şé̌ţár֙ ʼadĕmá֣ţáʼ ţarĕşǐ֔yş̌ me֥res marĕsĕná֖ʼ mĕmẇká֑n şǐbĕʻa֞ţ şá̂ré֣y ׀ pá̇ra֣s ẇ⁠máda֗y ròʼéy֙ pĕ̇né֣y ha⁠mė֔lekĕ ha⁠yò̇şĕ̌bi֥ym riʼşò̌ná֖h bȧ⁠mȧlĕkֽẇţ׃"],[1,15,"כְּ⁠דָת֙ מַֽה־לַּ⁠עֲשׂ֔וֹת בַּ⁠מַּלְכָּ֖ה וַשְׁתִּ֑י עַ֣ל ׀ אֲשֶׁ֣ר לֹֽא־עָשְׂתָ֗ה אֶֽת־מַאֲמַר֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ בְּ⁠יַ֖ד הַ⁠סָּרִיסִֽים׃ס","kĕ̇⁠dáţ֙ maֽh-lȧ⁠ʻàş̂֔wòţ bȧ⁠mȧlĕká֖̇h waşĕ̌ţi֑̇y ʻa֣l ׀ ʼàşě֣r lòֽʼ-ʻáşĕ̂ţá֗h ʼeֽţ-maʼàmar֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ bĕ̇⁠ya֖d ha⁠sá̇riysiֽym׃s"],[1,16,"וַ⁠יֹּ֣אמֶר מומכן לִ⁠פְנֵ֤י הַ⁠מֶּ֨לֶךְ֙ וְ⁠הַ⁠שָּׂרִ֔ים לֹ֤א עַל־הַ⁠מֶּ֨לֶךְ֙ לְ⁠בַדּ֔⁠וֹ עָוְתָ֖ה וַשְׁתִּ֣י הַ⁠מַּלְכָּ֑ה כִּ֤י עַל־כָּל־הַ⁠שָּׂרִים֙ וְ⁠עַל־כָּל־הָ֣⁠עַמִּ֔ים אֲשֶׁ֕ר בְּ⁠כָל־מְדִינ֖וֹת הַ⁠מֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wa⁠yò֣̇ʼmer mwmkn li⁠pĕné֤y ha⁠mė֨lekĕ֙ wĕ⁠ha⁠şá̇̂ri֔ym lò֤ʼ ʻal-ha⁠mė֨lekĕ֙ lĕ⁠baḋ֔⁠wò ʻáwĕţá֖h waşĕ̌ţi֣̇y ha⁠mȧlĕká֑̇h ki֤̇y ʻal-ká̇l-ha⁠şá̇̂riym֙ wĕ⁠ʻal-ká̇l-há֣⁠ʻami̇֔ym ʼàşě֕r bĕ̇⁠kál-mĕdiyn֖wòţ ha⁠mė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,17,"כִּֽי־יֵצֵ֤א דְבַר־הַ⁠מַּלְכָּה֙ עַל־כָּל־הַ⁠נָּשִׁ֔ים לְ⁠הַבְז֥וֹת בַּעְלֵי⁠הֶ֖ן בְּ⁠עֵינֵי⁠הֶ֑ן בְּ⁠אָמְרָ֗⁠ם הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֡וֹשׁ אָמַ֞ר לְ⁠הָבִ֨יא אֶת־וַשְׁתִּ֧י הַ⁠מַּלְכָּ֛ה לְ⁠פָנָ֖י⁠ו וְ⁠לֹא־בָֽאָה׃","kiֽ̇y-yéẕé֤ʼ dĕbar-ha⁠mȧlĕká̇h֙ ʻal-ká̇l-ha⁠ná̇şǐ֔ym lĕ⁠habĕz֥wòţ bȧʻĕléy⁠he֖n bĕ̇⁠ʻéynéy⁠he֑n bĕ̇⁠ʼámĕrá֗⁠m ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֡wòş̌ ʼáma֞r lĕ⁠hábi֨yʼ ʼeţ-waşĕ̌ţi֧̇y ha⁠mȧlĕká֛̇h lĕ⁠páná֖y⁠w wĕ⁠lòʼ-báֽʼáh׃"],[1,18,"וְֽ⁠הַ⁠יּ֨וֹם הַ⁠זֶּ֜ה תֹּאמַ֣רְנָה ׀ שָׂר֣וֹת פָּֽרַס־וּ⁠מָדַ֗י אֲשֶׁ֤ר שָֽׁמְעוּ֙ אֶת־דְּבַ֣ר הַ⁠מַּלְכָּ֔ה לְ⁠כֹ֖ל שָׂרֵ֣י הַ⁠מֶּ֑לֶךְ וּ⁠כְ⁠דַ֖י בִּזָּי֥וֹן וָ⁠קָֽצֶף׃","wĕֽ⁠ha⁠ẏ֨wòm ha⁠zė֜h ţò̇ʼma֣rĕnáh ׀ şá̂r֣wòţ páֽ̇ras-ẇ⁠máda֗y ʼàşě֤r şáֽ̌mĕʻẇ֙ ʼeţ-dĕ̇ba֣r ha⁠mȧlĕká̇֔h lĕ⁠kò֖l şá̂ré֣y ha⁠mė֑lekĕ ẇ⁠kĕ⁠da֖y bi̇zá̇y֥wòn wá⁠qáֽẕep׃"],[1,19,"אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֗וֹב יֵצֵ֤א דְבַר־מַלְכוּת֙ מִ⁠לְּ⁠פָנָ֔י⁠ו וְ⁠יִכָּתֵ֛ב בְּ⁠דָתֵ֥י פָֽרַס־וּ⁠מָדַ֖י וְ⁠לֹ֣א יַעֲב֑וֹר אֲשֶׁ֨ר לֹֽא־תָב֜וֹא וַשְׁתִּ֗י לִ⁠פְנֵי֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וּ⁠מַלְכוּתָ⁠הּ֙ יִתֵּ֣ן הַ⁠מֶּ֔לֶךְ לִ⁠רְעוּתָ֖⁠הּ הַ⁠טּוֹבָ֥ה מִמֶּֽ⁠נָּה׃","ʼim-ʻal-ha⁠mė֣lekĕ t֗wòb yéẕé֤ʼ dĕbar-malĕkẇţ֙ mi⁠lĕ̇⁠páná֔y⁠w wĕ⁠yiká̇ţé֛b bĕ̇⁠dáţé֥y páֽras-ẇ⁠máda֖y wĕ⁠lò֣ʼ yaʻàb֑wòr ʼàşě֨r lòֽʼ-ţáb֜wòʼ waşĕ̌ţi̇֗y li⁠pĕnéy֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ ẇ⁠malĕkẇţá⁠ḣ֙ yiţé֣̇n ha⁠mė֔lekĕ li⁠rĕʻẇţá֖⁠ḣ ha⁠ṫwòbá֥h mimėֽ⁠ná̇h׃"],[1,20,"וְ⁠נִשְׁמַע֩ פִּתְגָ֨ם הַ⁠מֶּ֤לֶךְ אֲשֶֽׁר־יַעֲשֶׂה֙ בְּ⁠כָל־מַלְכוּת֔⁠וֹ כִּ֥י רַבָּ֖ה הִ֑יא וְ⁠כָל־הַ⁠נָּשִׁ֗ים יִתְּנ֤וּ יְקָר֙ לְ⁠בַעְלֵי⁠הֶ֔ן לְ⁠מִ⁠גָּד֖וֹל וְ⁠עַד־קָטָֽן׃","wĕ⁠nişĕ̌maʻ֩ pi̇ţĕgá֨m ha⁠mė֤lekĕ ʼàşěֽr-yaʻàşêh֙ bĕ̇⁠kál-malĕkẇţ֔⁠wò ki֥̇y rabá֖̇h hi֑yʼ wĕ⁠kál-ha⁠ná̇şǐ֗ym yiţĕ̇n֤ẇ yĕqár֙ lĕ⁠baʻĕléy⁠he֔n lĕ⁠mi⁠gá̇d֖wòl wĕ⁠ʻad-qátáֽn׃"],[1,21,"וַ⁠יִּיטַב֙ הַ⁠דָּבָ֔ר בְּ⁠עֵינֵ֥י הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠שָּׂרִ֑ים וַ⁠יַּ֥עַשׂ הַ⁠מֶּ֖לֶךְ כִּ⁠דְבַ֥ר מְמוּכָֽן׃","wa⁠yi̇ytab֙ ha⁠dá̇bá֔r bĕ̇⁠ʻéyné֥y ha⁠mė֖lekĕ wĕ⁠ha⁠şá̇̂ri֑ym wa⁠yȧ֥ʻaş̂ ha⁠mė֖lekĕ ki̇⁠dĕba֥r mĕmẇkáֽn׃"],[1,22,"וַ⁠יִּשְׁלַ֤ח סְפָרִים֙ אֶל־כָּל־מְדִינ֣וֹת הַ⁠מֶּ֔לֶךְ אֶל־מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠אֶל־עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשׁוֹנ֑⁠וֹ לִ⁠הְי֤וֹת כָּל־אִישׁ֙ שֹׂרֵ֣ר בְּ⁠בֵית֔⁠וֹ וּ⁠מְדַבֵּ֖ר כִּ⁠לְשׁ֥וֹן עַמּֽ⁠וֹ׃פ","wa⁠yi̇şĕ̌la֤ẖ sĕpáriym֙ ʼel-ká̇l-mĕdiyn֣wòţ ha⁠mė֔lekĕ ʼel-mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʼel-ʻa֥m wá⁠ʻá֖m ki̇⁠lĕş̌wòn֑⁠wò li⁠hĕy֤wòţ ká̇l-ʼiyş̌֙ şò̂ré֣r bĕ̇⁠béyţ֔⁠wò ẇ⁠mĕdabé֖̇r ki̇⁠lĕş֥̌wòn ʻaṁֽ⁠wò׃p"],[2,1,"אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה כְּ⁠שֹׁ֕ךְ חֲמַ֖ת הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ זָכַ֤ר אֶת־וַשְׁתִּי֙ וְ⁠אֵ֣ת אֲשֶׁר־עָשָׂ֔תָה וְ⁠אֵ֥ת אֲשֶׁר־נִגְזַ֖ר עָלֶֽי⁠הָ׃","ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh kĕ̇⁠şò̌֕kĕ ẖàma֖ţ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ záka֤r ʼeţ-waşĕ̌ţi̇y֙ wĕ⁠ʼé֣ţ ʼàşěr-ʻáşá̂֔ţáh wĕ⁠ʼé֥ţ ʼàşěr-nigĕza֖r ʻáleֽy⁠há׃"],[2,2,"וַ⁠יֹּאמְר֥וּ נַעֲרֵֽי־הַ⁠מֶּ֖לֶךְ מְשָׁרְתָ֑י⁠ו יְבַקְשׁ֥וּ לַ⁠מֶּ֛לֶךְ נְעָר֥וֹת בְּתוּל֖וֹת טוֹב֥וֹת מַרְאֶֽה׃","wa⁠yò̇ʼmĕr֥ẇ naʻàréֽy-ha⁠mė֖lekĕ mĕşá̌rĕţá֑y⁠w yĕbaqĕş֥̌ẇ la⁠mė֛lekĕ nĕʻár֥wòţ bĕ̇ţẇl֖wòţ twòb֥wòţ marĕʼeֽh׃"],[2,3,"וְ⁠יַפְקֵ֨ד הַ⁠מֶּ֣לֶךְ פְּקִידִים֮ בְּ⁠כָל־מְדִינ֣וֹת מַלְכוּת⁠וֹ֒ וְ⁠יִקְבְּצ֣וּ אֶת־כָּל־נַעֲרָֽה־בְ֠תוּלָה טוֹבַ֨ת מַרְאֶ֜ה אֶל־שׁוּשַׁ֤ן הַ⁠בִּירָה֙ אֶל־בֵּ֣ית הַ⁠נָּשִׁ֔ים אֶל־יַ֥ד הֵגֶ֛א סְרִ֥יס הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠נָּשִׁ֑ים וְ⁠נָת֖וֹן תַּמְרוּקֵי⁠הֶֽן׃","wĕ⁠yapĕqé֨d ha⁠mė֣lekĕ pĕ̇qiydiym֮ bĕ̇⁠kál-mĕdiyn֣wòţ malĕkẇţ⁠wò֒ wĕ⁠yiqĕbĕ̇ẕ֣ẇ ʼeţ-ká̇l-naʻàráֽh-bĕ֠ţẇláh twòba֨ţ marĕʼe֜h ʼel-ş̌ẇşǎ֤n ha⁠bi̇yráh֙ ʼel-bé֣̇yţ ha⁠ná̇şǐ֔ym ʼel-ya֥d hége֛ʼ sĕri֥ys ha⁠mė֖lekĕ şò̌mé֣r ha⁠ná̇şǐ֑ym wĕ⁠náţ֖wòn ţȧmĕrẇqéy⁠heֽn׃"],[2,4,"וְ⁠הַֽ⁠נַּעֲרָ֗ה אֲשֶׁ֤ר תִּיטַב֙ בְּ⁠עֵינֵ֣י הַ⁠מֶּ֔לֶךְ תִּמְלֹ֖ךְ תַּ֣חַת וַשְׁתִּ֑י וַ⁠יִּיטַ֧ב הַ⁠דָּבָ֛ר בְּ⁠עֵינֵ֥י הַ⁠מֶּ֖לֶךְ וַ⁠יַּ֥עַשׂ כֵּֽן׃ס","wĕ⁠haֽ⁠nȧʻàrá֗h ʼàşě֤r ţi̇ytab֙ bĕ̇⁠ʻéyné֣y ha⁠mė֔lekĕ ţi̇mĕlò֖kĕ ţȧ֣ẖaţ waşĕ̌ţi֑̇y wa⁠yi̇yta֧b ha⁠dá̇bá֛r bĕ̇⁠ʻéyné֥y ha⁠mė֖lekĕ wa⁠yȧ֥ʻaş̂ kéֽ̇n׃s"],[2,5,"אִ֣ישׁ יְהוּדִ֔י הָיָ֖ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֑ה וּ⁠שְׁמ֣⁠וֹ מָרְדֳּכַ֗י בֶּ֣ן יָאִ֧יר בֶּן־שִׁמְעִ֛י בֶּן־קִ֖ישׁ אִ֥ישׁ יְמִינִֽי׃","ʼi֣yş̌ yĕhẇdi֔y háyá֖h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֑h ẇ⁠şĕ̌m֣⁠wò márĕdȯka֗y bė֣n yáʼi֧yr bėn-şǐmĕʻi֛y bėn-qi֖yş̌ ʼi֥yş̌ yĕmiyniֽy׃"],[2,6,"אֲשֶׁ֤ר הָגְלָה֙ מִ⁠יר֣וּשָׁלַ֔יִם עִם־הַ⁠גֹּלָה֙ אֲשֶׁ֣ר הָגְלְתָ֔ה עִ֖ם יְכָנְיָ֣ה מֶֽלֶךְ־יְהוּדָ֑ה אֲשֶׁ֣ר הֶגְלָ֔ה נְבוּכַדְנֶאצַּ֖ר מֶ֥לֶךְ בָּבֶֽל׃","ʼàşě֤r hágĕláh֙ mi⁠yr֣ẇşá̌la֔yim ʻim-ha⁠gò̇láh֙ ʼàşě֣r hágĕlĕţá֔h ʻi֖m yĕkánĕyá֣h meֽlekĕ-yĕhẇdá֑h ʼàşě֣r hegĕlá֔h nĕbẇkadĕneʼẕȧ֖r me֥lekĕ bá̇beֽl׃"],[2,7,"וַ⁠יְהִ֨י אֹמֵ֜ן אֶת־הֲדַסָּ֗ה הִ֤יא אֶסְתֵּר֙ בַּת־דֹּד֔⁠וֹ כִּ֛י אֵ֥ין לָ֖⁠הּ אָ֣ב וָ⁠אֵ֑ם וְ⁠הַ⁠נַּעֲרָ֤ה יְפַת־תֹּ֨אַר֙ וְ⁠טוֹבַ֣ת מַרְאֶ֔ה וּ⁠בְ⁠מ֤וֹת אָבִ֨י⁠הָ֙ וְ⁠אִמָּ֔⁠הּ לְקָחָ֧⁠הּ מָרְדֳּכַ֛י ל֖⁠וֹ לְ⁠בַֽת׃","wa⁠yĕhi֨y ʼòmé֜n ʼeţ-hàdasá̇֗h hi֤yʼ ʼesĕţé̇r֙ bȧţ-dò̇d֔⁠wò ki֛̇y ʼé֥yn lá֖⁠ḣ ʼá֣b wá⁠ʼé֑m wĕ⁠ha⁠nȧʻàrá֤h yĕpaţ-ţò̇֨ʼar֙ wĕ⁠twòba֣ţ marĕʼe֔h ẇ⁠bĕ⁠m֤wòţ ʼábi֨y⁠há֙ wĕ⁠ʼimá̇֔⁠ḣ lĕqáẖá֧⁠ḣ márĕdȯka֛y l֖⁠wò lĕ⁠baֽţ׃"],[2,8,"וַ⁠יְהִ֗י בְּ⁠הִשָּׁמַ֤ע דְּבַר־הַ⁠מֶּ֨לֶךְ֙ וְ⁠דָת֔⁠וֹ וּֽ⁠בְ⁠הִקָּבֵ֞ץ נְעָר֥וֹת רַבּ֛וֹת אֶל־שׁוּשַׁ֥ן הַ⁠בִּירָ֖ה אֶל־יַ֣ד הֵגָ֑י וַ⁠תִּלָּקַ֤ח אֶסְתֵּר֙ אֶל־בֵּ֣ית הַ⁠מֶּ֔לֶךְ אֶל־יַ֥ד הֵגַ֖י שֹׁמֵ֥ר הַ⁠נָּשִֽׁים׃","wa⁠yĕhi֗y bĕ̇⁠hişá̇̌ma֤ʻ dĕ̇bar-ha⁠mė֨lekĕ֙ wĕ⁠dáţ֔⁠wò ẇֽ⁠bĕ⁠hiqá̇bé֞ẕ nĕʻár֥wòţ raḃ֛wòţ ʼel-ş̌ẇşǎ֥n ha⁠bi̇yrá֖h ʼel-ya֣d hégá֑y wa⁠ţi̇lá̇qa֤ẖ ʼesĕţé̇r֙ ʼel-bé֣̇yţ ha⁠mė֔lekĕ ʼel-ya֥d héga֖y şò̌mé֥r ha⁠ná̇şǐֽym׃"],[2,9,"וַ⁠תִּיטַ֨ב הַ⁠נַּעֲרָ֣ה בְ⁠עֵינָי⁠ו֮ וַ⁠תִּשָּׂ֣א חֶ֣סֶד לְ⁠פָנָי⁠ו֒ וַ֠⁠יְבַהֵל אֶת־תַּמְרוּקֶ֤י⁠הָ וְ⁠אֶת־מָנוֹתֶ֨⁠הָ֙ לָ⁠תֵ֣ת לָ֔⁠הּ וְ⁠אֵת֙ שֶׁ֣בַע הַ⁠נְּעָר֔וֹת הָ⁠רְאֻי֥וֹת לָֽ⁠תֶת־לָ֖⁠הּ מִ⁠בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יְשַׁנֶּ֧⁠הָ וְ⁠אֶת־נַעֲרוֹתֶ֛י⁠הָ לְ⁠ט֖וֹב בֵּ֥ית הַ⁠נָּשִֽׁים׃","wa⁠ţi̇yta֨b ha⁠nȧʻàrá֣h bĕ⁠ʻéynáy⁠w֮ wa⁠ţi̇şá֣̇̂ʼ ẖe֣sed lĕ⁠pánáy⁠w֒ wa֠⁠yĕbahél ʼeţ-ţȧmĕrẇqe֤y⁠há wĕ⁠ʼeţ-mánwòţe֨⁠há֙ lá⁠ţé֣ţ lá֔⁠ḣ wĕ⁠ʼéţ֙ şě֣baʻ ha⁠nĕ̇ʻár֔wòţ há⁠rĕʼuy֥wòţ láֽ⁠ţeţ-lá֖⁠ḣ mi⁠bé֣̇yţ ha⁠mė֑lekĕ wa⁠yĕşǎnė֧⁠há wĕ⁠ʼeţ-naʻàrwòţe֛y⁠há lĕ⁠t֖wòb bé֥̇yţ ha⁠ná̇şǐֽym׃"],[2,10,"לֹא־הִגִּ֣ידָה אֶסְתֵּ֔ר אֶת־עַמָּ֖⁠הּ וְ⁠אֶת־מֽוֹלַדְתָּ֑⁠הּ כִּ֧י מָרְדֳּכַ֛י צִוָּ֥ה עָלֶ֖י⁠הָ אֲשֶׁ֥ר לֹא־תַגִּֽיד׃","lòʼ-higi֣̇ydáh ʼesĕţé̇֔r ʼeţ-ʻamá֖̇⁠ḣ wĕ⁠ʼeţ-mֽwòladĕţá֑̇⁠ḣ ki֧̇y márĕdȯka֛y ẕiwá֥̇h ʻále֖y⁠há ʼàşě֥r lòʼ-ţagiֽ̇yd׃"],[2,11,"וּ⁠בְ⁠כָל־י֣וֹם וָ⁠י֔וֹם מָרְדֳּכַי֙ מִתְהַלֵּ֔ךְ לִ⁠פְנֵ֖י חֲצַ֣ר בֵּית־הַ⁠נָּשִׁ֑ים לָ⁠דַ֨עַת֙ אֶת־שְׁל֣וֹם אֶסְתֵּ֔ר וּ⁠מַה־יֵּעָשֶׂ֖ה בָּֽ⁠הּ׃","ẇ⁠bĕ⁠kál-y֣wòm wá⁠y֔wòm márĕdȯkay֙ miţĕhalé̇֔kĕ li⁠pĕné֖y ẖàẕa֣r bé̇yţ-ha⁠ná̇şǐ֑ym lá⁠da֨ʻaţ֙ ʼeţ-şĕ̌l֣wòm ʼesĕţé̇֔r ẇ⁠mah-yé̇ʻáşê֖h báֽ̇⁠ḣ׃"],[2,12,"וּ⁠בְ⁠הַגִּ֡יעַ תֹּר֩ נַעֲרָ֨ה וְ⁠נַעֲרָ֜ה לָ⁠ב֣וֹא ׀ אֶל־הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ מִ⁠קֵּץ֩ הֱי֨וֹת לָ֜⁠הּ כְּ⁠דָ֤ת הַ⁠נָּשִׁים֙ שְׁנֵ֣ים עָשָׂ֣ר חֹ֔דֶשׁ כִּ֛י כֵּ֥ן יִמְלְא֖וּ יְמֵ֣י מְרוּקֵי⁠הֶ֑ן שִׁשָּׁ֤ה חֳדָשִׁים֙ בְּ⁠שֶׁ֣מֶן הַ⁠מֹּ֔ר וְ⁠שִׁשָּׁ֤ה חֳדָשִׁים֙ בַּ⁠בְּשָׂמִ֔ים וּ⁠בְ⁠תַמְרוּקֵ֖י הַ⁠נָּשִֽׁים׃","ẇ⁠bĕ⁠hagi̇֡yʻa ţò̇r֩ naʻàrá֨h wĕ⁠naʻàrá֜h lá⁠b֣wòʼ ׀ ʼel-ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ mi⁠qé̇ẕ֩ hèy֨wòţ lá֜⁠ḣ kĕ̇⁠dá֤ţ ha⁠ná̇şǐym֙ şĕ̌né֣ym ʻáşá֣̂r ẖò֔deş̌ ki֛̇y ké֥̇n yimĕlĕʼ֖ẇ yĕmé֣y mĕrẇqéy⁠he֑n şǐşá֤̇̌h ẖodáşǐym֙ bĕ̇⁠şě֣men ha⁠mò̇֔r wĕ⁠şǐşá֤̇̌h ẖodáşǐym֙ bȧ⁠bĕ̇şá̂mi֔ym ẇ⁠bĕ⁠ţamĕrẇqé֖y ha⁠ná̇şǐֽym׃"],[2,13,"וּ⁠בָ⁠זֶ֕ה הַֽ⁠נַּעֲרָ֖ה בָּאָ֣ה אֶל־הַ⁠מֶּ֑לֶךְ אֵת֩ כָּל־אֲשֶׁ֨ר תֹּאמַ֜ר יִנָּ֤תֵֽן לָ⁠הּ֙ לָ⁠ב֣וֹא עִמָּ֔⁠הּ מִ⁠בֵּ֥ית הַ⁠נָּשִׁ֖ים עַד־בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","ẇ⁠bá⁠ze֕h haֽ⁠nȧʻàrá֖h bá̇ʼá֣h ʼel-ha⁠mė֑lekĕ ʼéţ֩ ká̇l-ʼàşě֨r ţò̇ʼma֜r yiná֤̇ţéֽn lá⁠ḣ֙ lá⁠b֣wòʼ ʻimá̇֔⁠ḣ mi⁠bé֥̇yţ ha⁠ná̇şǐ֖ym ʻad-bé֥̇yţ ha⁠mėֽlekĕ׃"],[2,14,"בָּ⁠עֶ֣רֶב ׀ הִ֣יא בָאָ֗ה וּ֠⁠בַ⁠בֹּקֶר הִ֣יא שָׁבָ֞ה אֶל־בֵּ֤ית הַ⁠נָּשִׁים֙ שֵׁנִ֔י אֶל־יַ֧ד שַֽׁעֲשְׁגַ֛ז סְרִ֥יס הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠פִּֽילַגְשִׁ֑ים לֹא־תָב֥וֹא עוֹד֙ אֶל־הַ⁠מֶּ֔לֶךְ כִּ֣י אִם־חָפֵ֥ץ בָּ֛⁠הּ הַ⁠מֶּ֖לֶךְ וְ⁠נִקְרְאָ֥ה בְ⁠שֵֽׁם׃","bá̇⁠ʻe֣reb ׀ hi֣yʼ báʼá֗h ẇ֠⁠ba⁠bò̇qer hi֣yʼ şá̌bá֞h ʼel-bé֤̇yţ ha⁠ná̇şǐym֙ şé̌ni֔y ʼel-ya֧d şǎֽʻàşĕ̌ga֛z sĕri֥ys ha⁠mė֖lekĕ şò̌mé֣r ha⁠piֽ̇ylagĕşǐ֑ym lòʼ-ţáb֥wòʼ ʻwòd֙ ʼel-ha⁠mė֔lekĕ ki֣̇y ʼim-ẖápé֥ẕ bá֛̇⁠ḣ ha⁠mė֖lekĕ wĕ⁠niqĕrĕʼá֥h bĕ⁠şéֽ̌m׃"],[2,15,"וּ⁠בְ⁠הַגִּ֣יעַ תֹּר־אֶסְתֵּ֣ר בַּת־אֲבִיחַ֣יִל דֹּ֣ד מָרְדֳּכַ֡י אֲשֶׁר֩ לָקַֽח־ל֨⁠וֹ לְ⁠בַ֜ת לָ⁠ב֣וֹא אֶל־הַ⁠מֶּ֗לֶךְ לֹ֤א בִקְשָׁה֙ דָּבָ֔ר כִּ֠י אִ֣ם אֶת־אֲשֶׁ֥ר יֹאמַ֛ר הֵגַ֥י סְרִיס־הַ⁠מֶּ֖לֶךְ שֹׁמֵ֣ר הַ⁠נָּשִׁ֑ים וַ⁠תְּהִ֤י אֶסְתֵּר֙ נֹשֵׂ֣את חֵ֔ן בְּ⁠עֵינֵ֖י כָּל־רֹאֶֽי⁠הָ׃","ẇ⁠bĕ⁠hagi֣̇yʻa ţò̇r-ʼesĕţé֣̇r bȧţ-ʼàbiyẖa֣yil dò֣̇d márĕdȯka֡y ʼàşěr֩ láqaֽẖ-l֨⁠wò lĕ⁠ba֜ţ lá⁠b֣wòʼ ʼel-ha⁠mė֗lekĕ lò֤ʼ biqĕşá̌h֙ dá̇bá֔r ki̇֠y ʼi֣m ʼeţ-ʼàşě֥r yòʼma֛r héga֥y sĕriys-ha⁠mė֖lekĕ şò̌mé֣r ha⁠ná̇şǐ֑ym wa⁠ţĕ̇hi֤y ʼesĕţé̇r֙ nòşé֣̂ʼţ ẖé֔n bĕ̇⁠ʻéyné֖y ká̇l-ròʼeֽy⁠há׃"],[2,16,"וַ⁠תִּלָּקַ֨ח אֶסְתֵּ֜ר אֶל־הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ אֶל־בֵּ֣ית מַלְכוּת֔⁠וֹ בַּ⁠חֹ֥דֶשׁ הָ⁠עֲשִׂירִ֖י הוּא־חֹ֣דֶשׁ טֵבֵ֑ת בִּ⁠שְׁנַת־שֶׁ֖בַע לְ⁠מַלְכוּתֽ⁠וֹ׃","wa⁠ţi̇lá̇qa֨ẖ ʼesĕţé̇֜r ʼel-ha⁠mė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ ʼel-bé֣̇yţ malĕkẇţ֔⁠wò bȧ⁠ẖò֥deş̌ há⁠ʻàşîyri֖y hẇʼ-ẖò֣deş̌ tébé֑ţ bi̇⁠şĕ̌naţ-şě֖baʻ lĕ⁠malĕkẇţֽ⁠wò׃"],[2,17,"וַ⁠יֶּאֱהַ֨ב הַ⁠מֶּ֤לֶךְ אֶת־אֶסְתֵּר֙ מִ⁠כָּל־הַ⁠נָּשִׁ֔ים וַ⁠תִּשָּׂא־חֵ֥ן וָ⁠חֶ֛סֶד לְ⁠פָנָ֖י⁠ו מִ⁠כָּל־הַ⁠בְּתוּלֹ֑ת וַ⁠יָּ֤שֶׂם כֶּֽתֶר־מַלְכוּת֙ בְּ⁠רֹאשָׁ֔⁠הּ וַ⁠יַּמְלִיכֶ֖⁠הָ תַּ֥חַת וַשְׁתִּֽי׃","wa⁠yėʼèha֨b ha⁠mė֤lekĕ ʼeţ-ʼesĕţé̇r֙ mi⁠ká̇l-ha⁠ná̇şǐ֔ym wa⁠ţi̇şá̇̂ʼ-ẖé֥n wá⁠ẖe֛sed lĕ⁠páná֖y⁠w mi⁠ká̇l-ha⁠bĕ̇ţẇlò֑ţ wa⁠yá֤̇şêm kėֽţer-malĕkẇţ֙ bĕ̇⁠ròʼşá̌֔⁠ḣ wa⁠yȧmĕliyke֖⁠há ţȧ֥ẖaţ waşĕ̌ţiֽ̇y׃"],[2,18,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֜לֶךְ מִשְׁתֶּ֣ה גָד֗וֹל לְ⁠כָל־שָׂרָי⁠ו֙ וַ⁠עֲבָדָ֔י⁠ו אֵ֖ת מִשְׁתֵּ֣ה אֶסְתֵּ֑ר וַ⁠הֲנָחָ֤ה לַ⁠מְּדִינוֹת֙ עָשָׂ֔ה וַ⁠יִּתֵּ֥ן מַשְׂאֵ֖ת כְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֜lekĕ mişĕ̌ţė֣h gád֗wòl lĕ⁠kál-şá̂ráy⁠w֙ wa⁠ʻàbádá֔y⁠w ʼé֖ţ mişĕ̌ţé֣̇h ʼesĕţé֑̇r wa⁠hànáẖá֤h la⁠mĕ̇diynwòţ֙ ʻáşá̂֔h wa⁠yi̇ţé֥̇n maşĕ̂ʼé֖ţ kĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[2,19,"וּ⁠בְ⁠הִקָּבֵ֥ץ בְּתוּל֖וֹת שֵׁנִ֑ית וּ⁠מָרְדֳּכַ֖י יֹשֵׁ֥ב בְּ⁠שַֽׁעַר־הַ⁠מֶּֽלֶךְ׃","ẇ⁠bĕ⁠hiqá̇bé֥ẕ bĕ̇ţẇl֖wòţ şé̌ni֑yţ ẇ⁠márĕdȯka֖y yòşé֥̌b bĕ̇⁠şǎֽʻar-ha⁠mėֽlekĕ׃"],[2,20,"אֵ֣ין אֶסְתֵּ֗ר מַגֶּ֤דֶת מֽוֹלַדְתָּ⁠הּ֙ וְ⁠אֶת־עַמָּ֔⁠הּ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה עָלֶ֖י⁠הָ מָרְדֳּכָ֑י וְ⁠אֶת־מַאֲמַ֤ר מָרְדֳּכַי֙ אֶסְתֵּ֣ר עֹשָׂ֔ה כַּ⁠אֲשֶׁ֛ר הָיְתָ֥ה בְ⁠אָמְנָ֖ה אִתּֽ⁠וֹ׃ס","ʼé֣yn ʼesĕţé̇֗r magė֤deţ mֽwòladĕţá̇⁠ḣ֙ wĕ⁠ʼeţ-ʻamá̇֔⁠ḣ kȧ⁠ʼàşě֛r ẕiwá֥̇h ʻále֖y⁠há márĕdȯká֑y wĕ⁠ʼeţ-maʼàma֤r márĕdȯkay֙ ʼesĕţé֣̇r ʻòşá̂֔h kȧ⁠ʼàşě֛r háyĕţá֥h bĕ⁠ʼámĕná֖h ʼiţֽ̇⁠wò׃s"],[2,21,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם וּ⁠מָרְדֳּכַ֖י יֹשֵׁ֣ב בְּ⁠שַֽׁעַר־הַ⁠מֶּ֑לֶךְ קָצַף֩ בִּגְתָ֨ן וָ⁠תֶ֜רֶשׁ שְׁנֵֽי־סָרִיסֵ֤י הַ⁠מֶּ֨לֶךְ֙ מִ⁠שֹּׁמְרֵ֣י הַ⁠סַּ֔ף וַ⁠יְבַקְשׁוּ֙ לִ⁠שְׁלֹ֣חַ יָ֔ד בַּ⁠מֶּ֖לֶךְ אֲחַשְׁוֵֽרֹשׁ׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ẇ⁠márĕdȯka֖y yòşé֣̌b bĕ̇⁠şǎֽʻar-ha⁠mė֑lekĕ qáẕap֩ bi̇gĕţá֨n wá⁠ţe֜reş̌ şĕ̌néֽy-sáriysé֤y ha⁠mė֨lekĕ֙ mi⁠şò̇̌mĕré֣y ha⁠sȧ֔p wa⁠yĕbaqĕş̌ẇ֙ li⁠şĕ̌lò֣ẖa yá֔d bȧ⁠mė֖lekĕ ʼàẖaşĕ̌wéֽròş̌׃"],[2,22,"וַ⁠יִּוָּדַ֤ע הַ⁠דָּבָר֙ לְ⁠מָרְדֳּכַ֔י וַ⁠יַּגֵּ֖ד לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה וַ⁠תֹּ֧אמֶר אֶסְתֵּ֛ר לַ⁠מֶּ֖לֶךְ בְּ⁠שֵׁ֥ם מָרְדֳּכָֽי׃","wa⁠yi̇wá̇da֤ʻ ha⁠dá̇bár֙ lĕ⁠márĕdȯka֔y wa⁠yȧgé֖̇d lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h wa⁠ţò֧̇ʼmer ʼesĕţé֛̇r la⁠mė֖lekĕ bĕ̇⁠şé֥̌m márĕdȯkáֽy׃"],[2,23,"וַ⁠יְבֻקַּ֤שׁ הַ⁠דָּבָר֙ וַ⁠יִּמָּצֵ֔א וַ⁠יִּתָּל֥וּ שְׁנֵי⁠הֶ֖ם עַל־עֵ֑ץ וַ⁠יִּכָּתֵ֗ב בְּ⁠סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃פ","wa⁠yĕbuqȧ֤ş̌ ha⁠dá̇bár֙ wa⁠yi̇má̇ẕé֔ʼ wa⁠yi̇ţá̇l֥ẇ şĕ̌néy⁠he֖m ʻal-ʻé֑ẕ wa⁠yi̇ká̇ţé֗b bĕ̇⁠sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym li⁠pĕné֥y ha⁠mėֽlekĕ׃p"],[3,1,"אַחַ֣ר ׀ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה גִּדַּל֩ הַ⁠מֶּ֨לֶךְ אֲחַשְׁוֵר֜וֹשׁ אֶת־הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָ⁠אֲגָגִ֖י וַֽ⁠יְנַשְּׂאֵ֑⁠הוּ וַ⁠יָּ֨שֶׂם֙ אֶת־כִּסְא֔⁠וֹ מֵ⁠עַ֕ל כָּל־הַ⁠שָּׂרִ֖ים אֲשֶׁ֥ר אִתּֽ⁠וֹ׃","ʼaẖa֣r ׀ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh gi̇dȧl֩ ha⁠mė֨lekĕ ʼàẖaşĕ̌wér֜wòş̌ ʼeţ-hámá֧n bėֽn-hamĕ̇dá֛ţáʼ há⁠ʼàgági֖y waֽ⁠yĕnaşĕ̇̂ʼé֑⁠hẇ wa⁠yá̇֨şêm֙ ʼeţ-ki̇sĕʼ֔⁠wò mé⁠ʻa֕l ká̇l-ha⁠şá̇̂ri֖ym ʼàşě֥r ʼiţֽ̇⁠wò׃"],[3,2,"וְ⁠כָל־עַבְדֵ֨י הַ⁠מֶּ֜לֶךְ אֲשֶׁר־בְּ⁠שַׁ֣עַר הַ⁠מֶּ֗לֶךְ כֹּרְעִ֤ים וּ⁠מִֽשְׁתַּחֲוִים֙ לְ⁠הָמָ֔ן כִּי־כֵ֖ן צִוָּה־ל֣⁠וֹ הַ⁠מֶּ֑לֶךְ וּ⁠מָ֨רְדֳּכַ֔י לֹ֥א יִכְרַ֖ע וְ⁠לֹ֥א יִֽשְׁתַּחֲוֶֽה׃","wĕ⁠kál-ʻabĕdé֨y ha⁠mė֜lekĕ ʼàşěr-bĕ̇⁠şǎ֣ʻar ha⁠mė֗lekĕ kò̇rĕʻi֤ym ẇ⁠miֽşĕ̌ţȧẖàwiym֙ lĕ⁠hámá֔n ki̇y-ké֖n ẕiwá̇h-l֣⁠wò ha⁠mė֑lekĕ ẇ⁠má֨rĕdȯka֔y lò֥ʼ yikĕra֖ʻ wĕ⁠lò֥ʼ yiֽşĕ̌ţȧẖàweֽh׃"],[3,3,"וַ⁠יֹּ֨אמְר֜וּ עַבְדֵ֥י הַ⁠מֶּ֛לֶךְ אֲשֶׁר־בְּ⁠שַׁ֥עַר הַ⁠מֶּ֖לֶךְ לְ⁠מָרְדֳּכָ֑י מַדּ֨וּעַ֙ אַתָּ֣ה עוֹבֵ֔ר אֵ֖ת מִצְוַ֥ת הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmĕr֜ẇ ʻabĕdé֥y ha⁠mė֛lekĕ ʼàşěr-bĕ̇⁠şǎ֥ʻar ha⁠mė֖lekĕ lĕ⁠márĕdȯká֑y maḋ֨ẇʻa֙ ʼaţá֣̇h ʻwòbé֔r ʼé֖ţ miẕĕwa֥ţ ha⁠mėֽlekĕ׃"],[3,4,"וַ⁠יְהִ֗י ב⁠אמר⁠ם אֵלָי⁠ו֙ י֣וֹם וָ⁠י֔וֹם וְ⁠לֹ֥א שָׁמַ֖ע אֲלֵי⁠הֶ֑ם וַ⁠יַּגִּ֣ידוּ לְ⁠הָמָ֗ן לִ⁠רְאוֹת֙ הֲ⁠יַֽעַמְדוּ֙ דִּבְרֵ֣י מָרְדֳּכַ֔י כִּֽי־הִגִּ֥יד לָ⁠הֶ֖ם אֲשֶׁר־ה֥וּא יְהוּדִֽי׃","wa⁠yĕhi֗y b⁠ʼmr⁠m ʼéláy⁠w֙ y֣wòm wá⁠y֔wòm wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼàléy⁠he֑m wa⁠yȧgi֣̇ydẇ lĕ⁠hámá֗n li⁠rĕʼwòţ֙ hà⁠yaֽʻamĕdẇ֙ di̇bĕré֣y márĕdȯka֔y kiֽ̇y-higi֥̇yd lá⁠he֖m ʼàşěr-h֥ẇʼ yĕhẇdiֽy׃"],[3,5,"וַ⁠יַּ֣רְא הָמָ֔ן כִּי־אֵ֣ין מָרְדֳּכַ֔י כֹּרֵ֥עַ וּ⁠מִֽשְׁתַּחֲוֶ֖ה ל֑⁠וֹ וַ⁠יִּמָּלֵ֥א הָמָ֖ן חֵמָֽה׃","wa⁠yȧ֣rĕʼ hámá֔n ki̇y-ʼé֣yn márĕdȯka֔y kò̇ré֥ʻa ẇ⁠miֽşĕ̌ţȧẖàwe֖h l֑⁠wò wa⁠yi̇má̇lé֥ʼ hámá֖n ẖémáֽh׃"],[3,6,"וַ⁠יִּ֣בֶז בְּ⁠עֵינָ֗י⁠ו לִ⁠שְׁלֹ֤ח יָד֙ בְּ⁠מָרְדֳּכַ֣י לְ⁠בַדּ֔⁠וֹ כִּֽי־הִגִּ֥ידוּ ל֖⁠וֹ אֶת־עַ֣ם מָרְדֳּכָ֑י וַ⁠יְבַקֵּ֣שׁ הָמָ֗ן לְ⁠הַשְׁמִ֧יד אֶת־כָּל־הַ⁠יְּהוּדִ֛ים אֲשֶׁ֛ר בְּ⁠כָל־מַלְכ֥וּת אֲחַשְׁוֵר֖וֹשׁ עַ֥ם מָרְדֳּכָֽי׃","wa⁠yi֣̇bez bĕ̇⁠ʻéyná֗y⁠w li⁠şĕ̌lò֤ẖ yád֙ bĕ̇⁠márĕdȯka֣y lĕ⁠baḋ֔⁠wò kiֽ̇y-higi֥̇ydẇ l֖⁠wò ʼeţ-ʻa֣m márĕdȯká֑y wa⁠yĕbaqé֣̇ş̌ hámá֗n lĕ⁠haşĕ̌mi֧yd ʼeţ-ká̇l-ha⁠yĕ̇hẇdi֛ym ʼàşě֛r bĕ̇⁠kál-malĕk֥ẇţ ʼàẖaşĕ̌wér֖wòş̌ ʻa֥m márĕdȯkáֽy׃"],[3,7,"בַּ⁠חֹ֤דֶשׁ הָ⁠רִאשׁוֹן֙ הוּא־חֹ֣דֶשׁ נִיסָ֔ן בִּ⁠שְׁנַת֙ שְׁתֵּ֣ים עֶשְׂרֵ֔ה לַ⁠מֶּ֖לֶךְ אֲחַשְׁוֵר֑וֹשׁ הִפִּ֣יל פּוּר֩ ה֨וּא הַ⁠גּוֹרָ֜ל לִ⁠פְנֵ֣י הָמָ֗ן מִ⁠יּ֧וֹם ׀ לְ⁠י֛וֹם וּ⁠מֵ⁠חֹ֛דֶשׁ לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃ס","bȧ⁠ẖò֤deş̌ há⁠riʼş̌wòn֙ hẇʼ-ẖò֣deş̌ niysá֔n bi̇⁠şĕ̌naţ֙ şĕ̌ţé֣̇ym ʻeşĕ̂ré֔h la⁠mė֖lekĕ ʼàẖaşĕ̌wér֑wòş̌ hipi֣̇yl ṗẇr֩ h֨ẇʼ ha⁠ġwòrá֜l li⁠pĕné֣y hámá֗n mi⁠ẏ֧wòm ׀ lĕ⁠y֛wòm ẇ⁠mé⁠ẖò֛deş̌ lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃s"],[3,8,"וַ⁠יֹּ֤אמֶר הָמָן֙ לַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ יֶשְׁנ֣⁠וֹ עַם־אֶחָ֗ד מְפֻזָּ֤ר וּ⁠מְפֹרָד֙ בֵּ֣ין הָֽ⁠עַמִּ֔ים בְּ⁠כֹ֖ל מְדִינ֣וֹת מַלְכוּתֶ֑⁠ךָ וְ⁠דָתֵי⁠הֶ֞ם שֹׁנ֣וֹת מִ⁠כָּל־עָ֗ם וְ⁠אֶת־דָּתֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֵינָ֣⁠ם עֹשִׂ֔ים וְ⁠לַ⁠מֶּ֥לֶךְ אֵין־שֹׁוֶ֖ה לְ⁠הַנִּיחָֽ⁠ם׃","wa⁠yò֤̇ʼmer hámán֙ la⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ yeşĕ̌n֣⁠wò ʻam-ʼeẖá֗d mĕpuzá֤̇r ẇ⁠mĕpòrád֙ bé֣̇yn háֽ⁠ʻami̇֔ym bĕ̇⁠kò֖l mĕdiyn֣wòţ malĕkẇţe֑⁠ká wĕ⁠dáţéy⁠he֞m şò̌n֣wòţ mi⁠ká̇l-ʻá֗m wĕ⁠ʼeţ-dá̇ţé֤y ha⁠mė֨lekĕ֙ ʼéyná֣⁠m ʻòşî֔ym wĕ⁠la⁠mė֥lekĕ ʼéyn-şò̌we֖h lĕ⁠hani̇yẖáֽ⁠m׃"],[3,9,"אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב יִכָּתֵ֖ב לְ⁠אַבְּדָ֑⁠ם וַ⁠עֲשֶׂ֨רֶת אֲלָפִ֜ים כִּכַּר־כֶּ֗סֶף אֶשְׁקוֹל֙ עַל־יְדֵי֙ עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה לְ⁠הָבִ֖יא אֶל־גִּנְזֵ֥י הַ⁠מֶּֽלֶךְ׃","ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb yiká̇ţé֖b lĕ⁠ʼabĕ̇dá֑⁠m wa⁠ʻàşê֨reţ ʼàlápi֜ym ki̇kȧr-kė֗sep ʼeşĕ̌qwòl֙ ʻal-yĕdéy֙ ʻòşé֣̂y ha⁠mĕ̇láʼká֔h lĕ⁠hábi֖yʼ ʼel-gi̇nĕzé֥y ha⁠mėֽlekĕ׃"],[3,10,"וַ⁠יָּ֧סַר הַ⁠מֶּ֛לֶךְ אֶת־טַבַּעְתּ֖⁠וֹ מֵ⁠עַ֣ל יָד֑⁠וֹ וַֽ⁠יִּתְּנָ֗⁠הּ לְ⁠הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָ⁠אֲגָגִ֖י צֹרֵ֥ר הַ⁠יְּהוּדִֽים׃","wa⁠yá֧̇sar ha⁠mė֛lekĕ ʼeţ-tabȧʻĕţ֖̇⁠wò mé⁠ʻa֣l yád֑⁠wò waֽ⁠yi̇ţĕ̇ná֗⁠ḣ lĕ⁠hámá֧n bėֽn-hamĕ̇dá֛ţáʼ há⁠ʼàgági֖y ẕòré֥r ha⁠yĕ̇hẇdiֽym׃"],[3,11,"וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ לְ⁠הָמָ֔ן הַ⁠כֶּ֖סֶף נָת֣וּן לָ֑⁠ךְ וְ⁠הָ⁠עָ֕ם לַ⁠עֲשׂ֥וֹת בּ֖⁠וֹ כַּ⁠טּ֥וֹב בְּ⁠עֵינֶֽי⁠ךָ׃","wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ lĕ⁠hámá֔n ha⁠kė֖sep náţ֣ẇn lá֑⁠kĕ wĕ⁠há⁠ʻá֕m la⁠ʻàş֥̂wòţ ḃ֖⁠wò kȧ⁠ṫ֥wòb bĕ̇⁠ʻéyneֽy⁠ká׃"],[3,12,"וַ⁠יִּקָּרְאוּ֩ סֹפְרֵ֨י הַ⁠מֶּ֜לֶךְ בַּ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֗וֹן בִּ⁠שְׁלוֹשָׁ֨ה עָשָׂ֣ר יוֹם֮ בּ⁠וֹ֒ וַ⁠יִּכָּתֵ֣ב כְּֽ⁠כָל־אֲשֶׁר־צִוָּ֣ה הָמָ֡ן אֶ֣ל אֲחַשְׁדַּרְפְּנֵֽי־הַ֠⁠מֶּלֶךְ וְֽ⁠אֶל־הַ⁠פַּח֞וֹת אֲשֶׁ֣ר ׀ עַל־מְדִינָ֣ה וּ⁠מְדִינָ֗ה וְ⁠אֶל־שָׂ֤רֵי עַם֙ וָ⁠עָ֔ם מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשׁוֹנ֑⁠וֹ בְּ⁠שֵׁ֨ם הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ נִכְתָּ֔ב וְ⁠נֶחְתָּ֖ם בְּ⁠טַבַּ֥עַת הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇qá̇rĕʼẇ֩ sòpĕré֨y ha⁠mė֜lekĕ bȧ⁠ẖò֣deş̌ há⁠riʼş̌֗wòn bi̇⁠şĕ̌lwòşá̌֨h ʻáşá֣̂r ywòm֮ ḃ⁠wò֒ wa⁠yi̇ká̇ţé֣b kĕֽ̇⁠kál-ʼàşěr-ẕiwá֣̇h hámá֡n ʼe֣l ʼàẖaşĕ̌dȧrĕpĕ̇néֽy-ha֠⁠mėlekĕ wĕֽ⁠ʼel-ha⁠pȧẖ֞wòţ ʼàşě֣r ׀ ʻal-mĕdiyná֣h ẇ⁠mĕdiyná֗h wĕ⁠ʼel-şá֤̂réy ʻam֙ wá⁠ʻá֔m mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʻa֥m wá⁠ʻá֖m ki̇⁠lĕş̌wòn֑⁠wò bĕ̇⁠şé̌֨m ha⁠mė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ nikĕţá̇֔b wĕ⁠neẖĕţá֖̇m bĕ̇⁠tabȧ֥ʻaţ ha⁠mėֽlekĕ׃"],[3,13,"וְ⁠נִשְׁל֨וֹחַ סְפָרִ֜ים בְּ⁠יַ֣ד הָ⁠רָצִים֮ אֶל־כָּל־מְדִינ֣וֹת הַ⁠מֶּלֶךְ֒ לְ⁠הַשְׁמִ֡יד לַ⁠הֲרֹ֣ג וּ⁠לְ⁠אַבֵּ֣ד אֶת־כָּל־הַ֠⁠יְּהוּדִים מִ⁠נַּ֨עַר וְ⁠עַד־זָקֵ֜ן טַ֤ף וְ⁠נָשִׁים֙ בְּ⁠י֣וֹם אֶחָ֔ד בִּ⁠שְׁלוֹשָׁ֥ה עָשָׂ֛ר לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֣דֶשׁ אֲדָ֑ר וּ⁠שְׁלָלָ֖⁠ם לָ⁠בֽוֹז׃","wĕ⁠nişĕ̌l֨wòẖa sĕpári֜ym bĕ̇⁠ya֣d há⁠ráẕiym֮ ʼel-ká̇l-mĕdiyn֣wòţ ha⁠mėlekĕ֒ lĕ⁠haşĕ̌mi֡yd la⁠hàrò֣g ẇ⁠lĕ⁠ʼabé֣̇d ʼeţ-ká̇l-ha֠⁠yĕ̇hẇdiym mi⁠nȧ֨ʻar wĕ⁠ʻad-záqé֜n ta֤p wĕ⁠náşǐym֙ bĕ̇⁠y֣wòm ʼeẖá֔d bi̇⁠şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֣deş̌ ʼàdá֑r ẇ⁠şĕ̌lálá֖⁠m lá⁠bֽwòz׃"],[3,14,"פַּתְשֶׁ֣גֶן הַ⁠כְּתָ֗ב לְ⁠הִנָּ֤תֵֽן דָּת֙ בְּ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֔ה גָּל֖וּי לְ⁠כָל־הָֽ⁠עַמִּ֑ים לִ⁠הְי֥וֹת עֲתִדִ֖ים לַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","pȧţĕşě֣gen ha⁠kĕ̇ţá֗b lĕ⁠hiná֤̇ţéֽn dá̇ţ֙ bĕ̇⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֔h gá̇l֖ẇy lĕ⁠kál-háֽ⁠ʻami֑̇ym li⁠hĕy֥wòţ ʻàţidi֖ym la⁠ẏ֥wòm ha⁠zėֽh׃"],[3,15,"הָֽ⁠רָצִ֞ים יָצְא֤וּ דְחוּפִים֙ בִּ⁠דְבַ֣ר הַ⁠מֶּ֔לֶךְ וְ⁠הַ⁠דָּ֥ת נִתְּנָ֖ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֑ה וְ⁠הַ⁠מֶּ֤לֶךְ וְ⁠הָמָן֙ יָשְׁב֣וּ לִ⁠שְׁתּ֔וֹת וְ⁠הָ⁠עִ֥יר שׁוּשָׁ֖ן נָבֽוֹכָה׃פ","hֽá⁠ráẕi֞ym yáẕĕʼ֤ẇ dĕẖẇpiym֙ bi̇⁠dĕba֣r ha⁠mė֔lekĕ wĕ⁠ha⁠dá֥̇ţ niţĕ̇ná֖h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֑h wĕ⁠ha⁠mė֤lekĕ wĕ⁠hámán֙ yáşĕ̌b֣ẇ li⁠şĕ̌ţ̇֔wòţ wĕ⁠há⁠ʻi֥yr ş̌ẇşá֖̌n nábֽwòkáh׃p"],[4,1,"וּ⁠מָרְדֳּכַ֗י יָדַע֙ אֶת־כָּל־אֲשֶׁ֣ר נַעֲשָׂ֔ה וַ⁠יִּקְרַ֤ע מָרְדֳּכַי֙ אֶת־בְּגָדָ֔י⁠ו וַ⁠יִּלְבַּ֥שׁ שַׂ֖ק וָ⁠אֵ֑פֶר וַ⁠יֵּצֵא֙ בְּ⁠ת֣וֹךְ הָ⁠עִ֔יר וַ⁠יִּזְעַ֛ק זְעָקָ֥ה גְדֹלָ֖ה וּ⁠מָרָֽה׃","ẇ⁠márĕdȯka֗y yádaʻ֙ ʼeţ-ká̇l-ʼàşě֣r naʻàşá̂֔h wa⁠yi̇qĕra֤ʻ márĕdȯkay֙ ʼeţ-bĕ̇gádá֔y⁠w wa⁠yi̇lĕbȧ֥ş̌ şâ֖q wá⁠ʼé֑per wa⁠yé̇ẕéʼ֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻi֔yr wa⁠yi̇zĕʻa֛q zĕʻáqá֥h gĕdòlá֖h ẇ⁠máráֽh׃"],[4,2,"וַ⁠יָּב֕וֹא עַ֖ד לִ⁠פְנֵ֣י שַֽׁעַר־הַ⁠מֶּ֑לֶךְ כִּ֣י אֵ֥ין לָ⁠ב֛וֹא אֶל־שַׁ֥עַר הַ⁠מֶּ֖לֶךְ בִּ⁠לְב֥וּשׁ שָֽׂק׃","wa⁠yá̇b֕wòʼ ʻa֖d li⁠pĕné֣y şǎֽʻar-ha⁠mė֑lekĕ ki֣̇y ʼé֥yn lá⁠b֛wòʼ ʼel-şǎ֥ʻar ha⁠mė֖lekĕ bi̇⁠lĕb֥ẇş̌ şáֽ̂q׃"],[4,3,"וּ⁠בְ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֗ה מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַ⁠מֶּ֤לֶךְ וְ⁠דָת⁠וֹ֙ מַגִּ֔יעַ אֵ֤בֶל גָּדוֹל֙ לַ⁠יְּהוּדִ֔ים וְ⁠צ֥וֹם וּ⁠בְכִ֖י וּ⁠מִסְפֵּ֑ד שַׂ֣ק וָ⁠אֵ֔פֶר יֻצַּ֖ע לָֽ⁠רַבִּֽים׃","ẇ⁠bĕ⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֗h mĕqwòm֙ ʼàşě֨r dĕ̇bar-ha⁠mė֤lekĕ wĕ⁠dáţ⁠wò֙ magi̇֔yʻa ʼé֤bel gá̇dwòl֙ la⁠yĕ̇hẇdi֔ym wĕ⁠ẕ֥wòm ẇ⁠bĕki֖y ẇ⁠misĕpé֑̇d şâ֣q wá⁠ʼé֔per yuẕȧ֖ʻ láֽ⁠rabiֽ̇ym׃"],[4,4,"ותבואינה נַעֲר֨וֹת אֶסְתֵּ֤ר וְ⁠סָרִיסֶ֨י⁠הָ֙ וַ⁠יַּגִּ֣ידוּ לָ֔⁠הּ וַ⁠תִּתְחַלְחַ֥ל הַ⁠מַּלְכָּ֖ה מְאֹ֑ד וַ⁠תִּשְׁלַ֨ח בְּגָדִ֜ים לְ⁠הַלְבִּ֣ישׁ אֶֽת־מָרְדֳּכַ֗י וּ⁠לְ⁠הָסִ֥יר שַׂקּ֛⁠וֹ מֵ⁠עָלָ֖י⁠ו וְ⁠לֹ֥א קִבֵּֽל׃","wţbwʼynh naʻàr֨wòţ ʼesĕţé֤̇r wĕ⁠sáriyse֨y⁠há֙ wa⁠yȧgi֣̇ydẇ lá֔⁠ḣ wa⁠ţi̇ţĕẖalĕẖa֥l ha⁠mȧlĕká֖̇h mĕʼò֑d wa⁠ţi̇şĕ̌la֨ẖ bĕ̇gádi֜ym lĕ⁠halĕbi֣̇yş̌ ʼeֽţ-márĕdȯka֗y ẇ⁠lĕ⁠hási֥yr şâq֛̇⁠wò mé⁠ʻálá֖y⁠w wĕ⁠lò֥ʼ qibéֽ̇l׃"],[4,5,"וַ⁠תִּקְרָא֩ אֶסְתֵּ֨ר לַ⁠הֲתָ֜ךְ מִ⁠סָּרִיסֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר הֶעֱמִ֣יד לְ⁠פָנֶ֔י⁠הָ וַ⁠תְּצַוֵּ֖⁠הוּ עַֽל־מָרְדֳּכָ֑י לָ⁠דַ֥עַת מַה־זֶּ֖ה וְ⁠עַל־מַה־זֶּֽה׃","wa⁠ţi̇qĕráʼ֩ ʼesĕţé̇֨r la⁠hàţá֜kĕ mi⁠sá̇riysé֤y ha⁠mė֨lekĕ֙ ʼàşě֣r heʻèmi֣yd lĕ⁠páne֔y⁠há wa⁠ţĕ̇ẕawé֖̇⁠hẇ ʻaֽl-márĕdȯká֑y lá⁠da֥ʻaţ mah-zė֖h wĕ⁠ʻal-mah-zėֽh׃"],[4,6,"וַ⁠יֵּצֵ֥א הֲתָ֖ךְ אֶֽל־מָרְדֳּכָ֑י אֶל־רְח֣וֹב הָ⁠עִ֔יר אֲשֶׁ֖ר לִ⁠פְנֵ֥י שַֽׁעַר־הַ⁠מֶּֽלֶךְ׃","wa⁠yé̇ẕé֥ʼ hàţá֖kĕ ʼeֽl-márĕdȯká֑y ʼel-rĕẖ֣wòb há⁠ʻi֔yr ʼàşě֖r li⁠pĕné֥y şǎֽʻar-ha⁠mėֽlekĕ׃"],[4,7,"וַ⁠יַּגֶּד־ל֣⁠וֹ מָרְדֳּכַ֔י אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑⁠הוּ וְ⁠אֵ֣ת ׀ פָּרָשַׁ֣ת הַ⁠כֶּ֗סֶף אֲשֶׁ֨ר אָמַ֤ר הָמָן֙ לִ֠⁠שְׁקוֹל עַל־גִּנְזֵ֥י הַ⁠מֶּ֛לֶךְ ביהודיים לְ⁠אַבְּדָֽ⁠ם׃","wa⁠yȧgėd-l֣⁠wò márĕdȯka֔y ʼé֖ţ ká̇l-ʼàşě֣r qárá֑⁠hẇ wĕ⁠ʼé֣ţ ׀ pá̇ráşǎ֣ţ ha⁠kė֗sep ʼàşě֨r ʼáma֤r hámán֙ li֠⁠şĕ̌qwòl ʻal-gi̇nĕzé֥y ha⁠mė֛lekĕ byhwdyym lĕ⁠ʼabĕ̇dáֽ⁠m׃"],[4,8,"וְ⁠אֶת־פַּתְשֶׁ֣גֶן כְּתָֽב־הַ֠⁠דָּת אֲשֶׁר־נִתַּ֨ן בְּ⁠שׁוּשָׁ֤ן לְ⁠הַשְׁמִידָ⁠ם֙ נָ֣תַן ל֔⁠וֹ לְ⁠הַרְא֥וֹת אֶת־אֶסְתֵּ֖ר וּ⁠לְ⁠הַגִּ֣יד לָ֑⁠הּ וּ⁠לְ⁠צַוּ֣וֹת עָלֶ֗י⁠הָ לָ⁠ב֨וֹא אֶל־הַ⁠מֶּ֧לֶךְ לְ⁠הִֽתְחַנֶּן־ל֛⁠וֹ וּ⁠לְ⁠בַקֵּ֥שׁ מִ⁠לְּ⁠פָנָ֖י⁠ו עַל־עַמָּֽ⁠הּ׃","wĕ⁠ʼeţ-pȧţĕşě֣gen kĕ̇ţáֽb-ha֠⁠dá̇ţ ʼàşěr-niţȧ֨n bĕ̇⁠ş̌ẇşá֤̌n lĕ⁠haşĕ̌miydá⁠m֙ ná֣ţan l֔⁠wò lĕ⁠harĕʼ֥wòţ ʼeţ-ʼesĕţé֖̇r ẇ⁠lĕ⁠hagi֣̇yd lá֑⁠ḣ ẇ⁠lĕ⁠ẕaẇ֣wòţ ʻále֗y⁠há lá⁠b֨wòʼ ʼel-ha⁠mė֧lekĕ lĕ⁠hiֽţĕẖanėn-l֛⁠wò ẇ⁠lĕ⁠baqé֥̇ş̌ mi⁠lĕ̇⁠páná֖y⁠w ʻal-ʻamáֽ̇⁠ḣ׃"],[4,9,"וַ⁠יָּב֖וֹא הֲתָ֑ךְ וַ⁠יַּגֵּ֣ד לְ⁠אֶסְתֵּ֔ר אֵ֖ת דִּבְרֵ֥י מָרְדֳּכָֽי׃","wa⁠yá̇b֖wòʼ hàţá֑kĕ wa⁠yȧgé֣̇d lĕ⁠ʼesĕţé̇֔r ʼé֖ţ di̇bĕré֥y márĕdȯkáֽy׃"],[4,10,"וַ⁠תֹּ֤אמֶר אֶסְתֵּר֙ לַ⁠הֲתָ֔ךְ וַ⁠תְּצַוֵּ֖⁠הוּ אֶֽל־מָרְדֳּכָֽי׃","wa⁠ţò֤̇ʼmer ʼesĕţé̇r֙ la⁠hàţá֔kĕ wa⁠ţĕ̇ẕawé֖̇⁠hẇ ʼeֽl-márĕdȯkáֽy׃"],[4,11,"כָּל־עַבְדֵ֣י הַ⁠מֶּ֡לֶךְ וְ⁠עַם־מְדִינ֨וֹת הַ⁠מֶּ֜לֶךְ יֽוֹדְעִ֗ים אֲשֶׁ֣ר כָּל־אִ֣ישׁ וְ⁠אִשָּׁ֡ה אֲשֶׁ֣ר יָבֽוֹא־אֶל־הַ⁠מֶּלֶךְ֩ אֶל־הֶ⁠חָצֵ֨ר הַ⁠פְּנִימִ֜ית אֲשֶׁ֣ר לֹֽא־יִקָּרֵ֗א אַחַ֤ת דָּת⁠וֹ֙ לְ⁠הָמִ֔ית לְ֠⁠בַד מֵ⁠אֲשֶׁ֨ר יֽוֹשִׁיט־ל֥⁠וֹ הַ⁠מֶּ֛לֶךְ אֶת־שַׁרְבִ֥יט הַ⁠זָּהָ֖ב וְ⁠חָיָ֑ה וַ⁠אֲנִ֗י לֹ֤א נִקְרֵ֨אתי֙ לָ⁠ב֣וֹא אֶל־הַ⁠מֶּ֔לֶךְ זֶ֖ה שְׁלוֹשִׁ֥ים יֽוֹם׃","ká̇l-ʻabĕdé֣y ha⁠mė֡lekĕ wĕ⁠ʻam-mĕdiyn֨wòţ ha⁠mė֜lekĕ yֽwòdĕʻi֗ym ʼàşě֣r ká̇l-ʼi֣yş̌ wĕ⁠ʼişá̇̌֡h ʼàşě֣r yábֽwòʼ-ʼel-ha⁠mėlekĕ֩ ʼel-he⁠ẖáẕé֨r ha⁠pĕ̇niymi֜yţ ʼàşě֣r lòֽʼ-yiqá̇ré֗ʼ ʼaẖa֤ţ dá̇ţ⁠wò֙ lĕ⁠hámi֔yţ lĕ֠⁠bad mé⁠ʼàşě֨r yֽwòşǐyt-l֥⁠wò ha⁠mė֛lekĕ ʼeţ-şǎrĕbi֥yt ha⁠zá̇há֖b wĕ⁠ẖáyá֑h wa⁠ʼàni֗y lò֤ʼ niqĕré֨ʼţy֙ lá⁠b֣wòʼ ʼel-ha⁠mė֔lekĕ ze֖h şĕ̌lwòşǐ֥ym yֽwòm׃"],[4,12,"וַ⁠יַּגִּ֣ידוּ לְ⁠מָרְדֳּכָ֔י אֵ֖ת דִּבְרֵ֥י אֶסְתֵּֽר׃פ","wa⁠yȧgi֣̇ydẇ lĕ⁠márĕdȯká֔y ʼé֖ţ di̇bĕré֥y ʼesĕţéֽ̇r׃p"],[4,13,"וַ⁠יֹּ֥אמֶר מָרְדֳּכַ֖י לְ⁠הָשִׁ֣יב אֶל־אֶסְתֵּ֑ר אַל־תְּדַמִּ֣י בְ⁠נַפְשֵׁ֔⁠ךְ לְ⁠הִמָּלֵ֥ט בֵּית־הַ⁠מֶּ֖לֶךְ מִ⁠כָּל־הַ⁠יְּהוּדִֽים׃","wa⁠yò֥̇ʼmer márĕdȯka֖y lĕ⁠háşǐ֣yb ʼel-ʼesĕţé֑̇r ʼal-ţĕ̇dami֣̇y bĕ⁠napĕşé̌֔⁠kĕ lĕ⁠himá̇lé֥t bé̇yţ-ha⁠mė֖lekĕ mi⁠ká̇l-ha⁠yĕ̇hẇdiֽym׃"],[4,14,"כִּ֣י אִם־הַחֲרֵ֣שׁ תַּחֲרִישִׁי֮ בָּ⁠עֵ֣ת הַ⁠זֹּאת֒ רֶ֣וַח וְ⁠הַצָּלָ֞ה יַעֲמ֤וֹד לַ⁠יְּהוּדִים֙ מִ⁠מָּק֣וֹם אַחֵ֔ר וְ⁠אַ֥תְּ וּ⁠בֵית־אָבִ֖י⁠ךְ תֹּאבֵ֑דוּ וּ⁠מִ֣י יוֹדֵ֔עַ אִם־לְ⁠עֵ֣ת כָּ⁠זֹ֔את הִגַּ֖עַתְּ לַ⁠מַּלְכֽוּת׃","ki֣̇y ʼim-haẖàré֣ş̌ ţȧẖàriyşǐy֮ bá̇⁠ʻé֣ţ ha⁠zò̇ʼţ֒ re֣waẖ wĕ⁠haẕá̇lá֞h yaʻàm֤wòd la⁠yĕ̇hẇdiym֙ mi⁠má̇q֣wòm ʼaẖé֔r wĕ⁠ʼa֥ţĕ̇ ẇ⁠béyţ-ʼábi֖y⁠kĕ ţò̇ʼbé֑dẇ ẇ⁠mi֣y ywòdé֔ʻa ʼim-lĕ⁠ʻé֣ţ ká̇⁠zò֔ʼţ higȧ֖ʻaţĕ̇ la⁠mȧlĕkֽẇţ׃"],[4,15,"וַ⁠תֹּ֥אמֶר אֶסְתֵּ֖ר לְ⁠הָשִׁ֥יב אֶֽל־מָרְדֳּכָֽי׃","wa⁠ţò֥̇ʼmer ʼesĕţé֖̇r lĕ⁠háşǐ֥yb ʼeֽl-márĕdȯkáֽy׃"],[4,16,"לֵךְ֩ כְּנ֨וֹס אֶת־כָּל־הַ⁠יְּהוּדִ֜ים הַֽ⁠נִּמְצְאִ֣ים בְּ⁠שׁוּשָׁ֗ן וְ⁠צ֣וּמוּ עָ֠לַ⁠י וְ⁠אַל־תֹּאכְל֨וּ וְ⁠אַל־תִּשְׁתּ֜וּ שְׁלֹ֤שֶׁת יָמִים֙ לַ֣יְלָה וָ⁠י֔וֹם גַּם־אֲנִ֥י וְ⁠נַעֲרֹתַ֖⁠י אָצ֣וּם כֵּ֑ן וּ⁠בְ⁠כֵ֞ן אָב֤וֹא אֶל־הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר לֹֽא־כַ⁠דָּ֔ת וְ⁠כַ⁠אֲשֶׁ֥ר אָבַ֖דְתִּי אָבָֽדְתִּי׃","lékĕ֩ kĕ̇n֨wòs ʼeţ-ká̇l-ha⁠yĕ̇hẇdi֜ym haֽ⁠ni̇mĕẕĕʼi֣ym bĕ̇⁠ş̌ẇşá̌֗n wĕ⁠ẕ֣ẇmẇ ʻá֠la⁠y wĕ⁠ʼal-ţò̇ʼkĕl֨ẇ wĕ⁠ʼal-ţi̇şĕ̌ţ̇֜ẇ şĕ̌lò֤şěţ yámiym֙ la֣yĕláh wá⁠y֔wòm gȧm-ʼàni֥y wĕ⁠naʻàròţa֖⁠y ʼáẕ֣ẇm ké֑̇n ẇ⁠bĕ⁠ké֞n ʼáb֤wòʼ ʼel-ha⁠mė֨lekĕ֙ ʼàşě֣r lòֽʼ-ka⁠dá̇֔ţ wĕ⁠ka⁠ʼàşě֥r ʼába֖dĕţi̇y ʼábáֽdĕţi̇y׃"],[4,17,"וַֽ⁠יַּעֲבֹ֖ר מָרְדֳּכָ֑י וַ⁠יַּ֕עַשׂ כְּ⁠כֹ֛ל אֲשֶׁר־צִוְּתָ֥ה עָלָ֖י⁠ו אֶסְתֵּֽר׃ס","waֽ⁠yȧʻàbò֖r márĕdȯká֑y wa⁠yȧ֕ʻaş̂ kĕ̇⁠kò֛l ʼàşěr-ẕiwĕ̇ţá֥h ʻálá֖y⁠w ʼesĕţéֽ̇r׃s"],[5,1,"וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֗י וַ⁠תִּלְבַּ֤שׁ אֶסְתֵּר֙ מַלְכ֔וּת וַֽ⁠תַּעֲמֹ֞ד בַּ⁠חֲצַ֤ר בֵּית־הַ⁠מֶּ֨לֶךְ֙ הַ⁠פְּנִימִ֔ית נֹ֖כַח בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ֠⁠הַ⁠מֶּלֶךְ יוֹשֵׁ֞ב עַל־כִּסֵּ֤א מַלְכוּת⁠וֹ֙ בְּ⁠בֵ֣ית הַ⁠מַּלְכ֔וּת נֹ֖כַח פֶּ֥תַח הַ⁠בָּֽיִת׃","wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֗y wa⁠ţi̇lĕbȧ֤ş̌ ʼesĕţé̇r֙ malĕk֔ẇţ waֽ⁠ţȧʻàmò֞d bȧ⁠ẖàẕa֤r bé̇yţ-ha⁠mė֨lekĕ֙ ha⁠pĕ̇niymi֔yţ nò֖kaẖ bé֣̇yţ ha⁠mė֑lekĕ wĕ֠⁠ha⁠mėlekĕ ywòşé̌֞b ʻal-ki̇sé֤̇ʼ malĕkẇţ⁠wò֙ bĕ̇⁠bé֣yţ ha⁠mȧlĕk֔ẇţ nò֖kaẖ pė֥ţaẖ ha⁠báֽ̇yiţ׃"],[5,2,"וַ⁠יְהִי֩ כִ⁠רְא֨וֹת הַ⁠מֶּ֜לֶךְ אֶת־אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֗ה עֹמֶ֨דֶת֙ בֶּֽ⁠חָצֵ֔ר נָשְׂאָ֥ה חֵ֖ן בְּ⁠עֵינָ֑י⁠ו וַ⁠יּ֨וֹשֶׁט הַ⁠מֶּ֜לֶךְ לְ⁠אֶסְתֵּ֗ר אֶת־שַׁרְבִ֤יט הַ⁠זָּהָב֙ אֲשֶׁ֣ר בְּ⁠יָד֔⁠וֹ וַ⁠תִּקְרַ֣ב אֶסְתֵּ֔ר וַ⁠תִּגַּ֖ע בְּ⁠רֹ֥אשׁ הַ⁠שַּׁרְבִֽיט׃ס","wa⁠yĕhiy֩ ki⁠rĕʼ֨wòţ ha⁠mė֜lekĕ ʼeţ-ʼesĕţé֣̇r ha⁠mȧlĕká̇֗h ʻòme֨deţ֙ bėֽ⁠ẖáẕé֔r náşĕ̂ʼá֥h ẖé֖n bĕ̇⁠ʻéyná֑y⁠w wa⁠ẏ֨wòşět ha⁠mė֜lekĕ lĕ⁠ʼesĕţé̇֗r ʼeţ-şǎrĕbi֤yt ha⁠zá̇háb֙ ʼàşě֣r bĕ̇⁠yád֔⁠wò wa⁠ţi̇qĕra֣b ʼesĕţé̇֔r wa⁠ţi̇gȧ֖ʻ bĕ̇⁠rò֥ʼş̌ ha⁠şȧ̌rĕbiֽyt׃s"],[5,3,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ הַ⁠מֶּ֔לֶךְ מַה־לָּ֖⁠ךְ אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠יִנָּ֥תֵֽן לָֽ⁠ךְ׃","wa⁠yò֤̇ʼmer lá⁠ḣ֙ ha⁠mė֔lekĕ mah-lá֖̇⁠kĕ ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠yiná֥̇ţéֽn láֽ⁠kĕ׃"],[5,4,"וַ⁠תֹּ֣אמֶר אֶסְתֵּ֔ר אִם־עַל־הַ⁠מֶּ֖לֶךְ ט֑וֹב יָב֨וֹא הַ⁠מֶּ֤לֶךְ וְ⁠הָמָן֙ הַ⁠יּ֔וֹם אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשִׂ֥יתִי לֽ⁠וֹ׃","wa⁠ţò֣̇ʼmer ʼesĕţé̇֔r ʼim-ʻal-ha⁠mė֖lekĕ t֑wòb yáb֨wòʼ ha⁠mė֤lekĕ wĕ⁠hámán֙ ha⁠ẏ֔wòm ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşî֥yţiy lֽ⁠wò׃"],[5,5,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ מַהֲרוּ֙ אֶת־הָמָ֔ן לַ⁠עֲשׂ֖וֹת אֶת־דְּבַ֣ר אֶסְתֵּ֑ר וַ⁠יָּבֹ֤א הַ⁠מֶּ֨לֶךְ֙ וְ⁠הָמָ֔ן אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ mahàrẇ֙ ʼeţ-hámá֔n la⁠ʻàş֖̂wòţ ʼeţ-dĕ̇ba֣r ʼesĕţé֑̇r wa⁠yá̇bò֤ʼ ha⁠mė֨lekĕ֙ wĕ⁠hámá֔n ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[5,6,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ לְ⁠אֶסְתֵּר֙ בְּ⁠מִשְׁתֵּ֣ה הַ⁠יַּ֔יִן מַה־שְּׁאֵלָתֵ֖⁠ךְ וְ⁠יִנָּ֣תֵֽן לָ֑⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠תֵעָֽשׂ׃","wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ lĕ⁠ʼesĕţé̇r֙ bĕ̇⁠mişĕ̌ţé֣̇h ha⁠yȧ֔yin mah-şĕ̇̌ʼéláţé֖⁠kĕ wĕ⁠yiná֣̇ţéֽn lá֑⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠ţéʻáֽş̂׃"],[5,7,"וַ⁠תַּ֥עַן אֶסְתֵּ֖ר וַ⁠תֹּאמַ֑ר שְׁאֵלָתִ֖⁠י וּ⁠בַקָּשָׁתִֽ⁠י׃","wa⁠ţȧ֥ʻan ʼesĕţé֖̇r wa⁠ţò̇ʼma֑r şĕ̌ʼéláţi֖⁠y ẇ⁠baqá̇şá̌ţiֽ⁠y׃"],[5,8,"אִם־מָצָ֨אתִי חֵ֜ן בְּ⁠עֵינֵ֣י הַ⁠מֶּ֗לֶךְ וְ⁠אִם־עַל־הַ⁠מֶּ֨לֶךְ֙ ט֔וֹב לָ⁠תֵת֙ אֶת־שְׁאֵ֣לָתִ֔⁠י וְ⁠לַ⁠עֲשׂ֖וֹת אֶת־בַּקָּשָׁתִ֑⁠י יָב֧וֹא הַ⁠מֶּ֣לֶךְ וְ⁠הָמָ֗ן אֶל־הַ⁠מִּשְׁתֶּה֙ אֲשֶׁ֣ר אֶֽעֱשֶׂ֣ה לָ⁠הֶ֔ם וּ⁠מָחָ֥ר אֶֽעֱשֶׂ֖ה כִּ⁠דְבַ֥ר הַ⁠מֶּֽלֶךְ׃","ʼim-máẕá֨ʼţiy ẖé֜n bĕ̇⁠ʻéyné֣y ha⁠mė֗lekĕ wĕ⁠ʼim-ʻal-ha⁠mė֨lekĕ֙ t֔wòb lá⁠ţéţ֙ ʼeţ-şĕ̌ʼé֣láţi֔⁠y wĕ⁠la⁠ʻàş֖̂wòţ ʼeţ-bȧqá̇şá̌ţi֑⁠y yáb֧wòʼ ha⁠mė֣lekĕ wĕ⁠hámá֗n ʼel-ha⁠mi̇şĕ̌ţėh֙ ʼàşě֣r ʼeֽʻèşê֣h lá⁠he֔m ẇ⁠máẖá֥r ʼeֽʻèşê֖h ki̇⁠dĕba֥r ha⁠mėֽlekĕ׃"],[5,9,"וַ⁠יֵּצֵ֤א הָמָן֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא שָׂמֵ֖חַ וְ⁠ט֣וֹב לֵ֑ב וְ⁠כִ⁠רְאוֹת֩ הָמָ֨ן אֶֽת־מָרְדֳּכַ֜י בְּ⁠שַׁ֣עַר הַ⁠מֶּ֗לֶךְ וְ⁠לֹא־קָם֙ וְ⁠לֹא־זָ֣ע מִמֶּ֔⁠נּוּ וַ⁠יִּמָּלֵ֥א הָמָ֛ן עַֽל־מָרְדֳּכַ֖י חֵמָֽה׃","wa⁠yé̇ẕé֤ʼ hámán֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ şá̂mé֖ẖa wĕ⁠t֣wòb lé֑b wĕ⁠ki⁠rĕʼwòţ֩ hámá֨n ʼeֽţ-márĕdȯka֜y bĕ̇⁠şǎ֣ʻar ha⁠mė֗lekĕ wĕ⁠lòʼ-qám֙ wĕ⁠lòʼ-zá֣ʻ mimė֔⁠ṅẇ wa⁠yi̇má̇lé֥ʼ hámá֛n ʻaֽl-márĕdȯka֖y ẖémáֽh׃"],[5,10,"וַ⁠יִּתְאַפַּ֣ק הָמָ֔ן וַ⁠יָּב֖וֹא אֶל־בֵּית֑⁠וֹ וַ⁠יִּשְׁלַ֛ח וַ⁠יָּבֵ֥א אֶת־אֹהֲבָ֖י⁠ו וְ⁠אֶת־זֶ֥רֶשׁ אִשְׁתּֽ⁠וֹ׃","wa⁠yi̇ţĕʼapȧ֣q hámá֔n wa⁠yá̇b֖wòʼ ʼel-bé̇yţ֑⁠wò wa⁠yi̇şĕ̌la֛ẖ wa⁠yá̇bé֥ʼ ʼeţ-ʼòhàbá֖y⁠w wĕ⁠ʼeţ-ze֥reş̌ ʼişĕ̌ţֽ̇⁠wò׃"],[5,11,"וַ⁠יְסַפֵּ֨ר לָ⁠הֶ֥ם הָמָ֛ן אֶת־כְּב֥וֹד עָשְׁר֖⁠וֹ וְ⁠רֹ֣ב בָּנָ֑י⁠ו וְ⁠אֵת֩ כָּל־אֲשֶׁ֨ר גִּדְּל֤⁠וֹ הַ⁠מֶּ֨לֶךְ֙ וְ⁠אֵ֣ת אֲשֶׁ֣ר נִשְּׂא֔⁠וֹ עַל־הַ⁠שָּׂרִ֖ים וְ⁠עַבְדֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yĕsapé̇֨r lá⁠he֥m hámá֛n ʼeţ-kĕ̇b֥wòd ʻáşĕ̌r֖⁠wò wĕ⁠rò֣b bá̇ná֑y⁠w wĕ⁠ʼéţ֩ ká̇l-ʼàşě֨r gi̇dĕ̇l֤⁠wò ha⁠mė֨lekĕ֙ wĕ⁠ʼé֣ţ ʼàşě֣r nişĕ̇̂ʼ֔⁠wò ʻal-ha⁠şá̇̂ri֖ym wĕ⁠ʻabĕdé֥y ha⁠mėֽlekĕ׃"],[5,12,"וַ⁠יֹּאמֶר֮ הָמָן֒ אַ֣ף לֹא־הֵבִיאָה֩ אֶסְתֵּ֨ר הַ⁠מַּלְכָּ֧ה עִם־הַ⁠מֶּ֛לֶךְ אֶל־הַ⁠מִּשְׁתֶּ֥ה אֲשֶׁר־עָשָׂ֖תָה כִּ֣י אִם־אוֹתִ֑⁠י וְ⁠גַם־לְ⁠מָחָ֛ר אֲנִ֥י קָֽרוּא־לָ֖⁠הּ עִם־הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇ʼmer֮ hámán֒ ʼa֣p lòʼ-hébiyʼáh֩ ʼesĕţé̇֨r ha⁠mȧlĕká֧̇h ʻim-ha⁠mė֛lekĕ ʼel-ha⁠mi̇şĕ̌ţė֥h ʼàşěr-ʻáşá֖̂ţáh ki֣̇y ʼim-ʼwòţi֑⁠y wĕ⁠gam-lĕ⁠máẖá֛r ʼàni֥y qáֽrẇʼ-lá֖⁠ḣ ʻim-ha⁠mėֽlekĕ׃"],[5,13,"וְ⁠כָל־זֶ֕ה אֵינֶ֥⁠נּוּ שֹׁוֶ֖ה לִ֑⁠י בְּ⁠כָל־עֵ֗ת אֲשֶׁ֨ר אֲנִ֤י רֹאֶה֙ אֶת־מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֔י יוֹשֵׁ֖ב בְּ⁠שַׁ֥עַר הַ⁠מֶּֽלֶךְ׃","wĕ⁠kál-ze֕h ʼéyne֥⁠ṅẇ şò̌we֖h li֑⁠y bĕ̇⁠kál-ʻé֗ţ ʼàşě֨r ʼàni֤y ròʼeh֙ ʼeţ-márĕdȯka֣y ha⁠yĕ̇hẇdi֔y ywòşé֖̌b bĕ̇⁠şǎ֥ʻar ha⁠mėֽlekĕ׃"],[5,14,"וַ⁠תֹּ֣אמֶר ל⁠וֹ֩ זֶ֨רֶשׁ אִשְׁתּ֜⁠וֹ וְ⁠כָל־אֹֽהֲבָ֗י⁠ו יַֽעֲשׂוּ־עֵץ֮ גָּבֹ֣הַּ חֲמִשִּׁ֣ים אַמָּה֒ וּ⁠בַ⁠בֹּ֣קֶר ׀ אֱמֹ֣ר לַ⁠מֶּ֗לֶךְ וְ⁠יִתְל֤וּ אֶֽת־מָרְדֳּכַי֙ עָלָ֔י⁠ו וּ⁠בֹֽא־עִם־הַ⁠מֶּ֥לֶךְ אֶל הַ⁠מִּשְׁתֶּ֖ה שָׂמֵ֑חַ וַ⁠יִּיטַ֧ב הַ⁠דָּבָ֛ר לִ⁠פְנֵ֥י הָמָ֖ן וַ⁠יַּ֥עַשׂ הָ⁠עֵֽץ׃פ","wa⁠ţò֣̇ʼmer l⁠wò֩ ze֨reş̌ ʼişĕ̌ţ̇֜⁠wò wĕ⁠kál-ʼòֽhàbá֗y⁠w yaֽʻàş̂ẇ-ʻéẕ֮ gá̇bò֣hȧ ẖàmişi֣̇̌ym ʼamá̇h֒ ẇ⁠ba⁠bò֣̇qer ׀ ʼèmò֣r la⁠mė֗lekĕ wĕ⁠yiţĕl֤ẇ ʼeֽţ-márĕdȯkay֙ ʻálá֔y⁠w ẇ⁠bòֽʼ-ʻim-ha⁠mė֥lekĕ ʼel ha⁠mi̇şĕ̌ţė֖h şá̂mé֑ẖa wa⁠yi̇yta֧b ha⁠dá̇bá֛r li⁠pĕné֥y hámá֖n wa⁠yȧ֥ʻaş̂ há⁠ʻéֽẕ׃p"],[6,1,"בַּ⁠לַּ֣יְלָה הַ⁠ה֔וּא נָדְדָ֖ה שְׁנַ֣ת הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֗אמֶר לְ⁠הָבִ֞יא אֶת־סֵ֤פֶר הַ⁠זִּכְרֹנוֹת֙ דִּבְרֵ֣י הַ⁠יָּמִ֔ים וַ⁠יִּהְי֥וּ נִקְרָאִ֖ים לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","bȧ⁠lȧ֣yĕláh ha⁠h֔ẇʼ nádĕdá֖h şĕ̌na֣ţ ha⁠mė֑lekĕ wa⁠yò̇֗ʼmer lĕ⁠hábi֞yʼ ʼeţ-sé֤per ha⁠zi̇kĕrònwòţ֙ di̇bĕré֣y ha⁠yá̇mi֔ym wa⁠yi̇hĕy֥ẇ niqĕráʼi֖ym li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[6,2,"וַ⁠יִּמָּצֵ֣א כָת֗וּב אֲשֶׁר֩ הִגִּ֨יד מָרְדֳּכַ֜י עַל־בִּגְתָ֣נָא וָ⁠תֶ֗רֶשׁ שְׁנֵי֙ סָרִיסֵ֣י הַ⁠מֶּ֔לֶךְ מִ⁠שֹּׁמְרֵ֖י הַ⁠סַּ֑ף אֲשֶׁ֤ר בִּקְשׁוּ֙ לִ⁠שְׁלֹ֣חַ יָ֔ד בַּ⁠מֶּ֖לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wa⁠yi̇má̇ẕé֣ʼ káţ֗ẇb ʼàşěr֩ higi̇֨yd márĕdȯka֜y ʻal-bi̇gĕţá֣náʼ wá⁠ţe֗reş̌ şĕ̌néy֙ sáriysé֣y ha⁠mė֔lekĕ mi⁠şò̇̌mĕré֖y ha⁠sȧ֑p ʼàşě֤r bi̇qĕş̌ẇ֙ li⁠şĕ̌lò֣ẖa yá֔d bȧ⁠mė֖lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[6,3,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ מַֽה־נַּעֲשָׂ֞ה יְקָ֧ר וּ⁠גְדוּלָּ֛ה לְ⁠מָרְדֳּכַ֖י עַל־זֶ֑ה וַ⁠יֹּ֨אמְר֜וּ נַעֲרֵ֤י הַ⁠מֶּ֨לֶךְ֙ מְשָׁ֣רְתָ֔י⁠ו לֹא־נַעֲשָׂ֥ה עִמּ֖⁠וֹ דָּבָֽר׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ maֽh-nȧʻàşá̂֞h yĕqá֧r ẇ⁠gĕdẇlá֛̇h lĕ⁠márĕdȯka֖y ʻal-ze֑h wa⁠yò̇֨ʼmĕr֜ẇ naʻàré֤y ha⁠mė֨lekĕ֙ mĕşá֣̌rĕţá֔y⁠w lòʼ-naʻàşá֥̂h ʻiṁ֖⁠wò dá̇báֽr׃"],[6,4,"וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ מִ֣י בֶ⁠חָצֵ֑ר וְ⁠הָמָ֣ן בָּ֗א לַ⁠חֲצַ֤ר בֵּית־הַ⁠מֶּ֨לֶךְ֙ הַ⁠חִ֣יצוֹנָ֔ה לֵ⁠אמֹ֣ר לַ⁠מֶּ֔לֶךְ לִ⁠תְלוֹת֙ אֶֽת־מָרְדֳּכַ֔י עַל־הָ⁠עֵ֖ץ אֲשֶׁר־הֵכִ֥ין לֽ⁠וֹ׃","wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ mi֣y be⁠ẖáẕé֑r wĕ⁠hámá֣n bá̇֗ʼ la⁠ẖàẕa֤r bé̇yţ-ha⁠mė֨lekĕ֙ ha⁠ẖi֣yẕwòná֔h lé⁠ʼmò֣r la⁠mė֔lekĕ li⁠ţĕlwòţ֙ ʼeֽţ-márĕdȯka֔y ʻal-há⁠ʻé֖ẕ ʼàşěr-héki֥yn lֽ⁠wò׃"],[6,5,"וַ⁠יֹּ֨אמְר֜וּ נַעֲרֵ֤י הַ⁠מֶּ֨לֶךְ֙ אֵלָ֔י⁠ו הִנֵּ֥ה הָמָ֖ן עֹמֵ֣ד בֶּ⁠חָצֵ֑ר וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ יָבֽוֹא׃","wa⁠yò̇֨ʼmĕr֜ẇ naʻàré֤y ha⁠mė֨lekĕ֙ ʼélá֔y⁠w hiné֥̇h hámá֖n ʻòmé֣d bė⁠ẖáẕé֑r wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ yábֽwòʼ׃"],[6,6,"וַ⁠יָּבוֹא֮ הָמָן֒ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הַ⁠מֶּ֔לֶךְ מַה־לַ⁠עֲשׂ֕וֹת בָּ⁠אִ֕ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֣ץ בִּ⁠יקָר֑⁠וֹ וַ⁠יֹּ֤אמֶר הָמָן֙ בְּ⁠לִבּ֔⁠וֹ לְ⁠מִ֞י יַחְפֹּ֥ץ הַ⁠מֶּ֛לֶךְ לַ⁠עֲשׂ֥וֹת יְקָ֖ר יוֹתֵ֥ר מִמֶּֽ⁠נִּי׃","wa⁠yá̇bwòʼ֮ hámán֒ wa⁠yò֤̇ʼmer l⁠wò֙ ha⁠mė֔lekĕ mah-la⁠ʻàş̂֕wòţ bá̇⁠ʼi֕yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֣ẕ bi̇⁠yqár֑⁠wò wa⁠yò֤̇ʼmer hámán֙ bĕ̇⁠liḃ֔⁠wò lĕ⁠mi֞y yaẖĕpò֥̇ẕ ha⁠mė֛lekĕ la⁠ʻàş֥̂wòţ yĕqá֖r ywòţé֥r mimėֽ⁠ni̇y׃"],[6,7,"וַ⁠יֹּ֥אמֶר הָמָ֖ן אֶל־הַ⁠מֶּ֑לֶךְ אִ֕ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wa⁠yò֥̇ʼmer hámá֖n ʼel-ha⁠mė֑lekĕ ʼi֕yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,8,"יָבִ֨יאוּ֙ לְב֣וּשׁ מַלְכ֔וּת אֲשֶׁ֥ר לָֽבַשׁ־בּ֖⁠וֹ הַ⁠מֶּ֑לֶךְ וְ⁠ס֗וּס אֲשֶׁ֨ר רָכַ֤ב עָלָי⁠ו֙ הַ⁠מֶּ֔לֶךְ וַ⁠אֲשֶׁ֥ר נִתַּ֛ן כֶּ֥תֶר מַלְכ֖וּת בְּ⁠רֹאשֽׁ⁠וֹ׃","yábi֨yʼẇ֙ lĕb֣ẇş̌ malĕk֔ẇţ ʼàşě֥r láֽbaş̌-ḃ֖⁠wò ha⁠mė֑lekĕ wĕ⁠s֗ẇs ʼàşě֨r ráka֤b ʻáláy⁠w֙ ha⁠mė֔lekĕ wa⁠ʼàşě֥r niţȧ֛n kė֥ţer malĕk֖ẇţ bĕ̇⁠ròʼşֽ̌⁠wò׃"],[6,9,"וְ⁠נָת֨וֹן הַ⁠לְּב֜וּשׁ וְ⁠הַ⁠סּ֗וּס עַל־יַד־אִ֞ישׁ מִ⁠שָּׂרֵ֤י הַ⁠מֶּ֨לֶךְ֙ הַֽ⁠פַּרְתְּמִ֔ים וְ⁠הִלְבִּ֨ישׁוּ֙ אֶת־הָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֣ץ בִּֽ⁠יקָר֑⁠וֹ וְ⁠הִרְכִּיבֻ֤⁠הוּ עַל־הַ⁠סּוּס֙ בִּ⁠רְח֣וֹב הָ⁠עִ֔יר וְ⁠קָרְא֣וּ לְ⁠פָנָ֔י⁠ו כָּ֚כָה יֵעָשֶׂ֣ה לָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wĕ⁠náţ֨wòn ha⁠lĕ̇b֜ẇş̌ wĕ⁠ha⁠ṡ֗ẇs ʻal-yad-ʼi֞yş̌ mi⁠şá̇̂ré֤y ha⁠mė֨lekĕ֙ haֽ⁠pȧrĕţĕ̇mi֔ym wĕ⁠hilĕbi̇֨yş̌ẇ֙ ʼeţ-há⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֣ẕ biֽ̇⁠yqár֑⁠wò wĕ⁠hirĕki̇ybu֤⁠hẇ ʻal-ha⁠ṡẇs֙ bi̇⁠rĕẖ֣wòb há⁠ʻi֔yr wĕ⁠qárĕʼ֣ẇ lĕ⁠páná֔y⁠w ká֚̇káh yéʻáşê֣h lá⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,10,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ לְ⁠הָמָ֗ן מַ֠הֵר קַ֣ח אֶת־הַ⁠לְּב֤וּשׁ וְ⁠אֶת־הַ⁠סּוּס֙ כַּ⁠אֲשֶׁ֣ר דִּבַּ֔רְתָּ וַֽ⁠עֲשֵׂה־כֵן֙ לְ⁠מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֔י הַ⁠יּוֹשֵׁ֖ב בְּ⁠שַׁ֣עַר הַ⁠מֶּ֑לֶךְ אַל־תַּפֵּ֣ל דָּבָ֔ר מִ⁠כֹּ֖ל אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ lĕ⁠hámá֗n ma֠hér qa֣ẖ ʼeţ-ha⁠lĕ̇b֤ẇş̌ wĕ⁠ʼeţ-ha⁠ṡẇs֙ kȧ⁠ʼàşě֣r di̇bȧ֔rĕţá̇ waֽ⁠ʻàşé̂h-kén֙ lĕ⁠márĕdȯka֣y ha⁠yĕ̇hẇdi֔y ha⁠ẏwòşé֖̌b bĕ̇⁠şǎ֣ʻar ha⁠mė֑lekĕ ʼal-ţȧpé֣̇l dá̇bá֔r mi⁠kò֖̇l ʼàşě֥r di̇bȧֽrĕţá̇׃"],[6,11,"וַ⁠יִּקַּ֤ח הָמָן֙ אֶת־הַ⁠לְּב֣וּשׁ וְ⁠אֶת־הַ⁠סּ֔וּס וַ⁠יַּלְבֵּ֖שׁ אֶֽת־מָרְדֳּכָ֑י וַ⁠יַּרְכִּיבֵ֨⁠הוּ֙ בִּ⁠רְח֣וֹב הָ⁠עִ֔יר וַ⁠יִּקְרָ֣א לְ⁠פָנָ֔י⁠ו כָּ֚כָה יֵעָשֶׂ֣ה לָ⁠אִ֔ישׁ אֲשֶׁ֥ר הַ⁠מֶּ֖לֶךְ חָפֵ֥ץ בִּ⁠יקָרֽ⁠וֹ׃","wa⁠yi̇qȧ֤ẖ hámán֙ ʼeţ-ha⁠lĕ̇b֣ẇş̌ wĕ⁠ʼeţ-ha⁠ṡ֔ẇs wa⁠yȧlĕbé֖̇ş̌ ʼeֽţ-márĕdȯká֑y wa⁠yȧrĕki̇ybé֨⁠hẇ֙ bi̇⁠rĕẖ֣wòb há⁠ʻi֔yr wa⁠yi̇qĕrá֣ʼ lĕ⁠páná֔y⁠w ká֚̇káh yéʻáşê֣h lá⁠ʼi֔yş̌ ʼàşě֥r ha⁠mė֖lekĕ ẖápé֥ẕ bi̇⁠yqárֽ⁠wò׃"],[6,12,"וַ⁠יָּ֥שָׁב מָרְדֳּכַ֖י אֶל־שַׁ֣עַר הַ⁠מֶּ֑לֶךְ וְ⁠הָמָן֙ נִדְחַ֣ף אֶל־בֵּית֔⁠וֹ אָבֵ֖ל וַ⁠חֲפ֥וּי רֹֽאשׁ׃","wa⁠yá֥̇şá̌b márĕdȯka֖y ʼel-şǎ֣ʻar ha⁠mė֑lekĕ wĕ⁠hámán֙ nidĕẖa֣p ʼel-bé̇yţ֔⁠wò ʼábé֖l wa⁠ẖàp֥ẇy ròֽʼş̌׃"],[6,13,"וַ⁠יְסַפֵּ֨ר הָמָ֜ן לְ⁠זֶ֤רֶשׁ אִשְׁתּ⁠וֹ֙ וּ⁠לְ⁠כָל־אֹ֣הֲבָ֔י⁠ו אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑⁠הוּ וַ⁠יֹּ֩אמְרוּ֩ ל֨⁠וֹ חֲכָמָ֜י⁠ו וְ⁠זֶ֣רֶשׁ אִשְׁתּ֗⁠וֹ אִ֣ם מִ⁠זֶּ֣רַע הַ⁠יְּהוּדִ֡ים מָרְדֳּכַ֞י אֲשֶׁר֩ הַחִלּ֨וֹתָ לִ⁠נְפֹּ֤ל לְ⁠פָנָי⁠ו֙ לֹא־תוּכַ֣ל ל֔⁠וֹ כִּֽי־נָפ֥וֹל תִּפּ֖וֹל לְ⁠פָנָֽי⁠ו׃","wa⁠yĕsapé̇֨r hámá֜n lĕ⁠ze֤reş̌ ʼişĕ̌ţ̇⁠wò֙ ẇ⁠lĕ⁠kál-ʼò֣hàbá֔y⁠w ʼé֖ţ ká̇l-ʼàşě֣r qárá֑⁠hẇ wa⁠yò̇֩ʼmĕrẇ֩ l֨⁠wò ẖàkámá֜y⁠w wĕ⁠ze֣reş̌ ʼişĕ̌ţ̇֗⁠wò ʼi֣m mi⁠zė֣raʻ ha⁠yĕ̇hẇdi֡ym márĕdȯka֞y ʼàşěr֩ haẖil̇֨wòţá li⁠nĕpò֤̇l lĕ⁠pánáy⁠w֙ lòʼ-ţẇka֣l l֔⁠wò kiֽ̇y-náp֥wòl ţi̇ṗ֖wòl lĕ⁠pánáֽy⁠w׃"],[6,14,"עוֹדָ⁠ם֙ מְדַבְּרִ֣ים עִמּ֔⁠וֹ וְ⁠סָרִיסֵ֥י הַ⁠מֶּ֖לֶךְ הִגִּ֑יעוּ וַ⁠יַּבְהִ֨לוּ֙ לְ⁠הָבִ֣יא אֶת־הָמָ֔ן אֶל־הַ⁠מִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","ʻwòdá⁠m֙ mĕdabĕ̇ri֣ym ʻiṁ֔⁠wò wĕ⁠sáriysé֥y ha⁠mė֖lekĕ higi֑̇yʻẇ wa⁠yȧbĕhi֨lẇ֙ lĕ⁠hábi֣yʼ ʼeţ-hámá֔n ʼel-ha⁠mi̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[7,1,"וַ⁠יָּבֹ֤א הַ⁠מֶּ֨לֶךְ֙ וְ⁠הָמָ֔ן לִ⁠שְׁתּ֖וֹת עִם־אֶסְתֵּ֥ר הַ⁠מַּלְכָּֽה׃","wa⁠yá̇bò֤ʼ ha⁠mė֨lekĕ֙ wĕ⁠hámá֔n li⁠şĕ̌ţ֖̇wòţ ʻim-ʼesĕţé֥̇r ha⁠mȧlĕkáֽ̇h׃"],[7,2,"וַ⁠יֹּאמֶר֩ הַ⁠מֶּ֨לֶךְ לְ⁠אֶסְתֵּ֜ר גַּ֣ם בַּ⁠יּ֤וֹם הַ⁠שֵּׁנִי֙ בְּ⁠מִשְׁתֵּ֣ה הַ⁠יַּ֔יִן מַה־שְּׁאֵלָתֵ֛⁠ךְ אֶסְתֵּ֥ר הַ⁠מַּלְכָּ֖ה וְ⁠תִנָּ֣תֵֽן לָ֑⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֛⁠ךְ עַד־חֲצִ֥י הַ⁠מַּלְכ֖וּת וְ⁠תֵעָֽשׂ׃","wa⁠yò̇ʼmer֩ ha⁠mė֨lekĕ lĕ⁠ʼesĕţé̇֜r gȧ֣m bȧ⁠ẏ֤wòm ha⁠şé̇̌niy֙ bĕ̇⁠mişĕ̌ţé֣̇h ha⁠yȧ֔yin mah-şĕ̇̌ʼéláţé֛⁠kĕ ʼesĕţé֥̇r ha⁠mȧlĕká֖̇h wĕ⁠ţiná֣̇ţéֽn lá֑⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֛⁠kĕ ʻad-ẖàẕi֥y ha⁠mȧlĕk֖ẇţ wĕ⁠ţéʻáֽş̂׃"],[7,3,"וַ⁠תַּ֨עַן אֶסְתֵּ֤ר הַ⁠מַּלְכָּה֙ וַ⁠תֹּאמַ֔ר אִם־מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ הַ⁠מֶּ֔לֶךְ וְ⁠אִם־עַל־הַ⁠מֶּ֖לֶךְ ט֑וֹב תִּנָּֽתֶן־לִ֤⁠י נַפְשִׁ⁠י֙ בִּ⁠שְׁאֵ֣לָתִ֔⁠י וְ⁠עַמִּ֖⁠י בְּ⁠בַקָּשָׁתִֽ⁠י׃","wa⁠ţȧ֨ʻan ʼesĕţé֤̇r ha⁠mȧlĕká̇h֙ wa⁠ţò̇ʼma֔r ʼim-máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ ha⁠mė֔lekĕ wĕ⁠ʼim-ʻal-ha⁠mė֖lekĕ t֑wòb ţi̇náֽ̇ţen-li֤⁠y napĕşǐ⁠y֙ bi̇⁠şĕ̌ʼé֣láţi֔⁠y wĕ⁠ʻami֖̇⁠y bĕ̇⁠baqá̇şá̌ţiֽ⁠y׃"],[7,4,"כִּ֤י נִמְכַּ֨רְנוּ֙ אֲנִ֣י וְ⁠עַמִּ֔⁠י לְ⁠הַשְׁמִ֖יד לַ⁠הֲר֣וֹג וּ⁠לְ⁠אַבֵּ֑ד וְ֠⁠אִלּוּ לַ⁠עֲבָדִ֨ים וְ⁠לִ⁠שְׁפָח֤וֹת נִמְכַּ֨רְנוּ֙ הֶחֱרַ֔שְׁתִּי כִּ֣י אֵ֥ין הַ⁠צָּ֛ר שֹׁוֶ֖ה בְּ⁠נֵ֥זֶק הַ⁠מֶּֽלֶךְ׃ס","ki֤̇y nimĕkȧ֨rĕnẇ֙ ʼàni֣y wĕ⁠ʻami̇֔⁠y lĕ⁠haşĕ̌mi֖yd la⁠hàr֣wòg ẇ⁠lĕ⁠ʼabé֑̇d wĕ֠⁠ʼil̇ẇ la⁠ʻàbádi֨ym wĕ⁠li⁠şĕ̌páẖ֤wòţ nimĕkȧ֨rĕnẇ֙ heẖèra֔şĕ̌ţi̇y ki֣̇y ʼé֥yn ha⁠ẕá֛̇r şò̌we֖h bĕ̇⁠né֥zeq ha⁠mėֽlekĕ׃s"],[7,5,"וַ⁠יֹּ֨אמֶר֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וַ⁠יֹּ֖אמֶר לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֑ה מִ֣י ה֥וּא זֶה֙ וְ⁠אֵֽי־זֶ֣ה ה֔וּא אֲשֶׁר־מְלָא֥⁠וֹ לִבּ֖⁠וֹ לַ⁠עֲשׂ֥וֹת כֵּֽן׃","wa⁠yò̇֨ʼmer֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wa⁠yò֖̇ʼmer lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká֑̇h mi֣y h֥ẇʼ zeh֙ wĕ⁠ʼéֽy-ze֣h h֔ẇʼ ʼàşěr-mĕláʼ֥⁠wò liḃ֖⁠wò la⁠ʻàş֥̂wòţ kéֽ̇n׃"],[7,6,"וַ⁠תֹּ֣אמֶר־אֶסְתֵּ֔ר אִ֚ישׁ צַ֣ר וְ⁠אוֹיֵ֔ב הָמָ֥ן הָ⁠רָ֖ע הַ⁠זֶּ֑ה וְ⁠הָמָ֣ן נִבְעַ֔ת מִ⁠לִּ⁠פְנֵ֥י הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠מַּלְכָּֽה׃","wa⁠ţò֣̇ʼmer-ʼesĕţé̇֔r ʼi֚yş̌ ẕa֣r wĕ⁠ʼwòyé֔b hámá֥n há⁠rá֖ʻ ha⁠zė֑h wĕ⁠hámá֣n nibĕʻa֔ţ mi⁠li̇⁠pĕné֥y ha⁠mė֖lekĕ wĕ⁠ha⁠mȧlĕkáֽ̇h׃"],[7,7,"וְ⁠הַ⁠מֶּ֜לֶךְ קָ֤ם בַּ⁠חֲמָת⁠וֹ֙ מִ⁠מִּשְׁתֵּ֣ה הַ⁠יַּ֔יִן אֶל־גִּנַּ֖ת הַ⁠בִּיתָ֑ן וְ⁠הָמָ֣ן עָמַ֗ד לְ⁠בַקֵּ֤שׁ עַל־נַפְשׁ⁠וֹ֙ מֵֽ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה כִּ֣י רָאָ֔ה כִּֽי־כָלְתָ֥ה אֵלָ֛י⁠ו הָ⁠רָעָ֖ה מֵ⁠אֵ֥ת הַ⁠מֶּֽלֶךְ׃","wĕ⁠ha⁠mė֜lekĕ qá֤m bȧ⁠ẖàmáţ⁠wò֙ mi⁠mi̇şĕ̌ţé֣̇h ha⁠yȧ֔yin ʼel-gi̇nȧ֖ţ ha⁠bi̇yţá֑n wĕ⁠hámá֣n ʻáma֗d lĕ⁠baqé֤̇ş̌ ʻal-napĕş̌⁠wò֙ méֽ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ki֣̇y ráʼá֔h kiֽ̇y-kálĕţá֥h ʼélá֛y⁠w há⁠ráʻá֖h mé⁠ʼé֥ţ ha⁠mėֽlekĕ׃"],[7,8,"וְ⁠הַ⁠מֶּ֡לֶךְ שָׁב֩ מִ⁠גִּנַּ֨ת הַ⁠בִּיתָ֜ן אֶל־בֵּ֣ית ׀ מִשְׁתֵּ֣ה הַ⁠יַּ֗יִן וְ⁠הָמָן֙ נֹפֵ֔ל עַל־הַ⁠מִּטָּה֙ אֲשֶׁ֣ר אֶסְתֵּ֣ר עָלֶ֔י⁠הָ וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ הֲ֠⁠גַם לִ⁠כְבּ֧וֹשׁ אֶת־הַ⁠מַּלְכָּ֛ה עִמִּ֖⁠י בַּ⁠בָּ֑יִת הַ⁠דָּבָ֗ר יָצָא֙ מִ⁠פִּ֣י הַ⁠מֶּ֔לֶךְ וּ⁠פְנֵ֥י הָמָ֖ן חָפֽוּ׃ס","wĕ⁠ha⁠mė֡lekĕ şá̌b֩ mi⁠gi̇nȧ֨ţ ha⁠bi̇yţá֜n ʼel-bé֣̇yţ ׀ mişĕ̌ţé֣̇h ha⁠yȧ֗yin wĕ⁠hámán֙ nòpé֔l ʻal-ha⁠mi̇tá̇h֙ ʼàşě֣r ʼesĕţé֣̇r ʻále֔y⁠há wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ hà֠⁠gam li⁠kĕḃ֧wòş̌ ʼeţ-ha⁠mȧlĕká֛̇h ʻimi֖̇⁠y bȧ⁠bá֑̇yiţ ha⁠dá̇bá֗r yáẕáʼ֙ mi⁠pi֣̇y ha⁠mė֔lekĕ ẇ⁠pĕné֥y hámá֖n ẖápֽẇ׃s"],[7,9,"וַ⁠יֹּ֣אמֶר חַ֠רְבוֹנָה אֶחָ֨ד מִן־הַ⁠סָּרִיסִ֜ים לִ⁠פְנֵ֣י הַ⁠מֶּ֗לֶךְ גַּ֣ם הִנֵּה־הָ⁠עֵ֣ץ אֲשֶׁר־עָשָׂ֪ה הָמָ֟ן לְֽ⁠מָרְדֳּכַ֞י אֲשֶׁ֧ר דִּבֶּר־ט֣וֹב עַל־הַ⁠מֶּ֗לֶךְ עֹמֵד֙ בְּ⁠בֵ֣ית הָמָ֔ן גָּבֹ֖הַּ חֲמִשִּׁ֣ים אַמָּ֑ה וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ תְּלֻ֥⁠הוּ עָלָֽי⁠ו׃","wa⁠yò֣̇ʼmer ẖa֠rĕbwònáh ʼeẖá֨d min-ha⁠sá̇riysi֜ym li⁠pĕné֣y ha⁠mė֗lekĕ gȧ֣m hiné̇h-há⁠ʻé֣ẕ ʼàşěr-ʻáşá֪̂h hámá֟n lĕֽ⁠márĕdȯka֞y ʼàşě֧r di̇bėr-t֣wòb ʻal-ha⁠mė֗lekĕ ʻòméd֙ bĕ̇⁠bé֣yţ hámá֔n gá̇bò֖hȧ ẖàmişi֣̇̌ym ʼamá֑̇h wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ ţĕ̇lu֥⁠hẇ ʻáláֽy⁠w׃"],[7,10,"וַ⁠יִּתְלוּ֙ אֶת־הָמָ֔ן עַל־הָ⁠עֵ֖ץ אֲשֶׁר־הֵכִ֣ין לְ⁠מָרְדֳּכָ֑י וַ⁠חֲמַ֥ת הַ⁠מֶּ֖לֶךְ שָׁכָֽכָה׃פ","wa⁠yi̇ţĕlẇ֙ ʼeţ-hámá֔n ʻal-há⁠ʻé֖ẕ ʼàşěr-héki֣yn lĕ⁠márĕdȯká֑y wa⁠ẖàma֥ţ ha⁠mė֖lekĕ şá̌káֽkáh׃p"],[8,1,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נָתַ֞ן הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה אֶת־בֵּ֥ית הָמָ֖ן צֹרֵ֣ר היהודיים וּ⁠מָרְדֳּכַ֗י בָּ֚א לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ כִּֽי־הִגִּ֥ידָה אֶסְתֵּ֖ר מַ֥ה הוּא־לָֽ⁠הּ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ náţa֞n ha⁠mė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ʼeţ-bé֥̇yţ hámá֖n ẕòré֣r hyhwdyym ẇ⁠márĕdȯka֗y bá֚̇ʼ li⁠pĕné֣y ha⁠mė֔lekĕ kiֽ̇y-higi֥̇ydáh ʼesĕţé֖̇r ma֥h hẇʼ-láֽ⁠ḣ׃"],[8,2,"וַ⁠יָּ֨סַר הַ⁠מֶּ֜לֶךְ אֶת־טַבַּעְתּ֗⁠וֹ אֲשֶׁ֤ר הֶֽעֱבִיר֙ מֵֽ⁠הָמָ֔ן וַֽ⁠יִּתְּנָ֖⁠הּ לְ⁠מָרְדֳּכָ֑י וַ⁠תָּ֧שֶׂם אֶסְתֵּ֛ר אֶֽת־מָרְדֳּכַ֖י עַל־בֵּ֥ית הָמָֽן׃פ","wa⁠yá̇֨sar ha⁠mė֜lekĕ ʼeţ-tabȧʻĕţ̇֗⁠wò ʼàşě֤r heֽʻèbiyr֙ méֽ⁠hámá֔n waֽ⁠yi̇ţĕ̇ná֖⁠ḣ lĕ⁠márĕdȯká֑y wa⁠ţá֧̇şêm ʼesĕţé֛̇r ʼeֽţ-márĕdȯka֖y ʻal-bé֥̇yţ hámáֽn׃p"],[8,3,"וַ⁠תּ֣וֹסֶף אֶסְתֵּ֗ר וַ⁠תְּדַבֵּר֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וַ⁠תִּפֹּ֖ל לִ⁠פְנֵ֣י רַגְלָ֑י⁠ו וַ⁠תֵּ֣בְךְּ וַ⁠תִּתְחַנֶּן־ל֗⁠וֹ לְ⁠הַֽעֲבִיר֙ אֶת־רָעַת֙ הָמָ֣ן הָֽ⁠אֲגָגִ֔י וְ⁠אֵת֙ מַֽחֲשַׁבְתּ֔⁠וֹ אֲשֶׁ֥ר חָשַׁ֖ב עַל־הַ⁠יְּהוּדִֽים׃","wa⁠ţ֣̇wòsep ʼesĕţé̇֗r wa⁠ţĕ̇dabé̇r֙ li⁠pĕné֣y ha⁠mė֔lekĕ wa⁠ţi̇pò֖̇l li⁠pĕné֣y ragĕlá֑y⁠w wa⁠ţé֣̇bĕkĕ̇ wa⁠ţi̇ţĕẖanėn-l֗⁠wò lĕ⁠haֽʻàbiyr֙ ʼeţ-ráʻaţ֙ hámá֣n háֽ⁠ʼàgági֔y wĕ⁠ʼéţ֙ maֽẖàşǎbĕţ̇֔⁠wò ʼàşě֥r ẖáşǎ֖b ʻal-ha⁠yĕ̇hẇdiֽym׃"],[8,4,"וַ⁠יּ֤וֹשֶׁט הַ⁠מֶּ֨לֶךְ֙ לְ⁠אֶסְתֵּ֔ר אֵ֖ת שַׁרְבִ֣ט הַ⁠זָּהָ֑ב וַ⁠תָּ֣קָם אֶסְתֵּ֔ר וַֽ⁠תַּעֲמֹ֖ד לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠ẏ֤wòşět ha⁠mė֨lekĕ֙ lĕ⁠ʼesĕţé̇֔r ʼé֖ţ şǎrĕbi֣t ha⁠zá̇há֑b wa⁠ţá֣̇qám ʼesĕţé̇֔r waֽ⁠ţȧʻàmò֖d li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[8,5,"וַ֠⁠תֹּאמֶר אִם־עַל־הַ⁠מֶּ֨לֶךְ ט֜וֹב וְ⁠אִם־מָצָ֧אתִי חֵ֣ן לְ⁠פָנָ֗י⁠ו וְ⁠כָשֵׁ֤ר הַ⁠דָּבָר֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וְ⁠טוֹבָ֥ה אֲנִ֖י בְּ⁠עֵינָ֑י⁠ו יִכָּתֵ֞ב לְ⁠הָשִׁ֣יב אֶת־הַ⁠סְּפָרִ֗ים מַחֲשֶׁ֜בֶת הָמָ֤ן בֶּֽן־הַמְּדָ֨תָא֙ הָ⁠אֲגָגִ֔י אֲשֶׁ֣ר כָּתַ֗ב לְ⁠אַבֵּד֙ אֶת־הַ⁠יְּהוּדִ֔ים אֲשֶׁ֖ר בְּ⁠כָל־מְדִינ֥וֹת הַ⁠מֶּֽלֶךְ׃","wa֠⁠ţò̇ʼmer ʼim-ʻal-ha⁠mė֨lekĕ t֜wòb wĕ⁠ʼim-máẕá֧ʼţiy ẖé֣n lĕ⁠páná֗y⁠w wĕ⁠káşé֤̌r ha⁠dá̇bár֙ li⁠pĕné֣y ha⁠mė֔lekĕ wĕ⁠twòbá֥h ʼàni֖y bĕ̇⁠ʻéyná֑y⁠w yiká̇ţé֞b lĕ⁠háşǐ֣yb ʼeţ-ha⁠sĕ̇pári֗ym maẖàşě֜beţ hámá֤n bėֽn-hamĕ̇dá֨ţáʼ֙ há⁠ʼàgági֔y ʼàşě֣r ká̇ţa֗b lĕ⁠ʼabé̇d֙ ʼeţ-ha⁠yĕ̇hẇdi֔ym ʼàşě֖r bĕ̇⁠kál-mĕdiyn֥wòţ ha⁠mėֽlekĕ׃"],[8,6,"כִּ֠י אֵיכָכָ֤ה אוּכַל֙ וְֽ⁠רָאִ֔יתִי בָּ⁠רָעָ֖ה אֲשֶׁר־יִמְצָ֣א אֶת־עַמִּ֑⁠י וְ⁠אֵֽיכָכָ֤ה אוּכַל֙ וְֽ⁠רָאִ֔יתִי בְּ⁠אָבְדַ֖ן מוֹלַדְתִּֽ⁠י׃ס","ki̇֠y ʼéykáká֤h ʼẇkal֙ wĕֽ⁠ráʼi֔yţiy bá̇⁠ráʻá֖h ʼàşěr-yimĕẕá֣ʼ ʼeţ-ʻami֑̇⁠y wĕ⁠ʼéֽykáká֤h ʼẇkal֙ wĕֽ⁠ráʼi֔yţiy bĕ̇⁠ʼábĕda֖n mwòladĕţiֽ̇⁠y׃s"],[8,7,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה וּֽ⁠לְ⁠מָרְדֳּכַ֖י הַ⁠יְּהוּדִ֑י הִנֵּ֨ה בֵית־הָמָ֜ן נָתַ֣תִּי לְ⁠אֶסְתֵּ֗ר וְ⁠אֹת⁠וֹ֙ תָּל֣וּ עַל־הָ⁠עֵ֔ץ עַ֛ל אֲשֶׁר־שָׁלַ֥ח יָד֖⁠וֹ ביהודיים׃","wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h ẇֽ⁠lĕ⁠márĕdȯka֖y ha⁠yĕ̇hẇdi֑y hiné̇֨h béyţ-hámá֜n náţa֣ţi̇y lĕ⁠ʼesĕţé̇֗r wĕ⁠ʼòţ⁠wò֙ ţá̇l֣ẇ ʻal-há⁠ʻé֔ẕ ʻa֛l ʼàşěr-şá̌la֥ẖ yád֖⁠wò byhwdyym׃"],[8,8,"וְ֠⁠אַתֶּם כִּתְב֨וּ עַל־הַ⁠יְּהוּדִ֜ים כַּ⁠טּ֤וֹב בְּ⁠עֵֽינֵי⁠כֶם֙ בְּ⁠שֵׁ֣ם הַ⁠מֶּ֔לֶךְ וְ⁠חִתְמ֖וּ בְּ⁠טַבַּ֣עַת הַ⁠מֶּ֑לֶךְ כִּֽי־כְתָ֞ב אֲשֶׁר־נִכְתָּ֣ב בְּ⁠שֵׁם־הַ⁠מֶּ֗לֶךְ וְ⁠נַחְתּ֛וֹם בְּ⁠טַבַּ֥עַת הַ⁠מֶּ֖לֶךְ אֵ֥ין לְ⁠הָשִֽׁיב׃","wĕ֠⁠ʼaţėm ki̇ţĕb֨ẇ ʻal-ha⁠yĕ̇hẇdi֜ym kȧ⁠ṫ֤wòb bĕ̇⁠ʻéֽynéy⁠kem֙ bĕ̇⁠şé֣̌m ha⁠mė֔lekĕ wĕ⁠ẖiţĕm֖ẇ bĕ̇⁠tabȧ֣ʻaţ ha⁠mė֑lekĕ kiֽ̇y-kĕţá֞b ʼàşěr-nikĕţá֣̇b bĕ̇⁠şé̌m-ha⁠mė֗lekĕ wĕ⁠naẖĕţ֛̇wòm bĕ̇⁠tabȧ֥ʻaţ ha⁠mė֖lekĕ ʼé֥yn lĕ⁠háşǐֽyb׃"],[8,9,"וַ⁠יִּקָּרְא֣וּ סֹפְרֵֽי־הַ⁠מֶּ֣לֶךְ בָּֽ⁠עֵת־הַ֠⁠הִיא בַּ⁠חֹ֨דֶשׁ הַ⁠שְּׁלִישִׁ֜י הוּא־חֹ֣דֶשׁ סִיוָ֗ן בִּ⁠שְׁלוֹשָׁ֣ה וְ⁠עֶשְׂרִים֮ בּ⁠וֹ֒ וַ⁠יִּכָּתֵ֣ב כְּֽ⁠כָל־אֲשֶׁר־צִוָּ֣ה מָרְדֳּכַ֣י אֶל־הַ⁠יְּהוּדִ֡ים וְ⁠אֶ֣ל הָ⁠אֲחַשְׁדַּרְפְּנִֽים־וְ⁠הַ⁠פַּחוֹת֩ וְ⁠שָׂרֵ֨י הַ⁠מְּדִינ֜וֹת אֲשֶׁ֣ר ׀ מֵ⁠הֹ֣דּוּ וְ⁠עַד־כּ֗וּשׁ שֶׁ֣בַע וְ⁠עֶשְׂרִ֤ים וּ⁠מֵאָה֙ מְדִינָ֔ה מְדִינָ֤ה וּ⁠מְדִינָה֙ כִּ⁠כְתָבָ֔⁠הּ וְ⁠עַ֥ם וָ⁠עָ֖ם כִּ⁠לְשֹׁנ֑⁠וֹ וְ⁠אֶ֨ל־הַ⁠יְּהוּדִ֔ים כִּ⁠כְתָבָ֖⁠ם וְ⁠כִ⁠לְשׁוֹנָֽ⁠ם׃","wa⁠yi̇qá̇rĕʼ֣ẇ sòpĕréֽy-ha⁠mė֣lekĕ báֽ̇⁠ʻéţ-ha֠⁠hiyʼ bȧ⁠ẖò֨deş̌ ha⁠şĕ̇̌liyşǐ֜y hẇʼ-ẖò֣deş̌ siywá֗n bi̇⁠şĕ̌lwòşá֣̌h wĕ⁠ʻeşĕ̂riym֮ ḃ⁠wò֒ wa⁠yi̇ká̇ţé֣b kĕֽ̇⁠kál-ʼàşěr-ẕiwá֣̇h márĕdȯka֣y ʼel-ha⁠yĕ̇hẇdi֡ym wĕ⁠ʼe֣l há⁠ʼàẖaşĕ̌dȧrĕpĕ̇niֽym-wĕ⁠ha⁠pȧẖwòţ֩ wĕ⁠şá̂ré֨y ha⁠mĕ̇diyn֜wòţ ʼàşě֣r ׀ mé⁠hò֣ḋẇ wĕ⁠ʻad-k̇֗ẇş̌ şě֣baʻ wĕ⁠ʻeşĕ̂ri֤ym ẇ⁠méʼáh֙ mĕdiyná֔h mĕdiyná֤h ẇ⁠mĕdiynáh֙ ki̇⁠kĕţábá֔⁠ḣ wĕ⁠ʻa֥m wá⁠ʻá֖m ki̇⁠lĕşò̌n֑⁠wò wĕ⁠ʼe֨l-ha⁠yĕ̇hẇdi֔ym ki̇⁠kĕţábá֖⁠m wĕ⁠ki⁠lĕş̌wònáֽ⁠m׃"],[8,10,"וַ⁠יִּכְתֹּ֗ב בְּ⁠שֵׁם֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵרֹ֔שׁ וַ⁠יַּחְתֹּ֖ם בְּ⁠טַבַּ֣עַת הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֣ח סְפָרִ֡ים בְּ⁠יַד֩ הָ⁠רָצִ֨ים בַּ⁠סּוּסִ֜ים רֹכְבֵ֤י הָ⁠רֶ֨כֶשׁ֙ הָֽ⁠אֲחַשְׁתְּרָנִ֔ים בְּנֵ֖י הָֽ⁠רַמָּכִֽים׃","wa⁠yi̇kĕţò̇֗b bĕ̇⁠şé̌m֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wérò֔ş̌ wa⁠yȧẖĕţò֖̇m bĕ̇⁠tabȧ֣ʻaţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֣ẖ sĕpári֡ym bĕ̇⁠yad֩ há⁠ráẕi֨ym bȧ⁠ṡẇsi֜ym ròkĕbé֤y há⁠re֨keş̌֙ háֽ⁠ʼàẖaşĕ̌ţĕ̇ráni֔ym bĕ̇né֖y háֽ⁠ramá̇kiֽym׃"],[8,11,"אֲשֶׁר֩ נָתַ֨ן הַ⁠מֶּ֜לֶךְ לַ⁠יְּהוּדִ֣ים ׀ אֲשֶׁ֣ר בְּ⁠כָל־עִיר־וָ⁠עִ֗יר לְ⁠הִקָּהֵל֮ וְ⁠לַ⁠עֲמֹ֣ד עַל־נַפְשָׁ⁠ם֒ לְ⁠הַשְׁמִיד֩ וְ⁠לַ⁠הֲרֹ֨ג וּ⁠לְ⁠אַבֵּ֜ד אֶת־כָּל־חֵ֨יל עַ֧ם וּ⁠מְדִינָ֛ה הַ⁠צָּרִ֥ים אֹתָ֖⁠ם טַ֣ף וְ⁠נָשִׁ֑ים וּ⁠שְׁלָלָ֖⁠ם לָ⁠בֽוֹז׃","ʼàşěr֩ náţa֨n ha⁠mė֜lekĕ la⁠yĕ̇hẇdi֣ym ׀ ʼàşě֣r bĕ̇⁠kál-ʻiyr-wá⁠ʻi֗yr lĕ⁠hiqá̇hél֮ wĕ⁠la⁠ʻàmò֣d ʻal-napĕşá̌⁠m֒ lĕ⁠haşĕ̌miyd֩ wĕ⁠la⁠hàrò֨g ẇ⁠lĕ⁠ʼabé̇֜d ʼeţ-ká̇l-ẖé֨yl ʻa֧m ẇ⁠mĕdiyná֛h ha⁠ẕá̇ri֥ym ʼòţá֖⁠m ta֣p wĕ⁠náşǐ֑ym ẇ⁠şĕ̌lálá֖⁠m lá⁠bֽwòz׃"],[8,12,"בְּ⁠י֣וֹם אֶחָ֔ד בְּ⁠כָל־מְדִינ֖וֹת הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ בִּ⁠שְׁלוֹשָׁ֥ה עָשָׂ֛ר לְ⁠חֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃","bĕ̇⁠y֣wòm ʼeẖá֔d bĕ̇⁠kál-mĕdiyn֖wòţ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ bi̇⁠şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕ⁠ẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃"],[8,13,"פַּתְשֶׁ֣גֶן הַ⁠כְּתָ֗ב לְ⁠הִנָּ֤תֵֽן דָּת֙ בְּ⁠כָל־מְדִינָ֣ה וּ⁠מְדִינָ֔ה גָּל֖וּי לְ⁠כָל־הָ⁠עַמִּ֑ים וְ⁠לִ⁠הְי֨וֹת היהודיים עתודים לַ⁠יּ֣וֹם הַ⁠זֶּ֔ה לְ⁠הִנָּקֵ֖ם מֵ⁠אֹיְבֵי⁠הֶֽם׃","pȧţĕşě֣gen ha⁠kĕ̇ţá֗b lĕ⁠hiná֤̇ţéֽn dá̇ţ֙ bĕ̇⁠kál-mĕdiyná֣h ẇ⁠mĕdiyná֔h gá̇l֖ẇy lĕ⁠kál-há⁠ʻami֑̇ym wĕ⁠li⁠hĕy֨wòţ hyhwdyym ʻţwdym la⁠ẏ֣wòm ha⁠zė֔h lĕ⁠hiná̇qé֖m mé⁠ʼòyĕbéy⁠heֽm׃"],[8,14,"הָ⁠רָצִ֞ים רֹכְבֵ֤י הָ⁠רֶ֨כֶשׁ֙ הָֽ⁠אֲחַשְׁתְּרָנִ֔ים יָֽצְא֛וּ מְבֹהָלִ֥ים וּ⁠דְחוּפִ֖ים בִּ⁠דְבַ֣ר הַ⁠מֶּ֑לֶךְ וְ⁠הַ⁠דָּ֥ת נִתְּנָ֖ה בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָֽה׃פ","há⁠ráẕi֞ym ròkĕbé֤y há⁠re֨keş̌֙ háֽ⁠ʼàẖaşĕ̌ţĕ̇ráni֔ym yáֽẕĕʼ֛ẇ mĕbòháli֥ym ẇ⁠dĕẖẇpi֖ym bi̇⁠dĕba֣r ha⁠mė֑lekĕ wĕ⁠ha⁠dá֥̇ţ niţĕ̇ná֖h bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yráֽh׃p"],[8,15,"וּ⁠מָרְדֳּכַ֞י יָצָ֣א ׀ מִ⁠לִּ⁠פְנֵ֣י הַ⁠מֶּ֗לֶךְ בִּ⁠לְב֤וּשׁ מַלְכוּת֙ תְּכֵ֣לֶת וָ⁠ח֔וּר וַ⁠עֲטֶ֤רֶת זָהָב֙ גְּדוֹלָ֔ה וְ⁠תַכְרִ֥יךְ בּ֖וּץ וְ⁠אַרְגָּמָ֑ן וְ⁠הָ⁠עִ֣יר שׁוּשָׁ֔ן צָהֲלָ֖ה וְ⁠שָׂמֵֽחָה׃","ẇ⁠márĕdȯka֞y yáẕá֣ʼ ׀ mi⁠li̇⁠pĕné֣y ha⁠mė֗lekĕ bi̇⁠lĕb֤ẇş̌ malĕkẇţ֙ ţĕ̇ké֣leţ wá⁠ẖ֔ẇr wa⁠ʻàte֤reţ záháb֙ gĕ̇dwòlá֔h wĕ⁠ţakĕri֥ykĕ ḃ֖ẇẕ wĕ⁠ʼarĕgá̇má֑n wĕ⁠há⁠ʻi֣yr ş̌ẇşá̌֔n ẕáhàlá֖h wĕ⁠şá̂méֽẖáh׃"],[8,16,"לַ⁠יְּהוּדִ֕ים הָֽיְתָ֥ה אוֹרָ֖ה וְ⁠שִׂמְחָ֑ה וְ⁠שָׂשֹׂ֖ן וִ⁠יקָֽר׃","la⁠yĕ̇hẇdi֕ym háֽyĕţá֥h ʼwòrá֖h wĕ⁠şîmĕẖá֑h wĕ⁠şá̂şò֖̂n wi⁠yqáֽr׃"],[8,17,"וּ⁠בְ⁠כָל־מְדִינָ֨ה וּ⁠מְדִינָ֜ה וּ⁠בְ⁠כָל־עִ֣יר וָ⁠עִ֗יר מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַ⁠מֶּ֤לֶךְ וְ⁠דָת⁠וֹ֙ מַגִּ֔יעַ שִׂמְחָ֤ה וְ⁠שָׂשׂוֹן֙ לַ⁠יְּהוּדִ֔ים מִשְׁתֶּ֖ה וְ⁠י֣וֹם ט֑וֹב וְ⁠רַבִּ֞ים מֵֽ⁠עַמֵּ֤י הָ⁠אָ֨רֶץ֙ מִֽתְיַהֲדִ֔ים כִּֽי־נָפַ֥ל פַּֽחַד־הַ⁠יְּהוּדִ֖ים עֲלֵי⁠הֶֽם׃","ẇ⁠bĕ⁠kál-mĕdiyná֨h ẇ⁠mĕdiyná֜h ẇ⁠bĕ⁠kál-ʻi֣yr wá⁠ʻi֗yr mĕqwòm֙ ʼàşě֨r dĕ̇bar-ha⁠mė֤lekĕ wĕ⁠dáţ⁠wò֙ magi̇֔yʻa şîmĕẖá֤h wĕ⁠şá̂ş̂wòn֙ la⁠yĕ̇hẇdi֔ym mişĕ̌ţė֖h wĕ⁠y֣wòm t֑wòb wĕ⁠rabi̇֞ym méֽ⁠ʻamé֤̇y há⁠ʼá֨reẕ֙ miֽţĕyahàdi֔ym kiֽ̇y-nápa֥l pȧֽẖad-ha⁠yĕ̇hẇdi֖ym ʻàléy⁠heֽm׃"],[9,1,"וּ⁠בִ⁠שְׁנֵים֩ עָשָׂ֨ר חֹ֜דֶשׁ הוּא־חֹ֣דֶשׁ אֲדָ֗ר בִּ⁠שְׁלוֹשָׁ֨ה עָשָׂ֥ר יוֹם֙ בּ֔⁠וֹ אֲשֶׁ֨ר הִגִּ֧יעַ דְּבַר־הַ⁠מֶּ֛לֶךְ וְ⁠דָת֖⁠וֹ לְ⁠הֵעָשׂ֑וֹת בַּ⁠יּ֗וֹם אֲשֶׁ֨ר שִׂבְּר֜וּ אֹיְבֵ֤י הַ⁠יְּהוּדִים֙ לִ⁠שְׁל֣וֹט בָּ⁠הֶ֔ם וְ⁠נַהֲפ֣וֹךְ ה֔וּא אֲשֶׁ֨ר יִשְׁלְט֧וּ הַ⁠יְּהוּדִ֛ים הֵ֖מָּה בְּ⁠שֹׂנְאֵי⁠הֶֽם׃","ẇ⁠bi⁠şĕ̌néym֩ ʻáşá̂֨r ẖò֜deş̌ hẇʼ-ẖò֣deş̌ ʼàdá֗r bi̇⁠şĕ̌lwòşá̌֨h ʻáşá֥̂r ywòm֙ ḃ֔⁠wò ʼàşě֨r higi֧̇yʻa dĕ̇bar-ha⁠mė֛lekĕ wĕ⁠dáţ֖⁠wò lĕ⁠héʻáş֑̂wòţ bȧ⁠ẏ֗wòm ʼàşě֨r şîbĕ̇r֜ẇ ʼòyĕbé֤y ha⁠yĕ̇hẇdiym֙ li⁠şĕ̌l֣wòt bá̇⁠he֔m wĕ⁠nahàp֣wòkĕ h֔ẇʼ ʼàşě֨r yişĕ̌lĕt֧ẇ ha⁠yĕ̇hẇdi֛ym hé֖má̇h bĕ̇⁠şò̂nĕʼéy⁠heֽm׃"],[9,2,"נִקְהֲל֨וּ הַ⁠יְּהוּדִ֜ים בְּ⁠עָרֵי⁠הֶ֗ם בְּ⁠כָל־מְדִינוֹת֙ הַ⁠מֶּ֣לֶךְ אֳחַשְׁוֵר֔וֹשׁ לִ⁠שְׁלֹ֣חַ יָ֔ד בִּ⁠מְבַקְשֵׁ֖י רָֽעָתָ֑⁠ם וְ⁠אִישׁ֙ לֹא־עָמַ֣ד לִ⁠פְנֵי⁠הֶ֔ם כִּֽי־נָפַ֥ל פַּחְדָּ֖⁠ם עַל־כָּל־הָ⁠עַמִּֽים׃","niqĕhàl֨ẇ ha⁠yĕ̇hẇdi֜ym bĕ̇⁠ʻáréy⁠he֗m bĕ̇⁠kál-mĕdiynwòţ֙ ha⁠mė֣lekĕ ʼoẖaşĕ̌wér֔wòş̌ li⁠şĕ̌lò֣ẖa yá֔d bi̇⁠mĕbaqĕşé֖̌y ráֽʻáţá֑⁠m wĕ⁠ʼiyş̌֙ lòʼ-ʻáma֣d li⁠pĕnéy⁠he֔m kiֽ̇y-nápa֥l pȧẖĕdá֖̇⁠m ʻal-ká̇l-há⁠ʻamiֽ̇ym׃"],[9,3,"וְ⁠כָל־שָׂרֵ֨י הַ⁠מְּדִינ֜וֹת וְ⁠הָ⁠אֲחַשְׁדַּרְפְּנִ֣ים וְ⁠הַ⁠פַּח֗וֹת וְ⁠עֹשֵׂ֤י הַ⁠מְּלָאכָה֙ אֲשֶׁ֣ר לַ⁠מֶּ֔לֶךְ מְנַשְּׂאִ֖ים אֶת־הַ⁠יְּהוּדִ֑ים כִּֽי־נָפַ֥ל פַּֽחַד־מָרְדֳּכַ֖י עֲלֵי⁠הֶֽם׃","wĕ⁠kál-şá̂ré֨y ha⁠mĕ̇diyn֜wòţ wĕ⁠há⁠ʼàẖaşĕ̌dȧrĕpĕ̇ni֣ym wĕ⁠ha⁠pȧẖ֗wòţ wĕ⁠ʻòşé֤̂y ha⁠mĕ̇láʼkáh֙ ʼàşě֣r la⁠mė֔lekĕ mĕnaşĕ̇̂ʼi֖ym ʼeţ-ha⁠yĕ̇hẇdi֑ym kiֽ̇y-nápa֥l pȧֽẖad-márĕdȯka֖y ʻàléy⁠heֽm׃"],[9,4,"כִּֽי־גָ֤דוֹל מָרְדֳּכַי֙ בְּ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠שָׁמְע֖⁠וֹ הוֹלֵ֣ךְ בְּ⁠כָל־הַ⁠מְּדִינ֑וֹת כִּֽי־הָ⁠אִ֥ישׁ מָרְדֳּכַ֖י הוֹלֵ֥ךְ וְ⁠גָדֽוֹל׃פ","kiֽ̇y-gá֤dwòl márĕdȯkay֙ bĕ̇⁠bé֣yţ ha⁠mė֔lekĕ wĕ⁠şá̌mĕʻ֖⁠wò hwòlé֣kĕ bĕ̇⁠kál-ha⁠mĕ̇diyn֑wòţ kiֽ̇y-há⁠ʼi֥yş̌ márĕdȯka֖y hwòlé֥kĕ wĕ⁠gádֽwòl׃p"],[9,5,"וַ⁠יַּכּ֤וּ הַ⁠יְּהוּדִים֙ בְּ⁠כָל־אֹ֣יְבֵי⁠הֶ֔ם מַכַּת־חֶ֥רֶב וְ⁠הֶ֖רֶג וְ⁠אַבְדָ֑ן וַ⁠יַּֽעֲשׂ֥וּ בְ⁠שֹׂנְאֵי⁠הֶ֖ם כִּ⁠רְצוֹנָֽ⁠ם׃","wa⁠yȧk֤̇ẇ ha⁠yĕ̇hẇdiym֙ bĕ̇⁠kál-ʼò֣yĕbéy⁠he֔m makȧţ-ẖe֥reb wĕ⁠he֖reg wĕ⁠ʼabĕdá֑n wa⁠yȧֽʻàş֥̂ẇ bĕ⁠şò̂nĕʼéy⁠he֖m ki̇⁠rĕẕwònáֽ⁠m׃"],[9,6,"וּ⁠בְ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֗ה הָרְג֤וּ הַ⁠יְּהוּדִים֙ וְ⁠אַבֵּ֔ד חֲמֵ֥שׁ מֵא֖וֹת אִֽישׁ׃","ẇ⁠bĕ⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֗h hárĕg֤ẇ ha⁠yĕ̇hẇdiym֙ wĕ⁠ʼabé̇֔d ẖàmé֥ş̌ méʼ֖wòţ ʼiֽyş̌׃"],[9,7,"וְ⁠אֵ֧ת ׀ פַּרְשַׁנְדָּ֛תָא וְ⁠אֵ֥ת ׀ דַּֽלְפ֖וֹן וְ⁠אֵ֥ת ׀ אַסְפָּֽתָא׃","wĕ⁠ʼé֧ţ ׀ pȧrĕşǎnĕdá֛̇ţáʼ wĕ⁠ʼé֥ţ ׀ dȧֽlĕp֖wòn wĕ⁠ʼé֥ţ ׀ ʼasĕpáֽ̇ţáʼ׃"],[9,8,"וְ⁠אֵ֧ת ׀ פּוֹרָ֛תָא וְ⁠אֵ֥ת ׀ אֲדַלְיָ֖א וְ⁠אֵ֥ת ׀ אֲרִידָֽתָא׃","wĕ⁠ʼé֧ţ ׀ ṗwòrá֛ţáʼ wĕ⁠ʼé֥ţ ׀ ʼàdalĕyá֖ʼ wĕ⁠ʼé֥ţ ׀ ʼàriydáֽţáʼ׃"],[9,9,"וְ⁠אֵ֤ת ׀ פַּרְמַ֨שְׁתָּא֙ וְ⁠אֵ֣ת ׀ אֲרִיסַ֔י וְ⁠אֵ֥ת ׀ אֲרִדַ֖י וְ⁠אֵ֥ת ׀ וַיְזָֽתָא׃","wĕ⁠ʼé֤ţ ׀ pȧrĕma֨şĕ̌ţá̇ʼ֙ wĕ⁠ʼé֣ţ ׀ ʼàriysa֔y wĕ⁠ʼé֥ţ ׀ ʼàrida֖y wĕ⁠ʼé֥ţ ׀ wayĕzáֽţáʼ׃"],[9,10,"עֲ֠שֶׂרֶת בְּנֵ֨י הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא צֹרֵ֥ר הַ⁠יְּהוּדִ֖ים הָרָ֑גוּ וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","ʻà֠şêreţ bĕ̇né֨y hámá֧n bėֽn-hamĕ̇dá֛ţáʼ ẕòré֥r ha⁠yĕ̇hẇdi֖ym hárá֑gẇ ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,11,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא בָּ֣א מִסְפַּ֧ר הַֽ⁠הֲרוּגִ֛ים בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָ֖ה לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ bá֣̇ʼ misĕpȧ֧r hֽa⁠hàrẇgi֛ym bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yrá֖h li⁠pĕné֥y ha⁠mėֽlekĕ׃s"],[9,12,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ לְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֗ה בְּ⁠שׁוּשַׁ֣ן הַ⁠בִּירָ֡ה הָרְגוּ֩ הַ⁠יְּהוּדִ֨ים וְ⁠אַבֵּ֜ד חֲמֵ֧שׁ מֵא֣וֹת אִ֗ישׁ וְ⁠אֵת֙ עֲשֶׂ֣רֶת בְּנֵֽי־הָמָ֔ן בִּ⁠שְׁאָ֛ר מְדִינ֥וֹת הַ⁠מֶּ֖לֶךְ מֶ֣ה עָשׂ֑וּ וּ⁠מַה־שְּׁאֵֽלָתֵ⁠ךְ֙ וְ⁠יִנָּ֣תֵֽן לָ֔⁠ךְ וּ⁠מַה־בַּקָּשָׁתֵ֥⁠ךְ ע֖וֹד וְ⁠תֵעָֽשׂ׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ lĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֗h bĕ̇⁠ş̌ẇşǎ֣n ha⁠bi̇yrá֡h hárĕgẇ֩ ha⁠yĕ̇hẇdi֨ym wĕ⁠ʼabé̇֜d ẖàmé֧ş̌ méʼ֣wòţ ʼi֗yş̌ wĕ⁠ʼéţ֙ ʻàşê֣reţ bĕ̇néֽy-hámá֔n bi̇⁠şĕ̌ʼá֛r mĕdiyn֥wòţ ha⁠mė֖lekĕ me֣h ʻáş֑̂ẇ ẇ⁠mah-şĕ̇̌ʼéֽláţé⁠kĕ֙ wĕ⁠yiná֣̇ţéֽn lá֔⁠kĕ ẇ⁠mah-bȧqá̇şá̌ţé֥⁠kĕ ʻ֖wòd wĕ⁠ţéʻáֽş̂׃"],[9,13,"וַ⁠תֹּ֤אמֶר אֶסְתֵּר֙ אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב יִנָּתֵ֣ן גַּם־מָחָ֗ר לַ⁠יְּהוּדִים֙ אֲשֶׁ֣ר בְּ⁠שׁוּשָׁ֔ן לַ⁠עֲשׂ֖וֹת כְּ⁠דָ֣ת הַ⁠יּ֑וֹם וְ⁠אֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן יִתְל֥וּ עַל־הָ⁠עֵֽץ׃","wa⁠ţò֤̇ʼmer ʼesĕţé̇r֙ ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb yiná̇ţé֣n gȧm-máẖá֗r la⁠yĕ̇hẇdiym֙ ʼàşě֣r bĕ̇⁠ş̌ẇşá̌֔n la⁠ʻàş֖̂wòţ kĕ̇⁠dá֣ţ ha⁠ẏ֑wòm wĕ⁠ʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n yiţĕl֥ẇ ʻal-há⁠ʻéֽẕ׃"],[9,14,"וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ לְ⁠הֵֽעָשׂ֣וֹת כֵּ֔ן וַ⁠תִּנָּתֵ֥ן דָּ֖ת בְּ⁠שׁוּשָׁ֑ן וְ⁠אֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן תָּלֽוּ׃","wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ lĕ⁠héֽʻáş֣̂wòţ ké̇֔n wa⁠ţi̇ná̇ţé֥n dá֖̇ţ bĕ̇⁠ş̌ẇşá֑̌n wĕ⁠ʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n ţá̇lֽẇ׃"],[9,15,"וַ⁠יִּֽקָּהֲל֞וּ היהודיים אֲשֶׁר־בְּ⁠שׁוּשָׁ֗ן גַּ֠ם בְּ⁠י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר וַ⁠יַּֽהַרְג֣וּ בְ⁠שׁוּשָׁ֔ן שְׁלֹ֥שׁ מֵא֖וֹת אִ֑ישׁ וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","wa⁠yiֽ̇qá̇hàl֞ẇ hyhwdyym ʼàşěr-bĕ̇⁠ş̌ẇşá̌֗n gȧ֠m bĕ̇⁠y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r wa⁠ẏֽaharĕg֣ẇ bĕ⁠ş̌ẇşá̌֔n şĕ̌lò֥ş̌ méʼ֖wòţ ʼi֑yş̌ ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,16,"וּ⁠שְׁאָ֣ר הַ⁠יְּהוּדִ֡ים אֲשֶׁר֩ בִּ⁠מְדִינ֨וֹת הַ⁠מֶּ֜לֶךְ נִקְהֲל֣וּ ׀ וְ⁠עָמֹ֣ד עַל־נַפְשָׁ֗⁠ם וְ⁠נ֨וֹחַ֙ מֵ⁠אֹ֣יְבֵי⁠הֶ֔ם וְ⁠הָרֹג֙ בְּ⁠שֹׂ֣נְאֵי⁠הֶ֔ם חֲמִשָּׁ֥ה וְ⁠שִׁבְעִ֖ים אָ֑לֶף וּ⁠בַ֨⁠בִּזָּ֔ה לֹ֥א שָֽׁלְח֖וּ אֶת־יָדָֽ⁠ם׃","ẇ⁠şĕ̌ʼá֣r ha⁠yĕ̇hẇdi֡ym ʼàşěr֩ bi̇⁠mĕdiyn֨wòţ ha⁠mė֜lekĕ niqĕhàl֣ẇ ׀ wĕ⁠ʻámò֣d ʻal-napĕşá̌֗⁠m wĕ⁠n֨wòẖa֙ mé⁠ʼò֣yĕbéy⁠he֔m wĕ⁠háròg֙ bĕ̇⁠şò֣̂nĕʼéy⁠he֔m ẖàmişá֥̇̌h wĕ⁠şǐbĕʻi֖ym ʼá֑lep ẇ⁠ba֨⁠bi̇zá̇֔h lò֥ʼ şáֽ̌lĕẖ֖ẇ ʼeţ-yádáֽ⁠m׃"],[9,17,"בְּ⁠יוֹם־שְׁלֹשָׁ֥ה עָשָׂ֖ר לְ⁠חֹ֣דֶשׁ אֲדָ֑ר וְ⁠נ֗וֹחַ בְּ⁠אַרְבָּעָ֤ה עָשָׂר֙ בּ֔⁠וֹ וְ⁠עָשֹׂ֣ה אֹת֔⁠וֹ י֖וֹם מִשְׁתֶּ֥ה וְ⁠שִׂמְחָֽה׃","bĕ̇⁠ywòm-şĕ̌lòşá֥̌h ʻáşá֖̂r lĕ⁠ẖò֣deş̌ ʼàdá֑r wĕ⁠n֗wòẖa bĕ̇⁠ʼarĕbá̇ʻá֤h ʻáşá̂r֙ ḃ֔⁠wò wĕ⁠ʻáşò֣̂h ʼòţ֔⁠wò y֖wòm mişĕ̌ţė֥h wĕ⁠şîmĕẖáֽh׃"],[9,18,"והיהודיים אֲשֶׁר־בְּ⁠שׁוּשָׁ֗ן נִקְהֲלוּ֙ בִּ⁠שְׁלֹשָׁ֤ה עָשָׂר֙ בּ֔⁠וֹ וּ⁠בְ⁠אַרְבָּעָ֥ה עָשָׂ֖ר בּ֑⁠וֹ וְ⁠נ֗וֹחַ בַּ⁠חֲמִשָּׁ֤ה עָשָׂר֙ בּ֔⁠וֹ וְ⁠עָשֹׂ֣ה אֹת֔⁠וֹ י֖וֹם מִשְׁתֶּ֥ה וְ⁠שִׂמְחָֽה׃","whyhwdyym ʼàşěr-bĕ̇⁠ş̌ẇşá̌֗n niqĕhàlẇ֙ bi̇⁠şĕ̌lòşá֤̌h ʻáşá̂r֙ ḃ֔⁠wò ẇ⁠bĕ⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r ḃ֑⁠wò wĕ⁠n֗wòẖa bȧ⁠ẖàmişá֤̇̌h ʻáşá̂r֙ ḃ֔⁠wò wĕ⁠ʻáşò֣̂h ʼòţ֔⁠wò y֖wòm mişĕ̌ţė֥h wĕ⁠şîmĕẖáֽh׃"],[9,19,"עַל־כֵּ֞ן הַ⁠יְּהוּדִ֣ים ה⁠פרוזים הַ⁠יֹּשְׁבִים֮ בְּ⁠עָרֵ֣י הַ⁠פְּרָזוֹת֒ עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר שִׂמְחָ֥ה וּ⁠מִשְׁתֶּ֖ה וְ⁠י֣וֹם ט֑וֹב וּ⁠מִשְׁל֥וֹחַ מָנ֖וֹת אִ֥ישׁ לְ⁠רֵעֵֽ⁠הוּ׃פ","ʻal-ké̇֞n ha⁠yĕ̇hẇdi֣ym h⁠prwzym ha⁠yò̇şĕ̌biym֮ bĕ̇⁠ʻáré֣y ha⁠pĕ̇rázwòţ֒ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r şîmĕẖá֥h ẇ⁠mişĕ̌ţė֖h wĕ⁠y֣wòm t֑wòb ẇ⁠mişĕ̌l֥wòẖa mán֖wòţ ʼi֥yş̌ lĕ⁠réʻéֽ⁠hẇ׃p"],[9,20,"וַ⁠יִּכְתֹּ֣ב מָרְדֳּכַ֔י אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַ⁠יְּהוּדִ֗ים אֲשֶׁר֙ בְּ⁠כָל־מְדִינוֹת֙ הַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ הַ⁠קְּרוֹבִ֖ים וְ⁠הָ⁠רְחוֹקִֽים׃","wa⁠yi̇kĕţò֣̇b márĕdȯka֔y ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-ha⁠yĕ̇hẇdi֗ym ʼàşěr֙ bĕ̇⁠kál-mĕdiynwòţ֙ ha⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ ha⁠qĕ̇rwòbi֖ym wĕ⁠há⁠rĕẖwòqiֽym׃"],[9,21,"לְ⁠קַיֵּם֮ עֲלֵי⁠הֶם֒ לִ⁠הְי֣וֹת עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְ⁠חֹ֣דֶשׁ אֲדָ֔ר וְ⁠אֵ֛ת יוֹם־חֲמִשָּׁ֥ה עָשָׂ֖ר בּ֑⁠וֹ בְּ⁠כָל־שָׁנָ֖ה וְ⁠שָׁנָֽה׃","lĕ⁠qayé̇m֮ ʻàléy⁠hem֒ li⁠hĕy֣wòţ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕ⁠ẖò֣deş̌ ʼàdá֔r wĕ⁠ʼé֛ţ ywòm-ẖàmişá֥̇̌h ʻáşá֖̂r ḃ֑⁠wò bĕ̇⁠kál-şá̌ná֖h wĕ⁠şá̌náֽh׃"],[9,22,"כַּ⁠יָּמִ֗ים אֲשֶׁר־נָ֨חוּ בָ⁠הֶ֤ם הַ⁠יְּהוּדִים֙ מֵ⁠א֣וֹיְבֵי⁠הֶ֔ם וְ⁠הַ⁠חֹ֗דֶשׁ אֲשֶׁר֩ נֶהְפַּ֨ךְ לָ⁠הֶ֤ם מִ⁠יָּגוֹן֙ לְ⁠שִׂמְחָ֔ה וּ⁠מֵ⁠אֵ֖בֶל לְ⁠י֣וֹם ט֑וֹב לַ⁠עֲשׂ֣וֹת אוֹתָ֗⁠ם יְמֵי֙ מִשְׁתֶּ֣ה וְ⁠שִׂמְחָ֔ה וּ⁠מִשְׁל֤וֹחַ מָנוֹת֙ אִ֣ישׁ לְ⁠רֵעֵ֔⁠הוּ וּ⁠מַתָּנ֖וֹת לָֽ⁠אֶבְיוֹנִֽים׃","kȧ⁠yá̇mi֗ym ʼàşěr-ná֨ẖẇ bá⁠he֤m ha⁠yĕ̇hẇdiym֙ mé⁠ʼ֣wòyĕbéy⁠he֔m wĕ⁠ha⁠ẖò֗deş̌ ʼàşěr֩ nehĕpȧ֨kĕ lá⁠he֤m mi⁠yá̇gwòn֙ lĕ⁠şîmĕẖá֔h ẇ⁠mé⁠ʼé֖bel lĕ⁠y֣wòm t֑wòb la⁠ʻàş֣̂wòţ ʼwòţá֗⁠m yĕméy֙ mişĕ̌ţė֣h wĕ⁠şîmĕẖá֔h ẇ⁠mişĕ̌l֤wòẖa mánwòţ֙ ʼi֣yş̌ lĕ⁠réʻé֔⁠hẇ ẇ⁠maţá̇n֖wòţ láֽ⁠ʼebĕywòniֽym׃"],[9,23,"וְ⁠קִבֵּל֙ הַ⁠יְּהוּדִ֔ים אֵ֥ת אֲשֶׁר־הֵחֵ֖לּוּ לַ⁠עֲשׂ֑וֹת וְ⁠אֵ֛ת אֲשֶׁר־כָּתַ֥ב מָרְדֳּכַ֖י אֲלֵי⁠הֶֽם׃","wĕ⁠qibé̇l֙ ha⁠yĕ̇hẇdi֔ym ʼé֥ţ ʼàşěr-héẖé֖l̇ẇ la⁠ʻàş֑̂wòţ wĕ⁠ʼé֛ţ ʼàşěr-ká̇ţa֥b márĕdȯka֖y ʼàléy⁠heֽm׃"],[9,24,"כִּי֩ הָמָ֨ן בֶּֽן־הַמְּדָ֜תָא הָֽ⁠אֲגָגִ֗י צֹרֵר֙ כָּל־הַ⁠יְּהוּדִ֔ים חָשַׁ֥ב עַל־הַ⁠יְּהוּדִ֖ים לְ⁠אַבְּדָ֑⁠ם וְ⁠הִפִּ֥יל פּוּר֙ ה֣וּא הַ⁠גּוֹרָ֔ל לְ⁠הֻמָּ֖⁠ם וּֽ⁠לְ⁠אַבְּדָֽ⁠ם׃","ki̇y֩ hámá֨n bėֽn-hamĕ̇dá֜ţáʼ háֽ⁠ʼàgági֗y ẕòrér֙ ká̇l-ha⁠yĕ̇hẇdi֔ym ẖáşǎ֥b ʻal-ha⁠yĕ̇hẇdi֖ym lĕ⁠ʼabĕ̇dá֑⁠m wĕ⁠hipi֥̇yl ṗẇr֙ h֣ẇʼ ha⁠ġwòrá֔l lĕ⁠humá֖̇⁠m ẇֽ⁠lĕ⁠ʼabĕ̇dáֽ⁠m׃"],[9,25,"וּ⁠בְ⁠בֹאָ⁠הּ֮ לִ⁠פְנֵ֣י הַ⁠מֶּלֶךְ֒ אָמַ֣ר עִם־הַ⁠סֵּ֔פֶר יָשׁ֞וּב מַחֲשַׁבְתּ֧⁠וֹ הָ⁠רָעָ֛ה אֲשֶׁר־חָשַׁ֥ב עַל־הַ⁠יְּהוּדִ֖ים עַל־רֹאשׁ֑⁠וֹ וְ⁠תָל֥וּ אֹת֛⁠וֹ וְ⁠אֶת־בָּנָ֖י⁠ו עַל־הָ⁠עֵֽץ׃","ẇ⁠bĕ⁠bòʼá⁠ḣ֮ li⁠pĕné֣y ha⁠mėlekĕ֒ ʼáma֣r ʻim-ha⁠sé̇֔per yáş̌֞ẇb maẖàşǎbĕţ֧̇⁠wò há⁠ráʻá֛h ʼàşěr-ẖáşǎ֥b ʻal-ha⁠yĕ̇hẇdi֖ym ʻal-ròʼş֑̌⁠wò wĕ⁠ţál֥ẇ ʼòţ֛⁠wò wĕ⁠ʼeţ-bá̇ná֖y⁠w ʻal-há⁠ʻéֽẕ׃"],[9,26,"עַל־כֵּ֡ן קָֽרְאוּ֩ לַ⁠יָּמִ֨ים הָ⁠אֵ֤לֶּה פוּרִים֙ עַל־שֵׁ֣ם הַ⁠פּ֔וּר עַל־כֵּ֕ן עַל־כָּל־דִּבְרֵ֖י הָ⁠אִגֶּ֣רֶת הַ⁠זֹּ֑את וּ⁠מָֽה־רָא֣וּ עַל־כָּ֔כָה וּ⁠מָ֥ה הִגִּ֖יעַ אֲלֵי⁠הֶֽם׃","ʻal-ké̇֡n qáֽrĕʼẇ֩ la⁠yá̇mi֨ym há⁠ʼé֤lėh pẇriym֙ ʻal-şé֣̌m ha⁠ṗ֔ẇr ʻal-ké̇֕n ʻal-ká̇l-di̇bĕré֖y há⁠ʼigė֣reţ ha⁠zò֑̇ʼţ ẇ⁠máֽh-ráʼ֣ẇ ʻal-ká̇֔káh ẇ⁠má֥h higi֖̇yʻa ʼàléy⁠heֽm׃"],[9,27,"קִיְּמ֣וּ ו⁠קבל הַ⁠יְּהוּדִים֩ ׀ עֲלֵי⁠הֶ֨ם ׀ וְ⁠עַל־זַרְעָ֜⁠ם וְ⁠עַ֨ל כָּל־הַ⁠נִּלְוִ֤ים עֲלֵי⁠הֶם֙ וְ⁠לֹ֣א יַעֲב֔וֹר לִ⁠הְי֣וֹת עֹשִׂ֗ים אֵ֣ת שְׁנֵ֤י הַ⁠יָּמִים֙ הָ⁠אֵ֔לֶּה כִּ⁠כְתָבָ֖⁠ם וְ⁠כִ⁠זְמַנָּ֑⁠ם בְּ⁠כָל־שָׁנָ֖ה וְ⁠שָׁנָֽה׃","qiyĕ̇m֣ẇ w⁠qbl ha⁠yĕ̇hẇdiym֩ ׀ ʻàléy⁠he֨m ׀ wĕ⁠ʻal-zarĕʻá֜⁠m wĕ⁠ʻa֨l ká̇l-ha⁠ni̇lĕwi֤ym ʻàléy⁠hem֙ wĕ⁠lò֣ʼ yaʻàb֔wòr li⁠hĕy֣wòţ ʻòşî֗ym ʼé֣ţ şĕ̌né֤y ha⁠yá̇miym֙ há⁠ʼé֔lėh ki̇⁠kĕţábá֖⁠m wĕ⁠ki⁠zĕmaná֑̇⁠m bĕ̇⁠kál-şá̌ná֖h wĕ⁠şá̌náֽh׃"],[9,28,"וְ⁠הַ⁠יָּמִ֣ים הָ֠⁠אֵלֶּה נִזְכָּרִ֨ים וְ⁠נַעֲשִׂ֜ים בְּ⁠כָל־דּ֣וֹר וָ⁠ד֗וֹר מִשְׁפָּחָה֙ וּ⁠מִשְׁפָּחָ֔ה מְדִינָ֥ה וּ⁠מְדִינָ֖ה וְ⁠עִ֣יר וָ⁠עִ֑יר וִ⁠ימֵ֞י הַ⁠פּוּרִ֣ים הָ⁠אֵ֗לֶּה לֹ֤א יַֽעַבְרוּ֙ מִ⁠תּ֣וֹךְ הַ⁠יְּהוּדִ֔ים וְ⁠זִכְרָ֖⁠ם לֹא־יָס֥וּף מִ⁠זַּרְעָֽ⁠ם׃ס","wĕ⁠ha⁠yá̇mi֣ym há֠⁠ʼélėh nizĕká̇ri֨ym wĕ⁠naʻàşî֜ym bĕ̇⁠kál-ḋ֣wòr wá⁠d֗wòr mişĕ̌pá̇ẖáh֙ ẇ⁠mişĕ̌pá̇ẖá֔h mĕdiyná֥h ẇ⁠mĕdiyná֖h wĕ⁠ʻi֣yr wá⁠ʻi֑yr wi⁠ymé֞y ha⁠ṗẇri֣ym há⁠ʼé֗lėh lò֤ʼ yaֽʻabĕrẇ֙ mi⁠ţ֣̇wòkĕ ha⁠yĕ̇hẇdi֔ym wĕ⁠zikĕrá֖⁠m lòʼ-yás֥ẇp mi⁠zȧrĕʻáֽ⁠m׃s"],[9,29,"וַ֠⁠תִּכְתֹּב אֶסְתֵּ֨ר הַ⁠מַּלְכָּ֧ה בַת־אֲבִיחַ֛יִל וּ⁠מָרְדֳּכַ֥י הַ⁠יְּהוּדִ֖י אֶת־כָּל־תֹּ֑קֶף לְ⁠קַיֵּ֗ם אֵ֣ת אִגֶּ֧רֶת הַ⁠פּוּרִ֛ים הַ⁠זֹּ֖את הַ⁠שֵּׁנִֽית׃","wa֠⁠ţi̇kĕţò̇b ʼesĕţé̇֨r ha⁠mȧlĕká֧̇h baţ-ʼàbiyẖa֛yil ẇ⁠márĕdȯka֥y ha⁠yĕ̇hẇdi֖y ʼeţ-ká̇l-ţò֑̇qep lĕ⁠qayé̇֗m ʼé֣ţ ʼigė֧reţ ha⁠ṗẇri֛ym ha⁠zò֖̇ʼţ ha⁠şé̇̌niֽyţ׃"],[9,30,"וַ⁠יִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַ⁠יְּהוּדִ֗ים אֶל־שֶׁ֨בַע וְ⁠עֶשְׂרִ֤ים וּ⁠מֵאָה֙ מְדִינָ֔ה מַלְכ֖וּת אֲחַשְׁוֵר֑וֹשׁ דִּבְרֵ֥י שָׁל֖וֹם וֶ⁠אֱמֶֽת׃","wa⁠yi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-ha⁠yĕ̇hẇdi֗ym ʼel-şě֨baʻ wĕ⁠ʻeşĕ̂ri֤ym ẇ⁠méʼáh֙ mĕdiyná֔h malĕk֖ẇţ ʼàẖaşĕ̌wér֑wòş̌ di̇bĕré֥y şá̌l֖wòm we⁠ʼèmeֽţ׃"],[9,31,"לְ⁠קַיֵּ֡ם אֵת־יְמֵי֩ הַ⁠פֻּרִ֨ים הָ⁠אֵ֜לֶּה בִּ⁠זְמַנֵּי⁠הֶ֗ם כַּ⁠אֲשֶׁר֩ קִיַּ֨ם עֲלֵי⁠הֶ֜ם מָרְדֳּכַ֤י הַ⁠יְּהוּדִי֙ וְ⁠אֶסְתֵּ֣ר הַ⁠מַּלְכָּ֔ה וְ⁠כַ⁠אֲשֶׁ֛ר קִיְּמ֥וּ עַל־נַפְשָׁ֖⁠ם וְ⁠עַל־זַרְעָ֑⁠ם דִּבְרֵ֥י הַ⁠צֹּמ֖וֹת וְ⁠זַעֲקָתָֽ⁠ם׃","lĕ⁠qayé̇֡m ʼéţ-yĕméy֩ ha⁠pu̇ri֨ym há⁠ʼé֜lėh bi̇⁠zĕmané̇y⁠he֗m kȧ⁠ʼàşěr֩ qiyȧ֨m ʻàléy⁠he֜m márĕdȯka֤y ha⁠yĕ̇hẇdiy֙ wĕ⁠ʼesĕţé֣̇r ha⁠mȧlĕká̇֔h wĕ⁠ka⁠ʼàşě֛r qiyĕ̇m֥ẇ ʻal-napĕşá֖̌⁠m wĕ⁠ʻal-zarĕʻá֑⁠m di̇bĕré֥y ha⁠ẕò̇m֖wòţ wĕ⁠zaʻàqáţáֽ⁠m׃"],[9,32,"וּ⁠מַאֲמַ֣ר אֶסְתֵּ֔ר קִיַּ֕ם דִּבְרֵ֥י הַ⁠פֻּרִ֖ים הָ⁠אֵ֑לֶּה וְ⁠נִכְתָּ֖ב בַּ⁠סֵּֽפֶר׃פ","ẇ⁠maʼàma֣r ʼesĕţé̇֔r qiyȧ֕m di̇bĕré֥y ha⁠pu̇ri֖ym há⁠ʼé֑lėh wĕ⁠nikĕţá֖̇b bȧ⁠séֽ̇per׃p"],[10,1,"וַ⁠יָּשֶׂם֩ הַ⁠מֶּ֨לֶךְ אחשרש ׀ מַ֛ס עַל־הָ⁠אָ֖רֶץ וְ⁠אִיֵּ֥י הַ⁠יָּֽם׃","wa⁠yá̇şêm֩ ha⁠mė֨lekĕ ʼẖşrş ׀ ma֛s ʻal-há⁠ʼá֖reẕ wĕ⁠ʼiyé֥̇y ha⁠yáֽ̇m׃"],[10,2,"וְ⁠כָל־מַעֲשֵׂ֤ה תָקְפּ⁠וֹ֙ וּ⁠גְב֣וּרָת֔⁠וֹ וּ⁠פָרָשַׁת֙ גְּדֻלַּ֣ת מָרְדֳּכַ֔י אֲשֶׁ֥ר גִּדְּל֖⁠וֹ הַ⁠מֶּ֑לֶךְ הֲ⁠לוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֨פֶר֙ דִּבְרֵ֣י הַ⁠יָּמִ֔ים לְ⁠מַלְכֵ֖י מָדַ֥י וּ⁠פָרָֽס׃","wĕ⁠kál-maʻàşé֤̂h ţáqĕṗ⁠wò֙ ẇ⁠gĕb֣ẇráţ֔⁠wò ẇ⁠páráşǎţ֙ gĕ̇dulȧ֣ţ márĕdȯka֔y ʼàşě֥r gi̇dĕ̇l֖⁠wò ha⁠mė֑lekĕ hà⁠lwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֨per֙ di̇bĕré֣y ha⁠yá̇mi֔ym lĕ⁠malĕké֖y máda֥y ẇ⁠páráֽs׃"],[10,3,"כִּ֣י ׀ מָרְדֳּכַ֣י הַ⁠יְּהוּדִ֗י מִשְׁנֶה֙ לַ⁠מֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וְ⁠גָדוֹל֙ לַ⁠יְּהוּדִ֔ים וְ⁠רָצ֖וּי לְ⁠רֹ֣ב אֶחָ֑י⁠ו דֹּרֵ֥שׁ טוֹב֙ לְ⁠עַמּ֔⁠וֹ וְ⁠דֹבֵ֥ר שָׁל֖וֹם לְ⁠כָל־זַרְעֽ⁠וֹ׃","ki֣̇y ׀ márĕdȯka֣y ha⁠yĕ̇hẇdi֗y mişĕ̌neh֙ la⁠mė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wĕ⁠gádwòl֙ la⁠yĕ̇hẇdi֔ym wĕ⁠ráẕ֖ẇy lĕ⁠rò֣b ʼeẖá֑y⁠w dò̇ré֥ş̌ twòb֙ lĕ⁠ʻaṁ֔⁠wò wĕ⁠dòbé֥r şá̌l֖wòm lĕ⁠kál-zarĕʻֽ⁠wò׃"]],"fra-lsg1910":[[1,1,"C'était du temps d'Assuérus, de cet Assuérus qui régnait depuis l'Inde jusqu'en Éthiopie sur cent vingt-sept provinces;","C'était du temps d'Assuérus, de cet Assuérus qui régnait depuis l'Inde jusqu'en Éthiopie sur cent vingt-sept provinces;"],[1,2,"et le roi Assuérus était alors assis sur son trône royal à Suse, dans la capitale.","et le roi Assuérus était alors assis sur son trône royal à Suse, dans la capitale."],[1,3,"La troisième année de son règne, il fit un festin à tous ses princes et à ses serviteurs; les commandants de l'armée des Perses et des Mèdes, les grands et les chefs des provinces furent réunis en sa présence.","La troisième année de son règne, il fit un festin à tous ses princes et à ses serviteurs; les commandants de l'armée des Perses et des Mèdes, les grands et les chefs des provinces furent réunis en sa présence."],[1,4,"Il montra la splendide richesse de son royaume et l'éclatante magnificence de sa grandeur pendant nombre de jours, pendant cent quatre-vingts jours.","Il montra la splendide richesse de son royaume et l'éclatante magnificence de sa grandeur pendant nombre de jours, pendant cent quatre-vingts jours."],[1,5,"Lorsque ces jours furent écoulés, le roi fit pour tout le peuple qui se trouvait à Suse, la capitale, depuis le plus grand jusqu'au plus petit, un festin qui dura sept jours, dans la cour du jardin de la maison royale.","Lorsque ces jours furent écoulés, le roi fit pour tout le peuple qui se trouvait à Suse, la capitale, depuis le plus grand jusqu'au plus petit, un festin qui dura sept jours, dans la cour du jardin de la maison royale."],[1,6,"Des tentures blanches, vertes et bleues, étaient attachées par des cordons de byssus et de pourpre à des anneaux d'argent et à des colonnes de marbre. Des lits d'or et d'argent reposaient sur un pavé de porphyre, de marbre, de nacre et de pierres noires.","Des tentures blanches, vertes et bleues, étaient attachées par des cordons de byssus et de pourpre à des anneaux d'argent et à des colonnes de marbre. Des lits d'or et d'argent reposaient sur un pavé de porphyre, de marbre, de nacre et de pierres noires."],[1,7,"On servait à boire dans des vases d'or, de différentes espèces, et il y avait abondance de vin royal, grâce à la libéralité du roi.","On servait à boire dans des vases d'or, de différentes espèces, et il y avait abondance de vin royal, grâce à la libéralité du roi."],[1,8,"Mais on ne forçait personne à boire, car le roi avait ordonné à tous les gens de sa maison de se conformer à la volonté de chacun.","Mais on ne forçait personne à boire, car le roi avait ordonné à tous les gens de sa maison de se conformer à la volonté de chacun."],[1,9,"La reine Vasthi fit aussi un festin pour les femmes dans la maison royale du roi Assuérus.","La reine Vasthi fit aussi un festin pour les femmes dans la maison royale du roi Assuérus."],[1,10,"Le septième jour, comme le coeur du roi était réjoui par le vin, il ordonna à Mehuman, Biztha, Harbona, Bigtha, Abagtha, Zéthar et Carcas, les sept eunuques qui servaient devant le roi Assuérus,","Le septième jour, comme le coeur du roi était réjoui par le vin, il ordonna à Mehuman, Biztha, Harbona, Bigtha, Abagtha, Zéthar et Carcas, les sept eunuques qui servaient devant le roi Assuérus,"],[1,11,"d'amener en sa présence la reine Vasthi, avec la couronne royale, pour montrer sa beauté aux peuples et aux grands, car elle était belle de figure.","d'amener en sa présence la reine Vasthi, avec la couronne royale, pour montrer sa beauté aux peuples et aux grands, car elle était belle de figure."],[1,12,"Mais la reine Vasthi refusa de venir, quand elle reçut par les eunuques l'ordre du roi. Et le roi fut très irrité, il fut enflammé de colère.","Mais la reine Vasthi refusa de venir, quand elle reçut par les eunuques l'ordre du roi. Et le roi fut très irrité, il fut enflammé de colère."],[1,13,"Alors le roi s'adressa aux sages qui avaient la connaissance des temps. Car ainsi se traitaient les affaires du roi, devant tous ceux qui connaissaient les lois et le droit.","Alors le roi s'adressa aux sages qui avaient la connaissance des temps. Car ainsi se traitaient les affaires du roi, devant tous ceux qui connaissaient les lois et le droit."],[1,14,"Il avait auprès de lui Carschena, Schéthar, Admatha, Tarsis, Mérès, Marsena, Memucan, sept princes de Perse et de Médie, qui voyaient la face du roi et qui occupaient le premier rang dans le royaume.","Il avait auprès de lui Carschena, Schéthar, Admatha, Tarsis, Mérès, Marsena, Memucan, sept princes de Perse et de Médie, qui voyaient la face du roi et qui occupaient le premier rang dans le royaume."],[1,15,"Quelle loi, dit-il, faut-il appliquer à la reine Vasthi, pour n'avoir point exécuté ce que le roi Assuérus lui a ordonné par les eunuques?","Quelle loi, dit-il, faut-il appliquer à la reine Vasthi, pour n'avoir point exécuté ce que le roi Assuérus lui a ordonné par les eunuques?"],[1,16,"Memucan répondit devant le roi et les princes: Ce n'est pas seulement à l'égard du roi que la reine Vasthi a mal agi; c'est aussi envers tous les princes et tous les peuples qui sont dans toutes les provinces du roi Assuérus.","Memucan répondit devant le roi et les princes: Ce n'est pas seulement à l'égard du roi que la reine Vasthi a mal agi; c'est aussi envers tous les princes et tous les peuples qui sont dans toutes les provinces du roi Assuérus."],[1,17,"Car l'action de la reine parviendra à la connaissance de toutes les femmes, et les portera à mépriser leurs maris; elles diront: Le roi Assuérus avait ordonné qu'on amenât en sa présence la reine Vasthi, et elle n'y est pas allée.","Car l'action de la reine parviendra à la connaissance de toutes les femmes, et les portera à mépriser leurs maris; elles diront: Le roi Assuérus avait ordonné qu'on amenât en sa présence la reine Vasthi, et elle n'y est pas allée."],[1,18,"Et dès ce jour les princesses de Perse et de Médie qui auront appris l'action de la reine la rapporteront à tous les chefs du roi; de là beaucoup de mépris et de colère.","Et dès ce jour les princesses de Perse et de Médie qui auront appris l'action de la reine la rapporteront à tous les chefs du roi; de là beaucoup de mépris et de colère."],[1,19,"Si le roi le trouve bon, qu'on publie de sa part et qu'on inscrive parmi les lois des Perses et des Mèdes, avec défense de la transgresser, une ordonnance royale d'après laquelle Vasthi ne paraîtra plus devant le roi Assuérus et le roi donnera la dignité de reine à une autre qui soit meilleure qu'elle.","Si le roi le trouve bon, qu'on publie de sa part et qu'on inscrive parmi les lois des Perses et des Mèdes, avec défense de la transgresser, une ordonnance royale d'après laquelle Vasthi ne paraîtra plus devant le roi Assuérus et le roi donnera la dignité de reine à une autre qui soit meilleure qu'elle."],[1,20,"L'édit du roi sera connu dans tout son royaume, quelque grand qu'il soit, et toutes les femmes rendront honneur à leurs maris, depuis le plus grand jusqu'au plus petit.","L'édit du roi sera connu dans tout son royaume, quelque grand qu'il soit, et toutes les femmes rendront honneur à leurs maris, depuis le plus grand jusqu'au plus petit."],[1,21,"Cet avis fut approuvé du roi et des princes, et le roi agit d'après la parole de Memucan.","Cet avis fut approuvé du roi et des princes, et le roi agit d'après la parole de Memucan."],[1,22,"Il envoya des lettres à toutes les provinces du royaume, à chaque province selon son écriture et à chaque peuple selon sa langue; elles portaient que tout homme devait être le maître dans sa maison, et qu'il parlerait la langue de son peuple.","Il envoya des lettres à toutes les provinces du royaume, à chaque province selon son écriture et à chaque peuple selon sa langue; elles portaient que tout homme devait être le maître dans sa maison, et qu'il parlerait la langue de son peuple."],[2,1,"Après ces choses, lorsque la colère du roi Assuérus se fut calmée, il pensa à Vasthi, à ce qu'elle avait fait, et à la décision qui avait été prise à son sujet.","Après ces choses, lorsque la colère du roi Assuérus se fut calmée, il pensa à Vasthi, à ce qu'elle avait fait, et à la décision qui avait été prise à son sujet."],[2,2,"Alors ceux qui servaient le roi dirent: Qu'on cherche pour le roi des jeunes filles, vierges et belles de figure;","Alors ceux qui servaient le roi dirent: Qu'on cherche pour le roi des jeunes filles, vierges et belles de figure;"],[2,3,"que le roi établisse dans toutes les provinces de son royaume des commissaires chargés de rassembler toutes les jeunes filles, vierges et belles de figure, à Suse, la capitale, dans la maison des femmes, sous la surveillance d'Hégué, eunuque du roi et gardien des femmes, qui leur donnera les choses nécessaires pour leur toilette;","que le roi établisse dans toutes les provinces de son royaume des commissaires chargés de rassembler toutes les jeunes filles, vierges et belles de figure, à Suse, la capitale, dans la maison des femmes, sous la surveillance d'Hégué, eunuque du roi et gardien des femmes, qui leur donnera les choses nécessaires pour leur toilette;"],[2,4,"et que la jeune fille qui plaira au roi devienne reine à la place de Vasthi. Cet avis eut l'approbation du roi, et il fit ainsi.","et que la jeune fille qui plaira au roi devienne reine à la place de Vasthi. Cet avis eut l'approbation du roi, et il fit ainsi."],[2,5,"Il y avait dans Suse, la capitale, un Juif nommé Mardochée, fils de Jaïr, fils de Schimeï, fils de Kis, homme de Benjamin,","Il y avait dans Suse, la capitale, un Juif nommé Mardochée, fils de Jaïr, fils de Schimeï, fils de Kis, homme de Benjamin,"],[2,6,"qui avait été emmené de Jérusalem parmi les captifs déportés avec Jeconia, roi de Juda, par Nebucadnetsar, roi de Babylone.","qui avait été emmené de Jérusalem parmi les captifs déportés avec Jeconia, roi de Juda, par Nebucadnetsar, roi de Babylone."],[2,7,"Il élevait Hadassa, qui est Esther, fille de son oncle; car elle n'avait ni père ni mère. La jeune fille était belle de taille et belle de figure. À la mort de son père et de sa mère, Mardochée l'avait adoptée pour fille.","Il élevait Hadassa, qui est Esther, fille de son oncle; car elle n'avait ni père ni mère. La jeune fille était belle de taille et belle de figure. À la mort de son père et de sa mère, Mardochée l'avait adoptée pour fille."],[2,8,"Lorsqu'on eut publié l'ordre du roi et son édit, et qu'un grand nombre de jeunes filles furent rassemblées à Suse, la capitale, sous la surveillance d'Hégaï, Esther fut aussi prise et conduite dans la maison du roi, sous la surveillance d'Hégaï, gardien des femmes.","Lorsqu'on eut publié l'ordre du roi et son édit, et qu'un grand nombre de jeunes filles furent rassemblées à Suse, la capitale, sous la surveillance d'Hégaï, Esther fut aussi prise et conduite dans la maison du roi, sous la surveillance d'Hégaï, gardien des femmes."],[2,9,"La jeune fille lui plut, et trouva grâce devant lui; il s'empressa de lui fournir les choses nécessaires pour sa toilette et pour sa subsistance, lui donna sept jeunes filles choisies dans la maison du roi, et la plaça avec ses jeunes filles dans le meilleur appartement de la maison des femmes.","La jeune fille lui plut, et trouva grâce devant lui; il s'empressa de lui fournir les choses nécessaires pour sa toilette et pour sa subsistance, lui donna sept jeunes filles choisies dans la maison du roi, et la plaça avec ses jeunes filles dans le meilleur appartement de la maison des femmes."],[2,10,"Esther ne fit connaître ni son peuple ni sa naissance, car Mardochée lui avait défendu d'en parler.","Esther ne fit connaître ni son peuple ni sa naissance, car Mardochée lui avait défendu d'en parler."],[2,11,"Et chaque jour Mardochée allait et venait devant la cour de la maison des femmes, pour savoir comment se portait Esther et comment on la traitait.","Et chaque jour Mardochée allait et venait devant la cour de la maison des femmes, pour savoir comment se portait Esther et comment on la traitait."],[2,12,"Chaque jeune fille allait à son tour vers le roi Assuérus, après avoir employé douze mois à s'acquitter de ce qui était prescrit aux femmes; pendant ce temps, elles prenaient soin de leur toilette, six mois avec de l'huile de myrrhe, et six mois avec des aromates et des parfums en usage parmi les femmes.","Chaque jeune fille allait à son tour vers le roi Assuérus, après avoir employé douze mois à s'acquitter de ce qui était prescrit aux femmes; pendant ce temps, elles prenaient soin de leur toilette, six mois avec de l'huile de myrrhe, et six mois avec des aromates et des parfums en usage parmi les femmes."],[2,13,"C'est ainsi que chaque jeune fille allait vers le roi; et, quand elle passait de la maison des femmes dans la maison du roi, on lui laissait prendre avec elle tout ce qu'elle voulait.","C'est ainsi que chaque jeune fille allait vers le roi; et, quand elle passait de la maison des femmes dans la maison du roi, on lui laissait prendre avec elle tout ce qu'elle voulait."],[2,14,"Elle y allait le soir; et le lendemain matin elle passait dans la seconde maison des femmes, sous la surveillance de Schaaschgaz, eunuque du roi et gardien des concubines. Elle ne retournait plus vers le roi, à moins que le roi n'en eût le désir et qu'elle ne fût appelée par son nom.","Elle y allait le soir; et le lendemain matin elle passait dans la seconde maison des femmes, sous la surveillance de Schaaschgaz, eunuque du roi et gardien des concubines. Elle ne retournait plus vers le roi, à moins que le roi n'en eût le désir et qu'elle ne fût appelée par son nom."],[2,15,"Lorsque son tour d'aller vers le roi fut arrivé, Esther, fille d'Abichaïl, oncle de Mardochée qui l'avait adoptée pour fille, ne demanda que ce qui fut désigné par Hégaï, eunuque du roi et gardien des femmes. Esther trouvait grâce aux yeux de tous ceux qui la voyaient.","Lorsque son tour d'aller vers le roi fut arrivé, Esther, fille d'Abichaïl, oncle de Mardochée qui l'avait adoptée pour fille, ne demanda que ce qui fut désigné par Hégaï, eunuque du roi et gardien des femmes. Esther trouvait grâce aux yeux de tous ceux qui la voyaient."],[2,16,"Esther fut conduite auprès du roi Assuérus, dans sa maison royale, le dixième mois, qui est le mois de Tébeth, la septième année de son règne.","Esther fut conduite auprès du roi Assuérus, dans sa maison royale, le dixième mois, qui est le mois de Tébeth, la septième année de son règne."],[2,17,"Le roi aima Esther plus que toutes les autres femmes, et elle obtint grâce et faveur devant lui plus que toutes les autres jeunes filles. Il mit la couronne royale sur sa tête, et la fit reine à la place de Vasthi.","Le roi aima Esther plus que toutes les autres femmes, et elle obtint grâce et faveur devant lui plus que toutes les autres jeunes filles. Il mit la couronne royale sur sa tête, et la fit reine à la place de Vasthi."],[2,18,"Le roi donna un grand festin à tous ses princes et à ses serviteurs, un festin en l'honneur d'Esther; il accorda du repos aux provinces, et fit des présents avec une libéralité royale.","Le roi donna un grand festin à tous ses princes et à ses serviteurs, un festin en l'honneur d'Esther; il accorda du repos aux provinces, et fit des présents avec une libéralité royale."],[2,19,"La seconde fois qu'on assembla les jeunes filles, Mardochée était assis à la porte du roi.","La seconde fois qu'on assembla les jeunes filles, Mardochée était assis à la porte du roi."],[2,20,"Esther n'avait fait connaître ni sa naissance ni son peuple, car Mardochée le lui avait défendu, et elle suivait les ordres de Mardochée aussi fidèlement qu'à l'époque où elle était sous sa tutelle.","Esther n'avait fait connaître ni sa naissance ni son peuple, car Mardochée le lui avait défendu, et elle suivait les ordres de Mardochée aussi fidèlement qu'à l'époque où elle était sous sa tutelle."],[2,21,"Dans ce même temps, comme Mardochée était assis à la porte du roi, Bigthan et Théresch, deux eunuques du roi, gardes du seuil, cédèrent à un mouvement d'irritation et voulurent porter la main sur le roi Assuérus.","Dans ce même temps, comme Mardochée était assis à la porte du roi, Bigthan et Théresch, deux eunuques du roi, gardes du seuil, cédèrent à un mouvement d'irritation et voulurent porter la main sur le roi Assuérus."],[2,22,"Mardochée eut connaissance de la chose et en informa la reine Esther, qui la redit au roi de la part de Mardochée.","Mardochée eut connaissance de la chose et en informa la reine Esther, qui la redit au roi de la part de Mardochée."],[2,23,"Le fait ayant été vérifié et trouvé exact, les deux eunuques furent pendus à un bois. Et cela fut écrit dans le livre des Chroniques en présence du roi.","Le fait ayant été vérifié et trouvé exact, les deux eunuques furent pendus à un bois. Et cela fut écrit dans le livre des Chroniques en présence du roi."],[3,1,"Après ces choses, le roi Assuérus fit monter au pouvoir Haman, fils d'Hammedatha, l'Agaguite; il l'éleva en dignité et plaça son siège au-dessus de ceux de tous les chefs qui étaient auprès de lui.","Après ces choses, le roi Assuérus fit monter au pouvoir Haman, fils d'Hammedatha, l'Agaguite; il l'éleva en dignité et plaça son siège au-dessus de ceux de tous les chefs qui étaient auprès de lui."],[3,2,"Tous les serviteurs du roi, qui se tenaient à la porte du roi, fléchissaient le genou et se prosternaient devant Haman, car tel était l'ordre du roi à son égard. Mais Mardochée ne fléchissait point le genou et ne se prosternait point.","Tous les serviteurs du roi, qui se tenaient à la porte du roi, fléchissaient le genou et se prosternaient devant Haman, car tel était l'ordre du roi à son égard. Mais Mardochée ne fléchissait point le genou et ne se prosternait point."],[3,3,"Et les serviteurs du roi, qui se tenaient à la porte du roi, dirent à Mardochée: Pourquoi transgresses-tu l'ordre du roi?","Et les serviteurs du roi, qui se tenaient à la porte du roi, dirent à Mardochée: Pourquoi transgresses-tu l'ordre du roi?"],[3,4,"Comme ils le lui répétaient chaque jour et qu'il ne les écoutait pas, ils en firent rapport à Haman, pour voir si Mardochée persisterait dans sa résolution; car il leur avait dit qu'il était Juif.","Comme ils le lui répétaient chaque jour et qu'il ne les écoutait pas, ils en firent rapport à Haman, pour voir si Mardochée persisterait dans sa résolution; car il leur avait dit qu'il était Juif."],[3,5,"Et Haman vit que Mardochée ne fléchissait point le genou et ne se prosternait point devant lui. Il fut rempli de fureur;","Et Haman vit que Mardochée ne fléchissait point le genou et ne se prosternait point devant lui. Il fut rempli de fureur;"],[3,6,"mais il dédaigna de porter la main sur Mardochée seul, car on lui avait dit de quel peuple était Mardochée, et il voulut détruire le peuple de Mardochée, tous les Juifs qui se trouvaient dans tout le royaume d'Assuérus.","mais il dédaigna de porter la main sur Mardochée seul, car on lui avait dit de quel peuple était Mardochée, et il voulut détruire le peuple de Mardochée, tous les Juifs qui se trouvaient dans tout le royaume d'Assuérus."],[3,7,"Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le pur, c'est-à-dire le sort, devant Haman, pour chaque jour et pour chaque mois, jusqu'au douzième mois, qui est le mois d'Adar.","Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le pur, c'est-à-dire le sort, devant Haman, pour chaque jour et pour chaque mois, jusqu'au douzième mois, qui est le mois d'Adar."],[3,8,"Alors Haman dit au roi Assuérus: Il y a dans toutes les provinces de ton royaume un peuple dispersé et à part parmi les peuples, ayant des lois différentes de celles de tous les peuples et n'observant point les lois du roi. Il n'est pas dans l'intérêt du roi de le laisser en repos.","Alors Haman dit au roi Assuérus: Il y a dans toutes les provinces de ton royaume un peuple dispersé et à part parmi les peuples, ayant des lois différentes de celles de tous les peuples et n'observant point les lois du roi. Il n'est pas dans l'intérêt du roi de le laisser en repos."],[3,9,"Si le roi le trouve bon, qu'on écrive l'ordre de les faire périr; et je pèserai dix mille talents d'argent entre les mains des fonctionnaires, pour qu'on les porte dans le trésor du roi.","Si le roi le trouve bon, qu'on écrive l'ordre de les faire périr; et je pèserai dix mille talents d'argent entre les mains des fonctionnaires, pour qu'on les porte dans le trésor du roi."],[3,10,"Le roi ôta son anneau de la main, et le remit à Haman, fils d'Hammedatha, l'Agaguite, ennemi des Juifs.","Le roi ôta son anneau de la main, et le remit à Haman, fils d'Hammedatha, l'Agaguite, ennemi des Juifs."],[3,11,"Et le roi dit à Haman: L'argent t'est donné, et ce peuple aussi; fais-en ce que tu voudras.","Et le roi dit à Haman: L'argent t'est donné, et ce peuple aussi; fais-en ce que tu voudras."],[3,12,"Les secrétaires du roi furent appelés le treizième jour du premier mois, et l'on écrivit, suivant tout ce qui fut ordonné par Haman, aux satrapes du roi, aux gouverneurs de chaque province et aux chefs de chaque peuple, à chaque province selon son écriture et à chaque peuple selon sa langue. Ce fut au nom du roi Assuérus que l'on écrivit, et on scella avec l'anneau du roi.","Les secrétaires du roi furent appelés le treizième jour du premier mois, et l'on écrivit, suivant tout ce qui fut ordonné par Haman, aux satrapes du roi, aux gouverneurs de chaque province et aux chefs de chaque peuple, à chaque province selon son écriture et à chaque peuple selon sa langue. Ce fut au nom du roi Assuérus que l'on écrivit, et on scella avec l'anneau du roi."],[3,13,"Les lettres furent envoyées par les courriers dans toutes les provinces du roi, pour qu'on détruisît, qu'on tuât et qu'on fît périr tous les Juifs, jeunes et vieux, petits enfants et femmes, en un seul jour, le treizième du douzième mois, qui est le mois d'Adar, et pour que leurs biens fussent livrés au pillage.","Les lettres furent envoyées par les courriers dans toutes les provinces du roi, pour qu'on détruisît, qu'on tuât et qu'on fît périr tous les Juifs, jeunes et vieux, petits enfants et femmes, en un seul jour, le treizième du douzième mois, qui est le mois d'Adar, et pour que leurs biens fussent livrés au pillage."],[3,14,"Ces lettres renfermaient une copie de l'édit qui devait être publié dans chaque province, et invitaient tous les peuples à se tenir prêts pour ce jour-là.","Ces lettres renfermaient une copie de l'édit qui devait être publié dans chaque province, et invitaient tous les peuples à se tenir prêts pour ce jour-là."],[3,15,"Les courriers partirent en toute hâte, d'après l'ordre du roi. L'édit fut aussi publié dans Suse, la capitale; et tandis que le roi et Haman étaient à boire, la ville de Suse était dans la consternation.","Les courriers partirent en toute hâte, d'après l'ordre du roi. L'édit fut aussi publié dans Suse, la capitale; et tandis que le roi et Haman étaient à boire, la ville de Suse était dans la consternation."],[4,1,"Mardochée, ayant appris tout ce qui se passait, déchira ses vêtements, s'enveloppa d'un sac et se couvrit de cendre. Puis il alla au milieu de la ville en poussant avec force des cris amers,","Mardochée, ayant appris tout ce qui se passait, déchira ses vêtements, s'enveloppa d'un sac et se couvrit de cendre. Puis il alla au milieu de la ville en poussant avec force des cris amers,"],[4,2,"et se rendit jusqu'à la porte du roi, dont l'entrée était interdite à toute personne revêtue d'un sac.","et se rendit jusqu'à la porte du roi, dont l'entrée était interdite à toute personne revêtue d'un sac."],[4,3,"Dans chaque province, partout où arrivaient l'ordre du roi et son édit, il y eut une grande désolation parmi les Juifs; ils jeûnaient, pleuraient et se lamentaient, et beaucoup se couchaient sur le sac et la cendre.","Dans chaque province, partout où arrivaient l'ordre du roi et son édit, il y eut une grande désolation parmi les Juifs; ils jeûnaient, pleuraient et se lamentaient, et beaucoup se couchaient sur le sac et la cendre."],[4,4,"Les servantes d'Esther et ses eunuques vinrent lui annoncer cela, et la reine fut très effrayée. Elle envoya des vêtements à Mardochée pour le couvrir et lui faire ôter son sac, mais il ne les accepta pas.","Les servantes d'Esther et ses eunuques vinrent lui annoncer cela, et la reine fut très effrayée. Elle envoya des vêtements à Mardochée pour le couvrir et lui faire ôter son sac, mais il ne les accepta pas."],[4,5,"Alors Esther appela Hathac, l'un des eunuques que le roi avait placés auprès d'elle, et elle le chargea d'aller demander à Mardochée ce que c'était et d'où cela venait.","Alors Esther appela Hathac, l'un des eunuques que le roi avait placés auprès d'elle, et elle le chargea d'aller demander à Mardochée ce que c'était et d'où cela venait."],[4,6,"Hathac se rendit vers Mardochée sur la place de la ville, devant la porte du roi.","Hathac se rendit vers Mardochée sur la place de la ville, devant la porte du roi."],[4,7,"Et Mardochée lui raconta tout ce qui lui était arrivé, et lui indiqua la somme d'argent qu'Haman avait promis de livrer au trésor du roi en retour du massacre des Juifs.","Et Mardochée lui raconta tout ce qui lui était arrivé, et lui indiqua la somme d'argent qu'Haman avait promis de livrer au trésor du roi en retour du massacre des Juifs."],[4,8,"Il lui donna aussi une copie de l'édit publié dans Suse en vue de leur destruction, afin qu'il le montrât à Esther et lui fît tout connaître; et il ordonna qu'Esther se rendît chez le roi pour lui demander grâce et l'implorer en faveur de son peuple.","Il lui donna aussi une copie de l'édit publié dans Suse en vue de leur destruction, afin qu'il le montrât à Esther et lui fît tout connaître; et il ordonna qu'Esther se rendît chez le roi pour lui demander grâce et l'implorer en faveur de son peuple."],[4,9,"Hathac vint rapporter à Esther les paroles de Mardochée.","Hathac vint rapporter à Esther les paroles de Mardochée."],[4,10,"Esther chargea Hathac d'aller dire à Mardochée:","Esther chargea Hathac d'aller dire à Mardochée:"],[4,11,"Tous les serviteurs du roi et le peuple des provinces du roi savent qu'il existe une loi portant peine de mort contre quiconque, homme ou femme, entre chez le roi, dans la cour intérieure, sans avoir été appelé; celui-là seul a la vie sauve, à qui le roi tend le sceptre d'or. Et moi, je n'ai point été appelée auprès du roi depuis trente jours.","Tous les serviteurs du roi et le peuple des provinces du roi savent qu'il existe une loi portant peine de mort contre quiconque, homme ou femme, entre chez le roi, dans la cour intérieure, sans avoir été appelé; celui-là seul a la vie sauve, à qui le roi tend le sceptre d'or. Et moi, je n'ai point été appelée auprès du roi depuis trente jours."],[4,12,"Lorsque les paroles d'Esther eurent été rapportées à Mardochée,","Lorsque les paroles d'Esther eurent été rapportées à Mardochée,"],[4,13,"Mardochée fit répondre à Esther: Ne t'imagine pas que tu échapperas seule d'entre tous les Juifs, parce que tu es dans la maison du roi;","Mardochée fit répondre à Esther: Ne t'imagine pas que tu échapperas seule d'entre tous les Juifs, parce que tu es dans la maison du roi;"],[4,14,"car, si tu te tais maintenant, le secours et la délivrance surgiront d'autre part pour les Juifs, et toi et la maison de ton père vous périrez. Et qui sait si ce n'est pas pour un temps comme celui-ci que tu es parvenue à la royauté?","car, si tu te tais maintenant, le secours et la délivrance surgiront d'autre part pour les Juifs, et toi et la maison de ton père vous périrez. Et qui sait si ce n'est pas pour un temps comme celui-ci que tu es parvenue à la royauté?"],[4,15,"Esther envoya dire à Mardochée:","Esther envoya dire à Mardochée:"],[4,16,"Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, sans manger ni boire pendant trois jours, ni la nuit ni le jour. Moi aussi, je jeûnerai de même avec mes servantes, puis j'entrerai chez le roi, malgré la loi; et si je dois périr, je périrai.","Va, rassemble tous les Juifs qui se trouvent à Suse, et jeûnez pour moi, sans manger ni boire pendant trois jours, ni la nuit ni le jour. Moi aussi, je jeûnerai de même avec mes servantes, puis j'entrerai chez le roi, malgré la loi; et si je dois périr, je périrai."],[4,17,"Mardochée s'en alla, et fit tout ce qu'Esther lui avait ordonné.","Mardochée s'en alla, et fit tout ce qu'Esther lui avait ordonné."],[5,1,"Le troisième jour, Esther mit ses vêtements royaux et se présenta dans la cour intérieure de la maison du roi, devant la maison du roi. Le roi était assis sur son trône royal dans la maison royale, en face de l'entrée de la maison.","Le troisième jour, Esther mit ses vêtements royaux et se présenta dans la cour intérieure de la maison du roi, devant la maison du roi. Le roi était assis sur son trône royal dans la maison royale, en face de l'entrée de la maison."],[5,2,"Lorsque le roi vit la reine Esther debout dans la cour, elle trouva grâce à ses yeux; et le roi tendit à Esther le sceptre d'or qu'il tenait à la main. Esther s'approcha, et toucha le bout du sceptre.","Lorsque le roi vit la reine Esther debout dans la cour, elle trouva grâce à ses yeux; et le roi tendit à Esther le sceptre d'or qu'il tenait à la main. Esther s'approcha, et toucha le bout du sceptre."],[5,3,"Le roi lui dit: Qu'as-tu, reine Esther, et que demandes-tu? Quand ce serait la moitié du royaume, elle te serait donnée.","Le roi lui dit: Qu'as-tu, reine Esther, et que demandes-tu? Quand ce serait la moitié du royaume, elle te serait donnée."],[5,4,"Esther répondit: Si le roi le trouve bon, que le roi vienne aujourd'hui avec Haman au festin que je lui ai préparé.","Esther répondit: Si le roi le trouve bon, que le roi vienne aujourd'hui avec Haman au festin que je lui ai préparé."],[5,5,"Et le roi dit: Allez tout de suite chercher Haman, comme le désire Esther. Le roi se rendit avec Haman au festin qu'avait préparé Esther.","Et le roi dit: Allez tout de suite chercher Haman, comme le désire Esther. Le roi se rendit avec Haman au festin qu'avait préparé Esther."],[5,6,"Et pendant qu'on buvait le vin, le roi dit à Esther: Quelle est ta demande? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l'obtiendras.","Et pendant qu'on buvait le vin, le roi dit à Esther: Quelle est ta demande? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l'obtiendras."],[5,7,"Esther répondit: Voici ce que je demande et ce que je désire.","Esther répondit: Voici ce que je demande et ce que je désire."],[5,8,"Si j'ai trouvé grâce aux yeux du roi, et s'il plaît au roi d'accorder ma demande et de satisfaire mon désir, que le roi vienne avec Haman au festin que je leur préparerai, et demain je donnerai réponse au roi selon son ordre.","Si j'ai trouvé grâce aux yeux du roi, et s'il plaît au roi d'accorder ma demande et de satisfaire mon désir, que le roi vienne avec Haman au festin que je leur préparerai, et demain je donnerai réponse au roi selon son ordre."],[5,9,"Haman sortit ce jour-là, joyeux et le coeur content. Mais lorsqu'il vit, à la porte du roi, Mardochée qui ne se levait ni ne se remuait devant lui, il fut rempli de colère contre Mardochée.","Haman sortit ce jour-là, joyeux et le coeur content. Mais lorsqu'il vit, à la porte du roi, Mardochée qui ne se levait ni ne se remuait devant lui, il fut rempli de colère contre Mardochée."],[5,10,"Il sut néanmoins se contenir, et il alla chez lui. Puis il envoya chercher ses amis et Zéresch, sa femme.","Il sut néanmoins se contenir, et il alla chez lui. Puis il envoya chercher ses amis et Zéresch, sa femme."],[5,11,"Haman leur parla de la magnificence de ses richesses, du nombre de ses fils, de tout ce qu'avait fait le roi pour l'élever en dignité, et du rang qu'il lui avait donné au-dessus des chefs et des serviteurs du roi.","Haman leur parla de la magnificence de ses richesses, du nombre de ses fils, de tout ce qu'avait fait le roi pour l'élever en dignité, et du rang qu'il lui avait donné au-dessus des chefs et des serviteurs du roi."],[5,12,"Et il ajouta: Je suis même le seul que la reine Esther ait admis avec le roi au festin qu'elle a fait, et je suis encore invité pour demain chez elle avec le roi.","Et il ajouta: Je suis même le seul que la reine Esther ait admis avec le roi au festin qu'elle a fait, et je suis encore invité pour demain chez elle avec le roi."],[5,13,"Mais tout cela n'est d'aucun prix pour moi aussi longtemps que je verrai Mardochée, le Juif, assis à la porte du roi.","Mais tout cela n'est d'aucun prix pour moi aussi longtemps que je verrai Mardochée, le Juif, assis à la porte du roi."],[5,14,"Zéresch, sa femme, et tous ses amis lui dirent: Qu'on prépare un bois haut de cinquante coudées, et demain matin demande au roi qu'on y pende Mardochée; puis tu iras joyeux au festin avec le roi. Cet avis plut à Haman, et il fit préparer le bois.","Zéresch, sa femme, et tous ses amis lui dirent: Qu'on prépare un bois haut de cinquante coudées, et demain matin demande au roi qu'on y pende Mardochée; puis tu iras joyeux au festin avec le roi. Cet avis plut à Haman, et il fit préparer le bois."],[6,1,"Cette nuit-là, le roi ne put pas dormir, et il se fit apporter le livre des annales, les Chroniques. On les lut devant le roi,","Cette nuit-là, le roi ne put pas dormir, et il se fit apporter le livre des annales, les Chroniques. On les lut devant le roi,"],[6,2,"et l'on trouva écrit ce que Mardochée avait révélé au sujet de Bigthan et de Théresch, les deux eunuques du roi, gardes du seuil, qui avaient voulu porter la main sur le roi Assuérus.","et l'on trouva écrit ce que Mardochée avait révélé au sujet de Bigthan et de Théresch, les deux eunuques du roi, gardes du seuil, qui avaient voulu porter la main sur le roi Assuérus."],[6,3,"Le roi dit: Quelle marque de distinction et d'honneur Mardochée a-t-il reçue pour cela? Il n'a rien reçu, répondirent ceux qui servaient le roi.","Le roi dit: Quelle marque de distinction et d'honneur Mardochée a-t-il reçue pour cela? Il n'a rien reçu, répondirent ceux qui servaient le roi."],[6,4,"Alors le roi dit: Qui est dans la cour? -Haman était venu dans la cour extérieure de la maison du roi, pour demander au roi de faire pendre Mardochée au bois qu'il avait préparé pour lui. -","Alors le roi dit: Qui est dans la cour? -Haman était venu dans la cour extérieure de la maison du roi, pour demander au roi de faire pendre Mardochée au bois qu'il avait préparé pour lui. -"],[6,5,"Les serviteurs du roi lui répondirent: C'est Haman qui se tient dans la cour. Et le roi dit: Qu'il entre.","Les serviteurs du roi lui répondirent: C'est Haman qui se tient dans la cour. Et le roi dit: Qu'il entre."],[6,6,"Haman entra, et le roi lui dit: Que faut-il faire pour un homme que le roi veut honorer? Haman se dit en lui-même: Quel autre que moi le roi voudrait-il honorer?","Haman entra, et le roi lui dit: Que faut-il faire pour un homme que le roi veut honorer? Haman se dit en lui-même: Quel autre que moi le roi voudrait-il honorer?"],[6,7,"Et Haman répondit au roi: Pour un homme que le roi veut honorer,","Et Haman répondit au roi: Pour un homme que le roi veut honorer,"],[6,8,"il faut prendre le vêtement royal dont le roi se couvre et le cheval que le roi monte et sur la tête duquel se pose une couronne royale,","il faut prendre le vêtement royal dont le roi se couvre et le cheval que le roi monte et sur la tête duquel se pose une couronne royale,"],[6,9,"remettre le vêtement et le cheval à l'un des principaux chefs du roi, puis revêtir l'homme que le roi veut honorer, le promener à cheval à travers la place de la ville, et crier devant lui: C'est ainsi que l'on fait à l'homme que le roi veut honorer!","remettre le vêtement et le cheval à l'un des principaux chefs du roi, puis revêtir l'homme que le roi veut honorer, le promener à cheval à travers la place de la ville, et crier devant lui: C'est ainsi que l'on fait à l'homme que le roi veut honorer!"],[6,10,"Le roi dit à Haman: Prends tout de suite le vêtement et le cheval, comme tu l'as dit, et fais ainsi pour Mardochée, le Juif, qui est assis à la porte du roi; ne néglige rien de tout ce que tu as mentionné.","Le roi dit à Haman: Prends tout de suite le vêtement et le cheval, comme tu l'as dit, et fais ainsi pour Mardochée, le Juif, qui est assis à la porte du roi; ne néglige rien de tout ce que tu as mentionné."],[6,11,"Et Haman prit le vêtement et le cheval, il revêtit Mardochée, il le promena à cheval à travers la place de la ville, et il cria devant lui: C'est ainsi que l'on fait à l'homme que le roi veut honorer!","Et Haman prit le vêtement et le cheval, il revêtit Mardochée, il le promena à cheval à travers la place de la ville, et il cria devant lui: C'est ainsi que l'on fait à l'homme que le roi veut honorer!"],[6,12,"Mardochée retourna à la porte du roi, et Haman se rendit en hâte chez lui, désolé et la tête voilée.","Mardochée retourna à la porte du roi, et Haman se rendit en hâte chez lui, désolé et la tête voilée."],[6,13,"Haman raconta à Zéresch, sa femme, et à tous ses amis, tout ce qui lui était arrivé. Et ses sages, et Zéresch, sa femme, lui dirent: Si Mardochée, devant lequel tu as commencé de tomber, est de la race des Juifs, tu ne pourras rien contre lui, mais tu tomberas devant lui.","Haman raconta à Zéresch, sa femme, et à tous ses amis, tout ce qui lui était arrivé. Et ses sages, et Zéresch, sa femme, lui dirent: Si Mardochée, devant lequel tu as commencé de tomber, est de la race des Juifs, tu ne pourras rien contre lui, mais tu tomberas devant lui."],[6,14,"Comme ils lui parlaient encore, les eunuques du roi arrivèrent et conduisirent aussitôt Haman au festin qu'Esther avait préparé.","Comme ils lui parlaient encore, les eunuques du roi arrivèrent et conduisirent aussitôt Haman au festin qu'Esther avait préparé."],[7,1,"Le roi et Haman allèrent au festin chez la reine Esther.","Le roi et Haman allèrent au festin chez la reine Esther."],[7,2,"Ce second jour, le roi dit encore à Esther, pendant qu'on buvait le vin: Quelle est ta demande, reine Esther? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l'obtiendras.","Ce second jour, le roi dit encore à Esther, pendant qu'on buvait le vin: Quelle est ta demande, reine Esther? Elle te sera accordée. Que désires-tu? Quand ce serait la moitié du royaume, tu l'obtiendras."],[7,3,"La reine Esther répondit: Si j'ai trouvé grâce à tes yeux, ô roi, et si le roi le trouve bon, accorde-moi la vie, voilà ma demande, et sauve mon peuple, voilà mon désir!","La reine Esther répondit: Si j'ai trouvé grâce à tes yeux, ô roi, et si le roi le trouve bon, accorde-moi la vie, voilà ma demande, et sauve mon peuple, voilà mon désir!"],[7,4,"Car nous sommes vendus, moi et mon peuple, pour être détruits, égorgés, anéantis. Encore si nous étions vendus pour devenir esclaves et servantes, je me tairais, mais l'ennemi ne saurait compenser le dommage fait au roi.","Car nous sommes vendus, moi et mon peuple, pour être détruits, égorgés, anéantis. Encore si nous étions vendus pour devenir esclaves et servantes, je me tairais, mais l'ennemi ne saurait compenser le dommage fait au roi."],[7,5,"Le roi Assuérus prit la parole et dit à la reine Esther: Qui est-il et où est-il celui qui se propose d'agir ainsi?","Le roi Assuérus prit la parole et dit à la reine Esther: Qui est-il et où est-il celui qui se propose d'agir ainsi?"],[7,6,"Esther répondit: L'oppresseur, l'ennemi, c'est Haman, ce méchant-là! Haman fut saisi de terreur en présence du roi et de la reine.","Esther répondit: L'oppresseur, l'ennemi, c'est Haman, ce méchant-là! Haman fut saisi de terreur en présence du roi et de la reine."],[7,7,"Et le roi, dans sa colère, se leva et quitta le festin, pour aller dans le jardin du palais. Haman resta pour demander grâce de la vie à la reine Esther, car il voyait bien que sa perte était arrêtée dans l'esprit du roi.","Et le roi, dans sa colère, se leva et quitta le festin, pour aller dans le jardin du palais. Haman resta pour demander grâce de la vie à la reine Esther, car il voyait bien que sa perte était arrêtée dans l'esprit du roi."],[7,8,"Lorsque le roi revint du jardin du palais dans la salle du festin, il vit Haman qui s'était précipité vers le lit sur lequel était Esther, et il dit: Serait-ce encore pour faire violence à la reine, chez moi, dans le palais? Dès que cette parole fut sortie de la bouche du roi, on voila le visage d'Haman.","Lorsque le roi revint du jardin du palais dans la salle du festin, il vit Haman qui s'était précipité vers le lit sur lequel était Esther, et il dit: Serait-ce encore pour faire violence à la reine, chez moi, dans le palais? Dès que cette parole fut sortie de la bouche du roi, on voila le visage d'Haman."],[7,9,"Et Harbona, l'un des eunuques, dit en présence du roi: Voici, le bois préparé par Haman pour Mardochée, qui a parlé pour le bien du roi, est dressé dans la maison d'Haman, à une hauteur de cinquante coudées. Le roi dit: Qu'on y pende Haman!","Et Harbona, l'un des eunuques, dit en présence du roi: Voici, le bois préparé par Haman pour Mardochée, qui a parlé pour le bien du roi, est dressé dans la maison d'Haman, à une hauteur de cinquante coudées. Le roi dit: Qu'on y pende Haman!"],[7,10,"Et l'on pendit Haman au bois qu'il avait préparé pour Mardochée. Et la colère du roi s'apaisa.","Et l'on pendit Haman au bois qu'il avait préparé pour Mardochée. Et la colère du roi s'apaisa."],[8,1,"En ce même jour, le roi Assuérus donna à la reine Esther la maison d'Haman, l'ennemi des Juifs; et Mardochée parut devant le roi, car Esther avait fait connaître la parenté qui l'unissait à elle.","En ce même jour, le roi Assuérus donna à la reine Esther la maison d'Haman, l'ennemi des Juifs; et Mardochée parut devant le roi, car Esther avait fait connaître la parenté qui l'unissait à elle."],[8,2,"Le roi ôta son anneau, qu'il avait repris à Haman, et le donna à Mardochée; Esther, de son côté, établit Mardochée sur la maison d'Haman.","Le roi ôta son anneau, qu'il avait repris à Haman, et le donna à Mardochée; Esther, de son côté, établit Mardochée sur la maison d'Haman."],[8,3,"Puis Esther parla de nouveau en présence du roi. Elle se jeta à ses pieds, elle pleura, elle le supplia d'empêcher les effets de la méchanceté d'Haman, l'Agaguite, et la réussite de ses projets contre les Juifs.","Puis Esther parla de nouveau en présence du roi. Elle se jeta à ses pieds, elle pleura, elle le supplia d'empêcher les effets de la méchanceté d'Haman, l'Agaguite, et la réussite de ses projets contre les Juifs."],[8,4,"Le roi tendit le sceptre d'or à Esther, qui se releva et resta debout devant le roi.","Le roi tendit le sceptre d'or à Esther, qui se releva et resta debout devant le roi."],[8,5,"Elle dit alors: Si le roi le trouve bon et si j'ai trouvé grâce devant lui, si la chose paraît convenable au roi et si je suis agréable à ses yeux, qu'on écrive pour révoquer les lettres conçues par Haman, fils d'Hammedatha, l'Agaguite, et écrites par lui dans le but de faire périr les Juifs qui sont dans toutes les provinces du roi.","Elle dit alors: Si le roi le trouve bon et si j'ai trouvé grâce devant lui, si la chose paraît convenable au roi et si je suis agréable à ses yeux, qu'on écrive pour révoquer les lettres conçues par Haman, fils d'Hammedatha, l'Agaguite, et écrites par lui dans le but de faire périr les Juifs qui sont dans toutes les provinces du roi."],[8,6,"Car comment pourrais-je voir le malheur qui atteindrait mon peuple, et comment pourrais-je voir la destruction de ma race?","Car comment pourrais-je voir le malheur qui atteindrait mon peuple, et comment pourrais-je voir la destruction de ma race?"],[8,7,"Le roi Assuérus dit à la reine Esther et au Juif Mardochée: Voici, j'ai donné à Esther la maison d'Haman, et il a été pendu au bois pour avoir étendu la main contre les Juifs.","Le roi Assuérus dit à la reine Esther et au Juif Mardochée: Voici, j'ai donné à Esther la maison d'Haman, et il a été pendu au bois pour avoir étendu la main contre les Juifs."],[8,8,"Écrivez donc en faveur des Juifs comme il vous plaira, au nom du roi, et scellez avec l'anneau du roi; car une lettre écrite au nom du roi et scellée avec l'anneau du roi ne peut être révoquée.","Écrivez donc en faveur des Juifs comme il vous plaira, au nom du roi, et scellez avec l'anneau du roi; car une lettre écrite au nom du roi et scellée avec l'anneau du roi ne peut être révoquée."],[8,9,"Les secrétaires du roi furent appelés en ce temps, le vingt-troisième jour du troisième mois, qui est le mois de Sivan, et l'on écrivit, suivant tout ce qui fut ordonné par Mardochée, aux Juifs, aux satrapes, aux gouverneurs et aux chefs des cent vingt-sept provinces situées de l'Inde à l'Éthiopie, à chaque province selon son écriture, à chaque peuple selon sa langue, et aux Juifs selon leur écriture et selon leur langue.","Les secrétaires du roi furent appelés en ce temps, le vingt-troisième jour du troisième mois, qui est le mois de Sivan, et l'on écrivit, suivant tout ce qui fut ordonné par Mardochée, aux Juifs, aux satrapes, aux gouverneurs et aux chefs des cent vingt-sept provinces situées de l'Inde à l'Éthiopie, à chaque province selon son écriture, à chaque peuple selon sa langue, et aux Juifs selon leur écriture et selon leur langue."],[8,10,"On écrivit au nom du roi Assuérus, et l'on scella avec l'anneau du roi. On envoya les lettres par des courriers ayant pour montures des chevaux et des mulets nés de juments.","On écrivit au nom du roi Assuérus, et l'on scella avec l'anneau du roi. On envoya les lettres par des courriers ayant pour montures des chevaux et des mulets nés de juments."],[8,11,"Par ces lettres, le roi donnait aux Juifs, en quelque ville qu'ils fussent, la permission de se rassembler et de défendre leur vie, de détruire, de tuer et de faire périr, avec leurs petits enfants et leurs femmes, tous ceux de chaque peuple et de chaque province qui prendraient les armes pour les attaquer, et de livrer leurs biens au pillage,","Par ces lettres, le roi donnait aux Juifs, en quelque ville qu'ils fussent, la permission de se rassembler et de défendre leur vie, de détruire, de tuer et de faire périr, avec leurs petits enfants et leurs femmes, tous ceux de chaque peuple et de chaque province qui prendraient les armes pour les attaquer, et de livrer leurs biens au pillage,"],[8,12,"et cela en un seul jour, dans toutes les provinces du roi Assuérus, le treizième du douzième mois, qui est le mois d'Adar.","et cela en un seul jour, dans toutes les provinces du roi Assuérus, le treizième du douzième mois, qui est le mois d'Adar."],[8,13,"Ces lettres renfermaient une copie de l'édit qui devait être publié dans chaque province, et informaient tous les peuples que les Juifs se tiendraient prêts pour ce jour-là à se venger de leurs ennemis.","Ces lettres renfermaient une copie de l'édit qui devait être publié dans chaque province, et informaient tous les peuples que les Juifs se tiendraient prêts pour ce jour-là à se venger de leurs ennemis."],[8,14,"Les courriers, montés sur des chevaux et des mulets, partirent aussitôt et en toute hâte, d'après l'ordre du roi. L'édit fut aussi publié dans Suse, la capitale.","Les courriers, montés sur des chevaux et des mulets, partirent aussitôt et en toute hâte, d'après l'ordre du roi. L'édit fut aussi publié dans Suse, la capitale."],[8,15,"Mardochée sortit de chez le roi, avec un vêtement royal bleu et blanc, une grande couronne d'or, et un manteau de byssus et de pourpre. La ville de Suse poussait des cris et se réjouissait.","Mardochée sortit de chez le roi, avec un vêtement royal bleu et blanc, une grande couronne d'or, et un manteau de byssus et de pourpre. La ville de Suse poussait des cris et se réjouissait."],[8,16,"Il n'y avait pour les Juifs que bonheur et joie, allégresse et gloire.","Il n'y avait pour les Juifs que bonheur et joie, allégresse et gloire."],[8,17,"Dans chaque province et dans chaque ville, partout où arrivaient l'ordre du roi et son édit, il y eut parmi les Juifs de la joie et de l'allégresse, des festins et des fêtes. Et beaucoup de gens d'entre les peuples du pays se firent Juifs, car la crainte des Juifs les avait saisis.","Dans chaque province et dans chaque ville, partout où arrivaient l'ordre du roi et son édit, il y eut parmi les Juifs de la joie et de l'allégresse, des festins et des fêtes. Et beaucoup de gens d'entre les peuples du pays se firent Juifs, car la crainte des Juifs les avait saisis."],[9,1,"Au douzième mois, qui est le mois d'Adar, le treizième jour du mois, jour où devaient s'exécuter l'ordre et l'édit du roi, et où les ennemis des Juifs avaient espéré dominer sur eux, ce fut le contraire qui arriva, et les Juifs dominèrent sur leurs ennemis.","Au douzième mois, qui est le mois d'Adar, le treizième jour du mois, jour où devaient s'exécuter l'ordre et l'édit du roi, et où les ennemis des Juifs avaient espéré dominer sur eux, ce fut le contraire qui arriva, et les Juifs dominèrent sur leurs ennemis."],[9,2,"Les Juifs se rassemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus, pour mettre la main sur ceux qui cherchaient leur perte; et personne ne put leur résister, car la crainte qu'on avait d'eux s'était emparée de tous les peuples.","Les Juifs se rassemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus, pour mettre la main sur ceux qui cherchaient leur perte; et personne ne put leur résister, car la crainte qu'on avait d'eux s'était emparée de tous les peuples."],[9,3,"Et tous les chefs des provinces, les satrapes, les gouverneurs, les fonctionnaires du roi, soutinrent les Juifs, à cause de l'effroi que leur inspirait Mardochée.","Et tous les chefs des provinces, les satrapes, les gouverneurs, les fonctionnaires du roi, soutinrent les Juifs, à cause de l'effroi que leur inspirait Mardochée."],[9,4,"Car Mardochée était puissant dans la maison du roi, et sa renommée se répandait dans toutes les provinces, parce qu'il devenait de plus en plus puissant.","Car Mardochée était puissant dans la maison du roi, et sa renommée se répandait dans toutes les provinces, parce qu'il devenait de plus en plus puissant."],[9,5,"Les Juifs frappèrent à coups d'épée tous leurs ennemis, ils les tuèrent et les firent périr; ils traitèrent comme il leur plut ceux qui leur étaient hostiles.","Les Juifs frappèrent à coups d'épée tous leurs ennemis, ils les tuèrent et les firent périr; ils traitèrent comme il leur plut ceux qui leur étaient hostiles."],[9,6,"Dans Suse, la capitale, les Juifs tuèrent et firent périr cinq cents hommes,","Dans Suse, la capitale, les Juifs tuèrent et firent périr cinq cents hommes,"],[9,7,"et ils égorgèrent Parschandatha, Dalphon, Aspatha,","et ils égorgèrent Parschandatha, Dalphon, Aspatha,"],[9,8,"Poratha, Adalia, Aridatha,","Poratha, Adalia, Aridatha,"],[9,9,"Parmaschtha, Arizaï, Aridaï et Vajezatha,","Parmaschtha, Arizaï, Aridaï et Vajezatha,"],[9,10,"les dix fils d'Haman, fils d'Hammedatha, l'ennemi des Juifs. Mais ils ne mirent pas la main au pillage.","les dix fils d'Haman, fils d'Hammedatha, l'ennemi des Juifs. Mais ils ne mirent pas la main au pillage."],[9,11,"Ce jour-là, le nombre de ceux qui avaient été tués dans Suse, la capitale, parvint à la connaissance du roi.","Ce jour-là, le nombre de ceux qui avaient été tués dans Suse, la capitale, parvint à la connaissance du roi."],[9,12,"Et le roi dit à la reine Esther: Les Juifs ont tué et fait périr dans Suse, la capitale, cinq cents hommes et les dix fils d'Haman; qu'auront-ils fait dans le reste des provinces du roi? Quelle est ta demande? Elle te sera accordée. Que désires-tu encore? Tu l'obtiendras.","Et le roi dit à la reine Esther: Les Juifs ont tué et fait périr dans Suse, la capitale, cinq cents hommes et les dix fils d'Haman; qu'auront-ils fait dans le reste des provinces du roi? Quelle est ta demande? Elle te sera accordée. Que désires-tu encore? Tu l'obtiendras."],[9,13,"Esther répondit: Si le roi le trouve bon, qu'il soit permis aux Juifs qui sont à Suse d'agir encore demain selon le décret d'aujourd'hui, et que l'on pende au bois les dix fils d'Haman.","Esther répondit: Si le roi le trouve bon, qu'il soit permis aux Juifs qui sont à Suse d'agir encore demain selon le décret d'aujourd'hui, et que l'on pende au bois les dix fils d'Haman."],[9,14,"Et le roi ordonna de faire ainsi. L'édit fut publié dans Suse. On pendit les dix fils d'Haman;","Et le roi ordonna de faire ainsi. L'édit fut publié dans Suse. On pendit les dix fils d'Haman;"],[9,15,"et les Juifs qui se trouvaient à Suse se rassemblèrent de nouveau le quatorzième jour du mois d'Adar et tuèrent dans Suse trois cents hommes. Mais ils ne mirent pas la main au pillage.","et les Juifs qui se trouvaient à Suse se rassemblèrent de nouveau le quatorzième jour du mois d'Adar et tuèrent dans Suse trois cents hommes. Mais ils ne mirent pas la main au pillage."],[9,16,"Les autres Juifs qui étaient dans les provinces du roi se rassemblèrent et défendirent leur vie; ils se procurèrent du repos en se délivrant de leurs ennemis, et ils tuèrent soixante-quinze mille de ceux qui leur étaient hostiles. Mais ils ne mirent pas la main au pillage.","Les autres Juifs qui étaient dans les provinces du roi se rassemblèrent et défendirent leur vie; ils se procurèrent du repos en se délivrant de leurs ennemis, et ils tuèrent soixante-quinze mille de ceux qui leur étaient hostiles. Mais ils ne mirent pas la main au pillage."],[9,17,"Ces choses arrivèrent le treizième jour du mois d'Adar. Les Juifs se reposèrent le quatorzième, et ils en firent un jour de festin et de joie.","Ces choses arrivèrent le treizième jour du mois d'Adar. Les Juifs se reposèrent le quatorzième, et ils en firent un jour de festin et de joie."],[9,18,"Ceux qui se trouvaient à Suse, s'étant rassemblés le treizième jour et le quatorzième jour, se reposèrent le quinzième, et ils en firent un jour de festin et de joie.","Ceux qui se trouvaient à Suse, s'étant rassemblés le treizième jour et le quatorzième jour, se reposèrent le quinzième, et ils en firent un jour de festin et de joie."],[9,19,"C'est pourquoi les Juifs de la campagne, qui habitent des villes sans murailles, font du quatorzième jour du mois d'Adar un jour de joie, de festin et de fête, où l'on s'envoie des portions les uns aux autres.","C'est pourquoi les Juifs de la campagne, qui habitent des villes sans murailles, font du quatorzième jour du mois d'Adar un jour de joie, de festin et de fête, où l'on s'envoie des portions les uns aux autres."],[9,20,"Mardochée écrivit ces choses, et il envoya des lettres à tous les Juifs qui étaient dans toutes les provinces du roi Assuérus, auprès et au loin.","Mardochée écrivit ces choses, et il envoya des lettres à tous les Juifs qui étaient dans toutes les provinces du roi Assuérus, auprès et au loin."],[9,21,"Il leur prescrivait de célébrer chaque année le quatorzième jour et le quinzième jour du mois d'Adar","Il leur prescrivait de célébrer chaque année le quatorzième jour et le quinzième jour du mois d'Adar"],[9,22,"comme les jours où ils avaient obtenu du repos en se délivrant de leurs ennemis, de célébrer le mois où leur tristesse avait été changée en joie et leur désolation en jour de fête, et de faire de ces jours des jours de festin et de joie où l'on s'envoie des portions les uns aux autres et où l'on distribue des dons aux indigents.","comme les jours où ils avaient obtenu du repos en se délivrant de leurs ennemis, de célébrer le mois où leur tristesse avait été changée en joie et leur désolation en jour de fête, et de faire de ces jours des jours de festin et de joie où l'on s'envoie des portions les uns aux autres et où l'on distribue des dons aux indigents."],[9,23,"Les Juifs s'engagèrent à faire ce qu'ils avaient déjà commencé et ce que Mardochée leur écrivit.","Les Juifs s'engagèrent à faire ce qu'ils avaient déjà commencé et ce que Mardochée leur écrivit."],[9,24,"Car Haman, fils d'Hammedatha, l'Agaguite, ennemi de tous les Juifs, avait formé le projet de les faire périr, et il avait jeté le pur, c'est-à-dire le sort, afin de les tuer et de les détruire;","Car Haman, fils d'Hammedatha, l'Agaguite, ennemi de tous les Juifs, avait formé le projet de les faire périr, et il avait jeté le pur, c'est-à-dire le sort, afin de les tuer et de les détruire;"],[9,25,"mais Esther s'étant présentée devant le roi, le roi ordonna par écrit de faire retomber sur la tête d'Haman le méchant projet qu'il avait formé contre les Juifs, et de le pendre au bois, lui et ses fils.","mais Esther s'étant présentée devant le roi, le roi ordonna par écrit de faire retomber sur la tête d'Haman le méchant projet qu'il avait formé contre les Juifs, et de le pendre au bois, lui et ses fils."],[9,26,"C'est pourquoi on appela ces jours Purim, du nom de pur. D'après tout le contenu de cette lettre, d'après ce qu'ils avaient eux-mêmes vu et ce qui leur était arrivé,","C'est pourquoi on appela ces jours Purim, du nom de pur. D'après tout le contenu de cette lettre, d'après ce qu'ils avaient eux-mêmes vu et ce qui leur était arrivé,"],[9,27,"les Juifs prirent pour eux, pour leur postérité, et pour tous ceux qui s'attacheraient à eux, la résolution et l'engagement irrévocables de célébrer chaque année ces deux jours, selon le mode prescrit et au temps fixé.","les Juifs prirent pour eux, pour leur postérité, et pour tous ceux qui s'attacheraient à eux, la résolution et l'engagement irrévocables de célébrer chaque année ces deux jours, selon le mode prescrit et au temps fixé."],[9,28,"Ces jours devaient être rappelés et célébrés de génération en génération, dans chaque famille, dans chaque province et dans chaque ville; et ces jours de Purim ne devaient jamais être abolis au milieu des Juifs, ni le souvenir s'en effacer parmi leurs descendants.","Ces jours devaient être rappelés et célébrés de génération en génération, dans chaque famille, dans chaque province et dans chaque ville; et ces jours de Purim ne devaient jamais être abolis au milieu des Juifs, ni le souvenir s'en effacer parmi leurs descendants."],[9,29,"La reine Esther, fille d'Abichaïl, et le Juif Mardochée écrivirent d'une manière pressante une seconde fois pour confirmer la lettre sur les Purim.","La reine Esther, fille d'Abichaïl, et le Juif Mardochée écrivirent d'une manière pressante une seconde fois pour confirmer la lettre sur les Purim."],[9,30,"On envoya des lettres à tous les Juifs, dans les cent vingt-sept provinces du roi Assuérus. Elles contenaient des paroles de paix et de fidélité,","On envoya des lettres à tous les Juifs, dans les cent vingt-sept provinces du roi Assuérus. Elles contenaient des paroles de paix et de fidélité,"],[9,31,"pour prescrire ces jours de Purim au temps fixé, comme le Juif Mardochée et la reine Esther les avaient établis pour eux, et comme ils les avaient établis pour eux-mêmes et pour leur postérité, à l'occasion de leur jeûne et de leurs cris.","pour prescrire ces jours de Purim au temps fixé, comme le Juif Mardochée et la reine Esther les avaient établis pour eux, et comme ils les avaient établis pour eux-mêmes et pour leur postérité, à l'occasion de leur jeûne et de leurs cris."],[9,32,"Ainsi l'ordre d'Esther confirma l'institution des Purim, et cela fut écrit dans le livre.","Ainsi l'ordre d'Esther confirma l'institution des Purim, et cela fut écrit dans le livre."],[10,1,"Le roi Assuérus imposa un tribut au pays et aux îles de la mer.","Le roi Assuérus imposa un tribut au pays et aux îles de la mer."],[10,2,"Tous les faits concernant sa puissance et ses exploits, et les détails sur la grandeur à laquelle le roi éleva Mardochée, ne sont-ils pas écrits dans le livre des Chroniques des rois des Mèdes et des Perses?","Tous les faits concernant sa puissance et ses exploits, et les détails sur la grandeur à laquelle le roi éleva Mardochée, ne sont-ils pas écrits dans le livre des Chroniques des rois des Mèdes et des Perses?"],[10,3,"Car le Juif Mardochée était le premier après le roi Assuérus; considéré parmi les Juifs et aimé de la multitude de ses frères, il rechercha le bien de son peuple et parla pour le bonheur de toute sa race.","Car le Juif Mardochée était le premier après le roi Assuérus; considéré parmi les Juifs et aimé de la multitude de ses frères, il rechercha le bien de son peuple et parla pour le bonheur de toute sa race."]],"spa-rv1909":[[1,1,"Y ACONTECIÓen los díasde Assuero, (elAssueroque reinódesde la Indiahastala Etiopíasobre cientoveintey sieteprovincias,)","Y ACONTECIÓen los díasde Assuero, (elAssueroque reinódesde la Indiahastala Etiopíasobre cientoveintey sieteprovincias,)"],[1,2,"Que en aquellos días, asentado que fué el reyAssueroen la sillade su reino, la cualestaba en Susáncapitaldel reino,","Que en aquellos días, asentado que fué el reyAssueroen la sillade su reino, la cualestaba en Susáncapitaldel reino,"],[1,3,"En el tercerañode su reinadohizobanqueteá todossus príncipesy siervos, teniendo delantede él la fuerzade Persiay de Media, gobernadoresy príncipesde provincias,","En el tercerañode su reinadohizobanqueteá todossus príncipesy siervos, teniendo delantede él la fuerzade Persiay de Media, gobernadoresy príncipesde provincias,"],[1,4,"Para mostrarél las riquezasde la gloriade su reino, y el lustre de la magnificenciade su poder, por muchosdías, cientoy ochentadías.","Para mostrarél las riquezasde la gloriade su reino, y el lustre de la magnificenciade su poder, por muchosdías, cientoy ochentadías."],[1,5,"Y cumplidosestos días, hizoel reybanquetepor sietedíasen el patiodel huertodel palaciorealá todoel pueblo, desde el mayorhastael menorque se halló en Susáncapitaldel reino.","Y cumplidosestos días, hizoel reybanquetepor sietedíasen el patiodel huertodel palaciorealá todoel pueblo, desde el mayorhastael menorque se halló en Susáncapitaldel reino."],[1,6,"El pabellón era deblanco, verde, y cárdeno, tendidosobre cuerdasde linoy púrpuraensortijas de platay columnasde mármol: losreclinatoriosde oroy de plata, sobrelosadode pórfidoy de mármol, y de alabastroy de jacinto.","El pabellón era deblanco, verde, y cárdeno, tendidosobre cuerdasde linoy púrpuraensortijas de platay columnasde mármol: losreclinatoriosde oroy de plata, sobrelosadode pórfidoy de mármol, y de alabastroy de jacinto."],[1,7,"Y daban á beberen vasosde oro, y vasosdiferentesunos de otros, y muchovinoreal, conforme á la facultaddel rey.","Y daban á beberen vasosde oro, y vasosdiferentesunos de otros, y muchovinoreal, conforme á la facultaddel rey."],[1,8,"Y la bebidafué según esta ley: Que nadieconstriñese; porqueasílo había mandadoel reyátodoslos mayordomosde su casa; que se hiciesesegún la voluntadde cada uno.","Y la bebidafué según esta ley: Que nadieconstriñese; porqueasílo había mandadoel reyátodoslos mayordomosde su casa; que se hiciesesegún la voluntadde cada uno."],[1,9,"Asimismola reinaVasthihizobanquetede mujeres, en la casarealdel reyAssuero.","Asimismola reinaVasthihizobanquetede mujeres, en la casarealdel reyAssuero."],[1,10,"El séptimodía, estando el corazóndel reyalegredel vino, mandóá Mehumán, y á Biztha, y á Harbona, y á Bigtha, y á Abagtha, y á Zetar, y á Carcas, sieteeunucosque servíandelantedel reyAssuero,","El séptimodía, estando el corazóndel reyalegredel vino, mandóá Mehumán, y á Biztha, y á Harbona, y á Bigtha, y á Abagtha, y á Zetar, y á Carcas, sieteeunucosque servíandelantedel reyAssuero,"],[1,11,"Que trajesená la reinaVasthidelantedel reycon la coronaregia, para mostrará los pueblosy á los príncipessuhermosura; porqueera linda de aspecto.","Que trajesená la reinaVasthidelantedel reycon la coronaregia, para mostrará los pueblosy á los príncipessuhermosura; porqueera linda de aspecto."],[1,12,"Mas la reinaVasthino quisocomparecerá la ordendel rey, enviadapor manode los eunucos; y enojóseel reymuy mucho, y encendióse en él su ira.","Mas la reinaVasthino quisocomparecerá la ordendel rey, enviadapor manode los eunucos; y enojóseel reymuy mucho, y encendióse en él su ira."],[1,13,"Preguntóentonces el reyá los sabiosque sabíanlos tiempos, (porqueasíera la costumbre del reypara con todoslos que sabíanla leyy el derecho;","Preguntóentonces el reyá los sabiosque sabíanlos tiempos, (porqueasíera la costumbre del reypara con todoslos que sabíanla leyy el derecho;"],[1,14,"Y estaban juntoáél, Carsena, y Sethar, y Admatha, y Tharsis, y Meres, y Marsena, y Memucán, sietepríncipesde Persiay de Mediaque veíanla cara del rey, y se sentabanlos primerosdel reino:)","Y estaban juntoáél, Carsena, y Sethar, y Admatha, y Tharsis, y Meres, y Marsena, y Memucán, sietepríncipesde Persiay de Mediaque veíanla cara del rey, y se sentabanlos primerosdel reino:)"],[1,15,"Qué se había de hacer segúnla leycon la reinaVasthi, por cuantonohabíacumplidola ordendel reyAssuero, enviadapor manode los eunucos.","Qué se había de hacer segúnla leycon la reinaVasthi, por cuantonohabíacumplidola ordendel reyAssuero, enviadapor manode los eunucos."],[1,16,"Y dijoMemucándelantedel reyy de los príncipes: Nosolamente contrael reyha pecadola reinaVasthi, sinocontratodoslos príncipes, y contratodoslos pueblosquehay en todaslas provinciasdel reyAssuero.","Y dijoMemucándelantedel reyy de los príncipes: Nosolamente contrael reyha pecadola reinaVasthi, sinocontratodoslos príncipes, y contratodoslos pueblosquehay en todaslas provinciasdel reyAssuero."],[1,17,"Porqueeste hechode la reinapasaráánoticiade todaslas mujeres, para hacerles tener en poca estimaá sus maridos, diciendo: El reyAssueromandótraerdelantede sí á la reinaVasthi, y ella novino.","Porqueeste hechode la reinapasaráánoticiade todaslas mujeres, para hacerles tener en poca estimaá sus maridos, diciendo: El reyAssueromandótraerdelantede sí á la reinaVasthi, y ella novino."],[1,18,"Y entoncesdiránestolas señorasde Persiay de Mediaqueoyeren el hechode la reina, á todoslos príncipesdel rey: y habrámuchomenosprecioy enojo.","Y entoncesdiránestolas señorasde Persiay de Mediaqueoyeren el hechode la reina, á todoslos príncipesdel rey: y habrámuchomenosprecioy enojo."],[1,19,"Siparece bienalrey, salgamandamientorealdelantedeél, y escríbaseentre las leyesdePersiay deMedia, y nosea traspasado: Que novengamás Vasthidelantedel reyAssuero: y dé el reysu reinoá su compañeraque sea mejorqueella.","Siparece bienalrey, salgamandamientorealdelantedeél, y escríbaseentre las leyesdePersiay deMedia, y nosea traspasado: Que novengamás Vasthidelantedel reyAssuero: y dé el reysu reinoá su compañeraque sea mejorqueella."],[1,20,"Y el mandamientoqueharáel reyserá oídoen todosureino, aunquees grande, y todaslas mujeresdaránhonraá sus maridos, desde el mayorhastael menor.","Y el mandamientoqueharáel reyserá oídoen todosureino, aunquees grande, y todaslas mujeresdaránhonraá sus maridos, desde el mayorhastael menor."],[1,21,"Y plugo esta palabraen ojosdel reyy de los príncipes, é hizoel reyconforme al dichode Memucán;","Y plugo esta palabraen ojosdel reyy de los príncipes, é hizoel reyconforme al dichode Memucán;"],[1,22,"Pues envióletrasá todaslas provinciasdel rey, á cada provinciaconforme á su escribir, y ácada puebloconforme á su lenguaje, diciendoque todohombrefuese señoren su casa; y hábleseesto según la lenguade su pueblo.","Pues envióletrasá todaslas provinciasdel rey, á cada provinciaconforme á su escribir, y ácada puebloconforme á su lenguaje, diciendoque todohombrefuese señoren su casa; y hábleseesto según la lenguade su pueblo."],[2,1,"PASADASestas cosas, sosegadaya la iradel reyAssuero, acordósede Vasthi, y de lo quehizo, y de lo quefué sentenciado contraella.","PASADASestas cosas, sosegadaya la iradel reyAssuero, acordósede Vasthi, y de lo quehizo, y de lo quefué sentenciado contraella."],[2,2,"Y dijeronlos criadosdel rey, sus oficiales: Busquenal reymozasvírgenesde buenparecer;","Y dijeronlos criadosdel rey, sus oficiales: Busquenal reymozasvírgenesde buenparecer;"],[2,3,"Y pongael reypersonasen todaslas provinciasde su reino, que junten todaslas mozasvírgenesde buenpareceren Susánresidenciaregia, en la casade las mujeres, alcuidadode Hegai, eunucodel rey, guardade las mujeres, dándolessus atavíos;","Y pongael reypersonasen todaslas provinciasde su reino, que junten todaslas mozasvírgenesde buenpareceren Susánresidenciaregia, en la casade las mujeres, alcuidadode Hegai, eunucodel rey, guardade las mujeres, dándolessus atavíos;"],[2,4,"Y la mozaqueagradareá los ojosdel rey, reineen lugarde Vasthi. Y la cosa plugo en ojosdel rey, é hízolo así.","Y la mozaqueagradareá los ojosdel rey, reineen lugarde Vasthi. Y la cosa plugo en ojosdel rey, é hízolo así."],[2,5,"Habíaun varónJudíoen Susánresidenciaregia, cuyo nombreera Mardochêo, hijode Jair, hijode Simi, hijode Cis, del linaje de Benjamín;","Habíaun varónJudíoen Susánresidenciaregia, cuyo nombreera Mardochêo, hijode Jair, hijode Simi, hijode Cis, del linaje de Benjamín;"],[2,6,"El cualhabía sido trasportadode Jerusalemconlos cautivosque fueron llevadosconJechôníasreyde Judá, á quien hizo trasportar Nabucodonosorreyde Babilonia.","El cualhabía sido trasportadode Jerusalemconlos cautivosque fueron llevadosconJechôníasreyde Judá, á quien hizo trasportar Nabucodonosorreyde Babilonia."],[2,7,"Y habíacriadoá Hadassa, que es Esther, hijade sutío, porqueno tenía padreni madre; y era mozade hermosaforma y de buenparecer; y como supadrey sumadremurieron, Mardochêola habíatomado por hijasuya.","Y habíacriadoá Hadassa, que es Esther, hijade sutío, porqueno tenía padreni madre; y era mozade hermosaforma y de buenparecer; y como supadrey sumadremurieron, Mardochêola habíatomado por hijasuya."],[2,8,"Sucediópues, que como se divulgóel mandamientodel reyy su acuerdo, y siendo reunidas muchasmozasenSusánresidenciaregia, ácargode Hegai, fué tomadatambién Estherparacasadel rey, alcuidadode Hegai, guardade las mujeres.","Sucediópues, que como se divulgóel mandamientodel reyy su acuerdo, y siendo reunidas muchasmozasenSusánresidenciaregia, ácargode Hegai, fué tomadatambién Estherparacasadel rey, alcuidadode Hegai, guardade las mujeres."],[2,9,"Y la mozaagradóen sus ojos, y hallógraciadelantede él; por lo que hizo darleprestamente sus atavíosy sus raciones, dándole también sieteconvenientes doncellasde la casadel rey; y pasólacon sus doncellasá lo mejorde la casade las mujeres.","Y la mozaagradóen sus ojos, y hallógraciadelantede él; por lo que hizo darleprestamente sus atavíosy sus raciones, dándole también sieteconvenientes doncellasde la casadel rey; y pasólacon sus doncellasá lo mejorde la casade las mujeres."],[2,10,"Esthernodeclarósu puebloni su nacimiento; porqueMardochêolehabía mandadoquenolo declarase.","Esthernodeclarósu puebloni su nacimiento; porqueMardochêolehabía mandadoquenolo declarase."],[2,11,"Y cadadíaMardochêose paseabadelantedel patiode la casade las mujeres, por sabercómo ibaá Esther, y quése hacíade ella.","Y cadadíaMardochêose paseabadelantedel patiode la casade las mujeres, por sabercómo ibaá Esther, y quése hacíade ella."],[2,12,"Y como llegabael tiempode cada una de las mozaspara veniralreyAssuero, alcabo de haber estadoya docemesesconforme á la leyacerca de las mujeres(porque asíse cumplíael tiempode sus atavíos, esto es, seismesescon óleode mirra, y seismesescon cosasaromáticas y afeitesde mujeres),","Y como llegabael tiempode cada una de las mozaspara veniralreyAssuero, alcabo de haber estadoya docemesesconforme á la leyacerca de las mujeres(porque asíse cumplíael tiempode sus atavíos, esto es, seismesescon óleode mirra, y seismesescon cosasaromáticas y afeitesde mujeres),"],[2,13,"Entonces la mozaveníaasíalrey: todolo queella decía se le daba, para venirconello de la casade las mujereshastala casadel rey.","Entonces la mozaveníaasíalrey: todolo queella decía se le daba, para venirconello de la casade las mujereshastala casadel rey."],[2,14,"Ellaveníaá la tarde, y á la mañanase volvíaála casasegundade las mujeres, alcargode Saasgazeunucodel rey, guardade las concubinas: noveníamásalrey, salvo si el reyla quería, y era llamadapor nombre.","Ellaveníaá la tarde, y á la mañanase volvíaála casasegundade las mujeres, alcargode Saasgazeunucodel rey, guardade las concubinas: noveníamásalrey, salvo si el reyla quería, y era llamadapor nombre."],[2,15,"Y llegadoque fué el tiempode Esther, hijade Abihailtíode Mardochêo, queél se había tomadopor hija, para veniralrey, ningunacosaprocurósino lo quedijoHegaieunucodel rey, guardade las mujeres: y ganabaEstherla graciadetodoslos que la veían.","Y llegadoque fué el tiempode Esther, hijade Abihailtíode Mardochêo, queél se había tomadopor hija, para veniralrey, ningunacosaprocurósino lo quedijoHegaieunucodel rey, guardade las mujeres: y ganabaEstherla graciadetodoslos que la veían."],[2,16,"Fué pues EstherllevadaalreyAssueroásucasarealen el mesdécimo, que es el mesde Tebeth, en el añoséptimode sureinado.","Fué pues EstherllevadaalreyAssueroásucasarealen el mesdécimo, que es el mesde Tebeth, en el añoséptimode sureinado."],[2,17,"Y el reyamóá Esthersobre todaslas mujeres, y hallógraciay benevolenciadelantede él más que todaslas vírgenes; y pusola coronarealen su cabeza, é hízola reinaen lugarde Vasthi.","Y el reyamóá Esthersobre todaslas mujeres, y hallógraciay benevolenciadelantede él más que todaslas vírgenes; y pusola coronarealen su cabeza, é hízola reinaen lugarde Vasthi."],[2,18,"Hizoluego el reygranbanqueteá todossus príncipesy siervos, el banquetede Esther; y alivióá las provincias, é hizoy diómercedesconforme á la facultadreal.","Hizoluego el reygranbanqueteá todossus príncipesy siervos, el banquetede Esther; y alivióá las provincias, é hizoy diómercedesconforme á la facultadreal."],[2,19,"Y cuando se juntaban las vírgenesla segundavez, Mardochêoestaba puesto á la puertadel rey.","Y cuando se juntaban las vírgenesla segundavez, Mardochêoestaba puesto á la puertadel rey."],[2,20,"Y Esther, segúnle tenía mandadoMardochêo, no habíadeclaradosu naciónni su pueblo; porque Estherhacíalo quedecíaMardochêo, como cuando con élse educaba.","Y Esther, segúnle tenía mandadoMardochêo, no habíadeclaradosu naciónni su pueblo; porque Estherhacíalo quedecíaMardochêo, como cuando con élse educaba."],[2,21,"En aquellos días, estando Mardochêosentadoá la puertadel rey, enojáronseBigthány Teres, doseunucosdel rey, de la guardiade la puerta, y procurabanponermanoen el reyAssuero.","En aquellos días, estando Mardochêosentadoá la puertadel rey, enojáronseBigthány Teres, doseunucosdel rey, de la guardiade la puerta, y procurabanponermanoen el reyAssuero."],[2,22,"Mas entendido que fué estopor Mardochêo, él lo denuncióá la reinaEsther, y Estherlo dijoal reyen nombrede Mardochêo.","Mas entendido que fué estopor Mardochêo, él lo denuncióá la reinaEsther, y Estherlo dijoal reyen nombrede Mardochêo."],[2,23,"Hízose entonces indagaciónde la cosa, y fué halladacierta; por tanto, entrambosfueron colgadosenuna horca. Y escribióseel casoenel librode las cosasde los tiemposdelante del rey.","Hízose entonces indagaciónde la cosa, y fué halladacierta; por tanto, entrambosfueron colgadosenuna horca. Y escribióseel casoenel librode las cosasde los tiemposdelante del rey."],[3,1,"DESPUÉSde estas cosas, el reyAssueroengrandecióá Amánhijode AmadathaAgageo, y ensalzólo, y pusosu sillasobretodoslos príncipesqueestaban conél.","DESPUÉSde estas cosas, el reyAssueroengrandecióá Amánhijode AmadathaAgageo, y ensalzólo, y pusosu sillasobretodoslos príncipesqueestaban conél."],[3,2,"Y todoslos siervosdel reyqueestaban á la puertadel rey, se arrodillabané inclinabaná Amán, porqueasíse lo había mandadoel rey; pero Mardochêo, nise arrodillabanise humillaba.","Y todoslos siervosdel reyqueestaban á la puertadel rey, se arrodillabané inclinabaná Amán, porqueasíse lo había mandadoel rey; pero Mardochêo, nise arrodillabanise humillaba."],[3,3,"Y los siervosdel reyqueestaban á la puerta, dijeroná Mardochêo: ¿Por quétraspasasel mandamientodel rey?","Y los siervosdel reyqueestaban á la puerta, dijeroná Mardochêo: ¿Por quétraspasasel mandamientodel rey?"],[3,4,"Y acontecióque, hablándolecada díade esta manera, y noescuchándolosél, denunciáronloáAmán, por versi las palabras de Mardochêose mantendrían; porqueya él les había declaradoque eraJudío.","Y acontecióque, hablándolecada díade esta manera, y noescuchándolosél, denunciáronloáAmán, por versi las palabras de Mardochêose mantendrían; porqueya él les había declaradoque eraJudío."],[3,5,"Y vióAmánqueMardochêonise arrodillabanise humillabadelantede él; y llenósede ira.","Y vióAmánqueMardochêonise arrodillabanise humillabadelantede él; y llenósede ira."],[3,6,"Mas tuvoen pocometer manoen solo Mardochêo; queya le habían declaradoel pueblode Mardochêo: y procuróAmándestruirá todoslos Judíosquehabía en el reinode Assuero, al pueblode Mardochêo.","Mas tuvoen pocometer manoen solo Mardochêo; queya le habían declaradoel pueblode Mardochêo: y procuróAmándestruirá todoslos Judíosquehabía en el reinode Assuero, al pueblode Mardochêo."],[3,7,"En el mesprimero, que es el mesde Nisán, en el añoduodécimodel reyAssuero, fué echadaPur, estoes, la suerte, delantede Amán, de díaen díay de mes en mes; y salióel mes duodécimo, que esel mesde Adar.","En el mesprimero, que es el mesde Nisán, en el añoduodécimodel reyAssuero, fué echadaPur, estoes, la suerte, delantede Amán, de díaen díay de mes en mes; y salióel mes duodécimo, que esel mesde Adar."],[3,8,"Y dijoAmánal reyAssuero: Hayunpuebloesparcidoy dividido entrelos pueblosen todaslas provinciasde tu reino, y sus leyesson diferentesde las detodopueblo, y noobservan las leyesdel rey; y al reynovieneprovechode dejarlos.","Y dijoAmánal reyAssuero: Hayunpuebloesparcidoy dividido entrelos pueblosen todaslas provinciasde tu reino, y sus leyesson diferentesde las detodopueblo, y noobservan las leyesdel rey; y al reynovieneprovechode dejarlos."],[3,9,"Siplacealrey, escríbaseque sean destruídos; y yo pesarédiezmiltalentosde plataen manos de los que manejanla hacienda, para que sean traídosálos tesorosdel rey.","Siplacealrey, escríbaseque sean destruídos; y yo pesarédiezmiltalentosde plataen manos de los que manejanla hacienda, para que sean traídosálos tesorosdel rey."],[3,10,"Entoncesel reyquitósu anillode su mano, y dióloá Amánhijode AmadathaAgageo, enemigode los Judíos,","Entoncesel reyquitósu anillode su mano, y dióloá Amánhijode AmadathaAgageo, enemigode los Judíos,"],[3,11,"Y díjole: La platapropuesta seapara ti, y asimismo el pueblo, para que hagasde él lo que biente pareciere.","Y díjole: La platapropuesta seapara ti, y asimismo el pueblo, para que hagasde él lo que biente pareciere."],[3,12,"Entonces fueron llamadoslos escribanosdel reyen el mesprimero, á trecedel mismo, y fué escritoconforme á todolo quemandóAmán, á los príncipesdel rey, y á los capitanesqueestaban sobrecada provincia, y á los príncipesde cada pueblo, á cada provinciasegún su escritura, y á cada pueblosegún su lengua: en nombredel reyAssuerofué escrito, y signado con el anillodel rey.","Entonces fueron llamadoslos escribanosdel reyen el mesprimero, á trecedel mismo, y fué escritoconforme á todolo quemandóAmán, á los príncipesdel rey, y á los capitanesqueestaban sobrecada provincia, y á los príncipesde cada pueblo, á cada provinciasegún su escritura, y á cada pueblosegún su lengua: en nombredel reyAssuerofué escrito, y signado con el anillodel rey."],[3,13,"Y fueron enviadasletraspor manode los correosá todaslas provinciasdel rey, para destruir, y matar, yexterminará todoslos Judíos, desde el niño hasta el viejo, niñosymujeresen undía, en el trecedel mesduodécimo, que esel mesde Adar, ypara apoderarsede su despojo.","Y fueron enviadasletraspor manode los correosá todaslas provinciasdel rey, para destruir, y matar, yexterminará todoslos Judíos, desde el niño hasta el viejo, niñosymujeresen undía, en el trecedel mesduodécimo, que esel mesde Adar, ypara apoderarsede su despojo."],[3,14,"La copiadel escritoque se diesepor mandamientoen cadaprovincia, fué publicadaá todoslos pueblos, á fin de que estuviesenapercibidos para aquel día.","La copiadel escritoque se diesepor mandamientoen cadaprovincia, fué publicadaá todoslos pueblos, á fin de que estuviesenapercibidos para aquel día."],[3,15,"Y salieronlos correosde priesapor mandatodel rey, y el edictofué dadoen Susáncapitaldel reino. Y el reyy Amánestaban sentados á beber, y la ciudadde Susánestaba conmovida.","Y salieronlos correosde priesapor mandatodel rey, y el edictofué dadoen Susáncapitaldel reino. Y el reyy Amánestaban sentados á beber, y la ciudadde Susánestaba conmovida."],[4,1,"LUEGO que supoMardochêotodolo quese había hecho, rasgósus vestidos, y vistiósede sacoy de ceniza, y fuésepor medio de la ciudadclamandocon grandey amargoclamor.","LUEGO que supoMardochêotodolo quese había hecho, rasgósus vestidos, y vistiósede sacoy de ceniza, y fuésepor medio de la ciudadclamandocon grandey amargoclamor."],[4,2,"Y vinohastadelantede la puertadel rey: porque noera lícito pasaradentrode la puertadel reycon vestidode saco.","Y vinohastadelantede la puertadel rey: porque noera lícito pasaradentrode la puertadel reycon vestidode saco."],[4,3,"Y en cadaprovinciay lugardondeel mandamientodel reyy su decretollegaba, tenían los Judíosgrandeluto, y ayuno, y lloro, y lamentación: sacoy cenizaera la camade muchos.","Y en cadaprovinciay lugardondeel mandamientodel reyy su decretollegaba, tenían los Judíosgrandeluto, y ayuno, y lloro, y lamentación: sacoy cenizaera la camade muchos."],[4,4,"Y vinieronlas doncellasde Esthery sus eunucos, y dijéronselo: y la reinatuvo grandolor, y envióvestidospara hacer vestirá Mardochêo, y hacerle quitarel sacode sobre él; mas él nolos recibió.","Y vinieronlas doncellasde Esthery sus eunucos, y dijéronselo: y la reinatuvo grandolor, y envióvestidospara hacer vestirá Mardochêo, y hacerle quitarel sacode sobre él; mas él nolos recibió."],[4,5,"Entonces Estherllamóá Atach, uno de los eunucosdel rey, queél había hecho estardelante de ella, y mandóloáMardochêo, con orden de saberquéeraaquello, y porqué.","Entonces Estherllamóá Atach, uno de los eunucosdel rey, queél había hecho estardelante de ella, y mandóloáMardochêo, con orden de saberquéeraaquello, y porqué."],[4,6,"Saliópues AtacháMardochêo, ála plazade la ciudadqueestaba delantede la puertadel rey.","Saliópues AtacháMardochêo, ála plazade la ciudadqueestaba delantede la puertadel rey."],[4,7,"Y Mardochêole declarótodolo quele había acontecido, y dióle noticia de la plataqueAmánhabía dichoquepesaríaparalos tesorosdel reypor razón de los Judíos, para destruirlos.","Y Mardochêole declarótodolo quele había acontecido, y dióle noticia de la plataqueAmánhabía dichoquepesaríaparalos tesorosdel reypor razón de los Judíos, para destruirlos."],[4,8,"Dióletambién la copiade la escritura del decretoquehabía sido dadoen Susánpara quefuesen destruídos, á fin de quela mostrara á Esthery se lo declarase, y le encargaraquefueseal reyá suplicarle, y á pedir delantede él porsu pueblo.","Dióletambién la copiade la escritura del decretoquehabía sido dadoen Susánpara quefuesen destruídos, á fin de quela mostrara á Esthery se lo declarase, y le encargaraquefueseal reyá suplicarle, y á pedir delantede él porsu pueblo."],[4,9,"Y vinoAtach, y contóá Estherlas palabrasde Mardochêo.","Y vinoAtach, y contóá Estherlas palabrasde Mardochêo."],[4,10,"Entonces Estherdijoá Atach, y mandóledeciráMardochêo:","Entonces Estherdijoá Atach, y mandóledeciráMardochêo:"],[4,11,"Todoslos siervosdel rey, y el pueblode las provinciasdel reysaben, quecualquierhombreó mujerqueentraalreyalpatiode adentrosinser llamado, por unasola leyha de morir: salvoaquel á quien el reyextendiereel cetrode oro, el cual vivirá: y yonohe sido llamadapara entrar alreyestostreintadías.","Todoslos siervosdel rey, y el pueblode las provinciasdel reysaben, quecualquierhombreó mujerqueentraalreyalpatiode adentrosinser llamado, por unasola leyha de morir: salvoaquel á quien el reyextendiereel cetrode oro, el cual vivirá: y yonohe sido llamadapara entrar alreyestostreintadías."],[4,12,"Y dijeroná Mardochêolas palabrasde Esther.","Y dijeroná Mardochêolas palabrasde Esther."],[4,13,"Entonces dijoMardochêoque respondiesenáEsther: Nopiensesen tu alma, que escaparásen la casadel reymás que todos los Judíos:","Entonces dijoMardochêoque respondiesenáEsther: Nopiensesen tu alma, que escaparásen la casadel reymás que todos los Judíos:"],[4,14,"Porquesiabsolutamentecallaresen este tiempo, respiroy libertacióntendránlos Judíosde otraparte; mas túy la casade tupadrepereceréis. ¿Y quiénsabesipara estahorate han hecho llegar al reino?","Porquesiabsolutamentecallaresen este tiempo, respiroy libertacióntendránlos Judíosde otraparte; mas túy la casade tupadrepereceréis. ¿Y quiénsabesipara estahorate han hecho llegar al reino?"],[4,15,"Y Estherdijoque respondiesenáMardochêo:","Y Estherdijoque respondiesenáMardochêo:"],[4,16,"Ve, y junta á todoslos Judíosque se hallanen Susán, y ayunadpormí, y nocomáisnibebáisen tresdías, nochenidía: yotambiéncon misdoncellasayunaréigualmente, y así entraréal rey, aunquenosea conforme á la ley; y si perezco, que perezca.","Ve, y junta á todoslos Judíosque se hallanen Susán, y ayunadpormí, y nocomáisnibebáisen tresdías, nochenidía: yotambiéncon misdoncellasayunaréigualmente, y así entraréal rey, aunquenosea conforme á la ley; y si perezco, que perezca."],[4,17,"Entonces se fuéMardochêo, é hizoconforme á todolo quelemandóEsther.","Entonces se fuéMardochêo, é hizoconforme á todolo quelemandóEsther."],[5,1,"Y ACONTECIÓque al tercerdíase vistióEsthersu vestido real, y púsoseen el patiode adentrode la casadel rey, enfrentedel aposentodel rey: y estaba el reysentadoensu solioregio enel aposentoreal, enfrentede la puertadel aposento.","Y ACONTECIÓque al tercerdíase vistióEsthersu vestido real, y púsoseen el patiode adentrode la casadel rey, enfrentedel aposentodel rey: y estaba el reysentadoensu solioregio enel aposentoreal, enfrentede la puertadel aposento."],[5,2,"Y fué que, como vióá la reinaEstherque estabaen el patio, ella obtuvograciaen sus ojos; y el reyextendióá Estherel cetrode oroquetenía en la mano. Entonces se llegóEsther, y tocóla puntadel cetro.","Y fué que, como vióá la reinaEstherque estabaen el patio, ella obtuvograciaen sus ojos; y el reyextendióá Estherel cetrode oroquetenía en la mano. Entonces se llegóEsther, y tocóla puntadel cetro."],[5,3,"Y dijoel rey: ¿Quétienes, reinaEsther? ¿y cuáles tu petición? Hastala mitaddel reino, se te dará.","Y dijoel rey: ¿Quétienes, reinaEsther? ¿y cuáles tu petición? Hastala mitaddel reino, se te dará."],[5,4,"Y Estherdijo: Sialreyplace, venga hoyel reycon Amánalbanquetequele he hecho.","Y Estherdijo: Sialreyplace, venga hoyel reycon Amánalbanquetequele he hecho."],[5,5,"Y respondióel rey: Daos priesa, llamadá Amán, para hacerlo que Estherha dicho. Vinopues el reycon AmánalbanquetequeEstherdispuso.","Y respondióel rey: Daos priesa, llamadá Amán, para hacerlo que Estherha dicho. Vinopues el reycon AmánalbanquetequeEstherdispuso."],[5,6,"Y dijoel reyá Estheren el banquetedel vino: ¿Cuáles tu petición, y te será otorgada? ¿Cuáles tu demanda? Aunquesea la mitaddel reino, te será concedida.","Y dijoel reyá Estheren el banquetedel vino: ¿Cuáles tu petición, y te será otorgada? ¿Cuáles tu demanda? Aunquesea la mitaddel reino, te será concedida."],[5,7,"Entonces respondióEsther, y dijo: Mi peticióny mi demandaes:","Entonces respondióEsther, y dijo: Mi peticióny mi demandaes:"],[5,8,"Sihe halladograciaen los ojosdel rey, y siplacealreyotorgarmi peticióny hacer mi demanda, que vengael reycon Amánalbanquetequeles dispondré; y mañanaharéconforme á lo queel reyha mandado.","Sihe halladograciaen los ojosdel rey, y siplacealreyotorgarmi peticióny hacer mi demanda, que vengael reycon Amánalbanquetequeles dispondré; y mañanaharéconforme á lo queel reyha mandado."],[5,9,"Y salióAmánaquel díacontentoy alegrede corazón; pero como vióá Mardochêoá la puertadel rey, que nose levantabanise movía desulugar, llenósecontraMardochêodeira.","Y salióAmánaquel díacontentoy alegrede corazón; pero como vióá Mardochêoá la puertadel rey, que nose levantabanise movía desulugar, llenósecontraMardochêodeira."],[5,10,"Mas refrenóseAmán, y vinoá su casa, y envió, é hizovenir sus amigos, y á Zeressu mujer.","Mas refrenóseAmán, y vinoá su casa, y envió, é hizovenir sus amigos, y á Zeressu mujer."],[5,11,"Y refiriólesAmánla gloriade sus riquezas, y la multitudde sus hijos, y todaslas cosas con queel reyle había engrandecidoy con quele había ensalzadosobrelos príncipesy siervosdel rey.","Y refiriólesAmánla gloriade sus riquezas, y la multitudde sus hijos, y todaslas cosas con queel reyle había engrandecidoy con quele había ensalzadosobrelos príncipesy siervosdel rey."],[5,12,"Y añadióAmán: Tambiénla reinaEstherá ningunohizo venirconel reyalbanquetequeella dispuso, sino á mí: y aun para mañanasoy convidadode ella conel rey.","Y añadióAmán: Tambiénla reinaEstherá ningunohizo venirconel reyalbanquetequeella dispuso, sino á mí: y aun para mañanasoy convidadode ella conel rey."],[5,13,"Mas todoestonadame sirvecadavezqueveoal judíoMardochêosentadoá la puertadel rey.","Mas todoestonadame sirvecadavezqueveoal judíoMardochêosentadoá la puertadel rey."],[5,14,"Y díjoleZeressu mujer, y todossus amigos: Haganuna horcaalta de cincuentacodos, y mañanadial reyque cuelguená Mardochêoenella; y entraconel reyalbanquetealegre. Y plugo la cosa enlos ojos de Amán, é hizopreparar la horca.","Y díjoleZeressu mujer, y todossus amigos: Haganuna horcaalta de cincuentacodos, y mañanadial reyque cuelguená Mardochêoenella; y entraconel reyalbanquetealegre. Y plugo la cosa enlos ojos de Amán, é hizopreparar la horca."],[6,1,"AQUELLA nochese le fuéel sueñoal rey, y dijoque le trajesenel librode las memoriasde las cosasde los tiempos: y leyéronlasdelantedel rey.","AQUELLA nochese le fuéel sueñoal rey, y dijoque le trajesenel librode las memoriasde las cosasde los tiempos: y leyéronlasdelantedel rey."],[6,2,"Y hallóseescritoqueMardochêohabía denunciadodeBigthany deTeres, doseunucosdel rey, dela guardadela puerta, quehabíanprocuradometer manoen el reyAssuero.","Y hallóseescritoqueMardochêohabía denunciadodeBigthany deTeres, doseunucosdel rey, dela guardadela puerta, quehabíanprocuradometer manoen el reyAssuero."],[6,3,"Y dijoel rey: ¿Quéhonraó que distinciónse hizoá Mardochêoporesto? Y respondieronlos servidoresdel rey, sus oficiales: Nadase ha hechoconél.","Y dijoel rey: ¿Quéhonraó que distinciónse hizoá Mardochêoporesto? Y respondieronlos servidoresdel rey, sus oficiales: Nadase ha hechoconél."],[6,4,"Entonces dijoel rey: ¿Quiénestá en el patio? Y Amánhabía venidoal patiode afuerade la casadel rey, para decir al reyque hiciese colgará Mardochêoenla horcaqueél le tenía preparada.","Entonces dijoel rey: ¿Quiénestá en el patio? Y Amánhabía venidoal patiode afuerade la casadel rey, para decir al reyque hiciese colgará Mardochêoenla horcaqueél le tenía preparada."],[6,5,"Y los servidoresdel reylerespondieron: He aquíAmánestáen el patio. Y el reydijo: Entre.","Y los servidoresdel reylerespondieron: He aquíAmánestáen el patio. Y el reydijo: Entre."],[6,6,"Entrópues Amán, y el reyle dijo: ¿Quése haráal hombrecuya honradeseael rey? Y dijoAmánen su corazón: ¿A quiéndesearáel reyhacer honramásqueá mí?","Entrópues Amán, y el reyle dijo: ¿Quése haráal hombrecuya honradeseael rey? Y dijoAmánen su corazón: ¿A quiéndesearáel reyhacer honramásqueá mí?"],[6,7,"Y respondióAmánalrey: Alvaróncuya honradeseael rey,","Y respondióAmánalrey: Alvaróncuya honradeseael rey,"],[6,8,"Traiganel vestidorealde queel reyse viste, y el caballoen queel reycabalga, y la coronarealqueestá puestaen su cabeza;","Traiganel vestidorealde queel reyse viste, y el caballoen queel reycabalga, y la coronarealqueestá puestaen su cabeza;"],[6,9,"Y denel vestidoy el caballoenmanode algunode los príncipesmás noblesdel rey, y vistaná aquel varóncuyahonra deseael rey, y llévenloenel caballopor la plazade la ciudad, y pregonendelantede él: Asíse haráal varóncuyahonradeseael rey.","Y denel vestidoy el caballoenmanode algunode los príncipesmás noblesdel rey, y vistaná aquel varóncuyahonra deseael rey, y llévenloenel caballopor la plazade la ciudad, y pregonendelantede él: Asíse haráal varóncuyahonradeseael rey."],[6,10,"Entonces el reydijoá Amán: Date priesa, tomael vestidoy el caballo, como tú has dicho, y hazloasícon el judíoMardochêo, que se sientaá la puertadel rey; noomitasnadade todolo quehas dicho.","Entonces el reydijoá Amán: Date priesa, tomael vestidoy el caballo, como tú has dicho, y hazloasícon el judíoMardochêo, que se sientaá la puertadel rey; noomitasnadade todolo quehas dicho."],[6,11,"Y Amántomóel vestidoy el caballo, y vistióá Mardochêo, y llevóloá caballopor la plazade la ciudad, é hizo pregonardelantede él: Asíse haráal varóncuya honradeseael rey.","Y Amántomóel vestidoy el caballo, y vistióá Mardochêo, y llevóloá caballopor la plazade la ciudad, é hizo pregonardelantede él: Asíse haráal varóncuya honradeseael rey."],[6,12,"Después de esto Mardochêose volvióála puertadel rey, y Amánse fué corriendoásu casa, apesadumbradoy cubiertasu cabeza.","Después de esto Mardochêose volvióála puertadel rey, y Amánse fué corriendoásu casa, apesadumbradoy cubiertasu cabeza."],[6,13,"Contóluego Amáná Zeressu mujer, y á todossus amigos, todolo quele había acontecido: y dijéronlesus sabios, y Zeressu mujer: Side la simientede los Judíoses el Mardochêo, delantede quien has comenzadoá caer, nolo vencerás; antes caeráspor ciertodelantede él.","Contóluego Amáná Zeressu mujer, y á todossus amigos, todolo quele había acontecido: y dijéronlesus sabios, y Zeressu mujer: Side la simientede los Judíoses el Mardochêo, delantede quien has comenzadoá caer, nolo vencerás; antes caeráspor ciertodelantede él."],[6,14,"Aunestaban ellos hablandoconél, cuando los eunucosdel reyllegaronapresurados, para hacer venir á AmánalbanquetequeEstherhabía dispuesto.","Aunestaban ellos hablandoconél, cuando los eunucosdel reyllegaronapresurados, para hacer venir á AmánalbanquetequeEstherhabía dispuesto."],[7,1,"VINO pues el reycon Amáná beber con la reinaEsther.","VINO pues el reycon Amáná beber con la reinaEsther."],[7,2,"Y también el segundodíadijoel reyá Estheren el convite del vino: ¿Cuáles tu petición, reinaEsther, y se te concederá? ¿Cuáles pues tu demanda? Aunquesea la mitaddel reino, pondráse por obra.","Y también el segundodíadijoel reyá Estheren el convite del vino: ¿Cuáles tu petición, reinaEsther, y se te concederá? ¿Cuáles pues tu demanda? Aunquesea la mitaddel reino, pondráse por obra."],[7,3,"Entonces la reinaEstherrespondióy dijo: Oh rey, sihe halladograciaen tus ojos, y sialreyplace, séame dadami vidapor mi petición, y mi pueblopor mi demanda.","Entonces la reinaEstherrespondióy dijo: Oh rey, sihe halladograciaen tus ojos, y sialreyplace, séame dadami vidapor mi petición, y mi pueblopor mi demanda."],[7,4,"Porquevendidosestamos yoy mipueblo, para ser destruídos, para ser muertosy exterminados. Y sipara siervosy siervasfuéramos vendidos, callárame, bien que el enemigo no compensara el dañodel rey.","Porquevendidosestamos yoy mipueblo, para ser destruídos, para ser muertosy exterminados. Y sipara siervosy siervasfuéramos vendidos, callárame, bien que el enemigo no compensara el dañodel rey."],[7,5,"Y respondióel reyAssuero, y dijoá la reinaEsther: ¿Quiénes, y dónde está, aquél á quien ha henchido sucorazónpara obrarasí?","Y respondióel reyAssuero, y dijoá la reinaEsther: ¿Quiénes, y dónde está, aquél á quien ha henchido sucorazónpara obrarasí?"],[7,6,"Y Estherdijo: El enemigoy adversarioes este malvadoAmán. Entonces se turbóAmándelantedel reyy de la reina.","Y Estherdijo: El enemigoy adversarioes este malvadoAmán. Entonces se turbóAmándelantedel reyy de la reina."],[7,7,"Levantóseluego el reydel banquetedel vino en su furor, y se fuéalhuertodel palacio: y quedóseAmánpara procurarde la reinaEstherporsu vida; porquevióqueestaba resueltopara élel malde partedel rey.","Levantóseluego el reydel banquetedel vino en su furor, y se fuéalhuertodel palacio: y quedóseAmánpara procurarde la reinaEstherporsu vida; porquevióqueestaba resueltopara élel malde partedel rey."],[7,8,"Volviódespués el reydel huertodel palacioalaposentodel banquetedel vino, y Amánhabía caídosobreel lechoen queestaba Esther. Entonces dijoel rey: ¿Tambiénpara forzar la reina, estandoconmigo en casa? Como esta palabrasalióde la bocadel rey, el rostrode Amánfué cubierto.","Volviódespués el reydel huertodel palacioalaposentodel banquetedel vino, y Amánhabía caídosobreel lechoen queestaba Esther. Entonces dijoel rey: ¿Tambiénpara forzar la reina, estandoconmigo en casa? Como esta palabrasalióde la bocadel rey, el rostrode Amánfué cubierto."],[7,9,"Y dijoHarbona, unodelos eunucosde delantedel rey: He aquítambién la horcade cincuentacodosde alturaque hizoAmánpara Mardochêo, el cualhabía habladobienporel rey, está en casade Amán. Entonces el reydijo: Colgadloenella.","Y dijoHarbona, unodelos eunucosde delantedel rey: He aquítambién la horcade cincuentacodosde alturaque hizoAmánpara Mardochêo, el cualhabía habladobienporel rey, está en casade Amán. Entonces el reydijo: Colgadloenella."],[7,10,"Así colgaroná Amánenla horcaqueél había hecho aparejarpara Mardochêo; y apaciguósela iradel rey.","Así colgaroná Amánenla horcaqueél había hecho aparejarpara Mardochêo; y apaciguósela iradel rey."],[8,1,"EL MISMOdíadióel reyAssueroá la reinaEstherla casade Amánenemigode los Judíos; y Mardochêovinodelantedel rey, porqueEstherle declarólo queera respecto de ella.","EL MISMOdíadióel reyAssueroá la reinaEstherla casade Amánenemigode los Judíos; y Mardochêovinodelantedel rey, porqueEstherle declarólo queera respecto de ella."],[8,2,"Y quitóseel reysu anilloquehabía vuelto á tomarde Amán, y dióloá Mardochêo. Y Estherpusoá Mardochêosobrela casade Amán.","Y quitóseel reysu anilloquehabía vuelto á tomarde Amán, y dióloá Mardochêo. Y Estherpusoá Mardochêosobrela casade Amán."],[8,3,"Volvióluego Estherá hablardelantedel rey, y echóseá sus pies, llorandoy rogándoleque hiciese nulala maldadde AmánAgageo, y su designioquehabía formado contralos Judíos.","Volvióluego Estherá hablardelantedel rey, y echóseá sus pies, llorandoy rogándoleque hiciese nulala maldadde AmánAgageo, y su designioquehabía formado contralos Judíos."],[8,4,"Entonces extendióel reyá Estherel cetrode oro, y Estherse levantó, y púsose en piedelantedel rey.","Entonces extendióel reyá Estherel cetrode oro, y Estherse levantó, y púsose en piedelantedel rey."],[8,5,"Y dijo: Siplacealrey, y sihe halladograciadelantede él, y sila cosa es recta delantedel rey, y agradableyoen sus ojos, sea escritopara revocarlas letrasdel designiode Amánhijode AmadathaAgageo, que escribiópara destruirá los Judíosque están en todaslas provinciasdel rey.","Y dijo: Siplacealrey, y sihe halladograciadelantede él, y sila cosa es recta delantedel rey, y agradableyoen sus ojos, sea escritopara revocarlas letrasdel designiode Amánhijode AmadathaAgageo, que escribiópara destruirá los Judíosque están en todaslas provinciasdel rey."],[8,6,"Porque¿cómopodréyo verel malquealcanzaráá mi pueblo? ¿cómopodréyo verla destrucciónde mi nación?","Porque¿cómopodréyo verel malquealcanzaráá mi pueblo? ¿cómopodréyo verla destrucciónde mi nación?"],[8,7,"Y respondióel reyAssueroá la reinaEsther, y á MardochêoJudío: He aquíyo he dadoá Estherla casade Amán, y á él han colgadoenla horca, porcuantoextendiósu manocontra los Judíos.","Y respondióel reyAssueroá la reinaEsther, y á MardochêoJudío: He aquíyo he dadoá Estherla casade Amán, y á él han colgadoenla horca, porcuantoextendiósu manocontra los Judíos."],[8,8,"Escribidpues vosotrosálos Judíoscomo bienospareciereen el nombredel rey, y selladlocon el anillodel rey; porquela escrituraquese escribeen nombredel rey, y se sellacon el anillodel rey, noes para revocarla.","Escribidpues vosotrosálos Judíoscomo bienospareciereen el nombredel rey, y selladlocon el anillodel rey; porquela escrituraquese escribeen nombredel rey, y se sellacon el anillodel rey, noes para revocarla."],[8,9,"Entonces fueron llamadoslos escribanosdel reyen el mestercero, quees Siván, á veintitrésdel mismo; y escribióseconforme á todolo quemandóMardochêo, á los Judíos, y á los sátrapas, y á los capitanes, y á los príncipesde las provinciasquehabía desde la Indiahastala Ethiopía, cientoveintisieteprovincias; á cada provinciasegún suescribir, y á cada puebloconforme á sulengua, á los Judíostambién conforme á suescrituray lengua.","Entonces fueron llamadoslos escribanosdel reyen el mestercero, quees Siván, á veintitrésdel mismo; y escribióseconforme á todolo quemandóMardochêo, á los Judíos, y á los sátrapas, y á los capitanes, y á los príncipesde las provinciasquehabía desde la Indiahastala Ethiopía, cientoveintisieteprovincias; á cada provinciasegún suescribir, y á cada puebloconforme á sulengua, á los Judíostambién conforme á suescrituray lengua."],[8,10,"Y escribióen nombredel reyAssuero, y sellócon el anillodel rey, y envióletrasporcorreosde á caballo, montados en dromedarios, yen mulos hijos de yeguas;","Y escribióen nombredel reyAssuero, y sellócon el anillodel rey, y envióletrasporcorreosde á caballo, montados en dromedarios, yen mulos hijos de yeguas;"],[8,11,"Con intimaciónde queel reyconcedíaá los Judíosqueestaban en todaslas ciudades, quese juntaseny estuviesen á la defensade su vida, prontosá destruir, y matar, y acabar con todoejércitode puebloó provinciaqueviniesecontra ellos, aunniñosy mujeres, y su despojo para presa,","Con intimaciónde queel reyconcedíaá los Judíosqueestaban en todaslas ciudades, quese juntaseny estuviesen á la defensade su vida, prontosá destruir, y matar, y acabar con todoejércitode puebloó provinciaqueviniesecontra ellos, aunniñosy mujeres, y su despojo para presa,"],[8,12,"En unmismo díaen todaslas provinciasdel reyAssuero, en el trecedel mesduodécimo, quees el mesde Adar.","En unmismo díaen todaslas provinciasdel reyAssuero, en el trecedel mesduodécimo, quees el mesde Adar."],[8,13,"La copiade la escrituraque había de darsepor ordenanza en cadaprovincia, para quefuese manifiestaá todoslos pueblos, decíaquelos Judíosestuviesen apercibidospara aquel día, para vengarsede sus enemigos.","La copiade la escrituraque había de darsepor ordenanza en cadaprovincia, para quefuese manifiestaá todoslos pueblos, decíaquelos Judíosestuviesen apercibidospara aquel día, para vengarsede sus enemigos."],[8,14,"Los correospues, cabalgando en dromedarios yen mulos, salieronapresuradosy constreñidos por el mandamientodel rey: y la leyfué dadaen Susáncapitaldel reino.","Los correospues, cabalgando en dromedarios yen mulos, salieronapresuradosy constreñidos por el mandamientodel rey: y la leyfué dadaen Susáncapitaldel reino."],[8,15,"Y salióMardochêode delantedel reycon vestidorealde cárdenoy blanco, y una grancoronade oro, y un mantode linoy púrpura: y la ciudadde Susánse alegróy regocijó.","Y salióMardochêode delantedel reycon vestidorealde cárdenoy blanco, y una grancoronade oro, y un mantode linoy púrpura: y la ciudadde Susánse alegróy regocijó."],[8,16,"Los Judíostuvieronluzy alegría, y gozoy honra.","Los Judíostuvieronluzy alegría, y gozoy honra."],[8,17,"Y en cadaprovinciay en cadaciudaddondellegóel mandamientodel rey, los Judíostuvieron alegríay gozo, banquetey díade placer. Y muchosde los pueblosde la tierrase hacían Judíos, porqueel temorde los Judíoshabía caídosobreellos.","Y en cadaprovinciay en cadaciudaddondellegóel mandamientodel rey, los Judíostuvieron alegríay gozo, banquetey díade placer. Y muchosde los pueblosde la tierrase hacían Judíos, porqueel temorde los Judíoshabía caídosobreellos."],[9,1,"Y EN el mesduodécimo, quees el mesde Adar, á trecedel mismo, en el quetocaba se ejecutaseel mandamientodel reyy suley, el mismodíaen queesperabanlos enemigosde los Judíosenseñorearsede ellos, fué lo contrario; porquelos Judíosse enseñorearonde los que losaborrecían.","Y EN el mesduodécimo, quees el mesde Adar, á trecedel mismo, en el quetocaba se ejecutaseel mandamientodel reyy suley, el mismodíaen queesperabanlos enemigosde los Judíosenseñorearsede ellos, fué lo contrario; porquelos Judíosse enseñorearonde los que losaborrecían."],[9,2,"Los Judíosse juntaronen sus ciudadesen todaslas provinciasdel reyAssuero, para meter manosobre los que habían procuradosu mal: y nadiese puso delante de ellos, porqueel temorde ellos había caídosobretodoslos pueblos.","Los Judíosse juntaronen sus ciudadesen todaslas provinciasdel reyAssuero, para meter manosobre los que habían procuradosu mal: y nadiese puso delante de ellos, porqueel temorde ellos había caídosobretodoslos pueblos."],[9,3,"Y todoslos príncipesde las provincias, y los virreyes, y capitanes, y oficialesdel rey, ensalzabaná los Judíos; porqueel temorde Mardochêohabía caídosobreellos.","Y todoslos príncipesde las provincias, y los virreyes, y capitanes, y oficialesdel rey, ensalzabaná los Judíos; porqueel temorde Mardochêohabía caídosobreellos."],[9,4,"Porque Mardochêoera grandeen la casadel rey, y su famaibapor todaslas provincias; puesel varón Mardochêoibaengrandeciéndose.","Porque Mardochêoera grandeen la casadel rey, y su famaibapor todaslas provincias; puesel varón Mardochêoibaengrandeciéndose."],[9,5,"E hirieronlos Judíosá todossus enemigoscon plagade espada, y de mortandad, y de perdición; é hicieronen sus enemigosá su voluntad.","E hirieronlos Judíosá todossus enemigoscon plagade espada, y de mortandad, y de perdición; é hicieronen sus enemigosá su voluntad."],[9,6,"Y en Susáncapitaldel reino, matarony destruyeronlos Judíosá quinientoshombres.","Y en Susáncapitaldel reino, matarony destruyeronlos Judíosá quinientoshombres."],[9,7,"Mataron entonces á Phorsandatha, y á Dalphón, y á Asphatha,","Mataron entonces á Phorsandatha, y á Dalphón, y á Asphatha,"],[9,8,"Y á Phorathay á Ahalía, y á Aridatha,","Y á Phorathay á Ahalía, y á Aridatha,"],[9,9,"Y á Pharmastha, y á Arisai, y á Aridai, y á Vaizatha,","Y á Pharmastha, y á Arisai, y á Aridai, y á Vaizatha,"],[9,10,"Diezhijosde Amánhijode Amadatha, enemigode los Judíos: mas en la presanometieronsu mano.","Diezhijosde Amánhijode Amadatha, enemigode los Judíos: mas en la presanometieronsu mano."],[9,11,"El mismo díavino la cuentade los muertosen Susánresidenciaregia, delantedel rey.","El mismo díavino la cuentade los muertosen Susánresidenciaregia, delantedel rey."],[9,12,"Y dijoel reyá la reinaEsther: En Susán, capitaldel reino, han muerto los Judíosy destruído á quinientoshombres, y á diezhijosde Amán; ¿quéhabrán hechoen las otrasprovinciasdel rey? ¿Cuálpues es tupetición, y te será concedida? ¿ó quémáses tudemanda, y será hecho?","Y dijoel reyá la reinaEsther: En Susán, capitaldel reino, han muerto los Judíosy destruído á quinientoshombres, y á diezhijosde Amán; ¿quéhabrán hechoen las otrasprovinciasdel rey? ¿Cuálpues es tupetición, y te será concedida? ¿ó quémáses tudemanda, y será hecho?"],[9,13,"Y respondióEsther: Siplacealrey, concédasetambiénmañanaá los Judíosen Susán, que haganconforme á la leyde hoy; y que cuelguenenla horcaá los diezhijosde Amán.","Y respondióEsther: Siplacealrey, concédasetambiénmañanaá los Judíosen Susán, que haganconforme á la leyde hoy; y que cuelguenenla horcaá los diezhijosde Amán."],[9,14,"Y mandóel reyque se hicieseasí: y diósela ordenen Susán, y colgaroná los diezhijosde Amán.","Y mandóel reyque se hicieseasí: y diósela ordenen Susán, y colgaroná los diezhijosde Amán."],[9,15,"Y los Judíosqueestaban en Susán, se juntarontambiénel catorcedel mesde Adar, y mataronen Susántrescientoshombres: mas en la presanometieronsu mano.","Y los Judíosqueestaban en Susán, se juntarontambiénel catorcedel mesde Adar, y mataronen Susántrescientoshombres: mas en la presanometieronsu mano."],[9,16,"En cuanto á los otrosJudíosque estaban enlas provinciasdel rey, también se juntarony pusiéronseen defensade su vida, y tuvieron reposode sus enemigos, y mataronde sus contrariossetentay cincomil; mas en la presanometieronsu mano.","En cuanto á los otrosJudíosque estaban enlas provinciasdel rey, también se juntarony pusiéronseen defensade su vida, y tuvieron reposode sus enemigos, y mataronde sus contrariossetentay cincomil; mas en la presanometieronsu mano."],[9,17,"En el díatrecedel mesde Adarfué esto; y reposaronen el díacatorcedel mismo, é hiciéronlodíade banquetey de alegría.","En el díatrecedel mesde Adarfué esto; y reposaronen el díacatorcedel mismo, é hiciéronlodíade banquetey de alegría."],[9,18,"Mas los Judíosqueestaban en Susánse juntaronen el trecey en el catorcedel mismo mes; y al quincedel mismo reposaron, é hicieronaquel díadíade banquetey de regocijo.","Mas los Judíosqueestaban en Susánse juntaronen el trecey en el catorcedel mismo mes; y al quincedel mismo reposaron, é hicieronaquel díadíade banquetey de regocijo."],[9,19,"Portantolos Judíosaldeanosque habitanen las villassin muro, hacená los catorcedel mesde Adarel díade alegríay de banquete, y buen día, y de enviarporcionescadauno á su vecino.","Portantolos Judíosaldeanosque habitanen las villassin muro, hacená los catorcedel mesde Adarel díade alegríay de banquete, y buen día, y de enviarporcionescadauno á su vecino."],[9,20,"Y escribióMardochêoestas cosas, y envióletrasátodoslos Judíosqueestaban en todaslas provinciasdel reyAssuero, cercanosy distantes,","Y escribióMardochêoestas cosas, y envióletrasátodoslos Judíosqueestaban en todaslas provinciasdel reyAssuero, cercanosy distantes,"],[9,21,"Ordenándolesque celebrasenel díadécimocuartodel mesde Adar, y el décimoquintodel mismo, cadaun año,","Ordenándolesque celebrasenel díadécimocuartodel mesde Adar, y el décimoquintodel mismo, cadaun año,"],[9,22,"Como díasen quelos Judíostuvieron reposode susenemigos, y el mesquese les tornó de tristezaen alegría, y de lutoen díabueno; quelos hiciesendíasde banquetey de gozo, y de enviarporcionescada unoá su vecino, y dádivasá los pobres.","Como díasen quelos Judíostuvieron reposode susenemigos, y el mesquese les tornó de tristezaen alegría, y de lutoen díabueno; quelos hiciesendíasde banquetey de gozo, y de enviarporcionescada unoá su vecino, y dádivasá los pobres."],[9,23,"Y los Judíosaceptaronhacer, segúnhabían comenzado, lo quelesescribióMardochêo.","Y los Judíosaceptaronhacer, segúnhabían comenzado, lo quelesescribióMardochêo."],[9,24,"PorqueAmánhijode Amadatha, Agageo, enemigode todoslos Judíos, había ideadocontralos Judíospara destruirlos, y echó Pur, quequiere decir suerte, para consumirlosy acabarcon ellos.","PorqueAmánhijode Amadatha, Agageo, enemigode todoslos Judíos, había ideadocontralos Judíospara destruirlos, y echó Pur, quequiere decir suerte, para consumirlosy acabarcon ellos."],[9,25,"Mas como Esther vinoá la presenciadel rey, él intimó porcarta: El perversodesignioque aquél trazócontralos Judíos, recaiga sobresu cabeza; y cuélguenlo á él y á sus hijosenla horca.","Mas como Esther vinoá la presenciadel rey, él intimó porcarta: El perversodesignioque aquél trazócontralos Judíos, recaiga sobresu cabeza; y cuélguenlo á él y á sus hijosenla horca."],[9,26,"Porestollamaroná estos díasPurim, del nombrePur. Portodas las palabraspues de esta carta, y porlo queellos vieronsobreesto, y lo quellegóásu noticia,","Porestollamaroná estos díasPurim, del nombrePur. Portodas las palabraspues de esta carta, y porlo queellos vieronsobreesto, y lo quellegóásu noticia,"],[9,27,"Establecierony tomaronlos Judíossobresí, y sobresu simiente, y sobretodoslos allegadosá ellos, y noserá traspasado, el celebrarestos dosdíassegún está escritoen orden á ellos, y conforme á su tiempocadaun año;","Establecierony tomaronlos Judíossobresí, y sobresu simiente, y sobretodoslos allegadosá ellos, y noserá traspasado, el celebrarestos dosdíassegún está escritoen orden á ellos, y conforme á su tiempocadaun año;"],[9,28,"Y que estos dos díasserían en memoria, y celebradosen todaslas naciones, y familias, y provincias, y ciudades. Estos díasde Purimnopasaránde entre los Judíos, y la memoriade ellos nocesaráde su simiente.","Y que estos dos díasserían en memoria, y celebradosen todaslas naciones, y familias, y provincias, y ciudades. Estos díasde Purimnopasaránde entre los Judíos, y la memoriade ellos nocesaráde su simiente."],[9,29,"Y la reinaEstherhijade Abihail, y MardochêoJudío, escribieroncon todaeficacia, para confirmar esta segundacartade Purim.","Y la reinaEstherhijade Abihail, y MardochêoJudío, escribieroncon todaeficacia, para confirmar esta segundacartade Purim."],[9,30,"Y envióMardochêoletrasátodoslos Judíos, álas cientoveintisieteprovinciasdel reyAssuero, con palabrasde pazy de verdad,","Y envióMardochêoletrasátodoslos Judíos, álas cientoveintisieteprovinciasdel reyAssuero, con palabrasde pazy de verdad,"],[9,31,"Para confirmarestos díasde Purimen sus tiemposseñalados, según leshabía constituído MardochêoJudíoy la reinaEsther, y como habían ellos tomado sobresíy sobresu simiente, para conmemorarel finde los ayunosy de su clamor.","Para confirmarestos díasde Purimen sus tiemposseñalados, según leshabía constituído MardochêoJudíoy la reinaEsther, y como habían ellos tomado sobresíy sobresu simiente, para conmemorarel finde los ayunosy de su clamor."],[9,32,"Y el mandamientode Estherconfirmóestas palabras dadasacerca de Purim, y escribióseen el libro.","Y el mandamientode Estherconfirmóestas palabras dadasacerca de Purim, y escribióseen el libro."],[10,1,"Y EL reyAssueroimpusotributosobrela tierray las islasde la mar.","Y EL reyAssueroimpusotributosobrela tierray las islasde la mar."],[10,2,"Y todala obrade su fortaleza, y de su valor, y la declaración de la grandezade Mardochêo, con queel reyle engrandeció, ¿noestá escritoenel librode los anales de los reyesde Mediay de Persia?","Y todala obrade su fortaleza, y de su valor, y la declaración de la grandezade Mardochêo, con queel reyle engrandeció, ¿noestá escritoenel librode los anales de los reyesde Mediay de Persia?"],[10,3,"PorqueMardochêoJudíofué segundodespués del reyAssuero, y grandeentre los Judíos, y acepto á la multitudde sus hermanos, procurandoel biende su pueblo, y hablandopazpara todasu simiente.","PorqueMardochêoJudíofué segundodespués del reyAssuero, y grandeentre los Judíos, y acepto á la multitudde sus hermanos, procurandoel biende su pueblo, y hablandopazpara todasu simiente."]],"rus-synodal":[[1,1,"И было [после сего] во дни Артаксеркса, – этот Артаксеркс царствовал над ста двадцатью семью областями от Индии и до Ефиопии, –","I bylo [posle sego] vo dni Artakserksa, – étot Artakserks carstvoval nad sta dvadcatʹû semʹû oblastâmi ot Indii i do Efiopii, –"],[1,2,"в то время, как царь Артаксеркс сел на царский престол свой, что в Сузах, городе престольном,","v to vremâ, kak carʹ Artakserks sel na carskij prestol svoj, čto v Suzah, gorode prestolʹnom,"],[1,3,"в третий год своего царствования он сделал пир для всех князей своих и для служащих при нем, для главных начальников войска Персидского и Мидийского и для правителей областей своих,","v tretij god svoego carstvovaniâ on sdelal pir dlâ vseh knâzej svoih i dlâ služaŝih pri nem, dlâ glavnyh načalʹnikov vojska Persidskogo i Midijskogo i dlâ pravitelej oblastej svoih,"],[1,4,"показывая великое богатство царства своего и отличный блеск величия своего в течение многих дней, ста восьмидесяти дней.","pokazyvaâ velikoe bogatstvo carstva svoego i otličnyj blesk veličiâ svoego v tečenie mnogih dnej, sta vosʹmidesâti dnej."],[1,5,"По окончании сих дней сделал царь для народа своего, находившегося в престольном городе Сузах, от большого до малого, пир семидневный на садовом дворе дома царского.","Po okončanii sih dnej sdelal carʹ dlâ naroda svoego, nahodivšegosâ v prestolʹnom gorode Suzah, ot bolʹšogo do malogo, pir semidnevnyj na sadovom dvore doma carskogo."],[1,6,"Белые, бумажные, и яхонтового цвета шерстяные ткани, прикрепленные виссонными и пурпуровыми шнурами, висели на серебряных кольцах и мраморных столбах.","Belye, bumažnye, i âhontovogo cveta šerstânye tkani, prikreplennye vissonnymi i purpurovymi šnurami, viseli na serebrânyh kolʹcah i mramornyh stolbah."],[1,7,"Золотые и серебряные ложа были на помосте, устланном камнями зеленого цвета и мрамором, и перламутром, и камнями черного цвета.","Zolotye i serebrânye loža byli na pomoste, ustlannom kamnâmi zelenogo cveta i mramorom, i perlamutrom, i kamnâmi černogo cveta."],[1,8,"Напитки подаваемы были в золотых сосудах и сосудах разнообразных, ценою в тридцать тысяч талантов; и вина царского было множество, по богатству царя. Питье шло чинно, никто не принуждал, потому что царь дал такое приказание всем управляющим в доме его, чтобы делали по воле каждого.","Napitki podavaemy byli v zolotyh sosudah i sosudah raznoobraznyh, cenoû v tridcatʹ tysâč talantov; i vina carskogo bylo množestvo, po bogatstvu carâ. Pitʹe šlo činno, nikto ne prinuždal, potomu čto carʹ dal takoe prikazanie vsem upravlâûŝim v dome ego, čtoby delali po vole každogo."],[1,9,"И царица Астинь сделала также пир для женщин в царском доме царя Артаксеркса.","I carica Astinʹ sdelala takže pir dlâ ženŝin v carskom dome carâ Artakserksa."],[1,10,"В седьмой день, когда развеселилось сердце царя от вина, он сказал Мегуману, Бизфе, Харбоне, Бигфе и Авагфе, Зефару и Каркасу – семи евнухам, служившим пред лицом царя Артаксеркса,","V sedʹmoj denʹ, kogda razveselilosʹ serdce carâ ot vina, on skazal Megumanu, Bizfe, Harbone, Bigfe i Avagfe, Zefaru i Karkasu – semi evnuham, služivšim pred licom carâ Artakserksa,"],[1,11,"чтобы они привели царицу Астинь пред лицо царя в венце царском для того, чтобы показать народам и князьям красоту ее; потому что она была очень красива.","čtoby oni priveli caricu Astinʹ pred lico carâ v vence carskom dlâ togo, čtoby pokazatʹ narodam i knâzʹâm krasotu ee; potomu čto ona byla očenʹ krasiva."],[1,12,"Но царица Астинь не захотела прийти по приказанию царя, объявленному чрез евнухов.","No carica Astinʹ ne zahotela prijti po prikazaniû carâ, obʺâvlennomu črez evnuhov."],[1,13,"И разгневался царь сильно, и ярость его загорелась в нем. И сказал царь мудрецам, знающим прежние времена – ибо дела царя делались пред всеми, знающими закон и права, –","I razgnevalsâ carʹ silʹno, i ârostʹ ego zagorelasʹ v nem. I skazal carʹ mudrecam, znaûŝim prežnie vremena – ibo dela carâ delalisʹ pred vsemi, znaûŝimi zakon i prava, –"],[1,14,"приближенными же к нему тогда были: Каршена, Шефар, Адмафа, Фарсис, Мерес, Марсена, Мемухан – семь князей Персидских и Мидийских, которые могли видеть лицо царя и сидели первыми в царстве:","približennymi že k nemu togda byli: Karšena, Šefar, Admafa, Farsis, Meres, Marsena, Memuhan – semʹ knâzej Persidskih i Midijskih, kotorye mogli videtʹ lico carâ i sideli pervymi v carstve:"],[1,15,"как поступить по закону с царицею Астинь за то, что она не сделала по слову царя Артаксеркса, объявленному чрез евнухов?","kak postupitʹ po zakonu s cariceû Astinʹ za to, čto ona ne sdelala po slovu carâ Artakserksa, obʺâvlennomu črez evnuhov?"],[1,16,"И сказал Мемухан пред лицом царя и князей: не пред царем одним виновна царица Астинь, а пред всеми князьями и пред всеми народами, которые по всем областям царя Артаксеркса;","I skazal Memuhan pred licom carâ i knâzej: ne pred carem odnim vinovna carica Astinʹ, a pred vsemi knâzʹâmi i pred vsemi narodami, kotorye po vsem oblastâm carâ Artakserksa;"],[1,17,"потому что поступок царицы дойдет до всех жен, и они будут пренебрегать мужьями своими и говорить: «царь Артаксеркс велел привести царицу Астинь пред лицо свое, а она не пошла».","potomu čto postupok caricy dojdet do vseh žen, i oni budut prenebregatʹ mužʹâmi svoimi i govoritʹ: «carʹ Artakserks velel privesti caricu Astinʹ pred lico svoe, a ona ne pošla»."],[1,18,"Теперь княгини Персидские и Мидийские, которые услышат о поступке царицы, будут то же говорить всем князьям царя; и пренебрежения и огорчения будет довольно.","Teperʹ knâgini Persidskie i Midijskie, kotorye uslyšat o postupke caricy, budut to že govoritʹ vsem knâzʹâm carâ; i prenebreženiâ i ogorčeniâ budet dovolʹno."],[1,19,"Если благоугодно царю, пусть выйдет от него царское постановление и впишется в законы Персидские и Мидийские и не отменяется, о том, что Астинь не будет входить пред лицо царя Артаксеркса, а царское достоинство ее царь передаст другой, которая лучше ее.","Esli blagougodno carû, pustʹ vyjdet ot nego carskoe postanovlenie i vpišetsâ v zakony Persidskie i Midijskie i ne otmenâetsâ, o tom, čto Astinʹ ne budet vhoditʹ pred lico carâ Artakserksa, a carskoe dostoinstvo ee carʹ peredast drugoj, kotoraâ lučše ee."],[1,20,"Когда услышат о сем постановлении царя, которое разойдется по всему царству его, как оно ни велико, тогда все жены будут почитать мужей своих, от большого до малого.","Kogda uslyšat o sem postanovlenii carâ, kotoroe razojdetsâ po vsemu carstvu ego, kak ono ni veliko, togda vse ženy budut počitatʹ mužej svoih, ot bolʹšogo do malogo."],[1,21,"И угодно было слово сие в глазах царя и князей; и сделал царь по слову Мемухана.","I ugodno bylo slovo sie v glazah carâ i knâzej; i sdelal carʹ po slovu Memuhana."],[1,22,"И послал во все области царя письма, писанные в каждую область письменами ее и к каждому народу на языке его, чтобы всякий муж был господином в доме своем, и чтобы это было объявлено каждому на природном языке его.","I poslal vo vse oblasti carâ pisʹma, pisannye v každuû oblastʹ pisʹmenami ee i k každomu narodu na âzyke ego, čtoby vsâkij muž byl gospodinom v dome svoem, i čtoby éto bylo obʺâvleno každomu na prirodnom âzyke ego."],[2,1,"После сего, когда утих гнев царя Артаксеркса, он вспомнил об Астинь и о том, что она сделала, и что было определено о ней.","Posle sego, kogda utih gnev carâ Artakserksa, on vspomnil ob Astinʹ i o tom, čto ona sdelala, i čto bylo opredeleno o nej."],[2,2,"И сказали отроки царя, служившие при нем: пусть бы поискали царю молодых красивых девиц,","I skazali otroki carâ, služivšie pri nem: pustʹ by poiskali carû molodyh krasivyh devic,"],[2,3,"и пусть бы назначил царь наблюдателей во все области своего царства, которые собрали бы всех молодых девиц, красивых видом, в престольный город Сузы, в дом жен под надзор Гегая, царского евнуха, стража жен, и пусть бы выдавали им притиранья [и прочее, что нужно];","i pustʹ by naznačil carʹ nablûdatelej vo vse oblasti svoego carstva, kotorye sobrali by vseh molodyh devic, krasivyh vidom, v prestolʹnyj gorod Suzy, v dom žen pod nadzor Gegaâ, carskogo evnuha, straža žen, i pustʹ by vydavali im pritiranʹâ [i pročee, čto nužno];"],[2,4,"и девица, которая понравится глазам царя, пусть будет царицею вместо Астинь. И угодно было слово это в глазах царя, и он так и сделал.","i devica, kotoraâ ponravitsâ glazam carâ, pustʹ budet cariceû vmesto Astinʹ. I ugodno bylo slovo éto v glazah carâ, i on tak i sdelal."],[2,5,"Был в Сузах, городе престольном, один Иудеянин, имя его Мардохей, сын Иаира, сын Семея, сын Киса, из колена Вениаминова.","Byl v Suzah, gorode prestolʹnom, odin Iudeânin, imâ ego Mardohej, syn Iaira, syn Semeâ, syn Kisa, iz kolena Veniaminova."],[2,6,"Он был переселен из Иерусалима вместе с пленниками, выведенными с Иехониею, царем Иудейским, которых переселил Навуходоносор, царь Вавилонский.","On byl pereselen iz Ierusalima vmeste s plennikami, vyvedennymi s Iehonieû, carem Iudejskim, kotoryh pereselil Navuhodonosor, carʹ Vavilonskij."],[2,7,"И был он воспитателем Гадассы, – она же Есфирь, – дочери дяди его, так как не было у нее ни отца, ни матери. Девица эта была красива станом и пригожа лицом. И по смерти отца ее и матери ее Мардохей взял ее к себе вместо дочери.","I byl on vospitatelem Gadassy, – ona že Esfirʹ, – dočeri dâdi ego, tak kak ne bylo u nee ni otca, ni materi. Devica éta byla krasiva stanom i prigoža licom. I po smerti otca ee i materi ee Mardohej vzâl ee k sebe vmesto dočeri."],[2,8,"Когда объявлено было повеление царя и указ его, и когда собраны были многие девицы в престольный город Сузы под надзор Гегая, тогда взята была и Есфирь в царский дом под надзор Гегая, стража жен.","Kogda obʺâvleno bylo povelenie carâ i ukaz ego, i kogda sobrany byli mnogie devicy v prestolʹnyj gorod Suzy pod nadzor Gegaâ, togda vzâta byla i Esfirʹ v carskij dom pod nadzor Gegaâ, straža žen."],[2,9,"И понравилась эта девица глазам его и приобрела у него благоволение, и он поспешил выдать ей притиранья и все, назначенное на часть ее, и приставить к ней семь девиц, достойных быть при ней, из дома царского, и переместил ее и девиц ее в лучшее отделение женского дома.","I ponravilasʹ éta devica glazam ego i priobrela u nego blagovolenie, i on pospešil vydatʹ ej pritiranʹâ i vse, naznačennoe na častʹ ee, i pristavitʹ k nej semʹ devic, dostojnyh bytʹ pri nej, iz doma carskogo, i peremestil ee i devic ee v lučšee otdelenie ženskogo doma."],[2,10,"Не сказывала Есфирь ни о народе своем, ни о родстве своем, потому что Мардохей дал ей приказание, чтобы она не сказывала.","Ne skazyvala Esfirʹ ni o narode svoem, ni o rodstve svoem, potomu čto Mardohej dal ej prikazanie, čtoby ona ne skazyvala."],[2,11,"И всякий день Мардохей приходил ко двору женского дома, чтобы наведываться о здоровье Есфири и о том, что делается с нею.","I vsâkij denʹ Mardohej prihodil ko dvoru ženskogo doma, čtoby navedyvatʹsâ o zdorovʹe Esfiri i o tom, čto delaetsâ s neû."],[2,12,"Когда наступало время каждой девице входить к царю Артаксерксу, после того, как в течение двенадцати месяцев выполнено было над нею все, определенное женщинам, – ибо столько времени продолжались дни притиранья их: шесть месяцев мирровым маслом и шесть месяцев ароматами и другими притираньями женскими, –","Kogda nastupalo vremâ každoj device vhoditʹ k carû Artakserksu, posle togo, kak v tečenie dvenadcati mesâcev vypolneno bylo nad neû vse, opredelennoe ženŝinam, – ibo stolʹko vremeni prodolžalisʹ dni pritiranʹâ ih: šestʹ mesâcev mirrovym maslom i šestʹ mesâcev aromatami i drugimi pritiranʹâmi ženskimi, –"],[2,13,"Тогда девица входила к царю. Чего бы она ни потребовала, ей давали все для выхода из женского дома в дом царя.","Togda devica vhodila k carû. Čego by ona ni potrebovala, ej davali vse dlâ vyhoda iz ženskogo doma v dom carâ."],[2,14,"Вечером она входила и утром возвращалась в другой дом женский под надзор Шаазгаза, царского евнуха, стража наложниц; и уже не входила к царю, разве только царь пожелал бы ее, и она призывалась бы по имени.","Večerom ona vhodila i utrom vozvraŝalasʹ v drugoj dom ženskij pod nadzor Šaazgaza, carskogo evnuha, straža naložnic; i uže ne vhodila k carû, razve tolʹko carʹ poželal by ee, i ona prizyvalasʹ by po imeni."],[2,15,"Когда настало время Есфири, дочери Аминадава, дяди Мардохея, который взял ее к себе вместо дочери, – идти к царю, тогда она не просила ничего, кроме того, о чем сказал ей Гегай, евнух царский, страж жен. И приобрела Есфирь расположение к себе в глазах всех, видевших ее.","Kogda nastalo vremâ Esfiri, dočeri Aminadava, dâdi Mardoheâ, kotoryj vzâl ee k sebe vmesto dočeri, – idti k carû, togda ona ne prosila ničego, krome togo, o čem skazal ej Gegaj, evnuh carskij, straž žen. I priobrela Esfirʹ raspoloženie k sebe v glazah vseh, videvših ee."],[2,16,"И взята была Есфирь к царю Артаксерксу, в царский дом его, в десятом месяце, то есть в месяце Тебефе, в седьмой год его царствования.","I vzâta byla Esfirʹ k carû Artakserksu, v carskij dom ego, v desâtom mesâce, to estʹ v mesâce Tebefe, v sedʹmoj god ego carstvovaniâ."],[2,17,"И полюбил царь Есфирь более всех жен, и она приобрела его благоволение и благорасположение более всех девиц; и он возложил царский венец на голову ее и сделал ее царицею на место Астинь.","I polûbil carʹ Esfirʹ bolee vseh žen, i ona priobrela ego blagovolenie i blagoraspoloženie bolee vseh devic; i on vozložil carskij venec na golovu ee i sdelal ee cariceû na mesto Astinʹ."],[2,18,"И сделал царь большой пир для всех князей своих и для служащих при нем, – пир ради Есфири, и сделал льготу областям и раздал дары с царственною щедростью.","I sdelal carʹ bolʹšoj pir dlâ vseh knâzej svoih i dlâ služaŝih pri nem, – pir radi Esfiri, i sdelal lʹgotu oblastâm i razdal dary s carstvennoû ŝedrostʹû."],[2,19,"И когда во второй раз собраны были девицы, и Мардохей сидел у ворот царских,","I kogda vo vtoroj raz sobrany byli devicy, i Mardohej sidel u vorot carskih,"],[2,20,"Есфирь все еще не сказывала о родстве своем и о народе своем, как приказал ей Мардохей; а слово Мардохея Есфирь выполняла и теперь так же, как тогда, когда была у него на воспитании.","Esfirʹ vse eŝe ne skazyvala o rodstve svoem i o narode svoem, kak prikazal ej Mardohej; a slovo Mardoheâ Esfirʹ vypolnâla i teperʹ tak že, kak togda, kogda byla u nego na vospitanii."],[2,21,"В это время, как Мардохей сидел у ворот царских, два царских евнуха, Гавафа и Фарра, оберегавшие порог, озлобились [за то, что предпочтен был Мардохей] и замышляли наложить руку на царя Артаксеркса.","V éto vremâ, kak Mardohej sidel u vorot carskih, dva carskih evnuha, Gavafa i Farra, oberegavšie porog, ozlobilisʹ [za to, čto predpočten byl Mardohej] i zamyšlâli naložitʹ ruku na carâ Artakserksa."],[2,22,"Узнав о том, Мардохей сообщил царице Есфири, а Есфирь сказала царю от имени Мардохея.","Uznav o tom, Mardohej soobŝil carice Esfiri, a Esfirʹ skazala carû ot imeni Mardoheâ."],[2,23,"Дело было исследовано и найдено верным, и их обоих повесили на дереве. И было вписано о благодеянии Мардохея в книгу дневных записей у царя.","Delo bylo issledovano i najdeno vernym, i ih oboih povesili na dereve. I bylo vpisano o blagodeânii Mardoheâ v knigu dnevnyh zapisej u carâ."],[3,1,"После сего возвеличил царь Артаксеркс Амана, сына Амадафа, Вугеянина, и вознес его, и поставил седалище его выше всех князей, которые у него;","Posle sego vozveličil carʹ Artakserks Amana, syna Amadafa, Vugeânina, i voznes ego, i postavil sedaliŝe ego vyše vseh knâzej, kotorye u nego;"],[3,2,"и все, служащие при царе, которые были у царских ворот, кланялись и падали ниц пред Аманом, ибо так приказал царь. А Мардохей не кланялся и не падал ниц.","i vse, služaŝie pri care, kotorye byli u carskih vorot, klanâlisʹ i padali nic pred Amanom, ibo tak prikazal carʹ. A Mardohej ne klanâlsâ i ne padal nic."],[3,3,"И говорили служащие при царе, которые у царских ворот, Мардохею: зачем ты преступаешь повеление царское?","I govorili služaŝie pri care, kotorye u carskih vorot, Mardoheû: začem ty prestupaešʹ povelenie carskoe?"],[3,4,"И как они говорили ему каждый день, а он не слушал их, то они донесли Аману, чтобы посмотреть, устоит ли в слове своем Мардохей, ибо он сообщил им, что он Иудеянин.","I kak oni govorili emu každyj denʹ, a on ne slušal ih, to oni donesli Amanu, čtoby posmotretʹ, ustoit li v slove svoem Mardohej, ibo on soobŝil im, čto on Iudeânin."],[3,5,"И когда увидел Аман, что Мардохей не кланяется и не падает ниц пред ним, то исполнился гнева Аман.","I kogda uvidel Aman, čto Mardohej ne klanâetsâ i ne padaet nic pred nim, to ispolnilsâ gneva Aman."],[3,6,"И показалось ему ничтожным наложить руку на одного Мардохея; но так как сказали ему, из какого народа Мардохей, то задумал Аман истребить всех Иудеев, которые были во всем царстве Артаксеркса, как народ Мардохеев.","I pokazalosʹ emu ničtožnym naložitʹ ruku na odnogo Mardoheâ; no tak kak skazali emu, iz kakogo naroda Mardohej, to zadumal Aman istrebitʹ vseh Iudeev, kotorye byli vo vsem carstve Artakserksa, kak narod Mardoheev."],[3,7,"[И сделал совет] в первый месяц, который есть месяц Нисан, в двенадцатый год царя Артаксеркса, бросали пур, то есть жребий, пред лицом Амана изо дня в день и из месяца в месяц, [чтобы в один день погубить народ Мардохеев, и пал жребий] на двенадцатый месяц, то есть на месяц Адар.","[I sdelal sovet] v pervyj mesâc, kotoryj estʹ mesâc Nisan, v dvenadcatyj god carâ Artakserksa, brosali pur, to estʹ žrebij, pred licom Amana izo dnâ v denʹ i iz mesâca v mesâc, [čtoby v odin denʹ pogubitʹ narod Mardoheev, i pal žrebij] na dvenadcatyj mesâc, to estʹ na mesâc Adar."],[3,8,"И сказал Аман царю Артаксерксу: есть один народ, разбросанный и рассеянный между народами по всем областям царства твоего; и законы их отличны от законов всех народов, и законов царя они не выполняют; и царю не следует так оставлять их.","I skazal Aman carû Artakserksu: estʹ odin narod, razbrosannyj i rasseânnyj meždu narodami po vsem oblastâm carstva tvoego; i zakony ih otličny ot zakonov vseh narodov, i zakonov carâ oni ne vypolnâût; i carû ne sleduet tak ostavlâtʹ ih."],[3,9,"Если царю благоугодно, то пусть будет предписано истребить их, и десять тысяч талантов серебра я отвешу в руки приставников, чтобы внести в казну царскую.","Esli carû blagougodno, to pustʹ budet predpisano istrebitʹ ih, i desâtʹ tysâč talantov serebra â otvešu v ruki pristavnikov, čtoby vnesti v kaznu carskuû."],[3,10,"Тогда снял царь перстень свой с руки своей и отдал его Аману, сыну Амадафа, Вугеянину, чтобы скрепить указ против Иудеев.","Togda snâl carʹ perstenʹ svoj s ruki svoej i otdal ego Amanu, synu Amadafa, Vugeâninu, čtoby skrepitʹ ukaz protiv Iudeev."],[3,11,"И сказал царь Аману: отдаю тебе это серебро и народ; поступи с ним, как тебе угодно.","I skazal carʹ Amanu: otdaû tebe éto serebro i narod; postupi s nim, kak tebe ugodno."],[3,12,"И призваны были писцы царские в первый месяц, в тринадцатый день его, и написано было, как приказал Аман, к сатрапам царским и к начальствующим над каждою областью [от области Индийской до Ефиопии, над ста двадцатью семью областями], и к князьям у каждого народа, в каждую область письменами ее и к каждому народу на языке его: все было написано от имени царя Артаксеркса и скреплено царским перстнем.","I prizvany byli piscy carskie v pervyj mesâc, v trinadcatyj denʹ ego, i napisano bylo, kak prikazal Aman, k satrapam carskim i k načalʹstvuûŝim nad každoû oblastʹû [ot oblasti Indijskoj do Efiopii, nad sta dvadcatʹû semʹû oblastâmi], i k knâzʹâm u každogo naroda, v každuû oblastʹ pisʹmenami ee i k každomu narodu na âzyke ego: vse bylo napisano ot imeni carâ Artakserksa i skrepleno carskim perstnem."],[3,13,"И посланы были письма через гонцов во все области царя, чтобы убить, погубить и истребить всех Иудеев, малого и старого, детей и женщин в один день, в тринадцатый день двенадцатого месяца, то есть месяца Адара, и имение их разграбить. [Вот список с этого письма: великий царь Артаксеркс начальствующим от Индии до Ефиопии над ста двадцатью семью областями и подчиненным им наместникам. Царствуя над многими народами и властвуя над всею вселенною, я хотел, не превозносясь гордостью власти, но управляя всегда кротко и тихо, сделать жизнь подданных постоянно безмятежною и, соблюдая царство свое мирным и удобопроходимым до пределов его, восстановить желаемый для всех людей мир. Когда же я спросил советников, каким бы образом привести это в исполнение, то отличающийся у нас мудростью и пользующийся неизменным благоволением, и доказавший твердую верность, и получивший вторую честь по царе, Аман объяснил нам, что во всех племенах вселенной замешался один враждебный народ, по законам своим противный всякому народу, постоянно пренебрегающий царскими повелениями, дабы не благоустроялось безукоризненно совершаемое нами соуправление. Итак, узнав, что один только этот народ всегда противится всякому человеку, ведет образ жизни, чуждый законам, и, противясь нашим действиям, совершает величайшие злодеяния, чтобы царство наше не достигло благосостояния, мы повелели указанных вам в грамотах Амана, поставленного над делами и второго отца нашего, всех с женами и детьми всецело истребить вражескими мечами, без всякого сожаления и пощады, в тринадцатый день двенадцатого месяца Адара настоящего года, чтобы эти и прежде и теперь враждебные люди, быв в один день насильно низвергнуты в преисподнюю, не препятствовали нам в последующее время проводить жизнь мирно и безмятежно до конца.]","I poslany byli pisʹma čerez goncov vo vse oblasti carâ, čtoby ubitʹ, pogubitʹ i istrebitʹ vseh Iudeev, malogo i starogo, detej i ženŝin v odin denʹ, v trinadcatyj denʹ dvenadcatogo mesâca, to estʹ mesâca Adara, i imenie ih razgrabitʹ. [Vot spisok s étogo pisʹma: velikij carʹ Artakserks načalʹstvuûŝim ot Indii do Efiopii nad sta dvadcatʹû semʹû oblastâmi i podčinennym im namestnikam. Carstvuâ nad mnogimi narodami i vlastvuâ nad vseû vselennoû, â hotel, ne prevoznosâsʹ gordostʹû vlasti, no upravlââ vsegda krotko i tiho, sdelatʹ žiznʹ poddannyh postoânno bezmâtežnoû i, soblûdaâ carstvo svoe mirnym i udoboprohodimym do predelov ego, vosstanovitʹ želaemyj dlâ vseh lûdej mir. Kogda že â sprosil sovetnikov, kakim by obrazom privesti éto v ispolnenie, to otličaûŝijsâ u nas mudrostʹû i polʹzuûŝijsâ neizmennym blagovoleniem, i dokazavšij tverduû vernostʹ, i polučivšij vtoruû čestʹ po care, Aman obʺâsnil nam, čto vo vseh plemenah vselennoj zamešalsâ odin vraždebnyj narod, po zakonam svoim protivnyj vsâkomu narodu, postoânno prenebregaûŝij carskimi poveleniâmi, daby ne blagoustroâlosʹ bezukoriznenno soveršaemoe nami soupravlenie. Itak, uznav, čto odin tolʹko étot narod vsegda protivitsâ vsâkomu čeloveku, vedet obraz žizni, čuždyj zakonam, i, protivâsʹ našim dejstviâm, soveršaet veličajšie zlodeâniâ, čtoby carstvo naše ne dostiglo blagosostoâniâ, my poveleli ukazannyh vam v gramotah Amana, postavlennogo nad delami i vtorogo otca našego, vseh s ženami i detʹmi vsecelo istrebitʹ vražeskimi mečami, bez vsâkogo sožaleniâ i poŝady, v trinadcatyj denʹ dvenadcatogo mesâca Adara nastoâŝego goda, čtoby éti i prežde i teperʹ vraždebnye lûdi, byv v odin denʹ nasilʹno nizvergnuty v preispodnûû, ne prepâtstvovali nam v posleduûŝee vremâ provoditʹ žiznʹ mirno i bezmâtežno do konca.]"],[3,14,"Список с указа отдать в каждую область как закон, объявляемый для всех народов, чтобы они были готовы к тому дню.","Spisok s ukaza otdatʹ v každuû oblastʹ kak zakon, obʺâvlâemyj dlâ vseh narodov, čtoby oni byli gotovy k tomu dnû."],[3,15,"Гонцы отправились быстро с царским повелением. Объявлен был указ и в Сузах, престольном городе; и царь и Аман сидели и пили, а город Сузы был в смятении.","Goncy otpravilisʹ bystro s carskim poveleniem. Obʺâvlen byl ukaz i v Suzah, prestolʹnom gorode; i carʹ i Aman sideli i pili, a gorod Suzy byl v smâtenii."],[4,1,"Когда Мардохей узнал все, что делалось, разодрал одежды свои и возложил на себя вретище и пепел, и вышел на средину города и взывал с воплем великим и горьким: [истребляется народ ни в чем не повинный!].","Kogda Mardohej uznal vse, čto delalosʹ, razodral odeždy svoi i vozložil na sebâ vretiŝe i pepel, i vyšel na sredinu goroda i vzyval s voplem velikim i gorʹkim: [istreblâetsâ narod ni v čem ne povinnyj!]."],[4,2,"И дошел до царских ворот [и остановился], так как нельзя было входить в царские ворота во вретище [и с пеплом].","I došel do carskih vorot [i ostanovilsâ], tak kak nelʹzâ bylo vhoditʹ v carskie vorota vo vretiŝe [i s peplom]."],[4,3,"Равно и во всякой области и месте, куда только доходило повеление царя и указ его, было большое сетование у Иудеев, и пост, и плач, и вопль; вретище и пепел служили постелью для многих.","Ravno i vo vsâkoj oblasti i meste, kuda tolʹko dohodilo povelenie carâ i ukaz ego, bylo bolʹšoe setovanie u Iudeev, i post, i plač, i voplʹ; vretiŝe i pepel služili postelʹû dlâ mnogih."],[4,4,"И пришли служанки Есфири и евнухи ее и рассказали ей, и сильно встревожилась царица. И послала одежды, чтобы Мардохей надел их и снял с себя вретище свое. Но он не принял.","I prišli služanki Esfiri i evnuhi ee i rasskazali ej, i silʹno vstrevožilasʹ carica. I poslala odeždy, čtoby Mardohej nadel ih i snâl s sebâ vretiŝe svoe. No on ne prinâl."],[4,5,"Тогда позвала Есфирь Гафаха, одного из евнухов царя, которого он приставил к ней, и послала его к Мардохею узнать: что это и отчего это?","Togda pozvala Esfirʹ Gafaha, odnogo iz evnuhov carâ, kotorogo on pristavil k nej, i poslala ego k Mardoheû uznatʹ: čto éto i otčego éto?"],[4,6,"И пошел Гафах к Мардохею на городскую площадь, которая пред царскими воротами.","I pošel Gafah k Mardoheû na gorodskuû ploŝadʹ, kotoraâ pred carskimi vorotami."],[4,7,"И рассказал ему Мардохей обо всем, что с ним случилось, и об определенном числе серебра, которое обещал Аман отвесить в казну царскую за Иудеев, чтобы истребить их;","I rasskazal emu Mardohej obo vsem, čto s nim slučilosʹ, i ob opredelennom čisle serebra, kotoroe obeŝal Aman otvesitʹ v kaznu carskuû za Iudeev, čtoby istrebitʹ ih;"],[4,8,"и вручил ему список с указа, обнародованного в Сузах, об истреблении их, чтобы показать Есфири и дать ей знать обо всем; притом наказывал ей, чтобы она пошла к царю и молила его о помиловании и просила его за народ свой, [вспомнив дни смирения своего, когда она воспитывалась под рукою моею, потому что Аман, второй по царе, осудил нас на смерть, и чтобы призвала Господа и сказала о нас царю, да избавит нас от смерти].","i vručil emu spisok s ukaza, obnarodovannogo v Suzah, ob istreblenii ih, čtoby pokazatʹ Esfiri i datʹ ej znatʹ obo vsem; pritom nakazyval ej, čtoby ona pošla k carû i molila ego o pomilovanii i prosila ego za narod svoj, [vspomniv dni smireniâ svoego, kogda ona vospityvalasʹ pod rukoû moeû, potomu čto Aman, vtoroj po care, osudil nas na smertʹ, i čtoby prizvala Gospoda i skazala o nas carû, da izbavit nas ot smerti]."],[4,9,"И пришел Гафах и пересказал Есфири слова Мардохея.","I prišel Gafah i pereskazal Esfiri slova Mardoheâ."],[4,10,"И сказала Есфирь Гафаху и послала его сказать Мардохею:","I skazala Esfirʹ Gafahu i poslala ego skazatʹ Mardoheû:"],[4,11,"все, служащие при царе, и народы в областях царских знают, что всякому, и мужчине и женщине, кто войдет к царю во внутренний двор, не быв позван, один суд – смерть; только тот, к кому прострет царь свой золотой скипетр, останется жив. А я не звана к царю вот уже тридцать дней.","vse, služaŝie pri care, i narody v oblastâh carskih znaût, čto vsâkomu, i mužčine i ženŝine, kto vojdet k carû vo vnutrennij dvor, ne byv pozvan, odin sud – smertʹ; tolʹko tot, k komu prostret carʹ svoj zolotoj skipetr, ostanetsâ živ. A â ne zvana k carû vot uže tridcatʹ dnej."],[4,12,"И пересказали Мардохею слова Есфири.","I pereskazali Mardoheû slova Esfiri."],[4,13,"И сказал Мардохей в ответ Есфири: не думай, что ты одна спасешься в доме царском из всех Иудеев.","I skazal Mardohej v otvet Esfiri: ne dumaj, čto ty odna spasešʹsâ v dome carskom iz vseh Iudeev."],[4,14,"Если ты промолчишь в это время, то свобода и избавление придет для Иудеев из другого места, а ты и дом отца твоего погибнете. И кто знает, не для такого ли времени ты и достигла достоинства царского?","Esli ty promolčišʹ v éto vremâ, to svoboda i izbavlenie pridet dlâ Iudeev iz drugogo mesta, a ty i dom otca tvoego pogibnete. I kto znaet, ne dlâ takogo li vremeni ty i dostigla dostoinstva carskogo?"],[4,15,"И сказала Есфирь в ответ Мардохею:","I skazala Esfirʹ v otvet Mardoheû:"],[4,16,"пойди, собери всех Иудеев, находящихся в Сузах, и поститесь ради меня, и не ешьте и не пейте три дня, ни днем, ни ночью, и я с служанками моими буду также поститься и потом пойду к царю, хотя это против закона, и если погибнуть – погибну.","pojdi, soberi vseh Iudeev, nahodâŝihsâ v Suzah, i postitesʹ radi menâ, i ne ešʹte i ne pejte tri dnâ, ni dnem, ni nočʹû, i â s služankami moimi budu takže postitʹsâ i potom pojdu k carû, hotâ éto protiv zakona, i esli pogibnutʹ – pogibnu."],[4,17,"И пошел Мардохей и сделал, как приказала ему Есфирь. [И молился он Господу, воспоминая все дела Господни, и говорил: Господи, Господи, Царю, Вседержителю! Все в Твоей власти, и нет противящегося Тебе, когда Ты захочешь спасти Израиля; Ты сотворил небо и землю и все дивное в поднебесной; Ты Господь всех, и нет такого, кто воспротивился бы Тебе, Господу. Ты знаешь все; Ты знаешь, Господи, что не для обиды и не по гордости и не по тщеславию я делал это, что не поклонялся тщеславному Аману, ибо я охотно стал бы лобызать следы ног его для спасения Израиля; но я делал это для того, чтобы не воздать славы человеку выше славы Божией и не поклоняться никому, кроме Тебя, Господа моего, и я не стану делать этого по гордости. И ныне, Господи Боже, Царю, Боже Авраамов, пощади народ Твой; ибо замышляют нам погибель и хотят истребить изначальное наследие Твое; не презри достояния Твоего, которое Ты избавил для Себя из земли Египетской; услышь молитву мою и умилосердись над наследием Твоим и обрати сетование наше в веселие, дабы мы, живя, воспевали имя Твое, Господи, и не погуби уст, прославляющих Тебя, Господи. И все Израильтяне взывали всеми силами своими, потому что смерть их была пред глазами их.] [И царица Есфирь прибегла к Господу, объятая смертною горестью, и, сняв одежды славы своей, облеклась в одежды скорби и сетования, и, вместо многоценных мастей, пеплом и прахом посыпала голову свою, и весьма изнурила тело свое, и всякое место, украшаемое в веселии ее, покрыла распущенными волосами своими, и молилась Господу Богу Израилеву, говоря: Господи мой! Ты один Царь наш; помоги мне, одинокой и не имеющей помощника, кроме Тебя; ибо беда моя близ меня. Я слышала, Господи, от отца моего, в родном колене моем, что Ты, Господи, избрал себе Израиля из всех народов и отцов наших из всех предков их в наследие вечное, и сделал для них то, о чем говорил им. И ныне мы согрешили пред Тобою, и предал Ты нас в руки врагов наших за то, что мы славили богов их: праведен Ты, Господи! А ныне они не удовольствовались горьким рабством нашим, но положили руки свои в руки идолов своих, чтобы ниспровергнуть заповедь уст Твоих, и истребить наследие Твое, и заградить уста воспевающих Тебя, и погасить славу храма Твоего и жертвенника Твоего, и отверзть уста народов на прославление тщетных богов, и царю плотскому величаться вовек. Не предай, Господи, скипетра Твоего богам несуществующим, и пусть не радуются падению нашему, но обрати замысел их на них самих: наветника же против нас предай позору. Помяни, Господи, яви Себя нам во время скорби нашей и дай мне мужество. Царь богов и Владыка всякого начальства! даруй устам моим слово благоприятное пред этим львом и исполни сердце его ненавистью к преследующему нас, на погибель ему и единомышленникам его; нас же избавь рукою Твоею и помоги мне, одинокой и не имеющей помощника, кроме Тебя, Господи. Ты имеешь ведение всего и знаешь, что я ненавижу славу беззаконных и гнушаюсь ложа необрезанных и всякого иноплеменника; Ты знаешь необходимость мою, что я гнушаюсь знака гордости моей, который бывает на голове моей во дни появления моего, гнушаюсь его, как одежды, оскверненной кровью, и не ношу его во дни уединения моего. И не вкушала раба Твоя от трапезы Амана и не дорожила пиром царским, и не пила вина идоложертвенного, и не веселилась раба Твоя со дня перемены судьбы моей доныне, кроме как о Тебе, Господи Боже Авраамов. Боже, имеющий силу над всеми! услышь голос безнадежных, и спаси нас от руки злоумышляющих, и избавь меня от страха моего.]","I pošel Mardohej i sdelal, kak prikazala emu Esfirʹ. [I molilsâ on Gospodu, vospominaâ vse dela Gospodni, i govoril: Gospodi, Gospodi, Carû, Vsederžitelû! Vse v Tvoej vlasti, i net protivâŝegosâ Tebe, kogda Ty zahočešʹ spasti Izrailâ; Ty sotvoril nebo i zemlû i vse divnoe v podnebesnoj; Ty Gospodʹ vseh, i net takogo, kto vosprotivilsâ by Tebe, Gospodu. Ty znaešʹ vse; Ty znaešʹ, Gospodi, čto ne dlâ obidy i ne po gordosti i ne po tŝeslaviû â delal éto, čto ne poklonâlsâ tŝeslavnomu Amanu, ibo â ohotno stal by lobyzatʹ sledy nog ego dlâ spaseniâ Izrailâ; no â delal éto dlâ togo, čtoby ne vozdatʹ slavy čeloveku vyše slavy Božiej i ne poklonâtʹsâ nikomu, krome Tebâ, Gospoda moego, i â ne stanu delatʹ étogo po gordosti. I nyne, Gospodi Bože, Carû, Bože Avraamov, poŝadi narod Tvoj; ibo zamyšlâût nam pogibelʹ i hotât istrebitʹ iznačalʹnoe nasledie Tvoe; ne prezri dostoâniâ Tvoego, kotoroe Ty izbavil dlâ Sebâ iz zemli Egipetskoj; uslyšʹ molitvu moû i umiloserdisʹ nad naslediem Tvoim i obrati setovanie naše v veselie, daby my, živâ, vospevali imâ Tvoe, Gospodi, i ne pogubi ust, proslavlâûŝih Tebâ, Gospodi. I vse Izrailʹtâne vzyvali vsemi silami svoimi, potomu čto smertʹ ih byla pred glazami ih.] [I carica Esfirʹ pribegla k Gospodu, obʺâtaâ smertnoû gorestʹû, i, snâv odeždy slavy svoej, obleklasʹ v odeždy skorbi i setovaniâ, i, vmesto mnogocennyh mastej, peplom i prahom posypala golovu svoû, i vesʹma iznurila telo svoe, i vsâkoe mesto, ukrašaemoe v veselii ee, pokryla raspuŝennymi volosami svoimi, i molilasʹ Gospodu Bogu Izrailevu, govorâ: Gospodi moj! Ty odin Carʹ naš; pomogi mne, odinokoj i ne imeûŝej pomoŝnika, krome Tebâ; ibo beda moâ bliz menâ. Â slyšala, Gospodi, ot otca moego, v rodnom kolene moem, čto Ty, Gospodi, izbral sebe Izrailâ iz vseh narodov i otcov naših iz vseh predkov ih v nasledie večnoe, i sdelal dlâ nih to, o čem govoril im. I nyne my sogrešili pred Toboû, i predal Ty nas v ruki vragov naših za to, čto my slavili bogov ih: praveden Ty, Gospodi! A nyne oni ne udovolʹstvovalisʹ gorʹkim rabstvom našim, no položili ruki svoi v ruki idolov svoih, čtoby nisprovergnutʹ zapovedʹ ust Tvoih, i istrebitʹ nasledie Tvoe, i zagraditʹ usta vospevaûŝih Tebâ, i pogasitʹ slavu hrama Tvoego i žertvennika Tvoego, i otverztʹ usta narodov na proslavlenie tŝetnyh bogov, i carû plotskomu veličatʹsâ vovek. Ne predaj, Gospodi, skipetra Tvoego bogam nesuŝestvuûŝim, i pustʹ ne raduûtsâ padeniû našemu, no obrati zamysel ih na nih samih: navetnika že protiv nas predaj pozoru. Pomâni, Gospodi, âvi Sebâ nam vo vremâ skorbi našej i daj mne mužestvo. Carʹ bogov i Vladyka vsâkogo načalʹstva! daruj ustam moim slovo blagopriâtnoe pred étim lʹvom i ispolni serdce ego nenavistʹû k presleduûŝemu nas, na pogibelʹ emu i edinomyšlennikam ego; nas že izbavʹ rukoû Tvoeû i pomogi mne, odinokoj i ne imeûŝej pomoŝnika, krome Tebâ, Gospodi. Ty imeešʹ vedenie vsego i znaešʹ, čto â nenavižu slavu bezzakonnyh i gnušaûsʹ loža neobrezannyh i vsâkogo inoplemennika; Ty znaešʹ neobhodimostʹ moû, čto â gnušaûsʹ znaka gordosti moej, kotoryj byvaet na golove moej vo dni poâvleniâ moego, gnušaûsʹ ego, kak odeždy, oskvernennoj krovʹû, i ne nošu ego vo dni uedineniâ moego. I ne vkušala raba Tvoâ ot trapezy Amana i ne dorožila pirom carskim, i ne pila vina idoložertvennogo, i ne veselilasʹ raba Tvoâ so dnâ peremeny sudʹby moej donyne, krome kak o Tebe, Gospodi Bože Avraamov. Bože, imeûŝij silu nad vsemi! uslyšʹ golos beznadežnyh, i spasi nas ot ruki zloumyšlâûŝih, i izbavʹ menâ ot straha moego.]"],[5,1,"На третий день Есфирь, [перестав молиться, сняла одежды сетования и] оделась по-царски, [и сделавшись великолепною, призывая всевидца Бога и Спасителя, взяла двух служанок, и на одну опиралась, как бы предавшись неге, а другая следовала за нею, поддерживая одеяние ее. Она была прекрасна во цвете красоты своей, и лицо ее радостно, как бы исполненное любви, но сердце ее было стеснено от страха]. И стала она на внутреннем дворе царского дома, перед домом царя; царь же сидел тогда на царском престоле своем, в царском доме, прямо против входа в дом, [облеченный во все одеяние величия своего, весь в золоте и драгоценных камнях, и был весьма страшен]. Когда царь увидел царицу Есфирь, стоящую на дворе, она нашла милость в глазах его. [Обратив лицо свое, пламеневшее славою, он взглянул с сильным гневом; и царица упала духом и изменилась в лице своем от ослабления и склонилась на голову служанки, которая сопровождала ее. И изменил Бог дух царя на кротость, и поспешно встал он с престола своего и принял ее в объятия свои, пока она не пришла в себя. Потом он утешил ее ласковыми словами, сказав ей: что тебе, Есфирь? Я брат твой; ободрись, не умрешь, ибо наше владычество общее; подойди.]","Na tretij denʹ Esfirʹ, [perestav molitʹsâ, snâla odeždy setovaniâ i] odelasʹ po-carski, [i sdelavšisʹ velikolepnoû, prizyvaâ vsevidca Boga i Spasitelâ, vzâla dvuh služanok, i na odnu opiralasʹ, kak by predavšisʹ nege, a drugaâ sledovala za neû, podderživaâ odeânie ee. Ona byla prekrasna vo cvete krasoty svoej, i lico ee radostno, kak by ispolnennoe lûbvi, no serdce ee bylo stesneno ot straha]. I stala ona na vnutrennem dvore carskogo doma, pered domom carâ; carʹ že sidel togda na carskom prestole svoem, v carskom dome, prâmo protiv vhoda v dom, [oblečennyj vo vse odeânie veličiâ svoego, vesʹ v zolote i dragocennyh kamnâh, i byl vesʹma strašen]. Kogda carʹ uvidel caricu Esfirʹ, stoâŝuû na dvore, ona našla milostʹ v glazah ego. [Obrativ lico svoe, plamenevšee slavoû, on vzglânul s silʹnym gnevom; i carica upala duhom i izmenilasʹ v lice svoem ot oslableniâ i sklonilasʹ na golovu služanki, kotoraâ soprovoždala ee. I izmenil Bog duh carâ na krotostʹ, i pospešno vstal on s prestola svoego i prinâl ee v obʺâtiâ svoi, poka ona ne prišla v sebâ. Potom on utešil ee laskovymi slovami, skazav ej: čto tebe, Esfirʹ? Â brat tvoj; obodrisʹ, ne umrešʹ, ibo naše vladyčestvo obŝee; podojdi.]"],[5,2,"И простер царь к Есфири золотой скипетр, который был в руке его, и подошла Есфирь и коснулась конца скипетра, [и положил царь скипетр на шею ее и поцеловал ее и сказал: говори мне. И сказала она: я видела в тебе, господин, как бы Ангела Божия, и смутилось сердце мое от страха пред славою твоею, ибо дивен ты, господин, и лицо твое исполнено благодати. Но во время беседы она упала от ослабления; и царь смутился, и все слуги его утешали ее].","I proster carʹ k Esfiri zolotoj skipetr, kotoryj byl v ruke ego, i podošla Esfirʹ i kosnulasʹ konca skipetra, [i položil carʹ skipetr na šeû ee i poceloval ee i skazal: govori mne. I skazala ona: â videla v tebe, gospodin, kak by Angela Božiâ, i smutilosʹ serdce moe ot straha pred slavoû tvoeû, ibo diven ty, gospodin, i lico tvoe ispolneno blagodati. No vo vremâ besedy ona upala ot oslableniâ; i carʹ smutilsâ, i vse slugi ego utešali ee]."],[5,3,"И сказал ей царь: что тебе, царица Есфирь, и какая просьба твоя? Даже до полуцарства будет дано тебе.","I skazal ej carʹ: čto tebe, carica Esfirʹ, i kakaâ prosʹba tvoâ? Daže do polucarstva budet dano tebe."],[5,4,"И сказала Есфирь: [ныне у меня день праздничный;] если царю благоугодно, пусть придет царь с Аманом сегодня на пир, который я приготовила ему.","I skazala Esfirʹ: [nyne u menâ denʹ prazdničnyj;] esli carû blagougodno, pustʹ pridet carʹ s Amanom segodnâ na pir, kotoryj â prigotovila emu."],[5,5,"И сказал царь: сходите скорее за Аманом, чтобы сделать по слову Есфири. И пришел царь с Аманом на пир, который приготовила Есфирь.","I skazal carʹ: shodite skoree za Amanom, čtoby sdelatʹ po slovu Esfiri. I prišel carʹ s Amanom na pir, kotoryj prigotovila Esfirʹ."],[5,6,"И сказал царь Есфири при питье вина: какое желание твое? оно будет удовлетворено; и какая просьба твоя? хотя бы до полуцарства, она будет исполнена.","I skazal carʹ Esfiri pri pitʹe vina: kakoe želanie tvoe? ono budet udovletvoreno; i kakaâ prosʹba tvoâ? hotâ by do polucarstva, ona budet ispolnena."],[5,7,"И отвечала Есфирь, и сказала: вот мое желание и моя просьба:","I otvečala Esfirʹ, i skazala: vot moe želanie i moâ prosʹba:"],[5,8,"если я нашла благоволение в очах царя, и если царю благоугодно удовлетворить желание мое и исполнить просьбу мою, то пусть царь с Аманом придет [еще завтра] на пир, который я приготовлю для них, и завтра я исполню слово царя.","esli â našla blagovolenie v očah carâ, i esli carû blagougodno udovletvoritʹ želanie moe i ispolnitʹ prosʹbu moû, to pustʹ carʹ s Amanom pridet [eŝe zavtra] na pir, kotoryj â prigotovlû dlâ nih, i zavtra â ispolnû slovo carâ."],[5,9,"И вышел Аман в тот день веселый и благодушный. Но когда увидел Аман Мардохея у ворот царских, и тот не встал и с места не тронулся пред ним, тогда исполнился Аман гневом на Мардохея.","I vyšel Aman v tot denʹ veselyj i blagodušnyj. No kogda uvidel Aman Mardoheâ u vorot carskih, i tot ne vstal i s mesta ne tronulsâ pred nim, togda ispolnilsâ Aman gnevom na Mardoheâ."],[5,10,"Однако же скрепился Аман. А когда пришел в дом свой, то послал позвать друзей своих и Зерешь, жену свою.","Odnako že skrepilsâ Aman. A kogda prišel v dom svoj, to poslal pozvatʹ druzej svoih i Zerešʹ, ženu svoû."],[5,11,"И рассказывал им Аман о великом богатстве своем и о множестве сыновей своих и обо всем том, как возвеличил его царь и как вознес его над князьями и слугами царскими.","I rasskazyval im Aman o velikom bogatstve svoem i o množestve synovej svoih i obo vsem tom, kak vozveličil ego carʹ i kak voznes ego nad knâzʹâmi i slugami carskimi."],[5,12,"И сказал Аман: да и царица Есфирь никого не позвала с царем на пир, который она приготовила, кроме меня; так и на завтра я зван к ней с царем.","I skazal Aman: da i carica Esfirʹ nikogo ne pozvala s carem na pir, kotoryj ona prigotovila, krome menâ; tak i na zavtra â zvan k nej s carem."],[5,13,"Но всего этого не довольно для меня, доколе я вижу Мардохея Иудеянина сидящим у ворот царских.","No vsego étogo ne dovolʹno dlâ menâ, dokole â vižu Mardoheâ Iudeânina sidâŝim u vorot carskih."],[5,14,"И сказала ему Зерешь, жена его, и все друзья его: пусть приготовят дерево вышиною в пятьдесят локтей, и утром скажи царю, чтобы повесили Мардохея на нем, и тогда весело иди на пир с царем. И понравилось это слово Аману, и он приготовил дерево.","I skazala emu Zerešʹ, žena ego, i vse druzʹâ ego: pustʹ prigotovât derevo vyšinoû v pâtʹdesât loktej, i utrom skaži carû, čtoby povesili Mardoheâ na nem, i togda veselo idi na pir s carem. I ponravilosʹ éto slovo Amanu, i on prigotovil derevo."],[6,1,"В ту ночь [Господь] отнял сон от царя, и он велел [слуге] принести памятную книгу дневных записей; и читали их пред царем,","V tu nočʹ [Gospodʹ] otnâl son ot carâ, i on velel [sluge] prinesti pamâtnuû knigu dnevnyh zapisej; i čitali ih pred carem,"],[6,2,"и найдено записанным там, как донес Мардохей на Гавафу и Фарру, двух евнухов царских, оберегавших порог, которые замышляли наложить руку на царя Артаксеркса.","i najdeno zapisannym tam, kak dones Mardohej na Gavafu i Farru, dvuh evnuhov carskih, oberegavših porog, kotorye zamyšlâli naložitʹ ruku na carâ Artakserksa."],[6,3,"И сказал царь: какая дана почесть и отличие Мардохею за это? И сказали отроки царя, служившие при нем: ничего не сделано ему.","I skazal carʹ: kakaâ dana počestʹ i otličie Mardoheû za éto? I skazali otroki carâ, služivšie pri nem: ničego ne sdelano emu."],[6,4,"[Когда царь расспрашивал о благодеянии Мардохея, пришел на двор Аман,] и сказал царь: кто на дворе? Аман же пришел тогда на внешний двор царского дома поговорить с царем, чтобы повесили Мардохея на дереве, которое он приготовил для него.","[Kogda carʹ rassprašival o blagodeânii Mardoheâ, prišel na dvor Aman,] i skazal carʹ: kto na dvore? Aman že prišel togda na vnešnij dvor carskogo doma pogovoritʹ s carem, čtoby povesili Mardoheâ na dereve, kotoroe on prigotovil dlâ nego."],[6,5,"И сказали отроки царю: вот, Аман стоит на дворе. И сказал царь: пусть войдет.","I skazali otroki carû: vot, Aman stoit na dvore. I skazal carʹ: pustʹ vojdet."],[6,6,"И вошел Аман. И сказал ему царь: что сделать бы тому человеку, которого царь хочет отличить почестью? Аман подумал в сердце своем: кому другому захочет царь оказать почесть, кроме меня?","I vošel Aman. I skazal emu carʹ: čto sdelatʹ by tomu čeloveku, kotorogo carʹ hočet otličitʹ počestʹû? Aman podumal v serdce svoem: komu drugomu zahočet carʹ okazatʹ počestʹ, krome menâ?"],[6,7,"И сказал Аман царю: тому человеку, которого царь хочет отличить почестью,","I skazal Aman carû: tomu čeloveku, kotorogo carʹ hočet otličitʹ počestʹû,"],[6,8,"пусть принесут одеяние царское, в которое одевается царь, и приведут коня, на котором ездит царь, возложат царский венец на голову его,","pustʹ prinesut odeânie carskoe, v kotoroe odevaetsâ carʹ, i privedut konâ, na kotorom ezdit carʹ, vozložat carskij venec na golovu ego,"],[6,9,"и пусть подадут одеяние и коня в руки одному из первых князей царских, – и облекут того человека, которого царь хочет отличить почестью, и выведут его на коне на городскую площадь, и провозгласят пред ним: «так делается тому человеку, которого царь хочет отличить почестью!»","i pustʹ podadut odeânie i konâ v ruki odnomu iz pervyh knâzej carskih, – i oblekut togo čeloveka, kotorogo carʹ hočet otličitʹ počestʹû, i vyvedut ego na kone na gorodskuû ploŝadʹ, i provozglasât pred nim: «tak delaetsâ tomu čeloveku, kotorogo carʹ hočet otličitʹ počestʹû!»"],[6,10,"И сказал царь Аману: [хорошо ты сказал;] тотчас же возьми одеяние и коня, как ты сказал, и сделай это Мардохею Иудеянину, сидящему у царских ворот; ничего не опусти из всего, что ты говорил.","I skazal carʹ Amanu: [horošo ty skazal;] totčas že vozʹmi odeânie i konâ, kak ty skazal, i sdelaj éto Mardoheû Iudeâninu, sidâŝemu u carskih vorot; ničego ne opusti iz vsego, čto ty govoril."],[6,11,"И взял Аман одеяние и коня и облек Мардохея, и вывел его на коне на городскую площадь и провозгласил пред ним: «так делается тому человеку, которого царь хочет отличить почестью!»","I vzâl Aman odeânie i konâ i oblek Mardoheâ, i vyvel ego na kone na gorodskuû ploŝadʹ i provozglasil pred nim: «tak delaetsâ tomu čeloveku, kotorogo carʹ hočet otličitʹ počestʹû!»"],[6,12,"И возвратился Мардохей к царским воротам. Аман же поспешил в дом свой, печальный и закрыв голову.","I vozvratilsâ Mardohej k carskim vorotam. Aman že pospešil v dom svoj, pečalʹnyj i zakryv golovu."],[6,13,"И пересказал Аман Зереши, жене своей, и всем друзьям своим все, что случилось с ним. И сказали ему мудрецы его и Зерешь, жена его: если из племени Иудеев Мардохей, из-за которого ты начал падать, то не пересилишь его, а наверно падешь пред ним, [ибо с ним Бог живой].","I pereskazal Aman Zereši, žene svoej, i vsem druzʹâm svoim vse, čto slučilosʹ s nim. I skazali emu mudrecy ego i Zerešʹ, žena ego: esli iz plemeni Iudeev Mardohej, iz-za kotorogo ty načal padatʹ, to ne peresilišʹ ego, a naverno padešʹ pred nim, [ibo s nim Bog živoj]."],[6,14,"Они еще разговаривали с ним, как пришли евнухи царя и стали торопить Амана идти на пир, который приготовила Есфирь.","Oni eŝe razgovarivali s nim, kak prišli evnuhi carâ i stali toropitʹ Amana idti na pir, kotoryj prigotovila Esfirʹ."],[7,1,"И пришел царь с Аманом пировать у Есфири царицы.","I prišel carʹ s Amanom pirovatʹ u Esfiri caricy."],[7,2,"И сказал царь Есфири также и в этот второй день во время пира: какое желание твое, царица Есфирь? оно будет удовлетворено; и какая просьба твоя? хотя бы до полуцарства, она будет исполнена.","I skazal carʹ Esfiri takže i v étot vtoroj denʹ vo vremâ pira: kakoe želanie tvoe, carica Esfirʹ? ono budet udovletvoreno; i kakaâ prosʹba tvoâ? hotâ by do polucarstva, ona budet ispolnena."],[7,3,"И отвечала царица Есфирь и сказала: если я нашла благоволение в очах твоих, царь, и если царю благоугодно, то да будут дарованы мне жизнь моя, по желанию моему, и народ мой, по просьбе моей!","I otvečala carica Esfirʹ i skazala: esli â našla blagovolenie v očah tvoih, carʹ, i esli carû blagougodno, to da budut darovany mne žiznʹ moâ, po želaniû moemu, i narod moj, po prosʹbe moej!"],[7,4,"Ибо проданы мы, я и народ мой, на истребление, убиение и погибель. Если бы мы проданы были в рабы и рабыни, я молчала бы, хотя враг не вознаградил бы ущерба царя.","Ibo prodany my, â i narod moj, na istreblenie, ubienie i pogibelʹ. Esli by my prodany byli v raby i rabyni, â molčala by, hotâ vrag ne voznagradil by uŝerba carâ."],[7,5,"И отвечал царь Артаксеркс и сказал царице Есфири: кто это такой, и где тот, который отважился в сердце своем сделать так?","I otvečal carʹ Artakserks i skazal carice Esfiri: kto éto takoj, i gde tot, kotoryj otvažilsâ v serdce svoem sdelatʹ tak?"],[7,6,"И сказала Есфирь: враг и неприятель – этот злобный Аман! И Аман затрепетал пред царем и царицею.","I skazala Esfirʹ: vrag i nepriâtelʹ – étot zlobnyj Aman! I Aman zatrepetal pred carem i cariceû."],[7,7,"И царь встал во гневе своем с пира и пошел в сад при дворце; Аман же остался умолять о жизни своей царицу Есфирь, ибо видел, что определена ему злая участь от царя.","I carʹ vstal vo gneve svoem s pira i pošel v sad pri dvorce; Aman že ostalsâ umolâtʹ o žizni svoej caricu Esfirʹ, ibo videl, čto opredelena emu zlaâ učastʹ ot carâ."],[7,8,"Когда царь возвратился из сада при дворце в дом пира, Аман был припавшим к ложу, на котором находилась Есфирь. И сказал царь: даже и насиловать царицу хочет в доме у меня! Слово вышло из уст царя, – и накрыли лицо Аману.","Kogda carʹ vozvratilsâ iz sada pri dvorce v dom pira, Aman byl pripavšim k ložu, na kotorom nahodilasʹ Esfirʹ. I skazal carʹ: daže i nasilovatʹ caricu hočet v dome u menâ! Slovo vyšlo iz ust carâ, – i nakryli lico Amanu."],[7,9,"И сказал Харбона, один из евнухов при царе: вот и дерево, которое приготовил Аман для Мардохея, говорившего доброе для царя, стоит у дома Амана, вышиною в пятьдесят локтей. И сказал царь: повесьте его на нем.","I skazal Harbona, odin iz evnuhov pri care: vot i derevo, kotoroe prigotovil Aman dlâ Mardoheâ, govorivšego dobroe dlâ carâ, stoit u doma Amana, vyšinoû v pâtʹdesât loktej. I skazal carʹ: povesʹte ego na nem."],[7,10,"И повесили Амана на дереве, которое он приготовил для Мардохея. И гнев царя утих.","I povesili Amana na dereve, kotoroe on prigotovil dlâ Mardoheâ. I gnev carâ utih."],[8,1,"В тот день царь Артаксеркс отдал царице Есфири дом Амана, врага Иудеев; а Мардохей вошел пред лицо царя, ибо Есфирь объявила, что он для нее.","V tot denʹ carʹ Artakserks otdal carice Esfiri dom Amana, vraga Iudeev; a Mardohej vošel pred lico carâ, ibo Esfirʹ obʺâvila, čto on dlâ nee."],[8,2,"И снял царь перстень свой, который он отнял у Амана, и отдал его Мардохею; Есфирь же поставила Мардохея смотрителем над домом Амана.","I snâl carʹ perstenʹ svoj, kotoryj on otnâl u Amana, i otdal ego Mardoheû; Esfirʹ že postavila Mardoheâ smotritelem nad domom Amana."],[8,3,"И продолжала Есфирь говорить пред царем и пала к ногам его, и плакала и умоляла его отвратить злобу Амана Вугеянина и замысел его, который он замыслил против Иудеев.","I prodolžala Esfirʹ govoritʹ pred carem i pala k nogam ego, i plakala i umolâla ego otvratitʹ zlobu Amana Vugeânina i zamysel ego, kotoryj on zamyslil protiv Iudeev."],[8,4,"И простер царь к Есфири золотой скипетр; и поднялась Есфирь, и стала пред лицом царя,","I proster carʹ k Esfiri zolotoj skipetr; i podnâlasʹ Esfirʹ, i stala pred licom carâ,"],[8,5,"и сказала: если царю благоугодно, и если я нашла благоволение пред лицом его, и справедливо дело сие пред лицом царя, и нравлюсь я очам его, то пусть было бы написано, чтобы возвращены были письма по замыслу Амана, сына Амадафа, Вугеянина, писанные им об истреблении Иудеев во всех областях царя;","i skazala: esli carû blagougodno, i esli â našla blagovolenie pred licom ego, i spravedlivo delo sie pred licom carâ, i nravlûsʹ â očam ego, to pustʹ bylo by napisano, čtoby vozvraŝeny byli pisʹma po zamyslu Amana, syna Amadafa, Vugeânina, pisannye im ob istreblenii Iudeev vo vseh oblastâh carâ;"],[8,6,"ибо как я могу видеть бедствие, которое постигнет народ мой, и как я могу видеть погибель родных моих?","ibo kak â mogu videtʹ bedstvie, kotoroe postignet narod moj, i kak â mogu videtʹ pogibelʹ rodnyh moih?"],[8,7,"И сказал царь Артаксеркс царице Есфири и Мардохею Иудеянину: вот, я дом Амана отдал Есфири, и его самого повесили на дереве за то, что он налагал руку свою на Иудеев;","I skazal carʹ Artakserks carice Esfiri i Mardoheû Iudeâninu: vot, â dom Amana otdal Esfiri, i ego samogo povesili na dereve za to, čto on nalagal ruku svoû na Iudeev;"],[8,8,"напишите и вы о Иудеях, что вам угодно, от имени царя и скрепите царским перстнем, ибо письма, написанного от имени царя и скрепленного перстнем царским, нельзя изменить.","napišite i vy o Iudeâh, čto vam ugodno, ot imeni carâ i skrepite carskim perstnem, ibo pisʹma, napisannogo ot imeni carâ i skreplennogo perstnem carskim, nelʹzâ izmenitʹ."],[8,9,"И позваны были тогда царские писцы в третий месяц, то есть в месяц Сиван, в двадцать третий день его, и написано было все так, как приказал Мардохей, к Иудеям, и к сатрапам, и областеначальникам, и правителям областей от Индии до Ефиопии, ста двадцати семи областей, в каждую область письменами ее и к каждому народу на языке его, и к Иудеям письменами их и на языке их.","I pozvany byli togda carskie piscy v tretij mesâc, to estʹ v mesâc Sivan, v dvadcatʹ tretij denʹ ego, i napisano bylo vse tak, kak prikazal Mardohej, k Iudeâm, i k satrapam, i oblastenačalʹnikam, i pravitelâm oblastej ot Indii do Efiopii, sta dvadcati semi oblastej, v každuû oblastʹ pisʹmenami ee i k každomu narodu na âzyke ego, i k Iudeâm pisʹmenami ih i na âzyke ih."],[8,10,"И написал он от имени царя Артаксеркса, и скрепил царским перстнем, и послал письма чрез гонцов на конях, на дромадерах и мулах царских,","I napisal on ot imeni carâ Artakserksa, i skrepil carskim perstnem, i poslal pisʹma črez goncov na konâh, na dromaderah i mulah carskih,"],[8,11,"о том, что царь позволяет Иудеям, находящимся во всяком городе, собраться и стать на защиту жизни своей, истребить, убить и погубить всех сильных в народе и в области, которые во вражде с ними, детей и жен, и имение их разграбить,","o tom, čto carʹ pozvolâet Iudeâm, nahodâŝimsâ vo vsâkom gorode, sobratʹsâ i statʹ na zaŝitu žizni svoej, istrebitʹ, ubitʹ i pogubitʹ vseh silʹnyh v narode i v oblasti, kotorye vo vražde s nimi, detej i žen, i imenie ih razgrabitʹ,"],[8,12,"в один день по всем областям царя Артаксеркса, в тринадцатый день двенадцатого месяца, то есть месяца Адара. [Список с этого указа следующий: великий царь Артаксеркс начальствующим от Индии до Ефиопии над ста двадцатью семью областями и властителям, доброжелательствующим нам, радоваться. Многие, по чрезвычайной доброте благодетелей щедро награждаемые почестями, чрезмерно возгордились и не только подданным нашим ищут причинить зло, но, не могши насытить гордость, покушаются строить козни самим благодетелям своим, не только теряют чувство человеческой признательности, но, кичась надменностью безумных, преступно думают избежать суда все и всегда видящего Бога. Но часто и многие, будучи облечены властью, чтоб устроять дела доверивших им друзей, своим убеждением делают их виновниками пролития невинной крови и подвергают неисправимым бедствиям, хитросплетением коварной лжи обманывая непорочное благомыслие державных. Это можно видеть не столько из древних историй, как мы сказали, сколько из дел, преступно совершаемых пред вами злобою недостойно властвующих. Посему нужно озаботиться на последующее время, чтобы нам устроить царство безмятежным для всех людей в мире, не допуская изменений, но представляющиеся дела обсуждая с надлежащей предусмотрительностью. Так Аман Амадафов, Македонянин, поистине чуждый персидской крови и весьма далекий от нашей благости, быв принят у нас гостем, удостоился благосклонности, которую мы имеем ко всякому народу, настолько,что был провозглашен нашим отцом и почитаем всеми, представляя второе лицо при царском престоле; но, не умерив гордости, замышлял лишить нас власти и души, а нашего спасителя и всегдашнего благодетеля Мардохея и непорочную общницу царства Есфирь, со всем народом их, домогался разнообразными коварными мерами погубить. Таким образом он думал сделать нас безлюдными, а державу Персидскую передать Македонянам. Мы же находим Иудеев, осужденных этим злодеем на истребление, не зловредными, а живущими по справедливейшим законам, сынами Вышнего, величайшего живого Бога, даровавшего нам и предкам нашим царство в самом лучшем состоянии. Посему вы хорошо сделаете, не приводя в исполнение грамот, посланных Аманом Амадафовым; ибо он, совершивший это, при воротах Сузских повешен со всем домом, по воле владычествующего всем Бога, воздавшего ему скоро достойный суд. Список же с этого указа выставив на всяком месте открыто, оставьте Иудеев пользоваться своими законами и содействуйте им, чтобы восстававшим на них во время скорби они могли отмстить в тринадцатый день двенадцатого месяца Адара, в самый тот день. Ибо владычествующий над всем Бог, вместо погибели избранного рода, устроил им такую радость. И вы, в числе именитых праздников ваших, проводите сей знаменитый день со всем весельем, дабы и ныне и после памятно было спасение для нас и для благорасположенных к нам Персов и погубление строивших нам козни. Всякий город или область вообще, которая не исполнит сего, нещадно опустошится мечом и огнем и сделается не только необитаемою для людей, но и для зверей и птиц навсегда отвратительною.]","v odin denʹ po vsem oblastâm carâ Artakserksa, v trinadcatyj denʹ dvenadcatogo mesâca, to estʹ mesâca Adara. [Spisok s étogo ukaza sleduûŝij: velikij carʹ Artakserks načalʹstvuûŝim ot Indii do Efiopii nad sta dvadcatʹû semʹû oblastâmi i vlastitelâm, dobroželatelʹstvuûŝim nam, radovatʹsâ. Mnogie, po črezvyčajnoj dobrote blagodetelej ŝedro nagraždaemye počestâmi, črezmerno vozgordilisʹ i ne tolʹko poddannym našim iŝut pričinitʹ zlo, no, ne mogši nasytitʹ gordostʹ, pokušaûtsâ stroitʹ kozni samim blagodetelâm svoim, ne tolʹko terâût čuvstvo čelovečeskoj priznatelʹnosti, no, kičasʹ nadmennostʹû bezumnyh, prestupno dumaût izbežatʹ suda vse i vsegda vidâŝego Boga. No často i mnogie, buduči oblečeny vlastʹû, čtob ustroâtʹ dela doverivših im druzej, svoim ubeždeniem delaût ih vinovnikami prolitiâ nevinnoj krovi i podvergaût neispravimym bedstviâm, hitrospleteniem kovarnoj lži obmanyvaâ neporočnoe blagomyslie deržavnyh. Éto možno videtʹ ne stolʹko iz drevnih istorij, kak my skazali, skolʹko iz del, prestupno soveršaemyh pred vami zloboû nedostojno vlastvuûŝih. Posemu nužno ozabotitʹsâ na posleduûŝee vremâ, čtoby nam ustroitʹ carstvo bezmâtežnym dlâ vseh lûdej v mire, ne dopuskaâ izmenenij, no predstavlâûŝiesâ dela obsuždaâ s nadležaŝej predusmotritelʹnostʹû. Tak Aman Amadafov, Makedonânin, poistine čuždyj persidskoj krovi i vesʹma dalekij ot našej blagosti, byv prinât u nas gostem, udostoilsâ blagosklonnosti, kotoruû my imeem ko vsâkomu narodu, nastolʹko,čto byl provozglašen našim otcom i počitaem vsemi, predstavlââ vtoroe lico pri carskom prestole; no, ne umeriv gordosti, zamyšlâl lišitʹ nas vlasti i duši, a našego spasitelâ i vsegdašnego blagodetelâ Mardoheâ i neporočnuû obŝnicu carstva Esfirʹ, so vsem narodom ih, domogalsâ raznoobraznymi kovarnymi merami pogubitʹ. Takim obrazom on dumal sdelatʹ nas bezlûdnymi, a deržavu Persidskuû peredatʹ Makedonânam. My že nahodim Iudeev, osuždennyh étim zlodeem na istreblenie, ne zlovrednymi, a živuŝimi po spravedlivejšim zakonam, synami Vyšnego, veličajšego živogo Boga, darovavšego nam i predkam našim carstvo v samom lučšem sostoânii. Posemu vy horošo sdelaete, ne privodâ v ispolnenie gramot, poslannyh Amanom Amadafovym; ibo on, soveršivšij éto, pri vorotah Suzskih povešen so vsem domom, po vole vladyčestvuûŝego vsem Boga, vozdavšego emu skoro dostojnyj sud. Spisok že s étogo ukaza vystaviv na vsâkom meste otkryto, ostavʹte Iudeev polʹzovatʹsâ svoimi zakonami i sodejstvujte im, čtoby vosstavavšim na nih vo vremâ skorbi oni mogli otmstitʹ v trinadcatyj denʹ dvenadcatogo mesâca Adara, v samyj tot denʹ. Ibo vladyčestvuûŝij nad vsem Bog, vmesto pogibeli izbrannogo roda, ustroil im takuû radostʹ. I vy, v čisle imenityh prazdnikov vaših, provodite sej znamenityj denʹ so vsem veselʹem, daby i nyne i posle pamâtno bylo spasenie dlâ nas i dlâ blagoraspoložennyh k nam Persov i pogublenie stroivših nam kozni. Vsâkij gorod ili oblastʹ voobŝe, kotoraâ ne ispolnit sego, neŝadno opustošitsâ mečom i ognem i sdelaetsâ ne tolʹko neobitaemoû dlâ lûdej, no i dlâ zverej i ptic navsegda otvratitelʹnoû.]"],[8,13,"Список с сего указа отдать в каждую область, как закон, объявляемый для всех народов, чтоб Иудеи готовы были к тому дню мстить врагам своим.","Spisok s sego ukaza otdatʹ v každuû oblastʹ, kak zakon, obʺâvlâemyj dlâ vseh narodov, čtob Iudei gotovy byli k tomu dnû mstitʹ vragam svoim."],[8,14,"Гонцы, поехавшие верхом на быстрых конях царских, погнали скоро и поспешно, с царским повелением. Объявлен был указ и в Сузах, престольном городе.","Goncy, poehavšie verhom na bystryh konâh carskih, pognali skoro i pospešno, s carskim poveleniem. Obʺâvlen byl ukaz i v Suzah, prestolʹnom gorode."],[8,15,"И Мардохей вышел от царя в царском одеянии яхонтового и белого цвета и в большом золотом венце, и в мантии виссонной и пурпуровой. И город Сузы возвеселился и возрадовался.","I Mardohej vyšel ot carâ v carskom odeânii âhontovogo i belogo cveta i v bolʹšom zolotom vence, i v mantii vissonnoj i purpurovoj. I gorod Suzy vozveselilsâ i vozradovalsâ."],[8,16,"А у Иудеев было тогда освещение и радость, и веселье, и торжество.","A u Iudeev bylo togda osveŝenie i radostʹ, i veselʹe, i toržestvo."],[8,17,"И во всякой области и во всяком городе, во всяком месте, куда только доходило повеление царя и указ его, была радость у Иудеев и веселье, пиршество и праздничный день. И многие из народов страны сделались Иудеями, потому что напал на них страх пред Иудеями.","I vo vsâkoj oblasti i vo vsâkom gorode, vo vsâkom meste, kuda tolʹko dohodilo povelenie carâ i ukaz ego, byla radostʹ u Iudeev i veselʹe, piršestvo i prazdničnyj denʹ. I mnogie iz narodov strany sdelalisʹ Iudeâmi, potomu čto napal na nih strah pred Iudeâmi."],[9,1,"В двенадцатый месяц, то есть в месяц Адар, в тринадцатый день его, в который пришло время исполниться повелению царя и указу его, в тот день, когда надеялись неприятели Иудеев взять власть над ними, а вышло наоборот, что сами Иудеи взяли власть над врагами своими, –","V dvenadcatyj mesâc, to estʹ v mesâc Adar, v trinadcatyj denʹ ego, v kotoryj prišlo vremâ ispolnitʹsâ poveleniû carâ i ukazu ego, v tot denʹ, kogda nadeâlisʹ nepriâteli Iudeev vzâtʹ vlastʹ nad nimi, a vyšlo naoborot, čto sami Iudei vzâli vlastʹ nad vragami svoimi, –"],[9,2,"собрались Иудеи в городах своих по всем областям царя Артаксеркса, чтобы наложить руку на зложелателей своих; и никто не мог устоять пред лицом их, потому что страх пред ними напал на все народы.","sobralisʹ Iudei v gorodah svoih po vsem oblastâm carâ Artakserksa, čtoby naložitʹ ruku na zloželatelej svoih; i nikto ne mog ustoâtʹ pred licom ih, potomu čto strah pred nimi napal na vse narody."],[9,3,"И все князья в областях и сатрапы, и областеначальники, и исполнители дел царских поддерживали Иудеев, потому что напал на них страх пред Мардохеем.","I vse knâzʹâ v oblastâh i satrapy, i oblastenačalʹniki, i ispolniteli del carskih podderživali Iudeev, potomu čto napal na nih strah pred Mardoheem."],[9,4,"Ибо велик был Мардохей в доме у царя, и слава о нем ходила по всем областям, так как сей человек, Мардохей, поднимался выше и выше.","Ibo velik byl Mardohej v dome u carâ, i slava o nem hodila po vsem oblastâm, tak kak sej čelovek, Mardohej, podnimalsâ vyše i vyše."],[9,5,"И избивали Иудеи всех врагов своих, побивая мечом, умерщвляя и истребляя, и поступали с неприятелями своими по своей воле.","I izbivali Iudei vseh vragov svoih, pobivaâ mečom, umerŝvlââ i istreblââ, i postupali s nepriâtelâmi svoimi po svoej vole."],[9,6,"В Сузах, городе престольном, умертвили Иудеи и погубили пятьсот человек;","V Suzah, gorode prestolʹnom, umertvili Iudei i pogubili pâtʹsot čelovek;"],[9,7,"и Паршандафу, и Далфона, и Асфафу,","i Paršandafu, i Dalfona, i Asfafu,"],[9,8,"и Порафу, и Адалью, и Аридафу,","i Porafu, i Adalʹû, i Aridafu,"],[9,9,"и Пармашфу, и Арисая, и Аридая, и Ваиезафу –","i Parmašfu, i Arisaâ, i Aridaâ, i Vaiezafu –"],[9,10,"десятерых сыновей Амана, сына Амадафа, врага Иудеев, умертвили они, а на грабеж не простерли руки своей.","desâteryh synovej Amana, syna Amadafa, vraga Iudeev, umertvili oni, a na grabež ne prosterli ruki svoej."],[9,11,"В тот же день донесли царю о числе умерщвленных в Сузах, престольном городе.","V tot že denʹ donesli carû o čisle umerŝvlennyh v Suzah, prestolʹnom gorode."],[9,12,"И сказал царь царице Есфири: в Сузах, городе престольном, умертвили Иудеи и погубили пятьсот человек и десятерых сыновей Амана; что же сделали они в прочих областях царя? Какое желание твое? и оно будет удовлетворено. И какая еще просьба твоя? она будет исполнена.","I skazal carʹ carice Esfiri: v Suzah, gorode prestolʹnom, umertvili Iudei i pogubili pâtʹsot čelovek i desâteryh synovej Amana; čto že sdelali oni v pročih oblastâh carâ? Kakoe želanie tvoe? i ono budet udovletvoreno. I kakaâ eŝe prosʹba tvoâ? ona budet ispolnena."],[9,13,"И сказала Есфирь: если царю благоугодно, то пусть бы позволено было Иудеям, которые в Сузах, делать то же и завтра, что сегодня, и десятерых сыновей Амановых пусть бы повесили на дереве.","I skazala Esfirʹ: esli carû blagougodno, to pustʹ by pozvoleno bylo Iudeâm, kotorye v Suzah, delatʹ to že i zavtra, čto segodnâ, i desâteryh synovej Amanovyh pustʹ by povesili na dereve."],[9,14,"И приказал царь сделать так; и дан на это указ в Сузах, и десятерых сыновей Амановых повесили.","I prikazal carʹ sdelatʹ tak; i dan na éto ukaz v Suzah, i desâteryh synovej Amanovyh povesili."],[9,15,"И собрались Иудеи, которые в Сузах, также и в четырнадцатый день месяца Адара и умертвили в Сузах триста человек, а на грабеж не простерли руки своей.","I sobralisʹ Iudei, kotorye v Suzah, takže i v četyrnadcatyj denʹ mesâca Adara i umertvili v Suzah trista čelovek, a na grabež ne prosterli ruki svoej."],[9,16,"И прочие Иудеи, находившиеся в царских областях, собрались, чтобы стать на защиту жизни своей и быть покойными от врагов своих, и умертвили из неприятелей своих семьдесят пять тысяч, а на грабеж не простерли руки своей.","I pročie Iudei, nahodivšiesâ v carskih oblastâh, sobralisʹ, čtoby statʹ na zaŝitu žizni svoej i bytʹ pokojnymi ot vragov svoih, i umertvili iz nepriâtelej svoih semʹdesât pâtʹ tysâč, a na grabež ne prosterli ruki svoej."],[9,17,"Это было в тринадцатый день месяца Адара; а в четырнадцатый день сего же месяца они успокоились и сделали его днем пиршества и веселья.","Éto bylo v trinadcatyj denʹ mesâca Adara; a v četyrnadcatyj denʹ sego že mesâca oni uspokoilisʹ i sdelali ego dnem piršestva i veselʹâ."],[9,18,"Иудеи же, которые в Сузах, собирались в тринадцатый день его и в четырнадцатый день его, а в пятнадцатый день его успокоились и сделали его днем пиршества и веселья.","Iudei že, kotorye v Suzah, sobiralisʹ v trinadcatyj denʹ ego i v četyrnadcatyj denʹ ego, a v pâtnadcatyj denʹ ego uspokoilisʹ i sdelali ego dnem piršestva i veselʹâ."],[9,19,"Поэтому Иудеи сельские, живущие в селениях открытых, проводят четырнадцатый день месяца Адара в веселье и пиршестве, как день праздничный, посылая подарки друг ко другу; [живущие же в митрополиях и пятнадцатый день Адара проводят в добром веселье, посылая подарки ближним].","Poétomu Iudei selʹskie, živuŝie v seleniâh otkrytyh, provodât četyrnadcatyj denʹ mesâca Adara v veselʹe i piršestve, kak denʹ prazdničnyj, posylaâ podarki drug ko drugu; [živuŝie že v mitropoliâh i pâtnadcatyj denʹ Adara provodât v dobrom veselʹe, posylaâ podarki bližnim]."],[9,20,"И описал Мардохей эти происшествия и послал письма ко всем Иудеям, которые в областях царя Артаксеркса, к близким и к дальним,","I opisal Mardohej éti proisšestviâ i poslal pisʹma ko vsem Iudeâm, kotorye v oblastâh carâ Artakserksa, k blizkim i k dalʹnim,"],[9,21,"о том, чтобы они установили каждогодно празднование у себя четырнадцатого дня месяца Адара и пятнадцатого дня его,","o tom, čtoby oni ustanovili každogodno prazdnovanie u sebâ četyrnadcatogo dnâ mesâca Adara i pâtnadcatogo dnâ ego,"],[9,22,"как таких дней, в которые Иудеи сделались покойны от врагов своих, и как такого месяца, в который превратилась у них печаль в радость, и сетование – в день праздничный, – чтобы сделали их днями пиршества и веселья, посылая подарки друг другу и подаяния бедным.","kak takih dnej, v kotorye Iudei sdelalisʹ pokojny ot vragov svoih, i kak takogo mesâca, v kotoryj prevratilasʹ u nih pečalʹ v radostʹ, i setovanie – v denʹ prazdničnyj, – čtoby sdelali ih dnâmi piršestva i veselʹâ, posylaâ podarki drug drugu i podaâniâ bednym."],[9,23,"И приняли Иудеи то, что уже сами начали делать, и о чем Мардохей написал к ним,","I prinâli Iudei to, čto uže sami načali delatʹ, i o čem Mardohej napisal k nim,"],[9,24,"как Аман, сын Амадафа, Вугеянин, враг всех Иудеев, думал погубить Иудеев и бросал пур, жребий, об истреблении и погублении их,","kak Aman, syn Amadafa, Vugeânin, vrag vseh Iudeev, dumal pogubitʹ Iudeev i brosal pur, žrebij, ob istreblenii i pogublenii ih,"],[9,25,"и как Есфирь дошла до царя, и как царь приказал новым письмом, чтобы злой замысел Амана, который он задумал на Иудеев, обратился на голову его, и чтобы повесили его и сыновей его на дереве.","i kak Esfirʹ došla do carâ, i kak carʹ prikazal novym pisʹmom, čtoby zloj zamysel Amana, kotoryj on zadumal na Iudeev, obratilsâ na golovu ego, i čtoby povesili ego i synovej ego na dereve."],[9,26,"Потому и назвали эти дни Пурим, от имени: пур [жребий, ибо на языке их жребии называются пурим]. Поэтому, согласно со всеми словами сего письма и с тем, что сами видели и до чего доходило у них,","Potomu i nazvali éti dni Purim, ot imeni: pur [žrebij, ibo na âzyke ih žrebii nazyvaûtsâ purim]. Poétomu, soglasno so vsemi slovami sego pisʹma i s tem, čto sami videli i do čego dohodilo u nih,"],[9,27,"постановили Иудеи и приняли на себя и на детей своих и на всех, присоединяющихся к ним, неотменно, чтобы праздновать эти два дня, по предписанному о них и в свое для них время, каждый год;","postanovili Iudei i prinâli na sebâ i na detej svoih i na vseh, prisoedinâûŝihsâ k nim, neotmenno, čtoby prazdnovatʹ éti dva dnâ, po predpisannomu o nih i v svoe dlâ nih vremâ, každyj god;"],[9,28,"и чтобы дни эти были памятны и празднуемы во все роды в каждом племени, в каждой области и в каждом городе; и чтобы дни эти Пурим не отменялись у Иудеев, и память о них не исчезла у детей их.","i čtoby dni éti byli pamâtny i prazdnuemy vo vse rody v každom plemeni, v každoj oblasti i v každom gorode; i čtoby dni éti Purim ne otmenâlisʹ u Iudeev, i pamâtʹ o nih ne isčezla u detej ih."],[9,29,"Написала также царица Есфирь, дочь Абихаила, и Мардохей Иудеянин, со всею настойчивостью, чтобы исполняли это новое письмо о Пуриме;","Napisala takže carica Esfirʹ, dočʹ Abihaila, i Mardohej Iudeânin, so vseû nastojčivostʹû, čtoby ispolnâli éto novoe pisʹmo o Purime;"],[9,30,"и послали письма ко всем Иудеям в сто двадцать семь областей царства Артаксерксова со словами мира и правды,","i poslali pisʹma ko vsem Iudeâm v sto dvadcatʹ semʹ oblastej carstva Artakserksova so slovami mira i pravdy,"],[9,31,"чтобы они твердо наблюдали эти дни Пурим в свое время, какое уставил о них Мардохей Иудеянин и царица Есфирь, и как они сами назначали их для себя и для детей своих в дни пощения и воплей.","čtoby oni tverdo nablûdali éti dni Purim v svoe vremâ, kakoe ustavil o nih Mardohej Iudeânin i carica Esfirʹ, i kak oni sami naznačali ih dlâ sebâ i dlâ detej svoih v dni poŝeniâ i voplej."],[9,32,"Так повеление Есфири подтвердило это слово о Пуриме, и оно вписано в книгу.","Tak povelenie Esfiri podtverdilo éto slovo o Purime, i ono vpisano v knigu."],[10,1,"Потом наложил царь Артаксеркс подать на землю и на острова морские.","Potom naložil carʹ Artakserks podatʹ na zemlû i na ostrova morskie."],[10,2,"Впрочем, все дела силы его и могущества его и обстоятельное показание о величии Мардохея, которым возвеличил его царь, записаны в книге дневных записей царей Мидийских и Персидских,","Vpročem, vse dela sily ego i moguŝestva ego i obstoâtelʹnoe pokazanie o veličii Mardoheâ, kotorym vozveličil ego carʹ, zapisany v knige dnevnyh zapisej carej Midijskih i Persidskih,"],[10,3,"равно как и то, что Мардохей Иудеянин был вторым по царе Артаксерксе и великим у Иудеев и любимым у множества братьев своих, ибо искал добра народу своему и говорил во благо всего племени своего. [И сказал Мардохей: от Бога было это, ибо я вспомнил сон, который я видел о сих событиях; не осталось в нем ничего неисполнившимся. Малый источник сделался рекою, и был свет и солнце и множество воды: эта река есть Есфирь, которую взял себе в жену царь и сделал царицею. А два змея это я и Аман; народы это собравшиеся истребить имя Иудеев; а народ мой это Израильтяне, воззвавшие к Богу и спасенные. И спас Господь народ Свой, и избавил нас Господь от всех сих зол, и совершил Бог знамения и чудеса великие, какие не бывали между язычниками. Так устроил Бог два жребия: один для народа Божия, а другой для всех язычников, и вышли эти два жребия в час и время и в день суда пред Богом и всеми язычниками. И вспомнил Господь о народе Своем и оправдал наследие Свое. И будут праздноваться эти дни месяца Адара, в четырнадцатый и пятнадцатый день этого месяца, с торжеством и радостью и весельем пред Богом, в роды вечные, в народе Его Израиле.] [В четвертый год царствования Птоломея и Клеопатры Досифей, который, говорят, был священником и левитом, и Птоломей, сын его, принесли в Александрию это послание о Пуриме, которое, говорят, истолковал Лисимах, сын Птоломея, бывший в Иерусалиме.]","ravno kak i to, čto Mardohej Iudeânin byl vtorym po care Artakserkse i velikim u Iudeev i lûbimym u množestva bratʹev svoih, ibo iskal dobra narodu svoemu i govoril vo blago vsego plemeni svoego. [I skazal Mardohej: ot Boga bylo éto, ibo â vspomnil son, kotoryj â videl o sih sobytiâh; ne ostalosʹ v nem ničego neispolnivšimsâ. Malyj istočnik sdelalsâ rekoû, i byl svet i solnce i množestvo vody: éta reka estʹ Esfirʹ, kotoruû vzâl sebe v ženu carʹ i sdelal cariceû. A dva zmeâ éto â i Aman; narody éto sobravšiesâ istrebitʹ imâ Iudeev; a narod moj éto Izrailʹtâne, vozzvavšie k Bogu i spasennye. I spas Gospodʹ narod Svoj, i izbavil nas Gospodʹ ot vseh sih zol, i soveršil Bog znameniâ i čudesa velikie, kakie ne byvali meždu âzyčnikami. Tak ustroil Bog dva žrebiâ: odin dlâ naroda Božiâ, a drugoj dlâ vseh âzyčnikov, i vyšli éti dva žrebiâ v čas i vremâ i v denʹ suda pred Bogom i vsemi âzyčnikami. I vspomnil Gospodʹ o narode Svoem i opravdal nasledie Svoe. I budut prazdnovatʹsâ éti dni mesâca Adara, v četyrnadcatyj i pâtnadcatyj denʹ étogo mesâca, s toržestvom i radostʹû i veselʹem pred Bogom, v rody večnye, v narode Ego Izraile.] [V četvertyj god carstvovaniâ Ptolomeâ i Kleopatry Dosifej, kotoryj, govorât, byl svâŝennikom i levitom, i Ptolomej, syn ego, prinesli v Aleksandriû éto poslanie o Purime, kotoroe, govorât, istolkoval Lisimah, syn Ptolomeâ, byvšij v Ierusalime.]"]],"cmn-cuv-hant":[[1,1,"亞哈隨魯作王，從 印度直到 古實，統管一百二十七省。","yà hā suí lǔ zuò wáng， cóng yìn dù zhí dào gǔ shí， tǒng guǎn yī bǎi èr shí qī shěng."],[1,2,"亞哈隨魯王在 書珊城的宮登基；","yà hā suí lǔ wáng zài shū shān chéng de gōng dēng jī；"],[1,3,"在位第三年，為他一切首領臣僕設擺筵席，有 波斯和 米底亞的權貴，就是各省的貴冑與首領，在他面前。","zài wèi dì sān nián， wèi tā yī qiè shǒu lǐng chén pú shè bǎi yán xí， yǒu bō sī hé mǐ dǐ yà de quán guì， jiù shì gè shěng de guì zhòu yǔ shǒu lǐng， zài tā miàn qián."],[1,4,"他把他榮耀之國的豐富和他美好威嚴的尊貴給他們看了許多日，就是一百八十日。","tā bǎ tā róng yào zhī guó de fēng fù hé tā měi hǎo wēi yán de zūn guì gěi tā men kàn le xǔ duō rì， jiù shì yī bǎi bā shí rì."],[1,5,"這日子滿了，又為所有住 書珊城的大小人民在御園的院子裏設擺筵席七日。","zhè rì zǐ mǎn le， yòu wèi suǒ yǒu zhù shū shān chéng de dà xiǎo rén mín zài yù yuán de yuàn zǐ lǐ shè bǎi yán xí qī rì."],[1,6,"有白色、綠色、藍色的 帳子，用細麻繩、紫色繩從銀環內繫在白玉石柱上；有金銀的床榻擺在紅、白、黃、黑玉石的鋪石地上。","yǒu bái sè, lǜ sè, lán sè de zhàng zǐ， yòng xì má shéng, zǐ sè shéng cóng yín huán nèi xì zài bái yù shí zhù shàng； yǒu jīn yín de chuáng tà bǎi zài hóng, bái, huáng, hēi yù shí de pù shí de shàng."],[1,7,"用金器皿賜酒，器皿各有不同。御酒甚多，足顯王的厚意。","yòng jīn qì mǐn cì jiǔ， qì mǐn gè yǒu bù tóng. yù jiǔ shèn duō， zú xiǎn wáng de hòu yì."],[1,8,"喝酒有例，不准勉強人，因王吩咐宮裏的一切臣宰，讓人各隨己意。","hē jiǔ yǒu lì， bù zhǔn miǎn qiáng rén， yīn wáng fēn fù gōng lǐ de yī qiè chén zǎi， ràng rén gè suí jǐ yì."],[1,9,"王后 瓦實提在 亞哈隨魯王的宮內也為婦女設擺筵席。","wáng hòu wǎ shí tí zài yà hā suí lǔ wáng de gōng nèi yě wèi fù nǚ shè bǎi yán xí."],[1,10,"第七日， 亞哈隨魯王飲酒，心中快樂，就吩咐在他面前侍立的七個太監 米戶幔、 比斯他、 哈波拿、 比革他、 亞拔他、 西達、 甲迦，","dì qī rì， yà hā suí lǔ wáng yǐn jiǔ， xīn zhōng kuài lè， jiù fēn fù zài tā miàn qián shì lì de qī gè tài jiān mǐ hù màn, bǐ sī tā, hā bō ná, bǐ gé tā, yà bá tā, xī dá, jiǎ jiā，"],[1,11,"請王后 瓦實提頭戴王后的冠冕到王面前，使各等臣民看她的美貌，因為她容貌甚美。","qǐng wáng hòu wǎ shí tí tóu dài wáng hòu de guān miǎn dào wáng miàn qián， shǐ gè děng chén mín kàn tā de měi mào， yīn wèi tā róng mào shèn měi."],[1,12,"王后 瓦實提卻不肯遵太監所傳的王命而來，所以王甚發怒，心如火燒。","wáng hòu wǎ shí tí què bù kěn zūn tài jiān suǒ chuán de wáng mìng ér lái， suǒ yǐ wáng shèn fā nù， xīn rú huǒ shāo."],[1,13,"那時，在王左右常見王面、國中坐高位的，有 波斯和 米底亞的七個大臣，就是 甲示拿、 示達、 押瑪他、 他施斯、 米力、 瑪西拿、 米母干，都是達時務的明哲人。按王的常規，辦事必先詢問知例明法的人。王問他們說：","nà shí， zài wáng zuǒ yòu cháng jiàn wáng miàn, guó zhōng zuò gāo wèi de， yǒu bō sī hé mǐ dǐ yà de qī gè dà chén， jiù shì jiǎ shì ná, shì dá, yā mǎ tā, tā shī sī, mǐ lì, mǎ xī ná, mǐ mǔ gàn， dōu shì dá shí wù de míng zhé rén. àn wáng de cháng guī， bàn shì bì xiān xún wèn zhī lì míng fǎ de rén. wáng wèn tā men shuō："],[1,15,"「王后 瓦實提不遵太監所傳的王命，照例應當怎樣辦理呢？」","‘wáng hòu wǎ shí tí bù zūn tài jiān suǒ chuán de wáng mìng， zhào lì yīng dāng zěn yàng bàn lǐ ne？’"],[1,16,"米母干在王和眾首領面前回答說：「王后 瓦實提這事，不但得罪王，並且有害於王各省的臣民；","mǐ mǔ gàn zài wáng hé zhòng shǒu lǐng miàn qián huí dá shuō：‘wáng hòu wǎ shí tí zhè shì， bù dàn dé zuì wáng， bìng qiě yǒu hài yú wáng gè shěng de chén mín；"],[1,17,"因為王后這事必傳到眾婦人的耳中，說：『 亞哈隨魯王吩咐王后 瓦實提到王面前，她卻不來』，她們就藐視自己的丈夫。","yīn wèi wáng hòu zhè shì bì chuán dào zhòng fù rén de ěr zhōng， shuō：“ yà hā suí lǔ wáng fēn fù wáng hòu wǎ shí tí dào wáng miàn qián， tā què bù lái”， tā men jiù miǎo shì zì jǐ de zhàng fū."],[1,18,"今日 波斯和 米底亞的眾夫人聽見王后這事，必向王的大臣 照樣行；從此必大開藐視和忿怒之端。","jīn rì bō sī hé mǐ dǐ yà de zhòng fū rén tīng jiàn wáng hòu zhè shì， bì xiàng wáng de dà chén zhào yàng xíng； cóng cǐ bì dà kāi miǎo shì hé fèn nù zhī duān."],[1,19,"王若以為美，就降旨寫在 波斯和 米底亞人的例中，永不更改，不准 瓦實提再到王面前，將她王后的位分賜給比她還好的人。","wáng ruò yǐ wèi měi， jiù jiàng zhǐ xiě zài bō sī hé mǐ dǐ yà rén de lì zhōng， yǒng bù gèng gǎi， bù zhǔn wǎ shí tí zài dào wáng miàn qián， jiāng tā wáng hòu de wèi fēn cì gěi bǐ tā hái hǎo de rén."],[1,20,"所降的旨意傳遍通國（國度本來廣大），所有的婦人，無論丈夫貴賤都必尊敬他。」","suǒ jiàng de zhǐ yì chuán biàn tōng guó （guó dù běn lái guǎng dà）， suǒ yǒu de fù rén， wú lùn zhàng fū guì jiàn dōu bì zūn jìng tā.’"],[1,21,"王和眾首領都以 米母干的話為美，王就照這話去行，","wáng hé zhòng shǒu lǐng dōu yǐ mǐ mǔ gàn de huà wèi měi， wáng jiù zhào zhè huà qù xíng，"],[1,22,"發詔書，用各省的文字、各族的方言通知各省，使為丈夫的在家中作主，各說本地的方言。","fā zhào shū， yòng gè shěng de wén zì, gè zú de fāng yán tōng zhī gè shěng， shǐ wèi zhàng fū de zài jiā zhōng zuò zhǔ， gè shuō běn de de fāng yán."],[2,1,"這事以後， 亞哈隨魯王的忿怒止息，就想念 瓦實提和她所行的，並怎樣降旨辦她。","zhè shì yǐ hòu， yà hā suí lǔ wáng de fèn nù zhǐ xī， jiù xiǎng niàn wǎ shí tí hé tā suǒ xíng de， bìng zěn yàng jiàng zhǐ bàn tā."],[2,2,"於是王的侍臣對王說：「不如為王尋找美貌的處女。","yú shì wáng de shì chén duì wáng shuō：‘bù rú wèi wáng xún zhǎo měi mào de chù nǚ."],[2,3,"王可以派官在國中的各省招聚美貌的處女到 書珊城的女院，交給掌管女子的太監 希該，給她們當用的香品。","wáng kě yǐ pài guān zài guó zhōng de gè shěng zhāo jù měi mào de chù nǚ dào shū shān chéng de nǚ yuàn， jiāo gěi zhǎng guǎn nǚ zǐ de tài jiān xī gāi， gěi tā men dāng yòng de xiāng pǐn."],[2,4,"王所喜愛的女子可以立為王后，代替 瓦實提。」王以這事為美，就如此行。","wáng suǒ xǐ ài de nǚ zǐ kě yǐ lì wèi wáng hòu， dài tì wǎ shí tí.’ wáng yǐ zhè shì wèi měi， jiù rú cǐ xíng."],[2,5,"書珊城有一個 猶大人，名叫 末底改，是 便雅憫人 基士的曾孫， 示每的孫子， 睚珥的兒子。","shū shān chéng yǒu yī gè yóu dà rén， míng jiào mò dǐ gǎi， shì biàn yǎ mǐn rén jī shì de céng sūn， shì měi de sūn zǐ， yá ěr de ér zǐ."],[2,6,"從前 巴比倫王 尼布甲尼撒將 猶大王 耶哥尼雅和百姓從 耶路撒冷擄去， 末底改也在其內。","cóng qián bā bǐ lún wáng ní bù jiǎ ní sā jiāng yóu dà wáng yé gē ní yǎ hé bǎi xìng cóng yé lù sā lěng lǔ qù， mò dǐ gǎi yě zài qí nèi."],[2,7,"末底改撫養他叔叔的女兒 哈大沙（後名 以斯帖），因為她沒有父母。這女子又容貌俊美；她父母死了， 末底改就收她為自己的女兒。","mò dǐ gǎi fǔ yǎng tā shū shū de nǚ ér hā dà shā （hòu míng yǐ sī tiē）， yīn wèi tā méi yǒu fù mǔ. zhè nǚ zǐ yòu róng mào jùn měi； tā fù mǔ sǐ le， mò dǐ gǎi jiù shōu tā wèi zì jǐ de nǚ ér."],[2,8,"王的諭旨傳出，就招聚許多女子到 書珊城，交給掌管女子的 希該； 以斯帖也送入王宮，交付 希該。","wáng de yù zhǐ chuán chū， jiù zhāo jù xǔ duō nǚ zǐ dào shū shān chéng， jiāo gěi zhǎng guǎn nǚ zǐ de xī gāi； yǐ sī tiē yě sòng rù wáng gōng， jiāo fù xī gāi."],[2,9,"希該喜悅 以斯帖，就恩待她，急忙給她需用的香品和她所當得的分，又派所當得的七個宮女服事她，使她和她的宮女搬入女院上好的房屋。","xī gāi xǐ yuè yǐ sī tiē， jiù ēn dài tā， jí máng gěi tā xū yòng de xiāng pǐn hé tā suǒ dāng dé de fēn， yòu pài suǒ dāng dé de qī gè gōng nǚ fú shì tā， shǐ tā hé tā de gōng nǚ bān rù nǚ yuàn shàng hǎo de fáng wū."],[2,10,"以斯帖未曾將籍貫宗族告訴人，因為 末底改囑咐她不可叫人知道。","yǐ sī tiē wèi céng jiāng jí guàn zōng zú gào sù rén， yīn wèi mò dǐ gǎi zhǔ fù tā bù kě jiào rén zhī dào."],[2,11,"末底改天天在女院前邊行走，要知道 以斯帖平安不平安，並後事如何。","mò dǐ gǎi tiān tiān zài nǚ yuàn qián biān xíng zǒu， yào zhī dào yǐ sī tiē píng ān bù píng ān， bìng hòu shì rú hé."],[2,12,"眾女子照例先潔淨身體十二個月：六個月用沒藥油，六個月用香料和潔身之物。滿了日期，然後挨次進去見 亞哈隨魯王。","zhòng nǚ zǐ zhào lì xiān jié jìng shēn tǐ shí èr gè yuè： liù gè yuè yòng méi yào yóu， liù gè yuè yòng xiāng liào hé jié shēn zhī wù. mǎn le rì qī， rán hòu āi cì jìn qù jiàn yà hā suí lǔ wáng."],[2,13,"女子進去見王是這樣：從女院到王宮的時候，凡她所要的都必給她。","nǚ zǐ jìn qù jiàn wáng shì zhè yàng： cóng nǚ yuàn dào wáng gōng de shí hòu， fán tā suǒ yào de dōu bì gěi tā."],[2,14,"晚上進去，次日回到女子第二院，交給掌管妃嬪的太監 沙甲；除非王喜愛她，再提名召她，就不再進去見王。","wǎn shàng jìn qù， cì rì huí dào nǚ zǐ dì èr yuàn， jiāo gěi zhǎng guǎn fēi pín de tài jiān shā jiǎ； chú fēi wáng xǐ ài tā， zài tí míng zhào tā， jiù bù zài jìn qù jiàn wáng."],[2,15,"末底改叔叔 亞比孩的女兒，就是 末底改收為自己女兒的 以斯帖，按次序當進去見王的時候，除了掌管女子的太監 希該所派定給她的，她別無所求。凡看見 以斯帖的都喜悅她。","mò dǐ gǎi shū shū yà bǐ hái de nǚ ér， jiù shì mò dǐ gǎi shōu wèi zì jǐ nǚ ér de yǐ sī tiē， àn cì xù dāng jìn qù jiàn wáng de shí hòu， chú le zhǎng guǎn nǚ zǐ de tài jiān xī gāi suǒ pài dìng gěi tā de， tā bié wú suǒ qiú. fán kàn jiàn yǐ sī tiē de dōu xǐ yuè tā."],[2,16,"亞哈隨魯王第七年十月，就是提別月， 以斯帖被引入宮見王。","yà hā suí lǔ wáng dì qī nián shí yuè， jiù shì tí bié yuè， yǐ sī tiē bèi yǐn rù gōng jiàn wáng."],[2,17,"王愛 以斯帖過於愛眾女，她在王眼前蒙寵愛比眾處女更甚。王就把王后的冠冕戴在她頭上，立她為王后，代替 瓦實提。","wáng ài yǐ sī tiē guò yú ài zhòng nǚ， tā zài wáng yǎn qián méng chǒng ài bǐ zhòng chù nǚ gèng shèn. wáng jiù bǎ wáng hòu de guān miǎn dài zài tā tóu shàng， lì tā wèi wáng hòu， dài tì wǎ shí tí."],[2,18,"王因 以斯帖的緣故給眾首領和臣僕設擺大筵席，又豁免各省的 租稅，並照王的厚意大頒賞賜。","wáng yīn yǐ sī tiē de yuán gù gěi zhòng shǒu lǐng hé chén pú shè bǎi dà yán xí， yòu huō miǎn gè shěng de zū shuì， bìng zhào wáng de hòu yì dà bān shǎng cì."],[2,19,"第二次招聚處女的時候， 末底改坐在朝門。","dì èr cì zhāo jù chù nǚ de shí hòu， mò dǐ gǎi zuò zài cháo mén."],[2,20,"以斯帖照着 末底改所囑咐的，還沒有將籍貫宗族告訴人；因為 以斯帖遵* 末底改的命，如撫養她的時候一樣。","yǐ sī tiē zhào zhe mò dǐ gǎi suǒ zhǔ fù de， hái méi yǒu jiāng jí guàn zōng zú gào sù rén； yīn wèi yǐ sī tiē zūn* mò dǐ gǎi de mìng， rú fǔ yǎng tā de shí hòu yī yàng."],[2,21,"當那時候， 末底改坐在朝門，王的太監中有兩個守門的， 辟探和 提列，惱恨 亞哈隨魯王，想要下手害他。","dāng nà shí hòu， mò dǐ gǎi zuò zài cháo mén， wáng de tài jiān zhōng yǒu liǎng gè shǒu mén de， pì tàn hé tí liè， nǎo hèn yà hā suí lǔ wáng， xiǎng yào xià shǒu hài tā."],[2,22,"末底改知道了，就告訴王后 以斯帖。 以斯帖奉 末底改的名，報告於王；","mò dǐ gǎi zhī dào le， jiù gào sù wáng hòu yǐ sī tiē. yǐ sī tiē fèng mò dǐ gǎi de míng， bào gào yú wáng；"],[2,23,"究察這事，果然是實，就把二人掛在木頭上，將這事在王面前寫於歷史上。","jiū chá zhè shì， guǒ rán shì shí， jiù bǎ èr rén guà zài mù tóu shàng， jiāng zhè shì zài wáng miàn qián xiě yú lì shǐ shàng."],[3,1,"這事以後， 亞哈隨魯王抬舉 亞甲族 哈米大他的兒子 哈曼，使他高升，叫他的爵位超過與他同事的一切臣宰。","zhè shì yǐ hòu， yà hā suí lǔ wáng tái jǔ yà jiǎ zú hā mǐ dà tā de ér zǐ hā màn， shǐ tā gāo shēng， jiào tā de jué wèi chāo guò yǔ tā tóng shì de yī qiè chén zǎi."],[3,2,"在朝門的一切臣僕都跪拜 哈曼，因為王如此吩咐；惟獨 末底改不跪不拜。","zài cháo mén de yī qiè chén pú dōu guì bài hā màn， yīn wèi wáng rú cǐ fēn fù； wéi dú mò dǐ gǎi bù guì bù bài."],[3,3,"在朝門的臣僕問 末底改說：「你為何違背王的命令呢？」","zài cháo mén de chén pú wèn mò dǐ gǎi shuō：‘nǐ wèi hé wéi bèi wáng de mìng lìng ne？’"],[3,4,"他們天天勸他，他還是不聽，他們就告訴 哈曼，要看 末底改的事站得住站不住，因他已經告訴他們自己是 猶大人。","tā men tiān tiān quàn tā， tā hái shì bù tīng， tā men jiù gào sù hā màn， yào kàn mò dǐ gǎi de shì zhàn dé zhù zhàn bù zhù， yīn tā yǐ jīng gào sù tā men zì jǐ shì yóu dà rén."],[3,5,"哈曼見 末底改不跪不拜，他就怒氣填胸。","hā màn jiàn mò dǐ gǎi bù guì bù bài， tā jiù nù qì tián xiōng."],[3,6,"他們已將 末底改的本族告訴 哈曼；他以為下手害 末底改一人是小事，就要滅絕 亞哈隨魯王通國所有的 猶大人，就是 末底改的本族。","tā men yǐ jiāng mò dǐ gǎi de běn zú gào sù hā màn； tā yǐ wèi xià shǒu hài mò dǐ gǎi yī rén shì xiǎo shì， jiù yào miè jué yà hā suí lǔ wáng tōng guó suǒ yǒu de yóu dà rén， jiù shì mò dǐ gǎi de běn zú."],[3,7,"亞哈隨魯王十二年正月，就是尼散月，人在 哈曼面前，按日日月月掣普珥，就是掣籤，要定何月何日為吉，擇定了十二月，就是亞達月。","yà hā suí lǔ wáng shí èr nián zhèng yuè， jiù shì ní sàn yuè， rén zài hā màn miàn qián， àn rì rì yuè yuè chè pǔ ěr， jiù shì chè qiān， yào dìng hé yuè hé rì wèi jí， zé dìng le shí èr yuè， jiù shì yà dá yuè."],[3,8,"哈曼對 亞哈隨魯王說：「有一種民散居在王國各省的民中；他們的律例與萬民的律例不同，也不守王的律例，所以容留他們與王無益。","hā màn duì yà hā suí lǔ wáng shuō：‘yǒu yī zhǒng mín sàn jū zài wáng guó gè shěng de mín zhōng； tā men de lǜ lì yǔ wàn mín de lǜ lì bù tóng， yě bù shǒu wáng de lǜ lì， suǒ yǐ róng liú tā men yǔ wáng wú yì."],[3,9,"王若以為美，請下旨意滅絕他們；我就捐一萬他連得銀子交給掌管國帑的人，納入王的府庫。」","wáng ruò yǐ wèi měi， qǐng xià zhǐ yì miè jué tā men； wǒ jiù juān yī wàn tā lián dé yín zǐ jiāo gěi zhǎng guǎn guó tǎng de rén， nà rù wáng de fǔ kù.’"],[3,10,"於是王從自己手上摘下戒指給 猶大人的仇敵－ 亞甲族 哈米大他的兒子 哈曼。","yú shì wáng cóng zì jǐ shǒu shàng zhāi xià jiè zhǐ gěi yóu dà rén de chóu dí－ yà jiǎ zú hā mǐ dà tā de ér zǐ hā màn."],[3,11,"王對 哈曼說：「這銀子仍賜給你，這民也交給你，你可以隨意待他們。」","wáng duì hā màn shuō：‘zhè yín zǐ réng cì gěi nǐ， zhè mín yě jiāo gěi nǐ， nǐ kě yǐ suí yì dài tā men.’"],[3,12,"正月十三日，就召了王的書記來，照着 哈曼一切所吩咐的，用各省的文字、各族的方言，奉 亞哈隨魯王的名寫旨意，傳與總督和各省的省長，並各族的首領；又用王的戒指蓋印，","zhèng yuè shí sān rì， jiù zhào le wáng de shū jì lái， zhào zhe hā màn yī qiè suǒ fēn fù de， yòng gè shěng de wén zì, gè zú de fāng yán， fèng yà hā suí lǔ wáng de míng xiě zhǐ yì， chuán yǔ zǒng dū hé gè shěng de shěng zhǎng， bìng gè zú de shǒu lǐng； yòu yòng wáng de jiè zhǐ gài yìn，"],[3,13,"交給驛卒傳到王的各省，吩咐將 猶大人，無論老少婦女孩子，在一日之間，十二月，就是亞達月十三日，全然剪除，殺戮滅絕，並奪他們的財為掠物。","jiāo gěi yì zú chuán dào wáng de gè shěng， fēn fù jiāng yóu dà rén， wú lùn lǎo shǎo fù nǚ hái zǐ， zài yī rì zhī jiān， shí èr yuè， jiù shì yà dá yuè shí sān rì， quán rán jiǎn chú， shā lù miè jué， bìng duó tā men de cái wèi lüè wù."],[3,14,"抄錄這旨意，頒行各省，宣告各族，使他們預備等候那日。","chāo lù zhè zhǐ yì， bān xíng gè shěng， xuān gào gè zú， shǐ tā men yù bèi děng hòu nà rì."],[3,15,"驛卒奉王命急忙起行，旨意也傳遍 書珊城。王同 哈曼坐下飲 酒， 書珊城的民卻都慌亂。","yì zú fèng wáng mìng jí máng qǐ xíng， zhǐ yì yě chuán biàn shū shān chéng. wáng tóng hā màn zuò xià yǐn jiǔ， shū shān chéng de mín què dōu huāng luàn."],[4,1,"末底改知道所做的這一切事，就撕裂衣服，穿麻衣，蒙灰塵，在城中行走，痛哭哀號。","mò dǐ gǎi zhī dào suǒ zuò de zhè yī qiè shì， jiù sī liè yī fú， chuān má yī， méng huī chén， zài chéng zhōng xíng zǒu， tòng kū āi hào."],[4,2,"到了朝門前 停住腳步，因為穿麻衣的不可進朝門。","dào le cháo mén qián tíng zhù jiǎo bù， yīn wèi chuān má yī de bù kě jìn cháo mén."],[4,3,"王的諭旨所到的各省各處， 猶大人大大悲哀，禁食哭泣哀號，穿麻衣躺在灰中的甚多。","wáng de yù zhǐ suǒ dào de gè shěng gè chù， yóu dà rén dà dà bēi āi， jìn shí kū qì āi hào， chuān má yī tǎng zài huī zhōng de shèn duō."],[4,4,"王后 以斯帖的宮女和太監來把這事告訴 以斯帖，她甚是憂愁，就送衣服給 末底改穿，要他脫下麻衣，他卻不受。","wáng hòu yǐ sī tiē de gōng nǚ hé tài jiān lái bǎ zhè shì gào sù yǐ sī tiē， tā shèn shì yōu chóu， jiù sòng yī fú gěi mò dǐ gǎi chuān， yào tā tuō xià má yī， tā què bù shòu."],[4,5,"以斯帖就把王所派伺候她的一個太監，名叫 哈他革召來，吩咐他去見 末底改，要知道這是甚麼事，是甚麼緣故。","yǐ sī tiē jiù bǎ wáng suǒ pài cì hòu tā de yī gè tài jiān， míng jiào hā tā gé zhào lái， fēn fù tā qù jiàn mò dǐ gǎi， yào zhī dào zhè shì shèn me shì， shì shèn me yuán gù."],[4,6,"於是 哈他革出到朝門前的寬闊處見 末底改。","yú shì hā tā gé chū dào cháo mén qián de kuān kuò chù jiàn mò dǐ gǎi."],[4,7,"末底改將自己所遇的事，並 哈曼為滅絕 猶大人應許捐入王庫的銀數都告訴了他；","mò dǐ gǎi jiāng zì jǐ suǒ yù de shì， bìng hā màn wèi miè jué yóu dà rén yīng xǔ juān rù wáng kù de yín shù dōu gào sù le tā；"],[4,8,"又將所抄寫傳遍 書珊城要滅絕 猶大人的旨意交給 哈他革，要給 以斯帖看，又要給她說明，並囑咐她進去見王，為本族的人在王面前懇切祈求。","yòu jiāng suǒ chāo xiě chuán biàn shū shān chéng yào miè jué yóu dà rén de zhǐ yì jiāo gěi hā tā gé， yào gěi yǐ sī tiē kàn， yòu yào gěi tā shuō míng， bìng zhǔ fù tā jìn qù jiàn wáng， wèi běn zú de rén zài wáng miàn qián kěn qiè qí qiú."],[4,9,"哈他革回來，將 末底改的話告訴 以斯帖；","hā tā gé huí lái， jiāng mò dǐ gǎi de huà gào sù yǐ sī tiē；"],[4,10,"以斯帖就吩咐 哈他革去見 末底改， 說：","yǐ sī tiē jiù fēn fù hā tā gé qù jiàn mò dǐ gǎi， shuō："],[4,11,"「王的一切臣僕和各省的人民都知道有一個定例：若不蒙召，擅入內院見王的，無論男女必被治死；除非王向他伸出金杖，不得存活。現在我沒有蒙召進去見王已經三十日了。」","‘wáng de yī qiè chén pú hé gè shěng de rén mín dōu zhī dào yǒu yī gè dìng lì： ruò bù méng zhào， shàn rù nèi yuàn jiàn wáng de， wú lùn nán nǚ bì bèi zhì sǐ； chú fēi wáng xiàng tā shēn chū jīn zhàng， bù dé cún huó. xiàn zài wǒ méi yǒu méng zhào jìn qù jiàn wáng yǐ jīng sān shí rì le.’"],[4,12,"人就把 以斯帖這話告訴 末底改。","rén jiù bǎ yǐ sī tiē zhè huà gào sù mò dǐ gǎi."],[4,13,"末底改託人回覆 以斯帖說：「你莫想在王宮裏強過一切 猶大人，得免這禍。","mò dǐ gǎi tuō rén huí fù yǐ sī tiē shuō：‘nǐ mò xiǎng zài wáng gōng lǐ qiáng guò yī qiè yóu dà rén， dé miǎn zhè huò."],[4,14,"此時你若閉口不言， 猶大人必從別處得解脫，蒙拯救；你和你父家必致滅亡。焉知你得了王后的位分不是為現今的機會嗎？」","cǐ shí nǐ ruò bì kǒu bù yán， yóu dà rén bì cóng bié chù dé jiě tuō， méng zhěng jiù； nǐ hé nǐ fù jiā bì zhì miè wáng. yān zhī nǐ dé le wáng hòu de wèi fēn bù shì wèi xiàn jīn de jī huì ma？’"],[4,15,"以斯帖就吩咐人回報 末底改說：","yǐ sī tiē jiù fēn fù rén huí bào mò dǐ gǎi shuō："],[4,16,"「你當去招聚 書珊城所有的 猶大人，為我禁食三晝三夜，不吃不喝；我和我的宮女也要這樣禁食。然後我違例進去見王，我若死就死吧！」","‘nǐ dāng qù zhāo jù shū shān chéng suǒ yǒu de yóu dà rén， wèi wǒ jìn shí sān zhòu sān yè， bù chī bù hē； wǒ hé wǒ de gōng nǚ yě yào zhè yàng jìn shí. rán hòu wǒ wéi lì jìn qù jiàn wáng， wǒ ruò sǐ jiù sǐ ba！’"],[4,17,"於是 末底改照 以斯帖一切所吩咐的去行。","yú shì mò dǐ gǎi zhào yǐ sī tiē yī qiè suǒ fēn fù de qù xíng."],[5,1,"第三日， 以斯帖穿上朝服，進王宮的內院，對殿站立。王在殿裏坐在寶座上，對着殿門。","dì sān rì， yǐ sī tiē chuān shàng cháo fú， jìn wáng gōng de nèi yuàn， duì diàn zhàn lì. wáng zài diàn lǐ zuò zài bǎo zuò shàng， duì zhe diàn mén."],[5,2,"王見王后 以斯帖站在院內，就施恩於她，向她伸出手中的金杖； 以斯帖便向前摸杖頭。","wáng jiàn wáng hòu yǐ sī tiē zhàn zài yuàn nèi， jiù shī ēn yú tā， xiàng tā shēn chū shǒu zhōng de jīn zhàng； yǐ sī tiē biàn xiàng qián mō zhàng tóu."],[5,3,"王對她說：「王后 以斯帖啊，你要甚麼？你求甚麼，就是國的一半也必賜給你。」","wáng duì tā shuō：‘wáng hòu yǐ sī tiē a， nǐ yào shèn me？ nǐ qiú shèn me， jiù shì guó de yī bàn yě bì cì gěi nǐ.’"],[5,4,"以斯帖說：「王若以為美，就請王帶着 哈曼今日赴我所預備的筵席。」","yǐ sī tiē shuō：‘wáng ruò yǐ wèi měi， jiù qǐng wáng dài zhe hā màn jīn rì fù wǒ suǒ yù bèi de yán xí.’"],[5,5,"王說：「叫 哈曼速速照 以斯帖的話去行。」於是王帶着 哈曼赴 以斯帖所預備的筵席。","wáng shuō：‘jiào hā màn sù sù zhào yǐ sī tiē de huà qù xíng.’ yú shì wáng dài zhe hā màn fù yǐ sī tiē suǒ yù bèi de yán xí."],[5,6,"在酒席筵前，王又問 以斯帖說：「你要甚麼，我必賜給你；你求甚麼，就是國的一半也必 為你成就。」","zài jiǔ xí yán qián， wáng yòu wèn yǐ sī tiē shuō：‘nǐ yào shèn me， wǒ bì cì gěi nǐ； nǐ qiú shèn me， jiù shì guó de yī bàn yě bì wèi nǐ chéng jiù.’"],[5,7,"以斯帖回答說：「我有所要，我有所求。","yǐ sī tiē huí dá shuō：‘wǒ yǒu suǒ yào， wǒ yǒu suǒ qiú."],[5,8,"我若在王眼前蒙恩，王若願意賜我所要的，准我所求的，就請王帶着 哈曼再赴我所要預備的筵席。明日我必照王所問的說明。」","wǒ ruò zài wáng yǎn qián méng ēn， wáng ruò yuàn yì cì wǒ suǒ yào de， zhǔn wǒ suǒ qiú de， jiù qǐng wáng dài zhe hā màn zài fù wǒ suǒ yào yù bèi de yán xí. míng rì wǒ bì zhào wáng suǒ wèn de shuō míng.’"],[5,9,"那日 哈曼心中快樂，歡歡喜喜地出來；但見 末底改在朝門不站起來，連身也不動，就滿心惱怒 末底改。","nà rì hā màn xīn zhōng kuài lè， huān huān xǐ xǐ de chū lái； dàn jiàn mò dǐ gǎi zài cháo mén bù zhàn qǐ lái， lián shēn yě bù dòng， jiù mǎn xīn nǎo nù mò dǐ gǎi."],[5,10,"哈曼暫且忍耐回家，叫人請他朋友和他妻子 細利斯來。","hā màn zàn qiě rěn nài huí jiā， jiào rén qǐng tā péng yǒu hé tā qī zǐ xì lì sī lái."],[5,11,"哈曼將他富厚的榮耀、眾多的兒女，和王抬舉他使他超乎首領臣僕之上，都述說給他們聽。","hā màn jiāng tā fù hòu de róng yào, zhòng duō de ér nǚ， hé wáng tái jǔ tā shǐ tā chāo hū shǒu lǐng chén pú zhī shàng， dōu shù shuō gěi tā men tīng."],[5,12,"哈曼又說：「王后 以斯帖預備筵席，除了我之外不許別人隨王赴席。明日王后又請我隨王赴席；","hā màn yòu shuō：‘wáng hòu yǐ sī tiē yù bèi yán xí， chú le wǒ zhī wài bù xǔ bié rén suí wáng fù xí. míng rì wáng hòu yòu qǐng wǒ suí wáng fù xí；"],[5,13,"只是我見 猶大人 末底改坐在朝門，雖有這一切 榮耀，也與我無益。」","zhǐ shì wǒ jiàn yóu dà rén mò dǐ gǎi zuò zài cháo mén， suī yǒu zhè yī qiè róng yào， yě yǔ wǒ wú yì.’"],[5,14,"他的妻 細利斯和他一切的朋友對他說：「不如立一個五丈高的木架，明早求王將 末底改掛在其上，然後你可以歡歡喜喜地隨王赴席。」 哈曼以這話為美，就叫人做了木架。","tā de qī xì lì sī hé tā yī qiè de péng yǒu duì tā shuō：‘bù rú lì yī gè wǔ zhàng gāo de mù jià， míng zǎo qiú wáng jiāng mò dǐ gǎi guà zài qí shàng， rán hòu nǐ kě yǐ huān huān xǐ xǐ de suí wáng fù xí.’ hā màn yǐ zhè huà wèi měi， jiù jiào rén zuò le mù jià."],[6,1,"那夜王睡不着覺，就吩咐人取歷史來，念給他聽。","nà yè wáng shuì bù zhe jué， jiù fēn fù rén qǔ lì shǐ lái， niàn gěi tā tīng."],[6,2,"正遇見書上寫着 說：王的太監中有兩個守門的， 辟探和 提列，想要下手害 亞哈隨魯王， 末底改將這事告訴 王后。","zhèng yù jiàn shū shàng xiě zhe shuō： wáng de tài jiān zhōng yǒu liǎng gè shǒu mén de， pì tàn hé tí liè， xiǎng yào xià shǒu hài yà hā suí lǔ wáng， mò dǐ gǎi jiāng zhè shì gào sù wáng hòu."],[6,3,"王說：「 末底改行了這事，賜他甚麼尊榮爵位沒有？」伺候王的臣僕回答說：「沒有賜他甚麼。」","wáng shuō：‘ mò dǐ gǎi xíng le zhè shì， cì tā shèn me zūn róng jué wèi méi yǒu？’ cì hòu wáng de chén pú huí dá shuō：‘méi yǒu cì tā shèn me.’"],[6,4,"王說：「誰在院子裏？」（那時 哈曼正進王宮的外院，要求王將 末底改掛在他所預備的木架上。）","wáng shuō：‘shuí zài yuàn zǐ lǐ？’（nà shí hā màn zhèng jìn wáng gōng de wài yuàn， yào qiú wáng jiāng mò dǐ gǎi guà zài tā suǒ yù bèi de mù jià shàng.）"],[6,5,"臣僕說：「 哈曼站在院內。」王說：「叫他進來。」","chén pú shuō：‘ hā màn zhàn zài yuàn nèi.’ wáng shuō：‘jiào tā jìn lái.’"],[6,6,"哈曼就進去。王問他說：「王所喜悅尊榮的人，當如何待他呢？」 哈曼心裏說：「王所喜悅尊榮的，不是我是誰呢？」","hā màn jiù jìn qù. wáng wèn tā shuō：‘wáng suǒ xǐ yuè zūn róng de rén， dāng rú hé dài tā ne？’ hā màn xīn lǐ shuō：‘wáng suǒ xǐ yuè zūn róng de， bù shì wǒ shì shuí ne？’"],[6,7,"哈曼就回答說：「王所喜悅尊榮的，","hā màn jiù huí dá shuō：‘wáng suǒ xǐ yuè zūn róng de，"],[6,8,"當將王常穿的朝服和戴冠的御馬，","dāng jiāng wáng cháng chuān de cháo fú hé dài guān de yù mǎ，"],[6,9,"都交給王極尊貴的一個大臣，命他將衣服給王所喜悅尊榮的人穿上，使他騎上馬，走遍城裏的街市，在他面前宣告說：王所喜悅尊榮的人，就如此待他。」","dōu jiāo gěi wáng jí zūn guì de yī gè dà chén， mìng tā jiāng yī fú gěi wáng suǒ xǐ yuè zūn róng de rén chuān shàng， shǐ tā qí shàng mǎ， zǒu biàn chéng lǐ de jiē shì， zài tā miàn qián xuān gào shuō： wáng suǒ xǐ yuè zūn róng de rén， jiù rú cǐ dài tā.’"],[6,10,"王對 哈曼說：「你速速將這衣服和馬，照你所說的，向坐在朝門的 猶大人 末底改去行。凡你所說的，一樣不可缺。」","wáng duì hā màn shuō：‘nǐ sù sù jiāng zhè yī fú hé mǎ， zhào nǐ suǒ shuō de， xiàng zuò zài cháo mén de yóu dà rén mò dǐ gǎi qù xíng. fán nǐ suǒ shuō de， yī yàng bù kě quē.’"],[6,11,"於是 哈曼將朝服給 末底改穿上，使他騎上馬，走遍城裏的街市，在他面前宣告說：「王所喜悅尊榮的人，就如此待他。」","yú shì hā màn jiāng cháo fú gěi mò dǐ gǎi chuān shàng， shǐ tā qí shàng mǎ， zǒu biàn chéng lǐ de jiē shì， zài tā miàn qián xuān gào shuō：‘wáng suǒ xǐ yuè zūn róng de rén， jiù rú cǐ dài tā.’"],[6,12,"末底改仍回到朝門， 哈曼卻憂憂悶悶地蒙着頭，急忙回家去了，","mò dǐ gǎi réng huí dào cháo mén， hā màn què yōu yōu mèn mèn de méng zhe tóu， jí máng huí jiā qù le，"],[6,13,"將所遇的一切事詳細說給他的妻 細利斯和他的眾朋友聽。他的智慧人和他的妻 細利斯對他說：「你在 末底改面前始而敗落，他如果是 猶大人，你必不能勝他，終必在他面前敗落。」","jiāng suǒ yù de yī qiè shì xiáng xì shuō gěi tā de qī xì lì sī hé tā de zhòng péng yǒu tīng. tā de zhì huì rén hé tā de qī xì lì sī duì tā shuō：‘nǐ zài mò dǐ gǎi miàn qián shǐ ér bài luò， tā rú guǒ shì yóu dà rén， nǐ bì bù néng shèng tā， zhōng bì zài tā miàn qián bài luò.’"],[6,14,"他們還與 哈曼說話的時候，王的太監來催 哈曼快去赴 以斯帖所預備的筵席。","tā men hái yǔ hā màn shuō huà de shí hòu， wáng de tài jiān lái cuī hā màn kuài qù fù yǐ sī tiē suǒ yù bèi de yán xí."],[7,1,"王帶着 哈曼來赴王后 以斯帖的筵席。","wáng dài zhe hā màn lái fù wáng hòu yǐ sī tiē de yán xí."],[7,2,"這第二次在酒席筵前，王又問 以斯帖說：「王后 以斯帖啊，你要甚麼，我必賜給你；你求甚麼，*就是國的一半也必 為你成就。」","zhè dì èr cì zài jiǔ xí yán qián， wáng yòu wèn yǐ sī tiē shuō：‘wáng hòu yǐ sī tiē a， nǐ yào shèn me， wǒ bì cì gěi nǐ； nǐ qiú shèn me，*jiù shì guó de yī bàn yě bì wèi nǐ chéng jiù.’"],[7,3,"王后 以斯帖回答說：「我若在王眼前蒙恩，王若以為美，我所願的，是願王將我的性命賜給我；我所求的，是求王將我的本族賜給我。","wáng hòu yǐ sī tiē huí dá shuō：‘wǒ ruò zài wáng yǎn qián méng ēn， wáng ruò yǐ wèi měi， wǒ suǒ yuàn de， shì yuàn wáng jiāng wǒ de xìng mìng cì gěi wǒ； wǒ suǒ qiú de， shì qiú wáng jiāng wǒ de běn zú cì gěi wǒ."],[7,4,"因我和我的本族被賣了，要剪除殺戮滅絕我們。我們若被賣為奴為婢，我也閉口不言；但王的損失，敵人萬不能補足。」","yīn wǒ hé wǒ de běn zú bèi mài le， yào jiǎn chú shā lù miè jué wǒ men. wǒ men ruò bèi mài wèi nú wèi bì， wǒ yě bì kǒu bù yán； dàn wáng de sǔn shī， dí rén wàn bù néng bǔ zú.’"],[7,5,"亞哈隨魯王問王后 以斯帖說：「擅敢起意如此行的是誰？這人在哪裏呢？」","yà hā suí lǔ wáng wèn wáng hòu yǐ sī tiē shuō：‘shàn gǎn qǐ yì rú cǐ xíng de shì shuí？ zhè rén zài nǎ lǐ ne？’"],[7,6,"以斯帖說：「仇人敵人就是這惡人 哈曼！」 哈曼在王和王后面前就甚驚惶。","yǐ sī tiē shuō：‘chóu rén dí rén jiù shì zhè è rén hā màn！’ hā màn zài wáng hé wáng hòu miàn qián jiù shèn jīng huáng."],[7,7,"王便大怒，起來離開酒席往御園去了。 哈曼見王定意要加罪與他，就起來，求王后 以斯帖救命。","wáng biàn dà nù， qǐ lái lí kāi jiǔ xí wǎng yù yuán qù le. hā màn jiàn wáng dìng yì yào jiā zuì yǔ tā， jiù qǐ lái， qiú wáng hòu yǐ sī tiē jiù mìng."],[7,8,"王從御園回到酒席之處，見 哈曼伏在 以斯帖所靠的榻上；王說：「他竟敢在宮內、在我面前凌辱王后嗎？」這話一出王口，人就蒙了 哈曼的臉。","wáng cóng yù yuán huí dào jiǔ xí zhī chù， jiàn hā màn fú zài yǐ sī tiē suǒ kào de tà shàng； wáng shuō：‘tā jìng gǎn zài gōng nèi, zài wǒ miàn qián líng rǔ wáng hòu ma？’ zhè huà yī chū wáng kǒu， rén jiù méng le hā màn de liǎn."],[7,9,"伺候王的一個太監名叫 哈波拿，說：「 哈曼為那救王有功的 末底改做了五丈高的木架，現今立在 哈曼家裏。」王說：「把 哈曼掛在其上。」","cì hòu wáng de yī gè tài jiān míng jiào hā bō ná， shuō：‘ hā màn wèi nà jiù wáng yǒu gōng de mò dǐ gǎi zuò le wǔ zhàng gāo de mù jià， xiàn jīn lì zài hā màn jiā lǐ.’ wáng shuō：‘bǎ hā màn guà zài qí shàng.’"],[7,10,"於是人將 哈曼掛在他為 末底改所預備的木架上。王的忿怒這才止息。","yú shì rén jiāng hā màn guà zài tā wèi mò dǐ gǎi suǒ yù bèi de mù jià shàng. wáng de fèn nù zhè cái zhǐ xī."],[8,1,"當日， 亞哈隨魯王把 猶大人仇敵 哈曼的家產賜給王后 以斯帖。 末底改也來到王面前，因為 以斯帖已經告訴王， 末底改是她的親屬。","dāng rì， yà hā suí lǔ wáng bǎ yóu dà rén chóu dí hā màn de jiā chǎn cì gěi wáng hòu yǐ sī tiē. mò dǐ gǎi yě lái dào wáng miàn qián， yīn wèi yǐ sī tiē yǐ jīng gào sù wáng， mò dǐ gǎi shì tā de qīn shǔ."],[8,2,"王摘下自己的戒指，就是從 哈曼追回的，給了 末底改。 以斯帖派 末底改管理 哈曼的家產。","wáng zhāi xià zì jǐ de jiè zhǐ， jiù shì cóng hā màn zhuī huí de， gěi le mò dǐ gǎi. yǐ sī tiē pài mò dǐ gǎi guǎn lǐ hā màn de jiā chǎn."],[8,3,"以斯帖又俯伏在王腳前，流淚哀告，求他除掉 亞甲族 哈曼害 猶大人的惡謀。","yǐ sī tiē yòu fǔ fú zài wáng jiǎo qián， liú lèi āi gào， qiú tā chú diào yà jiǎ zú hā màn hài yóu dà rén de è móu."],[8,4,"王向 以斯帖伸出金杖； 以斯帖就起來，站在王前，","wáng xiàng yǐ sī tiē shēn chū jīn zhàng； yǐ sī tiē jiù qǐ lái， zhàn zài wáng qián，"],[8,5,"說：「 亞甲族 哈米大他的兒子 哈曼設謀傳旨，要殺滅在王各省的 猶大人。現今王若願意，我若在王眼前蒙恩，王若以為美，若喜悅我，請王另下旨意，廢除 哈曼所傳的那旨意。","shuō：‘ yà jiǎ zú hā mǐ dà tā de ér zǐ hā màn shè móu chuán zhǐ， yào shā miè zài wáng gè shěng de yóu dà rén. xiàn jīn wáng ruò yuàn yì， wǒ ruò zài wáng yǎn qián méng ēn， wáng ruò yǐ wèi měi， ruò xǐ yuè wǒ， qǐng wáng lìng xià zhǐ yì， fèi chú hā màn suǒ chuán de nà zhǐ yì."],[8,6,"我何忍見我本族的人受害？何忍見我同宗的人被滅呢？」","wǒ hé rěn jiàn wǒ běn zú de rén shòu hài？ hé rěn jiàn wǒ tóng zōng de rén bèi miè ne？’"],[8,7,"亞哈隨魯王對王后 以斯帖和 猶大人 末底改說：「因 哈曼要下手害 猶大人，我已將他的家產賜給 以斯帖，人也將 哈曼掛在木架上。","yà hā suí lǔ wáng duì wáng hòu yǐ sī tiē hé yóu dà rén mò dǐ gǎi shuō：‘yīn hā màn yào xià shǒu hài yóu dà rén， wǒ yǐ jiāng tā de jiā chǎn cì gěi yǐ sī tiē， rén yě jiāng hā màn guà zài mù jià shàng."],[8,8,"現在你們可以隨意奉王的名寫諭旨給 猶大人，用王的戒指蓋印；因為奉王名所寫、用王戒指蓋印的諭旨，人都不能廢除。」","xiàn zài nǐ men kě yǐ suí yì fèng wáng de míng xiě yù zhǐ gěi yóu dà rén， yòng wáng de jiè zhǐ gài yìn； yīn wèi fèng wáng míng suǒ xiě, yòng wáng jiè zhǐ gài yìn de yù zhǐ， rén dōu bù néng fèi chú.’"],[8,9,"三月，就是西彎月二十三日，將王的書記召來，按着 末底改所吩咐的，用各省的文字、各族的方言，並 猶大人的文字方言寫諭旨，傳給那從 印度直到 古實一百二十七省的 猶大人和總督省長首領。","sān yuè， jiù shì xī wān yuè èr shí sān rì， jiāng wáng de shū jì zhào lái， àn zhe mò dǐ gǎi suǒ fēn fù de， yòng gè shěng de wén zì, gè zú de fāng yán， bìng yóu dà rén de wén zì fāng yán xiě yù zhǐ， chuán gěi nà cóng yìn dù zhí dào gǔ shí yī bǎi èr shí qī shěng de yóu dà rén hé zǒng dū shěng zhǎng shǒu lǐng."],[8,10,"末底改奉 亞哈隨魯王的名寫諭旨，用王的戒指蓋印，交給騎御馬圈快馬的驛卒，傳 到各處。","mò dǐ gǎi fèng yà hā suí lǔ wáng de míng xiě yù zhǐ， yòng wáng de jiè zhǐ gài yìn， jiāo gěi qí yù mǎ quān kuài mǎ de yì zú， chuán dào gè chù."],[8,11,"諭旨中，王准各省各城的 猶大人在一日之間，十二月，就是亞達月十三日，聚集保護性命，剪除殺戮滅絕那要攻擊 猶大人的一切仇敵和他們的妻子兒女，奪取他們的財為掠物。","yù zhǐ zhōng， wáng zhǔn gè shěng gè chéng de yóu dà rén zài yī rì zhī jiān， shí èr yuè， jiù shì yà dá yuè shí sān rì， jù jí bǎo hù xìng mìng， jiǎn chú shā lù miè jué nà yào gōng jī yóu dà rén de yī qiè chóu dí hé tā men de qī zǐ ér nǚ， duó qǔ tā men de cái wèi lüè wù."],[8,13,"抄錄這諭旨，頒行各省，宣告各族，使 猶大人預備等候那日，在仇敵身上報仇。","chāo lù zhè yù zhǐ， bān xíng gè shěng， xuān gào gè zú， shǐ yóu dà rén yù bèi děng hòu nà rì， zài chóu dí shēn shàng bào chóu."],[8,14,"於是騎快馬的驛卒被王命催促，急忙起行；諭旨也傳遍 書珊城。","yú shì qí kuài mǎ de yì zú bèi wáng mìng cuī cù， jí máng qǐ xíng； yù zhǐ yě chuán biàn shū shān chéng."],[8,15,"末底改穿着藍色白色的朝服，頭戴大金冠冕，又穿紫色細麻布的外袍，從王面前出來； 書珊城的人民都歡呼快樂。","mò dǐ gǎi chuān zhe lán sè bái sè de cháo fú， tóu dài dà jīn guān miǎn， yòu chuān zǐ sè xì má bù de wài páo， cóng wáng miàn qián chū lái； shū shān chéng de rén mín dōu huān hū kuài lè."],[8,16,"猶大人有光榮，歡喜快樂而得尊貴。","yóu dà rén yǒu guāng róng， huān xǐ kuài lè ér dé zūn guì."],[8,17,"王的諭旨所到的各省各城， 猶大人都歡喜快樂，設擺筵宴，以那日為吉日。那國的人民，有許多因懼怕 猶大人，就入了 猶大籍。","wáng de yù zhǐ suǒ dào de gè shěng gè chéng， yóu dà rén dōu huān xǐ kuài lè， shè bǎi yán yàn， yǐ nà rì wèi jí rì. nà guó de rén mín， yǒu xǔ duō yīn jù pà yóu dà rén， jiù rù le yóu dà jí."],[9,1,"十二月，乃亞達月十三日，王的諭旨將要舉行，就是 猶大人的仇敵盼望轄制他們的日子， 猶大人反倒轄制恨他們的人。","shí èr yuè， nǎi yà dá yuè shí sān rì， wáng de yù zhǐ jiāng yào jǔ xíng， jiù shì yóu dà rén de chóu dí pàn wàng xiá zhì tā men de rì zǐ， yóu dà rén fǎn dào xiá zhì hèn tā men de rén."],[9,2,"猶大人在 亞哈隨魯王各省的城裏聚集，下手擊殺那要害他們的人。無人能敵擋他們，因為各族都懼怕他們。","yóu dà rén zài yà hā suí lǔ wáng gè shěng de chéng lǐ jù jí， xià shǒu jī shā nà yào hài tā men de rén. wú rén néng dí dǎng tā men， yīn wèi gè zú dōu jù pà tā men."],[9,3,"各省的首領、總督、省長，和辦理王事的人，因懼怕 末底改，就都幫助 猶大人。","gè shěng de shǒu lǐng, zǒng dū, shěng zhǎng， hé bàn lǐ wáng shì de rén， yīn jù pà mò dǐ gǎi， jiù dōu bāng zhù yóu dà rén."],[9,4,"末底改在朝中為大，名聲傳遍各省，日漸昌盛。","mò dǐ gǎi zài cháo zhōng wèi dà， míng shēng chuán biàn gè shěng， rì jiàn chāng shèng."],[9,5,"猶大人用刀擊殺一切仇敵，任意殺滅恨他們的人。","yóu dà rén yòng dāo jī shā yī qiè chóu dí， rèn yì shā miè hèn tā men de rén."],[9,6,"在 書珊城， 猶大人殺滅了五百人；","zài shū shān chéng， yóu dà rén shā miè le wǔ bǎi rén；"],[9,7,"又殺 巴珊大他、 達分、 亞斯帕他、","yòu shā bā shān dà tā, dá fēn, yà sī pà tā,"],[9,8,"破拉他、 亞大利雅、 亞利大他、","pò lā tā, yà dà lì yǎ, yà lì dà tā,"],[9,9,"帕瑪斯他、 亞利賽、 亞利代、 瓦耶撒他；","pà mǎ sī tā, yà lì sài, yà lì dài, wǎ yé sā tā；"],[9,10,"這十人都是 哈米大他的孫子、 猶大人仇敵 哈曼的兒子。 猶大人卻沒有下手奪取財物。","zhè shí rén dōu shì hā mǐ dà tā de sūn zǐ, yóu dà rén chóu dí hā màn de ér zǐ. yóu dà rén què méi yǒu xià shǒu duó qǔ cái wù."],[9,11,"當日，將 書珊城被殺的人數呈在王前。","dāng rì， jiāng shū shān chéng bèi shā de rén shù chéng zài wáng qián."],[9,12,"王對王后 以斯帖說：「 猶大人在 書珊城殺滅了五百人，又殺了 哈曼的十個兒子，在王的各省不知如何呢？現在你要甚麼，我必賜給你；你還求甚麼，也必 為你成就。」","wáng duì wáng hòu yǐ sī tiē shuō：‘ yóu dà rén zài shū shān chéng shā miè le wǔ bǎi rén， yòu shā le hā màn de shí gè ér zǐ， zài wáng de gè shěng bù zhī rú hé ne？ xiàn zài nǐ yào shèn me， wǒ bì cì gěi nǐ； nǐ hái qiú shèn me， yě bì wèi nǐ chéng jiù.’"],[9,13,"以斯帖說：「王若以為美，求你准 書珊的 猶大人，明日也照今日的旨意行，並將 哈曼十個兒子的屍首掛在木架上。」","yǐ sī tiē shuō：‘wáng ruò yǐ wèi měi， qiú nǐ zhǔn shū shān de yóu dà rén， míng rì yě zhào jīn rì de zhǐ yì xíng， bìng jiāng hā màn shí gè ér zǐ de shī shǒu guà zài mù jià shàng.’"],[9,14,"王便允准如此行。旨意傳在 書珊，人就把 哈曼十個兒子的屍首掛起來了。","wáng biàn yǔn zhǔn rú cǐ xíng. zhǐ yì chuán zài shū shān， rén jiù bǎ hā màn shí gè ér zǐ de shī shǒu guà qǐ lái le."],[9,15,"亞達月十四日， 書珊的 猶大人又聚集在 書珊，殺了三百人，卻沒有下手奪取財物。","yà dá yuè shí sì rì， shū shān de yóu dà rén yòu jù jí zài shū shān， shā le sān bǎi rén， què méi yǒu xià shǒu duó qǔ cái wù."],[9,16,"在王各省其餘的 猶大人也都聚集保護性命，殺了恨他們的人七萬五千，卻沒有下手奪取財物。這樣，就脫離仇敵，得享平安。","zài wáng gè shěng qí yú de yóu dà rén yě dōu jù jí bǎo hù xìng mìng， shā le hèn tā men de rén qī wàn wǔ qiān， què méi yǒu xià shǒu duó qǔ cái wù. zhè yàng， jiù tuō lí chóu dí， dé xiǎng píng ān."],[9,17,"亞達月十三日， 行了這事；十四日安息，以這日為設筵歡樂的日子。","yà dá yuè shí sān rì， xíng le zhè shì； shí sì rì ān xī， yǐ zhè rì wèi shè yán huān lè de rì zǐ."],[9,18,"但 書珊的 猶大人，這十三日、十四日聚集 殺戮仇敵；十五日安息，以這日為設筵歡樂的日子。","dàn shū shān de yóu dà rén， zhè shí sān rì, shí sì rì jù jí shā lù chóu dí； shí wǔ rì ān xī， yǐ zhè rì wèi shè yán huān lè de rì zǐ."],[9,19,"所以住無城牆鄉村的 猶大人，如今都以亞達月十四日為設筵歡樂的吉日，彼此餽送禮物。","suǒ yǐ zhù wú chéng qiáng xiāng cūn de yóu dà rén， rú jīn dōu yǐ yà dá yuè shí sì rì wèi shè yán huān lè de jí rì， bǐ cǐ kuì sòng lǐ wù."],[9,20,"末底改記錄這事，寫信與 亞哈隨魯王各省遠近所有的 猶大人，","mò dǐ gǎi jì lù zhè shì， xiě xìn yǔ yà hā suí lǔ wáng gè shěng yuǎn jìn suǒ yǒu de yóu dà rén，"],[9,21,"囑咐他們每年守亞達月十四、十五兩日，","zhǔ fù tā men měi nián shǒu yà dá yuè shí sì, shí wǔ liǎng rì，"],[9,22,"以這月的兩日為 猶大人脫離仇敵得平安、轉憂為喜、轉悲為樂的吉日。在這兩日設筵歡樂，彼此餽送禮物，賙濟窮人。","yǐ zhè yuè de liǎng rì wèi yóu dà rén tuō lí chóu dí dé píng ān, zhuǎn yōu wèi xǐ, zhuǎn bēi wèi lè de jí rì. zài zhè liǎng rì shè yán huān lè， bǐ cǐ kuì sòng lǐ wù， zhōu jì qióng rén."],[9,23,"於是， 猶大人按着 末底改所寫與他們的信，應承照初次所守的守為永例；","yú shì， yóu dà rén àn zhe mò dǐ gǎi suǒ xiě yǔ tā men de xìn， yīng chéng zhào chū cì suǒ shǒu de shǒu wèi yǒng lì；"],[9,24,"是因 猶大人的仇敵 亞甲族 哈米大他的兒子 哈曼設謀殺害 猶大人，掣普珥，就是掣籤，為要殺盡滅絕他們；","shì yīn yóu dà rén de chóu dí yà jiǎ zú hā mǐ dà tā de ér zǐ hā màn shè móu shā hài yóu dà rén， chè pǔ ěr， jiù shì chè qiān， wèi yào shā jǐn miè jué tā men；"],[9,25,"這事報告於王，王便降旨使 哈曼謀害 猶大人的惡事歸到他自己的頭上，並吩咐把他和他的眾子都掛在木架上。","zhè shì bào gào yú wáng， wáng biàn jiàng zhǐ shǐ hā màn móu hài yóu dà rén de è shì guī dào tā zì jǐ de tóu shàng， bìng fēn fù bǎ tā hé tā de zhòng zǐ dōu guà zài mù jià shàng."],[9,26,"照着普珥的名字， 猶大人就稱這兩日為「普珥日」。他們因這信上的話，又因所看見所遇見的事，","zhào zhe pǔ ěr de míng zì， yóu dà rén jiù chēng zhè liǎng rì wèi‘pǔ ěr rì’. tā men yīn zhè xìn shàng de huà， yòu yīn suǒ kàn jiàn suǒ yù jiàn de shì，"],[9,27,"就應承自己與後裔，並歸附他們的人，每年按時必守這兩日，永遠不廢。","jiù yīng chéng zì jǐ yǔ hòu yì， bìng guī fù tā men de rén， měi nián àn shí bì shǒu zhè liǎng rì， yǒng yuǎn bù fèi."],[9,28,"各省各城、家家戶戶、世世代代紀念遵守這兩日，使這「普珥日」在 猶大人中不可廢掉，在他們後裔中也不可忘記。","gè shěng gè chéng, jiā jiā hù hù, shì shì dài dài jì niàn zūn shǒu zhè liǎng rì， shǐ zhè‘pǔ ěr rì’ zài yóu dà rén zhōng bù kě fèi diào， zài tā men hòu yì zhōng yě bù kě wàng jì."],[9,29,"亞比孩的女兒－王后 以斯帖和 猶大人 末底改以全權寫第二封信，堅囑 猶大人守這「普珥日」，","yà bǐ hái de nǚ ér－wáng hòu yǐ sī tiē hé yóu dà rén mò dǐ gǎi yǐ quán quán xiě dì èr fēng xìn， jiān zhǔ yóu dà rén shǒu zhè‘pǔ ěr rì’，"],[9,30,"用和平誠實話寫信給 亞哈隨魯 王國中一百二十七省所有的 猶大人，","yòng hé píng chéng shí huà xiě xìn gěi yà hā suí lǔ wáng guó zhōng yī bǎi èr shí qī shěng suǒ yǒu de yóu dà rén，"],[9,31,"勸他們按時守這「普珥日」，禁食呼求，是照 猶大人 末底改和王后 以斯帖所囑咐的，也照 猶大人為自己與後裔所應承的。","quàn tā men àn shí shǒu zhè‘pǔ ěr rì’， jìn shí hū qiú， shì zhào yóu dà rén mò dǐ gǎi hé wáng hòu yǐ sī tiē suǒ zhǔ fù de， yě zhào yóu dà rén wèi zì jǐ yǔ hòu yì suǒ yīng chéng de."],[9,32,"以斯帖命定守「普珥日」，這事也記錄在書上。","yǐ sī tiē mìng dìng shǒu‘pǔ ěr rì’， zhè shì yě jì lù zài shū shàng."],[10,1,"亞哈隨魯王使旱地和海島的人民都進貢。","yà hā suí lǔ wáng shǐ hàn de hé hǎi dǎo de rén mín dōu jìn gòng."],[10,2,"他以權柄能力所行的，並他抬舉 末底改使他高升的事，豈不都寫在 米底亞和 波斯王的歷史上嗎？","tā yǐ quán bǐng néng lì suǒ xíng de， bìng tā tái jǔ mò dǐ gǎi shǐ tā gāo shēng de shì， qǐ bù dōu xiě zài mǐ dǐ yà hé bō sī wáng de lì shǐ shàng ma？"],[10,3,"猶大人 末底改作 亞哈隨魯王的宰相，在 猶大人中為大，得他眾弟兄的喜悅，為本族的人求好處，向他們說和平的話。","yóu dà rén mò dǐ gǎi zuò yà hā suí lǔ wáng de zǎi xiāng， zài yóu dà rén zhōng wèi dà， dé tā zhòng dì xiōng de xǐ yuè， wèi běn zú de rén qiú hǎo chù， xiàng tā men shuō hé píng de huà."]],"arb-vandyck":[[1,1,"وَحَدَثَ فِي أَيَّامِ أَحَشْوِيرُوشَ، هُوَ أَحَشْوِيرُوشُ ٱلَّذِي مَلَكَ مِنَ ٱلْهِنْدِ إِلَى كُوشٍ عَلَى مِئَةٍ وَسَبْعٍ وَعِشْرِينَ كُورَةً،","waḥadatẖa fī ạảyãạmi ạảḥasẖ̊wīrūsẖa, hūa ạảḥasẖ̊wīrūsẖu ٱlãdẖī malaka mina ٱl̊hin̊di ại̹lay̱ kūsẖiⁿ ʿalay̱ mīảẗiⁿ wasab̊ʿiⁿ waʿisẖ̊rīna kūraẗaⁿ,"],[1,2,"أَنَّهُ فِي تِلْكَ ٱلْأَيَّامِ حِينَ جَلَسَ ٱلْمَلِكُ أَحَشْوِيرُوشُ عَلَى كُرْسِيِّ مُلْكِهِ ٱلَّذِي فِي شُوشَنَ ٱلْقَصْرِ،","ạảnãhu fī til̊ka ٱl̊ạảyãạmi ḥīna jalasa ٱl̊maliku ạảḥasẖ̊wīrūsẖu ʿalay̱ kur̊sīĩ mul̊kihi ٱlãdẖī fī sẖūsẖana ٱl̊qaṣ̊ri,"],[1,3,"فِي ٱلسَّنَةِ ٱلثَّالِثَةِ مِنْ مُلْكِهِ، عَمِلَ وَلِيمَةً لِجَمِيعِ رُؤَسَائِهِ وَعَبِيدِهِ جَيْشِ فَارِسَ وَمَادِي، وَأَمَامَهُ شُرَفَاءُ ٱلْبُلْدَانِ وَرُؤَسَاؤُهَا،","fī ٱlsãnaẗi ٱltẖãạlitẖaẗi min̊ mul̊kihi, ʿamila walīmaẗaⁿ lijamīʿi rūảsāyỉhi waʿabīdihi jaẙsẖi fārisa wamādī, wāảmāmahu sẖurafāʾu ٱl̊bul̊dāni warūảsāwủhā,"],[1,4,"حِينَ أَظْهَرَ غِنَى مَجْدِ مُلْكِهِ وَوَقَارَ جَلَالِ عَظَمَتِهِ أَيَّامًا كَثِيرَةً، مِئَةً وَثَمَانِينَ يَوْمًا.","ḥīna ạảẓ̊hara gẖinay̱ maj̊di mul̊kihi wawaqāra jalāli ʿaẓamatihi ạảyãạmaⁿạ katẖīraẗaⁿ, mīảẗaⁿ watẖamānīna yaẘmaⁿạ."],[1,5,"وَعِنْدَ ٱنْقِضَاءِ هَذِهِ ٱلْأَيَّامِ، عَمِلَ ٱلْمَلِكُ لِجَمِيعِ ٱلشَّعْبِ ٱلْمَوْجُودِينَ فِي شُوشَنَ ٱلْقَصْرِ، مِنَ ٱلْكَبِيرِ إِلَى ٱلصَّغِيرِ، وَلِيمَةً سَبْعَةَ أَيَّامٍ فِي دَارِ جَنَّةِ قَصْرِ ٱلْمَلِكِ.","waʿin̊da ٱn̊qiḍāʾi hadẖihi ٱl̊ạảyãạmi, ʿamila ٱl̊maliku lijamīʿi ٱlsẖãʿ̊bi ٱl̊maẘjūdīna fī sẖūsẖana ٱl̊qaṣ̊ri, mina ٱl̊kabīri ại̹lay̱ ٱlṣãgẖīri, walīmaẗaⁿ sab̊ʿaẗa ạảyãạmiⁿ fī dāri janãẗi qaṣ̊ri ٱl̊maliki."],[1,6,"بِأَنْسِجَةٍ بَيْضَاءَ وَخَضْرَاءَ وَأَسْمَانْجُونِيَّةٍ مُعَلَّقَةٍ بِحِبَالٍ مِنْ بَزٍّ وَأُرْجُوانٍ، فِي حَلَقَاتٍ مِنْ فِضَّةٍ، وَأَعْمِدَةٍ مِنْ رُخَامٍ، وَأَسِرَّةٍ مِنْ ذَهَبٍ وَفِضَّةٍ، عَلَى مُجَزَّعٍ مِنْ بَهْتٍ وَمَرْمَرٍ وَدُرٍّ وَرُخَامٍ أَسْوَدَ.","biạản̊sijaẗiⁿ baẙḍāʾa wakẖaḍ̊rāʾa wāảs̊mān̊jūnīãẗiⁿ muʿalãqaẗiⁿ biḥibāliⁿ min̊ baziⁿ̃ wāủr̊jūạniⁿ, fī ḥalaqātiⁿ min̊ fiḍãẗiⁿ, wāảʿ̊midaẗiⁿ min̊ rukẖāmiⁿ, wāảsirãẗiⁿ min̊ dẖahabiⁿ wafiḍãẗiⁿ, ʿalay̱ mujazãʿiⁿ min̊ bah̊tiⁿ wamar̊mariⁿ waduriⁿ̃ warukẖāmiⁿ ạảs̊wada."],[1,7,"وَكَانَ ٱلسِّقَاءُ مِنْ ذَهَبٍ، وَٱلْآنِيَةُ مُخْتَلِفَةُ ٱلْأَشْكَالِ، وَٱلْخَمْرُ ٱلْمَلِكِيُّ بِكَثْرَةٍ حَسَبَ كَرَمِ ٱلْمَلِكِ.","wakāna ٱlsĩqāʾu min̊ dẖahabiⁿ, waٱl̊ậnīaẗu mukẖ̊talifaẗu ٱl̊ạảsẖ̊kāli, waٱl̊kẖam̊ru ٱl̊malikīũ bikatẖ̊raẗiⁿ ḥasaba karami ٱl̊maliki."],[1,8,"وَكَانَ ٱلشُّرْبُ حَسَبَ ٱلْأَمْرِ. لَمْ يَكُنْ غَاصِبٌ، لِأَنَّهُ هَكَذَا رَسَمَ ٱلْمَلِكُ عَلَى كُلِّ عَظِيمٍ فِي بَيْتِهِ أَنْ يَعْمَلُوا حَسَبَ رِضَا كُلِّ وَاحِدٍ.","wakāna ٱlsẖũr̊bu ḥasaba ٱl̊ạảm̊ri. lam̊ yakun̊ gẖāṣibuⁿ, liạảnãhu hakadẖā rasama ٱl̊maliku ʿalay̱ kulĩ ʿaẓīmiⁿ fī baẙtihi ạản̊ yaʿ̊malūạ ḥasaba riḍā kulĩ wāḥidiⁿ."],[1,9,"وَوَشْتِي ٱلْمَلِكَةُ عَمِلَتْ أَيْضًا وَلِيمَةً لِلنِّسَاءِ فِي بَيْتِ ٱلْمُلْكِ ٱلَّذِي لِلْمَلِكِ أَحَشْوِيرُوشَ.","wawasẖ̊tī ٱl̊malikaẗu ʿamilat̊ ạảẙḍaⁿạ walīmaẗaⁿ lilnĩsāʾi fī baẙti ٱl̊mul̊ki ٱlãdẖī lil̊maliki ạảḥasẖ̊wīrūsẖa."],[1,10,"فِي ٱلْيَوْمِ ٱلسَّابِعِ لَمَّا طَابَ قَلْبُ ٱلْمَلِكِ بِٱلْخَمْرِ، قَالَ لِمَهُومَانَ وَبِزْثَا وَحَرْبُونَا وَبِغْثَا وَأَبَغْثَا وَزِيثَارَ وَكَرْكَسَ، ٱلْخِصْيَانِ ٱلسَّبْعَةِ ٱلَّذِينَ كَانُوا يَخْدِمُونَ بَيْنَ يَدَيِ ٱلْمَلِكِ أَحَشْوِيرُوشَ،","fī ٱl̊yaẘmi ٱlsãạbiʿi lamãạ ṭāba qal̊bu ٱl̊maliki biٱl̊kẖam̊ri, qāla limahūmāna wabiz̊tẖā waḥar̊būnā wabigẖ̊tẖā wāảbagẖ̊tẖā wazītẖāra wakar̊kasa, ٱl̊kẖiṣ̊yāni ٱlsãb̊ʿaẗi ٱlãdẖīna kānūạ yakẖ̊dimūna baẙna yadayi ٱl̊maliki ạảḥasẖ̊wīrūsẖa,"],[1,11,"أَنْ يَأْتُوا بِوَشْتِي ٱلْمَلِكَةِ إِلَى أَمَامِ ٱلْمَلِكِ بِتَاجِ ٱلْمُلْكِ، لِيُرِيَ ٱلشُّعُوبَ وَٱلرُّؤَسَاءَ جَمَالَهَا، لِأَنَّهَا كَانَتْ حَسَنَةَ ٱلْمَنْظَرِ.","ạản̊ yā̊̉tūạ biwasẖ̊tī ٱl̊malikaẗi ại̹lay̱ ạảmāmi ٱl̊maliki bitāji ٱl̊mul̊ki, līurīa ٱlsẖũʿūba waٱlrũwảsāʾa jamālahā, liạảnãhā kānat̊ ḥasanaẗa ٱl̊man̊ẓari."],[1,12,"فَأَبَتِ ٱلْمَلِكَةُ وَشْتِي أَنْ تَأْتِيَ حَسَبَ أَمْرِ ٱلْمَلِكِ عَنْ يَدِ ٱلْخِصْيَانِ، فَٱغْتَاظَ ٱلْمَلِكُ جِدًّا وَٱشْتَعَلَ غَضَبُهُ فِيهِ.","fāảbati ٱl̊malikaẗu wasẖ̊tī ạản̊ tā̊̉tīa ḥasaba ạảm̊ri ٱl̊maliki ʿan̊ yadi ٱl̊kẖiṣ̊yāni, faٱgẖ̊tāẓa ٱl̊maliku jidaⁿ̃ạ waٱsẖ̊taʿala gẖaḍabuhu fīhi."],[1,13,"وَقَالَ ٱلْمَلِكُ لِلْحُكَمَاءِ ٱلْعَارِفِينَ بِٱلْأَزْمِنَةِ، لِأَنَّهُ هَكَذَا كَانَ أَمْرُ ٱلْمَلِكِ نَحْوَ جَمِيعِ ٱلْعَارِفِينَ بِٱلسُّنَّةِ وَٱلْقَضَاءِ،","waqāla ٱl̊maliku lil̊ḥukamāʾi ٱl̊ʿārifīna biٱl̊ạảz̊minaẗi, liạảnãhu hakadẖā kāna ạảm̊ru ٱl̊maliki naḥ̊wa jamīʿi ٱl̊ʿārifīna biٱlsũnãẗi waٱl̊qaḍāʾi,"],[1,14,"وَكَانَ ٱلْمُقَرِّبُونَ إِلَيْهِ كَرْشَنَا وَشِيثَارَ وَأَدْمَاثَا وَتَرْشِيشَ وَمَرَسَ وَمَرْسَنَا وَمَمُوكَانَ، سَبْعَةَ رُؤَسَاءِ فَارِسَ وَمَادِي ٱلَّذِينَ يَرَوْنَ وَجْهَ ٱلْمَلِكِ وَيَجْلِسُونَ أَوَّلًا فِي ٱلْمُلْكِ:","wakāna ٱl̊muqarĩbūna ại̹laẙhi kar̊sẖanā wasẖītẖāra wāảd̊mātẖā watar̊sẖīsẖa wamarasa wamar̊sanā wamamūkāna, sab̊ʿaẗa rūảsāʾi fārisa wamādī ٱlãdẖīna yaraẘna waj̊ha ٱl̊maliki wayaj̊lisūna ạảwãlaⁿạ fī ٱl̊mul̊ki:"],[1,15,"«حَسَبَ ٱلسُّنَّةِ، مَاذَا يُعْمَلُ بِٱلْمَلِكَةِ وَشْتِي لِأَنَّهَا لَمْ تَعْمَلْ كَقَوْلِ ٱلْمَلِكِ أَحَشْوِيرُوشَ عَنْ يَدِ ٱلْخِصْيَانِ؟»","«ḥasaba ٱlsũnãẗi, mādẖā yuʿ̊malu biٱl̊malikaẗi wasẖ̊tī liạảnãhā lam̊ taʿ̊mal̊ kaqaẘli ٱl̊maliki ạảḥasẖ̊wīrūsẖa ʿan̊ yadi ٱl̊kẖiṣ̊yāni?»"],[1,16,"فَقَالَ مَمُوكَانُ أَمَامَ ٱلْمَلِكِ وَٱلرُّؤَسَاءِ: «لَيْسَ إِلَى ٱلْمَلِكِ وَحْدَهُ أَذْنَبَتْ وَشْتِي ٱلْمَلِكَةُ، بَلْ إِلَى جَمِيعِ ٱلرُّؤَسَاءِ وَجَمِيعِ ٱلشُّعُوبِ ٱلَّذِينَ فِي كُلِّ بُلْدَانِ ٱلْمَلِكِ أَحَشْوِيرُوشَ.","faqāla mamūkānu ạảmāma ٱl̊maliki waٱlrũwảsāʾi: «laẙsa ại̹lay̱ ٱl̊maliki waḥ̊dahu ạảdẖ̊nabat̊ wasẖ̊tī ٱl̊malikaẗu, bal̊ ại̹lay̱ jamīʿi ٱlrũwảsāʾi wajamīʿi ٱlsẖũʿūbi ٱlãdẖīna fī kulĩ bul̊dāni ٱl̊maliki ạảḥasẖ̊wīrūsẖa."],[1,17,"لِأَنَّهُ سَوْفَ يَبْلُغُ خَبَرُ ٱلْمَلِكَةِ إِلَى جَمِيعِ ٱلنِّسَاءِ، حَتَّى يُحْتَقَرَ أَزْوَاجُهُنَّ فِي أَعْيُنِهِنَّ عِنْدَمَا يُقَالُ: إِنَّ ٱلْمَلِكَ أَحَشْوِيرُوشَ أَمَرَ أَنْ يُؤْتَى بِوَشْتِي ٱلْمَلِكَةِ إِلَى أَمَامِهِ فَلَمْ تَأْتِ.","liạảnãhu saẘfa yab̊lugẖu kẖabaru ٱl̊malikaẗi ại̹lay̱ jamīʿi ٱlnĩsāʾi, ḥatãy̱ yuḥ̊taqara ạảz̊wājuhunã fī ạảʿ̊yunihinã ʿin̊damā yuqālu: ại̹nã ٱl̊malika ạảḥasẖ̊wīrūsẖa ạảmara ạản̊ yū̊̉tay̱ biwasẖ̊tī ٱl̊malikaẗi ại̹lay̱ ạảmāmihi falam̊ tā̊̉ti."],[1,18,"وَفِي هَذَا ٱلْيَوْمِ تَقُولُهُ رَئِيسَاتُ فَارِسَ وَمَادِي ٱللَّوَاتِي سَمِعْنَ خَبَرَ ٱلْمَلِكَةِ لِجَمِيعِ رُؤَسَاءِ ٱلْمَلِكِ. وَمِثْلُ ذَلِكَ ٱحْتِقَارٌ وَغَضَبٌ.","wafī hadẖā ٱl̊yaẘmi taqūluhu rayỉysātu fārisa wamādī ٱllãwātī samiʿ̊na kẖabara ٱl̊malikaẗi lijamīʿi rūảsāʾi ٱl̊maliki. wamitẖ̊lu dẖalika ٱḥ̊tiqāruⁿ wagẖaḍabuⁿ."],[1,19,"فَإِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ، فَلْيَخْرُجْ أَمْرٌ مَلِكِيٌّ مِنْ عِنْدِهِ، وَلْيُكْتَبْ فِي سُنَنِ فَارِسَ وَمَادِي فَلَا يَتَغَيَّرَ، أَنْ لَا تَأْتِ وَشْتِي إِلَى أَمَامِ ٱلْمَلِكِ أَحَشْوِيرُوشَ، وَلْيُعْطِ ٱلْمَلِكُ مُلْكَهَا لِمَنْ هِيَ أَحْسَنُ مِنْهَا.","fāi̹dẖā ḥasuna ʿin̊da ٱl̊maliki, fal̊yakẖ̊ruj̊ ạảm̊ruⁿ malikīuⁿ̃ min̊ ʿin̊dihi, wal̊yuk̊tab̊ fī sunani fārisa wamādī falā yatagẖayãra, ạản̊ lā tā̊̉ti wasẖ̊tī ại̹lay̱ ạảmāmi ٱl̊maliki ạảḥasẖ̊wīrūsẖa, wal̊yuʿ̊ṭi ٱl̊maliku mul̊kahā liman̊ hīa ạảḥ̊sanu min̊hā."],[1,20,"فَيُسْمَعُ أَمْرُ ٱلْمَلِكِ ٱلَّذِي يُخْرِجُهُ فِي كُلِّ مَمْلَكَتِهِ لِأَنَّهَا عَظِيمَةٌ، فَتُعْطِي جَمِيعُ ٱلنِّسَاءِ ٱلْوَقَارَ لِأَزْوَاجِهِنَّ مِنَ ٱلْكَبِيرِ إِلَى ٱلصَّغِيرِ».","fayus̊maʿu ạảm̊ru ٱl̊maliki ٱlãdẖī yukẖ̊rijuhu fī kulĩ mam̊lakatihi liạảnãhā ʿaẓīmaẗuⁿ, fatuʿ̊ṭī jamīʿu ٱlnĩsāʾi ٱl̊waqāra liạảz̊wājihinã mina ٱl̊kabīri ại̹lay̱ ٱlṣãgẖīri»."],[1,21,"فَحَسُنَ ٱلْكَلَامُ فِي أَعْيُنِ ٱلْمَلِكِ وَٱلرُّؤَسَاءِ، وَعَمِلَ ٱلْمَلِكُ حَسَبَ قَوْلِ مَمُوكَانَ.","faḥasuna ٱl̊kalāmu fī ạảʿ̊yuni ٱl̊maliki waٱlrũwảsāʾi, waʿamila ٱl̊maliku ḥasaba qaẘli mamūkāna."],[1,22,"وَأَرْسَلَ كُتُبًا إِلَى كُلِّ بُلْدَانِ ٱلْمَلِكِ، إِلَى كُلِّ بِلَادٍ حَسَبَ كِتَابَتِهَا، وَإِلَى كُلِّ شَعْبٍ حَسَبَ لِسَانِهِ، لِيَكُونَ كُلُّ رَجُلٍ مُتَسَلِّطًا فِي بَيْتِهِ، وَيُتَكَلَّمَ بِذَلِكَ بِلِسَانِ شَعْبِهِ.","wāảr̊sala kutubaⁿạ ại̹lay̱ kulĩ bul̊dāni ٱl̊maliki, ại̹lay̱ kulĩ bilādiⁿ ḥasaba kitābatihā, wāi̹lay̱ kulĩ sẖaʿ̊biⁿ ḥasaba lisānihi, līakūna kulũ rajuliⁿ mutasalĩṭaⁿạ fī baẙtihi, wayutakalãma bidẖalika bilisāni sẖaʿ̊bihi."],[2,1,"بَعْدَ هَذِهِ ٱلْأُمُورِ لَمَّا خَمِدَ غَضَبُ ٱلْمَلِكِ أَحَشْوِيرُوشَ، ذَكَرَ وَشْتِي وَمَا عَمِلَتْهُ وَمَا حُتِمَ بِهِ عَلَيْهَا.","baʿ̊da hadẖihi ٱl̊ạủmūri lamãạ kẖamida gẖaḍabu ٱl̊maliki ạảḥasẖ̊wīrūsẖa, dẖakara wasẖ̊tī wamā ʿamilat̊hu wamā ḥutima bihi ʿalaẙhā."],[2,2,"فَقَالَ غِلْمَانُ ٱلْمَلِكِ ٱلَّذِينَ يَخْدِمُونَهُ: «لِيُطْلَبْ لِلْمَلِكِ فَتَيَاتٌ عَذَارَى حَسَنَاتُ ٱلْمَنْظَرِ،","faqāla gẖil̊mānu ٱl̊maliki ٱlãdẖīna yakẖ̊dimūnahu: «līuṭ̊lab̊ lil̊maliki fatayātuⁿ ʿadẖāray̱ ḥasanātu ٱl̊man̊ẓari,"],[2,3,"وَلْيُوَكِّلِ ٱلْمَلِكُ وُكَلَاءَ فِي كُلِّ بِلَادِ مَمْلَكَتِهِ لِيَجْمَعُوا كُلَّ ٱلْفَتَيَاتِ ٱلْعَذَارَى ٱلْحَسَنَاتِ ٱلْمَنْظَرِ إِلَى شُوشَنَ ٱلْقَصْرِ، إِلَى بَيْتِ ٱلنِّسَاءِ، إِلَى يَدِ هَيْجَايَ خَصِيِّ ٱلْمَلِكِ حَارِسِ ٱلنِّسَاءِ، وَلْيُعْطَيْنَ أَدْهَانَ عِطْرِهِنَّ.","wal̊yūakĩli ٱl̊maliku wukalāʾa fī kulĩ bilādi mam̊lakatihi līaj̊maʿūạ kulã ٱl̊fatayāti ٱl̊ʿadẖāray̱ ٱl̊ḥasanāti ٱl̊man̊ẓari ại̹lay̱ sẖūsẖana ٱl̊qaṣ̊ri, ại̹lay̱ baẙti ٱlnĩsāʾi, ại̹lay̱ yadi haẙjāya kẖaṣīĩ ٱl̊maliki ḥārisi ٱlnĩsāʾi, wal̊yuʿ̊ṭaẙna ạảd̊hāna ʿiṭ̊rihinã."],[2,4,"وَٱلْفَتَاةُ ٱلَّتِي تَحْسُنُ فِي عَيْنَيِ ٱلْمَلِكِ، فَلْتَمْلُكْ مَكَانَ وَشْتِي». فَحَسُنَ ٱلْكَلَامُ فِي عَيْنَيِ ٱلْمَلِكِ، فَعَمِلَ هَكَذَا.","waٱl̊fatāẗu ٱlãtī taḥ̊sunu fī ʿaẙnayi ٱl̊maliki, fal̊tam̊luk̊ makāna wasẖ̊tī». faḥasuna ٱl̊kalāmu fī ʿaẙnayi ٱl̊maliki, faʿamila hakadẖā."],[2,5,"كَانَ فِي شُوشَنَ ٱلْقَصْرِ رَجُلٌ يَهُودِيٌّ ٱسْمُهُ مُرْدَخَايُ بْنُ يَائِيرَ بْنِ شَمْعِي بْنِ قَيْسٍ، رَجُلٌ يَمِينِيٌّ،","kāna fī sẖūsẖana ٱl̊qaṣ̊ri rajuluⁿ yahūdīuⁿ̃ ٱs̊muhu mur̊dakẖāyu b̊nu yāyỉyra b̊ni sẖam̊ʿī b̊ni qaẙsiⁿ, rajuluⁿ yamīnīuⁿ̃,"],[2,6,"قَدْ سُبِيَ مِنْ أُورُشَلِيمَ مَعَ ٱلسَّبْيِ ٱلَّذِي سُبِيَ مَعَ يَكُنْيَا مَلِكِ يَهُوذَا ٱلَّذِي سَبَاهُ نَبُوخَذْنَصَّرُ مَلِكُ بَابِلَ.","qad̊ subīa min̊ ạủwrusẖalīma maʿa ٱlsãb̊yi ٱlãdẖī subīa maʿa yakun̊yā maliki yahūdẖā ٱlãdẖī sabāhu nabūkẖadẖ̊naṣãru maliku bābila."],[2,7,"وَكَانَ مُرَبِّيًا لِهَدَسَّةَ أَيْ أَسْتِيرَ بِنْتِ عَمِّهِ، لِأَنَّهُ لَمْ يَكُنْ لَهَا أَبٌ وَلَا أُمٌّ. وَكَانَتِ ٱلْفَتَاةُ جَمِيلَةَ ٱلصُّورَةِ وَحَسَنَةَ ٱلْمَنْظَرِ، وَعِنْدَ مَوْتِ أَبِيهَا وَأُمِّهَا ٱتَّخَذَهَا مُرْدَخَايُ لِنَفْسِهِ ٱبْنَةً.","wakāna murabĩyaⁿạ lihadasãẗa ạảẙ ạảs̊tīra bin̊ti ʿamĩhi, liạảnãhu lam̊ yakun̊ lahā ạảbuⁿ walā ạủmuⁿ̃. wakānati ٱl̊fatāẗu jamīlaẗa ٱlṣũwraẗi waḥasanaẗa ٱl̊man̊ẓari, waʿin̊da maẘti ạảbīhā wāủmĩhā ٱtãkẖadẖahā mur̊dakẖāyu linaf̊sihi ٱb̊naẗaⁿ."],[2,8,"فَلَمَّا سُمِعَ كَلَامُ ٱلْمَلِكِ وَأَمْرُهُ، وَجُمِعَتْ فَتَيَاتٌ كَثِيرَاتٌ إِلَى شُوشَنَ ٱلْقَصْرِ إِلَى يَدِ هَيْجَايَ، أُخِذَتْ أَسْتِيرُ إِلَى بَيْتِ ٱلْمَلِكِ إِلَى يَدِ هَيْجَايَ حَارِسِ ٱلنِّسَاءِ.","falamãạ sumiʿa kalāmu ٱl̊maliki wāảm̊ruhu, wajumiʿat̊ fatayātuⁿ katẖīrātuⁿ ại̹lay̱ sẖūsẖana ٱl̊qaṣ̊ri ại̹lay̱ yadi haẙjāya, ạủkẖidẖat̊ ạảs̊tīru ại̹lay̱ baẙti ٱl̊maliki ại̹lay̱ yadi haẙjāya ḥārisi ٱlnĩsāʾi."],[2,9,"وَحَسُنَتِ ٱلْفَتَاةُ فِي عَيْنَيْهِ وَنَالَتْ نِعْمَةً بَيْنَ يَدَيْهِ، فَبَادَرَ بِأَدْهَانِ عِطْرِهَا وَأَنْصِبَتِهَا لِيَعْطِيَهَا إِيَّاهَا مَعَ ٱلسَّبْعِ ٱلْفَتَيَاتِ ٱلْمُخْتَارَاتِ لِتُعْطَى لَهَا مِنْ بَيْتِ ٱلْمَلِكِ، وَنَقَلَهَا مَعَ فَتَيَاتِهَا إِلَى أَحْسَنِ مَكَانٍ فِي بَيْتِ ٱلنِّسَاءِ.","waḥasunati ٱl̊fatāẗu fī ʿaẙnaẙhi wanālat̊ niʿ̊maẗaⁿ baẙna yadaẙhi, fabādara biạảd̊hāni ʿiṭ̊rihā wāản̊ṣibatihā līaʿ̊ṭīahā ại̹yãạhā maʿa ٱlsãb̊ʿi ٱl̊fatayāti ٱl̊mukẖ̊tārāti lituʿ̊ṭay̱ lahā min̊ baẙti ٱl̊maliki, wanaqalahā maʿa fatayātihā ại̹lay̱ ạảḥ̊sani makāniⁿ fī baẙti ٱlnĩsāʾi."],[2,10,"وَلَمْ تُخْبِرْ أَسْتِيرُ عَنْ شَعْبِهَا وَجِنْسِهَا لِأَنَّ مُرْدَخَايَ أَوْصَاهَا أَنْ لَا تُخْبِرَ.","walam̊ tukẖ̊bir̊ ạảs̊tīru ʿan̊ sẖaʿ̊bihā wajin̊sihā liạảnã mur̊dakẖāya ạảẘṣāhā ạản̊ lā tukẖ̊bira."],[2,11,"وَكَانَ مُرْدَخَايُ يَتَمَشَّى يَوْمًا فَيَوْمًا أَمَامَ دَارِ بَيْتِ ٱلنِّسَاءِ، لِيَسْتَعْلِمَ عَنْ سَلَامَةِ أَسْتِيرَ وَعَمَّا يُصْنَعُ بِهَا.","wakāna mur̊dakẖāyu yatamasẖãy̱ yaẘmaⁿạ fayaẘmaⁿạ ạảmāma dāri baẙti ٱlnĩsāʾi, līas̊taʿ̊lima ʿan̊ salāmaẗi ạảs̊tīra waʿamãạ yuṣ̊naʿu bihā."],[2,12,"وَلَمَّا بَلَغَتْ نَوْبَةُ فَتَاةٍ فَفَتَاةٍ لِلدُّخُولِ إِلَى ٱلْمَلِكِ أَحَشْوِيرُوشَ بَعْدَ أَنْ يَكُونَ لَهَا حَسَبَ سُنَّةِ ٱلنِّسَاءِ ٱثْنَا عَشَرَ شَهْرًا، لِأَنَّهُ هَكَذَا كَانَتْ تُكْمَلُ أَيَّامُ تَعَطُّرِهِنَّ، سِتَّةَ أَشْهُرٍ بِزَيْتِ ٱلْمُرِّ وَسِتَّةَ أَشْهُرٍ بِٱلْأَطْيَابِ وَأَدْهَانِ تَعَطُّرِ ٱلنِّسَاءِ.","walamãạ balagẖat̊ naẘbaẗu fatāẗiⁿ fafatāẗiⁿ lildũkẖūli ại̹lay̱ ٱl̊maliki ạảḥasẖ̊wīrūsẖa baʿ̊da ạản̊ yakūna lahā ḥasaba sunãẗi ٱlnĩsāʾi ٱtẖ̊nā ʿasẖara sẖah̊raⁿạ, liạảnãhu hakadẖā kānat̊ tuk̊malu ạảyãạmu taʿaṭũrihinã, sitãẗa ạảsẖ̊huriⁿ bizaẙti ٱl̊murĩ wasitãẗa ạảsẖ̊huriⁿ biٱl̊ạảṭ̊yābi wāảd̊hāni taʿaṭũri ٱlnĩsāʾi."],[2,13,"وَهَكَذَا كَانَتَ كُلُّ فَتَاةٍ تَدْخُلُ إِلَى ٱلْمَلِكِ. وَكُلُّ مَا قَالَتْ عَنْهُ أُعْطِيَ لَهَا لِلدُّخُولِ مَعَهَا مِنْ بَيْتِ ٱلنِّسَاءِ إِلَى بَيْتِ ٱلْمَلِكِ.","wahakadẖā kānata kulũ fatāẗiⁿ tad̊kẖulu ại̹lay̱ ٱl̊maliki. wakulũ mā qālat̊ ʿan̊hu ạủʿ̊ṭīa lahā lildũkẖūli maʿahā min̊ baẙti ٱlnĩsāʾi ại̹lay̱ baẙti ٱl̊maliki."],[2,14,"فِي ٱلْمَسَاءِ دَخَلَتْ وَفِي ٱلصَّبَاحِ رَجَعَتْ إِلَى بَيْتِ ٱلنِّسَاءِ ٱلثَّانِي إِلَى يَدِ شَعَشْغَازَ خَصِيِّ ٱلْمَلِكِ حَارِسِ ٱلسَّرَارِيِّ. لَمْ تَعُدْ تَدْخُلْ إِلَى ٱلْمَلِكِ إِلَّا إِذَا سُرَّ بِهَا ٱلْمَلِكُ وَدُعِيَتْ بِٱسْمِهَا.","fī ٱl̊masāʾi dakẖalat̊ wafī ٱlṣãbāḥi rajaʿat̊ ại̹lay̱ baẙti ٱlnĩsāʾi ٱltẖãạnī ại̹lay̱ yadi sẖaʿasẖ̊gẖāza kẖaṣīĩ ٱl̊maliki ḥārisi ٱlsãrārīĩ. lam̊ taʿud̊ tad̊kẖul̊ ại̹lay̱ ٱl̊maliki ại̹lãạ ại̹dẖā surã bihā ٱl̊maliku waduʿīat̊ biٱs̊mihā."],[2,15,"وَلَمَّا بَلَغَتْ نَوْبَةُ أَسْتِيرَ ٱبْنَةِ أَبَيِحَائِلَ عَمِّ مُرْدَخَايَ ٱلَّذِي ٱتَّخَذَهَا لِنَفْسِهِ ٱبْنَةً لِلدُّخُولِ إِلَى ٱلْمَلِكِ، لَمْ تَطْلُبْ شَيْئًا إِلَّا مَا قَالَ عَنْهُ هَيْجَايُ خَصِيُّ ٱلْمَلِكِ حَارِسُ ٱلنِّسَاءِ. وَكَانَتْ أَسْتِيرُ تَنَالُ نِعْمَةً فِي عَيْنَيْ كُلِّ مَنْ رَآهَا.","walamãạ balagẖat̊ naẘbaẗu ạảs̊tīra ٱb̊naẗi ạảbayiḥāyỉla ʿamĩ mur̊dakẖāya ٱlãdẖī ٱtãkẖadẖahā linaf̊sihi ٱb̊naẗaⁿ lildũkẖūli ại̹lay̱ ٱl̊maliki, lam̊ taṭ̊lub̊ sẖaẙyaⁿ̉ạ ại̹lãạ mā qāla ʿan̊hu haẙjāyu kẖaṣīũ ٱl̊maliki ḥārisu ٱlnĩsāʾi. wakānat̊ ạảs̊tīru tanālu niʿ̊maẗaⁿ fī ʿaẙnaẙ kulĩ man̊ rā̂hā."],[2,16,"وَأُخِذَتْ أَسْتِيرُ إِلَى ٱلْمَلِكِ أَحَشْوِيرُوشَ إِلَى بَيْتِ مُلْكِهِ فِي ٱلشَّهْرِ ٱلْعَاشِرِ، هُوَ شَهْرُ طِيبِيتَ، فِي ٱلسَّنَةِ ٱلسَّابِعَةِ لِمُلْكِهِ.","wāủkẖidẖat̊ ạảs̊tīru ại̹lay̱ ٱl̊maliki ạảḥasẖ̊wīrūsẖa ại̹lay̱ baẙti mul̊kihi fī ٱlsẖãh̊ri ٱl̊ʿāsẖiri, hūa sẖah̊ru ṭībīta, fī ٱlsãnaẗi ٱlsãạbiʿaẗi limul̊kihi."],[2,17,"فَأَحَبَّ ٱلْمَلِكُ أَسْتِيرَ أَكْثَرَ مِنْ جَمِيعِ ٱلنِّسَاءِ، وَوَجَدَتْ نِعْمَةً وَإِحْسَانًا قُدَّامَهُ أَكْثَرَ مِنْ جَمِيعِ ٱلْعَذَارَى، فَوَضَعَ تَاجَ ٱلْمُلْكِ عَلَى رَأْسِهَا وَمَلَّكَهَا مَكَانَ وَشْتِي.","fāảḥabã ٱl̊maliku ạảs̊tīra ạảk̊tẖara min̊ jamīʿi ٱlnĩsāʾi, wawajadat̊ niʿ̊maẗaⁿ wāi̹ḥ̊sānaⁿạ qudãạmahu ạảk̊tẖara min̊ jamīʿi ٱl̊ʿadẖāray̱, fawaḍaʿa tāja ٱl̊mul̊ki ʿalay̱ rā̊̉sihā wamalãkahā makāna wasẖ̊tī."],[2,18,"وَعَمِلَ ٱلْمَلِكُ وَلِيمَةً عَظِيمَةً لِجَمِيعِ رُؤَسَائِهِ وَعَبِيدِهِ، وَلِيمَةَ أَسْتِيرَ. وَعَمِلَ رَاحَةً لِلْبِلَادِ وَأَعْطَى عَطَايَا حَسَبَ كَرَمِ ٱلْمَلِكِ.","waʿamila ٱl̊maliku walīmaẗaⁿ ʿaẓīmaẗaⁿ lijamīʿi rūảsāyỉhi waʿabīdihi, walīmaẗa ạảs̊tīra. waʿamila rāḥaẗaⁿ lil̊bilādi wāảʿ̊ṭay̱ ʿaṭāyā ḥasaba karami ٱl̊maliki."],[2,19,"وَلَمَّا جُمِعَتِ ٱلْعَذَارَى ثَانِيَةً كَانَ مُرْدَخَايُ جَالِسًا بِبَابِ ٱلْمَلِكِ.","walamãạ jumiʿati ٱl̊ʿadẖāray̱ tẖānīaẗaⁿ kāna mur̊dakẖāyu jālisaⁿạ bibābi ٱl̊maliki."],[2,20,"وَلَمْ تَكُنْ أَسْتِيرُ أَخْبَرَتْ عَنْ جِنْسِهَا وَشَعْبِهَا كَمَا أَوْصَاهَا مُرْدَخَايُ. وَكَانَتْ أَسْتِيرُ تَعْمَلُ حَسَبَ قَوْلِ مُرْدَخَايَ كَمَا كَانَتْ فِي تَرْبِيَتِهَا عِنْدَهُ.","walam̊ takun̊ ạảs̊tīru ạảkẖ̊barat̊ ʿan̊ jin̊sihā wasẖaʿ̊bihā kamā ạảẘṣāhā mur̊dakẖāyu. wakānat̊ ạảs̊tīru taʿ̊malu ḥasaba qaẘli mur̊dakẖāya kamā kānat̊ fī tar̊bīatihā ʿin̊dahu."],[2,21,"فِي تِلْكَ ٱلْأَيَّامِ، بَيْنَمَا كَانَ مُرْدَخَايُ جَالِسًا فِي بَابِ ٱلْمَلِكِ، غَضِبَ بِغْثَانُ وَتَرَشُ خَصِيَّا ٱلْمَلِكِ حَارِسَا ٱلْبَابِ، وَطَلَبَا أَنْ يَمُدَّا أَيْدِيَهُمَا إِلَى ٱلْمَلِكِ أَحَشْوِيرُوشَ.","fī til̊ka ٱl̊ạảyãạmi, baẙnamā kāna mur̊dakẖāyu jālisaⁿạ fī bābi ٱl̊maliki, gẖaḍiba bigẖ̊tẖānu watarasẖu kẖaṣīãạ ٱl̊maliki ḥārisā ٱl̊bābi, waṭalabā ạản̊ yamudãạ ạảẙdīahumā ại̹lay̱ ٱl̊maliki ạảḥasẖ̊wīrūsẖa."],[2,22,"فَعُلِمَ ٱلْأَمْرُ عِنْدَ مُرْدَخَايَ، فَأَخْبَرَ أَسْتِيرَ ٱلْمَلِكَةَ، فَأَخْبَرَتْ أَسْتِيرُ ٱلْمَلِكَ بِٱسْمِ مُرْدَخَايَ.","faʿulima ٱl̊ạảm̊ru ʿin̊da mur̊dakẖāya, fāảkẖ̊bara ạảs̊tīra ٱl̊malikaẗa, fāảkẖ̊barat̊ ạảs̊tīru ٱl̊malika biٱs̊mi mur̊dakẖāya."],[2,23,"فَفُحِصَ عَنِ ٱلْأَمْرِ وَوُجِدَ، فَصُلِبَا كِلَاهُمَا عَلَى خَشَبَةٍ، وَكُتِبَ ذَلِكَ فِي سِفْرِ أَخْبَارِ ٱلْأَيَّامِ أَمَامَ ٱلْمَلِكِ.","fafuḥiṣa ʿani ٱl̊ạảm̊ri wawujida, faṣulibā kilāhumā ʿalay̱ kẖasẖabaẗiⁿ, wakutiba dẖalika fī sif̊ri ạảkẖ̊bāri ٱl̊ạảyãạmi ạảmāma ٱl̊maliki."],[3,1,"بَعْدَ هَذِهِ ٱلْأُمُورِ عَظَّمَ ٱلْمَلِكُ أَحَشْوِيرُوشُ هَامَانَ بْنَ هَمَدَاثَا ٱلْأَجَاجِيَّ وَرَقَّاهُ، وَجَعَلَ كُرْسِيَّهُ فَوْقَ جَمِيعِ ٱلرُّؤَسَاءِ ٱلَّذِينَ مَعَهُ.","baʿ̊da hadẖihi ٱl̊ạủmūri ʿaẓãma ٱl̊maliku ạảḥasẖ̊wīrūsẖu hāmāna b̊na hamadātẖā ٱl̊ạảjājīã waraqãạhu, wajaʿala kur̊sīãhu faẘqa jamīʿi ٱlrũwảsāʾi ٱlãdẖīna maʿahu."],[3,2,"فَكَانَ كُلُّ عَبِيدِ ٱلْمَلِكِ ٱلَّذِينَ بِبَابِ ٱلْمَلِكِ يَجْثُونَ وَيَسْجُدُونَ لِهَامَانَ، لِأَنَّهُ هَكَذَا أَوْصَى بِهِ ٱلْمَلِكُ. وَأَمَّا مُرْدَخَايُ فَلَمْ يَجْثُ وَلَمْ يَسْجُدْ.","fakāna kulũ ʿabīdi ٱl̊maliki ٱlãdẖīna bibābi ٱl̊maliki yaj̊tẖūna wayas̊judūna lihāmāna, liạảnãhu hakadẖā ạảẘṣay̱ bihi ٱl̊maliku. wāảmãạ mur̊dakẖāyu falam̊ yaj̊tẖu walam̊ yas̊jud̊."],[3,3,"فَقَالَ عَبِيدُ ٱلْمَلِكِ ٱلَّذِينَ بِبَابِ ٱلْمَلِكِ لِمُرْدَخَايَ: «لِمَاذَا تَتَعَدَّى أَمْرَ ٱلْمَلِكِ؟»","faqāla ʿabīdu ٱl̊maliki ٱlãdẖīna bibābi ٱl̊maliki limur̊dakẖāya: «limādẖā tataʿadãy̱ ạảm̊ra ٱl̊maliki?»"],[3,4,"وَإِذْ كَانُوا يُكَلِّمُونَهُ يَوْمًا فَيَوْمًا وَلَمْ يَكُنْ يَسْمَعْ لَهُمْ، أَخْبَرُوا هَامَانَ لِيَرَوْا هَلْ يَقُومُ كَلَامُ مُرْدَخَايَ، لِأَنَّهُ أَخْبَرَهُمْ بِأَنَّهُ يَهُودِيٌّ.","wāi̹dẖ̊ kānūạ yukalĩmūnahu yaẘmaⁿạ fayaẘmaⁿạ walam̊ yakun̊ yas̊maʿ̊ lahum̊, ạảkẖ̊barūạ hāmāna līaraẘạ hal̊ yaqūmu kalāmu mur̊dakẖāya, liạảnãhu ạảkẖ̊barahum̊ biạảnãhu yahūdīuⁿ̃."],[3,5,"وَلَمَّا رَأَى هَامَانُ أَنَّ مُرْدَخَايَ لَا يَجْثُو وَلَا يَسْجُدُ لَهُ، ٱمْتَلَأَ هَامَانُ غَضَبًا.","walamãạ rāảy̱ hāmānu ạảnã mur̊dakẖāya lā yaj̊tẖū walā yas̊judu lahu, ٱm̊talāả hāmānu gẖaḍabaⁿạ."],[3,6,"وَٱزْدُرِيَ فِي عَيْنَيْهِ أَنْ يَمُدَّ يَدَهُ إِلَى مُرْدَخَايَ وَحْدَهُ، لِأَنَّهُمْ أَخْبَرُوهُ عَنْ شَعْبِ مُرْدَخَايَ. فَطَلَبَ هَامَانُ أَنْ يُهْلِكَ جَمِيعَ ٱلْيَهُودِ ٱلَّذِينَ فِي كُلِّ مَمْلَكَةِ أَحَشْوِيرُوشَ، شَعْبَ مُرْدَخَايَ.","waٱz̊durīa fī ʿaẙnaẙhi ạản̊ yamudã yadahu ại̹lay̱ mur̊dakẖāya waḥ̊dahu, liạảnãhum̊ ạảkẖ̊barūhu ʿan̊ sẖaʿ̊bi mur̊dakẖāya. faṭalaba hāmānu ạản̊ yuh̊lika jamīʿa ٱl̊yahūdi ٱlãdẖīna fī kulĩ mam̊lakaẗi ạảḥasẖ̊wīrūsẖa, sẖaʿ̊ba mur̊dakẖāya."],[3,7,"فِي ٱلشَّهْرِ ٱلْأَوَّلِ، أَيْ شَهْرِ نِيسَانَ، فِي ٱلسَّنَةِ ٱلثَّانِيَةِ عَشَرَةَ لِلْمَلِكِ أَحَشْوِيرُوشَ، كَانُوا يُلْقُونَ فُورًا، أَيْ قُرْعَةً، أَمَامَ هَامَانَ، مِنْ يَوْمٍ إِلَى يَوْمٍ، وَمِنْ شَهْرٍ إِلَى شَهْرٍ، إِلَى ٱلثَّانِي عَشَرَ، أَيْ شَهْرِ أَذَارَ.","fī ٱlsẖãh̊ri ٱl̊ạảwãli, ạảẙ sẖah̊ri nīsāna, fī ٱlsãnaẗi ٱltẖãạnīaẗi ʿasẖaraẗa lil̊maliki ạảḥasẖ̊wīrūsẖa, kānūạ yul̊qūna fūraⁿạ, ạảẙ qur̊ʿaẗaⁿ, ạảmāma hāmāna, min̊ yaẘmiⁿ ại̹lay̱ yaẘmiⁿ, wamin̊ sẖah̊riⁿ ại̹lay̱ sẖah̊riⁿ, ại̹lay̱ ٱltẖãạnī ʿasẖara, ạảẙ sẖah̊ri ạảdẖāra."],[3,8,"فَقَالَ هَامَانُ لِلْمَلِكِ أَحَشْوِيرُوشَ: «إِنَّهُ مَوْجُودٌ شَعْبٌ مَّا مُتَشَتِّتٌ وَمُتَفَرِّقٌ بَيْنَ ٱلشُّعُوبِ فِي كُلِّ بِلَادِ مَمْلَكَتِكَ، وَسُنَنُهُمْ مُغَايِرَةٌ لِجَمِيعِ ٱلشُّعُوبِ، وَهُمْ لَا يَعْمَلُونَ سُنَنَ ٱلْمَلِكِ، فَلَا يَلِيقُ بِٱلْمَلِكِ تَرْكُهُمْ.","faqāla hāmānu lil̊maliki ạảḥasẖ̊wīrūsẖa: «ại̹nãhu maẘjūduⁿ sẖaʿ̊buⁿ mãạ mutasẖatĩtuⁿ wamutafarĩquⁿ baẙna ٱlsẖũʿūbi fī kulĩ bilādi mam̊lakatika, wasunanuhum̊ mugẖāyiraẗuⁿ lijamīʿi ٱlsẖũʿūbi, wahum̊ lā yaʿ̊malūna sunana ٱl̊maliki, falā yalīqu biٱl̊maliki tar̊kuhum̊."],[3,9,"فَإِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ فَلْيُكْتَبْ أَنْ يُبَادُوا، وَأَنَا أَزِنُ عَشَرَةَ آلَافِ وَزْنَةٍ مِنَ ٱلْفِضَّةِ فِي أَيْدِي ٱلَّذِينَ يَعْمَلُونَ ٱلْعَمَلَ لِيُؤْتَى بِهَا إِلَى خَزَائِنِ ٱلْمَلِكِ».","fāi̹dẖā ḥasuna ʿin̊da ٱl̊maliki fal̊yuk̊tab̊ ạản̊ yubādūạ, wāảnā ạảzinu ʿasẖaraẗa ậlāfi waz̊naẗiⁿ mina ٱl̊fiḍãẗi fī ạảẙdī ٱlãdẖīna yaʿ̊malūna ٱl̊ʿamala līū̊̉tay̱ bihā ại̹lay̱ kẖazāyỉni ٱl̊maliki»."],[3,10,"فَنَزَعَ ٱلْمَلِكُ خَاتَمَهُ مِنْ يَدِهِ وَأَعْطَاهُ لِهَامَانَ بْنِ هَمَدَاثَا ٱلْأَجَاجِيِّ عَدُوِّ ٱلْيَهُودِ.","fanazaʿa ٱl̊maliku kẖātamahu min̊ yadihi wāảʿ̊ṭāhu lihāmāna b̊ni hamadātẖā ٱl̊ạảjājīĩ ʿadūĩ ٱl̊yahūdi."],[3,11,"وَقَالَ ٱلْمَلِكُ لِهَامَانَ: «ٱلْفِضَّةُ قَدْ أُعْطِيَتْ لَكَ، وَٱلشَّعْبُ أَيْضًا، لِتَفْعَلَ بِهِ مَا يَحْسُنُ فِي عَيْنَيْكَ».","waqāla ٱl̊maliku lihāmāna: «ٱl̊fiḍãẗu qad̊ ạủʿ̊ṭīat̊ laka, waٱlsẖãʿ̊bu ạảẙḍaⁿạ, litaf̊ʿala bihi mā yaḥ̊sunu fī ʿaẙnaẙka»."],[3,12,"فَدُعِيَ كُتَّابُ ٱلْمَلِكِ فِي ٱلشَّهْرِ ٱلْأَوَّلِ، فِي ٱلْيَوْمِ ٱلثَّالِثَ عَشَرَ مِنْهُ، وَكُتِبَ حَسَبَ كُلِّ مَا أَمَرَ بِهِ هَامَانُ إِلَى مَرَازِبَةِ ٱلْمَلِكِ وَإِلَى وُلَاةِ بِلَادٍ فَبِلَادٍ، وَإِلَى رُؤَسَاءِ شَعْبٍ فَشَعْبٍ، كُلِّ بِلَادٍ كَكِتَابَتِهَا، وَكُلِّ شَعْبٍ كَلِسَانِهِ، كُتِبَ بِٱسْمِ ٱلْمَلِكِ أَحَشْوِيرُوشَ وَخُتِمَ بِخَاتَمِ ٱلْمَلِكِ.","faduʿīa kutãạbu ٱl̊maliki fī ٱlsẖãh̊ri ٱl̊ạảwãli, fī ٱl̊yaẘmi ٱltẖãạlitẖa ʿasẖara min̊hu, wakutiba ḥasaba kulĩ mā ạảmara bihi hāmānu ại̹lay̱ marāzibaẗi ٱl̊maliki wāi̹lay̱ wulāẗi bilādiⁿ fabilādiⁿ, wāi̹lay̱ rūảsāʾi sẖaʿ̊biⁿ fasẖaʿ̊biⁿ, kulĩ bilādiⁿ kakitābatihā, wakulĩ sẖaʿ̊biⁿ kalisānihi, kutiba biٱs̊mi ٱl̊maliki ạảḥasẖ̊wīrūsẖa wakẖutima bikẖātami ٱl̊maliki."],[3,13,"وَأُرْسِلَتِ ٱلْكِتَابَاتُ بِيَدِ ٱلسُّعَاةِ إِلَى كُلِّ بُلْدَانِ ٱلْمَلِكِ لِإِهْلَاكِ وَقَتْلِ وَإِبَادَةِ جَمِيعِ ٱلْيَهُودِ، مِنَ ٱلْغُلَامِ إِلَى ٱلشَّيْخِ وَٱلْأَطْفَالِ وَٱلنِّسَاءِ فِي يَوْمٍ وَاحِدٍ، فِي ٱلثَّالِثَ عَشَرَ مِنَ ٱلشَّهْرِ ٱلثَّانِي عَشَرَ، أَيْ شَهْرِ أَذَارَ، وَأَنْ يَسْلِبُوا غَنِيمَتَهُمْ.","wāủr̊silati ٱl̊kitābātu bīadi ٱlsũʿāẗi ại̹lay̱ kulĩ bul̊dāni ٱl̊maliki liại̹h̊lāki waqat̊li wāi̹bādaẗi jamīʿi ٱl̊yahūdi, mina ٱl̊gẖulāmi ại̹lay̱ ٱlsẖãẙkẖi waٱl̊ạảṭ̊fāli waٱlnĩsāʾi fī yaẘmiⁿ wāḥidiⁿ, fī ٱltẖãạlitẖa ʿasẖara mina ٱlsẖãh̊ri ٱltẖãạnī ʿasẖara, ạảẙ sẖah̊ri ạảdẖāra, wāản̊ yas̊libūạ gẖanīmatahum̊."],[3,14,"صُورَةُ ٱلْكِتَابَةِ ٱلْمُعْطَاةِ سُنَّةً فِي كُلِّ ٱلْبُلْدَانِ، أُشْهِرَتْ بَيْنَ جَمِيعِ ٱلشُّعُوبِ لِيَكُونُوا مُسْتَعِدِّينَ لِهَذَا ٱلْيَوْمِ.","ṣūraẗu ٱl̊kitābaẗi ٱl̊muʿ̊ṭāẗi sunãẗaⁿ fī kulĩ ٱl̊bul̊dāni, ạủsẖ̊hirat̊ baẙna jamīʿi ٱlsẖũʿūbi līakūnūạ mus̊taʿidĩyna lihadẖā ٱl̊yaẘmi."],[3,15,"فَخَرَجَ ٱلسُّعَاةُ وَأَمْرُ ٱلْمَلِكِ يَحُثُّهُمْ، وَأُعْطِيَ ٱلْأَمْرُ فِي شُوشَنَ ٱلْقَصْرِ. وَجَلَسَ ٱلْمَلِكُ وَهَامَانُ لِلشُّرْبِ، وَأَمَّا ٱلْمَدِينَةُ شُوشَنُ فَٱرْتَبَكَتْ.","fakẖaraja ٱlsũʿāẗu wāảm̊ru ٱl̊maliki yaḥutẖũhum̊, wāủʿ̊ṭīa ٱl̊ạảm̊ru fī sẖūsẖana ٱl̊qaṣ̊ri. wajalasa ٱl̊maliku wahāmānu lilsẖũr̊bi, wāảmãạ ٱl̊madīnaẗu sẖūsẖanu faٱr̊tabakat̊."],[4,1,"وَلَمَّا عَلِمَ مُرْدَخَايُ كُلَّ مَا عُمِلَ، شَقَّ مُرْدَخَايُ ثِيَابَهُ وَلَبِسَ مِسْحًا بِرَمَادٍ وَخَرَجَ إِلَى وَسَطِ ٱلْمَدِينَةِ وَصَرَخَ صَرْخَةً عَظِيمَةً مُرَّةً،","walamãạ ʿalima mur̊dakẖāyu kulã mā ʿumila, sẖaqã mur̊dakẖāyu tẖīābahu walabisa mis̊ḥaⁿạ biramādiⁿ wakẖaraja ại̹lay̱ wasaṭi ٱl̊madīnaẗi waṣarakẖa ṣar̊kẖaẗaⁿ ʿaẓīmaẗaⁿ murãẗaⁿ,"],[4,2,"وَجَاءَ إِلَى قُدَّامِ بَابِ ٱلْمَلِكِ، لِأَنَّهُ لَا يَدْخُلُ أَحَدٌ بَابَ ٱلْمَلِكِ وَهُوَ لَابِسٌ مِسْحًا.","wajāʾa ại̹lay̱ qudãạmi bābi ٱl̊maliki, liạảnãhu lā yad̊kẖulu ạảḥaduⁿ bāba ٱl̊maliki wahūa lābisuⁿ mis̊ḥaⁿạ."],[4,3,"وَفِي كُلِّ كُورَةٍ حَيْثُمَا وَصَلَ إِلَيْهَا أَمْرُ ٱلْمَلِكِ وَسُنَّتُهُ، كَانَتْ مَنَاحَةٌ عَظِيمَةٌ عِنْدَ ٱلْيَهُودِ، وَصَوْمٌ وَبُكَاءٌ وَنَحِيبٌ. وَٱنْفَرَشَ مِسْحٌ وَرَمَادٌ لِكَثِيرِينَ.","wafī kulĩ kūraẗiⁿ ḥaẙtẖumā waṣala ại̹laẙhā ạảm̊ru ٱl̊maliki wasunãtuhu, kānat̊ manāḥaẗuⁿ ʿaẓīmaẗuⁿ ʿin̊da ٱl̊yahūdi, waṣaẘmuⁿ wabukāʾuⁿ wanaḥībuⁿ. waٱn̊farasẖa mis̊ḥuⁿ waramāduⁿ likatẖīrīna."],[4,4,"فَدَخَلَتْ جَوَارِي أَسْتِيرَ وَخُصْيَانُهَا وَأَخْبَرُوهَا، فَٱغْتَمَّتِ ٱلْمَلِكَةُ جِدًّا وَأَرْسَلَتْ ثِيَابًا لِإِلْبَاسِ مُرْدَخَايَ، وَلِأَجْلِ نَزْعِ مِسْحِهِ عَنْهُ، فَلَمْ يَقْبَلْ.","fadakẖalat̊ jawārī ạảs̊tīra wakẖuṣ̊yānuhā wāảkẖ̊barūhā, faٱgẖ̊tamãti ٱl̊malikaẗu jidaⁿ̃ạ wāảr̊salat̊ tẖīābaⁿạ liại̹l̊bāsi mur̊dakẖāya, waliạảj̊li naz̊ʿi mis̊ḥihi ʿan̊hu, falam̊ yaq̊bal̊."],[4,5,"فَدَعَتْ أَسْتِيرُ هَتَاخَ، وَاحِدًا مِنْ خِصْيَانِ ٱلْمَلِكِ ٱلَّذِي أَوْقَفَهُ بَيْنَ يَدَيْهَا، وَأَعْطَتْهُ وَصِيَّةً إِلَى مُرْدَخَايَ لِتَعْلَمَ مَاذَا وَلِمَاذَا.","fadaʿat̊ ạảs̊tīru hatākẖa, wāḥidaⁿạ min̊ kẖiṣ̊yāni ٱl̊maliki ٱlãdẖī ạảẘqafahu baẙna yadaẙhā, wāảʿ̊ṭat̊hu waṣīãẗaⁿ ại̹lay̱ mur̊dakẖāya litaʿ̊lama mādẖā walimādẖā."],[4,6,"فَخَرَجَ هَتَاخُ إِلَى مُرْدَخَايَ إِلَى سَاحَةِ ٱلْمَدِينَةِ ٱلَّتِي أَمَامَ بَابِ ٱلْمَلِكِ.","fakẖaraja hatākẖu ại̹lay̱ mur̊dakẖāya ại̹lay̱ sāḥaẗi ٱl̊madīnaẗi ٱlãtī ạảmāma bābi ٱl̊maliki."],[4,7,"فَأَخْبَرَهُ مُرْدَخَايُ بِكُلِّ مَا أَصَابَهُ، وَعَنْ مَبْلَغِ ٱلْفِضَّةِ ٱلَّذِي وَعَدَ هَامَانُ بِوَزْنِهِ لِخَزَائِنِ ٱلْمَلِكِ عَنِ ٱلْيَهُودِ لِإِبَادَتِهِمْ،","fāảkẖ̊barahu mur̊dakẖāyu bikulĩ mā ạảṣābahu, waʿan̊ mab̊lagẖi ٱl̊fiḍãẗi ٱlãdẖī waʿada hāmānu biwaz̊nihi likẖazāyỉni ٱl̊maliki ʿani ٱl̊yahūdi liại̹bādatihim̊,"],[4,8,"وَأَعْطَاهُ صُورَةَ كِتَابَةِ ٱلْأَمْرِ ٱلَّذِي أُعْطِيَ فِي شُوشَنَ لِإِهْلَاكِهِمْ، لِكَيْ يُرِيَهَا لِأَسْتِيرَ، وَيُخْبِرَهَا وَيُوصِيَهَا أَنْ تَدْخُلَ إِلَى ٱلْمَلِكِ وَتَتَضَرَّعَ إِلَيْهِ وَتَطْلُبَ مِنْهُ لِأَجْلِ شَعْبِهَا.","wāảʿ̊ṭāhu ṣūraẗa kitābaẗi ٱl̊ạảm̊ri ٱlãdẖī ạủʿ̊ṭīa fī sẖūsẖana liại̹h̊lākihim̊, likaẙ yurīahā liạảs̊tīra, wayukẖ̊birahā wayūṣīahā ạản̊ tad̊kẖula ại̹lay̱ ٱl̊maliki watataḍarãʿa ại̹laẙhi wataṭ̊luba min̊hu liạảj̊li sẖaʿ̊bihā."],[4,9,"فَأَتَى هَتَاخُ وَأَخْبَرَ أَسْتِيرَ بِكَلَامِ مُرْدَخَايَ.","fāảtay̱ hatākẖu wāảkẖ̊bara ạảs̊tīra bikalāmi mur̊dakẖāya."],[4,10,"فَكَلَّمَتْ أَسْتِيرُ هَتَاخَ وَأَعْطَتْهُ وَصِيَّةً إِلَى مُرْدَخَايَ:","fakalãmat̊ ạảs̊tīru hatākẖa wāảʿ̊ṭat̊hu waṣīãẗaⁿ ại̹lay̱ mur̊dakẖāya:"],[4,11,"«إِنَّ كُلَّ عَبِيدِ ٱلْمَلِكِ وَشُعُوبِ بِلَادِ ٱلْمَلِكِ يَعْلَمُونَ أَنَّ كُلَّ رَجُلٍ دَخَلَ أَوِ ٱمْرَأَةٍ إِلَى ٱلْمَلِكِ، إِلَى ٱلدَّارِ ٱلدَّاخِلِيَّةِ وَلَمْ يُدْعَ، فَشَرِيعَتُهُ وَاحِدَةٌ أَنْ يُقْتَلَ، إِلَّا ٱلَّذِي يَمُدُّ لَهُ ٱلْمَلِكُ قَضِيبَ ٱلذَّهَبِ فَإِنَّهُ يَحْيَا. وَأَنَا لَمْ أُدْعَ لِأَدْخُلَ إِلَى ٱلْمَلِكِ هَذِهِ ٱلثَّلَاثِينَ يَوْمًا».","«ại̹nã kulã ʿabīdi ٱl̊maliki wasẖuʿūbi bilādi ٱl̊maliki yaʿ̊lamūna ạảnã kulã rajuliⁿ dakẖala ạảwi ٱm̊rāảẗiⁿ ại̹lay̱ ٱl̊maliki, ại̹lay̱ ٱldãạri ٱldãạkẖilīãẗi walam̊ yud̊ʿa, fasẖarīʿatuhu wāḥidaẗuⁿ ạản̊ yuq̊tala, ại̹lãạ ٱlãdẖī yamudũ lahu ٱl̊maliku qaḍība ٱldẖãhabi fāi̹nãhu yaḥ̊yā. wāảnā lam̊ ạủd̊ʿa liạảd̊kẖula ại̹lay̱ ٱl̊maliki hadẖihi ٱltẖãlātẖīna yaẘmaⁿạ»."],[4,12,"فَأَخْبَرُوا مُرْدَخَايَ بِكَلَامِ أَسْتِيرَ.","fāảkẖ̊barūạ mur̊dakẖāya bikalāmi ạảs̊tīra."],[4,13,"فَقَالَ مُرْدَخَايُ أَنْ تُجَاوَبَ أَسْتِيرُ: «لَا تَفْتَكِرِي فِي نَفْسِكِ أَنَّكِ تَنْجِينَ فِي بَيْتِ ٱلْمَلِكِ دُونَ جَمِيعِ ٱلْيَهُودِ.","faqāla mur̊dakẖāyu ạản̊ tujāwaba ạảs̊tīru: «lā taf̊takirī fī naf̊siki ạảnãki tan̊jīna fī baẙti ٱl̊maliki dūna jamīʿi ٱl̊yahūdi."],[4,14,"لِأَنَّكِ إِنْ سَكَتِّ سُكُوتًا فِي هَذَا ٱلْوَقْتِ يَكُونُ ٱلْفَرَجُ وَٱلنَّجَاةُ لِلْيَهُودِ مِنْ مَكَانٍ آخَرَ، وَأَمَّا أَنْتِ وَبَيْتُ أَبِيكِ فَتَبِيدُونَ. وَمَنْ يَعْلَمُ إِنْ كُنْتِ لِوَقْتٍ مِثْلِ هَذَا وَصَلْتِ إِلَى ٱلْمُلْكِ؟».","liạảnãki ại̹n̊ sakatĩ sukūtaⁿạ fī hadẖā ٱl̊waq̊ti yakūnu ٱl̊faraju waٱlnãjāẗu lil̊yahūdi min̊ makāniⁿ ậkẖara, wāảmãạ ạản̊ti wabaẙtu ạảbīki fatabīdūna. waman̊ yaʿ̊lamu ại̹n̊ kun̊ti liwaq̊tiⁿ mitẖ̊li hadẖā waṣal̊ti ại̹lay̱ ٱl̊mul̊ki?»."],[4,15,"فَقَالَتْ أَسْتِيرُ أَنْ يُجَاوَبَ مُرْدَخَايُ:","faqālat̊ ạảs̊tīru ạản̊ yujāwaba mur̊dakẖāyu:"],[4,16,"«ٱذْهَبِ ٱجْمَعْ جَمِيعَ ٱلْيَهُودِ ٱلْمَوْجُودِينَ فِي شُوشَنَ وَصُومُوا مِنْ جِهَتِي وَلَا تَأْكُلُوا وَلَا تَشْرَبُوا ثَلَاثَةَ أَيَّامٍ لَيْلًا وَنَهَارًا. وَأَنَا أَيْضًا وَجَوَارِيَّ نَصُومُ كَذَلِكَ. وَهَكَذَا أَدْخُلُ إِلَى ٱلْمَلِكِ خِلَافَ ٱلسُّنَّةِ. فَإِذَا هَلَكْتُ، هَلَكْتُ».","«ٱdẖ̊habi ٱj̊maʿ̊ jamīʿa ٱl̊yahūdi ٱl̊maẘjūdīna fī sẖūsẖana waṣūmūạ min̊ jihatī walā tā̊̉kulūạ walā tasẖ̊rabūạ tẖalātẖaẗa ạảyãạmiⁿ laẙlaⁿạ wanahāraⁿạ. wāảnā ạảẙḍaⁿạ wajawārīã naṣūmu kadẖalika. wahakadẖā ạảd̊kẖulu ại̹lay̱ ٱl̊maliki kẖilāfa ٱlsũnãẗi. fāi̹dẖā halak̊tu, halak̊tu»."],[4,17,"فَٱنْصَرَفَ مُرْدَخَايُ وَعَمِلَ حَسَبَ كُلِّ مَا أَوْصَتْهُ بِهِ أَسْتِيرُ.","faٱn̊ṣarafa mur̊dakẖāyu waʿamila ḥasaba kulĩ mā ạảẘṣat̊hu bihi ạảs̊tīru."],[5,1,"وَفِي ٱلْيَوْمِ ٱلثَّالِثِ لَبِسَتْ أَسْتِيرُ ثِيَابًا مَلَكِيَّةً وَوَقَفَتْ فِي دَارِ بَيْتِ ٱلْمَلِكِ ٱلدَّاخِلِيَّةِ مُقَابِلَ بَيْتِ ٱلْمَلِكِ، وَٱلْمَلِكُ جَالِسٌ عَلَى كُرْسِيِّ مُلْكِهِ فِي بَيْتِ ٱلْمُلْكِ مُقَابِلَ مَدْخَلِ ٱلْبَيْتِ.","wafī ٱl̊yaẘmi ٱltẖãạlitẖi labisat̊ ạảs̊tīru tẖīābaⁿạ malakīãẗaⁿ wawaqafat̊ fī dāri baẙti ٱl̊maliki ٱldãạkẖilīãẗi muqābila baẙti ٱl̊maliki, waٱl̊maliku jālisuⁿ ʿalay̱ kur̊sīĩ mul̊kihi fī baẙti ٱl̊mul̊ki muqābila mad̊kẖali ٱl̊baẙti."],[5,2,"فَلَمَّا رَأَى ٱلْمَلِكُ أَسْتِيرَ ٱلْمَلِكَةَ وَاقِفَةً فِي ٱلدَّارِ نَالَتْ نِعْمَةً فِي عَيْنَيْهِ، فَمَدَّ ٱلْمَلِكُ لِأَسْتِيرَ قَضِيبَ ٱلذَّهَبِ ٱلَّذِي بِيَدِهِ، فَدَنَتْ أَسْتِيرُ وَلَمَسَتْ رَأْسَ ٱلْقَضِيبِ.","falamãạ rāảy̱ ٱl̊maliku ạảs̊tīra ٱl̊malikaẗa wāqifaẗaⁿ fī ٱldãạri nālat̊ niʿ̊maẗaⁿ fī ʿaẙnaẙhi, famadã ٱl̊maliku liạảs̊tīra qaḍība ٱldẖãhabi ٱlãdẖī bīadihi, fadanat̊ ạảs̊tīru walamasat̊ rā̊̉sa ٱl̊qaḍībi."],[5,3,"فَقَالَ لَهَا ٱلْمَلِكُ: «مَا لَكِ يَا أَسْتِيرُ ٱلْمَلِكَةُ؟ وَمَا هِيَ طِلْبَتُكِ؟ إِلَى نِصْفِ ٱلْمَمْلَكَةِ تُعْطَى لَكِ».","faqāla lahā ٱl̊maliku: «mā laki yā ạảs̊tīru ٱl̊malikaẗu? wamā hīa ṭil̊batuki? ại̹lay̱ niṣ̊fi ٱl̊mam̊lakaẗi tuʿ̊ṭay̱ laki»."],[5,4,"فَقَالَتْ أَسْتِيرُ: «إِنْ حَسُنَ عِنْدَ ٱلْمَلِكِ فَلْيَأْتِ ٱلْمَلِكُ وَهَامَانُ ٱلْيَوْمَ إِلَى ٱلْوَلِيمَةِ ٱلَّتِي عَمِلْتُهَا لَهُ».","faqālat̊ ạảs̊tīru: «ại̹n̊ ḥasuna ʿin̊da ٱl̊maliki fal̊yā̊̉ti ٱl̊maliku wahāmānu ٱl̊yaẘma ại̹lay̱ ٱl̊walīmaẗi ٱlãtī ʿamil̊tuhā lahu»."],[5,5,"فَقَالَ ٱلْمَلِكُ: «أَسْرِعُوا بِهَامَانَ لِيُفْعَلَ كَلَامُ أَسْتِيرَ». فَأَتَى ٱلْمَلِكُ وَهَامَانُ إِلَى ٱلْوَلِيمَةِ ٱلَّتِي عَمِلَتْهَا أَسْتِيرُ.","faqāla ٱl̊maliku: «ạảs̊riʿūạ bihāmāna līuf̊ʿala kalāmu ạảs̊tīra». fāảtay̱ ٱl̊maliku wahāmānu ại̹lay̱ ٱl̊walīmaẗi ٱlãtī ʿamilat̊hā ạảs̊tīru."],[5,6,"فَقَالَ ٱلْمَلِكُ لِأَسْتِيرَ عِنْدَ شُرْبِ ٱلْخَمْرِ: «مَا هُوَ سُؤْلُكِ فَيُعْطَى لَكِ؟ وَمَا هِيَ طِلْبَتُكِ؟ إِلَى نِصْفِ ٱلْمَمْلَكَةِ تُقْضَى».","faqāla ٱl̊maliku liạảs̊tīra ʿin̊da sẖur̊bi ٱl̊kẖam̊ri: «mā hūa sū̊̉luki fayuʿ̊ṭay̱ laki? wamā hīa ṭil̊batuki? ại̹lay̱ niṣ̊fi ٱl̊mam̊lakaẗi tuq̊ḍay̱»."],[5,7,"فَأَجَابَتْ أَسْتِيرُ وَقَالتْ: «إِنَّ سُؤْلِي وَطِلْبَتِي،","fāảjābat̊ ạảs̊tīru waqālt̊: «ại̹nã sū̊̉lī waṭil̊batī,"],[5,8,"إِنْ وَجَدْتُ نِعْمَةً فِي عَيْنَيِ ٱلْمَلِكِ، وَإِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ أَنْ يُعْطَى سُؤْلِي وَتُقْضَى طِلْبَتِي، أَنْ يَأْتِيَ ٱلْمَلِكُ وَهَامَانُ إِلَى ٱلْوَلِيمَةِ ٱلَّتِي أَعْمَلُهَا لَهُمَا، وَغَدًا أَفْعَلُ حَسَبَ أَمْرِ ٱلْمَلِكِ».","ại̹n̊ wajad̊tu niʿ̊maẗaⁿ fī ʿaẙnayi ٱl̊maliki, wāi̹dẖā ḥasuna ʿin̊da ٱl̊maliki ạản̊ yuʿ̊ṭay̱ sū̊̉lī watuq̊ḍay̱ ṭil̊batī, ạản̊ yā̊̉tīa ٱl̊maliku wahāmānu ại̹lay̱ ٱl̊walīmaẗi ٱlãtī ạảʿ̊maluhā lahumā, wagẖadaⁿạ ạảf̊ʿalu ḥasaba ạảm̊ri ٱl̊maliki»."],[5,9,"فَخَرَجَ هَامَانُ فِي ذَلِكَ ٱلْيَوْمِ فَرِحًا وَطَيِّبَ ٱلْقَلْبِ. وَلَكِنْ لَمَّا رَأَى هَامَانُ مُرْدَخَايَ فِي بَابِ ٱلْمَلِكِ وَلَمْ يَقُمْ وَلَا تَحَرَّكَ لَهُ، ٱمْتَلَأَ هَامَانُ غَيْظًا عَلَى مُرْدَخَايَ.","fakẖaraja hāmānu fī dẖalika ٱl̊yaẘmi fariḥaⁿạ waṭayĩba ٱl̊qal̊bi. walakin̊ lamãạ rāảy̱ hāmānu mur̊dakẖāya fī bābi ٱl̊maliki walam̊ yaqum̊ walā taḥarãka lahu, ٱm̊talāả hāmānu gẖaẙẓaⁿạ ʿalay̱ mur̊dakẖāya."],[5,10,"وَتَجَلَّدَ هَامَانُ وَدَخَلَ بَيْتَهُ وَأَرْسَلَ فَٱسْتَحْضَرَ أَحِبَّاءَهُ وَزَرَشَ زَوْجَتَهُ،","watajalãda hāmānu wadakẖala baẙtahu wāảr̊sala faٱs̊taḥ̊ḍara ạảḥibãạʾahu wazarasẖa zaẘjatahu,"],[5,11,"وَعَدَّدَ لَهُمْ هَامَانُ عَظَمَةَ غِنَاهُ وَكَثْرَةَ بَنِيهِ، وَكُلَّ مَا عَظَّمَهُ ٱلْمَلِكُ بِهِ وَرَقَّاهُ عَلَى ٱلرُّؤَسَاءِ وَعَبِيدِ ٱلْمَلِكِ.","waʿadãda lahum̊ hāmānu ʿaẓamaẗa gẖināhu wakatẖ̊raẗa banīhi, wakulã mā ʿaẓãmahu ٱl̊maliku bihi waraqãạhu ʿalay̱ ٱlrũwảsāʾi waʿabīdi ٱl̊maliki."],[5,12,"وَقَالَ هَامَانُ: «حَتَّى إِنَّ أَسْتِيرَ ٱلْمَلِكَةَ لَمْ تُدْخِلْ مَعَ ٱلْمَلِكِ إِلَى ٱلْوَلِيمَةِ ٱلَّتِي عَمِلَتْهَا إِلَّا إِيَّايَ. وَأَنَا غَدًا أَيْضًا مَدْعُوٌّ إِلَيْهَا مَعَ ٱلْمَلِكِ.","waqāla hāmānu: «ḥatãy̱ ại̹nã ạảs̊tīra ٱl̊malikaẗa lam̊ tud̊kẖil̊ maʿa ٱl̊maliki ại̹lay̱ ٱl̊walīmaẗi ٱlãtī ʿamilat̊hā ại̹lãạ ại̹yãạya. wāảnā gẖadaⁿạ ạảẙḍaⁿạ mad̊ʿūuⁿ̃ ại̹laẙhā maʿa ٱl̊maliki."],[5,13,"وَكُلُّ هَذَا لَا يُسَاوِي عِنْدِي شَيْئًا كُلَّمَا أَرَى مُرْدَخَايَ ٱلْيَهُودِيَّ جَالِسًا فِي بَابِ ٱلْمَلِكِ».","wakulũ hadẖā lā yusāwī ʿin̊dī sẖaẙyaⁿ̉ạ kulãmā ạảray̱ mur̊dakẖāya ٱl̊yahūdīã jālisaⁿạ fī bābi ٱl̊maliki»."],[5,14,"فَقَالَتْ لَهُ زَرَشُ زَوْجَتُهُ وَكُلُّ أَحِبَّائِهِ: «فَلْيَعْمَلُوا خَشَبَةً ٱرْتِفَاعُهَا خَمْسُونَ ذِرَاعًا، وَفِي ٱلصَّبَاحِ قُلْ لِلْمَلِكِ أَنْ يَصْلِبُوا مُرْدَخَايَ عَلَيْهَا، ثُمَّ ٱدْخُلْ مَعَ ٱلْمَلِكِ إِلَى ٱلْوَلِيمَةِ فَرِحًا». فَحَسُنَ ٱلْكَلَامُ عِنْدَ هَامَانَ وَعَمِلَ ٱلْخَشَبَةَ.","faqālat̊ lahu zarasẖu zaẘjatuhu wakulũ ạảḥibãạyỉhi: «fal̊yaʿ̊malūạ kẖasẖabaẗaⁿ ٱr̊tifāʿuhā kẖam̊sūna dẖirāʿaⁿạ, wafī ٱlṣãbāḥi qul̊ lil̊maliki ạản̊ yaṣ̊libūạ mur̊dakẖāya ʿalaẙhā, tẖumã ٱd̊kẖul̊ maʿa ٱl̊maliki ại̹lay̱ ٱl̊walīmaẗi fariḥaⁿạ». faḥasuna ٱl̊kalāmu ʿin̊da hāmāna waʿamila ٱl̊kẖasẖabaẗa."],[6,1,"فِي تِلْكَ ٱللَّيْلَةِ طَارَ نَوْمُ ٱلْمَلِكِ، فَأَمَرَ بِأَنْ يُؤْتَى بِسِفْرِ تَذْكَارِ أَخْبَارِ ٱلْأَيَّامِ فَقُرِئَتْ أَمَامَ ٱلْمَلِكِ.","fī til̊ka ٱllãẙlaẗi ṭāra naẘmu ٱl̊maliki, fāảmara biạản̊ yū̊̉tay̱ bisif̊ri tadẖ̊kāri ạảkẖ̊bāri ٱl̊ạảyãạmi faqurīảt̊ ạảmāma ٱl̊maliki."],[6,2,"فَوُجِدَ مَكْتُوبًا مَا أَخْبَرَ بِهِ مُرْدَخَايُ عَنْ بِغْثَانَا وَتَرَشَ خَصِيَّيِ ٱلْمَلِكِ حَارِسَيِ ٱلْبَابِ، ٱللَّذَيْنِ طَلَبَا أَنْ يَمُدَّا أَيْدِيَهُمَا إِلَى ٱلْمَلِكِ أَحَشْوِيرُوشَ.","fawujida mak̊tūbaⁿạ mā ạảkẖ̊bara bihi mur̊dakẖāyu ʿan̊ bigẖ̊tẖānā watarasẖa kẖaṣīãyi ٱl̊maliki ḥārisayi ٱl̊bābi, ٱllãdẖaẙni ṭalabā ạản̊ yamudãạ ạảẙdīahumā ại̹lay̱ ٱl̊maliki ạảḥasẖ̊wīrūsẖa."],[6,3,"فَقَالَ ٱلْمَلِكُ: «أَيَّةُ كَرَامَةٍ وَعَظَمَةٍ عُمِلَتْ لِمُرْدَخَايَ لِأَجْلِ هَذَا؟» فَقَالَ غِلْمَانُ ٱلْمَلِكِ ٱلَّذِينَ يَخْدِمُونَهُ: «لَمْ يُعْمَلْ مَعَهُ شَيْءٌ».","faqāla ٱl̊maliku: «ạảyãẗu karāmaẗiⁿ waʿaẓamaẗiⁿ ʿumilat̊ limur̊dakẖāya liạảj̊li hadẖā?» faqāla gẖil̊mānu ٱl̊maliki ٱlãdẖīna yakẖ̊dimūnahu: «lam̊ yuʿ̊mal̊ maʿahu sẖaẙʾuⁿ»."],[6,4,"فَقَالَ ٱلْمَلِكُ: «مَنْ في ٱلدَّارِ؟» وَكَانَ هَامَانُ قَدْ دَخَلَ دَارَ بَيْتِ ٱلْمَلِكِ ٱلْخَارِجِيَّةَ لِكَيْ يَقُولَ لِلْمَلِكِ أَنْ يُصْلَبَ مُرْدَخَايُ عَلَى ٱلْخَشَبَةِ ٱلَّتِي أَعَدَّهَا لَهُ.","faqāla ٱl̊maliku: «man̊ fy ٱldãạri?» wakāna hāmānu qad̊ dakẖala dāra baẙti ٱl̊maliki ٱl̊kẖārijīãẗa likaẙ yaqūla lil̊maliki ạản̊ yuṣ̊laba mur̊dakẖāyu ʿalay̱ ٱl̊kẖasẖabaẗi ٱlãtī ạảʿadãhā lahu."],[6,5,"فَقَالَ غِلْمَانُ ٱلْمَلِكِ لَهُ: «هُوَذَا هَامَانُ وَاقِفٌ فِي ٱلدَّارِ». فَقَالَ ٱلْمَلِكُ: «لِيَدْخُلْ».","faqāla gẖil̊mānu ٱl̊maliki lahu: «hūadẖā hāmānu wāqifuⁿ fī ٱldãạri». faqāla ٱl̊maliku: «līad̊kẖul̊»."],[6,6,"وَلَمَّا دَخَلَ هَامَانُ قَالَ لَهُ ٱلْمَلِكُ: «مَاذَا يُعْمَلُ لِرَجُلٍ يُسَرُّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ؟» فَقَالَ هَامَانُ فِي قَلْبِهِ: «مَنْ يُسَرُّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ أَكْثَرَ مِنِّي؟»","walamãạ dakẖala hāmānu qāla lahu ٱl̊maliku: «mādẖā yuʿ̊malu lirajuliⁿ yusarũ ٱl̊maliku biạản̊ yuk̊rimahu?» faqāla hāmānu fī qal̊bihi: «man̊ yusarũ ٱl̊maliku biạản̊ yuk̊rimahu ạảk̊tẖara minĩy?»"],[6,7,"فَقَالَ هَامَانُ لِلْمَلِكِ: «إِنَّ ٱلرَّجُلَ ٱلَّذِي يُسَرُّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ","faqāla hāmānu lil̊maliki: «ại̹nã ٱlrãjula ٱlãdẖī yusarũ ٱl̊maliku biạản̊ yuk̊rimahu"],[6,8,"يَأْتُونَ بِٱللِّبَاسِ ٱلسُّلْطَانِيِّ ٱلَّذِي يَلْبَسُهُ ٱلْمَلِكُ، وَبِالْفَرَسِ ٱلَّذِي يَرْكَبُهُ ٱلْمَلِكُ، وَبِتَاجِ ٱلْمُلْكِ ٱلَّذِي يُوضَعُ عَلَى رَأْسِهِ،","yā̊̉tūna biٱllĩbāsi ٱlsũl̊ṭānīĩ ٱlãdẖī yal̊basuhu ٱl̊maliku, wabiạl̊farasi ٱlãdẖī yar̊kabuhu ٱl̊maliku, wabitāji ٱl̊mul̊ki ٱlãdẖī yūḍaʿu ʿalay̱ rā̊̉sihi,"],[6,9,"وَيُدْفَعُ ٱللِّبَاسُ وَٱلْفَرَسُ لِرَجُلٍ مِنْ رُؤَسَاءِ ٱلْمَلِكِ ٱلْأَشْرَافِ، وَيُلْبِسُونَ ٱلرَّجُلَ ٱلَّذِي سُرَّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ وَيُرَكِّبُونَهُ عَلَى ٱلْفَرَسِ فِي سَاحَةِ ٱلْمَدِينَةِ، وَيُنَادُونَ قُدَّامَهُ: هَكَذَا يُصْنَعُ لِلرَّجُلِ ٱلَّذِي يُسَرُّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ».","wayud̊faʿu ٱllĩbāsu waٱl̊farasu lirajuliⁿ min̊ rūảsāʾi ٱl̊maliki ٱl̊ạảsẖ̊rāfi, wayul̊bisūna ٱlrãjula ٱlãdẖī surã ٱl̊maliku biạản̊ yuk̊rimahu wayurakĩbūnahu ʿalay̱ ٱl̊farasi fī sāḥaẗi ٱl̊madīnaẗi, wayunādūna qudãạmahu: hakadẖā yuṣ̊naʿu lilrãjuli ٱlãdẖī yusarũ ٱl̊maliku biạản̊ yuk̊rimahu»."],[6,10,"فَقَالَ ٱلْمَلِكُ لِهَامَانَ: «أَسْرِعْ وَخُذِ ٱللِّبَاسَ وَٱلْفَرَسَ كَمَا تَكَلَّمْتَ، وَٱفْعَلْ هَكَذَا لِمُرْدَخَايَ ٱلْيَهُودِيِّ ٱلْجَالِسِ فِي بَابِ ٱلْمَلِكِ. لَا يَسْقُطْ شَيْءٌ مِنْ جَمِيعِ مَا قُلْتَهُ».","faqāla ٱl̊maliku lihāmāna: «ạảs̊riʿ̊ wakẖudẖi ٱllĩbāsa waٱl̊farasa kamā takalãm̊ta, waٱf̊ʿal̊ hakadẖā limur̊dakẖāya ٱl̊yahūdīĩ ٱl̊jālisi fī bābi ٱl̊maliki. lā yas̊quṭ̊ sẖaẙʾuⁿ min̊ jamīʿi mā qul̊tahu»."],[6,11,"فَأَخَذَ هَامَانُ ٱللِّبَاسَ وَٱلْفَرَسَ وَأَلْبَسَ مُرْدَخَايَ وَأَرْكَبَهُ فِي سَاحَةِ ٱلْمَدِينَةِ، وَنَادَى قُدَّامَهُ: «هَكَذَا يُصْنَعُ لِلرَّجُلِ ٱلَّذِي يُسَرُّ ٱلْمَلِكُ بِأَنْ يُكْرِمَهُ».","fāảkẖadẖa hāmānu ٱllĩbāsa waٱl̊farasa wāảl̊basa mur̊dakẖāya wāảr̊kabahu fī sāḥaẗi ٱl̊madīnaẗi, wanāday̱ qudãạmahu: «hakadẖā yuṣ̊naʿu lilrãjuli ٱlãdẖī yusarũ ٱl̊maliku biạản̊ yuk̊rimahu»."],[6,12,"وَرَجَعَ مُرْدَخَايُ إِلَى بَابِ ٱلْمَلِكِ. وَأَمَّا هَامَانُ فَأَسْرَعَ إِلَى بَيْتِهِ نَائِحًا وَمُغَطَّى ٱلرَّأْسِ.","warajaʿa mur̊dakẖāyu ại̹lay̱ bābi ٱl̊maliki. wāảmãạ hāmānu fāảs̊raʿa ại̹lay̱ baẙtihi nāyỉḥaⁿạ wamugẖaṭãy̱ ٱlrãạ̊̉si."],[6,13,"وَقَصَّ هَامَانُ عَلَى زَرَشَ زَوْجَتِهِ وَجَمِيعِ أَحِبَّائِهِ كُلَّ مَا أَصَابَهُ. فَقَالَ لَهُ حُكَمَاؤُهُ وَزَرَشُ زَوْجَتُهُ: «إِذَا كَانَ مُرْدَخَايُ ٱلَّذِي ٱبْتَدَأْتَ تَسْقُطُ قُدَّامَهُ مِنْ نَسْلِ ٱلْيَهُودِ، فَلَا تَقْدِرُ عَلَيْهِ، بَلْ تَسْقُطُ قُدَّامَهُ سُقُوطًا».","waqaṣã hāmānu ʿalay̱ zarasẖa zaẘjatihi wajamīʿi ạảḥibãạyỉhi kulã mā ạảṣābahu. faqāla lahu ḥukamāwủhu wazarasẖu zaẘjatuhu: «ại̹dẖā kāna mur̊dakẖāyu ٱlãdẖī ٱb̊tadā̊̉ta tas̊quṭu qudãạmahu min̊ nas̊li ٱl̊yahūdi, falā taq̊diru ʿalaẙhi, bal̊ tas̊quṭu qudãạmahu suqūṭaⁿạ»."],[6,14,"وَفِيمَا هُمْ يُكَلِّمُونَهُ وَصَلَ خِصْيَانُ ٱلْمَلِكِ وَأَسْرَعُوا لِلْإِتْيَانِ بِهَامَانَ إِلَى ٱلْوَلِيمَةِ ٱلَّتِي عَمِلَتْهَا أَسْتِيرُ.","wafīmā hum̊ yukalĩmūnahu waṣala kẖiṣ̊yānu ٱl̊maliki wāảs̊raʿūạ lil̊ại̹t̊yāni bihāmāna ại̹lay̱ ٱl̊walīmaẗi ٱlãtī ʿamilat̊hā ạảs̊tīru."],[7,1,"فَجَاءَ ٱلْمَلِكُ وَهَامَانُ لِيَشْرَبَا عِنْدَ أَسْتِيرَ ٱلْمَلِكَةِ.","fajāʾa ٱl̊maliku wahāmānu līasẖ̊rabā ʿin̊da ạảs̊tīra ٱl̊malikaẗi."],[7,2,"فَقَالَ ٱلْمَلِكُ لِأَسْتِيرَ فِي ٱلْيَوْمِ ٱلثَّانِي أَيْضًا عِنْدَ شُرْبِ ٱلْخَمْرِ: «مَا هُوَ سُؤْلُكِ يَا أَسْتِيرُ ٱلْمَلِكَةُ فَيُعْطَى لَكِ؟ وَمَا هِيَ طِلْبَتُكِ؟ وَلَوْ إِلَى نِصْفِ ٱلْمَمْلَكَةِ تُقْضَى».","faqāla ٱl̊maliku liạảs̊tīra fī ٱl̊yaẘmi ٱltẖãạnī ạảẙḍaⁿạ ʿin̊da sẖur̊bi ٱl̊kẖam̊ri: «mā hūa sū̊̉luki yā ạảs̊tīru ٱl̊malikaẗu fayuʿ̊ṭay̱ laki? wamā hīa ṭil̊batuki? walaẘ ại̹lay̱ niṣ̊fi ٱl̊mam̊lakaẗi tuq̊ḍay̱»."],[7,3,"فَأَجَابَتْ أَسْتِيرُ ٱلْمَلِكَةُ وَقَالَتْ: «إِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ أَيُّهَا ٱلْمَلِكُ، وَإِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ، فَلْتُعْطَ لِي نَفْسِي بِسُؤْلِي، وَشَعْبِي بِطِلْبَتِي.","fāảjābat̊ ạảs̊tīru ٱl̊malikaẗu waqālat̊: «ại̹n̊ kun̊tu qad̊ wajad̊tu niʿ̊maẗaⁿ fī ʿaẙnaẙka ạảyũhā ٱl̊maliku, wāi̹dẖā ḥasuna ʿin̊da ٱl̊maliki, fal̊tuʿ̊ṭa lī naf̊sī bisū̊̉lī, wasẖaʿ̊bī biṭil̊batī."],[7,4,"لِأَنَّنَا قَدْ بِعْنَا أَنَا وَشَعْبِي لِلْهَلَاكِ وَٱلْقَتْلِ وَٱلْإِبَادَةِ. وَلَوْ بِعْنَا عَبِيدًا وَإِمَاءً لَكُنْتُ سَكَتُّ، مَعَ أَنَّ ٱلْعَدُوَّ لَا يُعَوِّضُ عَنْ خَسَارَةِ ٱلْمَلِكِ».","liạảnãnā qad̊ biʿ̊nā ạảnā wasẖaʿ̊bī lil̊halāki waٱl̊qat̊li waٱl̊ại̹bādaẗi. walaẘ biʿ̊nā ʿabīdaⁿạ wāi̹māʾaⁿ lakun̊tu sakatũ, maʿa ạảnã ٱl̊ʿadūã lā yuʿawĩḍu ʿan̊ kẖasāraẗi ٱl̊maliki»."],[7,5,"فَتَكَلَّمَ ٱلْمَلِكُ أَحَشْوِيرُوشُ وَقَالَ لِأَسْتِيرَ ٱلْمَلِكَةِ: «مَنْ هُوَ؟ وَأَيْنَ هُوَ هَذَا ٱلَّذِي يَتَجَاسَرُ بِقَلْبِهِ عَلَى أَنْ يَعْمَلَ هَكَذَا؟»","fatakalãma ٱl̊maliku ạảḥasẖ̊wīrūsẖu waqāla liạảs̊tīra ٱl̊malikaẗi: «man̊ hūa? wāảẙna hūa hadẖā ٱlãdẖī yatajāsaru biqal̊bihi ʿalay̱ ạản̊ yaʿ̊mala hakadẖā?»"],[7,6,"فَقَالَتْ أَسْتِيرُ: «هُوَ رَجُلٌ خَصْمٌ وَعَدُوٌّ، هَذَا هَامَانُ ٱلرَّدِيءُ». فَٱرْتَاعَ هَامَانُ أَمَامَ ٱلْمَلِكِ وَٱلْمَلِكَةِ.","faqālat̊ ạảs̊tīru: «hūa rajuluⁿ kẖaṣ̊muⁿ waʿadūuⁿ̃, hadẖā hāmānu ٱlrãdīʾu». faٱr̊tāʿa hāmānu ạảmāma ٱl̊maliki waٱl̊malikaẗi."],[7,7,"فَقَامَ ٱلْمَلِكُ بِغَيْظِهِ عَنْ شُرْبِ ٱلْخَمْرِ إِلَى جَنَّةِ ٱلْقَصْرِ. وَوَقَفَ هَامَانُ لِيَتَوَسَّلَ عَنْ نَفْسِهِ إِلَى أَسْتِيرَ ٱلْمَلِكَةِ، لِأَنَّهُ رَأَى أَنَّ ٱلشَّرَّ قَدْ أُعِدَّ عَلَيْهِ مِنْ قِبَلِ ٱلْمَلِكِ.","faqāma ٱl̊maliku bigẖaẙẓihi ʿan̊ sẖur̊bi ٱl̊kẖam̊ri ại̹lay̱ janãẗi ٱl̊qaṣ̊ri. wawaqafa hāmānu līatawasãla ʿan̊ naf̊sihi ại̹lay̱ ạảs̊tīra ٱl̊malikaẗi, liạảnãhu rāảy̱ ạảnã ٱlsẖãrã qad̊ ạủʿidã ʿalaẙhi min̊ qibali ٱl̊maliki."],[7,8,"وَلَمَّا رَجَعَ ٱلْمَلِكُ مِنْ جَنَّةِ ٱلْقَصْرِ إِلَى بَيْتِ شُرْبِ ٱلْخَمْرِ، وَهَامَانُ مُتَوَاقِعٌ عَلَى ٱلسَّرِيرِ ٱلَّذِي كَانَتْ أَسْتِيرُ عَلَيْهِ، قَالَ ٱلْمَلِكُ: «هَلْ أَيْضًا يَكْبِسُ ٱلْمَلِكَةَ مَعي فِي ٱلْبَيْتِ؟» وَلَمَّا خَرَجَتِ ٱلْكَلِمَةُ مِنْ فَمِ ٱلْمَلِكِ غَطَّوْا وَجْهَ هَامَانَ.","walamãạ rajaʿa ٱl̊maliku min̊ janãẗi ٱl̊qaṣ̊ri ại̹lay̱ baẙti sẖur̊bi ٱl̊kẖam̊ri, wahāmānu mutawāqiʿuⁿ ʿalay̱ ٱlsãrīri ٱlãdẖī kānat̊ ạảs̊tīru ʿalaẙhi, qāla ٱl̊maliku: «hal̊ ạảẙḍaⁿạ yak̊bisu ٱl̊malikaẗa maʿy fī ٱl̊baẙti?» walamãạ kẖarajati ٱl̊kalimaẗu min̊ fami ٱl̊maliki gẖaṭãẘạ waj̊ha hāmāna."],[7,9,"فَقَالَ حَرْبُونَا، وَاحِدٌ مِنَ ٱلْخِصْيَانِ ٱلَّذِينَ بَيْنَ يَدَيِ ٱلْمَلِكِ: «هُوَذَا ٱلْخَشَبَةُ أَيْضًا ٱلَّتِي عَمِلَهَا هَامَانُ لِمُرْدَخَايَ ٱلَّذِي تَكَلَّمَ بِٱلْخَيْرِ نَحْوَ ٱلْمَلِكِ قَائِمَةٌ فِي بَيْتِ هَامَانَ، ٱرْتِفَاعُهَا خَمْسُونَ ذِرَاعًا». فَقَالَ ٱلْمَلِكُ: «ٱصْلِبُوهُ عَلَيْهَا».","faqāla ḥar̊būnā, wāḥiduⁿ mina ٱl̊kẖiṣ̊yāni ٱlãdẖīna baẙna yadayi ٱl̊maliki: «hūadẖā ٱl̊kẖasẖabaẗu ạảẙḍaⁿạ ٱlãtī ʿamilahā hāmānu limur̊dakẖāya ٱlãdẖī takalãma biٱl̊kẖaẙri naḥ̊wa ٱl̊maliki qāyỉmaẗuⁿ fī baẙti hāmāna, ٱr̊tifāʿuhā kẖam̊sūna dẖirāʿaⁿạ». faqāla ٱl̊maliku: «ٱṣ̊libūhu ʿalaẙhā»."],[7,10,"فَصَلَبُوا هَامَانَ عَلَى ٱلْخَشَبَةِ ٱلَّتِي أَعَدَّهَا لِمُرْدَخَايَ. ثُمَّ سَكَنَ غَضَبُ ٱلْمَلِكِ.","faṣalabūạ hāmāna ʿalay̱ ٱl̊kẖasẖabaẗi ٱlãtī ạảʿadãhā limur̊dakẖāya. tẖumã sakana gẖaḍabu ٱl̊maliki."],[8,1,"فِي ذَلِكَ ٱلْيَوْمِ أَعْطَى ٱلْمَلِكُ أَحَشْوِيرُوشُ لِأَسْتِيرَ ٱلْمَلِكَةِ بَيْتَ هَامَانَ عَدُوِّ ٱلْيَهُودِ. وَأَتَى مُرْدَخَايُ إِلَى أَمَامِ ٱلْمَلِكِ لِأَنَّ أَسْتِيرَ أَخْبَرَتْهُ بِمَا هُوَ لَهَا.","fī dẖalika ٱl̊yaẘmi ạảʿ̊ṭay̱ ٱl̊maliku ạảḥasẖ̊wīrūsẖu liạảs̊tīra ٱl̊malikaẗi baẙta hāmāna ʿadūĩ ٱl̊yahūdi. wāảtay̱ mur̊dakẖāyu ại̹lay̱ ạảmāmi ٱl̊maliki liạảnã ạảs̊tīra ạảkẖ̊barat̊hu bimā hūa lahā."],[8,2,"وَنَزَعَ ٱلْمَلِكُ خَاتَمَهُ ٱلَّذِي أَخَذَهُ مِنْ هَامَانَ وَأَعْطَاهُ لِمُرْدَخَايَ. وَأَقَامَتْ أَسْتِيرُ مُرْدَخَايَ عَلَى بَيْتِ هَامَانَ.","wanazaʿa ٱl̊maliku kẖātamahu ٱlãdẖī ạảkẖadẖahu min̊ hāmāna wāảʿ̊ṭāhu limur̊dakẖāya. wāảqāmat̊ ạảs̊tīru mur̊dakẖāya ʿalay̱ baẙti hāmāna."],[8,3,"ثُمَّ عَادَتْ أَسْتِيرُ وَتَكَلَّمَتْ أَمَامَ ٱلْمَلِكِ وَسَقَطَتْ عِنْدَ رِجْلَيْهِ وَبَكَتْ وَتَضَرَّعَتْ إِلَيْهِ أَنْ يُزِيلَ شَرَّ هَامَانَ ٱلْأَجَاجِيِّ وَتَدْبِيرَهُ ٱلَّذِي دَبَّرَهُ عَلَى ٱلْيَهُودِ.","tẖumã ʿādat̊ ạảs̊tīru watakalãmat̊ ạảmāma ٱl̊maliki wasaqaṭat̊ ʿin̊da rij̊laẙhi wabakat̊ wataḍarãʿat̊ ại̹laẙhi ạản̊ yuzīla sẖarã hāmāna ٱl̊ạảjājīĩ watad̊bīrahu ٱlãdẖī dabãrahu ʿalay̱ ٱl̊yahūdi."],[8,4,"فَمَدَّ ٱلْمَلِكُ لِأَسْتِيرَ قَضِيبَ ٱلذَّهَبِ، فَقَامَتْ أَسْتِيرُ وَوَقَفَتْ أَمَامَ ٱلْمَلِكِ","famadã ٱl̊maliku liạảs̊tīra qaḍība ٱldẖãhabi, faqāmat̊ ạảs̊tīru wawaqafat̊ ạảmāma ٱl̊maliki"],[8,5,"وَقَالَتْ: «إِذَا حَسُنَ عِنْدَ ٱلْمَلِكِ، وَإِنْ كُنْتُ قَدْ وَجَدْتُ نِعْمَةً أَمَامَهُ وَٱسْتَقَامَ ٱلْأَمْرُ أَمَامَ ٱلْمَلِكِ وَحَسُنْتُ أَنَا لَدَيْهِ، فَلْيُكْتَبْ لِكَيْ تُرَدَّ كِتَابَاتُ تَدْبِيرِ هَامَانَ بْنِ هَمَدَاثَا ٱلْأَجَاجِيِّ ٱلَّتِي كَتَبَهَا لِإِبَادَةِ ٱلْيَهُودِ ٱلَّذِينَ فِي كُلِّ بِلَادِ ٱلْمَلِكِ.","waqālat̊: «ại̹dẖā ḥasuna ʿin̊da ٱl̊maliki, wāi̹n̊ kun̊tu qad̊ wajad̊tu niʿ̊maẗaⁿ ạảmāmahu waٱs̊taqāma ٱl̊ạảm̊ru ạảmāma ٱl̊maliki waḥasun̊tu ạảnā ladaẙhi, fal̊yuk̊tab̊ likaẙ turadã kitābātu tad̊bīri hāmāna b̊ni hamadātẖā ٱl̊ạảjājīĩ ٱlãtī katabahā liại̹bādaẗi ٱl̊yahūdi ٱlãdẖīna fī kulĩ bilādi ٱl̊maliki."],[8,6,"لِأَنَّنِي كَيْفَ أَسْتَطِيعُ أَنْ أَرَى ٱلشَّرَّ ٱلَّذِي يُصِيبُ شَعْبِي؟ وَكَيْفَ أَسْتَطِيعُ أَنْ أَرَى هَلَاكَ جِنْسِي؟».","liạảnãnī kaẙfa ạảs̊taṭīʿu ạản̊ ạảray̱ ٱlsẖãrã ٱlãdẖī yuṣību sẖaʿ̊bī? wakaẙfa ạảs̊taṭīʿu ạản̊ ạảray̱ halāka jin̊sī?»."],[8,7,"فَقَالَ ٱلْمَلِكُ أَحَشْوِيرُوشُ لِأَسْتِيرَ ٱلْمَلِكَةِ وَمُرْدَخَايَ ٱلْيَهُودِيِّ: «هُوَذَا قَدْ أَعْطَيْتُ بَيْتَ هَامَانَ لِأَسْتِيرَ، أَمَّا هُوَ فَقَدْ صَلَبُوهُ عَلَى ٱلْخَشَبَةِ مِنْ أَجْلِ أَنَّهُ مَدَّ يَدَهُ إِلَى ٱلْيَهُودِ.","faqāla ٱl̊maliku ạảḥasẖ̊wīrūsẖu liạảs̊tīra ٱl̊malikaẗi wamur̊dakẖāya ٱl̊yahūdīĩ: «hūadẖā qad̊ ạảʿ̊ṭaẙtu baẙta hāmāna liạảs̊tīra, ạảmãạ hūa faqad̊ ṣalabūhu ʿalay̱ ٱl̊kẖasẖabaẗi min̊ ạảj̊li ạảnãhu madã yadahu ại̹lay̱ ٱl̊yahūdi."],[8,8,"فَٱكْتُبَا أَنْتُمَا إِلَى ٱلْيَهُودِ مَا يَحْسُنُ فِي أَعْيُنِكُمَا بِٱسْمِ ٱلْمَلِكِ، وَٱخْتُمَاهُ بِخَاتِمِ ٱلْمَلِكِ، لِأَنَّ ٱلْكِتَابَةَ ٱلَّتِي تُكْتَبُ بِٱسْمِ ٱلْمَلِكِ وَتُخْتَمُ بِخَاتِمِهِ لَا تُرَدُّ».","faٱk̊tubā ạản̊tumā ại̹lay̱ ٱl̊yahūdi mā yaḥ̊sunu fī ạảʿ̊yunikumā biٱs̊mi ٱl̊maliki, waٱkẖ̊tumāhu bikẖātimi ٱl̊maliki, liạảnã ٱl̊kitābaẗa ٱlãtī tuk̊tabu biٱs̊mi ٱl̊maliki watukẖ̊tamu bikẖātimihi lā turadũ»."],[8,9,"فَدُعِيَ كُتَّابُ ٱلْمَلِكِ فِي ذَلِكَ ٱلْوَقْتِ فِي ٱلشَّهْرِ ٱلثَّالِثِ، أَيْ شَهْرِ سِيوَانَ، فِي ٱلثَّالِثِ وَٱلْعِشْرِينَ مِنْهُ، وَكُتِبَ حَسَبَ كُلِّ مَا أَمَرَ بِهِ مُرْدَخَايُ إِلَى ٱلْيَهُودِ وَإِلَى ٱلْمَرَازِبَةِ وَٱلْوُلَاةِ وَرُؤَسَاءِ ٱلْبُلْدَانِ ٱلَّتِي مِنَ ٱلْهِنْدِ إِلَى كُوشَ، مِئَةٍ وَسَبْعٍ وَعِشْرِينَ كُورَةً، إِلَى كُلِّ كُورَةٍ بِكِتَابَتِهَا وَكُلِّ شَعْبٍ بِلِسَانِهِ، وَإِلَى ٱلْيَهُودِ بِكِتَابَتِهِمْ وَلِسَانِهِمْ.","faduʿīa kutãạbu ٱl̊maliki fī dẖalika ٱl̊waq̊ti fī ٱlsẖãh̊ri ٱltẖãạlitẖi, ạảẙ sẖah̊ri sīwāna, fī ٱltẖãạlitẖi waٱl̊ʿisẖ̊rīna min̊hu, wakutiba ḥasaba kulĩ mā ạảmara bihi mur̊dakẖāyu ại̹lay̱ ٱl̊yahūdi wāi̹lay̱ ٱl̊marāzibaẗi waٱl̊wulāẗi warūảsāʾi ٱl̊bul̊dāni ٱlãtī mina ٱl̊hin̊di ại̹lay̱ kūsẖa, mīảẗiⁿ wasab̊ʿiⁿ waʿisẖ̊rīna kūraẗaⁿ, ại̹lay̱ kulĩ kūraẗiⁿ bikitābatihā wakulĩ sẖaʿ̊biⁿ bilisānihi, wāi̹lay̱ ٱl̊yahūdi bikitābatihim̊ walisānihim̊."],[8,10,"فَكَتَبَ بِٱسْمِ ٱلْمَلِكِ أَحَشْوِيرُوشَ وَخَتَمَ بِخَاتِمِ ٱلْمَلِكِ، وَأَرْسَلَ رَسَائِلَ بِأَيْدِي بَرِيدِ ٱلْخَيْلِ رُكَّابِ ٱلْجِيَادِ وَٱلْبِغَالِ بَنِي الرَّمَكِ،","fakataba biٱs̊mi ٱl̊maliki ạảḥasẖ̊wīrūsẖa wakẖatama bikẖātimi ٱl̊maliki, wāảr̊sala rasāyỉla biạảẙdī barīdi ٱl̊kẖaẙli rukãạbi ٱl̊jīādi waٱl̊bigẖāli banī ạlrãmaki,"],[8,11,"ٱلَّتِي بِهَا أَعْطَى ٱلْمَلِكُ ٱلْيَهُودَ فِي مَدِينَةٍ فَمَدِينَةٍ أَنْ يَجْتَمِعُوا وَيَقِفُوا لِأَجْلِ أَنْفُسِهِمْ، وَيُهْلِكُوا وَيَقْتُلُوا وَيُبِيدُوا قُوَّةَ كُلِّ شَعْبٍ وَكُورَةٍ تُضَادُّهُمْ حَتَّى ٱلْأَطْفَالَ وَٱلنِّسَاءَ، وَأَنْ يَسْلُبُوا غَنِيمَتَهُمْ،","ٱlãtī bihā ạảʿ̊ṭay̱ ٱl̊maliku ٱl̊yahūda fī madīnaẗiⁿ famadīnaẗiⁿ ạản̊ yaj̊tamiʿūạ wayaqifūạ liạảj̊li ạản̊fusihim̊, wayuh̊likūạ wayaq̊tulūạ wayubīdūạ qūãẗa kulĩ sẖaʿ̊biⁿ wakūraẗiⁿ tuḍādũhum̊ ḥatãy̱ ٱl̊ạảṭ̊fāla waٱlnĩsāʾa, wāản̊ yas̊lubūạ gẖanīmatahum̊,"],[8,12,"فِي يَوْمٍ وَاحِدٍ فِي كُلِّ كُوَرِ ٱلْمَلِكِ أَحَشْوِيرُوشَ، فِي ٱلثَّالِثَ عَشَرَ مِنَ ٱلشَّهْرِ ٱلثَّانِي عَشَرَ، أَيْ شَهْرِ أَذَارَ.","fī yaẘmiⁿ wāḥidiⁿ fī kulĩ kūari ٱl̊maliki ạảḥasẖ̊wīrūsẖa, fī ٱltẖãạlitẖa ʿasẖara mina ٱlsẖãh̊ri ٱltẖãạnī ʿasẖara, ạảẙ sẖah̊ri ạảdẖāra."],[8,13,"صُورَةُ ٱلْكِتَابَةِ ٱلْمُعْطَاةِ سُنَّةً فِي كُلِّ ٱلْبُلْدَانِ، أُشْهِرَتْ عَلَى جَمِيعِ ٱلشُّعُوبِ أَنْ يَكُونَ ٱلْيَهُودُ مُسْتَعِدِّينَ لِهَذَا ٱلْيَوْمِ لِيَنْتَقِمُوا مِنْ أَعْدَائِهِمْ.","ṣūraẗu ٱl̊kitābaẗi ٱl̊muʿ̊ṭāẗi sunãẗaⁿ fī kulĩ ٱl̊bul̊dāni, ạủsẖ̊hirat̊ ʿalay̱ jamīʿi ٱlsẖũʿūbi ạản̊ yakūna ٱl̊yahūdu mus̊taʿidĩyna lihadẖā ٱl̊yaẘmi līan̊taqimūạ min̊ ạảʿ̊dāyỉhim̊."],[8,14,"فَخَرَجَ ٱلبَرِيدُ رُكَّابُ ٱلْجِيَادِ وَٱلْبِغَالِ وَأَمْرُ ٱلْمَلِكِ يَحِثُّهُمْ وَيُعَجِّلُهُمْ، وَأُعْطِيَ ٱلْأَمْرُ فِي شُوشَنَ ٱلْقَصْرِ.","fakẖaraja ٱlbarīdu rukãạbu ٱl̊jīādi waٱl̊bigẖāli wāảm̊ru ٱl̊maliki yaḥitẖũhum̊ wayuʿajĩluhum̊, wāủʿ̊ṭīa ٱl̊ạảm̊ru fī sẖūsẖana ٱl̊qaṣ̊ri."],[8,15,"وَخَرَجَ مُرْدَخَايُ مِنْ أَمَامِ ٱلْمَلِكِ بِلِبَاسٍ مَلِكِيٍّ أَسْمَانْجُونِيٍّ وَأَبْيَضَ، وَتَاجٌ عَظِيمٌ مِنْ ذَهَبٍ، وَحُلَّةٌ مِنْ بَزٍّ وَأُرْجُوَانٍ. وَكَانَتْ مَدِينَةُ شُوشَنَ مُتَهَلِّلَةً وَفَرِحَةً.","wakẖaraja mur̊dakẖāyu min̊ ạảmāmi ٱl̊maliki bilibāsiⁿ malikīiⁿ̃ ạảs̊mān̊jūnīiⁿ̃ wāảb̊yaḍa, watājuⁿ ʿaẓīmuⁿ min̊ dẖahabiⁿ, waḥulãẗuⁿ min̊ baziⁿ̃ wāủr̊jūāniⁿ. wakānat̊ madīnaẗu sẖūsẖana mutahalĩlaẗaⁿ wafariḥaẗaⁿ."],[8,16,"وَكَانَ لِلْيَهُودِ نُورٌ وَفَرَحٌ وَبَهْجَةٌ وَكَرَامَةٌ.","wakāna lil̊yahūdi nūruⁿ wafaraḥuⁿ wabah̊jaẗuⁿ wakarāmaẗuⁿ."],[8,17,"وَفِي كُلِّ بِلَادٍ وَمَدِينَةٍ، كُلِّ مَكَانٍ وَصَلَ إِلَيْهِ كَلَامُ ٱلْمَلِكِ وَأَمْرُهُ، كَانَ فَرَحٌ وَبَهْجَةٌ عِنْدَ ٱلْيَهُودِ وَوَلَائِمُ وَيَوْمٌ طَيِّبٌ. وَكَثِيرُونَ مِنْ شُعُوبِ ٱلْأَرْضِ تَهَوَّدُوا لِأَنَّ رُعْبَ ٱلْيَهُودِ وَقَعَ عَلَيْهِمْ.","wafī kulĩ bilādiⁿ wamadīnaẗiⁿ, kulĩ makāniⁿ waṣala ại̹laẙhi kalāmu ٱl̊maliki wāảm̊ruhu, kāna faraḥuⁿ wabah̊jaẗuⁿ ʿin̊da ٱl̊yahūdi wawalāyỉmu wayaẘmuⁿ ṭayĩbuⁿ. wakatẖīrūna min̊ sẖuʿūbi ٱl̊ạảr̊ḍi tahawãdūạ liạảnã ruʿ̊ba ٱl̊yahūdi waqaʿa ʿalaẙhim̊."],[9,1,"وَفِي ٱلشَّهْرِ ٱلثَّانِي عَشَرَ، أَيْ شَهْرِ أَذَارَ، فِي ٱلْيَوْمِ ٱلثَّالِثَ عَشَرَ مِنْهُ، حِينَ قَرُبَ كَلَامُ ٱلْمَلِكِ وَأَمْرُهُ مِنَ ٱلإِجْرَاءِ، فِي ٱلْيَوْمِ ٱلَّذِي ٱنْتَظَرَ فِيهِ أَعْدَاءُ ٱلْيَهُودِ أَنْ يَتَسَلَّطُوا عَلَيْهِمْ، فَتَحَوَّلَ ذَلِكَ، حَتَّى إِنَّ ٱلْيَهُودَ تَسَلَّطُوا عَلَى مُبْغِضِيهِمِ.","wafī ٱlsẖãh̊ri ٱltẖãạnī ʿasẖara, ạảẙ sẖah̊ri ạảdẖāra, fī ٱl̊yaẘmi ٱltẖãạlitẖa ʿasẖara min̊hu, ḥīna qaruba kalāmu ٱl̊maliki wāảm̊ruhu mina ٱlại̹j̊rāʾi, fī ٱl̊yaẘmi ٱlãdẖī ٱn̊taẓara fīhi ạảʿ̊dāʾu ٱl̊yahūdi ạản̊ yatasalãṭūạ ʿalaẙhim̊, fataḥawãla dẖalika, ḥatãy̱ ại̹nã ٱl̊yahūda tasalãṭūạ ʿalay̱ mub̊gẖiḍīhimi."],[9,2,"ٱجْتَمَعَ ٱلْيَهُودُ فِي مُدُنِهِمْ فِي كُلِّ بِلَادِ ٱلْمَلِكِ أَحَشْوِيرُوشَ لِيَمُدُّوا أَيْدِيَهُمْ إِلَى طَالِبِي أَذِيَّتِهِمْ، فَلَمْ يَقِفْ أَحَدٌ قُدَّامَهُمْ لِأَنَّ رُعْبَهُمْ سَقَطَ عَلَى جَمِيعِ ٱلشُّعُوبِ.","ٱj̊tamaʿa ٱl̊yahūdu fī mudunihim̊ fī kulĩ bilādi ٱl̊maliki ạảḥasẖ̊wīrūsẖa līamudũwạ ạảẙdīahum̊ ại̹lay̱ ṭālibī ạảdẖīãtihim̊, falam̊ yaqif̊ ạảḥaduⁿ qudãạmahum̊ liạảnã ruʿ̊bahum̊ saqaṭa ʿalay̱ jamīʿi ٱlsẖũʿūbi."],[9,3,"وكُلُّ رُؤَسَاءِ ٱلْبُلْدَانِ وَٱلْمَرَازِبَةُ وَٱلْوُلَاةُ وَعُمَّالُ ٱلْمَلِكِ سَاعَدُوا ٱلْيَهُودَ، لِأَنَّ رُعْبَ مُرْدَخَايَ سَقَطَ عَلَيْهِمْ.","wkulũ rūảsāʾi ٱl̊bul̊dāni waٱl̊marāzibaẗu waٱl̊wulāẗu waʿumãạlu ٱl̊maliki sāʿadūạ ٱl̊yahūda, liạảnã ruʿ̊ba mur̊dakẖāya saqaṭa ʿalaẙhim̊."],[9,4,"لِأَنَّ مُرْدَخَايَ كَانَ عَظِيمًا فِي بَيْتِ ٱلْمَلِكِ، وَسَارَ خَبَرُهُ فِي كُلِّ ٱلْبُلْدَانِ، لِأَنَّ ٱلرَّجُلَ مُرْدَخَايَ كَانَ يَتَزَايَدُ عَظَمَةً.","liạảnã mur̊dakẖāya kāna ʿaẓīmaⁿạ fī baẙti ٱl̊maliki, wasāra kẖabaruhu fī kulĩ ٱl̊bul̊dāni, liạảnã ٱlrãjula mur̊dakẖāya kāna yatazāyadu ʿaẓamaẗaⁿ."],[9,5,"فَضَرَبَ ٱلْيَهُودُ جَمِيعَ أَعْدَائِهِمْ ضَرْبَةَ سَيْفٍ وَقَتْلٍ وَهَلَاكٍ، وَعَمِلُوا بِمُبْغِضِيهِمْ مَا أَرَادُوا.","faḍaraba ٱl̊yahūdu jamīʿa ạảʿ̊dāyỉhim̊ ḍar̊baẗa saẙfiⁿ waqat̊liⁿ wahalākiⁿ, waʿamilūạ bimub̊gẖiḍīhim̊ mā ạảrādūạ."],[9,6,"وَقَتَلَ ٱلْيَهُودُ فِي شُوشَنَ ٱلْقَصْرِ وَأَهْلَكُوا خَمْسَ مِئَةِ رَجُلٍ.","waqatala ٱl̊yahūdu fī sẖūsẖana ٱl̊qaṣ̊ri wāảh̊lakūạ kẖam̊sa mīảẗi rajuliⁿ."],[9,7,"وَفَرْشَنْدَاثَا وَدَلْفُونَ وَأَسْفَاثَا،","wafar̊sẖan̊dātẖā wadal̊fūna wāảs̊fātẖā,"],[9,8,"وَفُورَاثَا وَأَدَلْيَا وَأَرِيدَاثَا،","wafūrātẖā wāảdal̊yā wāảrīdātẖā,"],[9,9,"وَفَرْمَشْتَا وَأَرِيسَايَ وَأَرِيدَايَ وَيِزَاثَا،","wafar̊masẖ̊tā wāảrīsāya wāảrīdāya wayizātẖā,"],[9,10,"عَشَرَةَ، بَنِي هَامَانَ بْنِ هَمَدَاثَا عَدُوِّ ٱلْيَهُودِ، قَتَلُوهُمْ وَلَكِنَّهُمْ لَمْ يَمُدُّوا أَيْدِيَهُمْ إِلَى ٱلنَّهْبِ.","ʿasẖaraẗa, banī hāmāna b̊ni hamadātẖā ʿadūĩ ٱl̊yahūdi, qatalūhum̊ walakinãhum̊ lam̊ yamudũwạ ạảẙdīahum̊ ại̹lay̱ ٱlnãh̊bi."],[9,11,"فِي ذَلِكَ ٱلْيَوْمِ أُتِيَ بِعَدَدِ ٱلْقَتْلَى فِي شُوشَنَ ٱلْقَصْرِ إِلَى بَيْنِ يَدَيِ ٱلْمَلِكِ.","fī dẖalika ٱl̊yaẘmi ạủtīa biʿadadi ٱl̊qat̊lay̱ fī sẖūsẖana ٱl̊qaṣ̊ri ại̹lay̱ baẙni yadayi ٱl̊maliki."],[9,12,"فَقَالَ ٱلْمَلِكُ لِأَسْتِيرَ ٱلْمَلِكَةِ فِي شُوشَنَ ٱلْقَصْرِ: «قَدْ قَتَلَ ٱلْيَهُودُ وَأَهْلَكُوا خَمْسَ مِئَةِ رَجُلٍ، وَبَنِي هَامَانَ ٱلْعَشَرَةَ، فَمَاذَا عَمِلُوا فِي بَاقِي بُلْدَانِ ٱلْمَلِكِ؟ فَمَا هُوَ سُؤْلُكِ فَيُعْطَى لَكِ؟ وَمَا هِيَ طِلْبَتُكِ بَعْدُ فَتُقْضَى؟».","faqāla ٱl̊maliku liạảs̊tīra ٱl̊malikaẗi fī sẖūsẖana ٱl̊qaṣ̊ri: «qad̊ qatala ٱl̊yahūdu wāảh̊lakūạ kẖam̊sa mīảẗi rajuliⁿ, wabanī hāmāna ٱl̊ʿasẖaraẗa, famādẖā ʿamilūạ fī bāqī bul̊dāni ٱl̊maliki? famā hūa sū̊̉luki fayuʿ̊ṭay̱ laki? wamā hīa ṭil̊batuki baʿ̊du fatuq̊ḍay̱?»."],[9,13,"فَقَالَتْ أَسْتِيرُ: «إِنْ حَسُنَ عِنْدَ ٱلْمَلِكِ فَلْيُعْطَ غَدًا أَيْضًا لِلْيَهُودِ ٱلَّذِينَ فِي شُوشَنَ أَنْ يَعْمَلُوا كَمَا فِي هَذَا ٱلْيَوْمِ، وَيَصْلِبُوا بَنِي هَامَانَ ٱلْعَشَرَةَ عَلَى ٱلْخَشَبَةِ».","faqālat̊ ạảs̊tīru: «ại̹n̊ ḥasuna ʿin̊da ٱl̊maliki fal̊yuʿ̊ṭa gẖadaⁿạ ạảẙḍaⁿạ lil̊yahūdi ٱlãdẖīna fī sẖūsẖana ạản̊ yaʿ̊malūạ kamā fī hadẖā ٱl̊yaẘmi, wayaṣ̊libūạ banī hāmāna ٱl̊ʿasẖaraẗa ʿalay̱ ٱl̊kẖasẖabaẗi»."],[9,14,"فَأَمَرَ ٱلْمَلِكُ أَنْ يَعْمَلُوا هَكَذَا، وَأُعْطِيَ ٱلْأَمْرُ فِي شُوشَنَ. فَصَلَبُوا بَنِي هَامَانَ ٱلْعَشَرَةَ.","fāảmara ٱl̊maliku ạản̊ yaʿ̊malūạ hakadẖā, wāủʿ̊ṭīa ٱl̊ạảm̊ru fī sẖūsẖana. faṣalabūạ banī hāmāna ٱl̊ʿasẖaraẗa."],[9,15,"ثُمَّ ٱجْتَمَعَ ٱلْيَهُودُ ٱلَّذِينَ فِي شُوشَنَ، فِي ٱلْيَوْمِ ٱلرَّابِعِ عَشَرَ أَيْضًا مِنْ شَهْرِ أَذَارَ، وَقَتَلُوا فِي شُوشَنَ ثَلَاثَ مِئَةِ رَجُلٍ، وَلَكِنَّهُمْ لَمْ يَمُدُّوا أَيْدِيَهُمْ إِلَى ٱلنَّهْبِ.","tẖumã ٱj̊tamaʿa ٱl̊yahūdu ٱlãdẖīna fī sẖūsẖana, fī ٱl̊yaẘmi ٱlrãạbiʿi ʿasẖara ạảẙḍaⁿạ min̊ sẖah̊ri ạảdẖāra, waqatalūạ fī sẖūsẖana tẖalātẖa mīảẗi rajuliⁿ, walakinãhum̊ lam̊ yamudũwạ ạảẙdīahum̊ ại̹lay̱ ٱlnãh̊bi."],[9,16,"وَبَاقِي ٱلْيَهُودِ ٱلَّذِينَ فِي بُلْدَانِ ٱلْمَلِكِ ٱجْتَمَعُوا وَوَقَفُوا لِأَجْلِ أَنْفُسِهِمْ وَٱسْتَرَاحُوا مِنْ أَعْدَائِهِمْ، وَقَتَلُوا مِنْ مُبْغِضِيهِمْ خَمْسَةً وَسَبْعِينَ أَلْفًا، وَلَكِنَّهُمْ لَمْ يَمُدُّوا أَيْدِيَهُمْ إِلَى ٱلنَّهْبِ.","wabāqī ٱl̊yahūdi ٱlãdẖīna fī bul̊dāni ٱl̊maliki ٱj̊tamaʿūạ wawaqafūạ liạảj̊li ạản̊fusihim̊ waٱs̊tarāḥūạ min̊ ạảʿ̊dāyỉhim̊, waqatalūạ min̊ mub̊gẖiḍīhim̊ kẖam̊saẗaⁿ wasab̊ʿīna ạảl̊faⁿạ, walakinãhum̊ lam̊ yamudũwạ ạảẙdīahum̊ ại̹lay̱ ٱlnãh̊bi."],[9,17,"فِي ٱلْيَوْمِ ٱلثَّالِثِ عَشَرَ مِنْ شَهْرِ أَذَارَ. وَٱسْتَرَاحُوا فِي ٱلْيَوْمِ ٱلرَّابِعِ عَشَرَ مِنْهُ وَجَعَلُوهُ يَوْمَ شُرْبٍ وَفَرَحٍ.","fī ٱl̊yaẘmi ٱltẖãạlitẖi ʿasẖara min̊ sẖah̊ri ạảdẖāra. waٱs̊tarāḥūạ fī ٱl̊yaẘmi ٱlrãạbiʿi ʿasẖara min̊hu wajaʿalūhu yaẘma sẖur̊biⁿ wafaraḥiⁿ."],[9,18,"وَٱلْيَهُودُ ٱلَّذِينَ فِي شُوشَنَ ٱجْتَمَعُوا فِي ٱلثَّالِثِ عَشَرَ وَٱلرَّابِعِ عَشَرَ مِنْهُ، وَٱسْتَرَاحُوا فِي ٱلْخَامِسِ عَشَرَ وَجَعَلُوهُ يَوْمَ شُرْبٍ وَفَرَحٍ.","waٱl̊yahūdu ٱlãdẖīna fī sẖūsẖana ٱj̊tamaʿūạ fī ٱltẖãạlitẖi ʿasẖara waٱlrãạbiʿi ʿasẖara min̊hu, waٱs̊tarāḥūạ fī ٱl̊kẖāmisi ʿasẖara wajaʿalūhu yaẘma sẖur̊biⁿ wafaraḥiⁿ."],[9,19,"لِذَلِكَ يَهُودُ ٱلْأَعْرَاءِ ٱلسَّاكِنُونَ فِي مُدُنِ ٱلْأَعْرَاءِ جَعَلُوا ٱلْيَوْمَ ٱلرَّابِعَ عَشَرَ مِنْ شَهْرِ أَذَارَ لِلْفَرَحِ وَٱلشُّرْبِ، وَيَوْمًا طَيِّبًا وَلِإِرْسَالِ أَنْصِبَةٍ مِنْ كُلِّ وَاحِدٍ إِلَى صَاحِبِهِ.","lidẖalika yahūdu ٱl̊ạảʿ̊rāʾi ٱlsãạkinūna fī muduni ٱl̊ạảʿ̊rāʾi jaʿalūạ ٱl̊yaẘma ٱlrãạbiʿa ʿasẖara min̊ sẖah̊ri ạảdẖāra lil̊faraḥi waٱlsẖũr̊bi, wayaẘmaⁿạ ṭayĩbaⁿạ waliại̹r̊sāli ạản̊ṣibaẗiⁿ min̊ kulĩ wāḥidiⁿ ại̹lay̱ ṣāḥibihi."],[9,20,"وَكَتَبَ مُرْدَخَايُ هَذِهِ ٱلْأُمُورَ وَأَرْسَلَ رَسَائِلَ إِلَى جَمِيعِ ٱلْيَهُودِ ٱلَّذِينَ فِي كُلِّ بُلْدَانِ ٱلْمَلِكِ أَحَشْوِيرُوشَ ٱلْقَرِيبِينَ وَٱلْبَعِيدِينَ،","wakataba mur̊dakẖāyu hadẖihi ٱl̊ạủmūra wāảr̊sala rasāyỉla ại̹lay̱ jamīʿi ٱl̊yahūdi ٱlãdẖīna fī kulĩ bul̊dāni ٱl̊maliki ạảḥasẖ̊wīrūsẖa ٱl̊qarībīna waٱl̊baʿīdīna,"],[9,21,"لِيُوجِبَ عَلَيْهِمْ أَنْ يُعَيِّدُوا فِي ٱلْيَوْمِ ٱلرَّابِعِ عَشَرَ مِنْ شَهْرِ أَذَارَ، وَٱلْيَوْمِ ٱلْخَامِسِ عَشَرَ مِنْهُ فِي كُلِّ سَنَةٍ،","līūjiba ʿalaẙhim̊ ạản̊ yuʿayĩdūạ fī ٱl̊yaẘmi ٱlrãạbiʿi ʿasẖara min̊ sẖah̊ri ạảdẖāra, waٱl̊yaẘmi ٱl̊kẖāmisi ʿasẖara min̊hu fī kulĩ sanaẗiⁿ,"],[9,22,"حَسَبَ ٱلْأَيَّامِ ٱلَّتِي ٱسْتَرَاحَ فِيهَا ٱلْيَهُودُ مِنْ أَعْدَائِهِمْ وَٱلشَّهْرِ ٱلَّذِي تَحَوَّلَ عِنْدَهُمْ مِنْ حُزْنٍ إِلَى فَرَحٍ وَمِنْ نَوْحٍ إِلَى يَوْمٍ طَيِّبٍ، لِيَجْعَلُوهَا أَيَّامَ شُرْبٍ وَفَرَحٍ وَإِرْسَالِ أَنْصِبَةٍ مِنْ كُلِّ وَاحِدٍ إِلَى صَاحِبِهِ وَعَطَايَا لِلْفُقَرَاءِ.","ḥasaba ٱl̊ạảyãạmi ٱlãtī ٱs̊tarāḥa fīhā ٱl̊yahūdu min̊ ạảʿ̊dāyỉhim̊ waٱlsẖãh̊ri ٱlãdẖī taḥawãla ʿin̊dahum̊ min̊ ḥuz̊niⁿ ại̹lay̱ faraḥiⁿ wamin̊ naẘḥiⁿ ại̹lay̱ yaẘmiⁿ ṭayĩbiⁿ, līaj̊ʿalūhā ạảyãạma sẖur̊biⁿ wafaraḥiⁿ wāi̹r̊sāli ạản̊ṣibaẗiⁿ min̊ kulĩ wāḥidiⁿ ại̹lay̱ ṣāḥibihi waʿaṭāyā lil̊fuqarāʾi."],[9,23,"فَقَبِلَ ٱلْيَهُودُ مَا ٱبْتَدَأُوا يَعْمَلُونَهُ وَمَا كَتَبَهُ مُرْدَخَايُ إِلَيْهِمْ.","faqabila ٱl̊yahūdu mā ٱb̊tadāủwạ yaʿ̊malūnahu wamā katabahu mur̊dakẖāyu ại̹laẙhim̊."],[9,24,"وَلِأَنَّ هَامَانَ بْنَ هَمَدَاثَا ٱلْأَجَاجِيَّ عَدُوَّ ٱلْيَهُودِ جَمِيعًا تَفَكَّرَ عَلَى ٱلْيَهُودِ لِيُبِيدَهُمْ وَأَلْقَى فُورًا، أَيْ قُرْعَةً، لِإِفْنَائِهِمْ وَإِبَادَتِهِمْ.","waliạảnã hāmāna b̊na hamadātẖā ٱl̊ạảjājīã ʿadūã ٱl̊yahūdi jamīʿaⁿạ tafakãra ʿalay̱ ٱl̊yahūdi līubīdahum̊ wāảl̊qay̱ fūraⁿạ, ạảẙ qur̊ʿaẗaⁿ, liại̹f̊nāyỉhim̊ wāi̹bādatihim̊."],[9,25,"وَعِنْدَ دُخُولِهَا إِلَى أَمَامِ ٱلْمَلِكِ أَمَرَ بِكِتَابَةٍ أَنْ يُرَدَّ تَدْبِيرُهُ ٱلرَّدِيءُ ٱلَّذِي دَبَّرَهُ ضِدَّ ٱلْيَهُودِ عَلَى رَأْسِهِ، وَأَنْ يَصْلِبُوهُ هُوَ وَبَنِيهِ عَلَى ٱلْخَشَبَةِ.","waʿin̊da dukẖūlihā ại̹lay̱ ạảmāmi ٱl̊maliki ạảmara bikitābaẗiⁿ ạản̊ yuradã tad̊bīruhu ٱlrãdīʾu ٱlãdẖī dabãrahu ḍidã ٱl̊yahūdi ʿalay̱ rā̊̉sihi, wāản̊ yaṣ̊libūhu hūa wabanīhi ʿalay̱ ٱl̊kẖasẖabaẗi."],[9,26,"لِذَلِكَ دَعُوا تِلْكَ ٱلْأَيَّامِ «فُورِيمَ» عَلَى ٱسْمِ ٱلْفُورِ. لِذَلِكَ مِنْ أَجْلِ جَمِيعِ كَلِمَاتِ هَذِهِ ٱلرِّسَالَةِ وَمَا رَأَوْهُ مِنْ ذَلِكَ وَمَا أَصَابَهُمْ،","lidẖalika daʿūạ til̊ka ٱl̊ạảyãạmi «fūrīma» ʿalay̱ ٱs̊mi ٱl̊fūri. lidẖalika min̊ ạảj̊li jamīʿi kalimāti hadẖihi ٱlrĩsālaẗi wamā rāảẘhu min̊ dẖalika wamā ạảṣābahum̊,"],[9,27,"أَوْجَبَ ٱلْيَهُودُ وَقَبِلُوا عَلَى أَنْفُسِهِمْ وَعَلَى نَسْلِهِمْ وَعَلَى جَمِيعِ ٱلَّذِينَ يَلْتَصِقُونَ بِهِمْ حَتَّى لَا يَزُولَ، أَنْ يُعَيِّدُوا هَذَيْنِ ٱلْيَوْمَيْنِ حَسَبَ كِتَابَتِهِمَا وَحَسَبَ أَوْقَاتِهِمَا كُلَّ سَنَةٍ،","ạảẘjaba ٱl̊yahūdu waqabilūạ ʿalay̱ ạản̊fusihim̊ waʿalay̱ nas̊lihim̊ waʿalay̱ jamīʿi ٱlãdẖīna yal̊taṣiqūna bihim̊ ḥatãy̱ lā yazūla, ạản̊ yuʿayĩdūạ hadẖaẙni ٱl̊yaẘmaẙni ḥasaba kitābatihimā waḥasaba ạảẘqātihimā kulã sanaẗiⁿ,"],[9,28,"وَأَنْ يُذْكَرَ هَذَانِ ٱلْيَوْمَانِ وَيُحْفَظَا فِي دَوْرٍ فَدَوْرٍ وَعَشِيرَةٍ فَعَشِيرَةٍ وَبِلَادٍ فَبِلَادٍ وَمَدِينَةٍ فَمَدِينَةٍ. وَيَوْمَا ٱلْفُورِ هَذَانِ لَا يَزُولَانِ مِنْ وَسَطِ ٱلْيَهُودِ، وَذِكْرُهُمَا لَا يَفْنَى مِنْ نَسْلِهِمْ.","wāản̊ yudẖ̊kara hadẖāni ٱl̊yaẘmāni wayuḥ̊faẓā fī daẘriⁿ fadaẘriⁿ waʿasẖīraẗiⁿ faʿasẖīraẗiⁿ wabilādiⁿ fabilādiⁿ wamadīnaẗiⁿ famadīnaẗiⁿ. wayaẘmā ٱl̊fūri hadẖāni lā yazūlāni min̊ wasaṭi ٱl̊yahūdi, wadẖik̊ruhumā lā yaf̊nay̱ min̊ nas̊lihim̊."],[9,29,"وَكَتَبَتْ أَسْتِيرُ ٱلْمَلِكَةُ بِنْتُ أَبِيحَائِلَ وَمُرْدَخَايُ ٱلْيَهُودِيُّ بِكُلِّ سُلْطَانٍ بِإِيجَابِ رِسَالَةِ ٱلْفُورِيمِ هَذِهِ ثَانِيَةً،","wakatabat̊ ạảs̊tīru ٱl̊malikaẗu bin̊tu ạảbīḥāyỉla wamur̊dakẖāyu ٱl̊yahūdīũ bikulĩ sul̊ṭāniⁿ biại̹yjābi risālaẗi ٱl̊fūrīmi hadẖihi tẖānīaẗaⁿ,"],[9,30,"وَأَرْسَلَ ٱلْكِتَابَاتِ إِلَى جَمِيعِ ٱلْيَهُودِ، إِلَى كُوَرِ مَمْلَكَةِ أَحَشْوِيرُوشَ ٱلْمِئَةِ وَٱلسَّبْعِ وَٱلْعِشْرِينَ بِكَلَامِ سَلَامٍ وَأَمَانَةٍ،","wāảr̊sala ٱl̊kitābāti ại̹lay̱ jamīʿi ٱl̊yahūdi, ại̹lay̱ kūari mam̊lakaẗi ạảḥasẖ̊wīrūsẖa ٱl̊mīảẗi waٱlsãb̊ʿi waٱl̊ʿisẖ̊rīna bikalāmi salāmiⁿ wāảmānaẗiⁿ,"],[9,31,"لِإِيجَابِ يَوْمَيِ ٱلْفُورِيمِ هَذَيْنِ فِي أَوْقَاتِهِمَا، كَمَا أَوْجَبَ عَلَيْهِمْ مُرْدَخَايُ ٱلْيَهُودِيُّ وَأَسْتِيرُ ٱلْمَلِكَةُ، وَكَمَا أَوْجَبُوا عَلَى أَنْفُسِهِمْ وَعَلَى نَسْلِهِمْ أُمُورَ ٱلْأَصْوَامِ وَصُرَاخِهِمْ.","liại̹yjābi yaẘmayi ٱl̊fūrīmi hadẖaẙni fī ạảẘqātihimā, kamā ạảẘjaba ʿalaẙhim̊ mur̊dakẖāyu ٱl̊yahūdīũ wāảs̊tīru ٱl̊malikaẗu, wakamā ạảẘjabūạ ʿalay̱ ạản̊fusihim̊ waʿalay̱ nas̊lihim̊ ạủmūra ٱl̊ạảṣ̊wāmi waṣurākẖihim̊."],[9,32,"وَأَمْرُ أَسْتِيرَ أَوْجَبَ أُمُورَ ٱلْفُورِيمِ هَذِهِ، فَكُتِبَتْ فِي ٱلسِّفْرِ.","wāảm̊ru ạảs̊tīra ạảẘjaba ạủmūra ٱl̊fūrīmi hadẖihi, fakutibat̊ fī ٱlsĩf̊ri."],[10,1,"وَوَضَعَ ٱلْمَلِكُ أَحَشْوِيرُوشُ جِزْيَةً عَلَى ٱلْأَرْضِ وَجَزَائِرِ ٱلْبَحْرِ.","wawaḍaʿa ٱl̊maliku ạảḥasẖ̊wīrūsẖu jiz̊yaẗaⁿ ʿalay̱ ٱl̊ạảr̊ḍi wajazāyỉri ٱl̊baḥ̊ri."],[10,2,"وَكُلُّ عَمَلِ سُلْطَانِهِ وَجَبَرُوتِهِ وَإِذَاعَةُ عَظَمَةِ مُرْدَخَايَ ٱلَّذِي عَظَّمَهُ ٱلْمَلِكُ، أَمَا هِيَ مَكْتُوبَةٌ فِي سِفْرِ أَخْبَارِ ٱلْأَيَّامِ لِمُلُوكِ مَادِي وَفَارِسَ؟","wakulũ ʿamali sul̊ṭānihi wajabarūtihi wāi̹dẖāʿaẗu ʿaẓamaẗi mur̊dakẖāya ٱlãdẖī ʿaẓãmahu ٱl̊maliku, ạảmā hīa mak̊tūbaẗuⁿ fī sif̊ri ạảkẖ̊bāri ٱl̊ạảyãạmi limulūki mādī wafārisa?"],[10,3,"لِأَنَّ مُرْدَخَايَ ٱلْيَهُودِيَّ كَانَ ثَانِيَ ٱلْمَلِكِ أَحَشْوِيرُوشَ، وَعَظِيمًا بَيْنَ ٱلْيَهُودِ، وَمَقْبُولًا عِنْدَ كَثْرَةِ إِخْوَتِهِ، طَالِبًا ٱلْخَيْرَ لِشَعْبِهِ وَمُتَكَلِّمًا بِٱلسَّلَامِ لِكُلِّ نَسْلِهِ.","liạảnã mur̊dakẖāya ٱl̊yahūdīã kāna tẖānīa ٱl̊maliki ạảḥasẖ̊wīrūsẖa, waʿaẓīmaⁿạ baẙna ٱl̊yahūdi, wamaq̊būlaⁿạ ʿin̊da katẖ̊raẗi ại̹kẖ̊watihi, ṭālibaⁿạ ٱl̊kẖaẙra lisẖaʿ̊bihi wamutakalĩmaⁿạ biٱlsãlāmi likulĩ nas̊lihi."]],"bis-obbr":[[1,1,"Bifo, i gat wan king* i stap long kantri ya Pesia, we nem blong hem, King Sekses. Hem i stap rul long plante kantri, i stat long kantri ya India long is, i go kasem kantri ya Itiopia long wes. Hedkwota blong hem i stap long taon ya Susa we i kaptel blong Pesia, mo i gat wan handred twanti seven provins blong hem we hem i stap rul long olgeta.","Bifo, i gat wan king* i stap long kantri ya Pesia, we nem blong hem, King Sekses. Hem i stap rul long plante kantri, i stat long kantri ya India long is, i go kasem kantri ya Itiopia long wes. Hedkwota blong hem i stap long taon ya Susa we i kaptel blong Pesia, mo i gat wan handred twanti seven provins blong hem we hem i stap rul long olgeta.",2],[1,3,"Nao long namba tri yia blong hem we i stap rul, hem i mekem wan bigfala lafet blong olgeta minista blong hem wetem ol narafala haeman blong hem. Nao ol distrikejen* blong hem wetem ol haeman blong ol provins blong hem, mo ol soldia blong tufala kantri ya Pesia mo Media, olgeta evriwan oli kam long lafet ya.","Nao long namba tri yia blong hem we i stap rul, hem i mekem wan bigfala lafet blong olgeta minista blong hem wetem ol narafala haeman blong hem. Nao ol distrikejen* blong hem wetem ol haeman blong ol provins blong hem, mo ol soldia blong tufala kantri ya Pesia mo Media, olgeta evriwan oli kam long lafet ya."],[1,4,"Nao lafet ya i stap gohed gogo kasem sikis manis, mo long taem ya hem i stap soemaot ol gudgudfala samting blong ol kantri ya we hem i stap rul long hem, mo ol flas samting long haos blong hem, blong ol man ya oli luk.","Nao lafet ya i stap gohed gogo kasem sikis manis, mo long taem ya hem i stap soemaot ol gudgudfala samting blong ol kantri ya we hem i stap rul long hem, mo ol flas samting long haos blong hem, blong ol man ya oli luk."],[1,5,"Nao long en blong sikis manis ya, hem i mekem wan narafala lafet bakegen we olgeta man we oli stap long taon ya Susa oli kam long hem, ol haeman wetem ol man olbaot, olgeta evriwan oli kam. Hem i mekem lafet ya long yad afsaed long haos blong hem, we bigfala stonwol i goraon long hem, mo lafet ya i stap gohed gogo kasem wan fulwik.","Nao long en blong sikis manis ya, hem i mekem wan narafala lafet bakegen we olgeta man we oli stap long taon ya Susa oli kam long hem, ol haeman wetem ol man olbaot, olgeta evriwan oli kam. Hem i mekem lafet ya long yad afsaed long haos blong hem, we bigfala stonwol i goraon long hem, mo lafet ya i stap gohed gogo kasem wan fulwik."],[1,6,"Yad ya, oli flasem long ol kaliko we i blu mo ol kaliko we i waet. Oli tekem ol ring we oli wokem long silva, oli somap long ol kaliko ya long gudfala tred we i pepol, nao oli hangem long ol rop we oli fasem long ol bigfala pos we oli wokem long flas ston ya mabol.* Mo ol longfala jea ya we oli wokem long silva mo gol, we oli stap insaed long haos, oli tekem i kam, oli putum olgeta tu insaed long yad ya. Floa blong yad ya, oli wokem long ol flas ston, sam we i waet, mo sam we i red, mo sam we i blu, mo sam we i gat ol naranarafala kala mo oli saen gud.","Yad ya, oli flasem long ol kaliko we i blu mo ol kaliko we i waet. Oli tekem ol ring we oli wokem long silva, oli somap long ol kaliko ya long gudfala tred we i pepol, nao oli hangem long ol rop we oli fasem long ol bigfala pos we oli wokem long flas ston ya mabol.* Mo ol longfala jea ya we oli wokem long silva mo gol, we oli stap insaed long haos, oli tekem i kam, oli putum olgeta tu insaed long yad ya. Floa blong yad ya, oli wokem long ol flas ston, sam we i waet, mo sam we i red, mo sam we i blu, mo sam we i gat ol naranarafala kala mo oli saen gud."],[1,7,"Mo ol pankin we ol man oli yusum blong dring waen long hem, oli wokem long gol, mo olgeta evriwan oli naranarafala. Mo long taem ya, king i glad nomo blong givim plante waen long ol man we i no blong tingbaot.","Mo ol pankin we ol man oli yusum blong dring waen long hem, oli wokem long gol, mo olgeta evriwan oli naranarafala. Mo long taem ya, king i glad nomo blong givim plante waen long ol man we i no blong tingbaot."],[1,8,"Hem i talem long ol man blong wok blong hem, se i fri long olgeta man blong oli dring olsem we oli wantem.","Hem i talem long ol man blong wok blong hem, se i fri long olgeta man blong oli dring olsem we oli wantem."],[1,9,"Nao long taem ya, Kwin Vasti we i woman blong king ya, hem tu i stap mekem wan lafet blong ol woman, long haos blong king.","Nao long taem ya, Kwin Vasti we i woman blong king ya, hem tu i stap mekem wan lafet blong ol woman, long haos blong king."],[1,10,"Nao long namba seven dei blong lafet ya blong king, king ya i dring we i stap glad tumas, nao i singaot seven man blong wok blong hem oli kam we oli stap wok insaed long haos blong kwin. Nem blong olgeta ya, Mehuman, mo Bistaha, mo Habona, mo Bigtaha, mo Abagtaha, mo Setara, mo Kakas.","Nao long namba seven dei blong lafet ya blong king, king ya i dring we i stap glad tumas, nao i singaot seven man blong wok blong hem oli kam we oli stap wok insaed long haos blong kwin. Nem blong olgeta ya, Mehuman, mo Bistaha, mo Habona, mo Bigtaha, mo Abagtaha, mo Setara, mo Kakas."],[1,11,"Nao king i sanem olgeta blong oli go talem long woman ya blong hem blong i putum spesel hat blong hem, mo i kam stanap long saed blong hem, from we hem i wantem blong ol haeman blong hem wetem ol man ya we oli stap long lafet ya oli luk hem, from we hem i naes tumas.","Nao king i sanem olgeta blong oli go talem long woman ya blong hem blong i putum spesel hat blong hem, mo i kam stanap long saed blong hem, from we hem i wantem blong ol haeman blong hem wetem ol man ya we oli stap long lafet ya oli luk hem, from we hem i naes tumas."],[1,12,"Mo taem ol man ya oli go talem long hem, se king i wantem luk hem, be hem i no wantem kam. Nao samting ya i mekem king i kros we i kros tumas.","Mo taem ol man ya oli go talem long hem, se king i wantem luk hem, be hem i no wantem kam. Nao samting ya i mekem king i kros we i kros tumas."],[1,13,"Nao fasin blong king ya, taem we hem i gat problem long saed blong loa, oltaem hem i stap singaot ol advaesa blong hem we oli savegud ol bisnes blong loa, blong oli kam givhan long hem. Nao long olgeta ya i gat seven advaesa blong hem we oli haeman blong Pesia mo Media we oli hae moa long ol narafala haeman long kingdom blong hem, mo oltaem nomo hem i stap lukluk long olgeta blong oli givhan long hem. Nem blong olgeta ya, Kasnaha, mo Setara, mo Admata, mo Tasis, mo Meres, mo Masenaha, mo Memukan. Nao hem i singaot olgeta ya oli kam luk hem.","Nao fasin blong king ya, taem we hem i gat problem long saed blong loa, oltaem hem i stap singaot ol advaesa blong hem we oli savegud ol bisnes blong loa, blong oli kam givhan long hem. Nao long olgeta ya i gat seven advaesa blong hem we oli haeman blong Pesia mo Media we oli hae moa long ol narafala haeman long kingdom blong hem, mo oltaem nomo hem i stap lukluk long olgeta blong oli givhan long hem. Nem blong olgeta ya, Kasnaha, mo Setara, mo Admata, mo Tasis, mo Meres, mo Masenaha, mo Memukan. Nao hem i singaot olgeta ya oli kam luk hem.",14],[1,15,"Nao hem i talem long olgeta se, “Olgeta. !Mi mi king, be yufala i luk! !Woman blong mi i no obei long mi! Mi sanem ol man blong mi oli go blong tekem hem i kam luk mi, be hem i no wantem. ?Olsem wanem nao? ?Loa i talem olsem wanem? ?Bambae yumi mekem wanem long hem?”","Nao hem i talem long olgeta se, “Olgeta. !Mi mi king, be yufala i luk! !Woman blong mi i no obei long mi! Mi sanem ol man blong mi oli go blong tekem hem i kam luk mi, be hem i no wantem. ?Olsem wanem nao? ?Loa i talem olsem wanem? ?Bambae yumi mekem wanem long hem?”"],[1,16,"Nao Memukan i girap, i talem long hem wetem ol narafala haeman blong hem se, “King. Woman ya blong yu i mekem bigfala sem long yu. Be i no long yu nomo, hem i spolem ol haeman blong yu tu, wetem olgeta man long ol kantri ya we yu yu stap rul long hem.","Nao Memukan i girap, i talem long hem wetem ol narafala haeman blong hem se, “King. Woman ya blong yu i mekem bigfala sem long yu. Be i no long yu nomo, hem i spolem ol haeman blong yu tu, wetem olgeta man long ol kantri ya we yu yu stap rul long hem."],[1,17,"Sipos ol woman olbaot long ol ples ya oli harem nius blong samting ya we hem i mekem, bambae oli no moa save ona long ol man blong olgeta. Bambae oli stap talem se, ‘!Yu luk! !King Sekses i talem long Kwin Vasti blong hem i go luk hem, be hem i no wantem!’","Sipos ol woman olbaot long ol ples ya oli harem nius blong samting ya we hem i mekem, bambae oli no moa save ona long ol man blong olgeta. Bambae oli stap talem se, ‘!Yu luk! !King Sekses i talem long Kwin Vasti blong hem i go luk hem, be hem i no wantem!’"],[1,18,"Sipos ol woman blong ol haeman blong yu long Pesia mo Media oli harem samting ya, bambae oli stap mekem sem samting long ol man blong olgeta, nao bambae oli gat big trabol. Bambae ol woman long evri ples oli no moa save ona long ol man blong olgeta, mo ol man blong olgeta bambae oli stap kros long olgeta oltaem.","Sipos ol woman blong ol haeman blong yu long Pesia mo Media oli harem samting ya, bambae oli stap mekem sem samting long ol man blong olgeta, nao bambae oli gat big trabol. Bambae ol woman long evri ples oli no moa save ona long ol man blong olgeta, mo ol man blong olgeta bambae oli stap kros long olgeta oltaem."],[1,19,"King, long tingting blong mi, mi ting se i moa gud yu mekem wan niufala loa, yu talemaot we bambae yu no moa wantem luk fes blong woman ya bakegen samtaem. Mo i gud yu raetemdaon loa ya i stap wetem ol narafala loa blong Pesia mo Media, blong bambae ol man oli no save jenisim bakegen samtaem. Nao bambae yu putumap wan narafala woman we i moa gud long hem i tekem ples blong hem i kam kwin.","King, long tingting blong mi, mi ting se i moa gud yu mekem wan niufala loa, yu talemaot we bambae yu no moa wantem luk fes blong woman ya bakegen samtaem. Mo i gud yu raetemdaon loa ya i stap wetem ol narafala loa blong Pesia mo Media, blong bambae ol man oli no save jenisim bakegen samtaem. Nao bambae yu putumap wan narafala woman we i moa gud long hem i tekem ples blong hem i kam kwin."],[1,20,"Ol kantri we yu yu stap rul long hem oli plante we plante, mo sipos ol woman blong olgeta oli harem niufala loa ya blong yu, bambae oli save tinghevi long ol man blong olgeta. Nating we oli haeman no oli man olbaot, be ol woman blong olgeta bambae oli save ona gud long olgeta.”","Ol kantri we yu yu stap rul long hem oli plante we plante, mo sipos ol woman blong olgeta oli harem niufala loa ya blong yu, bambae oli save tinghevi long ol man blong olgeta. Nating we oli haeman no oli man olbaot, be ol woman blong olgeta bambae oli save ona gud long olgeta.”"],[1,21,"Nao king wetem ol haeman blong hem oli glad tumas long tingting ya, mo king i mekem olsem we Memukan i talem.","Nao king wetem ol haeman blong hem oli glad tumas long tingting ya, mo king i mekem olsem we Memukan i talem."],[1,22,"Hem i singaot ol sekretari blong hem oli kam, nao i talemaot toktok blong hem long olgeta, se man i mas bos long haos blong hem, mo taem hem i tok long woman blong hem, woman blong hem i mas harem hem. Nao olgeta oli tanem tok ya i go long ol lanwis blong ol provins blong hem, mo oli raetem long ol fasin blong raet blong olgeta wanwan, mo oli sanem i go long ol provins ya.","Hem i singaot ol sekretari blong hem oli kam, nao i talemaot toktok blong hem long olgeta, se man i mas bos long haos blong hem, mo taem hem i tok long woman blong hem, woman blong hem i mas harem hem. Nao olgeta oli tanem tok ya i go long ol lanwis blong ol provins blong hem, mo oli raetem long ol fasin blong raet blong olgeta wanwan, mo oli sanem i go long ol provins ya."],[2,1,"Nao biaen, longtaem lelebet, taem King Sekses i no moa kros, hem i tingbaot samting ya bakegen we Kwin Vasti i bin mekem long hem, mo niufala loa ya blong hem we i bin talemaot agens long hem.","Nao biaen, longtaem lelebet, taem King Sekses i no moa kros, hem i tingbaot samting ya bakegen we Kwin Vasti i bin mekem long hem, mo niufala loa ya blong hem we i bin talemaot agens long hem."],[2,2,"Nao from samting ya, sam long ol advaesa blong hem we oli stap klosap long hem oltaem, oli kam talem long hem se, “King. I gud yu sanem ol man blong yu oli go lukaot sam yang gel we oli naes, mo we oli no save man yet.","Nao from samting ya, sam long ol advaesa blong hem we oli stap klosap long hem oltaem, oli kam talem long hem se, “King. I gud yu sanem ol man blong yu oli go lukaot sam yang gel we oli naes, mo we oli no save man yet."],[2,3,"Yu save putumap sam haeman long evri provins, long olgeta kantri we yu yu stap rul long hem, nao yu save talem long olgeta blong oli faenem ol yang gel olsem, oli tekem olgeta i kam long taon ya Susa, blong oli kam stap long haos, blong oli kam woman blong yu. Nao bambae yu putum olgeta long han blong Hegae, man ya blong wok blong yu we i stap lukaot long ol narafala gel ya long haos blong yu. Hem bambae i stap lukaot long olgeta, mo bambae i stap givim ol gudfala oel long olgeta we i blong ravem long bodi blong olgeta blong mekem olgeta oli naes moa.","Yu save putumap sam haeman long evri provins, long olgeta kantri we yu yu stap rul long hem, nao yu save talem long olgeta blong oli faenem ol yang gel olsem, oli tekem olgeta i kam long taon ya Susa, blong oli kam stap long haos, blong oli kam woman blong yu. Nao bambae yu putum olgeta long han blong Hegae, man ya blong wok blong yu we i stap lukaot long ol narafala gel ya long haos blong yu. Hem bambae i stap lukaot long olgeta, mo bambae i stap givim ol gudfala oel long olgeta we i blong ravem long bodi blong olgeta blong mekem olgeta oli naes moa."],[2,4,"Nao biaen, sipos yu luk wan long olgeta we yu laekem hem tumas, bambae yu save putumap hem i kam kwin, blong tekem ples blong Kwin Vasti.” Nao king i harem se tok ya i gud tumas, mo hem i mekem olsem.","Nao biaen, sipos yu luk wan long olgeta we yu laekem hem tumas, bambae yu save putumap hem i kam kwin, blong tekem ples blong Kwin Vasti.” Nao king i harem se tok ya i gud tumas, mo hem i mekem olsem."],[2,5,"Nao i gat wan laen blong Isrel long taon ya Susa, we nem blong hem Modekae. Hem i pikinini blong Jaere, we i kamaot biaen long Simei, we hem i kamaot biaen long Kis we i wan laen blong Benjamin bifo.","Nao i gat wan laen blong Isrel long taon ya Susa, we nem blong hem Modekae. Hem i pikinini blong Jaere, we i kamaot biaen long Simei, we hem i kamaot biaen long Kis we i wan laen blong Benjamin bifo."],[2,6,"Fastaem, taem we King Nebukadnesa blong Babilon i kam mekem faet long King Jehoeakin blong Juda long Jerusalem, nao i winim hem, mo i tekem hem wetem ol man blong hem oli go wok slef* long ples blong hem, be wan olfala blong Modekae ya i wan long olgeta.","Fastaem, taem we King Nebukadnesa blong Babilon i kam mekem faet long King Jehoeakin blong Juda long Jerusalem, nao i winim hem, mo i tekem hem wetem ol man blong hem oli go wok slef* long ples blong hem, be wan olfala blong Modekae ya i wan long olgeta."],[2,7,"Nao Modekae i gat wan sista blong hem we nem blong hem Esta, we long lanwis blong ol laen blong Isrel, nem blong hem Hadasa. Mo hem i wan gudfala gel we i naes we i naes. Mo taem papa mo mama blong gel ya tufala i ded, Modekae i adoptem hem.","Nao Modekae i gat wan sista blong hem we nem blong hem Esta, we long lanwis blong ol laen blong Isrel, nem blong hem Hadasa. Mo hem i wan gudfala gel we i naes we i naes. Mo taem papa mo mama blong gel ya tufala i ded, Modekae i adoptem hem."],[2,8,"Nao ol man blong king oli talemaot tok ya blong hem olbaot long olgeta kantri we hem i stap rul long hem, nao oli stap tekem plante gel i kam long taon ya Susa, oli putum olgeta long ples blong king. Mo oli tekem Esta tu i go wetem olgeta. Long ples ya, man ya Hegae we i stap lukaot long haos blong ol gel, hem i stap lukaot long olgeta.","Nao ol man blong king oli talemaot tok ya blong hem olbaot long olgeta kantri we hem i stap rul long hem, nao oli stap tekem plante gel i kam long taon ya Susa, oli putum olgeta long ples blong king. Mo oli tekem Esta tu i go wetem olgeta. Long ples ya, man ya Hegae we i stap lukaot long haos blong ol gel, hem i stap lukaot long olgeta."],[2,9,"Nao man ya i laekem Esta tumas, we olgeta tingting blong hem i stap long hem. Mo kwiktaem nomo, hem i tekem ol gudfala oel i kam, i givim long hem blong i stap ravem long bodi blong hem, mo i stap givim ol spesel kakae long hem. Nao i putum hem long wan nambawan rum insaed long haos ya blong ol gel, mo i jusumaot seven gel long haos blong king, blong oli stap wok blong hem.","Nao man ya i laekem Esta tumas, we olgeta tingting blong hem i stap long hem. Mo kwiktaem nomo, hem i tekem ol gudfala oel i kam, i givim long hem blong i stap ravem long bodi blong hem, mo i stap givim ol spesel kakae long hem. Nao i putum hem long wan nambawan rum insaed long haos ya blong ol gel, mo i jusumaot seven gel long haos blong king, blong oli stap wok blong hem."],[2,10,"Nao Esta i no talemaot we hem i wan laen blong Isrel, from we Modekae i toktok long hem finis blong i no talemaot.","Nao Esta i no talemaot we hem i wan laen blong Isrel, from we Modekae i toktok long hem finis blong i no talemaot."],[2,11,"Be evri dei nomo, Modekae i stap wokbaot i go i kam long fran blong yad blong haos ya, blong luk se Esta i stap gud no olsem wanem, mo blong faenemaot ol samting we i stap hapen long hem.","Be evri dei nomo, Modekae i stap wokbaot i go i kam long fran blong yad blong haos ya, blong luk se Esta i stap gud no olsem wanem, mo blong faenemaot ol samting we i stap hapen long hem."],[2,12,"Nao long wan fulyia, ol gel ya oli stap gohed blong wokem ol fasin ya blong mekem bodi blong olgeta i naes. Long sikis manis, oli stap putum oel we oli miksimap wetem gudfala senta ya mir,* mo long sikis manis bakegen, oli stap putum oel we oli miksimap wetem gudfala senta ya balsam.* Nao biaen, man ya i stap tekem ol gel ya wanwan oli go stap wetem king.","Nao long wan fulyia, ol gel ya oli stap gohed blong wokem ol fasin ya blong mekem bodi blong olgeta i naes. Long sikis manis, oli stap putum oel we oli miksimap wetem gudfala senta ya mir,* mo long sikis manis bakegen, oli stap putum oel we oli miksimap wetem gudfala senta ya balsam.* Nao biaen, man ya i stap tekem ol gel ya wanwan oli go stap wetem king."],[2,13,"Taem wan gel i rere blong i aot long haos blong olgeta blong go stap wetem king, hem i save werem ol nambawan klos we hem i luk se i gud.","Taem wan gel i rere blong i aot long haos blong olgeta blong go stap wetem king, hem i save werem ol nambawan klos we hem i luk se i gud."],[2,14,"Nao hem i go stap wetem king long naet, mo long moning, oli tekem hem i go stap wetem ol narafala woman blong king long haos ya blong olgeta, we man ya Sahasgas i stap lukaot long hem. Sahasgas ya, hem i wan man blong wok blong king, we i stap lukaot long ol narafala woman ya blong king. Nao biaen, gel ya i no moa save go luk king bakegen. Be sipos king i laekem gel ya tumas, hem i save talem nem blong hem, nao oli save tekem hem i kam luk hem bakegen.","Nao hem i go stap wetem king long naet, mo long moning, oli tekem hem i go stap wetem ol narafala woman blong king long haos ya blong olgeta, we man ya Sahasgas i stap lukaot long hem. Sahasgas ya, hem i wan man blong wok blong king, we i stap lukaot long ol narafala woman ya blong king. Nao biaen, gel ya i no moa save go luk king bakegen. Be sipos king i laekem gel ya tumas, hem i save talem nem blong hem, nao oli save tekem hem i kam luk hem bakegen."],[2,15,"Nao long namba seven yia we King Sekses i stap rul, long manis ya Tebet* we i namba ten manis long kalenda blong olgeta, i taem blong oli tekem gel ya Esta blong i go stap wetem king. Gel ya i naes we i naes, ol man we oli luk hem oli laekem hem tumas. Nao long taem ya, hem i putum ol klos ya nomo we Hegae, man ya we i stap lukaot long haos blong ol gel i talem long hem blong i putum. Nao hem i go luk king, mo taem king i luk hem, hem i laekem hem tumas, we olgeta tingting blong hem i go long hem nomo, i winim ol narafala gel ya. Nao hem i putum hat blong kwin long hed blong hem, mo i putumap hem i kam kwin, i tekem ples blong Kwin Vasti. Nao long taem ya, king i mekem wan bigfala lafet blong ona long woman ya blong hem, Kwin Esta, mo hem i singaot ol minista blong hem wetem ol narafala haeman blong hem oli kam long lafet ya. Mo long taem ya, hem i stap givimaot ol gudgudfala presen i go long ol man, olsem we i stret blong king i givim, mo i talemaot se ol man blong olgeta kantri ya we hem i stap rul long hem, bambae oli gat holede. Esta ya, hem i dota blong wan olfala, we nem blong hem Abihael, we i lus finis, nao Modekae we i wan pikinini blong Abihael ya hem i adoptem hem.","Nao long namba seven yia we King Sekses i stap rul, long manis ya Tebet* we i namba ten manis long kalenda blong olgeta, i taem blong oli tekem gel ya Esta blong i go stap wetem king. Gel ya i naes we i naes, ol man we oli luk hem oli laekem hem tumas. Nao long taem ya, hem i putum ol klos ya nomo we Hegae, man ya we i stap lukaot long haos blong ol gel i talem long hem blong i putum. Nao hem i go luk king, mo taem king i luk hem, hem i laekem hem tumas, we olgeta tingting blong hem i go long hem nomo, i winim ol narafala gel ya. Nao hem i putum hat blong kwin long hed blong hem, mo i putumap hem i kam kwin, i tekem ples blong Kwin Vasti. Nao long taem ya, king i mekem wan bigfala lafet blong ona long woman ya blong hem, Kwin Esta, mo hem i singaot ol minista blong hem wetem ol narafala haeman blong hem oli kam long lafet ya. Mo long taem ya, hem i stap givimaot ol gudgudfala presen i go long ol man, olsem we i stret blong king i givim, mo i talemaot se ol man blong olgeta kantri ya we hem i stap rul long hem, bambae oli gat holede. Esta ya, hem i dota blong wan olfala, we nem blong hem Abihael, we i lus finis, nao Modekae we i wan pikinini blong Abihael ya hem i adoptem hem.",18],[2,19,"Nao long seken taem we oli tekem ol gel ya oli kam wanples bakegen, king ya i putumap Modekae i kam wan minista blong hem, we i gat ofis blong hem long doa* blong bigfala stonwol blong yad blong haos blong king.","Nao long seken taem we oli tekem ol gel ya oli kam wanples bakegen, king ya i putumap Modekae i kam wan minista blong hem, we i gat ofis blong hem long doa* blong bigfala stonwol blong yad blong haos blong king."],[2,20,"Be Esta i no talemaot nating we hem i wan laen* blong Isrel,* from we i stap holem tok ya blong Modekae yet, we i talem se bambae hem i no talemaot long wan man. Hem i stap obei long Modekae stret olsem we i stap obei long hem bifo, long taem ya we hem i smol gel yet, mo i stap long han blong hem.","Be Esta i no talemaot nating we hem i wan laen* blong Isrel,* from we i stap holem tok ya blong Modekae yet, we i talem se bambae hem i no talemaot long wan man. Hem i stap obei long Modekae stret olsem we i stap obei long hem bifo, long taem ya we hem i smol gel yet, mo i stap long han blong hem."],[2,21,"Long taem ya we Modekae i stap wok long ofis blong hem, i gat tu man blong wok blong king i stap we nem blong tufala, Bigtana mo Teres. Tufala i stap gad long doa blong haos blong king, be tufala i kros long king, nao tufala i stap mekem plan blong kilim hem i ded.","Long taem ya we Modekae i stap wok long ofis blong hem, i gat tu man blong wok blong king i stap we nem blong tufala, Bigtana mo Teres. Tufala i stap gad long doa blong haos blong king, be tufala i kros long king, nao tufala i stap mekem plan blong kilim hem i ded."],[2,22,"Be taem Modekae i save samting ya, hem i go talem long Kwin Esta, nao kwin i go talemaot long king.","Be taem Modekae i save samting ya, hem i go talem long Kwin Esta, nao kwin i go talemaot long king."],[2,23,"Nao taem ol man blong king oli lukluk long bisnes ya, oli faenemaot se samting ya i tru. Nao oli holem tufala ya, oli tekem tufala i go long ples blong kilim man, mo oli hangem tufala i ded. Nao king i talem long olgeta blong oli raetemdaon ripot blong samting ya. Mo long fes blong hem olgeta oli raetemdaon long buk* blong ol ripot blong ol samting we i stap hapen long ol kantri ya we hem i stap rul long hem.","Nao taem ol man blong king oli lukluk long bisnes ya, oli faenemaot se samting ya i tru. Nao oli holem tufala ya, oli tekem tufala i go long ples blong kilim man, mo oli hangem tufala i ded. Nao king i talem long olgeta blong oli raetemdaon ripot blong samting ya. Mo long fes blong hem olgeta oli raetemdaon long buk* blong ol ripot blong ol samting we i stap hapen long ol kantri ya we hem i stap rul long hem."],[3,1,"Nao biaen, King Sekses i putumap wan man we nem blong hem Haman i kam praeminista blong hem. Haman ya, hem i pikinini blong Hamedata, we i kamaot biaen long Agag.","Nao biaen, King Sekses i putumap wan man we nem blong hem Haman i kam praeminista blong hem. Haman ya, hem i pikinini blong Hamedata, we i kamaot biaen long Agag."],[3,2,"Mo king i talem long ol haeman blong hem, se oli mas ona long praeminista ya blong hem, mo oltaem oli mas nildaon long fes blong hem, mo oli mas bodaon long hem. Nao olgeta evriwan oli stap mekem olsem, Modekae nomo i no wantem.","Mo king i talem long ol haeman blong hem, se oli mas ona long praeminista ya blong hem, mo oltaem oli mas nildaon long fes blong hem, mo oli mas bodaon long hem. Nao olgeta evriwan oli stap mekem olsem, Modekae nomo i no wantem."],[3,3,"Nao oltaem ol narafala haeman blong king oli stap askem long Modekae from wanem hem i no save obei long tok ya blong king.","Nao oltaem ol narafala haeman blong king oli stap askem long Modekae from wanem hem i no save obei long tok ya blong king."],[3,4,"Evri dei nomo, oli stap tok long hem blong i mekem olsem we king i talem, be hem i no wantem. Hem i talem long olgeta se, “!Olgeta! !Mi mi laen* blong Isrel* ya, mi no save bodaon long Haman!” Nao oli go talemaot hem long Haman, from we oli wantem luk se bambae Haman i tok long hem, no i letem hem i stap mekem olsem.","Evri dei nomo, oli stap tok long hem blong i mekem olsem we king i talem, be hem i no wantem. Hem i talem long olgeta se, “!Olgeta! !Mi mi laen* blong Isrel* ya, mi no save bodaon long Haman!” Nao oli go talemaot hem long Haman, from we oli wantem luk se bambae Haman i tok long hem, no i letem hem i stap mekem olsem."],[3,5,"Be taem Haman i luk we Modekae i no save ona long hem olsem, hem i kros we i kros.","Be taem Haman i luk we Modekae i no save ona long hem olsem, hem i kros we i kros."],[3,6,"Mo taem hem i harem we Modekae i wan laen blong Isrel, hem i talem se bambae i no panisim Modekae nomo, bambae i holem olgeta laen blong Isrel we oli stap olbaot long ol kantri ya we king ya i stap rul long hem, i kilim olgeta evriwan i ded.","Mo taem hem i harem we Modekae i wan laen blong Isrel, hem i talem se bambae i no panisim Modekae nomo, bambae i holem olgeta laen blong Isrel we oli stap olbaot long ol kantri ya we king ya i stap rul long hem, i kilim olgeta evriwan i ded."],[3,7,"Nao long taem ya we King Sekses i stap rul, long namba twelef yia blong hem, long manis ya Nisan* we i fas manis blong yia, Haman i talem long ol man blong hem blong oli sakem ol spesel ston* blong faenemaot stret manis mo stret dei blong i wokem plan ya blong hem. Nao oli faenemaot se stret taem blong hem long namba twelef manis, we nem blong hem Adara,* long namba totin dei blong hem, nao oli agri long hem. (Ol spesel ston ya, long lanwis blong olgeta, nem blong hem, “purim”.)","Nao long taem ya we King Sekses i stap rul, long namba twelef yia blong hem, long manis ya Nisan* we i fas manis blong yia, Haman i talem long ol man blong hem blong oli sakem ol spesel ston* blong faenemaot stret manis mo stret dei blong i wokem plan ya blong hem. Nao oli faenemaot se stret taem blong hem long namba twelef manis, we nem blong hem Adara,* long namba totin dei blong hem, nao oli agri long hem. (Ol spesel ston ya, long lanwis blong olgeta, nem blong hem, “purim”.)"],[3,8,"Nao Haman i talem long king se, “King. Olbaot long ol kantri ya we yu yu stap rul long hem, long evri provins, i gat ol man i stap we oli stap folem ol kastom we oli defren olgeta long ol kastom blong ol narafala man. Olgeta ya oli no save obei long ol loa blong yu, mo sipos yu letem olgeta i stap olsem, bambae oli mekem bigfala trabol long yu.","Nao Haman i talem long king se, “King. Olbaot long ol kantri ya we yu yu stap rul long hem, long evri provins, i gat ol man i stap we oli stap folem ol kastom we oli defren olgeta long ol kastom blong ol narafala man. Olgeta ya oli no save obei long ol loa blong yu, mo sipos yu letem olgeta i stap olsem, bambae oli mekem bigfala trabol long yu."],[3,9,"Long tingting blong mi, mi ting se i moa gud yu mekem wan strong tok blong yu se olgeta ya oli mas ded, mo yu talemaot long evri ples. Sipos yu glad blong mekem olsem, mi mi promes se bambae mi givim fiftin taosen milian vatu* long yu blong yu save yusum blong mekem ol wok blong ol kantri ya we yu stap rul long hem.”","Long tingting blong mi, mi ting se i moa gud yu mekem wan strong tok blong yu se olgeta ya oli mas ded, mo yu talemaot long evri ples. Sipos yu glad blong mekem olsem, mi mi promes se bambae mi givim fiftin taosen milian vatu* long yu blong yu save yusum blong mekem ol wok blong ol kantri ya we yu stap rul long hem.”"],[3,10,"Nao king i gat wan ring blong hem we i stap yusum oltaem blong putum mak blong hem long ol niufala loa we oli raetem, blong soemaot we loa ya i blong hem. Nao hem i tekemaot ring ya, i givim long Haman, enemi ya blong ol laen blong Isrel.","Nao king i gat wan ring blong hem we i stap yusum oltaem blong putum mak blong hem long ol niufala loa we oli raetem, blong soemaot we loa ya i blong hem. Nao hem i tekemaot ring ya, i givim long Haman, enemi ya blong ol laen blong Isrel."],[3,11,"Mo i talem long hem se, “Ol mane ya i stap long han blong yu, mo olgeta man ya oli blong yu evriwan. Wanem samting we yu wantem mekem long olgeta, yu save mekem olsem we yu wantem.”","Mo i talem long hem se, “Ol mane ya i stap long han blong yu, mo olgeta man ya oli blong yu evriwan. Wanem samting we yu wantem mekem long olgeta, yu save mekem olsem we yu wantem.”"],[3,12,"Nao long sem manis ya yet, long namba totin dei blong hem, Haman i singaot ol sekretari blong king oli kam luk hem, nao hem i talemaot wan tok blong hem long olgeta blong oli raetemdaon. Nao oli tanem i go long ol lanwis blong olgeta provins we king ya i rul long hem, mo oli raetem long ol fasin blong raet blong ol lanwis ya wanwan. Nao Haman i tekem ring ya blong king, i putum mak blong hem long olgeta leta ya, blong tok ya blong hem bambae i kamaot long nem blong king, nao i sanem ol leta ya i go long ol lida mo ol distrikejen* mo ol haeman long olgeta kantri we king ya i stap rul long hem.","Nao long sem manis ya yet, long namba totin dei blong hem, Haman i singaot ol sekretari blong king oli kam luk hem, nao hem i talemaot wan tok blong hem long olgeta blong oli raetemdaon. Nao oli tanem i go long ol lanwis blong olgeta provins we king ya i rul long hem, mo oli raetem long ol fasin blong raet blong ol lanwis ya wanwan. Nao Haman i tekem ring ya blong king, i putum mak blong hem long olgeta leta ya, blong tok ya blong hem bambae i kamaot long nem blong king, nao i sanem ol leta ya i go long ol lida mo ol distrikejen* mo ol haeman long olgeta kantri we king ya i stap rul long hem."],[3,13,"Nao ol man blong resis oli tekem ol leta ya, oli karem i go long olgeta provins ya. Toktok blong ol leta ya i talem se, “Long manis ya Adara, long namba totin dei blong hem, olgeta laen blong Isrel we oli stap long ol provins blong yufala, bambae yufala i mas kilim olgeta evriwan oli ded. Ol yangfala wetem ol olfala, ol woman wetem ol pikinini, bambae yufala i mas kilim olgeta evriwan long wan dei nomo, we bambae yufala i no gat sore nating long olgeta. Bambae yufala i save tekem olting blong olgeta oli blong yufala.","Nao ol man blong resis oli tekem ol leta ya, oli karem i go long olgeta provins ya. Toktok blong ol leta ya i talem se, “Long manis ya Adara, long namba totin dei blong hem, olgeta laen blong Isrel we oli stap long ol provins blong yufala, bambae yufala i mas kilim olgeta evriwan oli ded. Ol yangfala wetem ol olfala, ol woman wetem ol pikinini, bambae yufala i mas kilim olgeta evriwan long wan dei nomo, we bambae yufala i no gat sore nating long olgeta. Bambae yufala i save tekem olting blong olgeta oli blong yufala."],[3,14,"Tok ya i mas go long olgeta provins blong yufala, blong olgeta man evriwan oli mas harem, nao long dei ya, bambae yufala i stap rere blong mekem samting ya.”","Tok ya i mas go long olgeta provins blong yufala, blong olgeta man evriwan oli mas harem, nao long dei ya, bambae yufala i stap rere blong mekem samting ya.”"],[3,15,"From we king i agri finis long tok ya, ol man blong hem oli go talemaot long bigfala taon ya Susa, mo ol man blong resis oli karem i go long olgeta kantri we king i stap rul long hem. Nao long taon ya, tok ya i mekem ol man oli stap harem nogud tumas, we tingting blong olgeta i paspas from, be king wetem Haman, tufala i stap sidaon, tufala i stap dring, tufala i stap harem gud.","From we king i agri finis long tok ya, ol man blong hem oli go talemaot long bigfala taon ya Susa, mo ol man blong resis oli karem i go long olgeta kantri we king i stap rul long hem. Nao long taon ya, tok ya i mekem ol man oli stap harem nogud tumas, we tingting blong olgeta i paspas from, be king wetem Haman, tufala i stap sidaon, tufala i stap dring, tufala i stap harem gud."],[4,1,"Nao taem Modekae i harem nius blong samting ya, hem i harem nogud tumas, mo i terem* klos blong hem from. Nao hem i putum rabis klos, mo i sakem asis blong faea i go long hed blong hem, mo i stap go olbaot long taon, we i stap krae bigwan","Nao taem Modekae i harem nius blong samting ya, hem i harem nogud tumas, mo i terem* klos blong hem from. Nao hem i putum rabis klos, mo i sakem asis blong faea i go long hed blong hem, mo i stap go olbaot long taon, we i stap krae bigwan"],[4,2,"gogo i kam long doa* blong bigfala stonwol blong yad blong haos blong king. Hem i no go insaed, from we man we i putum rabis klos olsem i no save go insaed long ples ya.","gogo i kam long doa* blong bigfala stonwol blong yad blong haos blong king. Hem i no go insaed, from we man we i putum rabis klos olsem i no save go insaed long ples ya."],[4,3,"Long olgeta provins we oli talemaot tok ya blong king, olgeta laen* blong Isrel* oli stap harem nogud tumas, oli krae. Oli stap krae bigwan, mo oli livim kakae blong soemaot we oli harem nogud, mo plante long olgeta oli putum rabis klos, mo oli stap ledaon long asis.","Long olgeta provins we oli talemaot tok ya blong king, olgeta laen* blong Isrel* oli stap harem nogud tumas, oli krae. Oli stap krae bigwan, mo oli livim kakae blong soemaot we oli harem nogud, mo plante long olgeta oli putum rabis klos, mo oli stap ledaon long asis."],[4,4,"Nao taem ol gel blong wok blong kwin wetem ol man blong wok blong hem oli talemaot ol samting ya long hem we Modekae i mekem, hem i harem nogud tumas. Nao hem i tekem sam klos, i sanem i go long Modekae blong hem i jenisim klos blong hem blong i kam insaed, be hem i no wantem.","Nao taem ol gel blong wok blong kwin wetem ol man blong wok blong hem oli talemaot ol samting ya long hem we Modekae i mekem, hem i harem nogud tumas. Nao hem i tekem sam klos, i sanem i go long Modekae blong hem i jenisim klos blong hem blong i kam insaed, be hem i no wantem."],[4,5,"Nao kwin i singaot wan man blong wok blong hem, we nem blong hem Hatak, we king i putumap hem blong i stap wok blong hem, nao i sanem hem blong i go luk Modekae, blong i faenemaot wanem samting i hapen, mo we hem i mekem olsem from wanem.","Nao kwin i singaot wan man blong wok blong hem, we nem blong hem Hatak, we king i putumap hem blong i stap wok blong hem, nao i sanem hem blong i go luk Modekae, blong i faenemaot wanem samting i hapen, mo we hem i mekem olsem from wanem."],[4,6,"Modekae i stap long bigfala ples ya blong mekem miting long medel blong taon, klosap long doa blong bigfala stonwol blong yad blong haos blong king, nao Hatak i go luk hem long ples ya,","Modekae i stap long bigfala ples ya blong mekem miting long medel blong taon, klosap long doa blong bigfala stonwol blong yad blong haos blong king, nao Hatak i go luk hem long ples ya,"],[4,7,"mo Modekae i talemaot ol samting ya long hem we oli bin mekem long hem, mo bigfala mane ya we Haman i promes finis long king, se sipos king i kilim olgeta laen blong Isrel oli ded, bambae i givim long hem.","mo Modekae i talemaot ol samting ya long hem we oli bin mekem long hem, mo bigfala mane ya we Haman i promes finis long king, se sipos king i kilim olgeta laen blong Isrel oli ded, bambae i givim long hem."],[4,8,"Modekae i gat wan kopi blong tok ya blong king, we oli stap putum olbaot long taon ya, we i talem se bambae ol man oli kilim olgeta laen blong Isrel oli ded. Nao hem i givim kopi ya long Hatak, mo i talem long hem blong i go talemaot ol samting ya long kwin, mo i givim kopi ya long hem. Mo i talem long hem tu se kwin i mas go krae long king, blong hem i gat sore long ol man ples blong hem.","Modekae i gat wan kopi blong tok ya blong king, we oli stap putum olbaot long taon ya, we i talem se bambae ol man oli kilim olgeta laen blong Isrel oli ded. Nao hem i givim kopi ya long Hatak, mo i talem long hem blong i go talemaot ol samting ya long kwin, mo i givim kopi ya long hem. Mo i talem long hem tu se kwin i mas go krae long king, blong hem i gat sore long ol man ples blong hem."],[4,9,"Nao Hatak i go mekem olsem we Modekae i talem.","Nao Hatak i go mekem olsem we Modekae i talem."],[4,10,"Be kwin i sanem hem i gobak blong talemaot long Modekae se,","Be kwin i sanem hem i gobak blong talemaot long Modekae se,"],[4,11,"“I gud, be i gat loa blong samting ya i stap. Loa ya i talem se, ‘Sipos wan man no wan woman i go long yad ya blong haos blong king we i insaed olgeta, we king i no singaot hem blong i go, bambae oli mas kilim hem i ded.’ Loa ya i tabu, mo olgeta man, i stat long ol advaesa blong king i go kasem olgeta man long ol provins, oli save finis. I gat wan samting nomo i save sevem man we i go insaed olsem. King i gat wokingstik blong hem we oli wokem long gol, nao sipos hem i holem stik ya, i poenem man olsem long hem, man ya bambae i no ded, i save stap. Be i gat wan manis i pas finis we king i no moa singaot mi blong mi go luk hem.”","“I gud, be i gat loa blong samting ya i stap. Loa ya i talem se, ‘Sipos wan man no wan woman i go long yad ya blong haos blong king we i insaed olgeta, we king i no singaot hem blong i go, bambae oli mas kilim hem i ded.’ Loa ya i tabu, mo olgeta man, i stat long ol advaesa blong king i go kasem olgeta man long ol provins, oli save finis. I gat wan samting nomo i save sevem man we i go insaed olsem. King i gat wokingstik blong hem we oli wokem long gol, nao sipos hem i holem stik ya, i poenem man olsem long hem, man ya bambae i no ded, i save stap. Be i gat wan manis i pas finis we king i no moa singaot mi blong mi go luk hem.”"],[4,12,"Nao taem Modekae i harem tok ya blong kwin,","Nao taem Modekae i harem tok ya blong kwin,"],[4,13,"hem i sanem narafala tok bakegen i go long hem blong givim woning long hem, i talem se, “Esta. I nogud yu ting se yu yu stap long haos blong king, nao bambae yu stap gud i winim mifala ol narafala laen blong Isrel.","hem i sanem narafala tok bakegen i go long hem blong givim woning long hem, i talem se, “Esta. I nogud yu ting se yu yu stap long haos blong king, nao bambae yu stap gud i winim mifala ol narafala laen blong Isrel."],[4,14,"Naoia i gat wan hadtaem i kasem yumi ol laen blong Isrel, mo sipos yu yu stap kwaet olsem, bambae God i givhan long mifala, i sevem mifala, be yu bambae yu ded, nao famle blong papa blong yu bambae i finis. ?Be naoia, hu i save? Maet yu yu kam kwin long taem ya, blong bambae yu save givhan long yumi long hadtaem ya.”","Naoia i gat wan hadtaem i kasem yumi ol laen blong Isrel, mo sipos yu yu stap kwaet olsem, bambae God i givhan long mifala, i sevem mifala, be yu bambae yu ded, nao famle blong papa blong yu bambae i finis. ?Be naoia, hu i save? Maet yu yu kam kwin long taem ya, blong bambae yu save givhan long yumi long hadtaem ya.”"],[4,15,"Nao kwin i sanem tok i gobak long hem bakegen,","Nao kwin i sanem tok i gobak long hem bakegen,"],[4,16,"i talem se, “Plis, yu go singaot olgeta man ples blong yumi we oli stap long taon ya, oli kam wanples. Bambae yufala i stap prea from mi gogo kasem tri dei mo tri naet we yufala i no kakae, mo yufala i no dring. Mo mi wetem ol gel blong wok blong mi, bambae mifala tu i mekem sem samting. Nao long namba tri dei ya, nating we i agensem loa, be bambae mi mas go luk king. Mo sipos i min se mi mi mas ded from, be bambae i mas olsem.”","i talem se, “Plis, yu go singaot olgeta man ples blong yumi we oli stap long taon ya, oli kam wanples. Bambae yufala i stap prea from mi gogo kasem tri dei mo tri naet we yufala i no kakae, mo yufala i no dring. Mo mi wetem ol gel blong wok blong mi, bambae mifala tu i mekem sem samting. Nao long namba tri dei ya, nating we i agensem loa, be bambae mi mas go luk king. Mo sipos i min se mi mi mas ded from, be bambae i mas olsem.”"],[4,17,"Nao Modekae i go, i mekem evri samting, stret olsem we kwin i talem.","Nao Modekae i go, i mekem evri samting, stret olsem we kwin i talem."],[5,1,"Nao long taem ya we kwin i livim kakae, long namba tri dei blong hem, hem i putum ol nambawan klos blong hem, nao i go long smol yad ya long haos blong king we i insaed olgeta, nao i stanap, i lukluk i go long rum ya we bigfala jea blong king i stap long hem. King i stap insaed, i stap sidaon long bigfala jea ya blong hem, i stap lukluk i kam long doa.","Nao long taem ya we kwin i livim kakae, long namba tri dei blong hem, hem i putum ol nambawan klos blong hem, nao i go long smol yad ya long haos blong king we i insaed olgeta, nao i stanap, i lukluk i go long rum ya we bigfala jea blong king i stap long hem. King i stap insaed, i stap sidaon long bigfala jea ya blong hem, i stap lukluk i kam long doa."],[5,2,"Mo taem hem i luk kwin we i stap stanap afsaed long yad ya, hem i glad tumas blong luk hem, nao i tekem wokingstik ya blong hem we oli wokem long gol, i poenem hem long hem. Nao kwin i go klosap, i tajem en blong stik ya.","Mo taem hem i luk kwin we i stap stanap afsaed long yad ya, hem i glad tumas blong luk hem, nao i tekem wokingstik ya blong hem we oli wokem long gol, i poenem hem long hem. Nao kwin i go klosap, i tajem en blong stik ya."],[5,3,"Nao king i askem long hem se, “?Esta, olsem wanem? ?Yu wantem wan samting? Sipos yu talemaot wanem samting long mi we yu yu wantem, nating sipos yu askem haf blong olgeta samting we mi mi gat long kingdom blong mi, be bambae mi save givim long yu.”","Nao king i askem long hem se, “?Esta, olsem wanem? ?Yu wantem wan samting? Sipos yu talemaot wanem samting long mi we yu yu wantem, nating sipos yu askem haf blong olgeta samting we mi mi gat long kingdom blong mi, be bambae mi save givim long yu.”"],[5,4,"Nao kwin i talem long hem se, “King. Plis mi wantem se tede bambae yu mo Haman, yutufala i kam kakae long haos blong mi. Mi stap mekemrere kakae blong yutufala, mo sipos yutufala i save kam, bambae mi mi glad tumas.”","Nao kwin i talem long hem se, “King. Plis mi wantem se tede bambae yu mo Haman, yutufala i kam kakae long haos blong mi. Mi stap mekemrere kakae blong yutufala, mo sipos yutufala i save kam, bambae mi mi glad tumas.”"],[5,5,"Nao king i sanem tok i go long Haman blong i kam kwiktaem, blong bambae tufala i go kakae long haos blong kwin. Mo taem hem i kamtru, hem wetem king, tufala i go long kakae ya we kwin i mekem blong tufala.","Nao king i sanem tok i go long Haman blong i kam kwiktaem, blong bambae tufala i go kakae long haos blong kwin. Mo taem hem i kamtru, hem wetem king, tufala i go long kakae ya we kwin i mekem blong tufala."],[5,6,"Nao taem trifala i stap dring waen, king i talem long kwin se, “Kwin, sipos yu talemaot long mi wanem samting we yu yu wantem, bambae mi save givim long yu naoia. Nating sipos yu askem haf blong olgeta samting we mi mi gat long kingdom blong mi, be bambae mi save mekem olsem we yu yu wantem.”","Nao taem trifala i stap dring waen, king i talem long kwin se, “Kwin, sipos yu talemaot long mi wanem samting we yu yu wantem, bambae mi save givim long yu naoia. Nating sipos yu askem haf blong olgeta samting we mi mi gat long kingdom blong mi, be bambae mi save mekem olsem we yu yu wantem.”"],[5,7,"Nao kwin i talem se,","Nao kwin i talem se,"],[5,8,"“King, sipos i tru we yu yu glad blong givim samting we bambae mi askem long yu, plis mi wantem tumas blong yutufala i kambak bakegen long ples ya tumora. Bambae mi mekemrere wan narafala kakae blong yutufala, mo sipos yu save mekem olsem, bambae mi mi glad tumas. Nao tumora bambae mi talemaot long yu samting ya we mi mi wantem.”","“King, sipos i tru we yu yu glad blong givim samting we bambae mi askem long yu, plis mi wantem tumas blong yutufala i kambak bakegen long ples ya tumora. Bambae mi mekemrere wan narafala kakae blong yutufala, mo sipos yu save mekem olsem, bambae mi mi glad tumas. Nao tumora bambae mi talemaot long yu samting ya we mi mi wantem.”"],[5,9,"Nao taem trifala i kakae finis, Haman i aot blong gohom we i harem gud tumas, mo tingting blong hem i glad we i glad. Be taem hem i stap wokbaot i go, hem i luk Modekae i stap sidaon long ofis blong hem, long doa* blong bigfala stonwol blong yad blong king, be hem i no girap blong ona long hem, mo taem hem i pas long ples ya, Modekae i no mekem wan saen nating blong ona long hem, nao hem i kros we i kros.","Nao taem trifala i kakae finis, Haman i aot blong gohom we i harem gud tumas, mo tingting blong hem i glad we i glad. Be taem hem i stap wokbaot i go, hem i luk Modekae i stap sidaon long ofis blong hem, long doa* blong bigfala stonwol blong yad blong king, be hem i no girap blong ona long hem, mo taem hem i pas long ples ya, Modekae i no mekem wan saen nating blong ona long hem, nao hem i kros we i kros."],[5,10,"Be hem i taetem hem nomo, i wokbaot i go long haos blong hem. Nao hem i singaot ol fren blong hem oli kam long haos blong hem, mo i singaot woman blong hem Seres tu, i kam joen wetem olgeta.","Be hem i taetem hem nomo, i wokbaot i go long haos blong hem. Nao hem i singaot ol fren blong hem oli kam long haos blong hem, mo i singaot woman blong hem Seres tu, i kam joen wetem olgeta."],[5,11,"Nao hem i stap tok flas long fes blong olgeta, i stap talem se hem i wan rijman we i gat plante pikinini boe blong hem, mo we king i mekem hem i holem wan wok we i gat hae nem long hem, mo we hem i kam namba wan haeman blong king, i winim ol narafala haeman blong hem.","Nao hem i stap tok flas long fes blong olgeta, i stap talem se hem i wan rijman we i gat plante pikinini boe blong hem, mo we king i mekem hem i holem wan wok we i gat hae nem long hem, mo we hem i kam namba wan haeman blong king, i winim ol narafala haeman blong hem."],[5,12,"Mo hem i talem se, “!Yufala i luk! Antap long ol samting ya, tede nomo, Kwin Esta i mekem wan gudfala kakae blong mi mo king, we i blong mitufala nomo, i no blong ol narafala man. Mo tumora, hem i wantem blong mitufala i go kakae long haos blong hem bakegen.","Mo hem i talem se, “!Yufala i luk! Antap long ol samting ya, tede nomo, Kwin Esta i mekem wan gudfala kakae blong mi mo king, we i blong mitufala nomo, i no blong ol narafala man. Mo tumora, hem i wantem blong mitufala i go kakae long haos blong hem bakegen."],[5,13,"Be i gat wan samting yet we i stap spolem tingting blong mi. Taem mi luk Modekae, laen* ya blong Isrel* we i stap sidaon long ofis blong hem long doa blong bigfala stonwol blong yad blong king, samting ya i mekem mi mi harem nogud tumas, nao mi luk ol gudgudfala samting ya i olsem samting nating nomo.”","Be i gat wan samting yet we i stap spolem tingting blong mi. Taem mi luk Modekae, laen* ya blong Isrel* we i stap sidaon long ofis blong hem long doa blong bigfala stonwol blong yad blong king, samting ya i mekem mi mi harem nogud tumas, nao mi luk ol gudgudfala samting ya i olsem samting nating nomo.”"],[5,14,"Nao woman blong hem mo ol fren ya blong hem oli talem long hem se, “I gud yu wokem wan ples blong hangem man we bambae i hae we i hae, i kasem twanti faef meta. Nao tumora long moning, bambae yu save askem long king, blong ol man blong hem oli hangem Modekae long hem. Ale biaen, bambae yu save go long kakae ya we tingting blong yu i glad.” Nao Haman i harem se plan ya i gud, nao hem i talem long ol man blong hem blong oli wokem wan ples blong hangem man, blong bambae oli hangem Modekae long hem.","Nao woman blong hem mo ol fren ya blong hem oli talem long hem se, “I gud yu wokem wan ples blong hangem man we bambae i hae we i hae, i kasem twanti faef meta. Nao tumora long moning, bambae yu save askem long king, blong ol man blong hem oli hangem Modekae long hem. Ale biaen, bambae yu save go long kakae ya we tingting blong yu i glad.” Nao Haman i harem se plan ya i gud, nao hem i talem long ol man blong hem blong oli wokem wan ples blong hangem man, blong bambae oli hangem Modekae long hem."],[6,1,"Nao long sem naet ya, king i no save slip, nao i talem long ol man blong hem blong oli go tekem buk* ya we oli stap raetemdaon ol ripot blong kingdom blong hem i go long hem, oli kam ridim long hem blong hem i harem.","Nao long sem naet ya, king i no save slip, nao i talem long ol man blong hem blong oli go tekem buk* ya we oli stap raetemdaon ol ripot blong kingdom blong hem i go long hem, oli kam ridim long hem blong hem i harem."],[6,2,"Nao oli stap ridim gogo i brok delaet, mo oli kasem wan ples we i gat ripot we i tokbaot Modekae we i faenemaot we Bigtana wetem Teres, tufala i mekem plan blong kilim king. Tufala ya, tufala i man blong wok blong king, we long taem ya, tufala i stap gad long rum blong hem.","Nao oli stap ridim gogo i brok delaet, mo oli kasem wan ples we i gat ripot we i tokbaot Modekae we i faenemaot we Bigtana wetem Teres, tufala i mekem plan blong kilim king. Tufala ya, tufala i man blong wok blong king, we long taem ya, tufala i stap gad long rum blong hem."],[6,3,"Nao king i askem se, “?Ei, be mi mi mekem wanem samting long Modekae blong ona long hem from samting ya?” Nao ol man blong wok blong hem oli talem se, “I no gat. Yu no mekem wan samting long hem yet.”","Nao king i askem se, “?Ei, be mi mi mekem wanem samting long Modekae blong ona long hem from samting ya?” Nao ol man blong wok blong hem oli talem se, “I no gat. Yu no mekem wan samting long hem yet.”"],[6,4,"Nao king i talem se, “Sipos i gat wan minista blong mi i stap long ples ya, bambae mitufala i save lukluk long bisnes ya.” Long taem ya, ol man blong Haman oli wokem finis ples ya blong hangem man, mo hem i jes kam insaed long yad blong haos blong king blong askem long hem blong i letem hem i hangem Modekae i ded.","Nao king i talem se, “Sipos i gat wan minista blong mi i stap long ples ya, bambae mitufala i save lukluk long bisnes ya.” Long taem ya, ol man blong Haman oli wokem finis ples ya blong hangem man, mo hem i jes kam insaed long yad blong haos blong king blong askem long hem blong i letem hem i hangem Modekae i ded."],[6,5,"Nao ol man blong wok blong king oli talem long hem se, “King. Praeminista ya i stap. Hem i stap wet blong luk yu.” Nao king i talem se, “Ale, yufala i go tekem hem i kam.”","Nao ol man blong wok blong king oli talem long hem se, “King. Praeminista ya i stap. Hem i stap wet blong luk yu.” Nao king i talem se, “Ale, yufala i go tekem hem i kam.”"],[6,6,"Nao Haman i kam insaed, mo king i talem long hem se, “Praeminista, i gat wan man we mi mi wantem tumas blong ona long hem. ?Yu ting se bambae mi save mekem wanem samting long hem blong leftemap nem blong hem?” Nao Haman i stap tingting hem wan se, “?Hu man ya we king i wantem tumas blong ona long hem? !Hemia i no narafala man ya, mi nomo ya!”","Nao Haman i kam insaed, mo king i talem long hem se, “Praeminista, i gat wan man we mi mi wantem tumas blong ona long hem. ?Yu ting se bambae mi save mekem wanem samting long hem blong leftemap nem blong hem?” Nao Haman i stap tingting hem wan se, “?Hu man ya we king i wantem tumas blong ona long hem? !Hemia i no narafala man ya, mi nomo ya!”"],[6,7,"Nao hem i talem long king se, “King. Sipos yu wantem ona long wan man olsem,","Nao hem i talem long king se, “King. Sipos yu wantem ona long wan man olsem,"],[6,8,"i gud yu talem long ol man blong wok blong yu blong oli go tekem wan longfala kot blong yu we yu stap putum oltaem, oli karem i kam, mo oli go flasem hos ya blong yu olsem we oli stap flasem oltaem, taem yu wantem wokbaot long hem.","i gud yu talem long ol man blong wok blong yu blong oli go tekem wan longfala kot blong yu we yu stap putum oltaem, oli karem i kam, mo oli go flasem hos ya blong yu olsem we oli stap flasem oltaem, taem yu wantem wokbaot long hem."],[6,9,"Nao yu talem long wan minista blong yu we i hae moa long ol narawan, blong i putum longfala kot ya long man ya, mo i givhan long hem blong i sidaon long hos ya, nao bambae i holem rop blong hos ya, i lidim i go olbaot long bigfala ples ya blong mekem miting, long medel blong taon. Mo taem tufala i stap go, minista ya bambae i mas singaot blong talemaot se, ‘Sipos king i wantem ona long wan man, fasin we hem i stap mekem i gud we i gud. !Yufala i kam luk! !Hemia nao fasin blong hem!’ ”","Nao yu talem long wan minista blong yu we i hae moa long ol narawan, blong i putum longfala kot ya long man ya, mo i givhan long hem blong i sidaon long hos ya, nao bambae i holem rop blong hos ya, i lidim i go olbaot long bigfala ples ya blong mekem miting, long medel blong taon. Mo taem tufala i stap go, minista ya bambae i mas singaot blong talemaot se, ‘Sipos king i wantem ona long wan man, fasin we hem i stap mekem i gud we i gud. !Yufala i kam luk! !Hemia nao fasin blong hem!’ ”"],[6,10,"Nao king i talem long Haman se, “Ale, yu hareap, yu go tekem longfala kot ya blong mi i kam, mo yu go tekem hos blong mi i kam, nao yu go mekem ol samting ya long Modekae, laen* ya blong Isrel,* blong ona long hem. Hem i stap sidaon long ofis blong hem, long doa* blong bigfala stonwol blong yad ya. Bambae yu mekem evri samting ya long hem stret olsem we yu yu talem.”","Nao king i talem long Haman se, “Ale, yu hareap, yu go tekem longfala kot ya blong mi i kam, mo yu go tekem hos blong mi i kam, nao yu go mekem ol samting ya long Modekae, laen* ya blong Isrel,* blong ona long hem. Hem i stap sidaon long ofis blong hem, long doa* blong bigfala stonwol blong yad ya. Bambae yu mekem evri samting ya long hem stret olsem we yu yu talem.”"],[6,11,"Nao Haman i go tekem longfala kot ya wetem hos ya i kam, nao i putum kot ya long Modekae, mo i givhan long hem blong i sidaon long hos ya. Mo hem i holem rop blong hos ya, i lidim hem i go olbaot long bigfala ples ya blong mekem miting long medel blong taon. Mo taem tufala i stap go, hem i stap singaot i stap talem se, “Sipos king i wantem ona long wan man, fasin we hem i stap mekem i gud we i gud. !Yufala i kam luk! !Hemia nao fasin blong hem!”","Nao Haman i go tekem longfala kot ya wetem hos ya i kam, nao i putum kot ya long Modekae, mo i givhan long hem blong i sidaon long hos ya. Mo hem i holem rop blong hos ya, i lidim hem i go olbaot long bigfala ples ya blong mekem miting long medel blong taon. Mo taem tufala i stap go, hem i stap singaot i stap talem se, “Sipos king i wantem ona long wan man, fasin we hem i stap mekem i gud we i gud. !Yufala i kam luk! !Hemia nao fasin blong hem!”"],[6,12,"Nao biaen, Modekae i gobak long ofis blong hem, be Haman i kavremap fes blong hem from we i sem tumas, i ronwe i go long haos blong hem.","Nao biaen, Modekae i gobak long ofis blong hem, be Haman i kavremap fes blong hem from we i sem tumas, i ronwe i go long haos blong hem."],[6,13,"Hem i go stori long woman blong hem wetem olgeta fren blong hem, i talemaot evri samting ya long olgeta, we i hapen long hem. Nao woman blong hem wetem ol fren ya blong hem oli talem long hem se, “Naoia nem blong yu i stap godaon, be nem blong Modekae i stap kam antap. Man ya i wan laen blong Isrel ya. Bambae yu no save winim hem. Hem bambae i mas winim yu ya.”","Hem i go stori long woman blong hem wetem olgeta fren blong hem, i talemaot evri samting ya long olgeta, we i hapen long hem. Nao woman blong hem wetem ol fren ya blong hem oli talem long hem se, “Naoia nem blong yu i stap godaon, be nem blong Modekae i stap kam antap. Man ya i wan laen blong Isrel ya. Bambae yu no save winim hem. Hem bambae i mas winim yu ya.”"],[6,14,"Nao taem olgeta oli stap tokbaot samting ya yet, ol man blong wok blong king oli kam, oli hareap long Haman blong tekem hem i go long kakae ya we kwin i wokem.","Nao taem olgeta oli stap tokbaot samting ya yet, ol man blong wok blong king oli kam, oli hareap long Haman blong tekem hem i go long kakae ya we kwin i wokem."],[7,1,"Nao king ya wetem Haman, tufala i go kakae wetem kwin bakegen.","Nao king ya wetem Haman, tufala i go kakae wetem kwin bakegen."],[7,2,"Mo taem trifala i stap dring waen, king i talem long kwin bakegen se, “Kwin, sipos yu talemaot long mi wanem samting we yu yu wantem, bambae mi save givim long yu naoia. Nating sipos yu askem haf blong olgeta samting we mi mi gat, be bambae mi save mekem olsem we yu yu wantem.”","Mo taem trifala i stap dring waen, king i talem long kwin bakegen se, “Kwin, sipos yu talemaot long mi wanem samting we yu yu wantem, bambae mi save givim long yu naoia. Nating sipos yu askem haf blong olgeta samting we mi mi gat, be bambae mi save mekem olsem we yu yu wantem.”"],[7,3,"Nao kwin i talem se, “King. Sipos i tru we yu yu glad blong givim samting we bambae mi askem long yu, plis mi wantem tumas blong yu sevem laef blong mi wetem laef blong ol man ples blong mi, blong bambae mifala i no ded.","Nao kwin i talem se, “King. Sipos i tru we yu yu glad blong givim samting we bambae mi askem long yu, plis mi wantem tumas blong yu sevem laef blong mi wetem laef blong ol man ples blong mi, blong bambae mifala i no ded."],[7,4,"Mi wetem ol man ples blong mi, wan man i bin pemaot mifala blong i save kilim mifala i ded. Sipos hem i bin pemaot mifala blong mekem mifala i kam slef* nomo, bambae mi save stap kwaet, mi no save mekem yu yu trabol from. Be naoia taem blong mifala i kam klosap we bambae man ya i kilim mifala evriwan i ded, we bambae i no gat wan long mifala i stap.”","Mi wetem ol man ples blong mi, wan man i bin pemaot mifala blong i save kilim mifala i ded. Sipos hem i bin pemaot mifala blong mekem mifala i kam slef* nomo, bambae mi save stap kwaet, mi no save mekem yu yu trabol from. Be naoia taem blong mifala i kam klosap we bambae man ya i kilim mifala evriwan i ded, we bambae i no gat wan long mifala i stap.”"],[7,5,"Nao king i askem long kwin se, “?Hu ya i wantem mekem samting ya? ?Man ya i stap wea?”","Nao king i askem long kwin se, “?Hu ya i wantem mekem samting ya? ?Man ya i stap wea?”"],[7,6,"Kwin i talem se, “Enemi ya blong mifala we i wantem spolem mifala, man nogud ya Haman.” Nao Haman i stap lukluk long tufala, we i fraet we i fraet.","Kwin i talem se, “Enemi ya blong mifala we i wantem spolem mifala, man nogud ya Haman.” Nao Haman i stap lukluk long tufala, we i fraet we i fraet."],[7,7,"Be king i kros we i kros, nao hem i girap, i aot long rum ya, i go long yad. Mo Haman i savegud we king bambae i kilim hem i ded from samting ya, nao hem i stap insaed blong askem long kwin blong i sevem laef blong hem.","Be king i kros we i kros, nao hem i girap, i aot long rum ya, i go long yad. Mo Haman i savegud we king bambae i kilim hem i ded from samting ya, nao hem i stap insaed blong askem long kwin blong i sevem laef blong hem."],[7,8,"Nao king i kam insaed long haos bakegen, stret long taem we Haman i foldaon antap long longfala jea ya we kwin i stap ledaon long hem, i stap krae long kwin blong i gat sore long hem. Mo taem king i luk hem, hem i talem se, “!Ei! ?Man ya i mekem wanem ya? ?Hem i stap traem fosem woman blong mi blong slip wetem hem insaed long haos blong mi, stret long fes blong mi?” Nao taem king i tok, wantaem nomo ol man blong wok blong hem oli kam kavremap fes blong Haman.","Nao king i kam insaed long haos bakegen, stret long taem we Haman i foldaon antap long longfala jea ya we kwin i stap ledaon long hem, i stap krae long kwin blong i gat sore long hem. Mo taem king i luk hem, hem i talem se, “!Ei! ?Man ya i mekem wanem ya? ?Hem i stap traem fosem woman blong mi blong slip wetem hem insaed long haos blong mi, stret long fes blong mi?” Nao taem king i tok, wantaem nomo ol man blong wok blong hem oli kam kavremap fes blong Haman."],[7,9,"Nao wan long olgeta we nem blong hem Habona, i talem se, “King. Man ya i jes wokem wan ples blong hangem man klosap long haos blong hem, we i hae we i hae i kasem twanti faef meta. Hem i wokem blong hangem Modekae long hem blong kilim hem i ded. Be man ya nao i sevem laef blong yu.” Nao king i talem se, “!Ale! !Yufala i go hangem Haman long hem!”","Nao wan long olgeta we nem blong hem Habona, i talem se, “King. Man ya i jes wokem wan ples blong hangem man klosap long haos blong hem, we i hae we i hae i kasem twanti faef meta. Hem i wokem blong hangem Modekae long hem blong kilim hem i ded. Be man ya nao i sevem laef blong yu.” Nao king i talem se, “!Ale! !Yufala i go hangem Haman long hem!”"],[7,10,"Nao oli tekem Haman, oli go hangem hem long ples ya we hem nomo i wokem blong hangem Modekae long hem. Nao king i no moa kros.","Nao oli tekem Haman, oli go hangem hem long ples ya we hem nomo i wokem blong hangem Modekae long hem. Nao king i no moa kros."],[8,1,"Nao long sem dei ya, olgeta samting blong Haman, enemi ya blong ol laen* blong Isrel,* king i givim olgeta evriwan i go long kwin. Mo kwin i talemaot long king we hem i wan sista blong Modekae, nao i stat long taem ya, king i givim raet long Modekae blong i save kam luk hem long haos blong hem olsem we hem i wantem.","Nao long sem dei ya, olgeta samting blong Haman, enemi ya blong ol laen* blong Isrel,* king i givim olgeta evriwan i go long kwin. Mo kwin i talemaot long king we hem i wan sista blong Modekae, nao i stat long taem ya, king i givim raet long Modekae blong i save kam luk hem long haos blong hem olsem we hem i wantem."],[8,2,"Mo king i tekem ring blong hem we i gat spesel mak blong hem long hem, i givim long Modekae blong hem i yusum. Ring ya, king i bin givim long Haman fastaem. Mo kwin i putum Modekae blong i stap lukaot long olgeta samting ya we i blong Haman fastaem.","Mo king i tekem ring blong hem we i gat spesel mak blong hem long hem, i givim long Modekae blong hem i yusum. Ring ya, king i bin givim long Haman fastaem. Mo kwin i putum Modekae blong i stap lukaot long olgeta samting ya we i blong Haman fastaem."],[8,3,"Nao kwin i luk we plan blong Haman blong kilim olgeta i ded, i stap yet, nao i nildaon long fes blong king, i stap krae, nao i askem bakegen long hem blong i mekem wan samting blong blokem plan ya.","Nao kwin i luk we plan blong Haman blong kilim olgeta i ded, i stap yet, nao i nildaon long fes blong king, i stap krae, nao i askem bakegen long hem blong i mekem wan samting blong blokem plan ya."],[8,4,"Nao king i holem wokingstik ya blong hem, we oli wokem long gol, i poenem kwin long hem, nao kwin i stanap, i talem se,","Nao king i holem wokingstik ya blong hem, we oli wokem long gol, i poenem kwin long hem, nao kwin i stanap, i talem se,"],[8,5,"“King, sipos i tru we yu yu lavem mi tumas, plis yu sore long mi. Leta ya we Haman i sanem i go long ol man, i talem long olgeta, se oli mas holem olgeta man ples blong mi we oli stap olbaot long ol kantri ya we yu yu stap rul long hem, oli mas kilim olgeta evriwan i ded. Plis yu mekem wan niufala tok blong blokem tok ya blong hem, yu sanem i go long ol man blong yu.","“King, sipos i tru we yu yu lavem mi tumas, plis yu sore long mi. Leta ya we Haman i sanem i go long ol man, i talem long olgeta, se oli mas holem olgeta man ples blong mi we oli stap olbaot long ol kantri ya we yu yu stap rul long hem, oli mas kilim olgeta evriwan i ded. Plis yu mekem wan niufala tok blong blokem tok ya blong hem, yu sanem i go long ol man blong yu."],[8,6,"King, sipos plan ya i gohed, nao ol man oli go kilim ol man ples blong mi mo ol laen blong mi oli ded, hemia bambae i nogud tumas long mi. I moa gud mi tu mi ded wetem olgeta.”","King, sipos plan ya i gohed, nao ol man oli go kilim ol man ples blong mi mo ol laen blong mi oli ded, hemia bambae i nogud tumas long mi. I moa gud mi tu mi ded wetem olgeta.”"],[8,7,"Long taem ya, Modekae tu i stap, nao king i talem long tufala se, “Yutufala i save. Mi mi hangem Haman finis from plan ya blong hem we i mekem agens long ol man ples blong yutufala, mo yu, kwin, mi givim olgeta samting blong hem finis long yu.","Long taem ya, Modekae tu i stap, nao king i talem long tufala se, “Yutufala i save. Mi mi hangem Haman finis from plan ya blong hem we i mekem agens long ol man ples blong yutufala, mo yu, kwin, mi givim olgeta samting blong hem finis long yu."],[8,8,"Be tok blong mi we oli raetemdaon mo i gat mak blong mi i stap long hem, nao i goaot finis long nem blong mi, i no gat man i save tekemaot. Be yutufala i save raetem wan leta i go long ol man ples blong yutufala, yutufala i save talem wanem tok long olgeta we yutufala i wantem. Bambae yutufala i raetem long nem blong mi, nao yutufala i putum mak blong mi long hem, mo yutufala i sanem i goaot long nem blong mi.”","Be tok blong mi we oli raetemdaon mo i gat mak blong mi i stap long hem, nao i goaot finis long nem blong mi, i no gat man i save tekemaot. Be yutufala i save raetem wan leta i go long ol man ples blong yutufala, yutufala i save talem wanem tok long olgeta we yutufala i wantem. Bambae yutufala i raetem long nem blong mi, nao yutufala i putum mak blong mi long hem, mo yutufala i sanem i goaot long nem blong mi.”"],[8,9,"Nao long namba tri manis blong yia ya, long manis ya Sivan,* long namba twanti tri dei blong hem, Modekae i singaot ol sekretari blong king oli kam, nao oli raetem wan leta long nem blong king. Leta ya i blong go long olgeta laen blong Isrel, wetem ol distrikejen* mo ol minista mo ol haeman blong king long ol wan handred twanti seven provins blong hem, i stat long kantri ya India long is, i go kasem kantri ya Itiopia long wes. Nao hem i gohed i stap toktok, mo olgeta oli stap raetemdaon ol tok blong hem, mo oli tanem tok ya i go long ol lanwis blong evri provins, mo oli raetem long ol fasin blong raet blong ol lanwis ya wanwan, mo oli tanem tu i go long lanwis ya Hibru* we i lanwis blong ol laen blong Isrel, mo oli raetem long fasin blong raet blong olgeta.","Nao long namba tri manis blong yia ya, long manis ya Sivan,* long namba twanti tri dei blong hem, Modekae i singaot ol sekretari blong king oli kam, nao oli raetem wan leta long nem blong king. Leta ya i blong go long olgeta laen blong Isrel, wetem ol distrikejen* mo ol minista mo ol haeman blong king long ol wan handred twanti seven provins blong hem, i stat long kantri ya India long is, i go kasem kantri ya Itiopia long wes. Nao hem i gohed i stap toktok, mo olgeta oli stap raetemdaon ol tok blong hem, mo oli tanem tok ya i go long ol lanwis blong evri provins, mo oli raetem long ol fasin blong raet blong ol lanwis ya wanwan, mo oli tanem tu i go long lanwis ya Hibru* we i lanwis blong ol laen blong Isrel, mo oli raetem long fasin blong raet blong olgeta."],[8,10,"Nao Modekae i talem long olgeta blong oli raetem ol leta ya long nem blong King Sekses, mo hem i putum mak blong king long olgeta. Nao ol man blong ron long hos oli tekem ol hos blong king we oli save ron strong, oli karem ol leta ya i go long evri ples.","Nao Modekae i talem long olgeta blong oli raetem ol leta ya long nem blong King Sekses, mo hem i putum mak blong king long olgeta. Nao ol man blong ron long hos oli tekem ol hos blong king we oli save ron strong, oli karem ol leta ya i go long evri ples."],[8,11,"Leta ya i talemaot long olgeta laen blong Isrel long evri taon, we king i talem se long dei ya we Haman i putum blong ol man bambae oli kam kilim olgeta i ded, bambae olgeta oli save kam wanples blong mekemrere blong faet blong sevem laef blong olgeta. Leta ya i talem se, “Long yia ya, long namba twelef manis, long manis ya Adara,* long namba totin dei blong hem, bambae yufala i save stap rere blong mekem faet. I nomata weples yufala i stap, long ol provins ya we mi mi stap rul long hem, be sipos i gat ol man we oli tekem ol samting blong faet, oli kam blong kilim yufala, bambae yufala i save go faet long olgeta. Long dei ya, bambae yufala i gat raet blong kilim olgeta oli ded, wetem ol woman blong olgeta mo ol pikinini blong olgeta, gogo olgeta oli ded evriwan, mo bambae yufala i save tekemaot olgeta samting we i blong olgeta, oli blong yufala. Hemia nao tok blong mi, we i kam long yufala evriwan, long olgeta provins we mi mi stap rul long hem.”","Leta ya i talemaot long olgeta laen blong Isrel long evri taon, we king i talem se long dei ya we Haman i putum blong ol man bambae oli kam kilim olgeta i ded, bambae olgeta oli save kam wanples blong mekemrere blong faet blong sevem laef blong olgeta. Leta ya i talem se, “Long yia ya, long namba twelef manis, long manis ya Adara,* long namba totin dei blong hem, bambae yufala i save stap rere blong mekem faet. I nomata weples yufala i stap, long ol provins ya we mi mi stap rul long hem, be sipos i gat ol man we oli tekem ol samting blong faet, oli kam blong kilim yufala, bambae yufala i save go faet long olgeta. Long dei ya, bambae yufala i gat raet blong kilim olgeta oli ded, wetem ol woman blong olgeta mo ol pikinini blong olgeta, gogo olgeta oli ded evriwan, mo bambae yufala i save tekemaot olgeta samting we i blong olgeta, oli blong yufala. Hemia nao tok blong mi, we i kam long yufala evriwan, long olgeta provins we mi mi stap rul long hem.”",12],[8,13,"Leta ya i talem long ol haeman blong king, blong oli talemaot tok ya long olgeta man long ol provins, se long dei ya, ol laen blong Isrel bambae oli save mekemrere blong faet long ol enemi blong olgeta.","Leta ya i talem long ol haeman blong king, blong oli talemaot tok ya long olgeta man long ol provins, se long dei ya, ol laen blong Isrel bambae oli save mekemrere blong faet long ol enemi blong olgeta."],[8,14,"Nao ol man blong ron long hos, oli karem ol leta ya, oli resis long ol hos blong king, oli spid i go blong givimaot tok ya olsem we king i talem, mo long bigfala taon ya Susa ol man oli talemaot tok ya, blong olgeta man i harem.","Nao ol man blong ron long hos, oli karem ol leta ya, oli resis long ol hos blong king, oli spid i go blong givimaot tok ya olsem we king i talem, mo long bigfala taon ya Susa ol man oli talemaot tok ya, blong olgeta man i harem."],[8,15,"Nao Modekae i putum ol spesel klos blong king we i blu mo i waet, mo i putum wan longfala kot tu we i pepol, mo i putum wan hat blong king we i flas gud, we oli wokem long gol. Mo olgeta man long evri ples long taon ya oli stap singsingaot bigwan, from we oli glad we oli glad.","Nao Modekae i putum ol spesel klos blong king we i blu mo i waet, mo i putum wan longfala kot tu we i pepol, mo i putum wan hat blong king we i flas gud, we oli wokem long gol. Mo olgeta man long evri ples long taon ya oli stap singsingaot bigwan, from we oli glad we oli glad."],[8,16,"Nao ol laen blong Isrel oli harem gud bakegen, oli glad we oli glad, from we oli haremsave se oli win finis.","Nao ol laen blong Isrel oli harem gud bakegen, oli glad we oli glad, from we oli haremsave se oli win finis."],[8,17,"Long olgeta provins mo long olgeta taon we oli talemaot tok ya blong king, ol laen blong Isrel oli holede, nao oli stap mekem lafet we oli glad we oli glad. Mo taem samting ya i hapen, plante narafala man oli kam laen blong Isrel, from we oli fraet long olgeta.","Long olgeta provins mo long olgeta taon we oli talemaot tok ya blong king, ol laen blong Isrel oli holede, nao oli stap mekem lafet we oli glad we oli glad. Mo taem samting ya i hapen, plante narafala man oli kam laen blong Isrel, from we oli fraet long olgeta."],[9,1,"Nao dei ya we Haman i putum, i kamtru. Fastaem, hem i talemaot long nem blong king, se long yia ya nomo, long namba twelef manis we nem blong hem Adara,* long namba totin dei blong hem, ol enemi blong ol laen* blong Isrel* bambae oli gat janis blong kilim olgeta oli ded. Be taem dei ya i kamtru, ol samting ya i jenis bigwan, nao ol laen blong Isrel oli kilim olgeta, oli winim olgeta.","Nao dei ya we Haman i putum, i kamtru. Fastaem, hem i talemaot long nem blong king, se long yia ya nomo, long namba twelef manis we nem blong hem Adara,* long namba totin dei blong hem, ol enemi blong ol laen* blong Isrel* bambae oli gat janis blong kilim olgeta oli ded. Be taem dei ya i kamtru, ol samting ya i jenis bigwan, nao ol laen blong Isrel oli kilim olgeta, oli winim olgeta."],[9,2,"Long evri taon we ol laen blong Isrel oli stap long hem, long olgeta kantri we king ya i stap rul long hem, olgeta oli mekemrere finis blong faet agens long ol man ya we oli wantem kilim olgeta. Be long evri ples, ol man oli fraet long olgeta, nao i no gat man we i naf blong go mekem faet long olgeta.","Long evri taon we ol laen blong Isrel oli stap long hem, long olgeta kantri we king ya i stap rul long hem, olgeta oli mekemrere finis blong faet agens long ol man ya we oli wantem kilim olgeta. Be long evri ples, ol man oli fraet long olgeta, nao i no gat man we i naf blong go mekem faet long olgeta."],[9,3,"Long olgeta provins, ol haeman blong gavman we hemia ol distrikejen,* mo ol minista, mo ol man blong king, olgeta evriwan oli stap givhan long ol laen blong Isrel, from we oli fraet long Modekae.","Long olgeta provins, ol haeman blong gavman we hemia ol distrikejen,* mo ol minista, mo ol man blong king, olgeta evriwan oli stap givhan long ol laen blong Isrel, from we oli fraet long Modekae."],[9,4,"Long evri ples we king i stap rul long hem, olgeta man oli save se naoia, king i putumap Modekae i kam wan haeman, mo oltaem, nem blong hem i stap kam antap moa.","Long evri ples we king i stap rul long hem, olgeta man oli save se naoia, king i putumap Modekae i kam wan haeman, mo oltaem, nem blong hem i stap kam antap moa."],[9,5,"Nao from samting ya, ol laen blong Isrel oli save mekem olsem we oli wantem long ol enemi ya blong olgeta. Nao oli tekem ol naef blong faet blong olgeta, oli go kilim ol man ya oli ded.","Nao from samting ya, ol laen blong Isrel oli save mekem olsem we oli wantem long ol enemi ya blong olgeta. Nao oli tekem ol naef blong faet blong olgeta, oli go kilim ol man ya oli ded."],[9,6,"Nao long bigfala taon ya Susa, we hedkwota blong king i stap long hem, ol laen blong Isrel oli kilim faef handred man oli ded.","Nao long bigfala taon ya Susa, we hedkwota blong king i stap long hem, ol laen blong Isrel oli kilim faef handred man oli ded."],[9,7,"Mo ol ten pikinini boe blong Haman, enemi ya blong olgeta, oli ded long taem ya. Nem blong olgeta, Pasandata, mo Dalfon, mo Aspata, mo Porata, mo Adalia, mo Aridata, mo Pamastaha, mo Arisae, mo Aridae mo Vaesata. Oli kilim ol ten man ya oli ded, be oli no karem olting blong olgeta.","Mo ol ten pikinini boe blong Haman, enemi ya blong olgeta, oli ded long taem ya. Nem blong olgeta, Pasandata, mo Dalfon, mo Aspata, mo Porata, mo Adalia, mo Aridata, mo Pamastaha, mo Arisae, mo Aridae mo Vaesata. Oli kilim ol ten man ya oli ded, be oli no karem olting blong olgeta.",10],[9,11,"Nao long sem dei ya, king i harem ripot blong namba blong ol man ya we oli ded long taon ya.","Nao long sem dei ya, king i harem ripot blong namba blong ol man ya we oli ded long taon ya."],[9,12,"Nao hem i talem long kwin se, “Esta. Long taon ya nomo, ol man ples blong yu oli kilim faef handred man oli ded, we ten long olgeta, ol ten pikinini ya blong Haman. Mo olbaot long ol provins, ating namba blong olgeta bambae i go moa, yumi no save. !Be nating! ?Tingting blong yu i olsem wanem? Sipos yu wantem wan samting moa, yu save talem. Wanem samting we yu askem bambae yu save kasem.”","Nao hem i talem long kwin se, “Esta. Long taon ya nomo, ol man ples blong yu oli kilim faef handred man oli ded, we ten long olgeta, ol ten pikinini ya blong Haman. Mo olbaot long ol provins, ating namba blong olgeta bambae i go moa, yumi no save. !Be nating! ?Tingting blong yu i olsem wanem? Sipos yu wantem wan samting moa, yu save talem. Wanem samting we yu askem bambae yu save kasem.”"],[9,13,"Nao kwin i talem se, “King. Sipos yu glad blong mekem olsem, plis yu letem olgeta ya oli mekem sem samting bakegen tumora long taon ya, olsem we oli mekem tede. Mo yu talem long ol man blong yu, blong oli hangem ol dedbodi blong ol ten pikinini ya blong Haman long ples blong hangem man.”","Nao kwin i talem se, “King. Sipos yu glad blong mekem olsem, plis yu letem olgeta ya oli mekem sem samting bakegen tumora long taon ya, olsem we oli mekem tede. Mo yu talem long ol man blong yu, blong oli hangem ol dedbodi blong ol ten pikinini ya blong Haman long ples blong hangem man.”"],[9,14,"Nao king i talemaot wan narafala tok blong hem long taon ya blong oli mekem olsem we kwin i talem. Mo ol man blong hem oli go hangem dedbodi blong ol ten pikinini ya blong Haman, blong ol man oli save luk.","Nao king i talemaot wan narafala tok blong hem long taon ya blong oli mekem olsem we kwin i talem. Mo ol man blong hem oli go hangem dedbodi blong ol ten pikinini ya blong Haman, blong ol man oli save luk."],[9,15,"Nao long namba fotin dei blong manis ya Adara, ol laen blong Isrel we oli stap long taon ya oli hivap wanples, nao oli kilim tri handred man bakegen long taon ya oli ded. Be bakegen, oli no karem olting blong olgeta.","Nao long namba fotin dei blong manis ya Adara, ol laen blong Isrel we oli stap long taon ya oli hivap wanples, nao oli kilim tri handred man bakegen long taon ya oli ded. Be bakegen, oli no karem olting blong olgeta."],[9,16,"Nao ol laen blong Isrel we oli stap olbaot long olgeta provins we king i stap rul long hem, olgeta tu oli mekemrere blong faet blong blokem ol man we oli wantem kam kilim olgeta. Oli kilim ol enemi ya blong olgeta we oli finisimgud olgeta, nao seventi faef taosen man oli ded. Be bakegen, oli no karem olting blong olgeta.","Nao ol laen blong Isrel we oli stap olbaot long olgeta provins we king i stap rul long hem, olgeta tu oli mekemrere blong faet blong blokem ol man we oli wantem kam kilim olgeta. Oli kilim ol enemi ya blong olgeta we oli finisimgud olgeta, nao seventi faef taosen man oli ded. Be bakegen, oli no karem olting blong olgeta."],[9,17,"Hemia long namba totin dei blong manis ya Adara. Be long nekis dei, long namba fotin, oli no moa kilim ol man. Long dei ya, olgeta oli stap mekem lafet we oli glad we oli glad.","Hemia long namba totin dei blong manis ya Adara. Be long nekis dei, long namba fotin, oli no moa kilim ol man. Long dei ya, olgeta oli stap mekem lafet we oli glad we oli glad."],[9,18,"Be ol laen blong Isrel we oli stap long Susa oli holede long namba fiftin, from we long namba totin mo namba fotin, oli stap mekem faet, nao long namba fiftin, oli jes mekem lafet.","Be ol laen blong Isrel we oli stap long Susa oli holede long namba fiftin, from we long namba totin mo namba fotin, oli stap mekem faet, nao long namba fiftin, oli jes mekem lafet."],[9,19,"Nao from samting ya, evri yia, ol laen blong Isrel we oli stap long ol vilej oli stap holem namba fotin dei blong manis ya se hem i dei we oli stap holede long hem we oli glad we oli glad. Evri famle oli stap mekem kakae, mo oli stap givgivim kakae long ol fren blong olgeta.","Nao from samting ya, evri yia, ol laen blong Isrel we oli stap long ol vilej oli stap holem namba fotin dei blong manis ya se hem i dei we oli stap holede long hem we oli glad we oli glad. Evri famle oli stap mekem kakae, mo oli stap givgivim kakae long ol fren blong olgeta."],[9,20,"Nao Modekae i raetemdaon stori blong ol samting ya, mo i raetem ol leta, i sanem i go long olgeta laen* blong Isrel* we oli stap olbaot long olgeta kantri we King Sekses i stap rul long hem,","Nao Modekae i raetemdaon stori blong ol samting ya, mo i raetem ol leta, i sanem i go long olgeta laen* blong Isrel* we oli stap olbaot long olgeta kantri we King Sekses i stap rul long hem,"],[9,21,"blong talemaot long olgeta, se bambae evri yia oli mas holede long tufala dei ya, namba fotin mo namba fiftin blong manis ya Adara.*","blong talemaot long olgeta, se bambae evri yia oli mas holede long tufala dei ya, namba fotin mo namba fiftin blong manis ya Adara.*"],[9,22,"Hemia tufala dei ya we ol laen blong Isrel oli kilim ol enemi blong olgeta, we oli flatemgud olgeta. Fastaem, tingting blong olgeta i foldaon olgeta, from we oli ting se long manis ya bambae oli sore tumas oli stap krae, be biaen, hem i kam wan taem we oli glad we oli glad. Modekae i talem long olgeta, se bambae oli mas glad long tufala dei ya, mo ol famle blong olgeta bambae oli mas mekem kakae, mo bambae oli mas givim kakae i go long ol fren blong olgeta, mo long ol puaman tu.","Hemia tufala dei ya we ol laen blong Isrel oli kilim ol enemi blong olgeta, we oli flatemgud olgeta. Fastaem, tingting blong olgeta i foldaon olgeta, from we oli ting se long manis ya bambae oli sore tumas oli stap krae, be biaen, hem i kam wan taem we oli glad we oli glad. Modekae i talem long olgeta, se bambae oli mas glad long tufala dei ya, mo ol famle blong olgeta bambae oli mas mekem kakae, mo bambae oli mas givim kakae i go long ol fren blong olgeta, mo long ol puaman tu."],[9,23,"Nao ol laen blong Isrel oli folem tok ya we Modekae i talem, mo oli mekem i kam wan kastom blong olgeta, we evri yia, oli stap mekem lafet long tufala dei ya.","Nao ol laen blong Isrel oli folem tok ya we Modekae i talem, mo oli mekem i kam wan kastom blong olgeta, we evri yia, oli stap mekem lafet long tufala dei ya."],[9,24,"Haman ya, we i enemi blong ol laen blong Isrel, hem i pikinini blong Hamedata, we i kamaot biaen long Agag. Hem i bin sakem ol spesel ston,* we long lanwis blong olgeta oli kolem purim, blong faenemaot se long wanem dei nao bambae oli kilim ol laen blong Isrel oli ded. Hem i mekem wan plan blong finisimgud olgeta, we bambae i no gat wan i stap.","Haman ya, we i enemi blong ol laen blong Isrel, hem i pikinini blong Hamedata, we i kamaot biaen long Agag. Hem i bin sakem ol spesel ston,* we long lanwis blong olgeta oli kolem purim, blong faenemaot se long wanem dei nao bambae oli kilim ol laen blong Isrel oli ded. Hem i mekem wan plan blong finisimgud olgeta, we bambae i no gat wan i stap."],[9,25,"Be Kwin Esta i go luk king from samting ya, nao king i mekem wan narafala tok we oli go talemaot long nem blong hem, nao plan ya blong Haman blong kilim olgeta laen blong Isrel evriwan oli ded i kakae hem bakegen, nao hem i ded from plan ya blong hem. Mo oli hangem hem mo ol pikinini blong hem long ples blong hangem man.","Be Kwin Esta i go luk king from samting ya, nao king i mekem wan narafala tok we oli go talemaot long nem blong hem, nao plan ya blong Haman blong kilim olgeta laen blong Isrel evriwan oli ded i kakae hem bakegen, nao hem i ded from plan ya blong hem. Mo oli hangem hem mo ol pikinini blong hem long ples blong hangem man."],[9,26,"Nao from samting ya, ol laen blong Isrel oli putum nem blong lafet ya, se “Lafet* blong Purim”, we hemia tok blong ol man Pesia bifo blong talem ol spesel ston ya. Nao from leta ya blong Modekae, mo from ol samting we i hapen long olgeta,","Nao from samting ya, ol laen blong Isrel oli putum nem blong lafet ya, se “Lafet* blong Purim”, we hemia tok blong ol man Pesia bifo blong talem ol spesel ston ya. Nao from leta ya blong Modekae, mo from ol samting we i hapen long olgeta,"],[9,27,"oli mekem wan rul bakegen we i blong olgeta, mo blong olgeta we bambae oli kamaot biaen long olgeta, mo ol narafala man we bambae oli wantem kam laen blong Isrel, se bambae oli mas holem tufala dei ya evri yia, long stret taem blong hem, olsem we Modekae i talem long leta ya blong hem.","oli mekem wan rul bakegen we i blong olgeta, mo blong olgeta we bambae oli kamaot biaen long olgeta, mo ol narafala man we bambae oli wantem kam laen blong Isrel, se bambae oli mas holem tufala dei ya evri yia, long stret taem blong hem, olsem we Modekae i talem long leta ya blong hem."],[9,28,"Mo olgeta man oli agri se ol pikinini blong olgeta we bambae oli stap kamaot biaen long olgeta, bambae oli mas tingbaot tufala dei ya blong Purim oltaem, nao long evri provins mo long evri taon, bambae oli mas holem lafet ya evri yia, gogo i no save finis.","Mo olgeta man oli agri se ol pikinini blong olgeta we bambae oli stap kamaot biaen long olgeta, bambae oli mas tingbaot tufala dei ya blong Purim oltaem, nao long evri provins mo long evri taon, bambae oli mas holem lafet ya evri yia, gogo i no save finis."],[9,29,"Nao Kwin Esta wetem Modekae, tufala i raetem wan leta bakegen blong soemaot we kwin i agri fulwan long leta ya we Modekae i raetem fastaem long saed blong Lafet ya blong Purim.","Nao Kwin Esta wetem Modekae, tufala i raetem wan leta bakegen blong soemaot we kwin i agri fulwan long leta ya we Modekae i raetem fastaem long saed blong Lafet ya blong Purim."],[9,30,"Tufala i sanem leta ya i go long olgeta laen blong Isrel we oli stap olbaot long wan handred twanti seven provins we king blong Pesia i stap rul long hem. Leta ya i talemaot we tufala i wantem we ol laen blong Isrel bambae oli stap gud, oli gat pis.","Tufala i sanem leta ya i go long olgeta laen blong Isrel we oli stap olbaot long wan handred twanti seven provins we king blong Pesia i stap rul long hem. Leta ya i talemaot we tufala i wantem we ol laen blong Isrel bambae oli stap gud, oli gat pis."],[9,31,"Mo i talem long olgeta, se olgeta wetem olgeta we bambae oli kamaot biaen long olgeta, bambae oli mas holemgud tufala dei ya blong Purim long stret taem blong hem, olsem nomo we oli stap holem ol rul blong ol narafala dei ya we oli dei blong livim kakae blong olgeta, no oli dei blong harem nogud from we man i ded. Modekae mo Esta, tufala i putum rul ya.","Mo i talem long olgeta, se olgeta wetem olgeta we bambae oli kamaot biaen long olgeta, bambae oli mas holemgud tufala dei ya blong Purim long stret taem blong hem, olsem nomo we oli stap holem ol rul blong ol narafala dei ya we oli dei blong livim kakae blong olgeta, no oli dei blong harem nogud from we man i ded. Modekae mo Esta, tufala i putum rul ya."],[9,32,"Nao tok ya blong Kwin Esta i mekem ol rul blong Lafet ya Purim i stanap, mo ol man oli raetemdaon long wan buk.*","Nao tok ya blong Kwin Esta i mekem ol rul blong Lafet ya Purim i stanap, mo ol man oli raetemdaon long wan buk.*"],[10,1,"King Sekses i putum wan loa se olgeta man we hem i stap rulum olgeta, nating we oli stap klosap long solwota, no oli stap long bus, bambae oli mas wok blong leftemap laef blong kingdom blong hem, mo oltaem hem i stap fosem olgeta blong oli mekem olsem.","King Sekses i putum wan loa se olgeta man we hem i stap rulum olgeta, nating we oli stap klosap long solwota, no oli stap long bus, bambae oli mas wok blong leftemap laef blong kingdom blong hem, mo oltaem hem i stap fosem olgeta blong oli mekem olsem."],[10,2,"Ol gudgudfala samting we hem i wokem we oli stap soemaot hae nem blong hem, wetem stori blong ol samting we i mekem long Modekae, laen* ya blong Isrel* we hem i givim hae nem long hem, oli raetem evriwan long buk ya we nem blong hem Ol Stori blong ol King blong Pesia mo Media.","Ol gudgudfala samting we hem i wokem we oli stap soemaot hae nem blong hem, wetem stori blong ol samting we i mekem long Modekae, laen* ya blong Isrel* we hem i givim hae nem long hem, oli raetem evriwan long buk ya we nem blong hem Ol Stori blong ol King blong Pesia mo Media."],[10,3,"Modekae i praeminista blong King Sekses, mo ol man ples blong hem oli glad tumas long hem, mo oltaem oli stap ona gud long hem. Hem i wan man we i wok strong blong mekem ol man ples blong hem oli stap gud, mo blong olgeta we bambae oli stap kamaot biaen long olgeta oli save stap gud oltaem nomo.","Modekae i praeminista blong King Sekses, mo ol man ples blong hem oli glad tumas long hem, mo oltaem oli stap ona gud long hem. Hem i wan man we i wok strong blong mekem ol man ples blong hem oli stap gud, mo blong olgeta we bambae oli stap kamaot biaen long olgeta oli save stap gud oltaem nomo."]],"hbo-wlc":[[1,1,"וַיְהִ֖י בִּימֵ֣י אֲחַשְׁוֵר֑וֹשׁ ה֣וּא אֲחַשְׁוֵר֗וֹשׁ הַמֹּלֵךְ֙ מֵהֹ֣דּוּ וְעַד־כּ֔וּשׁ שֶׁ֛בַע וְעֶשְׂרִ֥ים וּמֵאָ֖ה מְדִינָֽה׃","wayĕhi֖y bi̇ymé֣y ʼàẖaşĕ̌wér֑wòş̌ h֣ẇʼ ʼàẖaşĕ̌wér֗wòş̌ hamò̇lékĕ֙ méhò֣ḋẇ wĕʻad-k̇֔ẇş̌ şě֛baʻ wĕʻeşĕ̂ri֥ym ẇméʼá֖h mĕdiynáֽh׃"],[1,2,"בַּיָּמִ֖ים הָהֵ֑ם כְּשֶׁ֣בֶת ׀ הַמֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ עַ֚ל כִּסֵּ֣א מַלְכוּת֔וֹ אֲשֶׁ֖ר בְּשׁוּשַׁ֥ן הַבִּירָֽה׃","bȧyá̇mi֖ym háhé֑m kĕ̇şě֣beţ ׀ hamė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ ʻa֚l ki̇sé֣̇ʼ malĕkẇţ֔wò ʼàşě֖r bĕ̇ş̌ẇşǎ֥n habi̇yráֽh׃"],[1,3,"בִּשְׁנַ֤ת שָׁלוֹשׁ֙ לְמָלְכ֔וֹ עָשָׂ֣ה מִשְׁתֶּ֔ה לְכָל־שָׂרָ֖יו וַעֲבָדָ֑יו חֵ֣יל ׀ פָּרַ֣ס וּמָדַ֗י הַֽפַּרְתְּמִ֛ים וְשָׂרֵ֥י הַמְּדִינ֖וֹת לְפָנָֽיו׃","bi̇şĕ̌na֤ţ şá̌lwòş̌֙ lĕmálĕk֔wò ʻáşá֣̂h mişĕ̌ţė֔h lĕkál-şá̂rá֖yw waʻàbádá֑yw ẖé֣yl ׀ pá̇ra֣s ẇmáda֗y haֽpȧrĕţĕ̇mi֛ym wĕşá̂ré֥y hamĕ̇diyn֖wòţ lĕpánáֽyw׃"],[1,4,"בְּהַרְאֹת֗וֹ אֶת־עֹ֙שֶׁר֙ כְּב֣וֹד מַלְכוּת֔וֹ וְאֶ֨ת־יְקָ֔ר תִּפְאֶ֖רֶת גְּדוּלָּת֑וֹ יָמִ֣ים רַבִּ֔ים שְׁמוֹנִ֥ים וּמְאַ֖ת יֽוֹם׃","bĕ̇harĕʼòţ֗wò ʼeţ-ʻò֙şěr֙ kĕ̇b֣wòd malĕkẇţ֔wò wĕʼe֨ţ-yĕqá֔r ţi̇pĕʼe֖reţ gĕ̇dẇlá̇ţ֑wò yámi֣ym rabi̇֔ym şĕ̌mwòni֥ym ẇmĕʼa֖ţ yֽwòm׃"],[1,5,"וּבִמְל֣וֹאת ׀ הַיָּמִ֣ים הָאֵ֗לֶּה עָשָׂ֣ה הַמֶּ֡לֶךְ לְכָל־הָעָ֣ם הַנִּמְצְאִים֩ בְּשׁוּשַׁ֨ן הַבִּירָ֜ה לְמִגָּ֧דוֹל וְעַד־קָטָ֛ן מִשְׁתֶּ֖ה שִׁבְעַ֣ת יָמִ֑ים בַּחֲצַ֕ר גִּנַּ֥ת בִּיתַ֖ן הַמֶּֽלֶךְ׃","ẇbimĕl֣wòʼţ ׀ hayá̇mi֣ym háʼé֗lėh ʻáşá֣̂h hamė֡lekĕ lĕkál-háʻá֣m hani̇mĕẕĕʼiym֩ bĕ̇ş̌ẇşǎ֨n habi̇yrá֜h lĕmigá֧̇dwòl wĕʻad-qátá֛n mişĕ̌ţė֖h şǐbĕʻa֣ţ yámi֑ym bȧẖàẕa֕r gi̇nȧ֥ţ bi̇yţa֖n hamėֽlekĕ׃"],[1,6,"ח֣וּר ׀ כַּרְפַּ֣ס וּתְכֵ֗לֶת אָחוּז֙ בְּחַבְלֵי־ב֣וּץ וְאַרְגָּמָ֔ן עַל־גְּלִ֥ילֵי כֶ֖סֶף וְעַמּ֣וּדֵי שֵׁ֑שׁ מִטּ֣וֹת ׀ זָהָ֣ב וָכֶ֗סֶף עַ֛ל רִֽצְפַ֥ת בַּהַט־וָשֵׁ֖שׁ וְדַ֥ר וְסֹחָֽרֶת׃","ẖ֣ẇr ׀ kȧrĕpȧ֣s ẇţĕké֗leţ ʼáẖẇz֙ bĕ̇ẖabĕléy-b֣ẇẕ wĕʼarĕgá̇má֔n ʻal-gĕ̇li֥yléy ke֖sep wĕʻaṁ֣ẇdéy şé֑̌ş̌ miṫ֣wòţ ׀ záhá֣b wáke֗sep ʻa֛l riֽẕĕpa֥ţ bȧhat-wáşé֖̌ş̌ wĕda֥r wĕsòẖáֽreţ׃"],[1,7,"וְהַשְׁקוֹת֙ בִּכְלֵ֣י זָהָ֔ב וְכֵלִ֖ים מִכֵּלִ֣ים שׁוֹנִ֑ים וְיֵ֥ין מַלְכ֛וּת רָ֖ב כְּיַ֥ד הַמֶּֽלֶךְ׃","wĕhaşĕ̌qwòţ֙ bi̇kĕlé֣y záhá֔b wĕkéli֖ym miké̇li֣ym ş̌wòni֑ym wĕyé֥yn malĕk֛ẇţ rá֖b kĕ̇ya֥d hamėֽlekĕ׃"],[1,8,"וְהַשְּׁתִיָּ֥ה כַדָּ֖ת אֵ֣ין אֹנֵ֑ס כִּי־כֵ֣ן ׀ יִסַּ֣ד הַמֶּ֗לֶךְ עַ֚ל כָּל־רַ֣ב בֵּית֔וֹ לַעֲשׂ֖וֹת כִּרְצ֥וֹן אִישׁ־וָאִֽישׁ׃","wĕhaşĕ̇̌ţiyá֥̇h kadá֖̇ţ ʼé֣yn ʼòné֑s ki̇y-ké֣n ׀ yisȧ֣d hamė֗lekĕ ʻa֚l ká̇l-ra֣b bé̇yţ֔wò laʻàş֖̂wòţ ki̇rĕẕ֥wòn ʼiyş̌-wáʼiֽyş̌׃"],[1,9,"גַּ֚ם וַשְׁתִּ֣י הַמַּלְכָּ֔ה עָשְׂתָ֖ה מִשְׁתֵּ֣ה נָשִׁ֑ים בֵּ֚ית הַמַּלְכ֔וּת אֲשֶׁ֖ר לַמֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃ ס","gȧ֚m waşĕ̌ţi֣̇y hamȧlĕká̇֔h ʻáşĕ̂ţá֖h mişĕ̌ţé֣̇h náşǐ֑ym bé֚̇yţ hamȧlĕk֔ẇţ ʼàşě֖r lamė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃ s"],[1,10,"בַּיּוֹם֙ הַשְּׁבִיעִ֔י כְּט֥וֹב לֵב־הַמֶּ֖לֶךְ בַּיָּ֑יִן אָמַ֡ר לִ֠מְהוּמָן בִּזְּתָ֨א חַרְבוֹנָ֜א בִּגְתָ֤א וַאֲבַגְתָא֙ זֵתַ֣ר וְכַרְכַּ֔ס שִׁבְעַת֙ הַסָּ֣רִיסִ֔ים הַמְשָׁ֣רְתִ֔ים אֶת־פְּנֵ֖י הַמֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","bȧẏwòm֙ haşĕ̇̌biyʻi֔y kĕ̇t֥wòb léb-hamė֖lekĕ bȧyá֑̇yin ʼáma֡r li֠mĕhẇmán bi̇zĕ̇ţá֨ʼ ẖarĕbwòná֜ʼ bi̇gĕţá֤ʼ waʼàbagĕţáʼ֙ zéţa֣r wĕkarĕkȧ֔s şǐbĕʻaţ֙ hasá֣̇riysi֔ym hamĕşá֣̌rĕţi֔ym ʼeţ-pĕ̇né֖y hamė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,11,"לְ֠הָבִיא אֶת־וַשְׁתִּ֧י הַמַּלְכָּ֛ה לִפְנֵ֥י הַמֶּ֖לֶךְ בְּכֶ֣תֶר מַלְכ֑וּת לְהַרְא֨וֹת הָֽעַמִּ֤ים וְהַשָּׂרִים֙ אֶת־יָפְיָ֔הּ כִּֽי־טוֹבַ֥ת מַרְאֶ֖ה הִֽיא׃","lĕ֠hábiyʼ ʼeţ-waşĕ̌ţi֧̇y hamȧlĕká֛̇h lipĕné֥y hamė֖lekĕ bĕ̇ke֣ţer malĕk֑ẇţ lĕharĕʼ֨wòţ háֽʻami֤̇ym wĕhaşá̇̂riym֙ ʼeţ-yápĕyá֔ḣ kiֽ̇y-twòba֥ţ marĕʼe֖h hiֽyʼ׃"],[1,12,"וַתְּמָאֵ֞ן הַמַּלְכָּ֣ה וַשְׁתִּ֗י לָבוֹא֙ בִּדְבַ֣ר הַמֶּ֔לֶךְ אֲשֶׁ֖ר בְּיַ֣ד הַסָּרִיסִ֑ים וַיִּקְצֹ֤ף הַמֶּ֙לֶךְ֙ מְאֹ֔ד וַחֲמָת֖וֹ בָּעֲרָ֥ה בֽוֹ׃","waţĕ̇máʼé֞n hamȧlĕká֣̇h waşĕ̌ţi̇֗y lábwòʼ֙ bi̇dĕba֣r hamė֔lekĕ ʼàşě֖r bĕ̇ya֣d hasá̇riysi֑ym wayi̇qĕẕò֤p hamė֙lekĕ֙ mĕʼò֔d waẖàmáţ֖wò bá̇ʻàrá֥h bֽwò׃"],[1,13,"וַיֹּ֣אמֶר הַמֶּ֔לֶךְ לַחֲכָמִ֖ים יֹדְעֵ֣י הָֽעִתִּ֑ים כִּי־כֵן֙ דְּבַ֣ר הַמֶּ֔לֶךְ לִפְנֵ֕י כָּל־יֹדְעֵ֖י דָּ֥ת וָדִֽין׃","wayò֣̇ʼmer hamė֔lekĕ laẖàkámi֖ym yòdĕʻé֣y hֽáʻiţi֑̇ym ki̇y-kén֙ dĕ̇ba֣r hamė֔lekĕ lipĕné֕y ká̇l-yòdĕʻé֖y dá֥̇ţ wádiֽyn׃"],[1,14,"וְהַקָּרֹ֣ב אֵלָ֗יו כַּרְשְׁנָ֤א שֵׁתָר֙ אַדְמָ֣תָא תַרְשִׁ֔ישׁ מֶ֥רֶס מַרְסְנָ֖א מְמוּכָ֑ן שִׁבְעַ֞ת שָׂרֵ֣י ׀ פָּרַ֣ס וּמָדַ֗י רֹאֵי֙ פְּנֵ֣י הַמֶּ֔לֶךְ הַיֹּשְׁבִ֥ים רִאשֹׁנָ֖ה בַּמַּלְכֽוּת׃","wĕhaqá̇rò֣b ʼélá֗yw kȧrĕşĕ̌ná֤ʼ şé̌ţár֙ ʼadĕmá֣ţáʼ ţarĕşǐ֔yş̌ me֥res marĕsĕná֖ʼ mĕmẇká֑n şǐbĕʻa֞ţ şá̂ré֣y ׀ pá̇ra֣s ẇmáda֗y ròʼéy֙ pĕ̇né֣y hamė֔lekĕ hayò̇şĕ̌bi֥ym riʼşò̌ná֖h bȧmȧlĕkֽẇţ׃"],[1,15,"כְּדָת֙ מַֽה־לַּעֲשׂ֔וֹת בַּמַּלְכָּ֖ה וַשְׁתִּ֑י עַ֣ל ׀ אֲשֶׁ֣ר לֹֽא־עָשְׂתָ֗ה אֶֽת־מַאֲמַר֙ הַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ בְּיַ֖ד הַסָּרִיסִֽים׃ ס","kĕ̇dáţ֙ maֽh-lȧʻàş̂֔wòţ bȧmȧlĕká֖̇h waşĕ̌ţi֑̇y ʻa֣l ׀ ʼàşě֣r lòֽʼ-ʻáşĕ̂ţá֗h ʼeֽţ-maʼàmar֙ hamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ bĕ̇ya֖d hasá̇riysiֽym׃ s"],[1,16,"וַיֹּ֣אמֶר מומכן לִפְנֵ֤י הַמֶּ֙לֶךְ֙ וְהַשָּׂרִ֔ים לֹ֤א עַל־הַמֶּ֙לֶךְ֙ לְבַדּ֔וֹ עָוְתָ֖ה וַשְׁתִּ֣י הַמַּלְכָּ֑ה כִּ֤י עַל־כָּל־הַשָּׂרִים֙ וְעַל־כָּל־הָ֣עַמִּ֔ים אֲשֶׁ֕ר בְּכָל־מְדִינ֖וֹת הַמֶּ֥לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wayò֣̇ʼmer mwmkn lipĕné֤y hamė֙lekĕ֙ wĕhaşá̇̂ri֔ym lò֤ʼ ʻal-hamė֙lekĕ֙ lĕbaḋ֔wò ʻáwĕţá֖h waşĕ̌ţi֣̇y hamȧlĕká֑̇h ki֤̇y ʻal-ká̇l-haşá̇̂riym֙ wĕʻal-ká̇l-há֣ʻami̇֔ym ʼàşě֕r bĕ̇kál-mĕdiyn֖wòţ hamė֥lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[1,17,"כִּֽי־יֵצֵ֤א דְבַר־הַמַּלְכָּה֙ עַל־כָּל־הַנָּשִׁ֔ים לְהַבְז֥וֹת בַּעְלֵיהֶ֖ן בְּעֵינֵיהֶ֑ן בְּאָמְרָ֗ם הַמֶּ֣לֶךְ אֲחַשְׁוֵר֡וֹשׁ אָמַ֞ר לְהָבִ֨יא אֶת־וַשְׁתִּ֧י הַמַּלְכָּ֛ה לְפָנָ֖יו וְלֹא־בָֽאָה׃","kiֽ̇y-yéẕé֤ʼ dĕbar-hamȧlĕká̇h֙ ʻal-ká̇l-haná̇şǐ֔ym lĕhabĕz֥wòţ bȧʻĕléyhe֖n bĕ̇ʻéynéyhe֑n bĕ̇ʼámĕrá֗m hamė֣lekĕ ʼàẖaşĕ̌wér֡wòş̌ ʼáma֞r lĕhábi֨yʼ ʼeţ-waşĕ̌ţi֧̇y hamȧlĕká֛̇h lĕpáná֖yw wĕlòʼ-báֽʼáh׃"],[1,18,"וְֽהַיּ֨וֹם הַזֶּ֜ה תֹּאמַ֣רְנָה ׀ שָׂר֣וֹת פָּֽרַס־וּמָדַ֗י אֲשֶׁ֤ר שָֽׁמְעוּ֙ אֶת־דְּבַ֣ר הַמַּלְכָּ֔ה לְכֹ֖ל שָׂרֵ֣י הַמֶּ֑לֶךְ וּכְדַ֖י בִּזָּי֥וֹן וָקָֽצֶף׃","wĕֽhaẏ֨wòm hazė֜h ţò̇ʼma֣rĕnáh ׀ şá̂r֣wòţ páֽ̇ras-ẇmáda֗y ʼàşě֤r şáֽ̌mĕʻẇ֙ ʼeţ-dĕ̇ba֣r hamȧlĕká̇֔h lĕkò֖l şá̂ré֣y hamė֑lekĕ ẇkĕda֖y bi̇zá̇y֥wòn wáqáֽẕep׃"],[1,19,"אִם־עַל־הַמֶּ֣לֶךְ ט֗וֹב יֵצֵ֤א דְבַר־מַלְכוּת֙ מִלְּפָנָ֔יו וְיִכָּתֵ֛ב בְּדָתֵ֥י פָֽרַס־וּמָדַ֖י וְלֹ֣א יַעֲב֑וֹר אֲשֶׁ֨ר לֹֽא־תָב֜וֹא וַשְׁתִּ֗י לִפְנֵי֙ הַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וּמַלְכוּתָהּ֙ יִתֵּ֣ן הַמֶּ֔לֶךְ לִרְעוּתָ֖הּ הַטּוֹבָ֥ה מִמֶּֽנָּה׃","ʼim-ʻal-hamė֣lekĕ t֗wòb yéẕé֤ʼ dĕbar-malĕkẇţ֙ milĕ̇páná֔yw wĕyiká̇ţé֛b bĕ̇dáţé֥y páֽras-ẇmáda֖y wĕlò֣ʼ yaʻàb֑wòr ʼàşě֨r lòֽʼ-ţáb֜wòʼ waşĕ̌ţi̇֗y lipĕnéy֙ hamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ ẇmalĕkẇţáḣ֙ yiţé֣̇n hamė֔lekĕ lirĕʻẇţá֖ḣ haṫwòbá֥h mimėֽná̇h׃"],[1,20,"וְנִשְׁמַע֩ פִּתְגָ֨ם הַמֶּ֤לֶךְ אֲשֶֽׁר־יַעֲשֶׂה֙ בְּכָל־מַלְכוּת֔וֹ כִּ֥י רַבָּ֖ה הִ֑יא וְכָל־הַנָּשִׁ֗ים יִתְּנ֤וּ יְקָר֙ לְבַעְלֵיהֶ֔ן לְמִגָּד֖וֹל וְעַד־קָטָֽן׃","wĕnişĕ̌maʻ֩ pi̇ţĕgá֨m hamė֤lekĕ ʼàşěֽr-yaʻàşêh֙ bĕ̇kál-malĕkẇţ֔wò ki֥̇y rabá֖̇h hi֑yʼ wĕkál-haná̇şǐ֗ym yiţĕ̇n֤ẇ yĕqár֙ lĕbaʻĕléyhe֔n lĕmigá̇d֖wòl wĕʻad-qátáֽn׃"],[1,21,"וַיִּיטַב֙ הַדָּבָ֔ר בְּעֵינֵ֥י הַמֶּ֖לֶךְ וְהַשָּׂרִ֑ים וַיַּ֥עַשׂ הַמֶּ֖לֶךְ כִּדְבַ֥ר מְמוּכָֽן׃","wayi̇ytab֙ hadá̇bá֔r bĕ̇ʻéyné֥y hamė֖lekĕ wĕhaşá̇̂ri֑ym wayȧ֥ʻaş̂ hamė֖lekĕ ki̇dĕba֥r mĕmẇkáֽn׃"],[1,22,"וַיִּשְׁלַ֤ח סְפָרִים֙ אֶל־כָּל־מְדִינ֣וֹת הַמֶּ֔לֶךְ אֶל־מְדִינָ֤ה וּמְדִינָה֙ כִּכְתָבָ֔הּ וְאֶל־עַ֥ם וָעָ֖ם כִּלְשׁוֹנ֑וֹ לִהְי֤וֹת כָּל־אִישׁ֙ שֹׂרֵ֣ר בְּבֵית֔וֹ וּמְדַבֵּ֖ר כִּלְשׁ֥וֹן עַמּֽוֹ׃ פ","wayi̇şĕ̌la֤ẖ sĕpáriym֙ ʼel-ká̇l-mĕdiyn֣wòţ hamė֔lekĕ ʼel-mĕdiyná֤h ẇmĕdiynáh֙ ki̇kĕţábá֔ḣ wĕʼel-ʻa֥m wáʻá֖m ki̇lĕş̌wòn֑wò lihĕy֤wòţ ká̇l-ʼiyş̌֙ şò̂ré֣r bĕ̇béyţ֔wò ẇmĕdabé֖̇r ki̇lĕş֥̌wòn ʻaṁֽwò׃ p"],[2,1,"אַחַר֙ הַדְּבָרִ֣ים הָאֵ֔לֶּה כְּשֹׁ֕ךְ חֲמַ֖ת הַמֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ זָכַ֤ר אֶת־וַשְׁתִּי֙ וְאֵ֣ת אֲשֶׁר־עָשָׂ֔תָה וְאֵ֥ת אֲשֶׁר־נִגְזַ֖ר עָלֶֽיהָ׃","ʼaẖar֙ hadĕ̇bári֣ym háʼé֔lėh kĕ̇şò̌֕kĕ ẖàma֖ţ hamė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ záka֤r ʼeţ-waşĕ̌ţi̇y֙ wĕʼé֣ţ ʼàşěr-ʻáşá̂֔ţáh wĕʼé֥ţ ʼàşěr-nigĕza֖r ʻáleֽyhá׃"],[2,2,"וַיֹּאמְר֥וּ נַעֲרֵֽי־הַמֶּ֖לֶךְ מְשָׁרְתָ֑יו יְבַקְשׁ֥וּ לַמֶּ֛לֶךְ נְעָר֥וֹת בְּתוּל֖וֹת טוֹב֥וֹת מַרְאֶֽה׃","wayò̇ʼmĕr֥ẇ naʻàréֽy-hamė֖lekĕ mĕşá̌rĕţá֑yw yĕbaqĕş֥̌ẇ lamė֛lekĕ nĕʻár֥wòţ bĕ̇ţẇl֖wòţ twòb֥wòţ marĕʼeֽh׃"],[2,3,"וְיַפְקֵ֨ד הַמֶּ֣לֶךְ פְּקִידִים֮ בְּכָל־מְדִינ֣וֹת מַלְכוּתוֹ֒ וְיִקְבְּצ֣וּ אֶת־כָּל־נַעֲרָֽה־בְ֠תוּלָה טוֹבַ֨ת מַרְאֶ֜ה אֶל־שׁוּשַׁ֤ן הַבִּירָה֙ אֶל־בֵּ֣ית הַנָּשִׁ֔ים אֶל־יַ֥ד הֵגֶ֛א סְרִ֥יס הַמֶּ֖לֶךְ שֹׁמֵ֣ר הַנָּשִׁ֑ים וְנָת֖וֹן תַּמְרוּקֵיהֶֽן׃","wĕyapĕqé֨d hamė֣lekĕ pĕ̇qiydiym֮ bĕ̇kál-mĕdiyn֣wòţ malĕkẇţwò֒ wĕyiqĕbĕ̇ẕ֣ẇ ʼeţ-ká̇l-naʻàráֽh-bĕ֠ţẇláh twòba֨ţ marĕʼe֜h ʼel-ş̌ẇşǎ֤n habi̇yráh֙ ʼel-bé֣̇yţ haná̇şǐ֔ym ʼel-ya֥d hége֛ʼ sĕri֥ys hamė֖lekĕ şò̌mé֣r haná̇şǐ֑ym wĕnáţ֖wòn ţȧmĕrẇqéyheֽn׃"],[2,4,"וְהַֽנַּעֲרָ֗ה אֲשֶׁ֤ר תִּיטַב֙ בְּעֵינֵ֣י הַמֶּ֔לֶךְ תִּמְלֹ֖ךְ תַּ֣חַת וַשְׁתִּ֑י וַיִּיטַ֧ב הַדָּבָ֛ר בְּעֵינֵ֥י הַמֶּ֖לֶךְ וַיַּ֥עַשׂ כֵּֽן׃ ס","wĕhaֽnȧʻàrá֗h ʼàşě֤r ţi̇ytab֙ bĕ̇ʻéyné֣y hamė֔lekĕ ţi̇mĕlò֖kĕ ţȧ֣ẖaţ waşĕ̌ţi֑̇y wayi̇yta֧b hadá̇bá֛r bĕ̇ʻéyné֥y hamė֖lekĕ wayȧ֥ʻaş̂ kéֽ̇n׃ s"],[2,5,"אִ֣ישׁ יְהוּדִ֔י הָיָ֖ה בְּשׁוּשַׁ֣ן הַבִּירָ֑ה וּשְׁמ֣וֹ מָרְדֳּכַ֗י בֶּ֣ן יָאִ֧יר בֶּן־שִׁמְעִ֛י בֶּן־קִ֖ישׁ אִ֥ישׁ יְמִינִֽי׃","ʼi֣yş̌ yĕhẇdi֔y háyá֖h bĕ̇ş̌ẇşǎ֣n habi̇yrá֑h ẇşĕ̌m֣wò márĕdȯka֗y bė֣n yáʼi֧yr bėn-şǐmĕʻi֛y bėn-qi֖yş̌ ʼi֥yş̌ yĕmiyniֽy׃"],[2,6,"אֲשֶׁ֤ר הָגְלָה֙ מִיר֣וּשָׁלַ֔יִם עִם־הַגֹּלָה֙ אֲשֶׁ֣ר הָגְלְתָ֔ה עִ֖ם יְכָנְיָ֣ה מֶֽלֶךְ־יְהוּדָ֑ה אֲשֶׁ֣ר הֶגְלָ֔ה נְבוּכַדְנֶאצַּ֖ר מֶ֥לֶךְ בָּבֶֽל׃","ʼàşě֤r hágĕláh֙ miyr֣ẇşá̌la֔yim ʻim-hagò̇láh֙ ʼàşě֣r hágĕlĕţá֔h ʻi֖m yĕkánĕyá֣h meֽlekĕ-yĕhẇdá֑h ʼàşě֣r hegĕlá֔h nĕbẇkadĕneʼẕȧ֖r me֥lekĕ bá̇beֽl׃"],[2,7,"וַיְהִ֨י אֹמֵ֜ן אֶת־הֲדַסָּ֗ה הִ֤יא אֶסְתֵּר֙ בַּת־דֹּד֔וֹ כִּ֛י אֵ֥ין לָ֖הּ אָ֣ב וָאֵ֑ם וְהַנַּעֲרָ֤ה יְפַת־תֹּ֙אַר֙ וְטוֹבַ֣ת מַרְאֶ֔ה וּבְמ֤וֹת אָבִ֙יהָ֙ וְאִמָּ֔הּ לְקָחָ֧הּ מָרְדֳּכַ֛י ל֖וֹ לְבַֽת׃","wayĕhi֨y ʼòmé֜n ʼeţ-hàdasá̇֗h hi֤yʼ ʼesĕţé̇r֙ bȧţ-dò̇d֔wò ki֛̇y ʼé֥yn lá֖ḣ ʼá֣b wáʼé֑m wĕhanȧʻàrá֤h yĕpaţ-ţò̇֙ʼar֙ wĕtwòba֣ţ marĕʼe֔h ẇbĕm֤wòţ ʼábi֙yhá֙ wĕʼimá̇֔ḣ lĕqáẖá֧ḣ márĕdȯka֛y l֖wò lĕbaֽţ׃"],[2,8,"וַיְהִ֗י בְּהִשָּׁמַ֤ע דְּבַר־הַמֶּ֙לֶךְ֙ וְדָת֔וֹ וּֽבְהִקָּבֵ֞ץ נְעָר֥וֹת רַבּ֛וֹת אֶל־שׁוּשַׁ֥ן הַבִּירָ֖ה אֶל־יַ֣ד הֵגָ֑י וַתִּלָּקַ֤ח אֶסְתֵּר֙ אֶל־בֵּ֣ית הַמֶּ֔לֶךְ אֶל־יַ֥ד הֵגַ֖י שֹׁמֵ֥ר הַנָּשִֽׁים׃","wayĕhi֗y bĕ̇hişá̇̌ma֤ʻ dĕ̇bar-hamė֙lekĕ֙ wĕdáţ֔wò ẇֽbĕhiqá̇bé֞ẕ nĕʻár֥wòţ raḃ֛wòţ ʼel-ş̌ẇşǎ֥n habi̇yrá֖h ʼel-ya֣d hégá֑y waţi̇lá̇qa֤ẖ ʼesĕţé̇r֙ ʼel-bé֣̇yţ hamė֔lekĕ ʼel-ya֥d héga֖y şò̌mé֥r haná̇şǐֽym׃"],[2,9,"וַתִּיטַ֨ב הַנַּעֲרָ֣ה בְעֵינָיו֮ וַתִּשָּׂ֣א חֶ֣סֶד לְפָנָיו֒ וַ֠יְבַהֵל אֶת־תַּמְרוּקֶ֤יהָ וְאֶת־מָנוֹתֶ֙הָ֙ לָתֵ֣ת לָ֔הּ וְאֵת֙ שֶׁ֣בַע הַנְּעָר֔וֹת הָרְאֻי֥וֹת לָֽתֶת־לָ֖הּ מִבֵּ֣ית הַמֶּ֑לֶךְ וַיְשַׁנֶּ֧הָ וְאֶת־נַעֲרוֹתֶ֛יהָ לְט֖וֹב בֵּ֥ית הַנָּשִֽׁים׃","waţi̇yta֨b hanȧʻàrá֣h bĕʻéynáyw֮ waţi̇şá֣̇̂ʼ ẖe֣sed lĕpánáyw֒ wa֠yĕbahél ʼeţ-ţȧmĕrẇqe֤yhá wĕʼeţ-mánwòţe֙há֙ láţé֣ţ lá֔ḣ wĕʼéţ֙ şě֣baʻ hanĕ̇ʻár֔wòţ hárĕʼuy֥wòţ láֽţeţ-lá֖ḣ mibé֣̇yţ hamė֑lekĕ wayĕşǎnė֧há wĕʼeţ-naʻàrwòţe֛yhá lĕt֖wòb bé֥̇yţ haná̇şǐֽym׃"],[2,10,"לֹא־הִגִּ֣ידָה אֶסְתֵּ֔ר אֶת־עַמָּ֖הּ וְאֶת־מֽוֹלַדְתָּ֑הּ כִּ֧י מָרְדֳּכַ֛י צִוָּ֥ה עָלֶ֖יהָ אֲשֶׁ֥ר לֹא־תַגִּֽיד׃","lòʼ-higi֣̇ydáh ʼesĕţé̇֔r ʼeţ-ʻamá֖̇ḣ wĕʼeţ-mֽwòladĕţá֑̇ḣ ki֧̇y márĕdȯka֛y ẕiwá֥̇h ʻále֖yhá ʼàşě֥r lòʼ-ţagiֽ̇yd׃"],[2,11,"וּבְכָל־י֣וֹם וָי֔וֹם מָרְדֳּכַי֙ מִתְהַלֵּ֔ךְ לִפְנֵ֖י חֲצַ֣ר בֵּית־הַנָּשִׁ֑ים לָדַ֙עַת֙ אֶת־שְׁל֣וֹם אֶסְתֵּ֔ר וּמַה־יֵּעָשֶׂ֖ה בָּֽהּ׃","ẇbĕkál-y֣wòm wáy֔wòm márĕdȯkay֙ miţĕhalé̇֔kĕ lipĕné֖y ẖàẕa֣r bé̇yţ-haná̇şǐ֑ym láda֙ʻaţ֙ ʼeţ-şĕ̌l֣wòm ʼesĕţé̇֔r ẇmah-yé̇ʻáşê֖h báֽ̇ḣ׃"],[2,12,"וּבְהַגִּ֡יעַ תֹּר֩ נַעֲרָ֨ה וְנַעֲרָ֜ה לָב֣וֹא ׀ אֶל־הַמֶּ֣לֶךְ אֲחַשְׁוֵר֗וֹשׁ מִקֵּץ֩ הֱי֨וֹת לָ֜הּ כְּדָ֤ת הַנָּשִׁים֙ שְׁנֵ֣ים עָשָׂ֣ר חֹ֔דֶשׁ כִּ֛י כֵּ֥ן יִמְלְא֖וּ יְמֵ֣י מְרוּקֵיהֶ֑ן שִׁשָּׁ֤ה חֳדָשִׁים֙ בְּשֶׁ֣מֶן הַמֹּ֔ר וְשִׁשָּׁ֤ה חֳדָשִׁים֙ בַּבְּשָׂמִ֔ים וּבְתַמְרוּקֵ֖י הַנָּשִֽׁים׃","ẇbĕhagi̇֡yʻa ţò̇r֩ naʻàrá֨h wĕnaʻàrá֜h láb֣wòʼ ׀ ʼel-hamė֣lekĕ ʼàẖaşĕ̌wér֗wòş̌ miqé̇ẕ֩ hèy֨wòţ lá֜ḣ kĕ̇dá֤ţ haná̇şǐym֙ şĕ̌né֣ym ʻáşá֣̂r ẖò֔deş̌ ki֛̇y ké֥̇n yimĕlĕʼ֖ẇ yĕmé֣y mĕrẇqéyhe֑n şǐşá֤̇̌h ẖodáşǐym֙ bĕ̇şě֣men hamò̇֔r wĕşǐşá֤̇̌h ẖodáşǐym֙ bȧbĕ̇şá̂mi֔ym ẇbĕţamĕrẇqé֖y haná̇şǐֽym׃"],[2,13,"וּבָזֶ֕ה הַֽנַּעֲרָ֖ה בָּאָ֣ה אֶל־הַמֶּ֑לֶךְ אֵת֩ כָּל־אֲשֶׁ֨ר תֹּאמַ֜ר יִנָּ֤תֵֽן לָהּ֙ לָב֣וֹא עִמָּ֔הּ מִבֵּ֥ית הַנָּשִׁ֖ים עַד־בֵּ֥ית הַמֶּֽלֶךְ׃","ẇbáze֕h haֽnȧʻàrá֖h bá̇ʼá֣h ʼel-hamė֑lekĕ ʼéţ֩ ká̇l-ʼàşě֨r ţò̇ʼma֜r yiná֤̇ţéֽn láḣ֙ láb֣wòʼ ʻimá̇֔ḣ mibé֥̇yţ haná̇şǐ֖ym ʻad-bé֥̇yţ hamėֽlekĕ׃"],[2,14,"בָּעֶ֣רֶב ׀ הִ֣יא בָאָ֗ה וּ֠בַבֹּקֶר הִ֣יא שָׁבָ֞ה אֶל־בֵּ֤ית הַנָּשִׁים֙ שֵׁנִ֔י אֶל־יַ֧ד שַֽׁעֲשְׁגַ֛ז סְרִ֥יס הַמֶּ֖לֶךְ שֹׁמֵ֣ר הַפִּֽילַגְשִׁ֑ים לֹא־תָב֥וֹא עוֹד֙ אֶל־הַמֶּ֔לֶךְ כִּ֣י אִם־חָפֵ֥ץ בָּ֛הּ הַמֶּ֖לֶךְ וְנִקְרְאָ֥ה בְשֵֽׁם׃","bá̇ʻe֣reb ׀ hi֣yʼ báʼá֗h ẇ֠babò̇qer hi֣yʼ şá̌bá֞h ʼel-bé֤̇yţ haná̇şǐym֙ şé̌ni֔y ʼel-ya֧d şǎֽʻàşĕ̌ga֛z sĕri֥ys hamė֖lekĕ şò̌mé֣r hapiֽ̇ylagĕşǐ֑ym lòʼ-ţáb֥wòʼ ʻwòd֙ ʼel-hamė֔lekĕ ki֣̇y ʼim-ẖápé֥ẕ bá֛̇ḣ hamė֖lekĕ wĕniqĕrĕʼá֥h bĕşéֽ̌m׃"],[2,15,"וּבְהַגִּ֣יעַ תֹּר־אֶסְתֵּ֣ר בַּת־אֲבִיחַ֣יִל דֹּ֣ד מָרְדֳּכַ֡י אֲשֶׁר֩ לָקַֽח־ל֨וֹ לְבַ֜ת לָב֣וֹא אֶל־הַמֶּ֗לֶךְ לֹ֤א בִקְשָׁה֙ דָּבָ֔ר כִּ֠י אִ֣ם אֶת־אֲשֶׁ֥ר יֹאמַ֛ר הֵגַ֥י סְרִיס־הַמֶּ֖לֶךְ שֹׁמֵ֣ר הַנָּשִׁ֑ים וַתְּהִ֤י אֶסְתֵּר֙ נֹשֵׂ֣את חֵ֔ן בְּעֵינֵ֖י כָּל־רֹאֶֽיהָ׃","ẇbĕhagi֣̇yʻa ţò̇r-ʼesĕţé֣̇r bȧţ-ʼàbiyẖa֣yil dò֣̇d márĕdȯka֡y ʼàşěr֩ láqaֽẖ-l֨wò lĕba֜ţ láb֣wòʼ ʼel-hamė֗lekĕ lò֤ʼ biqĕşá̌h֙ dá̇bá֔r ki̇֠y ʼi֣m ʼeţ-ʼàşě֥r yòʼma֛r héga֥y sĕriys-hamė֖lekĕ şò̌mé֣r haná̇şǐ֑ym waţĕ̇hi֤y ʼesĕţé̇r֙ nòşé֣̂ʼţ ẖé֔n bĕ̇ʻéyné֖y ká̇l-ròʼeֽyhá׃"],[2,16,"וַתִּלָּקַ֨ח אֶסְתֵּ֜ר אֶל־הַמֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ אֶל־בֵּ֣ית מַלְכוּת֔וֹ בַּחֹ֥דֶשׁ הָעֲשִׂירִ֖י הוּא־חֹ֣דֶשׁ טֵבֵ֑ת בִּשְׁנַת־שֶׁ֖בַע לְמַלְכוּתֽוֹ׃","waţi̇lá̇qa֨ẖ ʼesĕţé̇֜r ʼel-hamė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ ʼel-bé֣̇yţ malĕkẇţ֔wò bȧẖò֥deş̌ háʻàşîyri֖y hẇʼ-ẖò֣deş̌ tébé֑ţ bi̇şĕ̌naţ-şě֖baʻ lĕmalĕkẇţֽwò׃"],[2,17,"וַיֶּאֱהַ֨ב הַמֶּ֤לֶךְ אֶת־אֶסְתֵּר֙ מִכָּל־הַנָּשִׁ֔ים וַתִּשָּׂא־חֵ֥ן וָחֶ֛סֶד לְפָנָ֖יו מִכָּל־הַבְּתוּלֹ֑ת וַיָּ֤שֶׂם כֶּֽתֶר־מַלְכוּת֙ בְּרֹאשָׁ֔הּ וַיַּמְלִיכֶ֖הָ תַּ֥חַת וַשְׁתִּֽי׃","wayėʼèha֨b hamė֤lekĕ ʼeţ-ʼesĕţé̇r֙ miká̇l-haná̇şǐ֔ym waţi̇şá̇̂ʼ-ẖé֥n wáẖe֛sed lĕpáná֖yw miká̇l-habĕ̇ţẇlò֑ţ wayá֤̇şêm kėֽţer-malĕkẇţ֙ bĕ̇ròʼşá̌֔ḣ wayȧmĕliyke֖há ţȧ֥ẖaţ waşĕ̌ţiֽ̇y׃"],[2,18,"וַיַּ֨עַשׂ הַמֶּ֜לֶךְ מִשְׁתֶּ֣ה גָד֗וֹל לְכָל־שָׂרָיו֙ וַעֲבָדָ֔יו אֵ֖ת מִשְׁתֵּ֣ה אֶסְתֵּ֑ר וַהֲנָחָ֤ה לַמְּדִינוֹת֙ עָשָׂ֔ה וַיִּתֵּ֥ן מַשְׂאֵ֖ת כְּיַ֥ד הַמֶּֽלֶךְ׃","wayȧ֨ʻaş̂ hamė֜lekĕ mişĕ̌ţė֣h gád֗wòl lĕkál-şá̂ráyw֙ waʻàbádá֔yw ʼé֖ţ mişĕ̌ţé֣̇h ʼesĕţé֑̇r wahànáẖá֤h lamĕ̇diynwòţ֙ ʻáşá̂֔h wayi̇ţé֥̇n maşĕ̂ʼé֖ţ kĕ̇ya֥d hamėֽlekĕ׃"],[2,19,"וּבְהִקָּבֵ֥ץ בְּתוּל֖וֹת שֵׁנִ֑ית וּמָרְדֳּכַ֖י יֹשֵׁ֥ב בְּשַֽׁעַר־הַמֶּֽלֶךְ ׃","ẇbĕhiqá̇bé֥ẕ bĕ̇ţẇl֖wòţ şé̌ni֑yţ ẇmárĕdȯka֖y yòşé֥̌b bĕ̇şǎֽʻar-hamėֽlekĕ ׃"],[2,20,"אֵ֣ין אֶסְתֵּ֗ר מַגֶּ֤דֶת מֽוֹלַדְתָּהּ֙ וְאֶת־עַמָּ֔הּ כַּאֲשֶׁ֛ר צִוָּ֥ה עָלֶ֖יהָ מָרְדֳּכָ֑י וְאֶת־מַאֲמַ֤ר מָרְדֳּכַי֙ אֶסְתֵּ֣ר עֹשָׂ֔ה כַּאֲשֶׁ֛ר הָיְתָ֥ה בְאָמְנָ֖ה אִתּֽוֹ׃ ס","ʼé֣yn ʼesĕţé̇֗r magė֤deţ mֽwòladĕţá̇ḣ֙ wĕʼeţ-ʻamá̇֔ḣ kȧʼàşě֛r ẕiwá֥̇h ʻále֖yhá márĕdȯká֑y wĕʼeţ-maʼàma֤r márĕdȯkay֙ ʼesĕţé֣̇r ʻòşá̂֔h kȧʼàşě֛r háyĕţá֥h bĕʼámĕná֖h ʼiţֽ̇wò׃ s"],[2,21,"בַּיָּמִ֣ים הָהֵ֔ם וּמָרְדֳּכַ֖י יֹשֵׁ֣ב בְּשַֽׁעַר־הַמֶּ֑לֶךְ קָצַף֩ בִּגְתָ֨ן וָתֶ֜רֶשׁ שְׁנֵֽי־סָרִיסֵ֤י הַמֶּ֙לֶךְ֙ מִשֹּׁמְרֵ֣י הַסַּ֔ף וַיְבַקְשׁוּ֙ לִשְׁלֹ֣חַ יָ֔ד בַּמֶּ֖לֶךְ אֲחַשְׁוֵֽרֹשׁ׃","bȧyá̇mi֣ym háhé֔m ẇmárĕdȯka֖y yòşé֣̌b bĕ̇şǎֽʻar-hamė֑lekĕ qáẕap֩ bi̇gĕţá֨n wáţe֜reş̌ şĕ̌néֽy-sáriysé֤y hamė֙lekĕ֙ mişò̇̌mĕré֣y hasȧ֔p wayĕbaqĕş̌ẇ֙ lişĕ̌lò֣ẖa yá֔d bȧmė֖lekĕ ʼàẖaşĕ̌wéֽròş̌׃"],[2,22,"וַיִּוָּדַ֤ע הַדָּבָר֙ לְמָרְדֳּכַ֔י וַיַּגֵּ֖ד לְאֶסְתֵּ֣ר הַמַּלְכָּ֑ה וַתֹּ֧אמֶר אֶסְתֵּ֛ר לַמֶּ֖לֶךְ בְּשֵׁ֥ם מָרְדֳּכָֽי׃","wayi̇wá̇da֤ʻ hadá̇bár֙ lĕmárĕdȯka֔y wayȧgé֖̇d lĕʼesĕţé֣̇r hamȧlĕká֑̇h waţò֧̇ʼmer ʼesĕţé֛̇r lamė֖lekĕ bĕ̇şé֥̌m márĕdȯkáֽy׃"],[2,23,"וַיְבֻקַּ֤שׁ הַדָּבָר֙ וַיִּמָּצֵ֔א וַיִּתָּל֥וּ שְׁנֵיהֶ֖ם עַל־עֵ֑ץ וַיִּכָּתֵ֗ב בְּסֵ֛פֶר דִּבְרֵ֥י הַיָּמִ֖ים לִפְנֵ֥י הַמֶּֽלֶךְ׃ פ","wayĕbuqȧ֤ş̌ hadá̇bár֙ wayi̇má̇ẕé֔ʼ wayi̇ţá̇l֥ẇ şĕ̌néyhe֖m ʻal-ʻé֑ẕ wayi̇ká̇ţé֗b bĕ̇sé֛per di̇bĕré֥y hayá̇mi֖ym lipĕné֥y hamėֽlekĕ׃ p"],[3,1,"אַחַ֣ר ׀ הַדְּבָרִ֣ים הָאֵ֗לֶּה גִּדַּל֩ הַמֶּ֨לֶךְ אֲחַשְׁוֵר֜וֹשׁ אֶת־הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָאֲגָגִ֖י וַֽיְנַשְּׂאֵ֑הוּ וַיָּ֙שֶׂם֙ אֶת־כִּסְא֔וֹ מֵעַ֕ל כָּל־הַשָּׂרִ֖ים אֲשֶׁ֥ר אִתּֽוֹ׃","ʼaẖa֣r ׀ hadĕ̇bári֣ym háʼé֗lėh gi̇dȧl֩ hamė֨lekĕ ʼàẖaşĕ̌wér֜wòş̌ ʼeţ-hámá֧n bėֽn-hamĕ̇dá֛ţáʼ háʼàgági֖y waֽyĕnaşĕ̇̂ʼé֑hẇ wayá̇֙şêm֙ ʼeţ-ki̇sĕʼ֔wò méʻa֕l ká̇l-haşá̇̂ri֖ym ʼàşě֥r ʼiţֽ̇wò׃"],[3,2,"וְכָל־עַבְדֵ֨י הַמֶּ֜לֶךְ אֲשֶׁר־בְּשַׁ֣עַר הַמֶּ֗לֶךְ כֹּרְעִ֤ים וּמִֽשְׁתַּחֲוִים֙ לְהָמָ֔ן כִּי־כֵ֖ן צִוָּה־ל֣וֹ הַמֶּ֑לֶךְ וּמָ֨רְדֳּכַ֔י לֹ֥א יִכְרַ֖ע וְלֹ֥א יִֽשְׁתַּחֲוֶֽה׃","wĕkál-ʻabĕdé֨y hamė֜lekĕ ʼàşěr-bĕ̇şǎ֣ʻar hamė֗lekĕ kò̇rĕʻi֤ym ẇmiֽşĕ̌ţȧẖàwiym֙ lĕhámá֔n ki̇y-ké֖n ẕiwá̇h-l֣wò hamė֑lekĕ ẇmá֨rĕdȯka֔y lò֥ʼ yikĕra֖ʻ wĕlò֥ʼ yiֽşĕ̌ţȧẖàweֽh׃"],[3,3,"וַיֹּ֨אמְר֜וּ עַבְדֵ֥י הַמֶּ֛לֶךְ אֲשֶׁר־בְּשַׁ֥עַר הַמֶּ֖לֶךְ לְמָרְדֳּכָ֑י מַדּ֙וּעַ֙ אַתָּ֣ה עוֹבֵ֔ר אֵ֖ת מִצְוַ֥ת הַמֶּֽלֶךְ׃","wayò̇֨ʼmĕr֜ẇ ʻabĕdé֥y hamė֛lekĕ ʼàşěr-bĕ̇şǎ֥ʻar hamė֖lekĕ lĕmárĕdȯká֑y maḋ֙ẇʻa֙ ʼaţá֣̇h ʻwòbé֔r ʼé֖ţ miẕĕwa֥ţ hamėֽlekĕ׃"],[3,4,"וַיְהִ֗י באמרם אֵלָיו֙ י֣וֹם וָי֔וֹם וְלֹ֥א שָׁמַ֖ע אֲלֵיהֶ֑ם וַיַּגִּ֣ידוּ לְהָמָ֗ן לִרְאוֹת֙ הֲיַֽעַמְדוּ֙ דִּבְרֵ֣י מָרְדֳּכַ֔י כִּֽי־הִגִּ֥יד לָהֶ֖ם אֲשֶׁר־ה֥וּא יְהוּדִֽי׃","wayĕhi֗y bʼmrm ʼéláyw֙ y֣wòm wáy֔wòm wĕlò֥ʼ şá̌ma֖ʻ ʼàléyhe֑m wayȧgi֣̇ydẇ lĕhámá֗n lirĕʼwòţ֙ hàyaֽʻamĕdẇ֙ di̇bĕré֣y márĕdȯka֔y kiֽ̇y-higi֥̇yd láhe֖m ʼàşěr-h֥ẇʼ yĕhẇdiֽy׃"],[3,5,"וַיַּ֣רְא הָמָ֔ן כִּי־אֵ֣ין מָרְדֳּכַ֔י כֹּרֵ֥עַ וּמִֽשְׁתַּחֲוֶ֖ה ל֑וֹ וַיִּמָּלֵ֥א הָמָ֖ן חֵמָֽה׃","wayȧ֣rĕʼ hámá֔n ki̇y-ʼé֣yn márĕdȯka֔y kò̇ré֥ʻa ẇmiֽşĕ̌ţȧẖàwe֖h l֑wò wayi̇má̇lé֥ʼ hámá֖n ẖémáֽh׃"],[3,6,"וַיִּ֣בֶז בְּעֵינָ֗יו לִשְׁלֹ֤ח יָד֙ בְּמָרְדֳּכַ֣י לְבַדּ֔וֹ כִּֽי־הִגִּ֥ידוּ ל֖וֹ אֶת־עַ֣ם מָרְדֳּכָ֑י וַיְבַקֵּ֣שׁ הָמָ֗ן לְהַשְׁמִ֧יד אֶת־כָּל־הַיְּהוּדִ֛ים אֲשֶׁ֛ר בְּכָל־מַלְכ֥וּת אֲחַשְׁוֵר֖וֹשׁ עַ֥ם מָרְדֳּכָֽי׃","wayi֣̇bez bĕ̇ʻéyná֗yw lişĕ̌lò֤ẖ yád֙ bĕ̇márĕdȯka֣y lĕbaḋ֔wò kiֽ̇y-higi֥̇ydẇ l֖wò ʼeţ-ʻa֣m márĕdȯká֑y wayĕbaqé֣̇ş̌ hámá֗n lĕhaşĕ̌mi֧yd ʼeţ-ká̇l-hayĕ̇hẇdi֛ym ʼàşě֛r bĕ̇kál-malĕk֥ẇţ ʼàẖaşĕ̌wér֖wòş̌ ʻa֥m márĕdȯkáֽy׃"],[3,7,"בַּחֹ֤דֶשׁ הָרִאשׁוֹן֙ הוּא־חֹ֣דֶשׁ נִיסָ֔ן בִּשְׁנַת֙ שְׁתֵּ֣ים עֶשְׂרֵ֔ה לַמֶּ֖לֶךְ אֲחַשְׁוֵר֑וֹשׁ הִפִּ֣יל פּוּר֩ ה֨וּא הַגּוֹרָ֜ל לִפְנֵ֣י הָמָ֗ן מִיּ֧וֹם ׀ לְי֛וֹם וּמֵחֹ֛דֶשׁ לְחֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃ ס","bȧẖò֤deş̌ háriʼş̌wòn֙ hẇʼ-ẖò֣deş̌ niysá֔n bi̇şĕ̌naţ֙ şĕ̌ţé֣̇ym ʻeşĕ̂ré֔h lamė֖lekĕ ʼàẖaşĕ̌wér֑wòş̌ hipi֣̇yl ṗẇr֩ h֨ẇʼ haġwòrá֜l lipĕné֣y hámá֗n miẏ֧wòm ׀ lĕy֛wòm ẇméẖò֛deş̌ lĕẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃ s"],[3,8,"וַיֹּ֤אמֶר הָמָן֙ לַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ יֶשְׁנ֣וֹ עַם־אֶחָ֗ד מְפֻזָּ֤ר וּמְפֹרָד֙ בֵּ֣ין הָֽעַמִּ֔ים בְּכֹ֖ל מְדִינ֣וֹת מַלְכוּתֶ֑ךָ וְדָתֵיהֶ֞ם שֹׁנ֣וֹת מִכָּל־עָ֗ם וְאֶת־דָּתֵ֤י הַמֶּ֙לֶךְ֙ אֵינָ֣ם עֹשִׂ֔ים וְלַמֶּ֥לֶךְ אֵין־שֹׁוֶ֖ה לְהַנִּיחָֽם׃","wayò֤̇ʼmer hámán֙ lamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ yeşĕ̌n֣wò ʻam-ʼeẖá֗d mĕpuzá֤̇r ẇmĕpòrád֙ bé֣̇yn háֽʻami̇֔ym bĕ̇kò֖l mĕdiyn֣wòţ malĕkẇţe֑ká wĕdáţéyhe֞m şò̌n֣wòţ miká̇l-ʻá֗m wĕʼeţ-dá̇ţé֤y hamė֙lekĕ֙ ʼéyná֣m ʻòşî֔ym wĕlamė֥lekĕ ʼéyn-şò̌we֖h lĕhani̇yẖáֽm׃"],[3,9,"אִם־עַל־הַמֶּ֣לֶךְ ט֔וֹב יִכָּתֵ֖ב לְאַבְּדָ֑ם וַעֲשֶׂ֨רֶת אֲלָפִ֜ים כִּכַּר־כֶּ֗סֶף אֶשְׁקוֹל֙ עַל־יְדֵי֙ עֹשֵׂ֣י הַמְּלָאכָ֔ה לְהָבִ֖יא אֶל־גִּנְזֵ֥י הַמֶּֽלֶךְ׃","ʼim-ʻal-hamė֣lekĕ t֔wòb yiká̇ţé֖b lĕʼabĕ̇dá֑m waʻàşê֨reţ ʼàlápi֜ym ki̇kȧr-kė֗sep ʼeşĕ̌qwòl֙ ʻal-yĕdéy֙ ʻòşé֣̂y hamĕ̇láʼká֔h lĕhábi֖yʼ ʼel-gi̇nĕzé֥y hamėֽlekĕ׃"],[3,10,"וַיָּ֧סַר הַמֶּ֛לֶךְ אֶת־טַבַּעְתּ֖וֹ מֵעַ֣ל יָד֑וֹ וַֽיִּתְּנָ֗הּ לְהָמָ֧ן בֶּֽן־הַמְּדָ֛תָא הָאֲגָגִ֖י צֹרֵ֥ר הַיְּהוּדִֽים׃","wayá֧̇sar hamė֛lekĕ ʼeţ-tabȧʻĕţ֖̇wò méʻa֣l yád֑wò waֽyi̇ţĕ̇ná֗ḣ lĕhámá֧n bėֽn-hamĕ̇dá֛ţáʼ háʼàgági֖y ẕòré֥r hayĕ̇hẇdiֽym׃"],[3,11,"וַיֹּ֤אמֶר הַמֶּ֙לֶךְ֙ לְהָמָ֔ן הַכֶּ֖סֶף נָת֣וּן לָ֑ךְ וְהָעָ֕ם לַעֲשׂ֥וֹת בּ֖וֹ כַּטּ֥וֹב בְּעֵינֶֽיךָ׃","wayò֤̇ʼmer hamė֙lekĕ֙ lĕhámá֔n hakė֖sep náţ֣ẇn lá֑kĕ wĕháʻá֕m laʻàş֥̂wòţ ḃ֖wò kȧṫ֥wòb bĕ̇ʻéyneֽyká׃"],[3,12,"וַיִּקָּרְאוּ֩ סֹפְרֵ֨י הַמֶּ֜לֶךְ בַּחֹ֣דֶשׁ הָרִאשׁ֗וֹן בִּשְׁלוֹשָׁ֨ה עָשָׂ֣ר יוֹם֮ בּוֹ֒ וַיִּכָּתֵ֣ב כְּֽכָל־אֲשֶׁר ־צִוָּ֣ה הָמָ֡ן אֶ֣ל אֲחַשְׁדַּרְפְּנֵֽי־הַ֠מֶּלֶךְ וְֽאֶל־הַפַּח֞וֹת אֲשֶׁ֣ר ׀ עַל־מְדִינָ֣ה וּמְדִינָ֗ה וְאֶל־שָׂ֤רֵי עַם֙ וָעָ֔ם מְדִינָ֤ה וּמְדִינָה֙ כִּכְתָבָ֔הּ וְעַ֥ם וָעָ֖ם כִּלְשׁוֹנ֑וֹ בְּשֵׁ֨ם הַמֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ נִכְתָּ֔ב וְנֶחְתָּ֖ם בְּטַבַּ֥עַת הַמֶּֽלֶךְ׃","wayi̇qá̇rĕʼẇ֩ sòpĕré֨y hamė֜lekĕ bȧẖò֣deş̌ háriʼş̌֗wòn bi̇şĕ̌lwòşá̌֨h ʻáşá֣̂r ywòm֮ ḃwò֒ wayi̇ká̇ţé֣b kĕֽ̇kál-ʼàşěr -ẕiwá֣̇h hámá֡n ʼe֣l ʼàẖaşĕ̌dȧrĕpĕ̇néֽy-ha֠mėlekĕ wĕֽʼel-hapȧẖ֞wòţ ʼàşě֣r ׀ ʻal-mĕdiyná֣h ẇmĕdiyná֗h wĕʼel-şá֤̂réy ʻam֙ wáʻá֔m mĕdiyná֤h ẇmĕdiynáh֙ ki̇kĕţábá֔ḣ wĕʻa֥m wáʻá֖m ki̇lĕş̌wòn֑wò bĕ̇şé̌֨m hamė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ nikĕţá̇֔b wĕneẖĕţá֖̇m bĕ̇tabȧ֥ʻaţ hamėֽlekĕ׃"],[3,13,"וְנִשְׁל֨וֹחַ סְפָרִ֜ים בְּיַ֣ד הָרָצִים֮ אֶל־כָּל־מְדִינ֣וֹת הַמֶּלֶךְ֒ לְהַשְׁמִ֡יד לַהֲרֹ֣ג וּלְאַבֵּ֣ד אֶת־כָּל־הַ֠יְּהוּדִים מִנַּ֨עַר וְעַד־זָקֵ֨ן טַ֤ף וְנָשִׁים֙ בְּי֣וֹם אֶחָ֔ד בִּשְׁלוֹשָׁ֥ה עָשָׂ֛ר לְחֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֣דֶשׁ אֲדָ֑ר וּשְׁלָלָ֖ם לָבֽוֹז׃","wĕnişĕ̌l֨wòẖa sĕpári֜ym bĕ̇ya֣d háráẕiym֮ ʼel-ká̇l-mĕdiyn֣wòţ hamėlekĕ֒ lĕhaşĕ̌mi֡yd lahàrò֣g ẇlĕʼabé֣̇d ʼeţ-ká̇l-ha֠yĕ̇hẇdiym minȧ֨ʻar wĕʻad-záqé֨n ta֤p wĕnáşǐym֙ bĕ̇y֣wòm ʼeẖá֔d bi̇şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֣deş̌ ʼàdá֑r ẇşĕ̌lálá֖m lábֽwòz׃"],[3,14,"פַּתְשֶׁ֣גֶן הַכְּתָ֗ב לְהִנָּ֤תֵֽן דָּת֙ בְּכָל־מְדִינָ֣ה וּמְדִינָ֔ה גָּל֖וּי לְכָל־הָֽעַמִּ֑ים לִהְי֥וֹת עֲתִדִ֖ים לַיּ֥וֹם הַזֶּֽה׃","pȧţĕşě֣gen hakĕ̇ţá֗b lĕhiná֤̇ţéֽn dá̇ţ֙ bĕ̇kál-mĕdiyná֣h ẇmĕdiyná֔h gá̇l֖ẇy lĕkál-háֽʻami֑̇ym lihĕy֥wòţ ʻàţidi֖ym laẏ֥wòm hazėֽh׃"],[3,15,"הָֽרָצִ֞ים יָצְא֤וּ דְחוּפִים֙ בִּדְבַ֣ר הַמֶּ֔לֶךְ וְהַדָּ֥ת נִתְּנָ֖ה בְּשׁוּשַׁ֣ן הַבִּירָ֑ה וְהַמֶּ֤לֶךְ וְהָמָן֙ יָשְׁב֣וּ לִשְׁתּ֔וֹת וְהָעִ֥יר שׁוּשָׁ֖ן נָבֽוֹכָה׃ פ","hֽáráẕi֞ym yáẕĕʼ֤ẇ dĕẖẇpiym֙ bi̇dĕba֣r hamė֔lekĕ wĕhadá֥̇ţ niţĕ̇ná֖h bĕ̇ş̌ẇşǎ֣n habi̇yrá֑h wĕhamė֤lekĕ wĕhámán֙ yáşĕ̌b֣ẇ lişĕ̌ţ̇֔wòţ wĕháʻi֥yr ş̌ẇşá֖̌n nábֽwòkáh׃ p"],[4,1,"וּמָרְדֳּכַ֗י יָדַע֙ אֶת־כָּל־אֲשֶׁ֣ר נַעֲשָׂ֔ה וַיִּקְרַ֤ע מָרְדֳּכַי֙ אֶת־בְּגָדָ֔יו וַיִּלְבַּ֥שׁ שַׂ֖ק וָאֵ֑פֶר וַיֵּצֵא֙ בְּת֣וֹךְ הָעִ֔יר וַיִּזְעַ֛ק זְעָקָ֥ה גְדֹלָ֖ה וּמָרָֽה׃","ẇmárĕdȯka֗y yádaʻ֙ ʼeţ-ká̇l-ʼàşě֣r naʻàşá̂֔h wayi̇qĕra֤ʻ márĕdȯkay֙ ʼeţ-bĕ̇gádá֔yw wayi̇lĕbȧ֥ş̌ şâ֖q wáʼé֑per wayé̇ẕéʼ֙ bĕ̇ţ֣wòkĕ háʻi֔yr wayi̇zĕʻa֛q zĕʻáqá֥h gĕdòlá֖h ẇmáráֽh׃"],[4,2,"וַיָּב֕וֹא עַ֖ד לִפְנֵ֣י שַֽׁעַר־הַמֶּ֑לֶךְ כִּ֣י אֵ֥ין לָב֛וֹא אֶל־שַׁ֥עַר הַמֶּ֖לֶךְ בִּלְב֥וּשׁ שָֽׂק׃","wayá̇b֕wòʼ ʻa֖d lipĕné֣y şǎֽʻar-hamė֑lekĕ ki֣̇y ʼé֥yn láb֛wòʼ ʼel-şǎ֥ʻar hamė֖lekĕ bi̇lĕb֥ẇş̌ şáֽ̂q׃"],[4,3,"וּבְכָל־מְדִינָ֣ה וּמְדִינָ֗ה מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַמֶּ֤לֶךְ וְדָתוֹ֙ מַגִּ֔יעַ אֵ֤בֶל גָּדוֹל֙ לַיְּהוּדִ֔ים וְצ֥וֹם וּבְכִ֖י וּמִסְפֵּ֑ד שַׂ֣ק וָאֵ֔פֶר יֻצַּ֖ע לָֽרַבִּֽים׃","ẇbĕkál-mĕdiyná֣h ẇmĕdiyná֗h mĕqwòm֙ ʼàşě֨r dĕ̇bar-hamė֤lekĕ wĕdáţwò֙ magi̇֔yʻa ʼé֤bel gá̇dwòl֙ layĕ̇hẇdi֔ym wĕẕ֥wòm ẇbĕki֖y ẇmisĕpé֑̇d şâ֣q wáʼé֔per yuẕȧ֖ʻ láֽrabiֽ̇ym׃"],[4,4,"וַ֠תָּבוֹאינָה נַעֲר֨וֹת אֶסְתֵּ֤ר וְסָרִיסֶ֙יהָ֙ וַיַּגִּ֣ידוּ לָ֔הּ וַתִּתְחַלְחַ֥ל הַמַּלְכָּ֖ה מְאֹ֑ד וַתִּשְׁלַ֨ח בְּגָדִ֜ים לְהַלְבִּ֣ישׁ אֶֽת־מָרְדֳּכַ֗י וּלְהָסִ֥יר שַׂקּ֛וֹ מֵעָלָ֖יו וְלֹ֥א קִבֵּֽל׃","wa֠ţá̇bwòʼynáh naʻàr֨wòţ ʼesĕţé֤̇r wĕsáriyse֙yhá֙ wayȧgi֣̇ydẇ lá֔ḣ waţi̇ţĕẖalĕẖa֥l hamȧlĕká֖̇h mĕʼò֑d waţi̇şĕ̌la֨ẖ bĕ̇gádi֜ym lĕhalĕbi֣̇yş̌ ʼeֽţ-márĕdȯka֗y ẇlĕhási֥yr şâq֛̇wò méʻálá֖yw wĕlò֥ʼ qibéֽ̇l׃"],[4,5,"וַתִּקְרָא֩ אֶסְתֵּ֨ר לַהֲתָ֜ךְ מִסָּרִיסֵ֤י הַמֶּ֙לֶךְ֙ אֲשֶׁ֣ר הֶעֱמִ֣יד לְפָנֶ֔יהָ וַתְּצַוֵּ֖הוּ עַֽל־מָרְדֳּכָ֑י לָדַ֥עַת מַה־זֶּ֖ה וְעַל־מַה־זֶּֽה׃","waţi̇qĕráʼ֩ ʼesĕţé̇֨r lahàţá֜kĕ misá̇riysé֤y hamė֙lekĕ֙ ʼàşě֣r heʻèmi֣yd lĕpáne֔yhá waţĕ̇ẕawé֖̇hẇ ʻaֽl-márĕdȯká֑y láda֥ʻaţ mah-zė֖h wĕʻal-mah-zėֽh׃"],[4,6,"וַיֵּצֵ֥א הֲתָ֖ךְ אֶֽל־מָרְדֳּכָ֑י אֶל־רְח֣וֹב הָעִ֔יר אֲשֶׁ֖ר לִפְנֵ֥י שַֽׁעַר־הַמֶּֽלֶךְ׃","wayé̇ẕé֥ʼ hàţá֖kĕ ʼeֽl-márĕdȯká֑y ʼel-rĕẖ֣wòb háʻi֔yr ʼàşě֖r lipĕné֥y şǎֽʻar-hamėֽlekĕ׃"],[4,7,"וַיַּגֶּד־ל֣וֹ מָרְדֳּכַ֔י אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑הוּ וְאֵ֣ת ׀ פָּרָשַׁ֣ת הַכֶּ֗סֶף אֲשֶׁ֨ר אָמַ֤ר הָמָן֙ לִ֠שְׁקוֹל עַל־גִּנְזֵ֥י הַמֶּ֛לֶךְ ביהודיים לְאַבְּדָֽם׃","wayȧgėd-l֣wò márĕdȯka֔y ʼé֖ţ ká̇l-ʼàşě֣r qárá֑hẇ wĕʼé֣ţ ׀ pá̇ráşǎ֣ţ hakė֗sep ʼàşě֨r ʼáma֤r hámán֙ li֠şĕ̌qwòl ʻal-gi̇nĕzé֥y hamė֛lekĕ byhwdyym lĕʼabĕ̇dáֽm׃"],[4,8,"וְאֶת־פַּתְשֶׁ֣גֶן כְּתָֽב־הַ֠דָּת אֲשֶׁר־נִתַּ֨ן בְּשׁוּשָׁ֤ן לְהַשְׁמִידָם֙ נָ֣תַן ל֔וֹ לְהַרְא֥וֹת אֶת־אֶסְתֵּ֖ר וּלְהַגִּ֣יד לָ֑הּ וּלְצַוּ֣וֹת עָלֶ֗יהָ לָב֨וֹא אֶל־הַמֶּ֧לֶךְ לְהִֽתְחַנֶּן־ל֛וֹ וּלְבַקֵּ֥שׁ מִלְּפָנָ֖יו עַל־עַמָּֽהּ׃","wĕʼeţ-pȧţĕşě֣gen kĕ̇ţáֽb-ha֠dá̇ţ ʼàşěr-niţȧ֨n bĕ̇ş̌ẇşá֤̌n lĕhaşĕ̌miydám֙ ná֣ţan l֔wò lĕharĕʼ֥wòţ ʼeţ-ʼesĕţé֖̇r ẇlĕhagi֣̇yd lá֑ḣ ẇlĕẕaẇ֣wòţ ʻále֗yhá láb֨wòʼ ʼel-hamė֧lekĕ lĕhiֽţĕẖanėn-l֛wò ẇlĕbaqé֥̇ş̌ milĕ̇páná֖yw ʻal-ʻamáֽ̇ḣ׃"],[4,9,"וַיָּב֖וֹא הֲתָ֑ךְ וַיַּגֵּ֣ד לְאֶסְתֵּ֔ר אֵ֖ת דִּבְרֵ֥י מָרְדֳּכָֽי׃","wayá̇b֖wòʼ hàţá֑kĕ wayȧgé֣̇d lĕʼesĕţé̇֔r ʼé֖ţ di̇bĕré֥y márĕdȯkáֽy׃"],[4,10,"וַתֹּ֤אמֶר אֶסְתֵּר֙ לַהֲתָ֔ךְ וַתְּצַוֵּ֖הוּ אֶֽל־מָרְדֳּכָֽי׃","waţò֤̇ʼmer ʼesĕţé̇r֙ lahàţá֔kĕ waţĕ̇ẕawé֖̇hẇ ʼeֽl-márĕdȯkáֽy׃"],[4,11,"כָּל־עַבְדֵ֣י הַמֶּ֡לֶךְ וְעַם־מְדִינ֨וֹת הַמֶּ֜לֶךְ יֽוֹדְעִ֗ים אֲשֶׁ֣ר כָּל־אִ֣ישׁ וְאִשָּׁ֡ה אֲשֶׁ֣ר יָבֽוֹא־אֶל־הַמֶּלֶךְ֩ אֶל־הֶחָצֵ֨ר הַפְּנִימִ֜ית אֲשֶׁ֣ר לֹֽא־יִקָּרֵ֗א אַחַ֤ת דָּתוֹ֙ לְהָמִ֔ית לְ֠בַד מֵאֲשֶׁ֨ר יֽוֹשִׁיט־ל֥וֹ הַמֶּ֛לֶךְ אֶת־שַׁרְבִ֥יט הַזָּהָ֖ב וְחָיָ֑ה וַאֲנִ֗י לֹ֤א נִקְרֵ֙אתי֙ לָב֣וֹא אֶל־הַמֶּ֔לֶךְ זֶ֖ה שְׁלוֹשִׁ֥ים יֽוֹם׃","ká̇l-ʻabĕdé֣y hamė֡lekĕ wĕʻam-mĕdiyn֨wòţ hamė֜lekĕ yֽwòdĕʻi֗ym ʼàşě֣r ká̇l-ʼi֣yş̌ wĕʼişá̇̌֡h ʼàşě֣r yábֽwòʼ-ʼel-hamėlekĕ֩ ʼel-heẖáẕé֨r hapĕ̇niymi֜yţ ʼàşě֣r lòֽʼ-yiqá̇ré֗ʼ ʼaẖa֤ţ dá̇ţwò֙ lĕhámi֔yţ lĕ֠bad méʼàşě֨r yֽwòşǐyt-l֥wò hamė֛lekĕ ʼeţ-şǎrĕbi֥yt hazá̇há֖b wĕẖáyá֑h waʼàni֗y lò֤ʼ niqĕré֙ʼţy֙ láb֣wòʼ ʼel-hamė֔lekĕ ze֖h şĕ̌lwòşǐ֥ym yֽwòm׃"],[4,12,"וַיַּגִּ֣ידוּ לְמָרְדֳּכָ֔י אֵ֖ת דִּבְרֵ֥י אֶסְתֵּֽר׃ פ","wayȧgi֣̇ydẇ lĕmárĕdȯká֔y ʼé֖ţ di̇bĕré֥y ʼesĕţéֽ̇r׃ p"],[4,13,"וַיֹּ֥אמֶר מָרְדֳּכַ֖י לְהָשִׁ֣יב אֶל־אֶסְתֵּ֑ר אַל־תְּדַמִּ֣י בְנַפְשֵׁ֔ךְ לְהִמָּלֵ֥ט בֵּית־הַמֶּ֖לֶךְ מִכָּל־הַיְּהוּדִֽים׃","wayò֥̇ʼmer márĕdȯka֖y lĕháşǐ֣yb ʼel-ʼesĕţé֑̇r ʼal-ţĕ̇dami֣̇y bĕnapĕşé̌֔kĕ lĕhimá̇lé֥t bé̇yţ-hamė֖lekĕ miká̇l-hayĕ̇hẇdiֽym׃"],[4,14,"כִּ֣י אִם־הַחֲרֵ֣שׁ תַּחֲרִישִׁי֮ בָּעֵ֣ת הַזֹּאת֒ רֶ֣וַח וְהַצָּלָ֞ה יַעֲמ֤וֹד לַיְּהוּדִים֙ מִמָּק֣וֹם אַחֵ֔ר וְאַ֥תְּ וּבֵית־אָבִ֖יךְ תֹּאבֵ֑דוּ וּמִ֣י יוֹדֵ֔עַ אִם־לְעֵ֣ת כָּזֹ֔את הִגַּ֖עַתְּ לַמַּלְכֽוּת׃","ki֣̇y ʼim-haẖàré֣ş̌ ţȧẖàriyşǐy֮ bá̇ʻé֣ţ hazò̇ʼţ֒ re֣waẖ wĕhaẕá̇lá֞h yaʻàm֤wòd layĕ̇hẇdiym֙ mimá̇q֣wòm ʼaẖé֔r wĕʼa֥ţĕ̇ ẇbéyţ-ʼábi֖ykĕ ţò̇ʼbé֑dẇ ẇmi֣y ywòdé֔ʻa ʼim-lĕʻé֣ţ ká̇zò֔ʼţ higȧ֖ʻaţĕ̇ lamȧlĕkֽẇţ׃"],[4,15,"וַתֹּ֥אמֶר אֶסְתֵּ֖ר לְהָשִׁ֥יב אֶֽל־מָרְדֳּכָֽי׃","waţò֥̇ʼmer ʼesĕţé֖̇r lĕháşǐ֥yb ʼeֽl-márĕdȯkáֽy׃"],[4,16,"לֵךְ֩ כְּנ֨וֹס אֶת־כָּל־הַיְּהוּדִ֜ים הַֽנִּמְצְאִ֣ים בְּשׁוּשָׁ֗ן וְצ֣וּמוּ עָ֠לַי וְאַל־תֹּאכְל֨וּ וְאַל־תִּשְׁתּ֜וּ שְׁלֹ֤שֶׁת יָמִים֙ לַ֣יְלָה וָי֔וֹם גַּם־אֲנִ֥י וְנַעֲרֹתַ֖י אָצ֣וּם כֵּ֑ן וּבְכֵ֞ן אָב֤וֹא אֶל־הַמֶּ֙לֶךְ֙ אֲשֶׁ֣ר לֹֽא־כַדָּ֔ת וְכַאֲשֶׁ֥ר אָבַ֖דְתִּי אָבָֽדְתִּי׃","lékĕ֩ kĕ̇n֨wòs ʼeţ-ká̇l-hayĕ̇hẇdi֜ym haֽni̇mĕẕĕʼi֣ym bĕ̇ş̌ẇşá̌֗n wĕẕ֣ẇmẇ ʻá֠lay wĕʼal-ţò̇ʼkĕl֨ẇ wĕʼal-ţi̇şĕ̌ţ̇֜ẇ şĕ̌lò֤şěţ yámiym֙ la֣yĕláh wáy֔wòm gȧm-ʼàni֥y wĕnaʻàròţa֖y ʼáẕ֣ẇm ké֑̇n ẇbĕké֞n ʼáb֤wòʼ ʼel-hamė֙lekĕ֙ ʼàşě֣r lòֽʼ-kadá̇֔ţ wĕkaʼàşě֥r ʼába֖dĕţi̇y ʼábáֽdĕţi̇y׃"],[4,17,"וַֽיַּעֲבֹ֖ר מָרְדֳּכָ֑י וַיַּ֕עַשׂ כְּכֹ֛ל אֲשֶׁר־צִוְּתָ֥ה עָלָ֖יו אֶסְתֵּֽר׃ ס","waֽyȧʻàbò֖r márĕdȯká֑y wayȧ֕ʻaş̂ kĕ̇kò֛l ʼàşěr-ẕiwĕ̇ţá֥h ʻálá֖yw ʼesĕţéֽ̇r׃ s"],[5,1,"וַיְהִ֣י ׀ בַּיּ֣וֹם הַשְּׁלִישִׁ֗י וַתִּלְבַּ֤שׁ אֶסְתֵּר֙ מַלְכ֔וּת וַֽתַּעֲמֹ֞ד בַּחֲצַ֤ר בֵּית־הַמֶּ֙לֶךְ֙ הַפְּנִימִ֔ית נֹ֖כַח בֵּ֣ית הַמֶּ֑לֶךְ וְ֠הַמֶּלֶךְ יוֹשֵׁ֞ב עַל־כִּסֵּ֤א מַלְכוּתוֹ֙ בְּבֵ֣ית הַמַּלְכ֔וּת נֹ֖כַח פֶּ֥תַח הַבָּֽיִת׃","wayĕhi֣y ׀ bȧẏ֣wòm haşĕ̇̌liyşǐ֗y waţi̇lĕbȧ֤ş̌ ʼesĕţé̇r֙ malĕk֔ẇţ waֽţȧʻàmò֞d bȧẖàẕa֤r bé̇yţ-hamė֙lekĕ֙ hapĕ̇niymi֔yţ nò֖kaẖ bé֣̇yţ hamė֑lekĕ wĕ֠hamėlekĕ ywòşé̌֞b ʻal-ki̇sé֤̇ʼ malĕkẇţwò֙ bĕ̇bé֣yţ hamȧlĕk֔ẇţ nò֖kaẖ pė֥ţaẖ habáֽ̇yiţ׃"],[5,2,"וַיְהִי֩ כִרְא֨וֹת הַמֶּ֜לֶךְ אֶת־אֶסְתֵּ֣ר הַמַּלְכָּ֗ה עֹמֶ֙דֶת֙ בֶּֽחָצֵ֔ר נָשְׂאָ֥ה חֵ֖ן בְּעֵינָ֑יו וַיּ֨וֹשֶׁט הַמֶּ֜לֶךְ לְאֶסְתֵּ֗ר אֶת־שַׁרְבִ֤יט הַזָּהָב֙ אֲשֶׁ֣ר בְּיָד֔וֹ וַתִּקְרַ֣ב אֶסְתֵּ֔ר וַתִּגַּ֖ע בְּרֹ֥אשׁ הַשַּׁרְבִֽיט׃ ס","wayĕhiy֩ kirĕʼ֨wòţ hamė֜lekĕ ʼeţ-ʼesĕţé֣̇r hamȧlĕká̇֗h ʻòme֙deţ֙ bėֽẖáẕé֔r náşĕ̂ʼá֥h ẖé֖n bĕ̇ʻéyná֑yw waẏ֨wòşět hamė֜lekĕ lĕʼesĕţé̇֗r ʼeţ-şǎrĕbi֤yt hazá̇háb֙ ʼàşě֣r bĕ̇yád֔wò waţi̇qĕra֣b ʼesĕţé̇֔r waţi̇gȧ֖ʻ bĕ̇rò֥ʼş̌ haşȧ̌rĕbiֽyt׃ s"],[5,3,"וַיֹּ֤אמֶר לָהּ֙ הַמֶּ֔לֶךְ מַה־לָּ֖ךְ אֶסְתֵּ֣ר הַמַּלְכָּ֑ה וּמַה־בַּקָּשָׁתֵ֛ךְ עַד־חֲצִ֥י הַמַּלְכ֖וּת וְיִנָּ֥תֵֽן לָֽךְ׃","wayò֤̇ʼmer láḣ֙ hamė֔lekĕ mah-lá֖̇kĕ ʼesĕţé֣̇r hamȧlĕká֑̇h ẇmah-bȧqá̇şá̌ţé֛kĕ ʻad-ẖàẕi֥y hamȧlĕk֖ẇţ wĕyiná֥̇ţéֽn láֽkĕ׃"],[5,4,"וַתֹּ֣אמֶר אֶסְתֵּ֔ר אִם־עַל־הַמֶּ֖לֶךְ ט֑וֹב יָב֨וֹא הַמֶּ֤לֶךְ וְהָמָן֙ הַיּ֔וֹם אֶל־הַמִּשְׁתֶּ֖ה אֲשֶׁר־עָשִׂ֥יתִי לֽוֹ׃","waţò֣̇ʼmer ʼesĕţé̇֔r ʼim-ʻal-hamė֖lekĕ t֑wòb yáb֨wòʼ hamė֤lekĕ wĕhámán֙ haẏ֔wòm ʼel-hami̇şĕ̌ţė֖h ʼàşěr-ʻáşî֥yţiy lֽwò׃"],[5,5,"וַיֹּ֣אמֶר הַמֶּ֔לֶךְ מַהֲרוּ֙ אֶת־הָמָ֔ן לַעֲשׂ֖וֹת אֶת־דְּבַ֣ר אֶסְתֵּ֑ר וַיָּבֹ֤א הַמֶּ֙לֶךְ֙ וְהָמָ֔ן אֶל־הַמִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","wayò֣̇ʼmer hamė֔lekĕ mahàrẇ֙ ʼeţ-hámá֔n laʻàş֖̂wòţ ʼeţ-dĕ̇ba֣r ʼesĕţé֑̇r wayá̇bò֤ʼ hamė֙lekĕ֙ wĕhámá֔n ʼel-hami̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[5,6,"וַיֹּ֨אמֶר הַמֶּ֤לֶךְ לְאֶסְתֵּר֙ בְּמִשְׁתֵּ֣ה הַיַּ֔יִן מַה־שְּׁאֵלָתֵ֖ךְ וְיִנָּ֣תֵֽן לָ֑ךְ וּמַה־בַּקָּשָׁתֵ֛ךְ עַד־חֲצִ֥י הַמַּלְכ֖וּת וְתֵעָֽשׂ׃","wayò̇֨ʼmer hamė֤lekĕ lĕʼesĕţé̇r֙ bĕ̇mişĕ̌ţé֣̇h hayȧ֔yin mah-şĕ̇̌ʼéláţé֖kĕ wĕyiná֣̇ţéֽn lá֑kĕ ẇmah-bȧqá̇şá̌ţé֛kĕ ʻad-ẖàẕi֥y hamȧlĕk֖ẇţ wĕţéʻáֽş̂׃"],[5,7,"וַתַּ֥עַן אֶסְתֵּ֖ר וַתֹּאמַ֑ר שְׁאֵלָתִ֖י וּבַקָּשָׁתִֽי׃","waţȧ֥ʻan ʼesĕţé֖̇r waţò̇ʼma֑r şĕ̌ʼéláţi֖y ẇbaqá̇şá̌ţiֽy׃"],[5,8,"אִם־מָצָ֨אתִי חֵ֜ן בְּעֵינֵ֣י הַמֶּ֗לֶךְ וְאִם־עַל־הַמֶּ֙לֶךְ֙ ט֔וֹב לָתֵת֙ אֶת־שְׁאֵ֣לָתִ֔י וְלַעֲשׂ֖וֹת אֶת־בַּקָּשָׁתִ֑י יָב֧וֹא הַמֶּ֣לֶךְ וְהָמָ֗ן אֶל־הַמִּשְׁתֶּה֙ אֲשֶׁ֣ר אֶֽעֱשֶׂ֣ה לָהֶ֔ם וּמָחָ֥ר אֶֽעֱשֶׂ֖ה כִּדְבַ֥ר הַמֶּֽלֶךְ׃","ʼim-máẕá֨ʼţiy ẖé֜n bĕ̇ʻéyné֣y hamė֗lekĕ wĕʼim-ʻal-hamė֙lekĕ֙ t֔wòb láţéţ֙ ʼeţ-şĕ̌ʼé֣láţi֔y wĕlaʻàş֖̂wòţ ʼeţ-bȧqá̇şá̌ţi֑y yáb֧wòʼ hamė֣lekĕ wĕhámá֗n ʼel-hami̇şĕ̌ţėh֙ ʼàşě֣r ʼeֽʻèşê֣h láhe֔m ẇmáẖá֥r ʼeֽʻèşê֖h ki̇dĕba֥r hamėֽlekĕ׃"],[5,9,"וַיֵּצֵ֤א הָמָן֙ בַּיּ֣וֹם הַה֔וּא שָׂמֵ֖חַ וְט֣וֹב לֵ֑ב וְכִרְאוֹת֩ הָמָ֨ן אֶֽת־מָרְדֳּכַ֜י בְּשַׁ֣עַר הַמֶּ֗לֶךְ וְלֹא־קָם֙ וְלֹא־זָ֣ע מִמֶּ֔נּוּ וַיִּמָּלֵ֥א הָמָ֛ן עַֽל־מָרְדֳּכַ֖י חֵמָֽה׃","wayé̇ẕé֤ʼ hámán֙ bȧẏ֣wòm hah֔ẇʼ şá̂mé֖ẖa wĕt֣wòb lé֑b wĕkirĕʼwòţ֩ hámá֨n ʼeֽţ-márĕdȯka֜y bĕ̇şǎ֣ʻar hamė֗lekĕ wĕlòʼ-qám֙ wĕlòʼ-zá֣ʻ mimė֔ṅẇ wayi̇má̇lé֥ʼ hámá֛n ʻaֽl-márĕdȯka֖y ẖémáֽh׃"],[5,10,"וַיִּתְאַפַּ֣ק הָמָ֔ן וַיָּב֖וֹא אֶל־בֵּית֑וֹ וַיִּשְׁלַ֛ח וַיָּבֵ֥א אֶת־אֹהֲבָ֖יו וְאֶת־זֶ֥רֶשׁ אִשְׁתּֽוֹ׃","wayi̇ţĕʼapȧ֣q hámá֔n wayá̇b֖wòʼ ʼel-bé̇yţ֑wò wayi̇şĕ̌la֛ẖ wayá̇bé֥ʼ ʼeţ-ʼòhàbá֖yw wĕʼeţ-ze֥reş̌ ʼişĕ̌ţֽ̇wò׃"],[5,11,"וַיְסַפֵּ֨ר לָהֶ֥ם הָמָ֛ן אֶת־כְּב֥וֹד עָשְׁר֖וֹ וְרֹ֣ב בָּנָ֑יו וְאֵת֩ כָּל־אֲשֶׁ֨ר גִּדְּל֤וֹ הַמֶּ֙לֶךְ֙ וְאֵ֣ת אֲשֶׁ֣ר נִשְּׂא֔וֹ עַל־הַשָּׂרִ֖ים וְעַבְדֵ֥י הַמֶּֽלֶךְ׃","wayĕsapé̇֨r láhe֥m hámá֛n ʼeţ-kĕ̇b֥wòd ʻáşĕ̌r֖wò wĕrò֣b bá̇ná֑yw wĕʼéţ֩ ká̇l-ʼàşě֨r gi̇dĕ̇l֤wò hamė֙lekĕ֙ wĕʼé֣ţ ʼàşě֣r nişĕ̇̂ʼ֔wò ʻal-haşá̇̂ri֖ym wĕʻabĕdé֥y hamėֽlekĕ׃"],[5,12,"וַיֹּאמֶר֮ הָמָן֒ אַ֣ף לֹא־הֵבִיאָה֩ אֶסְתֵּ֨ר הַמַּלְכָּ֧ה עִם־הַמֶּ֛לֶךְ אֶל־הַמִּשְׁתֶּ֥ה אֲשֶׁר־עָשָׂ֖תָה כִּ֣י אִם־אוֹתִ֑י וְגַם־לְמָחָ֛ר אֲנִ֥י קָֽרוּא־לָ֖הּ עִם־הַמֶּֽלֶךְ׃","wayò̇ʼmer֮ hámán֒ ʼa֣p lòʼ-hébiyʼáh֩ ʼesĕţé̇֨r hamȧlĕká֧̇h ʻim-hamė֛lekĕ ʼel-hami̇şĕ̌ţė֥h ʼàşěr-ʻáşá֖̂ţáh ki֣̇y ʼim-ʼwòţi֑y wĕgam-lĕmáẖá֛r ʼàni֥y qáֽrẇʼ-lá֖ḣ ʻim-hamėֽlekĕ׃"],[5,13,"וְכָל־זֶ֕ה אֵינֶ֥נּוּ שֹׁוֶ֖ה לִ֑י בְּכָל־עֵ֗ת אֲשֶׁ֨ר אֲנִ֤י רֹאֶה֙ אֶת־מָרְדֳּכַ֣י הַיְּהוּדִ֔י יוֹשֵׁ֖ב בְּשַׁ֥עַר הַמֶּֽלֶךְ׃","wĕkál-ze֕h ʼéyne֥ṅẇ şò̌we֖h li֑y bĕ̇kál-ʻé֗ţ ʼàşě֨r ʼàni֤y ròʼeh֙ ʼeţ-márĕdȯka֣y hayĕ̇hẇdi֔y ywòşé֖̌b bĕ̇şǎ֥ʻar hamėֽlekĕ׃"],[5,14,"וַתֹּ֣אמֶר לוֹ֩ זֶ֨רֶשׁ אִשְׁתּ֜וֹ וְכָל־אֹֽהֲבָ֗יו יַֽעֲשׂוּ־עֵץ֮ גָּבֹ֣הַּ חֲמִשִּׁ֣ים אַמָּה֒ וּבַבֹּ֣קֶר ׀ אֱמֹ֣ר לַמֶּ֗לֶךְ וְיִתְל֤וּ אֶֽת־מָרְדֳּכַי֙ עָלָ֔יו וּבֹֽא־עִם־הַמֶּ֥לֶךְ אֶל הַמִּשְׁתֶּ֖ה שָׂמֵ֑חַ וַיִּיטַ֧ב הַדָּבָ֛ר לִפְנֵ֥י הָמָ֖ן וַיַּ֥עַשׂ הָעֵֽץ׃ פ","waţò֣̇ʼmer lwò֩ ze֨reş̌ ʼişĕ̌ţ̇֜wò wĕkál-ʼòֽhàbá֗yw yaֽʻàş̂ẇ-ʻéẕ֮ gá̇bò֣hȧ ẖàmişi֣̇̌ym ʼamá̇h֒ ẇbabò֣̇qer ׀ ʼèmò֣r lamė֗lekĕ wĕyiţĕl֤ẇ ʼeֽţ-márĕdȯkay֙ ʻálá֔yw ẇbòֽʼ-ʻim-hamė֥lekĕ ʼel hami̇şĕ̌ţė֖h şá̂mé֑ẖa wayi̇yta֧b hadá̇bá֛r lipĕné֥y hámá֖n wayȧ֥ʻaş̂ háʻéֽẕ׃ p"],[6,1,"בַּלַּ֣יְלָה הַה֔וּא נָדְדָ֖ה שְׁנַ֣ת הַמֶּ֑לֶךְ וַיֹּ֗אמֶר לְהָבִ֞יא אֶת־סֵ֤פֶר הַזִּכְרֹנוֹת֙ דִּבְרֵ֣י הַיָּמִ֔ים וַיִּהְי֥וּ נִקְרָאִ֖ים לִפְנֵ֥י הַמֶּֽלֶךְ׃","bȧlȧ֣yĕláh hah֔ẇʼ nádĕdá֖h şĕ̌na֣ţ hamė֑lekĕ wayò̇֗ʼmer lĕhábi֞yʼ ʼeţ-sé֤per hazi̇kĕrònwòţ֙ di̇bĕré֣y hayá̇mi֔ym wayi̇hĕy֥ẇ niqĕráʼi֖ym lipĕné֥y hamėֽlekĕ׃"],[6,2,"וַיִּמָּצֵ֣א כָת֗וּב אֲשֶׁר֩ הִגִּ֨יד מָרְדֳּכַ֜י עַל־בִּגְתָ֣נָא וָתֶ֗רֶשׁ שְׁנֵי֙ סָרִיסֵ֣י הַמֶּ֔לֶךְ מִשֹּׁמְרֵ֖י הַסַּ֑ף אֲשֶׁ֤ר בִּקְשׁוּ֙ לִשְׁלֹ֣חַ יָ֔ד בַּמֶּ֖לֶךְ אֲחַשְׁוֵרֽוֹשׁ׃","wayi̇má̇ẕé֣ʼ káţ֗ẇb ʼàşěr֩ higi̇֨yd márĕdȯka֜y ʻal-bi̇gĕţá֣náʼ wáţe֗reş̌ şĕ̌néy֙ sáriysé֣y hamė֔lekĕ mişò̇̌mĕré֖y hasȧ֑p ʼàşě֤r bi̇qĕş̌ẇ֙ lişĕ̌lò֣ẖa yá֔d bȧmė֖lekĕ ʼàẖaşĕ̌wérֽwòş̌׃"],[6,3,"וַיֹּ֣אמֶר הַמֶּ֔לֶךְ מַֽה־נַּעֲשָׂ֞ה יְקָ֧ר וּגְדוּלָּ֛ה לְמָרְדֳּכַ֖י עַל־זֶ֑ה וַיֹּ֨אמְר֜וּ נַעֲרֵ֤י הַמֶּ֙לֶךְ֙ מְשָׁ֣רְתָ֔יו לֹא־נַעֲשָׂ֥ה עִמּ֖וֹ דָּבָֽר׃","wayò֣̇ʼmer hamė֔lekĕ maֽh-nȧʻàşá̂֞h yĕqá֧r ẇgĕdẇlá֛̇h lĕmárĕdȯka֖y ʻal-ze֑h wayò̇֨ʼmĕr֜ẇ naʻàré֤y hamė֙lekĕ֙ mĕşá֣̌rĕţá֔yw lòʼ-naʻàşá֥̂h ʻiṁ֖wò dá̇báֽr׃"],[6,4,"וַיֹּ֥אמֶר הַמֶּ֖לֶךְ מִ֣י בֶחָצֵ֑ר וְהָמָ֣ן בָּ֗א לַחֲצַ֤ר בֵּית־הַמֶּ֙לֶךְ֙ הַחִ֣יצוֹנָ֔ה לֵאמֹ֣ר לַמֶּ֔לֶךְ לִתְלוֹת֙ אֶֽת־מָרְדֳּכַ֔י עַל־הָעֵ֖ץ אֲשֶׁר־הֵכִ֥ין לֽוֹ׃","wayò֥̇ʼmer hamė֖lekĕ mi֣y beẖáẕé֑r wĕhámá֣n bá̇֗ʼ laẖàẕa֤r bé̇yţ-hamė֙lekĕ֙ haẖi֣yẕwòná֔h léʼmò֣r lamė֔lekĕ liţĕlwòţ֙ ʼeֽţ-márĕdȯka֔y ʻal-háʻé֖ẕ ʼàşěr-héki֥yn lֽwò׃"],[6,5,"וַיֹּ֨אמְר֜וּ נַעֲרֵ֤י הַמֶּ֙לֶךְ֙ אֵלָ֔יו הִנֵּ֥ה הָמָ֖ן עֹמֵ֣ד בֶּחָצֵ֑ר וַיֹּ֥אמֶר הַמֶּ֖לֶךְ יָבֽוֹא׃","wayò̇֨ʼmĕr֜ẇ naʻàré֤y hamė֙lekĕ֙ ʼélá֔yw hiné֥̇h hámá֖n ʻòmé֣d bėẖáẕé֑r wayò֥̇ʼmer hamė֖lekĕ yábֽwòʼ׃"],[6,6,"וַיָּבוֹא֮ הָמָן֒ וַיֹּ֤אמֶר לוֹ֙ הַמֶּ֔לֶךְ מַה־לַעֲשׂ֕וֹת בָּאִ֕ישׁ אֲשֶׁ֥ר הַמֶּ֖לֶךְ חָפֵ֣ץ בִּיקָר֑וֹ וַיֹּ֤אמֶר הָמָן֙ בְּלִבּ֔וֹ לְמִ֞י יַחְפֹּ֥ץ הַמֶּ֛לֶךְ לַעֲשׂ֥וֹת יְקָ֖ר יוֹתֵ֥ר מִמֶּֽנִּי׃","wayá̇bwòʼ֮ hámán֒ wayò֤̇ʼmer lwò֙ hamė֔lekĕ mah-laʻàş̂֕wòţ bá̇ʼi֕yş̌ ʼàşě֥r hamė֖lekĕ ẖápé֣ẕ bi̇yqár֑wò wayò֤̇ʼmer hámán֙ bĕ̇liḃ֔wò lĕmi֞y yaẖĕpò֥̇ẕ hamė֛lekĕ laʻàş֥̂wòţ yĕqá֖r ywòţé֥r mimėֽni̇y׃"],[6,7,"וַיֹּ֥אמֶר הָמָ֖ן אֶל־הַמֶּ֑לֶךְ אִ֕ישׁ אֲשֶׁ֥ר הַמֶּ֖לֶךְ חָפֵ֥ץ בִּיקָרֽוֹ׃","wayò֥̇ʼmer hámá֖n ʼel-hamė֑lekĕ ʼi֕yş̌ ʼàşě֥r hamė֖lekĕ ẖápé֥ẕ bi̇yqárֽwò׃"],[6,8,"יָבִ֙יאוּ֙ לְב֣וּשׁ מַלְכ֔וּת אֲשֶׁ֥ר לָֽבַשׁ־בּ֖וֹ הַמֶּ֑לֶךְ וְס֗וּס אֲשֶׁ֨ר רָכַ֤ב עָלָיו֙ הַמֶּ֔לֶךְ וַאֲשֶׁ֥ר נִתַּ֛ן כֶּ֥תֶר מַלְכ֖וּת בְּרֹאשֽׁוֹ׃","yábi֙yʼẇ֙ lĕb֣ẇş̌ malĕk֔ẇţ ʼàşě֥r láֽbaş̌-ḃ֖wò hamė֑lekĕ wĕs֗ẇs ʼàşě֨r ráka֤b ʻáláyw֙ hamė֔lekĕ waʼàşě֥r niţȧ֛n kė֥ţer malĕk֖ẇţ bĕ̇ròʼşֽ̌wò׃"],[6,9,"וְנָת֨וֹן הַלְּב֜וּשׁ וְהַסּ֗וּס עַל־יַד־אִ֞ישׁ מִשָּׂרֵ֤י הַמֶּ֙לֶךְ֙ הַֽפַּרְתְּמִ֔ים וְהִלְבִּ֙ישׁוּ֙ אֶת־הָאִ֔ישׁ אֲשֶׁ֥ר הַמֶּ֖לֶךְ חָפֵ֣ץ בִּֽיקָר֑וֹ וְהִרְכִּיבֻ֤הוּ עַל־הַסּוּס֙ בִּרְח֣וֹב הָעִ֔יר וְקָרְא֣וּ לְפָנָ֔יו כָּ֚כָה יֵעָשֶׂ֣ה לָאִ֔ישׁ אֲשֶׁ֥ר הַמֶּ֖לֶךְ חָפֵ֥ץ בִּיקָרֽוֹ׃","wĕnáţ֨wòn halĕ̇b֜ẇş̌ wĕhaṡ֗ẇs ʻal-yad-ʼi֞yş̌ mişá̇̂ré֤y hamė֙lekĕ֙ haֽpȧrĕţĕ̇mi֔ym wĕhilĕbi̇֙yş̌ẇ֙ ʼeţ-háʼi֔yş̌ ʼàşě֥r hamė֖lekĕ ẖápé֣ẕ biֽ̇yqár֑wò wĕhirĕki̇ybu֤hẇ ʻal-haṡẇs֙ bi̇rĕẖ֣wòb háʻi֔yr wĕqárĕʼ֣ẇ lĕpáná֔yw ká֚̇káh yéʻáşê֣h láʼi֔yş̌ ʼàşě֥r hamė֖lekĕ ẖápé֥ẕ bi̇yqárֽwò׃"],[6,10,"וַיֹּ֨אמֶר הַמֶּ֜לֶךְ לְהָמָ֗ן מַ֠הֵר קַ֣ח אֶת־הַלְּב֤וּשׁ וְאֶת־הַסּוּס֙ כַּאֲשֶׁ֣ר דִּבַּ֔רְתָּ וַֽעֲשֵׂה־כֵן֙ לְמָרְדֳּכַ֣י הַיְּהוּדִ֔י הַיּוֹשֵׁ֖ב בְּשַׁ֣עַר הַמֶּ֑לֶךְ אַל־תַּפֵּ֣ל דָּבָ֔ר מִכֹּ֖ל אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wayò̇֨ʼmer hamė֜lekĕ lĕhámá֗n ma֠hér qa֣ẖ ʼeţ-halĕ̇b֤ẇş̌ wĕʼeţ-haṡẇs֙ kȧʼàşě֣r di̇bȧ֔rĕţá̇ waֽʻàşé̂h-kén֙ lĕmárĕdȯka֣y hayĕ̇hẇdi֔y haẏwòşé֖̌b bĕ̇şǎ֣ʻar hamė֑lekĕ ʼal-ţȧpé֣̇l dá̇bá֔r mikò֖̇l ʼàşě֥r di̇bȧֽrĕţá̇׃"],[6,11,"וַיִּקַּ֤ח הָמָן֙ אֶת־הַלְּב֣וּשׁ וְאֶת־הַסּ֔וּס וַיַּלְבֵּ֖שׁ אֶֽת־מָרְדֳּכָ֑י וַיַּרְכִּיבֵ֙הוּ֙ בִּרְח֣וֹב הָעִ֔יר וַיִּקְרָ֣א לְפָנָ֔יו כָּ֚כָה יֵעָשֶׂ֣ה לָאִ֔ישׁ אֲשֶׁ֥ר הַמֶּ֖לֶךְ חָפֵ֥ץ בִּיקָרֽוֹ׃","wayi̇qȧ֤ẖ hámán֙ ʼeţ-halĕ̇b֣ẇş̌ wĕʼeţ-haṡ֔ẇs wayȧlĕbé֖̇ş̌ ʼeֽţ-márĕdȯká֑y wayȧrĕki̇ybé֙hẇ֙ bi̇rĕẖ֣wòb háʻi֔yr wayi̇qĕrá֣ʼ lĕpáná֔yw ká֚̇káh yéʻáşê֣h láʼi֔yş̌ ʼàşě֥r hamė֖lekĕ ẖápé֥ẕ bi̇yqárֽwò׃"],[6,12,"וַיָּ֥שָׁב מָרְדֳּכַ֖י אֶל־שַׁ֣עַר הַמֶּ֑לֶךְ וְהָמָן֙ נִדְחַ֣ף אֶל־בֵּית֔וֹ אָבֵ֖ל וַחֲפ֥וּי רֹֽאשׁ׃","wayá֥̇şá̌b márĕdȯka֖y ʼel-şǎ֣ʻar hamė֑lekĕ wĕhámán֙ nidĕẖa֣p ʼel-bé̇yţ֔wò ʼábé֖l waẖàp֥ẇy ròֽʼş̌׃"],[6,13,"וַיְסַפֵּ֨ר הָמָ֜ן לְזֶ֤רֶשׁ אִשְׁתּוֹ֙ וּלְכָל־אֹ֣הֲבָ֔יו אֵ֖ת כָּל־אֲשֶׁ֣ר קָרָ֑הוּ וַיֹּ֩אמְרוּ֩ ל֨וֹ חֲכָמָ֜יו וְזֶ֣רֶשׁ אִשְׁתּ֗וֹ אִ֣ם מִזֶּ֣רַע הַיְּהוּדִ֡ים מָרְדֳּכַ֞י אֲשֶׁר֩ הַחִלּ֨וֹתָ לִנְפֹּ֤ל לְפָנָיו֙ לֹא־תוּכַ֣ל ל֔וֹ כִּֽי־נָפ֥וֹל תִּפּ֖וֹל לְפָנָֽיו׃","wayĕsapé̇֨r hámá֜n lĕze֤reş̌ ʼişĕ̌ţ̇wò֙ ẇlĕkál-ʼò֣hàbá֔yw ʼé֖ţ ká̇l-ʼàşě֣r qárá֑hẇ wayò̇֩ʼmĕrẇ֩ l֨wò ẖàkámá֜yw wĕze֣reş̌ ʼişĕ̌ţ̇֗wò ʼi֣m mizė֣raʻ hayĕ̇hẇdi֡ym márĕdȯka֞y ʼàşěr֩ haẖil̇֨wòţá linĕpò֤̇l lĕpánáyw֙ lòʼ-ţẇka֣l l֔wò kiֽ̇y-náp֥wòl ţi̇ṗ֖wòl lĕpánáֽyw׃"],[6,14,"עוֹדָם֙ מְדַבְּרִ֣ים עִמּ֔וֹ וְסָרִיסֵ֥י הַמֶּ֖לֶךְ הִגִּ֑יעוּ וַיַּבְהִ֙לוּ֙ לְהָבִ֣יא אֶת־הָמָ֔ן אֶל־הַמִּשְׁתֶּ֖ה אֲשֶׁר־עָשְׂתָ֥ה אֶסְתֵּֽר׃","ʻwòdám֙ mĕdabĕ̇ri֣ym ʻiṁ֔wò wĕsáriysé֥y hamė֖lekĕ higi֑̇yʻẇ wayȧbĕhi֙lẇ֙ lĕhábi֣yʼ ʼeţ-hámá֔n ʼel-hami̇şĕ̌ţė֖h ʼàşěr-ʻáşĕ̂ţá֥h ʼesĕţéֽ̇r׃"],[7,1,"וַיָּבֹ֤א הַמֶּ֙לֶךְ֙ וְהָמָ֔ן לִשְׁתּ֖וֹת עִם־אֶסְתֵּ֥ר הַמַּלְכָּֽה׃","wayá̇bò֤ʼ hamė֙lekĕ֙ wĕhámá֔n lişĕ̌ţ֖̇wòţ ʻim-ʼesĕţé֥̇r hamȧlĕkáֽ̇h׃"],[7,2,"וַיֹּאמֶר֩ הַמֶּ֨לֶךְ לְאֶסְתֵּ֜ר גַּ֣ם בַּיּ֤וֹם הַשֵּׁנִי֙ בְּמִשְׁתֵּ֣ה הַיַּ֔יִן מַה־שְּׁאֵלָתֵ֛ךְ אֶסְתֵּ֥ר הַמַּלְכָּ֖ה וְתִנָּ֣תֵֽן לָ֑ךְ וּמַה־בַּקָּשָׁתֵ֛ךְ עַד־חֲצִ֥י הַמַּלְכ֖וּת וְתֵעָֽשׂ׃","wayò̇ʼmer֩ hamė֨lekĕ lĕʼesĕţé̇֜r gȧ֣m bȧẏ֤wòm haşé̇̌niy֙ bĕ̇mişĕ̌ţé֣̇h hayȧ֔yin mah-şĕ̇̌ʼéláţé֛kĕ ʼesĕţé֥̇r hamȧlĕká֖̇h wĕţiná֣̇ţéֽn lá֑kĕ ẇmah-bȧqá̇şá̌ţé֛kĕ ʻad-ẖàẕi֥y hamȧlĕk֖ẇţ wĕţéʻáֽş̂׃"],[7,3,"וַתַּ֨עַן אֶסְתֵּ֤ר הַמַּלְכָּה֙ וַתֹּאמַ֔ר אִם־מָצָ֨אתִי חֵ֤ן בְּעֵינֶ֙יךָ֙ הַמֶּ֔לֶךְ וְאִם־עַל־הַמֶּ֖לֶךְ ט֑וֹב תִּנָּֽתֶן־לִ֤י נַפְשִׁי֙ בִּשְׁאֵ֣לָתִ֔י וְעַמִּ֖י בְּבַקָּשָׁתִֽי׃","waţȧ֨ʻan ʼesĕţé֤̇r hamȧlĕká̇h֙ waţò̇ʼma֔r ʼim-máẕá֨ʼţiy ẖé֤n bĕ̇ʻéyne֙yká֙ hamė֔lekĕ wĕʼim-ʻal-hamė֖lekĕ t֑wòb ţi̇náֽ̇ţen-li֤y napĕşǐy֙ bi̇şĕ̌ʼé֣láţi֔y wĕʻami֖̇y bĕ̇baqá̇şá̌ţiֽy׃"],[7,4,"כִּ֤י נִמְכַּ֙רְנוּ֙ אֲנִ֣י וְעַמִּ֔י לְהַשְׁמִ֖יד לַהֲר֣וֹג וּלְאַבֵּ֑ד וְ֠אִלּוּ לַעֲבָדִ֨ים וְלִשְׁפָח֤וֹת נִמְכַּ֙רְנוּ֙ הֶחֱרַ֔שְׁתִּי כִּ֣י אֵ֥ין הַצָּ֛ר שֹׁוֶ֖ה בְּנֵ֥זֶק הַמֶּֽלֶךְ׃ ס","ki֤̇y nimĕkȧ֙rĕnẇ֙ ʼàni֣y wĕʻami̇֔y lĕhaşĕ̌mi֖yd lahàr֣wòg ẇlĕʼabé֑̇d wĕ֠ʼil̇ẇ laʻàbádi֨ym wĕlişĕ̌páẖ֤wòţ nimĕkȧ֙rĕnẇ֙ heẖèra֔şĕ̌ţi̇y ki֣̇y ʼé֥yn haẕá֛̇r şò̌we֖h bĕ̇né֥zeq hamėֽlekĕ׃ s"],[7,5,"וַיֹּ֙אמֶר֙ הַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וַיֹּ֖אמֶר לְאֶסְתֵּ֣ר הַמַּלְכָּ֑ה מִ֣י ה֥וּא זֶה֙ וְאֵֽי־זֶ֣ה ה֔וּא אֲשֶׁר־מְלָא֥וֹ לִבּ֖וֹ לַעֲשׂ֥וֹת כֵּֽן׃","wayò̇֙ʼmer֙ hamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wayò֖̇ʼmer lĕʼesĕţé֣̇r hamȧlĕká֑̇h mi֣y h֥ẇʼ zeh֙ wĕʼéֽy-ze֣h h֔ẇʼ ʼàşěr-mĕláʼ֥wò liḃ֖wò laʻàş֥̂wòţ kéֽ̇n׃"],[7,6,"וַתֹּ֣אמֶר־אֶסְתֵּ֔ר אִ֚ישׁ צַ֣ר וְאוֹיֵ֔ב הָמָ֥ן הָרָ֖ע הַזֶּ֑ה וְהָמָ֣ן נִבְעַ֔ת מִלִּפְנֵ֥י הַמֶּ֖לֶךְ וְהַמַּלְכָּֽה׃","waţò֣̇ʼmer-ʼesĕţé̇֔r ʼi֚yş̌ ẕa֣r wĕʼwòyé֔b hámá֥n hárá֖ʻ hazė֑h wĕhámá֣n nibĕʻa֔ţ mili̇pĕné֥y hamė֖lekĕ wĕhamȧlĕkáֽ̇h׃"],[7,7,"וְהַמֶּ֜לֶךְ קָ֤ם בַּחֲמָתוֹ֙ מִמִּשְׁתֵּ֣ה הַיַּ֔יִן אֶל־גִּנַּ֖ת הַבִּיתָ֑ן וְהָמָ֣ן עָמַ֗ד לְבַקֵּ֤שׁ עַל־נַפְשׁוֹ֙ מֵֽאֶסְתֵּ֣ר הַמַּלְכָּ֔ה כִּ֣י רָאָ֔ה כִּֽי־כָלְתָ֥ה אֵלָ֛יו הָרָעָ֖ה מֵאֵ֥ת הַמֶּֽלֶךְ׃","wĕhamė֜lekĕ qá֤m bȧẖàmáţwò֙ mimi̇şĕ̌ţé֣̇h hayȧ֔yin ʼel-gi̇nȧ֖ţ habi̇yţá֑n wĕhámá֣n ʻáma֗d lĕbaqé֤̇ş̌ ʻal-napĕş̌wò֙ méֽʼesĕţé֣̇r hamȧlĕká̇֔h ki֣̇y ráʼá֔h kiֽ̇y-kálĕţá֥h ʼélá֛yw háráʻá֖h méʼé֥ţ hamėֽlekĕ׃"],[7,8,"וְהַמֶּ֡לֶךְ שָׁב֩ מִגִּנַּ֨ת הַבִּיתָ֜ן אֶל־בֵּ֣ית ׀ מִשְׁתֵּ֣ה הַיַּ֗יִן וְהָמָן֙ נֹפֵ֔ל עַל־הַמִּטָּה֙ אֲשֶׁ֣ר אֶסְתֵּ֣ר עָלֶ֔יהָ וַיֹּ֣אמֶר הַמֶּ֔לֶךְ הֲ֠גַם לִכְבּ֧וֹשׁ אֶת־הַמַּלְכָּ֛ה עִמִּ֖י בַּבָּ֑יִת הַדָּבָ֗ר יָצָא֙ מִפִּ֣י הַמֶּ֔לֶךְ וּפְנֵ֥י הָמָ֖ן חָפֽוּ׃ ס","wĕhamė֡lekĕ şá̌b֩ migi̇nȧ֨ţ habi̇yţá֜n ʼel-bé֣̇yţ ׀ mişĕ̌ţé֣̇h hayȧ֗yin wĕhámán֙ nòpé֔l ʻal-hami̇tá̇h֙ ʼàşě֣r ʼesĕţé֣̇r ʻále֔yhá wayò֣̇ʼmer hamė֔lekĕ hà֠gam likĕḃ֧wòş̌ ʼeţ-hamȧlĕká֛̇h ʻimi֖̇y bȧbá֑̇yiţ hadá̇bá֗r yáẕáʼ֙ mipi֣̇y hamė֔lekĕ ẇpĕné֥y hámá֖n ẖápֽẇ׃ s"],[7,9,"וַיֹּ֣אמֶר חַ֠רְבוֹנָה אֶחָ֨ד מִן־הַסָּרִיסִ֜ים לִפְנֵ֣י הַמֶּ֗לֶךְ גַּ֣ם הִנֵּה־הָעֵ֣ץ אֲשֶׁר־עָשָׂ֪ה הָמָ֟ן לְֽמָרְדֳּכַ֞י אֲשֶׁ֧ר דִּבֶּר־ט֣וֹב עַל־הַמֶּ֗לֶךְ עֹמֵד֙ בְּבֵ֣ית הָמָ֔ן גָּבֹ֖הַּ חֲמִשִּׁ֣ים אַמָּ֑ה וַיֹּ֥אמֶר הַמֶּ֖לֶךְ תְּלֻ֥הוּ עָלָֽיו׃","wayò֣̇ʼmer ẖa֠rĕbwònáh ʼeẖá֨d min-hasá̇riysi֜ym lipĕné֣y hamė֗lekĕ gȧ֣m hiné̇h-háʻé֣ẕ ʼàşěr-ʻáşá֪̂h hámá֟n lĕֽmárĕdȯka֞y ʼàşě֧r di̇bėr-t֣wòb ʻal-hamė֗lekĕ ʻòméd֙ bĕ̇bé֣yţ hámá֔n gá̇bò֖hȧ ẖàmişi֣̇̌ym ʼamá֑̇h wayò֥̇ʼmer hamė֖lekĕ ţĕ̇lu֥hẇ ʻáláֽyw׃"],[7,10,"וַיִּתְלוּ֙ אֶת־הָמָ֔ן עַל־הָעֵ֖ץ אֲשֶׁר־הֵכִ֣ין לְמָרְדֳּכָ֑י וַחֲמַ֥ת הַמֶּ֖לֶךְ שָׁכָֽכָה׃ פ","wayi̇ţĕlẇ֙ ʼeţ-hámá֔n ʻal-háʻé֖ẕ ʼàşěr-héki֣yn lĕmárĕdȯká֑y waẖàma֥ţ hamė֖lekĕ şá̌káֽkáh׃ p"],[8,1,"בַּיּ֣וֹם הַה֗וּא נָתַ֞ן הַמֶּ֤לֶךְ אֲחַשְׁוֵרוֹשׁ֙ לְאֶסְתֵּ֣ר הַמַּלְכָּ֔ה אֶת־בֵּ֥ית הָמָ֖ן צֹרֵ֣ר היהודיים וּמָרְדֳּכַ֗י בָּ֚א לִפְנֵ֣י הַמֶּ֔לֶךְ כִּֽי־הִגִּ֥ידָה אֶסְתֵּ֖ר מַ֥ה הוּא־לָֽהּ׃","bȧẏ֣wòm hah֗ẇʼ náţa֞n hamė֤lekĕ ʼàẖaşĕ̌wérwòş̌֙ lĕʼesĕţé֣̇r hamȧlĕká̇֔h ʼeţ-bé֥̇yţ hámá֖n ẕòré֣r hyhwdyym ẇmárĕdȯka֗y bá֚̇ʼ lipĕné֣y hamė֔lekĕ kiֽ̇y-higi֥̇ydáh ʼesĕţé֖̇r ma֥h hẇʼ-láֽḣ׃"],[8,2,"וַיָּ֨סַר הַמֶּ֜לֶךְ אֶת־טַבַּעְתּ֗וֹ אֲשֶׁ֤ר הֶֽעֱבִיר֙ מֵֽהָמָ֔ן וַֽיִּתְּנָ֖הּ לְמָרְדֳּכָ֑י וַתָּ֧שֶׂם אֶסְתֵּ֛ר אֶֽת־מָרְדֳּכַ֖י עַל־בֵּ֥ית הָמָֽן׃ פ","wayá̇֨sar hamė֜lekĕ ʼeţ-tabȧʻĕţ̇֗wò ʼàşě֤r heֽʻèbiyr֙ méֽhámá֔n waֽyi̇ţĕ̇ná֖ḣ lĕmárĕdȯká֑y waţá֧̇şêm ʼesĕţé֛̇r ʼeֽţ-márĕdȯka֖y ʻal-bé֥̇yţ hámáֽn׃ p"],[8,3,"וַתּ֣וֹסֶף אֶסְתֵּ֗ר וַתְּדַבֵּר֙ לִפְנֵ֣י הַמֶּ֔לֶךְ וַתִּפֹּ֖ל לִפְנֵ֣י רַגְלָ֑יו וַתֵּ֣בְךְּ וַתִּתְחַנֶּן־ל֗וֹ לְהַֽעֲבִיר֙ אֶת־רָעַת֙ הָמָ֣ן הָֽאֲגָגִ֔י וְאֵת֙ מַֽחֲשַׁבְתּ֔וֹ אֲשֶׁ֥ר חָשַׁ֖ב עַל־הַיְּהוּדִֽים׃","waţ֣̇wòsep ʼesĕţé̇֗r waţĕ̇dabé̇r֙ lipĕné֣y hamė֔lekĕ waţi̇pò֖̇l lipĕné֣y ragĕlá֑yw waţé֣̇bĕkĕ̇ waţi̇ţĕẖanėn-l֗wò lĕhaֽʻàbiyr֙ ʼeţ-ráʻaţ֙ hámá֣n háֽʼàgági֔y wĕʼéţ֙ maֽẖàşǎbĕţ̇֔wò ʼàşě֥r ẖáşǎ֖b ʻal-hayĕ̇hẇdiֽym׃"],[8,4,"וַיּ֤וֹשֶׁט הַמֶּ֙לֶךְ֙ לְאֶסְתֵּ֔ר אֵ֖ת שַׁרְבִ֣ט הַזָּהָ֑ב וַתָּ֣קָם אֶסְתֵּ֔ר וַֽתַּעֲמֹ֖ד לִפְנֵ֥י הַמֶּֽלֶךְ׃","waẏ֤wòşět hamė֙lekĕ֙ lĕʼesĕţé̇֔r ʼé֖ţ şǎrĕbi֣t hazá̇há֑b waţá֣̇qám ʼesĕţé̇֔r waֽţȧʻàmò֖d lipĕné֥y hamėֽlekĕ׃"],[8,5,"וַ֠תֹּאמֶר אִם־עַל־הַמֶּ֨לֶךְ ט֜וֹב וְאִם־מָצָ֧אתִי חֵ֣ן לְפָנָ֗יו וְכָשֵׁ֤ר הַדָּבָר֙ לִפְנֵ֣י הַמֶּ֔לֶךְ וְטוֹבָ֥ה אֲנִ֖י בְּעֵינָ֑יו יִכָּתֵ֞ב לְהָשִׁ֣יב אֶת־הַסְּפָרִ֗ים מַחֲשֶׁ֜בֶת הָמָ֤ן בֶּֽן־הַמְּדָ֙תָא֙ הָאֲגָגִ֔י אֲשֶׁ֣ר כָּתַ֗ב לְאַבֵּד֙ אֶת־הַיְּהוּדִ֔ים אֲשֶׁ֖ר בְּכָל־מְדִינ֥וֹת הַמֶּֽלֶךְ׃","wa֠ţò̇ʼmer ʼim-ʻal-hamė֨lekĕ t֜wòb wĕʼim-máẕá֧ʼţiy ẖé֣n lĕpáná֗yw wĕkáşé֤̌r hadá̇bár֙ lipĕné֣y hamė֔lekĕ wĕtwòbá֥h ʼàni֖y bĕ̇ʻéyná֑yw yiká̇ţé֞b lĕháşǐ֣yb ʼeţ-hasĕ̇pári֗ym maẖàşě֜beţ hámá֤n bėֽn-hamĕ̇dá֙ţáʼ֙ háʼàgági֔y ʼàşě֣r ká̇ţa֗b lĕʼabé̇d֙ ʼeţ-hayĕ̇hẇdi֔ym ʼàşě֖r bĕ̇kál-mĕdiyn֥wòţ hamėֽlekĕ׃"],[8,6,"כִּ֠י אֵיכָכָ֤ה אוּכַל֙ וְֽרָאִ֔יתִי בָּרָעָ֖ה אֲשֶׁר־יִמְצָ֣א אֶת־עַמִּ֑י וְאֵֽיכָכָ֤ה אוּכַל֙ וְֽרָאִ֔יתִי בְּאָבְדַ֖ן מוֹלַדְתִּֽי׃ ס","ki̇֠y ʼéykáká֤h ʼẇkal֙ wĕֽráʼi֔yţiy bá̇ráʻá֖h ʼàşěr-yimĕẕá֣ʼ ʼeţ-ʻami֑̇y wĕʼéֽykáká֤h ʼẇkal֙ wĕֽráʼi֔yţiy bĕ̇ʼábĕda֖n mwòladĕţiֽ̇y׃ s"],[8,7,"וַיֹּ֨אמֶר הַמֶּ֤לֶךְ אֲחַשְׁוֵרֹשׁ֙ לְאֶסְתֵּ֣ר הַמַּלְכָּ֔ה וּֽלְמָרְדֳּכַ֖י הַיְּהוּדִ֑י הִנֵּ֨ה בֵית־הָמָ֜ן נָתַ֣תִּי לְאֶסְתֵּ֗ר וְאֹתוֹ֙ תָּל֣וּ עַל־הָעֵ֔ץ עַ֛ל אֲשֶׁר־שָׁלַ֥ח יָד֖וֹ ביהודיים׃","wayò̇֨ʼmer hamė֤lekĕ ʼàẖaşĕ̌wéròş̌֙ lĕʼesĕţé֣̇r hamȧlĕká̇֔h ẇֽlĕmárĕdȯka֖y hayĕ̇hẇdi֑y hiné̇֨h béyţ-hámá֜n náţa֣ţi̇y lĕʼesĕţé̇֗r wĕʼòţwò֙ ţá̇l֣ẇ ʻal-háʻé֔ẕ ʻa֛l ʼàşěr-şá̌la֥ẖ yád֖wò byhwdyym׃"],[8,8,"וְ֠אַתֶּם כִּתְב֨וּ עַל־הַיְּהוּדִ֜ים כַּטּ֤וֹב בְּעֵֽינֵיכֶם֙ בְּשֵׁ֣ם הַמֶּ֔לֶךְ וְחִתְמ֖וּ בְּטַבַּ֣עַת הַמֶּ֑לֶךְ כִּֽי־כְתָ֞ב אֲשֶׁר־נִכְתָּ֣ב בְּשֵׁם־הַמֶּ֗לֶךְ וְנַחְתּ֛וֹם בְּטַבַּ֥עַת הַמֶּ֖לֶךְ אֵ֥ין לְהָשִֽׁיב׃","wĕ֠ʼaţėm ki̇ţĕb֨ẇ ʻal-hayĕ̇hẇdi֜ym kȧṫ֤wòb bĕ̇ʻéֽynéykem֙ bĕ̇şé֣̌m hamė֔lekĕ wĕẖiţĕm֖ẇ bĕ̇tabȧ֣ʻaţ hamė֑lekĕ kiֽ̇y-kĕţá֞b ʼàşěr-nikĕţá֣̇b bĕ̇şé̌m-hamė֗lekĕ wĕnaẖĕţ֛̇wòm bĕ̇tabȧ֥ʻaţ hamė֖lekĕ ʼé֥yn lĕháşǐֽyb׃"],[8,9,"וַיִּקָּרְא֣וּ סֹפְרֵֽי־הַמֶּ֣לֶךְ בָּֽעֵת־הַ֠הִיא בַּחֹ֨דֶשׁ הַשְּׁלִישִׁ֜י הוּא־חֹ֣דֶשׁ סִיוָ֗ן בִּשְׁלוֹשָׁ֣ה וְעֶשְׂרִים֮ בּוֹ֒ וַיִּכָּתֵ֣ב כְּֽכָל־אֲשֶׁר־צִוָּ֣ה מָרְדֳּכַ֣י אֶל־הַיְּהוּדִ֡ים וְאֶ֣ל הָאֲחַשְׁדַּרְפְּנִֽים־וְהַפַּחוֹת֩ וְשָׂרֵ֨י הַמְּדִינ֜וֹת אֲשֶׁ֣ר ׀ מֵהֹ֣דּוּ וְעַד־כּ֗וּשׁ שֶׁ֣בַע וְעֶשְׂרִ֤ים וּמֵאָה֙ מְדִינָ֔ה מְדִינָ֤ה וּמְדִינָה֙ כִּכְתָבָ֔הּ וְעַ֥ם וָעָ֖ם כִּלְשֹׁנ֑וֹ וְאֶ֨ל־הַיְּהוּדִ֔ים כִּכְתָבָ֖ם וְכִלְשׁוֹנָֽם׃","wayi̇qá̇rĕʼ֣ẇ sòpĕréֽy-hamė֣lekĕ báֽ̇ʻéţ-ha֠hiyʼ bȧẖò֨deş̌ haşĕ̇̌liyşǐ֜y hẇʼ-ẖò֣deş̌ siywá֗n bi̇şĕ̌lwòşá֣̌h wĕʻeşĕ̂riym֮ ḃwò֒ wayi̇ká̇ţé֣b kĕֽ̇kál-ʼàşěr-ẕiwá֣̇h márĕdȯka֣y ʼel-hayĕ̇hẇdi֡ym wĕʼe֣l háʼàẖaşĕ̌dȧrĕpĕ̇niֽym-wĕhapȧẖwòţ֩ wĕşá̂ré֨y hamĕ̇diyn֜wòţ ʼàşě֣r ׀ méhò֣ḋẇ wĕʻad-k̇֗ẇş̌ şě֣baʻ wĕʻeşĕ̂ri֤ym ẇméʼáh֙ mĕdiyná֔h mĕdiyná֤h ẇmĕdiynáh֙ ki̇kĕţábá֔ḣ wĕʻa֥m wáʻá֖m ki̇lĕşò̌n֑wò wĕʼe֨l-hayĕ̇hẇdi֔ym ki̇kĕţábá֖m wĕkilĕş̌wònáֽm׃"],[8,10,"וַיִּכְתֹּ֗ב בְּשֵׁם֙ הַמֶּ֣לֶךְ אֲחַשְׁוֵרֹ֔שׁ וַיַּחְתֹּ֖ם בְּטַבַּ֣עַת הַמֶּ֑לֶךְ וַיִּשְׁלַ֣ח סְפָרִ֡ים בְּיַד֩ הָרָצִ֨ים בַּסּוּסִ֜ים רֹכְבֵ֤י הָרֶ֙כֶשׁ֙ הָֽאֲחַשְׁתְּרָנִ֔ים בְּנֵ֖י הָֽרַמָּכִֽים׃","wayi̇kĕţò̇֗b bĕ̇şé̌m֙ hamė֣lekĕ ʼàẖaşĕ̌wérò֔ş̌ wayȧẖĕţò֖̇m bĕ̇tabȧ֣ʻaţ hamė֑lekĕ wayi̇şĕ̌la֣ẖ sĕpári֡ym bĕ̇yad֩ háráẕi֨ym bȧṡẇsi֜ym ròkĕbé֤y háre֙keş̌֙ háֽʼàẖaşĕ̌ţĕ̇ráni֔ym bĕ̇né֖y háֽramá̇kiֽym׃"],[8,11,"אֲשֶׁר֩ נָתַ֨ן הַמֶּ֜לֶךְ לַיְּהוּדִ֣ים ׀ אֲשֶׁ֣ר בְּכָל־עִיר־וָעִ֗יר לְהִקָּהֵל֮ וְלַעֲמֹ֣ד עַל־נַפְשָׁם֒ לְהַשְׁמִיד֩ וְלַהֲרֹ֨ג וּלְאַבֵּ֜ד אֶת־כָּל־חֵ֨יל עַ֧ם וּמְדִינָ֛ה הַצָּרִ֥ים אֹתָ֖ם טַ֣ף וְנָשִׁ֑ים וּשְׁלָלָ֖ם לָבֽוֹז׃","ʼàşěr֩ náţa֨n hamė֜lekĕ layĕ̇hẇdi֣ym ׀ ʼàşě֣r bĕ̇kál-ʻiyr-wáʻi֗yr lĕhiqá̇hél֮ wĕlaʻàmò֣d ʻal-napĕşá̌m֒ lĕhaşĕ̌miyd֩ wĕlahàrò֨g ẇlĕʼabé̇֜d ʼeţ-ká̇l-ẖé֨yl ʻa֧m ẇmĕdiyná֛h haẕá̇ri֥ym ʼòţá֖m ta֣p wĕnáşǐ֑ym ẇşĕ̌lálá֖m lábֽwòz׃"],[8,12,"בְּי֣וֹם אֶחָ֔ד בְּכָל־מְדִינ֖וֹת הַמֶּ֣לֶךְ אֲחַשְׁוֵר֑וֹשׁ בִּשְׁלוֹשָׁ֥ה עָשָׂ֛ר לְחֹ֥דֶשׁ שְׁנֵים־עָשָׂ֖ר הוּא־חֹ֥דֶשׁ אֲדָֽר׃","bĕ̇y֣wòm ʼeẖá֔d bĕ̇kál-mĕdiyn֖wòţ hamė֣lekĕ ʼàẖaşĕ̌wér֑wòş̌ bi̇şĕ̌lwòşá֥̌h ʻáşá֛̂r lĕẖò֥deş̌ şĕ̌néym-ʻáşá֖̂r hẇʼ-ẖò֥deş̌ ʼàdáֽr׃"],[8,13,"פַּתְשֶׁ֣גֶן הַכְּתָ֗ב לְהִנָּ֤תֵֽן דָּת֙ בְּכָל־מְדִינָ֣ה וּמְדִינָ֔ה גָּל֖וּי לְכָל־הָעַמִּ֑ים וְלִהְי֨וֹת היהודיים עתודים לַיּ֣וֹם הַזֶּ֔ה לְהִנָּקֵ֖ם מֵאֹיְבֵיהֶֽם׃","pȧţĕşě֣gen hakĕ̇ţá֗b lĕhiná֤̇ţéֽn dá̇ţ֙ bĕ̇kál-mĕdiyná֣h ẇmĕdiyná֔h gá̇l֖ẇy lĕkál-háʻami֑̇ym wĕlihĕy֨wòţ hyhwdyym ʻţwdym laẏ֣wòm hazė֔h lĕhiná̇qé֖m méʼòyĕbéyheֽm׃"],[8,14,"הָרָצִ֞ים רֹכְבֵ֤י הָרֶ֙כֶשׁ֙ הָֽאֲחַשְׁתְּרָנִ֔ים יָֽצְא֛וּ מְבֹהָלִ֥ים וּדְחוּפִ֖ים בִּדְבַ֣ר הַמֶּ֑לֶךְ וְהַדָּ֥ת נִתְּנָ֖ה בְּשׁוּשַׁ֥ן הַבִּירָֽה׃ פ","háráẕi֞ym ròkĕbé֤y háre֙keş̌֙ háֽʼàẖaşĕ̌ţĕ̇ráni֔ym yáֽẕĕʼ֛ẇ mĕbòháli֥ym ẇdĕẖẇpi֖ym bi̇dĕba֣r hamė֑lekĕ wĕhadá֥̇ţ niţĕ̇ná֖h bĕ̇ş̌ẇşǎ֥n habi̇yráֽh׃ p"],[8,15,"וּמָרְדֳּכַ֞י יָצָ֣א ׀ מִלִּפְנֵ֣י הַמֶּ֗לֶךְ בִּלְב֤וּשׁ מַלְכוּת֙ תְּכֵ֣לֶת וָח֔וּר וַעֲטֶ֤רֶת זָהָב֙ גְּדוֹלָ֔ה וְתַכְרִ֥יךְ בּ֖וּץ וְאַרְגָּמָ֑ן וְהָעִ֣יר שׁוּשָׁ֔ן צָהֲלָ֖ה וְשָׂמֵֽחָה׃","ẇmárĕdȯka֞y yáẕá֣ʼ ׀ mili̇pĕné֣y hamė֗lekĕ bi̇lĕb֤ẇş̌ malĕkẇţ֙ ţĕ̇ké֣leţ wáẖ֔ẇr waʻàte֤reţ záháb֙ gĕ̇dwòlá֔h wĕţakĕri֥ykĕ ḃ֖ẇẕ wĕʼarĕgá̇má֑n wĕháʻi֣yr ş̌ẇşá̌֔n ẕáhàlá֖h wĕşá̂méֽẖáh׃"],[8,16,"לַיְּהוּדִ֕ים הָֽיְתָ֥ה אוֹרָ֖ה וְשִׂמְחָ֑ה וְשָׂשֹׂ֖ן וִיקָֽר׃","layĕ̇hẇdi֕ym háֽyĕţá֥h ʼwòrá֖h wĕşîmĕẖá֑h wĕşá̂şò֖̂n wiyqáֽr׃"],[8,17,"וּבְכָל־מְדִינָ֨ה וּמְדִינָ֜ה וּבְכָל־עִ֣יר וָעִ֗יר מְקוֹם֙ אֲשֶׁ֨ר דְּבַר־הַמֶּ֤לֶךְ וְדָתוֹ֙ מַגִּ֔יעַ שִׂמְחָ֤ה וְשָׂשׂוֹן֙ לַיְּהוּדִ֔ים מִשְׁתֶּ֖ה וְי֣וֹם ט֑וֹב וְרַבִּ֞ים מֵֽעַמֵּ֤י הָאָ֙רֶץ֙ מִֽתְיַהֲדִ֔ים כִּֽי־נָפַ֥ל פַּֽחַד־הַיְּהוּדִ֖ים עֲלֵיהֶֽם׃","ẇbĕkál-mĕdiyná֨h ẇmĕdiyná֜h ẇbĕkál-ʻi֣yr wáʻi֗yr mĕqwòm֙ ʼàşě֨r dĕ̇bar-hamė֤lekĕ wĕdáţwò֙ magi̇֔yʻa şîmĕẖá֤h wĕşá̂ş̂wòn֙ layĕ̇hẇdi֔ym mişĕ̌ţė֖h wĕy֣wòm t֑wòb wĕrabi̇֞ym méֽʻamé֤̇y háʼá֙reẕ֙ miֽţĕyahàdi֔ym kiֽ̇y-nápa֥l pȧֽẖad-hayĕ̇hẇdi֖ym ʻàléyheֽm׃"],[9,1,"וּבִשְׁנֵים֩ עָשָׂ֨ר חֹ֜דֶשׁ הוּא־חֹ֣דֶשׁ אֲדָ֗ר בִּשְׁלוֹשָׁ֨ה עָשָׂ֥ר יוֹם֙ בּ֔וֹ אֲשֶׁ֨ר הִגִּ֧יעַ דְּבַר־הַמֶּ֛לֶךְ וְדָת֖וֹ לְהֵעָשׂ֑וֹת בַּיּ֗וֹם אֲשֶׁ֨ר שִׂבְּר֜וּ אֹיְבֵ֤י הַיְּהוּדִים֙ לִשְׁל֣וֹט בָּהֶ֔ם וְנַהֲפ֣וֹךְ ה֔וּא אֲשֶׁ֨ר יִשְׁלְט֧וּ הַיְּהוּדִ֛ים הֵ֖מָּה בְּשֹׂנְאֵיהֶֽם׃","ẇbişĕ̌néym֩ ʻáşá̂֨r ẖò֜deş̌ hẇʼ-ẖò֣deş̌ ʼàdá֗r bi̇şĕ̌lwòşá̌֨h ʻáşá֥̂r ywòm֙ ḃ֔wò ʼàşě֨r higi֧̇yʻa dĕ̇bar-hamė֛lekĕ wĕdáţ֖wò lĕhéʻáş֑̂wòţ bȧẏ֗wòm ʼàşě֨r şîbĕ̇r֜ẇ ʼòyĕbé֤y hayĕ̇hẇdiym֙ lişĕ̌l֣wòt bá̇he֔m wĕnahàp֣wòkĕ h֔ẇʼ ʼàşě֨r yişĕ̌lĕt֧ẇ hayĕ̇hẇdi֛ym hé֖má̇h bĕ̇şò̂nĕʼéyheֽm׃"],[9,2,"נִקְהֲל֨וּ הַיְּהוּדִ֜ים בְּעָרֵיהֶ֗ם בְּכָל־מְדִינוֹת֙ הַמֶּ֣לֶךְ אֳחַשְׁוֵר֔וֹשׁ לִשְׁלֹ֣חַ יָ֔ד בִּמְבַקְשֵׁ֖י רָֽעָתָ֑ם וְאִישׁ֙ לֹא־עָמַ֣ד לִפְנֵיהֶ֔ם כִּֽי־נָפַ֥ל פַּחְדָּ֖ם עַל־כָּל־הָעַמִּֽים׃","niqĕhàl֨ẇ hayĕ̇hẇdi֜ym bĕ̇ʻáréyhe֗m bĕ̇kál-mĕdiynwòţ֙ hamė֣lekĕ ʼoẖaşĕ̌wér֔wòş̌ lişĕ̌lò֣ẖa yá֔d bi̇mĕbaqĕşé֖̌y ráֽʻáţá֑m wĕʼiyş̌֙ lòʼ-ʻáma֣d lipĕnéyhe֔m kiֽ̇y-nápa֥l pȧẖĕdá֖̇m ʻal-ká̇l-háʻamiֽ̇ym׃"],[9,3,"וְכָל־שָׂרֵ֨י הַמְּדִינ֜וֹת וְהָאֲחַשְׁדַּרְפְּנִ֣ים וְהַפַּח֗וֹת וְעֹשֵׂ֤י הַמְּלָאכָה֙ אֲשֶׁ֣ר לַמֶּ֔לֶךְ מְנַשְּׂאִ֖ים אֶת־הַיְּהוּדִ֑ים כִּֽי־נָפַ֥ל פַּֽחַד־מָרְדֳּכַ֖י עֲלֵיהֶֽם׃","wĕkál-şá̂ré֨y hamĕ̇diyn֜wòţ wĕháʼàẖaşĕ̌dȧrĕpĕ̇ni֣ym wĕhapȧẖ֗wòţ wĕʻòşé֤̂y hamĕ̇láʼkáh֙ ʼàşě֣r lamė֔lekĕ mĕnaşĕ̇̂ʼi֖ym ʼeţ-hayĕ̇hẇdi֑ym kiֽ̇y-nápa֥l pȧֽẖad-márĕdȯka֖y ʻàléyheֽm׃"],[9,4,"כִּֽי־גָ֤דוֹל מָרְדֳּכַי֙ בְּבֵ֣ית הַמֶּ֔לֶךְ וְשָׁמְע֖וֹ הוֹלֵ֣ךְ בְּכָל־הַמְּדִינ֑וֹת כִּֽי־הָאִ֥ישׁ מָרְדֳּכַ֖י הוֹלֵ֥ךְ וְגָדֽוֹל׃ פ","kiֽ̇y-gá֤dwòl márĕdȯkay֙ bĕ̇bé֣yţ hamė֔lekĕ wĕşá̌mĕʻ֖wò hwòlé֣kĕ bĕ̇kál-hamĕ̇diyn֑wòţ kiֽ̇y-háʼi֥yş̌ márĕdȯka֖y hwòlé֥kĕ wĕgádֽwòl׃ p"],[9,5,"וַיַּכּ֤וּ הַיְּהוּדִים֙ בְּכָל־אֹ֣יְבֵיהֶ֔ם מַכַּת־חֶ֥רֶב וְהֶ֖רֶג וְאַבְדָ֑ן וַיַּֽעֲשׂ֥וּ בְשֹׂנְאֵיהֶ֖ם כִּרְצוֹנָֽם׃","wayȧk֤̇ẇ hayĕ̇hẇdiym֙ bĕ̇kál-ʼò֣yĕbéyhe֔m makȧţ-ẖe֥reb wĕhe֖reg wĕʼabĕdá֑n wayȧֽʻàş֥̂ẇ bĕşò̂nĕʼéyhe֖m ki̇rĕẕwònáֽm׃"],[9,6,"וּבְשׁוּשַׁ֣ן הַבִּירָ֗ה הָרְג֤וּ הַיְּהוּדִים֙ וְאַבֵּ֔ד חֲמֵ֥שׁ מֵא֖וֹת אִֽישׁ׃","ẇbĕş̌ẇşǎ֣n habi̇yrá֗h hárĕg֤ẇ hayĕ̇hẇdiym֙ wĕʼabé̇֔d ẖàmé֥ş̌ méʼ֖wòţ ʼiֽyş̌׃"],[9,7,"וְאֵ֧ת ׀ פַּרְשַׁנְדָּ֛תָא וְאֵ֥ת ׀ דַּֽלְפ֖וֹן וְאֵ֥ת ׀ אַסְפָּֽתָא׃","wĕʼé֧ţ ׀ pȧrĕşǎnĕdá֛̇ţáʼ wĕʼé֥ţ ׀ dȧֽlĕp֖wòn wĕʼé֥ţ ׀ ʼasĕpáֽ̇ţáʼ׃"],[9,8,"וְאֵ֧ת ׀ פּוֹרָ֛תָא וְאֵ֥ת ׀ אֲדַלְיָ֖א וְאֵ֥ת ׀ אֲרִידָֽתָא׃","wĕʼé֧ţ ׀ ṗwòrá֛ţáʼ wĕʼé֥ţ ׀ ʼàdalĕyá֖ʼ wĕʼé֥ţ ׀ ʼàriydáֽţáʼ׃"],[9,9,"וְאֵ֤ת ׀ פַּרְמַ֙שְׁתָּא֙ וְאֵ֣ת ׀ אֲרִיסַ֔י וְאֵ֥ת ׀ אֲרִדַ֖י וְאֵ֥ת ׀ וַיְזָֽתָא׃","wĕʼé֤ţ ׀ pȧrĕma֙şĕ̌ţá̇ʼ֙ wĕʼé֣ţ ׀ ʼàriysa֔y wĕʼé֥ţ ׀ ʼàrida֖y wĕʼé֥ţ ׀ wayĕzáֽţáʼ׃"],[9,10,"עֲ֠שֶׂרֶת בְּנֵ֨י הָמָ֧ן בֶּֽן־הַמְּדָ֛תָא צֹרֵ֥ר הַיְּהוּדִ֖ים הָרָ֑גוּ וּבַ֨בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽם׃","ʻà֠şêreţ bĕ̇né֨y hámá֧n bėֽn-hamĕ̇dá֛ţáʼ ẕòré֥r hayĕ̇hẇdi֖ym hárá֑gẇ ẇba֨bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽm׃"],[9,11,"בַּיּ֣וֹם הַה֗וּא בָּ֣א מִסְפַּ֧ר הַֽהֲרוּגִ֛ים בְּשׁוּשַׁ֥ן הַבִּירָ֖ה לִפְנֵ֥י הַמֶּֽלֶךְ׃ ס","bȧẏ֣wòm hah֗ẇʼ bá֣̇ʼ misĕpȧ֧r hֽahàrẇgi֛ym bĕ̇ş̌ẇşǎ֥n habi̇yrá֖h lipĕné֥y hamėֽlekĕ׃ s"],[9,12,"וַיֹּ֨אמֶר הַמֶּ֜לֶךְ לְאֶסְתֵּ֣ר הַמַּלְכָּ֗ה בְּשׁוּשַׁ֣ן הַבִּירָ֡ה הָרְגוּ֩ הַיְּהוּדִ֨ים וְאַבֵּ֜ד חֲמֵ֧שׁ מֵא֣וֹת אִ֗ישׁ וְאֵת֙ עֲשֶׂ֣רֶת בְּנֵֽי־הָמָ֔ן בִּשְׁאָ֛ר מְדִינ֥וֹת הַמֶּ֖לֶךְ מֶ֣ה עָשׂ֑וּ וּמַה־שְּׁאֵֽלָתֵךְ֙ וְיִנָּ֣תֵֽן לָ֔ךְ וּמַה־בַּקָּשָׁתֵ֥ךְ ע֖וֹד וְתֵעָֽשׂ׃","wayò̇֨ʼmer hamė֜lekĕ lĕʼesĕţé֣̇r hamȧlĕká̇֗h bĕ̇ş̌ẇşǎ֣n habi̇yrá֡h hárĕgẇ֩ hayĕ̇hẇdi֨ym wĕʼabé̇֜d ẖàmé֧ş̌ méʼ֣wòţ ʼi֗yş̌ wĕʼéţ֙ ʻàşê֣reţ bĕ̇néֽy-hámá֔n bi̇şĕ̌ʼá֛r mĕdiyn֥wòţ hamė֖lekĕ me֣h ʻáş֑̂ẇ ẇmah-şĕ̇̌ʼéֽláţékĕ֙ wĕyiná֣̇ţéֽn lá֔kĕ ẇmah-bȧqá̇şá̌ţé֥kĕ ʻ֖wòd wĕţéʻáֽş̂׃"],[9,13,"וַתֹּ֤אמֶר אֶסְתֵּר֙ אִם־עַל־הַמֶּ֣לֶךְ ט֔וֹב יִנָּתֵ֣ן גַּם־מָחָ֗ר לַיְּהוּדִים֙ אֲשֶׁ֣ר בְּשׁוּשָׁ֔ן לַעֲשׂ֖וֹת כְּדָ֣ת הַיּ֑וֹם וְאֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן יִתְל֥וּ עַל־הָעֵֽץ׃","waţò֤̇ʼmer ʼesĕţé̇r֙ ʼim-ʻal-hamė֣lekĕ t֔wòb yiná̇ţé֣n gȧm-máẖá֗r layĕ̇hẇdiym֙ ʼàşě֣r bĕ̇ş̌ẇşá̌֔n laʻàş֖̂wòţ kĕ̇dá֣ţ haẏ֑wòm wĕʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n yiţĕl֥ẇ ʻal-háʻéֽẕ׃"],[9,14,"וַיֹּ֤אמֶר הַמֶּ֙לֶךְ֙ לְהֵֽעָשׂ֣וֹת כֵּ֔ן וַתִּנָּתֵ֥ן דָּ֖ת בְּשׁוּשָׁ֑ן וְאֵ֛ת עֲשֶׂ֥רֶת בְּנֵֽי־הָמָ֖ן תָּלֽוּ׃","wayò֤̇ʼmer hamė֙lekĕ֙ lĕhéֽʻáş֣̂wòţ ké̇֔n waţi̇ná̇ţé֥n dá֖̇ţ bĕ̇ş̌ẇşá֑̌n wĕʼé֛ţ ʻàşê֥reţ bĕ̇néֽy-hámá֖n ţá̇lֽẇ׃"],[9,15,"וַיִּֽקָּהֲל֞וּ היהודיים אֲשֶׁר־בְּשׁוּשָׁ֗ן גַּ֠ם בְּי֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְחֹ֣דֶשׁ אֲדָ֔ר וַיַּֽהַרְג֣וּ בְשׁוּשָׁ֔ן שְׁלֹ֥שׁ מֵא֖וֹת אִ֑ישׁ וּבַ֨בִּזָּ֔ה לֹ֥א שָׁלְח֖וּ אֶת־יָדָֽם׃","wayiֽ̇qá̇hàl֞ẇ hyhwdyym ʼàşěr-bĕ̇ş̌ẇşá̌֗n gȧ֠m bĕ̇y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕẖò֣deş̌ ʼàdá֔r waẏֽaharĕg֣ẇ bĕş̌ẇşá̌֔n şĕ̌lò֥ş̌ méʼ֖wòţ ʼi֑yş̌ ẇba֨bi̇zá̇֔h lò֥ʼ şá̌lĕẖ֖ẇ ʼeţ-yádáֽm׃"],[9,16,"וּשְׁאָ֣ר הַיְּהוּדִ֡ים אֲשֶׁר֩ בִּמְדִינ֨וֹת הַמֶּ֜לֶךְ נִקְהֲל֣וּ ׀ וְעָמֹ֣ד עַל־נַפְשָׁ֗ם וְנ֙וֹחַ֙ מֵאֹ֣יְבֵיהֶ֔ם וְהָרֹג֙ בְּשֹׂ֣נְאֵיהֶ֔ם חֲמִשָּׁ֥ה וְשִׁבְעִ֖ים אָ֑לֶף וּבַ֨בִּזָּ֔ה לֹ֥א שָֽׁלְח֖וּ אֶת־יָדָֽם׃","ẇşĕ̌ʼá֣r hayĕ̇hẇdi֡ym ʼàşěr֩ bi̇mĕdiyn֨wòţ hamė֜lekĕ niqĕhàl֣ẇ ׀ wĕʻámò֣d ʻal-napĕşá̌֗m wĕn֙wòẖa֙ méʼò֣yĕbéyhe֔m wĕháròg֙ bĕ̇şò֣̂nĕʼéyhe֔m ẖàmişá֥̇̌h wĕşǐbĕʻi֖ym ʼá֑lep ẇba֨bi̇zá̇֔h lò֥ʼ şáֽ̌lĕẖ֖ẇ ʼeţ-yádáֽm׃"],[9,17,"בְּיוֹם־שְׁלֹשָׁ֥ה עָשָׂ֖ר לְחֹ֣דֶשׁ אֲדָ֑ר וְנ֗וֹחַ בְּאַרְבָּעָ֤ה עָשָׂר֙ בּ֔וֹ וְעָשֹׂ֣ה אֹת֔וֹ י֖וֹם מִשְׁתֶּ֥ה וְשִׂמְחָֽה׃","bĕ̇ywòm-şĕ̌lòşá֥̌h ʻáşá֖̂r lĕẖò֣deş̌ ʼàdá֑r wĕn֗wòẖa bĕ̇ʼarĕbá̇ʻá֤h ʻáşá̂r֙ ḃ֔wò wĕʻáşò֣̂h ʼòţ֔wò y֖wòm mişĕ̌ţė֥h wĕşîmĕẖáֽh׃"],[9,18,"והיהודיים אֲשֶׁר־בְּשׁוּשָׁ֗ן נִקְהֲלוּ֙ בִּשְׁלֹשָׁ֤ה עָשָׂר֙ בּ֔וֹ וּבְאַרְבָּעָ֥ה עָשָׂ֖ר בּ֑וֹ וְנ֗וֹחַ בַּחֲמִשָּׁ֤ה עָשָׂר֙ בּ֔וֹ וְעָשֹׂ֣ה אֹת֔וֹ י֖וֹם מִשְׁתֶּ֥ה וְשִׂמְחָֽה׃","whyhwdyym ʼàşěr-bĕ̇ş̌ẇşá̌֗n niqĕhàlẇ֙ bi̇şĕ̌lòşá֤̌h ʻáşá̂r֙ ḃ֔wò ẇbĕʼarĕbá̇ʻá֥h ʻáşá֖̂r ḃ֑wò wĕn֗wòẖa bȧẖàmişá֤̇̌h ʻáşá̂r֙ ḃ֔wò wĕʻáşò֣̂h ʼòţ֔wò y֖wòm mişĕ̌ţė֥h wĕşîmĕẖáֽh׃"],[9,19,"עַל־כֵּ֞ן הַיְּהוּדִ֣ים הפרוזים הַיֹּשְׁבִים֮ בְּעָרֵ֣י הַפְּרָזוֹת֒ עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְחֹ֣דֶשׁ אֲדָ֔ר שִׂמְחָ֥ה וּמִשְׁתֶּ֖ה וְי֣וֹם ט֑וֹב וּמִשְׁל֥וֹחַ מָנ֖וֹת אִ֥ישׁ לְרֵעֵֽהוּ׃ פ","ʻal-ké̇֞n hayĕ̇hẇdi֣ym hprwzym hayò̇şĕ̌biym֮ bĕ̇ʻáré֣y hapĕ̇rázwòţ֒ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕẖò֣deş̌ ʼàdá֔r şîmĕẖá֥h ẇmişĕ̌ţė֖h wĕy֣wòm t֑wòb ẇmişĕ̌l֥wòẖa mán֖wòţ ʼi֥yş̌ lĕréʻéֽhẇ׃ p"],[9,20,"וַיִּכְתֹּ֣ב מָרְדֳּכַ֔י אֶת־הַדְּבָרִ֖ים הָאֵ֑לֶּה וַיִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַיְּהוּדִ֗ים אֲשֶׁר֙ בְּכָל־מְדִינוֹת֙ הַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ הַקְּרוֹבִ֖ים וְהָרְחוֹקִֽים׃","wayi̇kĕţò֣̇b márĕdȯka֔y ʼeţ-hadĕ̇bári֖ym háʼé֑lėh wayi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-hayĕ̇hẇdi֗ym ʼàşěr֙ bĕ̇kál-mĕdiynwòţ֙ hamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ haqĕ̇rwòbi֖ym wĕhárĕẖwòqiֽym׃"],[9,21,"לְקַיֵּם֮ עֲלֵיהֶם֒ לִהְי֣וֹת עֹשִׂ֗ים אֵ֠ת י֣וֹם אַרְבָּעָ֤ה עָשָׂר֙ לְחֹ֣דֶשׁ אֲדָ֔ר וְאֵ֛ת יוֹם־חֲמִשָּׁ֥ה עָשָׂ֖ר בּ֑וֹ בְּכָל־שָׁנָ֖ה וְשָׁנָֽה׃","lĕqayé̇m֮ ʻàléyhem֒ lihĕy֣wòţ ʻòşî֗ym ʼé֠ţ y֣wòm ʼarĕbá̇ʻá֤h ʻáşá̂r֙ lĕẖò֣deş̌ ʼàdá֔r wĕʼé֛ţ ywòm-ẖàmişá֥̇̌h ʻáşá֖̂r ḃ֑wò bĕ̇kál-şá̌ná֖h wĕşá̌náֽh׃"],[9,22,"כַּיָּמִ֗ים אֲשֶׁר־נָ֨חוּ בָהֶ֤ם הַיְּהוּדִים֙ מֵא֣וֹיְבֵיהֶ֔ם וְהַחֹ֗דֶשׁ אֲשֶׁר֩ נֶהְפַּ֨ךְ לָהֶ֤ם מִיָּגוֹן֙ לְשִׂמְחָ֔ה וּמֵאֵ֖בֶל לְי֣וֹם ט֑וֹב לַעֲשׂ֣וֹת אוֹתָ֗ם יְמֵי֙ מִשְׁתֶּ֣ה וְשִׂמְחָ֔ה וּמִשְׁל֤וֹחַ מָנוֹת֙ אִ֣ישׁ לְרֵעֵ֔הוּ וּמַתָּנ֖וֹת לָֽאֶבְיוֹנִֽים׃","kȧyá̇mi֗ym ʼàşěr-ná֨ẖẇ báhe֤m hayĕ̇hẇdiym֙ méʼ֣wòyĕbéyhe֔m wĕhaẖò֗deş̌ ʼàşěr֩ nehĕpȧ֨kĕ láhe֤m miyá̇gwòn֙ lĕşîmĕẖá֔h ẇméʼé֖bel lĕy֣wòm t֑wòb laʻàş֣̂wòţ ʼwòţá֗m yĕméy֙ mişĕ̌ţė֣h wĕşîmĕẖá֔h ẇmişĕ̌l֤wòẖa mánwòţ֙ ʼi֣yş̌ lĕréʻé֔hẇ ẇmaţá̇n֖wòţ láֽʼebĕywòniֽym׃"],[9,23,"וְקִבֵּל֙ הַיְּהוּדִ֔ים אֵ֥ת אֲשֶׁר־הֵחֵ֖לּוּ לַעֲשׂ֑וֹת וְאֵ֛ת אֲשֶׁר־כָּתַ֥ב מָרְדֳּכַ֖י אֲלֵיהֶֽם׃","wĕqibé̇l֙ hayĕ̇hẇdi֔ym ʼé֥ţ ʼàşěr-héẖé֖l̇ẇ laʻàş֑̂wòţ wĕʼé֛ţ ʼàşěr-ká̇ţa֥b márĕdȯka֖y ʼàléyheֽm׃"],[9,24,"כִּי֩ הָמָ֨ן בֶּֽן־הַמְּדָ֜תָא הָֽאֲגָגִ֗י צֹרֵר֙ כָּל־הַיְּהוּדִ֔ים חָשַׁ֥ב עַל־הַיְּהוּדִ֖ים לְאַבְּדָ֑ם וְהִפִּ֥יל פּוּר֙ ה֣וּא הַגּוֹרָ֔ל לְהֻמָּ֖ם וּֽלְאַבְּדָֽם׃","ki̇y֩ hámá֨n bėֽn-hamĕ̇dá֜ţáʼ háֽʼàgági֗y ẕòrér֙ ká̇l-hayĕ̇hẇdi֔ym ẖáşǎ֥b ʻal-hayĕ̇hẇdi֖ym lĕʼabĕ̇dá֑m wĕhipi֥̇yl ṗẇr֙ h֣ẇʼ haġwòrá֔l lĕhumá֖̇m ẇֽlĕʼabĕ̇dáֽm׃"],[9,25,"וּבְבֹאָהּ֮ לִפְנֵ֣י הַמֶּלֶךְ֒ אָמַ֣ר עִם־הַסֵּ֔פֶר יָשׁ֞וּב מַחֲשַׁבְתּ֧וֹ הָרָעָ֛ה אֲשֶׁר־חָשַׁ֥ב עַל־הַיְּהוּדִ֖ים עַל־רֹאשׁ֑וֹ וְתָל֥וּ אֹת֛וֹ וְאֶת־בָּנָ֖יו עַל־הָעֵֽץ׃","ẇbĕbòʼáḣ֮ lipĕné֣y hamėlekĕ֒ ʼáma֣r ʻim-hasé̇֔per yáş̌֞ẇb maẖàşǎbĕţ֧̇wò háráʻá֛h ʼàşěr-ẖáşǎ֥b ʻal-hayĕ̇hẇdi֖ym ʻal-ròʼş֑̌wò wĕţál֥ẇ ʼòţ֛wò wĕʼeţ-bá̇ná֖yw ʻal-háʻéֽẕ׃"],[9,26,"עַל־כֵּ֡ן קָֽרְאוּ֩ לַיָּמִ֨ים הָאֵ֤לֶּה פוּרִים֙ עַל־שֵׁ֣ם הַפּ֔וּר עַל־כֵּ֕ן עַל־כָּל־דִּבְרֵ֖י הָאִגֶּ֣רֶת הַזֹּ֑את וּמָֽה־רָא֣וּ עַל־כָּ֔כָה וּמָ֥ה הִגִּ֖יעַ אֲלֵיהֶֽם׃","ʻal-ké̇֡n qáֽrĕʼẇ֩ layá̇mi֨ym háʼé֤lėh pẇriym֙ ʻal-şé֣̌m haṗ֔ẇr ʻal-ké̇֕n ʻal-ká̇l-di̇bĕré֖y háʼigė֣reţ hazò֑̇ʼţ ẇmáֽh-ráʼ֣ẇ ʻal-ká̇֔káh ẇmá֥h higi֖̇yʻa ʼàléyheֽm׃"],[9,27,"קִיְּמ֣וּ וקבל הַיְּהוּדִים֩ ׀ עֲלֵיהֶ֨ם ׀ וְעַל־זַרְעָ֜ם וְעַ֨ל כָּל־הַנִּלְוִ֤ים עֲלֵיהֶם֙ וְלֹ֣א יַעֲב֔וֹר לִהְי֣וֹת עֹשִׂ֗ים אֵ֣ת שְׁנֵ֤י הַיָּמִים֙ הָאֵ֔לֶּה כִּכְתָבָ֖ם וְכִזְמַנָּ֑ם בְּכָל־שָׁנָ֖ה וְשָׁנָֽה׃","qiyĕ̇m֣ẇ wqbl hayĕ̇hẇdiym֩ ׀ ʻàléyhe֨m ׀ wĕʻal-zarĕʻá֜m wĕʻa֨l ká̇l-hani̇lĕwi֤ym ʻàléyhem֙ wĕlò֣ʼ yaʻàb֔wòr lihĕy֣wòţ ʻòşî֗ym ʼé֣ţ şĕ̌né֤y hayá̇miym֙ háʼé֔lėh ki̇kĕţábá֖m wĕkizĕmaná֑̇m bĕ̇kál-şá̌ná֖h wĕşá̌náֽh׃"],[9,28,"וְהַיָּמִ֣ים הָ֠אֵלֶּה נִזְכָּרִ֨ים וְנַעֲשִׂ֜ים בְּכָל־דּ֣וֹר וָד֗וֹר מִשְׁפָּחָה֙ וּמִשְׁפָּחָ֔ה מְדִינָ֥ה וּמְדִינָ֖ה וְעִ֣יר וָעִ֑יר וִימֵ֞י הַפּוּרִ֣ים הָאֵ֗לֶּה לֹ֤א יַֽעַבְרוּ֙ מִתּ֣וֹךְ הַיְּהוּדִ֔ים וְזִכְרָ֖ם לֹא־יָס֥וּף מִזַּרְעָֽם׃ ס","wĕhayá̇mi֣ym há֠ʼélėh nizĕká̇ri֨ym wĕnaʻàşî֜ym bĕ̇kál-ḋ֣wòr wád֗wòr mişĕ̌pá̇ẖáh֙ ẇmişĕ̌pá̇ẖá֔h mĕdiyná֥h ẇmĕdiyná֖h wĕʻi֣yr wáʻi֑yr wiymé֞y haṗẇri֣ym háʼé֗lėh lò֤ʼ yaֽʻabĕrẇ֙ miţ֣̇wòkĕ hayĕ̇hẇdi֔ym wĕzikĕrá֖m lòʼ-yás֥ẇp mizȧrĕʻáֽm׃ s"],[9,29,"וַ֠תִּכְתֹּב אֶסְתֵּ֨ר הַמַּלְכָּ֧ה בַת־אֲבִיחַ֛יִל וּמָרְדֳּכַ֥י הַיְּהוּדִ֖י אֶת־כָּל־תֹּ֑קֶף לְקַיֵּ֗ם אֵ֣ת אִגֶּ֧רֶת הַפּוּרִ֛ים הַזֹּ֖את הַשֵּׁנִֽית׃","wa֠ţi̇kĕţò̇b ʼesĕţé̇֨r hamȧlĕká֧̇h baţ-ʼàbiyẖa֛yil ẇmárĕdȯka֥y hayĕ̇hẇdi֖y ʼeţ-ká̇l-ţò֑̇qep lĕqayé̇֗m ʼé֣ţ ʼigė֧reţ haṗẇri֛ym hazò֖̇ʼţ haşé̇̌niֽyţ׃"],[9,30,"וַיִּשְׁלַ֨ח סְפָרִ֜ים אֶל־כָּל־הַיְּהוּדִ֗ים אֶל־שֶׁ֨בַע וְעֶשְׂרִ֤ים וּמֵאָה֙ מְדִינָ֔ה מַלְכ֖וּת אֲחַשְׁוֵר֑וֹשׁ דִּבְרֵ֥י שָׁל֖וֹם וֶאֱמֶֽת׃","wayi̇şĕ̌la֨ẖ sĕpári֜ym ʼel-ká̇l-hayĕ̇hẇdi֗ym ʼel-şě֨baʻ wĕʻeşĕ̂ri֤ym ẇméʼáh֙ mĕdiyná֔h malĕk֖ẇţ ʼàẖaşĕ̌wér֑wòş̌ di̇bĕré֥y şá̌l֖wòm weʼèmeֽţ׃"],[9,31,"לְקַיֵּ֡ם אֵת־יְמֵי֩ הַפֻּרִ֨ים הָאֵ֜לֶּה בִּזְמַנֵּיהֶ֗ם כַּאֲשֶׁר֩ קִיַּ֨ם עֲלֵיהֶ֜ם מָרְדֳּכַ֤י הַיְּהוּדִי֙ וְאֶסְתֵּ֣ר הַמַּלְכָּ֔ה וְכַאֲשֶׁ֛ר קִיְּמ֥וּ עַל־נַפְשָׁ֖ם וְעַל־זַרְעָ֑ם דִּבְרֵ֥י הַצֹּמ֖וֹת וְזַעֲקָתָֽם׃","lĕqayé̇֡m ʼéţ-yĕméy֩ hapu̇ri֨ym háʼé֜lėh bi̇zĕmané̇yhe֗m kȧʼàşěr֩ qiyȧ֨m ʻàléyhe֜m márĕdȯka֤y hayĕ̇hẇdiy֙ wĕʼesĕţé֣̇r hamȧlĕká̇֔h wĕkaʼàşě֛r qiyĕ̇m֥ẇ ʻal-napĕşá֖̌m wĕʻal-zarĕʻá֑m di̇bĕré֥y haẕò̇m֖wòţ wĕzaʻàqáţáֽm׃"],[9,32,"וּמַאֲמַ֣ר אֶסְתֵּ֔ר קִיַּ֕ם דִּבְרֵ֥י הַפֻּרִ֖ים הָאֵ֑לֶּה וְנִכְתָּ֖ב בַּסֵּֽפֶר׃ פ","ẇmaʼàma֣r ʼesĕţé̇֔r qiyȧ֕m di̇bĕré֥y hapu̇ri֖ym háʼé֑lėh wĕnikĕţá֖̇b bȧséֽ̇per׃ p"],[10,1,"וַיָּשֶׂם֩ הַמֶּ֨לֶךְ אחשרש ׀ מַ֛ס עַל־הָאָ֖רֶץ וְאִיֵּ֥י הַיָּֽם׃","wayá̇şêm֩ hamė֨lekĕ ʼẖşrş ׀ ma֛s ʻal-háʼá֖reẕ wĕʼiyé֥̇y hayáֽ̇m׃"],[10,2,"וְכָל־מַעֲשֵׂ֤ה תָקְפּוֹ֙ וּגְב֣וּרָת֔וֹ וּפָרָשַׁת֙ גְּדֻלַּ֣ת מָרְדֳּכַ֔י אֲשֶׁ֥ר גִּדְּל֖וֹ הַמֶּ֑לֶךְ הֲלוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֙פֶר֙ דִּבְרֵ֣י הַיָּמִ֔ים לְמַלְכֵ֖י מָדַ֥י וּפָרָֽס׃","wĕkál-maʻàşé֤̂h ţáqĕṗwò֙ ẇgĕb֣ẇráţ֔wò ẇpáráşǎţ֙ gĕ̇dulȧ֣ţ márĕdȯka֔y ʼàşě֥r gi̇dĕ̇l֖wò hamė֑lekĕ hàlwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֙per֙ di̇bĕré֣y hayá̇mi֔ym lĕmalĕké֖y máda֥y ẇpáráֽs׃"],[10,3,"כִּ֣י ׀ מָרְדֳּכַ֣י הַיְּהוּדִ֗י מִשְׁנֶה֙ לַמֶּ֣לֶךְ אֲחַשְׁוֵר֔וֹשׁ וְגָדוֹל֙ לַיְּהוּדִ֔ים וְרָצ֖וּי לְרֹ֣ב אֶחָ֑יו דֹּרֵ֥שׁ טוֹב֙ לְעַמּ֔וֹ וְדֹבֵ֥ר שָׁל֖וֹם לְכָל־זַרְעֽוֹ׃","ki֣̇y ׀ márĕdȯka֣y hayĕ̇hẇdi֗y mişĕ̌neh֙ lamė֣lekĕ ʼàẖaşĕ̌wér֔wòş̌ wĕgádwòl֙ layĕ̇hẇdi֔ym wĕráẕ֖ẇy lĕrò֣b ʼeẖá֑yw dò̇ré֥ş̌ twòb֙ lĕʻaṁ֔wò wĕdòbé֥r şá̌l֖wòm lĕkál-zarĕʻֽwò׃"]],"fra-giguet-lxx":[[1,1,"Or, après ces choses, il advint durant les jours d’Artaxerxès, qui régnait depuis l’Inde sur cent vingt-sept contrées,","Or, après ces choses, il advint durant les jours d’Artaxerxès, qui régnait depuis l’Inde sur cent vingt-sept contrées,"],[1,2,"En ces jours-là, tandis qu’il trônait en la ville de Suse,","En ces jours-là, tandis qu’il trônait en la ville de Suse,"],[1,3,"La troisième année de son règne, il advint qu’il fit un festin à ses amis et au reste des nations, et aux hommes considérables des Perses et des Mèdes, et aux premiers des satrapes.","La troisième année de son règne, il advint qu’il fit un festin à ses amis et au reste des nations, et aux hommes considérables des Perses et des Mèdes, et aux premiers des satrapes."],[1,4,"Et ensuite, après leur avoir montré les richesses de son royaume, et la splendeur de ses joies et de ses trésors, pendant cent quatre-vingts jours,","Et ensuite, après leur avoir montré les richesses de son royaume, et la splendeur de ses joies et de ses trésors, pendant cent quatre-vingts jours,"],[1,5,"Lorsque les jours de ses noces furent remplis, il fit pendant six jours aux nations qui se trouvaient à Suse un festin dans le parvis du palais,","Lorsque les jours de ses noces furent remplis, il fit pendant six jours aux nations qui se trouvaient à Suse un festin dans le parvis du palais,"],[1,6,"Orné de voiles du lin le plus fin, et de gaze tendue par des cordons de lin et de pourpre sur des socles d’or et d’argent, et sur des colonnes de marbre blanc et de pierre. Les lits, d’argent et d’or, étaient posés sur des mosaïques d’émeraudes, de nacre et de marbre blanc; et les couvertures transparentes, diversement brodées, étaient encadrées de feuilles de roses.","Orné de voiles du lin le plus fin, et de gaze tendue par des cordons de lin et de pourpre sur des socles d’or et d’argent, et sur des colonnes de marbre blanc et de pierre. Les lits, d’argent et d’or, étaient posés sur des mosaïques d’émeraudes, de nacre et de marbre blanc; et les couvertures transparentes, diversement brodées, étaient encadrées de feuilles de roses."],[1,7,"Les coupes étaient d’argent et d’or, et il y avait une petite coupe en diamant évaluée trente mille talents; on les remplissait de vin abondant et doux, le même que le roi buvait.","Les coupes étaient d’argent et d’or, et il y avait une petite coupe en diamant évaluée trente mille talents; on les remplissait de vin abondant et doux, le même que le roi buvait."],[1,8,"Et le repas ne se fit pas selon la loi établie; le roi l’avait ainsi voulu, et il avait ordonné à ses économes de se conformer à ses propres désirs et à ceux de ses convives.","Et le repas ne se fit pas selon la loi établie; le roi l’avait ainsi voulu, et il avait ordonné à ses économes de se conformer à ses propres désirs et à ceux de ses convives."],[1,9,"Et Vasthi, la reine, fit un festin pour les femmes dans l’intérieur du palais où résidait le roi Artaxerxès.","Et Vasthi, la reine, fit un festin pour les femmes dans l’intérieur du palais où résidait le roi Artaxerxès."],[1,10,"Le septième jour, le roi, étant en belle humeur, dit à Aman, à Bazan, à Tharra, à Barazi, à Zatholtha, à Abataza et à Tharaba, les sept eunuques attachés à sa personne,","Le septième jour, le roi, étant en belle humeur, dit à Aman, à Bazan, à Tharra, à Barazi, à Zatholtha, à Abataza et à Tharaba, les sept eunuques attachés à sa personne,"],[1,11,"De lui amener la reine pour qu’il la couronnât, qu’il posât sur sa tête le diadème, et qu’il la montrât dans sa beauté aux chefs et aux nations; car elle était belle.","De lui amener la reine pour qu’il la couronnât, qu’il posât sur sa tête le diadème, et qu’il la montrât dans sa beauté aux chefs et aux nations; car elle était belle."],[1,12,"Mais la reine Vasthi refusa de suivre les eunuques, et le roi en fut affligé, et il se mit en colère.","Mais la reine Vasthi refusa de suivre les eunuques, et le roi en fut affligé, et il se mit en colère."],[1,13,"Et il dit à ses amis: Voici ce qu’a dit la reine, faites donc à ce sujet loi et jugement.","Et il dit à ses amis: Voici ce qu’a dit la reine, faites donc à ce sujet loi et jugement."],[1,14,"Et Arcesée, Sarsathée et Maliséar, princes des Perses et des Mèdes, ceux qui se tenaient près du roi, et qui s’asseyaient les premiers après lui, s’approchèrent.","Et Arcesée, Sarsathée et Maliséar, princes des Perses et des Mèdes, ceux qui se tenaient près du roi, et qui s’asseyaient les premiers après lui, s’approchèrent."],[1,15,"Et ils lui firent connaître ce que selon la loi il était à propos de faire à la reine Vasthi, parce qu’elle n’avait point fait ce que lui avait commandé le roi par ses eunuques.","Et ils lui firent connaître ce que selon la loi il était à propos de faire à la reine Vasthi, parce qu’elle n’avait point fait ce que lui avait commandé le roi par ses eunuques."],[1,16,"Et Muchée dit au roi et aux princes: Vasthi, la reine, n’a pas nui au roi seul, mais aussi à tous les princes et aux grands officiers du roi.","Et Muchée dit au roi et aux princes: Vasthi, la reine, n’a pas nui au roi seul, mais aussi à tous les princes et aux grands officiers du roi."],[1,17,"Et il leur dit les paroles de la reine, et comme elle avait contredit le roi, et continuant: De même, ajouta-t-il, qu’elle a contredit le roi Artaxerxès,","Et il leur dit les paroles de la reine, et comme elle avait contredit le roi, et continuant: De même, ajouta-t-il, qu’elle a contredit le roi Artaxerxès,"],[1,18,"Les autres femmes des Perses et des Mèdes du premier rang, apprenant ce qu’elle a dit au roi, oseront à l’avenir ne point honorer leurs époux.","Les autres femmes des Perses et des Mèdes du premier rang, apprenant ce qu’elle a dit au roi, oseront à l’avenir ne point honorer leurs époux."],[1,19,"Si donc le roi le juge à propos, qu’il rende un édit, qu’il l’écrive selon la loi des Perses et des Mèdes, que l’on ne puisse y déroger; qu’il défende à la reine de s’approcher désormais de sa personne, et que le roi donne le diadème royal à une femme meilleure qu’elle;","Si donc le roi le juge à propos, qu’il rende un édit, qu’il l’écrive selon la loi des Perses et des Mèdes, que l’on ne puisse y déroger; qu’il défende à la reine de s’approcher désormais de sa personne, et que le roi donne le diadème royal à une femme meilleure qu’elle;"],[1,20,"Et que l’édit qu’aura rendu le roi soit publié en tout son royaume. Alors, toutes les femmes mettront leurs soins à honorer leurs époux, depuis l’indigent jusqu’au riche.","Et que l’édit qu’aura rendu le roi soit publié en tout son royaume. Alors, toutes les femmes mettront leurs soins à honorer leurs époux, depuis l’indigent jusqu’au riche."],[1,21,"Or, ce conseil plut au roi et aux princes, et le roi fit comme avait dit Muchée.","Or, ce conseil plut au roi et aux princes, et le roi fit comme avait dit Muchée."],[1,22,"Et il envoya dans toutes les provinces de son royaume l’édit traduit en leurs diverses langues, afin qu’en toute demeure on eût crainte.","Et il envoya dans toutes les provinces de son royaume l’édit traduit en leurs diverses langues, afin qu’en toute demeure on eût crainte."],[2,1,"Après ces choses, la colère du roi à la longue s’assoupit; mais il ne rechercha plus la reine, se souvenant de ce qu’elle avait dit, et du jugement qu’il avait rendu contre elle.","Après ces choses, la colère du roi à la longue s’assoupit; mais il ne rechercha plus la reine, se souvenant de ce qu’elle avait dit, et du jugement qu’il avait rendu contre elle."],[2,2,"Et les serviteurs du roi dirent: Que l’on cherche pour le roi des jeunes filles chastes et belles.","Et les serviteurs du roi dirent: Que l’on cherche pour le roi des jeunes filles chastes et belles."],[2,3,"Que le roi donne ses ordres aux comarques de toutes les provinces de son royaume; qu’ils choisissent des jeunes filles vierges et belles pour le gynécée de la ville de Suse; qu’on les mette entre les mains de l’eunuque du roi gardien des femmes; et qu’on leur donne là des cosmétiques et toutes sortes de soins.","Que le roi donne ses ordres aux comarques de toutes les provinces de son royaume; qu’ils choisissent des jeunes filles vierges et belles pour le gynécée de la ville de Suse; qu’on les mette entre les mains de l’eunuque du roi gardien des femmes; et qu’on leur donne là des cosmétiques et toutes sortes de soins."],[2,4,"Puis, la femme qui plaira au roi sera reine à la place de Vasthi. Ce projet fut agréable au roi, et il fit ainsi.","Puis, la femme qui plaira au roi sera reine à la place de Vasthi. Ce projet fut agréable au roi, et il fit ainsi."],[2,5,"Or, il y avait en la ville de Suse un Juif qui se nommait Mardochée, fils de Jaïr, fils de Sémeï, fils de Cisée, de la tribu de Benjamin,","Or, il y avait en la ville de Suse un Juif qui se nommait Mardochée, fils de Jaïr, fils de Sémeï, fils de Cisée, de la tribu de Benjamin,"],[2,6,"Qui avait été fait captif à Jérusalem, parmi ceux qu’avait emmenés Nabuchodonosor, roi de Babylone.","Qui avait été fait captif à Jérusalem, parmi ceux qu’avait emmenés Nabuchodonosor, roi de Babylone."],[2,7,"Il avait élevé une enfant, fille d’Aminadab, son oncle paternel, et elle se nommait Esther, et, ses parents étant morts, il l’avait élevée pour qu’elle fût sa femme, et la jeune fille était belle.","Il avait élevé une enfant, fille d’Aminadab, son oncle paternel, et elle se nommait Esther, et, ses parents étant morts, il l’avait élevée pour qu’elle fût sa femme, et la jeune fille était belle."],[2,8,"Or, lorsque l’édit du roi fut publié, beaucoup de jeunes filles furent réunies à Suse entre les mains de l’eunuque Haï. Esther fut aussi conduite chez Haï, gardien des femmes.","Or, lorsque l’édit du roi fut publié, beaucoup de jeunes filles furent réunies à Suse entre les mains de l’eunuque Haï. Esther fut aussi conduite chez Haï, gardien des femmes."],[2,9,"Et la jeune fille lui plut et elle trouva grâce à ses yeux, et il se hâta de lui donner des cosmétiques et sa part, et sept jeunes filles du palais pour la servir; il en usa bien avec elle et avec ses suivantes, dans le gynécée.","Et la jeune fille lui plut et elle trouva grâce à ses yeux, et il se hâta de lui donner des cosmétiques et sa part, et sept jeunes filles du palais pour la servir; il en usa bien avec elle et avec ses suivantes, dans le gynécée."],[2,10,"Et Esther ne fit connaître ni ses parents ni sa patrie, car Mardochée lui avait défendu d’en rien déclarer.","Et Esther ne fit connaître ni ses parents ni sa patrie, car Mardochée lui avait défendu d’en rien déclarer."],[2,11,"Et chaque jour Mardochée se promenait dans le parvis du gynécée, observant ce qui pouvait arriver à Esther.","Et chaque jour Mardochée se promenait dans le parvis du gynécée, observant ce qui pouvait arriver à Esther."],[2,12,"Or, le moment où une jeune fille entre chez le roi, arrive quand les douze mois sont accomplis, car alors les jours de la purification sont écoulés; pendant six mois, elle s’est ointe d’huile de myrrhe, et pendant six mois d’aromates et de cosmétiques de femmes.","Or, le moment où une jeune fille entre chez le roi, arrive quand les douze mois sont accomplis, car alors les jours de la purification sont écoulés; pendant six mois, elle s’est ointe d’huile de myrrhe, et pendant six mois d’aromates et de cosmétiques de femmes."],[2,13,"Enfin, on l’introduit chez le roi, et l’eunuque à qui il en donne l’ordre la conduit, pour qu’elle aille auprès de lui, du gynécée aux chambres du roi.","Enfin, on l’introduit chez le roi, et l’eunuque à qui il en donne l’ordre la conduit, pour qu’elle aille auprès de lui, du gynécée aux chambres du roi."],[2,14,"Elle y entre le soir, et, le lendemain, elle retourne au second gynécée où est l’eunuque Haï, gardien des femmes, et on ne la reconduit plus chez le roi, à moins qu’il ne la demande par son nom.","Elle y entre le soir, et, le lendemain, elle retourne au second gynécée où est l’eunuque Haï, gardien des femmes, et on ne la reconduit plus chez le roi, à moins qu’il ne la demande par son nom."],[2,15,"Et quand fut accompli le temps après lequel Esther, fille d’Aminadab, oncle paternel de Mardochée, devait être présentée au roi, elle ne négligea rien de ce que lui prescrivit l’eunuque, gardien des femmes. Car il était donné à Esther de trouver grâce aux yeux de tous ceux qui la voyaient.","Et quand fut accompli le temps après lequel Esther, fille d’Aminadab, oncle paternel de Mardochée, devait être présentée au roi, elle ne négligea rien de ce que lui prescrivit l’eunuque, gardien des femmes. Car il était donné à Esther de trouver grâce aux yeux de tous ceux qui la voyaient."],[2,16,"Elle entra donc chez le roi Artaxerxès, le douzième mois qui est adar, la septième année de son règne.","Elle entra donc chez le roi Artaxerxès, le douzième mois qui est adar, la septième année de son règne."],[2,17,"Et le roi aima Esther, et elle trouva grâce à ses yeux plus que toutes les autres vierges, et il lui mit le diadème de reine.","Et le roi aima Esther, et elle trouva grâce à ses yeux plus que toutes les autres vierges, et il lui mit le diadème de reine."],[2,18,"Et le roi fit un festin à tous ses amis et à tous ses grands, et la fête dura sept jours, et il célébra magnifiquement le mariage d’Esther, et il fit remise de ce qui lui était dû par les sujets de son royaume.","Et le roi fit un festin à tous ses amis et à tous ses grands, et la fête dura sept jours, et il célébra magnifiquement le mariage d’Esther, et il fit remise de ce qui lui était dû par les sujets de son royaume."],[2,19,"Et Mardochée servait dans le parvis.","Et Mardochée servait dans le parvis."],[2,20,"Et Esther ne déclara point quelle était sa patrie; car Mardochée le lui avait défendu, lui prescrivant de craindre Dieu et de suivre ses commandements, comme lorsqu’elle demeurait en sa maison; et Esther ne changea rien à ses habitudes.","Et Esther ne déclara point quelle était sa patrie; car Mardochée le lui avait défendu, lui prescrivant de craindre Dieu et de suivre ses commandements, comme lorsqu’elle demeurait en sa maison; et Esther ne changea rien à ses habitudes."],[2,21,"Et les deux eunuques, chefs des gardes du corps du roi, s’affligèrent des honneurs auxquels s’élevait Mardochée, et ils cherchèrent à tuer Artaxerxès","Et les deux eunuques, chefs des gardes du corps du roi, s’affligèrent des honneurs auxquels s’élevait Mardochée, et ils cherchèrent à tuer Artaxerxès"],[2,22,"Et Mardochée découvrit le complot, et il le dit à Esther, qui dévoila tout au roi.","Et Mardochée découvrit le complot, et il le dit à Esther, qui dévoila tout au roi."],[2,23,"Or, le roi interrogea les eunuques et il les fit pendre; et il prescrivit d’écrire en un mémorial, dans les archives de la bibliothèque royale, une notice sur les bons offices de Mardochée, à sa louange.","Or, le roi interrogea les eunuques et il les fit pendre; et il prescrivit d’écrire en un mémorial, dans les archives de la bibliothèque royale, une notice sur les bons offices de Mardochée, à sa louange."],[3,1,"Et, après cela, le roi Artaxerxès glorifia Aman, fils d’Amadathe le Bugéen, et il l’exalta, et il le fit asseoir sur un siège au-dessus de tous ses amis.","Et, après cela, le roi Artaxerxès glorifia Aman, fils d’Amadathe le Bugéen, et il l’exalta, et il le fit asseoir sur un siège au-dessus de tous ses amis."],[3,2,"Et tous ceux qui servaient dans le parvis l’adoraient, car ainsi l’avait ordonné le roi; et Mardochée ne se prosternait pas devant lui.","Et tous ceux qui servaient dans le parvis l’adoraient, car ainsi l’avait ordonné le roi; et Mardochée ne se prosternait pas devant lui."],[3,3,"Et les serviteurs du parvis dirent à Mardochée: Mardochée, pourquoi désobéis-tu à ce qu’a dit le roi?","Et les serviteurs du parvis dirent à Mardochée: Mardochée, pourquoi désobéis-tu à ce qu’a dit le roi?"],[3,4,"Chaque jour ils lui parlaient ainsi, et il ne les écoutait pas; enfin, ils informèrent Aman que Mardochée résistait aux ordres du roi; or, Mardochée leur avait déclaré qu’il était Juif.","Chaque jour ils lui parlaient ainsi, et il ne les écoutait pas; enfin, ils informèrent Aman que Mardochée résistait aux ordres du roi; or, Mardochée leur avait déclaré qu’il était Juif."],[3,5,"Et Aman, en apprenant que Mardochée ne se prosternait pas devant lui, fut fort courroucé.","Et Aman, en apprenant que Mardochée ne se prosternait pas devant lui, fut fort courroucé."],[3,6,"Et il résolut d’effacer tous les Juifs du royaume d’Artaxerxès.","Et il résolut d’effacer tous les Juifs du royaume d’Artaxerxès."],[3,7,"Et, en la douzième année du règne d’Artaxerxès, il prépara un édit, et il agita les sorts pour savoir le mois et le jour où il exterminerait en même temps la race de Mardochée, et le sort tomba sur le quatorzième du mois qui est appelé adar.","Et, en la douzième année du règne d’Artaxerxès, il prépara un édit, et il agita les sorts pour savoir le mois et le jour où il exterminerait en même temps la race de Mardochée, et le sort tomba sur le quatorzième du mois qui est appelé adar."],[3,8,"Et il parla au roi disant: Il y a un peuple épars en toutes les provinces de ton royaume; leurs lois diffèrent de toutes les autres lois; ils n’obéissent point à celles du roi; il n’est pas à propos que le roi les laisse subsister.","Et il parla au roi disant: Il y a un peuple épars en toutes les provinces de ton royaume; leurs lois diffèrent de toutes les autres lois; ils n’obéissent point à celles du roi; il n’est pas à propos que le roi les laisse subsister."],[3,9,"S’il plaît au roi, qu’il décrète qu’on les détruise, et moi je ferai rentrer au trésor royal dix mille talents d’argent.","S’il plaît au roi, qu’il décrète qu’on les détruise, et moi je ferai rentrer au trésor royal dix mille talents d’argent."],[3,10,"Et le roi ôtant son anneau le remit à Aman pour sceller l’édit contre les Juifs.","Et le roi ôtant son anneau le remit à Aman pour sceller l’édit contre les Juifs."],[3,11,"Et le roi lui dit: L’argent sera pour toi, fais de ce peuple ce qu’il te plaît.","Et le roi lui dit: L’argent sera pour toi, fais de ce peuple ce qu’il te plaît."],[3,12,"Et, le treize du premier mois, les scribes du roi furent convoqués, et ils écrivirent, selon l’ordre d’Aman, aux généraux et aux gouverneurs des cent vingt-sept provinces de l’Inde à l’Éthiopie, et aux chefs des nations chacun en sa langue, de la part du roi Artaxerxès.","Et, le treize du premier mois, les scribes du roi furent convoqués, et ils écrivirent, selon l’ordre d’Aman, aux généraux et aux gouverneurs des cent vingt-sept provinces de l’Inde à l’Éthiopie, et aux chefs des nations chacun en sa langue, de la part du roi Artaxerxès."],[3,13,"Et des courriers portèrent dans tout le royaume le commandement de détruire en un seul jour, le premier du douzième mois, qui est adar, toute la race des Juifs, et de piller leurs biens. Or, voici la copie de la lettre:","Et des courriers portèrent dans tout le royaume le commandement de détruire en un seul jour, le premier du douzième mois, qui est adar, toute la race des Juifs, et de piller leurs biens. Or, voici la copie de la lettre:"],[3,14,"Et les copies de ces lettres furent publiées en chaque province, et il fut enjoint à chaque nation de se tenir prête pour le jour indiqué.","Et les copies de ces lettres furent publiées en chaque province, et il fut enjoint à chaque nation de se tenir prête pour le jour indiqué."],[3,15,"On y avait mis de l’empressement à Suse, et le roi et Aman buvaient à pleines coupes; mais la ville était toute troublée.","On y avait mis de l’empressement à Suse, et le roi et Aman buvaient à pleines coupes; mais la ville était toute troublée."],[4,1,"Or, Mardochée, instruit de ce qu’on avait fait, déchira ses vêtements, se ceignit d’un cilice et se couvrit de cendre; puis, s’élançant par les rues de la ville, il cria à haute voix: Un peuple innocent périt.","Or, Mardochée, instruit de ce qu’on avait fait, déchira ses vêtements, se ceignit d’un cilice et se couvrit de cendre; puis, s’élançant par les rues de la ville, il cria à haute voix: Un peuple innocent périt."],[4,2,"Et il arriva devant la porte du roi, et il s’y tint debout; car il ne lui était pas permis d’entrer dans la cour, ayant un cilice et de la cendre.","Et il arriva devant la porte du roi, et il s’y tint debout; car il ne lui était pas permis d’entrer dans la cour, ayant un cilice et de la cendre."],[4,3,"Et en toute province, où l’édit avait été publié, les Juifs s’étaient couverts de cilices et de cendres, et l’on n’entendait que des cris, des gémissements et des pleurs.","Et en toute province, où l’édit avait été publié, les Juifs s’étaient couverts de cilices et de cendres, et l’on n’entendait que des cris, des gémissements et des pleurs."],[4,4,"Et les servantes et les eunuques de la reine entrèrent, et lui dirent ce qui était advenu, et elle en fut troublée, et elle envoya prier Mardochée de se vêtir d’une robe et d’ôter son cilice, et il n’obéit pas.","Et les servantes et les eunuques de la reine entrèrent, et lui dirent ce qui était advenu, et elle en fut troublée, et elle envoya prier Mardochée de se vêtir d’une robe et d’ôter son cilice, et il n’obéit pas."],[4,5,"Et Esther appela Achrathée, son eunuque, qui se tenait auprès d’elle, et elle l’envoya demander à Mardochée la vérité exacte.","Et Esther appela Achrathée, son eunuque, qui se tenait auprès d’elle, et elle l’envoya demander à Mardochée la vérité exacte."],[4,6,"Et Mardochée lui fit connaître tout ce qui s’était passé, et la promesse qu’Aman avait faite au roi de verser au trésor dix mille talents d’argent, afin qu’il exterminât les Juifs.","Et Mardochée lui fit connaître tout ce qui s’était passé, et la promesse qu’Aman avait faite au roi de verser au trésor dix mille talents d’argent, afin qu’il exterminât les Juifs."],[4,7,"Et il lui donna, pour le montrer à Esther, l’édit affiché dans Suse sur ce massacre, et il lui dit: Recommande à la reine d’entrer chez le roi, pour l’implorer et le supplier en faveur du peuple, dis-lui: Souviens-toi de ton humble état, quand je te nourrissais de ma main. Pourquoi Aman, le second après le roi, a-t-il parlé contre nous afin que nous périssions? Invoque le Seigneur; parle au roi pour nous sauver de la mort.","Et il lui donna, pour le montrer à Esther, l’édit affiché dans Suse sur ce massacre, et il lui dit: Recommande à la reine d’entrer chez le roi, pour l’implorer et le supplier en faveur du peuple, dis-lui: Souviens-toi de ton humble état, quand je te nourrissais de ma main. Pourquoi Aman, le second après le roi, a-t-il parlé contre nous afin que nous périssions? Invoque le Seigneur; parle au roi pour nous sauver de la mort."],[4,8,"Or, Achrathée, étant rentré, répéta toutes ces paroles à la reine.","Or, Achrathée, étant rentré, répéta toutes ces paroles à la reine."],[4,9,"Et Esther lui répondit: Va retrouver Mardochée, et dis-lui:","Et Esther lui répondit: Va retrouver Mardochée, et dis-lui:"],[4,10,"Toutes les nations de l’empire savent que n’importe quel homme ou femme qui entre auprès du roi, dans l’intérieur du palais, sans y être appelé, n’a pas de salut à espérer; sauf celui sur qui le roi étend sa verge d’or; celui-là est sauvé. Et moi, voilà trente jours que je n’ai été appelée pour entrer chez le roi.","Toutes les nations de l’empire savent que n’importe quel homme ou femme qui entre auprès du roi, dans l’intérieur du palais, sans y être appelé, n’a pas de salut à espérer; sauf celui sur qui le roi étend sa verge d’or; celui-là est sauvé. Et moi, voilà trente jours que je n’ai été appelée pour entrer chez le roi."],[4,11,"Et Achrathée rapporta toutes les paroles d’Esther à Mardochée.","Et Achrathée rapporta toutes les paroles d’Esther à Mardochée."],[4,12,"Et Mardochée lui répondit: Rentre, et dis — lui: Esther, ne te dis pas à toi-même que dans tout le royaume, toi seule échapperais plutôt que tous les Juifs.","Et Mardochée lui répondit: Rentre, et dis — lui: Esther, ne te dis pas à toi-même que dans tout le royaume, toi seule échapperais plutôt que tous les Juifs."],[4,13,"Si en ce moment tu me désobéis, le secours et la protection viendront d’ailleurs aux Juifs, et toi, et la maison de ton père, vous périrez. Et qui sait si ce n’est pas à cette occasion que tu règnes?","Si en ce moment tu me désobéis, le secours et la protection viendront d’ailleurs aux Juifs, et toi, et la maison de ton père, vous périrez. Et qui sait si ce n’est pas à cette occasion que tu règnes?"],[4,14,"Et Esther renvoya à Mardochée l’homme qui était venu près d’elle, disant:","Et Esther renvoya à Mardochée l’homme qui était venu près d’elle, disant:"],[4,15,"Éloigne-toi, rassemble tous les Juifs qui sont à Suse, jeûnez pour moi; passez trois jours et trois nuits sans manger ni boire, et moi et mes suivantes, nous ne prendrons aucun aliment; alors j’entrerai chez le roi, contre la loi, dussé-je mourir.","Éloigne-toi, rassemble tous les Juifs qui sont à Suse, jeûnez pour moi; passez trois jours et trois nuits sans manger ni boire, et moi et mes suivantes, nous ne prendrons aucun aliment; alors j’entrerai chez le roi, contre la loi, dussé-je mourir."],[4,16,"Et Mardochée, s’étant éloigné, fit ce que lui avait prescrit Esther; et il pria le Seigneur, se souvenant de toutes les œuvres de Dieu, et il dit: Seigneur, Seigneur, Roi de tous les rois; il n’est rien qui ne soit en votre puissance, et nul ne vous contredira si votre volonté est de sauver Israël. Vous avez créé le ciel et la terre et toutes les merveilles qui sont sous les cieux, vous êtes le Seigneur de toutes choses, et nul ne peut s’opposer au Seigneur. Rien ne vous est caché; vous savez, Seigneur, que ce n’est point par insolence, que ce n’est point par orgueil, que ce n’est point par vaine gloire, que j’ai refusé d’adorer le superbe Aman; car, pour le salut d’Israël, je lui eusse avec joie baisé la plante des pieds. Mais, je ne l’ai point adoré, de peur de mettre la gloire d’un homme au-dessus de la gloire de Dieu, et je n’adorerai personne hormis vous, mon Seigneur, et je ne ferai point de telles choses par orgueil. Et maintenant, Seigneur Dieu et Roi, Dieu d’Abraham, épargnez votre peuple, car ils nous regardent pour nous perdre, et dès l’origine ils ont désiré détruire votre héritage. Ne méprisez point votre peuple particulier que vous avez délivré de la terre d’Égypte; exaucez ma prière, soyez propice à ceux que vous vous êtes réservés en partage; changez notre deuil en fêtes, afin que vivants nous chantions votre nom, ô Seigneur; ne fermez pas la bouche de ceux qui vous louent, ô Seigneur. Et tout Israël jeta des cris de toute sa force, car ils avaient la mort devant les yeux.","Et Mardochée, s’étant éloigné, fit ce que lui avait prescrit Esther; et il pria le Seigneur, se souvenant de toutes les œuvres de Dieu, et il dit: Seigneur, Seigneur, Roi de tous les rois; il n’est rien qui ne soit en votre puissance, et nul ne vous contredira si votre volonté est de sauver Israël. Vous avez créé le ciel et la terre et toutes les merveilles qui sont sous les cieux, vous êtes le Seigneur de toutes choses, et nul ne peut s’opposer au Seigneur. Rien ne vous est caché; vous savez, Seigneur, que ce n’est point par insolence, que ce n’est point par orgueil, que ce n’est point par vaine gloire, que j’ai refusé d’adorer le superbe Aman; car, pour le salut d’Israël, je lui eusse avec joie baisé la plante des pieds. Mais, je ne l’ai point adoré, de peur de mettre la gloire d’un homme au-dessus de la gloire de Dieu, et je n’adorerai personne hormis vous, mon Seigneur, et je ne ferai point de telles choses par orgueil. Et maintenant, Seigneur Dieu et Roi, Dieu d’Abraham, épargnez votre peuple, car ils nous regardent pour nous perdre, et dès l’origine ils ont désiré détruire votre héritage. Ne méprisez point votre peuple particulier que vous avez délivré de la terre d’Égypte; exaucez ma prière, soyez propice à ceux que vous vous êtes réservés en partage; changez notre deuil en fêtes, afin que vivants nous chantions votre nom, ô Seigneur; ne fermez pas la bouche de ceux qui vous louent, ô Seigneur. Et tout Israël jeta des cris de toute sa force, car ils avaient la mort devant les yeux."],[5,1,"Et le troisième jour, lorsqu’elle eut fini de prier, elle dépouilla les habits de la servitude et se revêtit de sa gloire, et redevenue éclatante, après avoir invoqué le Dieu qui voit toutes choses et qui sauve, elle prit avec elle deux servantes; sur l’une elle s’appuya comme une femme délicate; l’autre la suivit allégeant le poids de son manteau; et elle-même s’avança rougissant en la fraîcheur de sa beauté, le visage riant, plein de bienveillance, tandis que son cœur était oppressé par la crainte. Ayant franchi toutes les portes, elle s’arrêta devant le roi. Or, il était assis sur son trône royal, et il s’était revêtu de toute sa magnificence, et il était couvert d’or et de pierres précieuses, et il était terrible. Et quand il leva son front rayonnant de majesté, un éclair de fureur brilla dans son regard. Et la reine tomba, et son teint se changea en une mortelle pâleur, et elle se pencha sur la tête de la servante qui la précédait. Et Dieu adoucit l’esprit du roi; et saisi d’angoisse, Artaxerxès s’élança de son trône, et il la prit dans ses bras jusqu’à ce qu’elle revînt, et il la consola par des paroles caressantes, et il lui dit: Esther! qu’y a-t-il, je suis ton frère, rassure-toi, tu ne mourras point; mais notre loi est pour tous; approche.","Et le troisième jour, lorsqu’elle eut fini de prier, elle dépouilla les habits de la servitude et se revêtit de sa gloire, et redevenue éclatante, après avoir invoqué le Dieu qui voit toutes choses et qui sauve, elle prit avec elle deux servantes; sur l’une elle s’appuya comme une femme délicate; l’autre la suivit allégeant le poids de son manteau; et elle-même s’avança rougissant en la fraîcheur de sa beauté, le visage riant, plein de bienveillance, tandis que son cœur était oppressé par la crainte. Ayant franchi toutes les portes, elle s’arrêta devant le roi. Or, il était assis sur son trône royal, et il s’était revêtu de toute sa magnificence, et il était couvert d’or et de pierres précieuses, et il était terrible. Et quand il leva son front rayonnant de majesté, un éclair de fureur brilla dans son regard. Et la reine tomba, et son teint se changea en une mortelle pâleur, et elle se pencha sur la tête de la servante qui la précédait. Et Dieu adoucit l’esprit du roi; et saisi d’angoisse, Artaxerxès s’élança de son trône, et il la prit dans ses bras jusqu’à ce qu’elle revînt, et il la consola par des paroles caressantes, et il lui dit: Esther! qu’y a-t-il, je suis ton frère, rassure-toi, tu ne mourras point; mais notre loi est pour tous; approche."],[5,2,"Et ayant levé sa verge d’or, il la posa sur son cou et il l’embrassa, et il lui dit: Parle-moi, et elle répondit: Je t’ai vu, seigneur, comme l’ange de Dieu, et mon cœur a été troublé par la crainte de ta gloire, car tu frappes d’admiration, ô seigneur, et ton visage est l’arbitre des grâces. Pendant qu’elle parlait, elle s’évanouit encore, et le roi fut troublé, et tous ses serviteurs la consolèrent.","Et ayant levé sa verge d’or, il la posa sur son cou et il l’embrassa, et il lui dit: Parle-moi, et elle répondit: Je t’ai vu, seigneur, comme l’ange de Dieu, et mon cœur a été troublé par la crainte de ta gloire, car tu frappes d’admiration, ô seigneur, et ton visage est l’arbitre des grâces. Pendant qu’elle parlait, elle s’évanouit encore, et le roi fut troublé, et tous ses serviteurs la consolèrent."],[5,3,"Et le roi dit: Que veux-tu, Esther? quelle est ta demande? Serait-ce la moitié de mon royaume, elle sera à toi.","Et le roi dit: Que veux-tu, Esther? quelle est ta demande? Serait-ce la moitié de mon royaume, elle sera à toi."],[5,4,"Et Esther dit: Ce jour est pour moi un jour de fête, s’il plaît au roi, qu’il vienne avec Aman à un festin que je fais aujourd’hui.","Et Esther dit: Ce jour est pour moi un jour de fête, s’il plaît au roi, qu’il vienne avec Aman à un festin que je fais aujourd’hui."],[5,5,"Et le roi dit: Que l’on se hâte d’avertir Aman, afin que nous fassions selon la parole d’Esther. Et tous les deux assistèrent au festin qu’avait dit la reine.","Et le roi dit: Que l’on se hâte d’avertir Aman, afin que nous fassions selon la parole d’Esther. Et tous les deux assistèrent au festin qu’avait dit la reine."],[5,6,"Et, pendant le repas, le roi lui dit: Qu’y a-t-il, reine Esther? Ce que tu demandes sera.","Et, pendant le repas, le roi lui dit: Qu’y a-t-il, reine Esther? Ce que tu demandes sera."],[5,7,"Et elle répondit: Ma requête et ma demande?","Et elle répondit: Ma requête et ma demande?"],[5,8,"Si j’ai trouvé grâce devant le roi, que le roi vienne encore avec Aman demain au festin que je leur ferai, et demain je ferai ma requête et ma demande.","Si j’ai trouvé grâce devant le roi, que le roi vienne encore avec Aman demain au festin que je leur ferai, et demain je ferai ma requête et ma demande."],[5,9,"Et Aman, au comble de la joie, sortit d’auprès de son maître; et en apercevant dans le parvis le Juif Mardochée, il fut grandement courroucé.","Et Aman, au comble de la joie, sortit d’auprès de son maître; et en apercevant dans le parvis le Juif Mardochée, il fut grandement courroucé."],[5,10,"Et aussitôt rentré chez lui, il convoqua ses amis et Zosara, sa femme,","Et aussitôt rentré chez lui, il convoqua ses amis et Zosara, sa femme,"],[5,11,"Et il leur décrivit ses richesses et les honneurs dont le roi l’avait revêtu, et comme il l’avait placé à la tête du royaume.","Et il leur décrivit ses richesses et les honneurs dont le roi l’avait revêtu, et comme il l’avait placé à la tête du royaume."],[5,12,"Et il ajouta: La reine n’a invité personne au festin qu’elle vient de donner à son époux, si ce n’est moi, et je suis convié encore pour demain.","Et il ajouta: La reine n’a invité personne au festin qu’elle vient de donner à son époux, si ce n’est moi, et je suis convié encore pour demain."],[5,13,"Mais rien de tout cela ne me charmera tant que je verrai dans le parvis le Juif Mardochée.","Mais rien de tout cela ne me charmera tant que je verrai dans le parvis le Juif Mardochée."],[5,14,"Et Zosara, sa femme, et ses amis lui dirent: Que l’on te fasse une potence de cinquante coudées; parles-en demain au roi dès l’aurore, et que Mardochée soit pendu à cette potence. Ensuite, va au festin avec ton maître, et sois joyeux. Et le conseil plut à Aman, et il fit dresser la potence.","Et Zosara, sa femme, et ses amis lui dirent: Que l’on te fasse une potence de cinquante coudées; parles-en demain au roi dès l’aurore, et que Mardochée soit pendu à cette potence. Ensuite, va au festin avec ton maître, et sois joyeux. Et le conseil plut à Aman, et il fit dresser la potence."],[6,1,"Or, cette nuit-là, le Seigneur éloigna du roi le sommeil, et Artaxerxès dit à son serviteur d’apporter le livre de ses archives et de le lui lire.","Or, cette nuit-là, le Seigneur éloigna du roi le sommeil, et Artaxerxès dit à son serviteur d’apporter le livre de ses archives et de le lui lire."],[6,2,"Et il tomba sur ce qui était écrit concernant Mardochée, quand il avait fait connaître au roi le complot des deux eunuques qui le gardaient, et qui voulaient porter les mains sur lui.","Et il tomba sur ce qui était écrit concernant Mardochée, quand il avait fait connaître au roi le complot des deux eunuques qui le gardaient, et qui voulaient porter les mains sur lui."],[6,3,"Et le roi dit: Quels honneurs, quelle grâce Mardochée a-t-il reçus de moi? Et les serviteurs répondirent: Tu n’as rien fait pour lui.","Et le roi dit: Quels honneurs, quelle grâce Mardochée a-t-il reçus de moi? Et les serviteurs répondirent: Tu n’as rien fait pour lui."],[6,4,"Pendant que le roi se rappelait le zèle de Mardochée, Aman entra dans le parvis, et le roi dit: Y a-t-il quelqu’un dans le parvis? Or, Aman arrivait pour demander au roi de pendre Mardochée à la potence qu’il avait dressée.","Pendant que le roi se rappelait le zèle de Mardochée, Aman entra dans le parvis, et le roi dit: Y a-t-il quelqu’un dans le parvis? Or, Aman arrivait pour demander au roi de pendre Mardochée à la potence qu’il avait dressée."],[6,5,"Et les serviteurs du roi répondirent: Voilà Aman dans le parvis. Et le roi dit: Appelez-le.","Et les serviteurs du roi répondirent: Voilà Aman dans le parvis. Et le roi dit: Appelez-le."],[6,6,"Et le roi dit à Aman: Que ferai-je pour l’homme que je veux glorifier? Et Aman se dit: Qui donc le roi veut-il glorifier, si ce n’est moi?","Et le roi dit à Aman: Que ferai-je pour l’homme que je veux glorifier? Et Aman se dit: Qui donc le roi veut-il glorifier, si ce n’est moi?"],[6,7,"Et il répondit: Pour l’homme que le roi veut glorifier,","Et il répondit: Pour l’homme que le roi veut glorifier,"],[6,8,"Que les serviteurs du roi apportent la robe de fin lin dont il se revêt, et le cheval qu’il monte.","Que les serviteurs du roi apportent la robe de fin lin dont il se revêt, et le cheval qu’il monte."],[6,9,"Que cela soit donné à l’un des amis du roi, parmi ceux du premier rang; qu’il habille l’homme que le roi aime, qu’il le fasse monter à cheval, que dans toutes les places de la ville il proclame ces mots: Ainsi sera-t-il fait à tout homme que le roi honore.","Que cela soit donné à l’un des amis du roi, parmi ceux du premier rang; qu’il habille l’homme que le roi aime, qu’il le fasse monter à cheval, que dans toutes les places de la ville il proclame ces mots: Ainsi sera-t-il fait à tout homme que le roi honore."],[6,10,"Et le roi dit à Aman: Tu as bien parlé; ainsi soit fait par toi au Juif Mardochée qui sert en mon parvis, et que rien ne soit négligé de ce que tu as dit.","Et le roi dit à Aman: Tu as bien parlé; ainsi soit fait par toi au Juif Mardochée qui sert en mon parvis, et que rien ne soit négligé de ce que tu as dit."],[6,11,"Aman prit donc la robe, et le cheval, et il habilla Mardochée, et il le fit monter à cheval, et il parcourut toutes les rues de la ville, et il proclama ces mots: Ainsi sera-t-il fait à tout homme que le roi voudra honorer.","Aman prit donc la robe, et le cheval, et il habilla Mardochée, et il le fit monter à cheval, et il parcourut toutes les rues de la ville, et il proclama ces mots: Ainsi sera-t-il fait à tout homme que le roi voudra honorer."],[6,12,"Et Mardochée revint au parvis, et Aman rentra en sa demeure avec un grand mal de tête.","Et Mardochée revint au parvis, et Aman rentra en sa demeure avec un grand mal de tête."],[6,13,"Et il fit à Zosara, sa femme, et à ses amis, le récit de ce qui était advenu; et ses amis et sa femme lui dirent: Si Mardochée est de la race des Juifs, tu as commencé à être humilié devant lui; tu tomberas, et tu ne pourras te défendre contre lui; car le Dieu vivant est avec lui.","Et il fit à Zosara, sa femme, et à ses amis, le récit de ce qui était advenu; et ses amis et sa femme lui dirent: Si Mardochée est de la race des Juifs, tu as commencé à être humilié devant lui; tu tomberas, et tu ne pourras te défendre contre lui; car le Dieu vivant est avec lui."],[6,14,"Comme ils parlaient encore, les eunuques vinrent presser Aman de se rendre au repas qu’Esther avait préparé.","Comme ils parlaient encore, les eunuques vinrent presser Aman de se rendre au repas qu’Esther avait préparé."],[7,1,"Le roi et Aman entrèrent pour boire avec la reine.","Le roi et Aman entrèrent pour boire avec la reine."],[7,2,"Et, à ce second festin, le roi dit à Esther: Qu’y a-t-il, reine Esther? Quelle est ta requête, quelle est ta demande? Qu’il te soit accordé jusqu’à la moitié de mon royaume.","Et, à ce second festin, le roi dit à Esther: Qu’y a-t-il, reine Esther? Quelle est ta requête, quelle est ta demande? Qu’il te soit accordé jusqu’à la moitié de mon royaume."],[7,3,"Et elle répondit: Si j’ai trouvé grâce devant le roi, qu’il accorde à ma requête, ma vie, et à ma demande, mon peuple.","Et elle répondit: Si j’ai trouvé grâce devant le roi, qu’il accorde à ma requête, ma vie, et à ma demande, mon peuple."],[7,4,"Car moi et mon peuple nous sommes voués à la destruction, au pillage, à l’esclavage, nous et nos enfants, nos serviteurs et nos servantes. Mais je n’y ai point cru, parce que l’accusateur n’est pas digne du palais du roi.","Car moi et mon peuple nous sommes voués à la destruction, au pillage, à l’esclavage, nous et nos enfants, nos serviteurs et nos servantes. Mais je n’y ai point cru, parce que l’accusateur n’est pas digne du palais du roi."],[7,5,"Et le roi Qui donc est celui qui a osé faire cette chose?","Et le roi Qui donc est celui qui a osé faire cette chose?"],[7,6,"Et Esther dit: Notre ennemi c’est Aman, ce méchant homme. Or, Aman était plein de trouble à cause du roi et de la reine.","Et Esther dit: Notre ennemi c’est Aman, ce méchant homme. Or, Aman était plein de trouble à cause du roi et de la reine."],[7,7,"Et le roi se leva de table pour aller dans le jardin, et Aman implora la reine; car il se voyait dans le malheur.","Et le roi se leva de table pour aller dans le jardin, et Aman implora la reine; car il se voyait dans le malheur."],[7,8,"Et le roi rentra du jardin, et Aman était tombé sur le lit en suppliant la reine, et le roi s’écria: Va-t-il jusqu’à faire violence à ma femme dans mon palais? A ces mots, Aman eut le visage bouleversé.","Et le roi rentra du jardin, et Aman était tombé sur le lit en suppliant la reine, et le roi s’écria: Va-t-il jusqu’à faire violence à ma femme dans mon palais? A ces mots, Aman eut le visage bouleversé."],[7,9,"Et Bugathan, l’un des eunuques, dit au roi: Aman a préparé pour Mardochée, qui a jadis averti le roi, une potence de cinquante coudées; elle est dressée dans sa maison. Et le roi dit: Qu’on l’y attache.","Et Bugathan, l’un des eunuques, dit au roi: Aman a préparé pour Mardochée, qui a jadis averti le roi, une potence de cinquante coudées; elle est dressée dans sa maison. Et le roi dit: Qu’on l’y attache."],[7,10,"Et Aman fut pendu à la potence qu’il tenaît prête pour Mardochée, et la colère du roi s’apaisa.","Et Aman fut pendu à la potence qu’il tenaît prête pour Mardochée, et la colère du roi s’apaisa."],[8,1,"Et, en ce jour-là même, le roi Artaxerxès fit don à Esther de tout ce que possédait Aman l’accusateur; et il appela Mardochée, car la reine lui avait dit leur parenté,","Et, en ce jour-là même, le roi Artaxerxès fit don à Esther de tout ce que possédait Aman l’accusateur; et il appela Mardochée, car la reine lui avait dit leur parenté,"],[8,2,"Et le roi prit l’anneau qu’il avait ôté à Aman et il le remit à Mardochée; et la reine chargea celui-ci d’administrer les biens d’Aman.","Et le roi prit l’anneau qu’il avait ôté à Aman et il le remit à Mardochée; et la reine chargea celui-ci d’administrer les biens d’Aman."],[8,3,"Et, continuant de parler au roi, elle se jeta à ses pieds, et lui demanda de rendre nuls les mauvais desseins d’Aman, et ce qu’il avait fait contre les Juifs.","Et, continuant de parler au roi, elle se jeta à ses pieds, et lui demanda de rendre nuls les mauvais desseins d’Aman, et ce qu’il avait fait contre les Juifs."],[8,4,"Et le roi étendit sur Esther sa verge d’or, et elle fut encouragée à se placer auprès de lui.","Et le roi étendit sur Esther sa verge d’or, et elle fut encouragée à se placer auprès de lui."],[8,5,"Et elle dit: S’il te plaît, si j’ai trouvé grâce, que l’on fasse révoquer les édits qu’a publiés Aman, ordonnant d’exterminer tous les Juifs qui sont en ton royaume.","Et elle dit: S’il te plaît, si j’ai trouvé grâce, que l’on fasse révoquer les édits qu’a publiés Aman, ordonnant d’exterminer tous les Juifs qui sont en ton royaume."],[8,6,"Car, comment pourrais — je voir la ruine de mon peuple? Comment pourrais-je survivre à la destruction de ma patrie?","Car, comment pourrais — je voir la ruine de mon peuple? Comment pourrais-je survivre à la destruction de ma patrie?"],[8,7,"Et le roi dit à Esther: Puisque je t’ai donné tous les biens d’Aman, et que je t’en ai gratifié; puisque je l’ai fait pendre lui — même pour avoir porté les mains sur les Juifs, que demandes-tu encore?","Et le roi dit à Esther: Puisque je t’ai donné tous les biens d’Aman, et que je t’en ai gratifié; puisque je l’ai fait pendre lui — même pour avoir porté les mains sur les Juifs, que demandes-tu encore?"],[8,8,"Écrivez vous-mêmes en mon nom ce qu’il vous plaira, et scellez-le avec mon anneau; car nul ne peut contredire ce qui est écrit par l’ordre du roi, et revêtu de son scel.","Écrivez vous-mêmes en mon nom ce qu’il vous plaira, et scellez-le avec mon anneau; car nul ne peut contredire ce qui est écrit par l’ordre du roi, et revêtu de son scel."],[8,9,"Les scribes furent donc convoqués le vingt-trois du premier mois, du mois de nisan, de la même année, et l’on écrivit ce qui était ordonné, concernant les Juifs, aux intendants et aux chefs des satrapes des cent vingt-sept provinces, depuis l’Inde jusqu’à l’Éthiopie, en la langue de chacune d’elles.","Les scribes furent donc convoqués le vingt-trois du premier mois, du mois de nisan, de la même année, et l’on écrivit ce qui était ordonné, concernant les Juifs, aux intendants et aux chefs des satrapes des cent vingt-sept provinces, depuis l’Inde jusqu’à l’Éthiopie, en la langue de chacune d’elles."],[8,10,"On écrivit au nom du roi, et on scella de son sceau les lettres, et on les expédia par des courriers.","On écrivit au nom du roi, et on scella de son sceau les lettres, et on les expédia par des courriers."],[8,11,"Elles prescrivaient de permettre aux Juifs, en chaque ville, de vivre selon leur loi, de leur porter secours, et de mettre à leur merci leurs ennemis et ceux qui résisteraient,","Elles prescrivaient de permettre aux Juifs, en chaque ville, de vivre selon leur loi, de leur porter secours, et de mettre à leur merci leurs ennemis et ceux qui résisteraient,"],[8,12,"Dans le royaume d’Artaxerxès, le treizième jour du douzième mois qui est adar.","Dans le royaume d’Artaxerxès, le treizième jour du douzième mois qui est adar."],[8,13,"Voici la copie de la lettre: Le grand roi Artaxerxès aux satrapes des cent vingt-sept provinces, de l’Inde à l’Éthiopie, aux gouverneurs des districts, et aux hommes dévoués à mon service, salut. Il arrive que plusieurs, après avoir été souvent honorés des bienfaits de la bonté, ambitionnent plus encore; non-seulement ils cherchent à maltraiter nos sujets, mais, incapables de modérer leur orgueil, ils méditent de mauvais desseins contre leurs bienfaiteurs; non-seulement ils veulent abolir la gratitude parmi les hommes, mais, exaltés par la vaine jactance de gens sans vertu, ils pensent se soustraire au jugement, fatal aux méchants, du Dieu qui voit toutes choses. Maintes fois la flatterie a rendu complices du crime de verser le sang innocent, et enveloppé de maux intolérables plusieurs de ceux qui sont investis de l’autorité, à qui est confié le maniement des affaires de leurs amis; certains hommes ayant trompé, par le faux raisonnement de la malice, la bienveillance sincère des puissants. Cela se peut voir moins par les plus anciennes histoires, que nous nous transmettons, qu’en examinant, sous nos pieds, les choses accomplies d’une manière criminelle par la pestilence d’hommes indignement revêtus du pouvoir; et il est de notre devoir, en vue de l’avenir, de préserver de trouble le royaume, et de donner la paix à tous les hommes, en usant de changements utiles, en jugeant, avec l’à-propos le plus équitable, les choses qui surviennent sous nos yeux. Aman, fils d’Amadathe, Macédonien en réalité, étranger au sang des Perses, bien éloigné de notre bonté naturelle, amicalement accueilli par nous, eut de notre amour, que nous portons à tous les hommes, une telle part que nous l’appelions notre père, que nous le faisions adorer par tous, et que nous lui avions donné la seconde place du royaume. Mais, il ne put maîtriser son orgueil, et il entreprit de nous ôter la vie et le pouvoir. D’abord, il nous demanda de perdre notre sauveur Mardochée, notre bienfaiteur en toute circonstance, et la reine Esther, notre irréprochable compagne, et tout leur peuple; et il me surprit par un tissu d’accusations calomnieuses. Et il espérait par ses artifices dépeupler nos provinces, et faire passer aux Macédoniens l’empire des Perses. Ce triple scélérat nous avait donc trahis au point de nous décider à exterminer les Juifs, quand nous avons reconnu que, loin d’être portés à mal faire, ils obéissaient aux lois les plus justes, qu’ils étaient les fils du Dieu vivant, très-grand et très-haut, qui nous a dirigés nous et nos ancêtres pour mettre notre royaume en la situation la plus florissante. En conséquence, vous agirez bien en n’exécutant pas l’édit que vous a envoyé Aman, fils d’Amadathe; car, pour ce qu’il a fait, il a été pendu avec toute sa famille devant les portes de Suse; Dieu lui-même, le maître de toutes choses, l’a promptement rétribué selon son mérite. Que la présente copie de lettre soit affichée en tout lieu, assurant aux Juifs la liberté de suivre leurs lois et d’user de leurs richesses; qu’au temps marqué pour leur affliction, le treize du douzième mois, du mois d’adar, ils puissent se défendre eux-mêmes contre ceux qui les attaqueraient. Car Dieu, maître de toutes choses, a changé en un jour de joie le jour où devait périr la race qu’il a choisie; et vous-mêmes, vous le rangerez parmi vos fêtes solennelles, et vous le célèbrerez par des festins universels; afin que, dès maintenant et à l’avenir, ce soit un jour de délivrance tant pour nous que pour les amis des Perses, et que, pour ceux qui conspirent contre nous, ce jour soit un mémorial de destruction. Toute ville ou province qui désobéira aux présentes prescriptions, ressentira ma colère, et périra par le fer et la flamme; il ne suffira pas qu’elle devienne inaccessible aux hommes, les bêtes fauves et les oiseaux la haïront à jamais. Et que l’on affiche cette copie en des places apparentes dans tout le royaume, et que, le jour indiqué, les Juifs se tiennent prêts à combattre leurs ennemis.","Voici la copie de la lettre: Le grand roi Artaxerxès aux satrapes des cent vingt-sept provinces, de l’Inde à l’Éthiopie, aux gouverneurs des districts, et aux hommes dévoués à mon service, salut. Il arrive que plusieurs, après avoir été souvent honorés des bienfaits de la bonté, ambitionnent plus encore; non-seulement ils cherchent à maltraiter nos sujets, mais, incapables de modérer leur orgueil, ils méditent de mauvais desseins contre leurs bienfaiteurs; non-seulement ils veulent abolir la gratitude parmi les hommes, mais, exaltés par la vaine jactance de gens sans vertu, ils pensent se soustraire au jugement, fatal aux méchants, du Dieu qui voit toutes choses. Maintes fois la flatterie a rendu complices du crime de verser le sang innocent, et enveloppé de maux intolérables plusieurs de ceux qui sont investis de l’autorité, à qui est confié le maniement des affaires de leurs amis; certains hommes ayant trompé, par le faux raisonnement de la malice, la bienveillance sincère des puissants. Cela se peut voir moins par les plus anciennes histoires, que nous nous transmettons, qu’en examinant, sous nos pieds, les choses accomplies d’une manière criminelle par la pestilence d’hommes indignement revêtus du pouvoir; et il est de notre devoir, en vue de l’avenir, de préserver de trouble le royaume, et de donner la paix à tous les hommes, en usant de changements utiles, en jugeant, avec l’à-propos le plus équitable, les choses qui surviennent sous nos yeux. Aman, fils d’Amadathe, Macédonien en réalité, étranger au sang des Perses, bien éloigné de notre bonté naturelle, amicalement accueilli par nous, eut de notre amour, que nous portons à tous les hommes, une telle part que nous l’appelions notre père, que nous le faisions adorer par tous, et que nous lui avions donné la seconde place du royaume. Mais, il ne put maîtriser son orgueil, et il entreprit de nous ôter la vie et le pouvoir. D’abord, il nous demanda de perdre notre sauveur Mardochée, notre bienfaiteur en toute circonstance, et la reine Esther, notre irréprochable compagne, et tout leur peuple; et il me surprit par un tissu d’accusations calomnieuses. Et il espérait par ses artifices dépeupler nos provinces, et faire passer aux Macédoniens l’empire des Perses. Ce triple scélérat nous avait donc trahis au point de nous décider à exterminer les Juifs, quand nous avons reconnu que, loin d’être portés à mal faire, ils obéissaient aux lois les plus justes, qu’ils étaient les fils du Dieu vivant, très-grand et très-haut, qui nous a dirigés nous et nos ancêtres pour mettre notre royaume en la situation la plus florissante. En conséquence, vous agirez bien en n’exécutant pas l’édit que vous a envoyé Aman, fils d’Amadathe; car, pour ce qu’il a fait, il a été pendu avec toute sa famille devant les portes de Suse; Dieu lui-même, le maître de toutes choses, l’a promptement rétribué selon son mérite. Que la présente copie de lettre soit affichée en tout lieu, assurant aux Juifs la liberté de suivre leurs lois et d’user de leurs richesses; qu’au temps marqué pour leur affliction, le treize du douzième mois, du mois d’adar, ils puissent se défendre eux-mêmes contre ceux qui les attaqueraient. Car Dieu, maître de toutes choses, a changé en un jour de joie le jour où devait périr la race qu’il a choisie; et vous-mêmes, vous le rangerez parmi vos fêtes solennelles, et vous le célèbrerez par des festins universels; afin que, dès maintenant et à l’avenir, ce soit un jour de délivrance tant pour nous que pour les amis des Perses, et que, pour ceux qui conspirent contre nous, ce jour soit un mémorial de destruction. Toute ville ou province qui désobéira aux présentes prescriptions, ressentira ma colère, et périra par le fer et la flamme; il ne suffira pas qu’elle devienne inaccessible aux hommes, les bêtes fauves et les oiseaux la haïront à jamais. Et que l’on affiche cette copie en des places apparentes dans tout le royaume, et que, le jour indiqué, les Juifs se tiennent prêts à combattre leurs ennemis."],[8,14,"Les courriers se hâtèrent de partir pour porter les ordres du roi, et l’édit fut affiché dans Suse.","Les courriers se hâtèrent de partir pour porter les ordres du roi, et l’édit fut affiché dans Suse."],[8,15,"Et Mardochée sortit, revêtu d’une robe royale, ayant une couronne d’or et un diadème pourpre du lin le plus fin; et le peuple de Suse, l’ayant vu, se réjouit.","Et Mardochée sortit, revêtu d’une robe royale, ayant une couronne d’or et un diadème pourpre du lin le plus fin; et le peuple de Suse, l’ayant vu, se réjouit."],[8,16,"Et, pour les Juifs, il y eut lumière et allégresse","Et, pour les Juifs, il y eut lumière et allégresse"],[8,17,"En toute ville et province où l’on afficha l’édit et où il fut proclamé, ils firent des réjouissances et se donnèrent des repas. Et, parmi les gentils, beaucoup se circoncirent et judaïsèrent par crainte des Juifs.","En toute ville et province où l’on afficha l’édit et où il fut proclamé, ils firent des réjouissances et se donnèrent des repas. Et, parmi les gentils, beaucoup se circoncirent et judaïsèrent par crainte des Juifs."],[9,1,"Le treize du douzième mois, du mois d’adar, l’édit du roi fut exécuté.","Le treize du douzième mois, du mois d’adar, l’édit du roi fut exécuté."],[9,2,"Ce jour-là, les ennemis des Juifs périrent, et nul ne se défendit à cause de la crainte qu’ils avaient d’eux.","Ce jour-là, les ennemis des Juifs périrent, et nul ne se défendit à cause de la crainte qu’ils avaient d’eux."],[9,3,"Et les officiers des satrapes, et les rois, et les scribes royaux, honorèrent les Juifs; car ils redoutaient Mardochée.","Et les officiers des satrapes, et les rois, et les scribes royaux, honorèrent les Juifs; car ils redoutaient Mardochée."],[9,4,"Et l’édit du roi en vint à être loué dans tout le royaume.","Et l’édit du roi en vint à être loué dans tout le royaume."],[9,5,"Et à Suse les Juifs tuèrent cinq cents hommes,","Et à Suse les Juifs tuèrent cinq cents hommes,"],[9,6,"Pharsannès, et Delphon, et Phasgas,","Pharsannès, et Delphon, et Phasgas,"],[9,7,"Et Phardathas, et Barcas, et Sarbacas,","Et Phardathas, et Barcas, et Sarbacas,"],[9,8,"Et Marmarinas, et Ruphès, et Arsès, et Zabuthis.","Et Marmarinas, et Ruphès, et Arsès, et Zabuthis."],[9,9,"Et ils enlevèrent les dix fils d’Aman, fils d’Amadathe le Bugéen, l’ennemi des Juifs, et ils pillèrent leurs maisons","Et ils enlevèrent les dix fils d’Aman, fils d’Amadathe le Bugéen, l’ennemi des Juifs, et ils pillèrent leurs maisons"],[9,10,"Ce même jour-là. Et on remit au roi le dénombrement de ceux qui, à Suse, avaient péri.","Ce même jour-là. Et on remit au roi le dénombrement de ceux qui, à Suse, avaient péri."],[9,11,"Et le roi dit à Esther: Les Juifs ont tué cinq cents hommes à Suse; combien penses-tu qu’ils en aient exterminé dans les provinces? Que demandes-tu encore, que te faut-il?","Et le roi dit à Esther: Les Juifs ont tué cinq cents hommes à Suse; combien penses-tu qu’ils en aient exterminé dans les provinces? Que demandes-tu encore, que te faut-il?"],[9,12,"Et Esther répondit: Qu’il soit permis aux Juifs d’en user de même demain jusqu’à pendre les dix fils d’Aman. 13. Et le roi le voulut ainsi; et les corps des fils d’Aman furent livrés aux Juifs de la ville pour être pendus.","Et Esther répondit: Qu’il soit permis aux Juifs d’en user de même demain jusqu’à pendre les dix fils d’Aman. 13. Et le roi le voulut ainsi; et les corps des fils d’Aman furent livrés aux Juifs de la ville pour être pendus."],[9,14,"Et les Juifs de Suse se réunirent le quatorze d’Adar, et ils tuèrent trois cents hommes, et ils ne prirent rien de leurs dépouilles.","Et les Juifs de Suse se réunirent le quatorze d’Adar, et ils tuèrent trois cents hommes, et ils ne prirent rien de leurs dépouilles."],[9,15,"Les autres Juifs du royaume se réunirent et se prêtèrent un mutuel secours, et ils se débarrassèrent de leurs ennemis; car ils en tuèrent quinze mille, le treize d’adar, et ils ne prirent rien.","Les autres Juifs du royaume se réunirent et se prêtèrent un mutuel secours, et ils se débarrassèrent de leurs ennemis; car ils en tuèrent quinze mille, le treize d’adar, et ils ne prirent rien."],[9,16,"Et ils restèrent en repos le quatorze du même mois, car ils fêtèrent ce jour de repos par de grandes réjouissances.","Et ils restèrent en repos le quatorze du même mois, car ils fêtèrent ce jour de repos par de grandes réjouissances."],[9,17,"Mais les Juifs de Suse ne cessèrent le massacre qu’à fin du quatorze; et ils passèrent le quinze à se réjouir.","Mais les Juifs de Suse ne cessèrent le massacre qu’à fin du quatorze; et ils passèrent le quinze à se réjouir."],[9,18,"A cause de cela, les Juifs dispersés dans toutes les provinces ont coutume de fêter le quatorze d’adar, et chacun envoie des parts à son voisin.","A cause de cela, les Juifs dispersés dans toutes les provinces ont coutume de fêter le quatorze d’adar, et chacun envoie des parts à son voisin."],[9,19,"Mardochée écrivit ces choses en un livre, et il envoya dire à tous les Juifs qui demeuraient dans le royaume dArtaxerxès, soit près, soit loin,","Mardochée écrivit ces choses en un livre, et il envoya dire à tous les Juifs qui demeuraient dans le royaume dArtaxerxès, soit près, soit loin,"],[9,20,"D’instituer ces jours comme des jours heureux, et de fêter le treize et le quatorze d’adar.","D’instituer ces jours comme des jours heureux, et de fêter le treize et le quatorze d’adar."],[9,21,"Car, en ces deux journées, les Juifs avaient été délivrés de leurs ennemis; et le mois, qui est adar, durant lequel ils avaient passé du deuil à la joie, et des douleurs à un jour heureux, fut consacré tout entier aux jours heureux des noces et des réjouissances; et chacun envoya des parts à ses amis et aux indigents.","Car, en ces deux journées, les Juifs avaient été délivrés de leurs ennemis; et le mois, qui est adar, durant lequel ils avaient passé du deuil à la joie, et des douleurs à un jour heureux, fut consacré tout entier aux jours heureux des noces et des réjouissances; et chacun envoya des parts à ses amis et aux indigents."],[9,22,"Et les Juifs se sont conformés depuis à ce qu’avait écrit Mardochée, leur faisant savoir:","Et les Juifs se sont conformés depuis à ce qu’avait écrit Mardochée, leur faisant savoir:"],[9,23,"Comme Aman, fils d’Amadathe le Macédonien, était devenu leur ennemi; comme il avait fait un édit, et agité les sorts pour les exterminer;","Comme Aman, fils d’Amadathe le Macédonien, était devenu leur ennemi; comme il avait fait un édit, et agité les sorts pour les exterminer;"],[9,24,"Comme il était entré chez le roi, lui disant de faire pendre Mardochée; et comment tous les maux qu’il avait essayé de faire tomber sur les Juifs étaient tombés sur luimême, qui avait été pendu ainsi que ses fils.","Comme il était entré chez le roi, lui disant de faire pendre Mardochée; et comment tous les maux qu’il avait essayé de faire tomber sur les Juifs étaient tombés sur luimême, qui avait été pendu ainsi que ses fils."],[9,25,"À cause de cela, ces jours furent appelés Phrurées, à cause des sorts (car, dans leur dialecte, les sorts se traduisent par Phrurées); à cause des paroles de ce livre de Mardochée, et à cause de ce qu’ils avaient souffert à ce sujet et de ce qui leur était advenu.","À cause de cela, ces jours furent appelés Phrurées, à cause des sorts (car, dans leur dialecte, les sorts se traduisent par Phrurées); à cause des paroles de ce livre de Mardochée, et à cause de ce qu’ils avaient souffert à ce sujet et de ce qui leur était advenu."],[9,27,"Et il régla les choses ainsi. Et les Juifs adoptèrent l’usage de ces fêtes pour eux et pour leur race, et pour ceux qui se joignirent à eux pour les observer, et ils ne feront jamais autrement; et ces jours sont un mémorial gardé de générations en générations en chaque ville, chaque famille, chaque province.","Et il régla les choses ainsi. Et les Juifs adoptèrent l’usage de ces fêtes pour eux et pour leur race, et pour ceux qui se joignirent à eux pour les observer, et ils ne feront jamais autrement; et ces jours sont un mémorial gardé de générations en générations en chaque ville, chaque famille, chaque province."],[9,28,"Et ces jours des Phrurées, disent-ils, seront gardés en tout temps, et le mémorial ne manquera à aucune génération.","Et ces jours des Phrurées, disent-ils, seront gardés en tout temps, et le mémorial ne manquera à aucune génération."],[9,29,"Et la reine Esther, fille d’Aminadab, et le Juif Mardochée, écrivirent tout ce qu’ils avaient fait pour confirmer la lettre concernant les Phrurées.","Et la reine Esther, fille d’Aminadab, et le Juif Mardochée, écrivirent tout ce qu’ils avaient fait pour confirmer la lettre concernant les Phrurées."],[9,30,"Et Mardochée et la reine Esther instituèrent pour eux-mêmes et les leurs, ces choses; et, en ce temps, ils établirent de leur propre autorité cette loi concernant leur délivrance.","Et Mardochée et la reine Esther instituèrent pour eux-mêmes et les leurs, ces choses; et, en ce temps, ils établirent de leur propre autorité cette loi concernant leur délivrance."],[9,32,"Et Esther fit cela par un commandement pour toujours, et elle l’écrivit en un mémoire.","Et Esther fit cela par un commandement pour toujours, et elle l’écrivit en un mémoire."],[10,1,"Et le roi écrivit ce qui concernait l’empire de la terre et de la mer;","Et le roi écrivit ce qui concernait l’empire de la terre et de la mer;"],[10,2,"Et sa puissance, et sa valeur, et ses richesses, et sa gloire, sont décrites dans le livre des rois des Perses et des Mèdes, comme un mémorial.","Et sa puissance, et sa valeur, et ses richesses, et sa gloire, sont décrites dans le livre des rois des Perses et des Mèdes, comme un mémorial."],[10,3,"Et Mardochée fut le lieutenant du roi Artaxerxès, et il fut grand dans le royaume, et il fut glorifié par les Juifs; et, aimé de tous, il exposa la suite de l’événement à tout son peuple.","Et Mardochée fut le lieutenant du roi Artaxerxès, et il fut grand dans le royaume, et il fut glorifié par les Juifs; et, aimé de tous, il exposa la suite de l’événement à tout son peuple."],[10,4,"Et Mardochée dit: Tout cela vient de Dieu;","Et Mardochée dit: Tout cela vient de Dieu;"],[10,5,"Car je me souviens de la vision que j’ai eue au sujet de ces événements, et rien de ce qu’elle annonçait n’a manqué d’advenir.","Car je me souviens de la vision que j’ai eue au sujet de ces événements, et rien de ce qu’elle annonçait n’a manqué d’advenir."],[10,6,"La petite fontaine qui devint fleuve et qui fut lumière, soleil et onde abondante: c’est Esther, c’est elle qui est le fleuve; le roi l’a épousée et il l’a couronnée reine.","La petite fontaine qui devint fleuve et qui fut lumière, soleil et onde abondante: c’est Esther, c’est elle qui est le fleuve; le roi l’a épousée et il l’a couronnée reine."],[10,7,"Les deux dragons, c’est moi et Aman.","Les deux dragons, c’est moi et Aman."],[10,8,"Les nations, c’est la foule qui s’assembla pour effacer le nom des Juifs.","Les nations, c’est la foule qui s’assembla pour effacer le nom des Juifs."],[10,9,"Et notre nation, c’est Israël qui invoqua Dieu et fut sauvé. Et le Seigneur a protégé son peuple, et il nous a délivrés de tous ces maux, et il a fait éclater des prodiges, et il a montré des signes, ce qui n’est jamais arrivé chez les nations.","Et notre nation, c’est Israël qui invoqua Dieu et fut sauvé. Et le Seigneur a protégé son peuple, et il nous a délivrés de tous ces maux, et il a fait éclater des prodiges, et il a montré des signes, ce qui n’est jamais arrivé chez les nations."],[10,10,"A cause de cela, il a fait deux sorts: l’un pour son peuple, l’autre pour les autres nations.","A cause de cela, il a fait deux sorts: l’un pour son peuple, l’autre pour les autres nations."],[10,11,"Et les deux sorts ont comparu devant Dieu au moment et à l’heure, le jour où il devait juger toutes les nations.","Et les deux sorts ont comparu devant Dieu au moment et à l’heure, le jour où il devait juger toutes les nations."],[10,12,"Et Dieu s’est souvenu de son peuple, et il a vengé son héritage.","Et Dieu s’est souvenu de son peuple, et il a vengé son héritage."],[10,13,"Et les jours d’adar, le treize et le quatorze, seront célébrés devant Dieu par tout le peuple à jamais, par des réjouissances et des fêtes, en tout Israël.","Et les jours d’adar, le treize et le quatorze, seront célébrés devant Dieu par tout le peuple à jamais, par des réjouissances et des fêtes, en tout Israël."],[11,1,"La quatrième année du règne de Ptolémée et de Cléopâtré, Dosithée, qui dit être prêtre et lévite, accompagné de Ptolémée, son fils, apporta cette lettre sur les Phruréés; et, tous les deux, déclarèrent qu’elle avait été traduite à Jérusalem par Lysimaque, fils de Ptolémée.","La quatrième année du règne de Ptolémée et de Cléopâtré, Dosithée, qui dit être prêtre et lévite, accompagné de Ptolémée, son fils, apporta cette lettre sur les Phruréés; et, tous les deux, déclarèrent qu’elle avait été traduite à Jérusalem par Lysimaque, fils de Ptolémée."]],"ell-vamvas1850":[[1,1,"Και εν ταις ημέραις του Ασσουήρου, ούτος είναι ο Ασσουήρης, ο βασιλεύων από της Ινδίας έως της Αιθιοπίας, επί εκατόν εικοσιεπτά επαρχιών·","Kai en tais ēmérais tou Assouḗrou, oútos eínai o Assouḗrēs, o basileúōn apó tēs Indías éōs tēs Aithiopías, epí ekatón eikosieptá eparchiṓn:"],[1,2,"εν εκείναις ταις ημέραις, ότε ο βασιλεύς Ασσουήρης εκάθησεν επί τον θρόνον της βασιλείας αυτού, εν Σούσοις τη βασιλευούση,","en ekeínais tais ēmérais, óte o basileús Assouḗrēs ekáthēsen epí ton thrónon tēs basileías autoú, en Soúsois tē basileuoúsē,"],[1,3,"εν τω τρίτω έτει της βασιλείας αυτού, έκαμε συμπόσιον εις πάντας τους άρχοντας αυτού και τους δούλους αυτού· και ήτο ενώπιον αυτού η δύναμις της Περσίας και της Μηδίας, οι ευγενείς και οι άρχοντες των επαρχιών,","en tō trítō étei tēs basileías autoú, ékame sympósion eis pántas tous árchontas autoú kai tous doúlous autoú: kai ḗto enṓpion autoú ē dýnamis tēs Persías kai tēs Mēdías, oi eugeneís kai oi árchontes tōn eparchiṓn,"],[1,4,"ότε εδείκνυε τα πλούτη της ενδόξου βασιλείας αυτού, και την λαμπρότητα της εξόχου μεγαλειότητος αυτού, ημέρας πολλάς, εκατόν ογδοήκοντα ημέρας.","óte edeíknye ta ploútē tēs endóxou basileías autoú, kai tēn lamprótēta tēs exóchou megaleiótētos autoú, ēméras pollás, ekatón ogdoḗkonta ēméras."],[1,5,"Και αφού επληρώθησαν αι ημέραι αύται, έκαμεν ο βασιλεύς συμπόσιον εις πάντα τον λαόν τον ευρεθέντα εν Σούσοις τη βασιλευούση, από μεγάλου έως μικρού, επτά ημέρας, εν τη αυλή του κήπου του βασιλικού παλατίου·","Kai aphoú eplērṓthēsan ai ēmérai aútai, ékamen o basileús sympósion eis pánta ton laón ton eurethénta en Soúsois tē basileuoúsē, apó megálou éōs mikroú, eptá ēméras, en tē aulḗ tou kḗpou tou basilikoú palatíou:"],[1,6,"όπου ήσαν παραπετάσματα λευκά, πράσινα και κυανά, κρεμάμενα διά σχοινίων βυσσίνων και πορφυρών διά κρίκων αργυρών εις στύλους εκ μαρμάρου· κλίναι χρυσαί και αργυραί ήσαν επί λιθόστρωτον εκ πορφυρίτου και κυανού και λευκού και μέλανος μαρμάρου.","ópou ḗsan parapetásmata leuká, prásina kai kyaná, kremámena diá schoiníōn byssínōn kai porphyrṓn diá kríkōn argyrṓn eis stýlous ek marmárou: klínai chrysaí kai argyraí ḗsan epí lithóstrōton ek porphyrítou kai kyanoú kai leukoú kai mélanos marmárou."],[1,7,"Εκέρνων δε εις σκεύη χρυσά, ηλλάσσοντο δε τα σκεύη διαδοχικώς, και ήτο οίνος βασιλικός εν αφθονία, κατά την μεγαλοπρέπειαν του βασιλέως.","Ekérnōn de eis skeúē chrysá, ēllássonto de ta skeúē diadochikṓs, kai ḗto oínos basilikós en aphthonía, katá tēn megaloprépeian tou basiléōs."],[1,8,"Η δε πόσις ήτο κεκανονισμένη· ουδείς εβίαζε· διότι ο βασιλεύς προσέταξεν ούτως εις πάντας τους οικονόμους του παλατίου αυτού, να κάμνωσι κατά την ευχαρίστησιν εκάστου.","Ē de pósis ḗto kekanonisménē: oudeís ebíaze: dióti o basileús prosétaxen oútōs eis pántas tous oikonómous tou palatíou autoú, na kámnōsi katá tēn eucharístēsin ekástou."],[1,9,"Και Αστίν έτι η βασίλισσα έκαμεν εις τας γυναίκας συμπόσιον εν τω οίκω τω βασιλικώ του βασιλέως Ασσουήρου.","Kai Astín éti ē basílissa ékamen eis tas gynaíkas sympósion en tō oíkō tō basilikṓ tou basiléōs Assouḗrou."],[1,10,"Εν τη εβδόμη δε ημέρα, ότε η καρδία του βασιλέως ήτο εύθυμος εκ του οίνου, προσέταξε τον Μεουμάν, τον Βηζαθά, τον Αρβωνά, τον Βηγθά και Αβαγθά, τον Ζεθάρ και τον Χαρκάς, τους επτά ευνούχους τους υπηρετούντας ενώπιον του βασιλέως Ασσουήρου,","En tē ebdómē de ēméra, óte ē kardía tou basiléōs ḗto eúthymos ek tou oínou, prosétaxe ton Meoumán, ton Bēzathá, ton Arbōná, ton Bēgthá kai Abagthá, ton Zethár kai ton Charkás, tous eptá eunoúchous tous ypēretoúntas enṓpion tou basiléōs Assouḗrou,"],[1,11,"να φέρωσι την Αστίν την βασίλισσαν ενώπιον του βασιλέως, μετά του βασιλικού διαδήματος, διά να δείξη το κάλλος αυτής εις τους λαούς και εις τους άρχοντας· διότι ήτο ώραία την όψιν.","na phérōsi tēn Astín tēn basílissan enṓpion tou basiléōs, metá tou basilikoú diadḗmatos, diá na deíxē to kállos autḗs eis tous laoús kai eis tous árchontas: dióti ḗto ṓraía tēn ópsin."],[1,12,"Η βασίλισσα όμως Αστίν ηρνήθη να έλθη κατά την προσταγήν του βασιλέως, την διά των ευνούχων. Όθεν ο βασιλεύς εθυμώθη σφόδρα, και η οργή αυτού εξήφθη εν εαυτώ.","Ē basílissa ómōs Astín ērnḗthē na élthē katá tēn prostagḗn tou basiléōs, tēn diá tōn eunoúchōn. Óthen o basileús ethymṓthē sphódra, kai ē orgḗ autoú exḗphthē en eautṓ."],[1,13,"Τότε είπεν ο βασιλεύς προς τους σοφούς, τους γνωρίζοντας τους καιρούς· διότι τοιαύτη ήτο η συνήθεια του βασιλέως προς πάντας τους γνωρίζοντας τον νόμον και την κρίσιν·","Tóte eípen o basileús pros tous sophoús, tous gnōrízontas tous kairoús: dióti toiaútē ḗto ē synḗtheia tou basiléōs pros pántas tous gnōrízontas ton nómon kai tēn krísin:"],[1,14,"πλησίον δε αυτού ήτο ο Καρσένα, ο Σεθάρ, ο Αδμαθά, ο Θαρσείς, ο Μερές, ο Μαρσενά και ο Μεμουκάν, οι επτά άρχοντες της Περσίας και της Μηδίας, οίτινες έβλεπον το πρόσωπον του βασιλέως και είχον την προεδρίαν εν τω βασιλείω·","plēsíon de autoú ḗto o Karséna, o Sethár, o Admathá, o Tharseís, o Merés, o Marsená kai o Memoukán, oi eptá árchontes tēs Persías kai tēs Mēdías, oítines éblepon to prósōpon tou basiléōs kai eíchon tēn proedrían en tō basileíō:"],[1,15,"Τι αρμόζει να κάμωμεν προς την βασίλισσαν Αστίν κατά τον νόμον, διότι δεν εξετέλεσε την διά των ευνούχων προσταγήν του βασιλέως Ασσουήρου;","Ti armózei na kámōmen pros tēn basílissan Astín katá ton nómon, dióti den exetélese tēn diá tōn eunoúchōn prostagḗn tou basiléōs Assouḗrou?"],[1,16,"Και απεκρίθη ο Μεμουκάν ενώπιον του βασιλέως και των αρχόντων, Η βασίλισσα Αστίν δεν ημάρτησε μόνον εις τον βασιλέα, αλλά και εις πάντας τους άρχοντας και εις πάντας τους λαούς τους εν πάσαις ταις επαρχίαις του βασιλέως Ασσουήρου·","Kai apekríthē o Memoukán enṓpion tou basiléōs kai tōn archóntōn, Ē basílissa Astín den ēmártēse mónon eis ton basiléa, allá kai eis pántas tous árchontas kai eis pántas tous laoús tous en pásais tais eparchíais tou basiléōs Assouḗrou:"],[1,17,"διότι η πράξις της βασιλίσσης θέλει διαδοθή εις πάσας τας γυναίκας, ώστε θέλουσι καταφρονεί τους άνδρας αυτών έμπροσθεν των οφθαλμών αυτών, όταν διαφημισθή ότι ο βασιλεύς Ασσουήρης προσέταξε την βασίλισσαν Αστίν να φερθή ενώπιον αυτού, και δεν ήλθε·","dióti ē práxis tēs basilíssēs thélei diadothḗ eis pásas tas gynaíkas, ṓste thélousi kataphroneí tous ándras autṓn émprosthen tōn ophthalmṓn autṓn, ótan diaphēmisthḗ óti o basileús Assouḗrēs prosétaxe tēn basílissan Astín na pherthḗ enṓpion autoú, kai den ḗlthe:"],[1,18,"και την σήμερον αι δέσποιναι της Περσίας και της Μηδίας, όσαι ήκουσαν περί της πράξεως της βασιλίσσης, θέλουσι λαλήσει ούτω προς πάντας τους άρχοντας του βασιλέως· εντεύθεν μεγάλη περιφρόνησις και οργή·","kai tēn sḗmeron ai déspoinai tēs Persías kai tēs Mēdías, ósai ḗkousan perí tēs práxeōs tēs basilíssēs, thélousi lalḗsei oútō pros pántas tous árchontas tou basiléōs: enteúthen megálē periphrónēsis kai orgḗ:"],[1,19,"εάν λοιπόν ήναι αρεστόν εις τον βασιλέα, ας εξέλθη παρ' αυτού βασιλική διαταγή, και ας γραφή μεταξύ των νόμων των Περσών και των Μήδων, διά να ήναι αμετάθετος, να μη έλθη πλέον η Αστίν ενώπιον του βασιλέως Ασσουήρου· και ας δώση ο βασιλεύς την βασιλικήν αυτής αξίαν εις άλλην καλητέραν αυτής·","eán loipón ḗnai arestón eis ton basiléa, as exélthē par' autoú basilikḗ diatagḗ, kai as graphḗ metaxý tōn nómōn tōn Persṓn kai tōn Mḗdōn, diá na ḗnai ametáthetos, na mē élthē pléon ē Astín enṓpion tou basiléōs Assouḗrou: kai as dṓsē o basileús tēn basilikḗn autḗs axían eis állēn kalētéran autḗs:"],[1,20,"και όταν το πρόσταγμα του βασιλέως, το οποίον θέλει κάμει, δημοσιευθή διά παντός του βασιλείου αυτού, διότι είναι μέγα, πάσαι αι γυναίκες θέλουσιν αποδίδει τιμήν εις τους άνδρας αυτών, από μεγάλου έως μικρού.","kai ótan to próstagma tou basiléōs, to opoíon thélei kámei, dēmosieuthḗ diá pantós tou basileíou autoú, dióti eínai méga, pásai ai gynaíkes thélousin apodídei timḗn eis tous ándras autṓn, apó megálou éōs mikroú."],[1,21,"Και ο λόγος ήρεσεν εις τον βασιλέα και εις τους άρχοντας· και έκαμεν ο βασιλεύς κατά τον λόγον του Μεμουκάν·","Kai o lógos ḗresen eis ton basiléa kai eis tous árchontas: kai ékamen o basileús katá ton lógon tou Memoukán:"],[1,22,"και έστειλε γράμματα εις πάσας τας επαρχίας του βασιλέως, εις εκάστην επαρχίαν κατά το γράφειν αυτής, και προς έκαστον λαόν κατά την γλώσσαν αυτού, να ήναι πας ανήρ κύριος εν τη οικία αυτού, και να λαλή κατά την γλώσσαν του λαού αυτού.","kai ésteile grámmata eis pásas tas eparchías tou basiléōs, eis ekástēn eparchían katá to gráphein autḗs, kai pros ékaston laón katá tēn glṓssan autoú, na ḗnai pas anḗr kýrios en tē oikía autoú, kai na lalḗ katá tēn glṓssan tou laoú autoú."],[2,1,"Μετά τα πράγματα ταύτα, αφού κατεπραΰνθη ο θυμός του βασιλέως Ασσουήρου, ενεθυμήθη την Αστίν, και τι είχε κάμει αυτή και τι είχεν αποφασισθή εναντίον αυτής.","Metá ta prágmata taúta, aphoú katepraǘnthē o thymós tou basiléōs Assouḗrou, enethymḗthē tēn Astín, kai ti eíche kámei autḗ kai ti eíchen apophasisthḗ enantíon autḗs."],[2,2,"Και είπον οι δούλοι του βασιλέως, οι υπηρετούντες αυτόν, Ας ζητηθώσι διά τον βασιλέα νέαι παρθένοι, ώραίαι την όψιν·","Kai eípon oi doúloi tou basiléōs, oi ypēretoúntes autón, As zētēthṓsi diá ton basiléa néai parthénoi, ṓraíai tēn ópsin:"],[2,3,"και ας διορίση ο βασιλεύς εφόρους εν πάσαις ταις επαρχίαις του βασιλείου αυτού, και να συνάξωσιν εις τα Σούσα την βασιλεύουσαν πάσας τας νέας παρθένους τας ώραίας την όψιν εις τον γυναικώνα, υπό την τήρησιν του Ήγαϊ ευνούχου του βασιλέως, του φύλακος των γυναικών· και ας δοθώσιν εις αυτάς τα προς καθαρισμόν αυτών·","kai as diorísē o basileús ephórous en pásais tais eparchíais tou basileíou autoú, kai na synáxōsin eis ta Soúsa tēn basileúousan pásas tas néas parthénous tas ṓraías tēn ópsin eis ton gynaikṓna, ypó tēn tḗrēsin tou Ḗgaï eunoúchou tou basiléōs, tou phýlakos tōn gynaikṓn: kai as dothṓsin eis autás ta pros katharismón autṓn:"],[2,4,"και η νέα, ήτις αρέση εις τον βασιλέα, ας ήναι βασίλισσα αντί της Αστίν. Και το πράγμα ήρεσεν εις τον βασιλέα, και έκαμεν ούτω.","kai ē néa, ḗtis arésē eis ton basiléa, as ḗnai basílissa antí tēs Astín. Kai to prágma ḗresen eis ton basiléa, kai ékamen oútō."],[2,5,"Ήτο δε εν Σούσοις τη βασιλευούση άνθρωπός τις Ιουδαίος, ονομαζόμενος Μαροδοχαίος, υιός του Ιαείρ, υιού του Σιμεΐ, υιού του Κείς, Βενιαμίτης·","Ḗto de en Soúsois tē basileuoúsē ánthrōpós tis Ioudaíos, onomazómenos Marodochaíos, yiós tou Iaeír, yioú tou Simeḯ, yioú tou Keís, Beniamítēs:"],[2,6,"όστις είχε μετοικισθή από Ιερουσαλήμ μετά των αιχμαλώτων, οίτινες μετωκίσθησαν μετά του Ιεχονία βασιλέως του Ιούδα, τους οποίους μετώκισε Ναβουχοδονόσορ ο βασιλεύς της Βαβυλώνος.","óstis eíche metoikisthḗ apó Ierousalḗm metá tōn aichmalṓtōn, oítines metōkísthēsan metá tou Iechonía basiléōs tou Ioúda, tous opoíous metṓkise Nabouchodonósor o basileús tēs Babylṓnos."],[2,7,"Και ούτος ανέτρεφε την Αδασσά, ήτις είναι η Εσθήρ, την θυγατέρα του θείου αυτού· διότι δεν είχεν ούτε πατέρα ούτε μητέρα· και το κοράσιον ήτο ευειδές και ώραίον· το οποίον ο Μαροδοχαίος, ότε ο πατήρ αυτής και η μήτηρ απέθανον, ανέλαβε διά θυγατέρα αυτού.","Kai oútos anétrephe tēn Adassá, ḗtis eínai ē Esthḗr, tēn thygatéra tou theíou autoú: dióti den eíchen oúte patéra oúte mētéra: kai to korásion ḗto eueidés kai ṓraíon: to opoíon o Marodochaíos, óte o patḗr autḗs kai ē mḗtēr apéthanon, anélabe diá thygatéra autoú."],[2,8,"Ότε δε ηκούσθη το πρόσταγμα του βασιλέως και η διαταγή αυτού, και ότε πολλά κοράσια συνήχθησαν εις τα Σούσα την βασιλεύουσαν υπό την τήρησιν του Ήγαϊ, εφέρθη και η Εσθήρ εις τον οίκον του βασιλέως υπό την τήρησιν του Ήγαϊ, του φύλακος των γυναικών.","Óte de ēkoústhē to próstagma tou basiléōs kai ē diatagḗ autoú, kai óte pollá korásia synḗchthēsan eis ta Soúsa tēn basileúousan ypó tēn tḗrēsin tou Ḗgaï, ephérthē kai ē Esthḗr eis ton oíkon tou basiléōs ypó tēn tḗrēsin tou Ḗgaï, tou phýlakos tōn gynaikṓn."],[2,9,"Και το κοράσιον ήρεσεν εις αυτόν και εύρηκε χάριν ενώπιον αυτού, ώστε έσπευσε να δώση εις αυτήν τα προς καθαρισμόν αυτής και την μερίδα αυτής· έδωκε δε εις αυτήν και τα επτά κοράσια τα διωρισμένα εκ του οίκου του βασιλέως· και μετέφερεν αυτήν και τα κοράσια αυτής εις το καλήτερον μέρος του γυναικώνος.","Kai to korásion ḗresen eis autón kai eúrēke chárin enṓpion autoú, ṓste éspeuse na dṓsē eis autḗn ta pros katharismón autḗs kai tēn merída autḗs: édōke de eis autḗn kai ta eptá korásia ta diōrisména ek tou oíkou tou basiléōs: kai metépheren autḗn kai ta korásia autḗs eis to kalḗteron méros tou gynaikṓnos."],[2,10,"Η Εσθήρ δεν εφανέρωσε τον λαόν αυτής ουδέ την συγγένειαν αυτής· διότι ο Μαροδοχαίος είχε προστάξει εις αυτήν να μη φανερώση.","Ē Esthḗr den ephanérōse ton laón autḗs oudé tēn syngéneian autḗs: dióti o Marodochaíos eíche prostáxei eis autḗn na mē phanerṓsē."],[2,11,"Και καθ' εκάστην ημέραν περιεπάτει ο Μαροδοχαίος έμπροσθεν της αυλής του γυναικώνος, διά να μανθάνη πως είχεν η Εσθήρ και τι έγεινεν εις αυτήν.","Kai kath' ekástēn ēméran periepátei o Marodochaíos émprosthen tēs aulḗs tou gynaikṓnos, diá na manthánē pōs eíchen ē Esthḗr kai ti égeinen eis autḗn."],[2,12,"Ότε δε έφθανεν η σειρά εκάστου κορασίου διά να εισέλθη προς τον βασιλέα Ασσουήρην, αφού ήθελε σταθή δώδεκα μήνας κατά το ήθος των γυναικών, διότι ούτω συνεπληρούντο αι ημέραι του καθαρισμού αυτών, εξ μήνας περιηλείφοντο με έλαιον σμύρνινον, και εξ μήνας με αρώματα και με άλλα καθαριστικά των γυναικών·","Óte de éphthanen ē seirá ekástou korasíou diá na eisélthē pros ton basiléa Assouḗrēn, aphoú ḗthele stathḗ dṓdeka mḗnas katá to ḗthos tōn gynaikṓn, dióti oútō syneplēroúnto ai ēmérai tou katharismoú autṓn, ex mḗnas periēleíphonto me élaion smýrninon, kai ex mḗnas me arṓmata kai me álla katharistiká tōn gynaikṓn:"],[2,13,"και ούτως εισήρχετο το κοράσιον προς τον βασιλέα· παν ό,τι έλεγεν, εδίδετο εις αυτήν, διά να λάβη μεθ' εαυτής εκ του γυναικώνος εις τον οίκον του βασιλέως.","kai oútōs eisḗrcheto to korásion pros ton basiléa: pan ó,ti élegen, edídeto eis autḗn, diá na lábē meth' eautḗs ek tou gynaikṓnos eis ton oíkon tou basiléōs."],[2,14,"Το εσπέρας εισήρχετο και το πρωΐ επέστρεφεν εις τον δεύτερον γυναικώνα, υπό την τήρησιν του Σαασγάζ, ευνούχου του βασιλέως, όστις εφύλαττε τας παλλακίδας· δεν εισήρχετο πλέον εις τον βασιλέα, ειμή εάν ήθελεν αυτήν ο βασιλεύς, και εκαλείτο ονομαστί.","To espéras eisḗrcheto kai to prōḯ epéstrephen eis ton deúteron gynaikṓna, ypó tēn tḗrēsin tou Saasgáz, eunoúchou tou basiléōs, óstis ephýlatte tas pallakídas: den eisḗrcheto pléon eis ton basiléa, eimḗ eán ḗthelen autḗn o basileús, kai ekaleíto onomastí."],[2,15,"Ότε λοιπόν έφθασεν η σειρά διά να εισέλθη προς τον βασιλέα η Εσθήρ, η θυγάτηρ του Αβιχαίλ, θείου του Μαροδοχαίου, την οποίαν έλαβε διά θυγατέρα αυτού, δεν εζήτησεν άλλο παρ' ό,τι διώρισεν ο Ήγαϊ ο ευνούχος του βασιλέως, ο φύλαξ των γυναικών. Και η Εσθήρ εύρισκε χάριν ενώπιον πάντων των βλεπόντων αυτήν.","Óte loipón éphthasen ē seirá diá na eisélthē pros ton basiléa ē Esthḗr, ē thygátēr tou Abichaíl, theíou tou Marodochaíou, tēn opoían élabe diá thygatéra autoú, den ezḗtēsen állo par' ó,ti diṓrisen o Ḗgaï o eunoúchos tou basiléōs, o phýlax tōn gynaikṓn. Kai ē Esthḗr eúriske chárin enṓpion pántōn tōn blepóntōn autḗn."],[2,16,"Η Εσθήρ λοιπόν εφέρθη προς τον βασιλέα Ασσουήρην εις τον βασιλικόν αυτού οίκον, τον δέκατον μήνα, ούτος είναι ο μην Τεβέθ, εν τω εβδόμω έτει της βασιλείας αυτού.","Ē Esthḗr loipón ephérthē pros ton basiléa Assouḗrēn eis ton basilikón autoú oíkon, ton dékaton mḗna, oútos eínai o mēn Tebéth, en tō ebdómō étei tēs basileías autoú."],[2,17,"Και ηγάπησεν ο βασιλεύς την Εσθήρ υπέρ πάσας τας γυναίκας, και εύρηκε χάριν και έλεος ενώπιον αυτού υπέρ πάσας τας παρθένους· και επέθηκε το βασιλικόν διάδημα επί την κεφαλήν αυτής και έκαμεν αυτήν βασίλισσαν αντί της Αστίν.","Kai ēgápēsen o basileús tēn Esthḗr ypér pásas tas gynaíkas, kai eúrēke chárin kai éleos enṓpion autoú ypér pásas tas parthénous: kai epéthēke to basilikón diádēma epí tēn kephalḗn autḗs kai ékamen autḗn basílissan antí tēs Astín."],[2,18,"Τότε έκαμεν ο βασιλεύς συμπόσιον μέγα εις πάντας τους άρχοντας αυτού και τους δούλους αυτού, το συμπόσιον της Εσθήρ· και έκαμεν άφεσιν εις τας επαρχίας και έδωκε δώρα κατά την βασιλικήν μεγαλοπρέπειαν.","Tóte ékamen o basileús sympósion méga eis pántas tous árchontas autoú kai tous doúlous autoú, to sympósion tēs Esthḗr: kai ékamen áphesin eis tas eparchías kai édōke dṓra katá tēn basilikḗn megaloprépeian."],[2,19,"Και ότε αι παρθένοι συνήχθησαν την δευτέραν φοράν, τότε εκάθησεν ο Μαροδοχαίος εν τη βασιλική πύλη.","Kai óte ai parthénoi synḗchthēsan tēn deutéran phorán, tóte ekáthēsen o Marodochaíos en tē basilikḗ pýlē."],[2,20,"Η Εσθήρ δεν εφανέρωσε την συγγένειαν αυτής ούτε τον λαόν αυτής, καθώς προσέταξεν εις αυτήν ο Μαροδοχαίος· διότι η Εσθήρ έκαμνε την προσταγήν του Μαροδοχαίου, καθώς ότε ανετρέφετο πλησίον αυτού.","Ē Esthḗr den ephanérōse tēn syngéneian autḗs oúte ton laón autḗs, kathṓs prosétaxen eis autḗn o Marodochaíos: dióti ē Esthḗr ékamne tēn prostagḗn tou Marodochaíou, kathṓs óte anetrépheto plēsíon autoú."],[2,21,"Εν εκείναις ταις ημέραις, ενώ ο Μαροδοχαίος εκάθητο εν τη βασιλική πύλη, δύο εκ των ευνούχων του βασιλέως, Βιχθάν και Θερές, εκ των φυλαττόντων την είσοδον, ωργίσθησαν και εζήτουν να επιβάλωσι χείρα επί τον βασιλέα Ασσουήρην.","En ekeínais tais ēmérais, enṓ o Marodochaíos ekáthēto en tē basilikḗ pýlē, dýo ek tōn eunoúchōn tou basiléōs, Bichthán kai Therés, ek tōn phylattóntōn tēn eísodon, ōrgísthēsan kai ezḗtoun na epibálōsi cheíra epí ton basiléa Assouḗrēn."],[2,22,"Και το πράγμα έγεινε γνωστόν εις τον Μαροδοχαίον, και ανήγγειλεν αυτό προς Εσθήρ την βασίλισσαν· η δε Εσθήρ είπεν αυτό προς τον βασιλέα εξ ονόματος του Μαροδοχαίου.","Kai to prágma égeine gnōstón eis ton Marodochaíon, kai anḗngeilen autó pros Esthḗr tēn basílissan: ē de Esthḗr eípen autó pros ton basiléa ex onómatos tou Marodochaíou."],[2,23,"Και γενομένης εξετάσεως περί του πράγματος, ευρέθη ούτως· όθεν εκρεμάσθησαν αμφότεροι εις ξύλον· και εγράφη εν τω βιβλίω των χρονικών ενώπιον του βασιλέως.","Kai genoménēs exetáseōs perí tou prágmatos, euréthē oútōs: óthen ekremásthēsan amphóteroi eis xýlon: kai egráphē en tō biblíō tōn chronikṓn enṓpion tou basiléōs."],[3,1,"Μετά τα πράγματα ταύτα εμεγάλυνεν ο βασιλεύς Ασσουήρης τον Αμάν, τον υιόν του Αμμεδαθά του Αγαγίτου, και ύψωσεν αυτόν και έθεσε τον θρόνον αυτού υπεράνω πάντων των αρχόντων των περί αυτόν.","Metá ta prágmata taúta emegálynen o basileús Assouḗrēs ton Amán, ton yión tou Ammedathá tou Agagítou, kai ýpsōsen autón kai éthese ton thrónon autoú yperánō pántōn tōn archóntōn tōn perí autón."],[3,2,"Και πάντες οι δούλοι του βασιλέως, οι εν τη βασιλική πύλη, έκλινον και προσεκύνουν τον Αμάν· διότι ούτω προσέταξεν ο βασιλεύς περί αυτού. Ο Μαροδοχαίος όμως δεν έκλινε και δεν προσεκύνει αυτόν.","Kai pántes oi doúloi tou basiléōs, oi en tē basilikḗ pýlē, éklinon kai prosekýnoun ton Amán: dióti oútō prosétaxen o basileús perí autoú. O Marodochaíos ómōs den ékline kai den prosekýnei autón."],[3,3,"Και είπον οι δούλοι του βασιλέως, οι εν τη βασιλική πύλη, προς τον Μαροδοχαίον, Διά τι συ παραβαίνεις την προσταγήν του βασιλέως;","Kai eípon oi doúloi tou basiléōs, oi en tē basilikḗ pýlē, pros ton Marodochaíon, Diá ti sy parabaíneis tēn prostagḗn tou basiléōs?"],[3,4,"Αφού δε καθ' ημέραν έλεγον προς αυτόν, και εκείνος δεν υπήκουεν εις αυτούς, απήγγειλαν τούτο προς τον Αμάν, διά να ίδωσιν αν οι λόγοι του Μαροδοχαίου ήσαν στερεοί· διότι είχε φανερώσει προς αυτούς ότι ήτο Ιουδαίος.","Aphoú de kath' ēméran élegon pros autón, kai ekeínos den ypḗkouen eis autoús, apḗngeilan toúto pros ton Amán, diá na ídōsin an oi lógoi tou Marodochaíou ḗsan stereoí: dióti eíche phanerṓsei pros autoús óti ḗto Ioudaíos."],[3,5,"Και ότε ο Αμάν είδεν ότι ο Μαροδοχαίος δεν έκλινε και δεν προσεκύνει αυτόν, ενεπλήσθη θυμού ο Αμάν.","Kai óte o Amán eíden óti o Marodochaíos den ékline kai den prosekýnei autón, eneplḗsthē thymoú o Amán."],[3,6,"Και εστοχάσθη ταπεινόν να βάλη χείρα επί μόνον τον Μαροδοχαίον· διότι είχον φανερώσει προς αυτόν τον λαόν του Μαροδοχαίου· όθεν εζήτει ο Αμάν να αφανίση πάντας τους Ιουδαίους τους εν παντί τω βασιλείω του Ασσουήρου, τον λαόν του Μαροδοχαίου.","Kai estochásthē tapeinón na bálē cheíra epí mónon ton Marodochaíon: dióti eíchon phanerṓsei pros autón ton laón tou Marodochaíou: óthen ezḗtei o Amán na aphanísē pántas tous Ioudaíous tous en pantí tō basileíō tou Assouḗrou, ton laón tou Marodochaíou."],[3,7,"Και εν τω πρώτω μηνί, ούτος είναι ο μην Νισάν, εν τω δωδεκάτω έτει του βασιλέως Ασσουήρου, έρριψαν φούρ, ήγουν κλήρον, ενώπιον του Αμάν, από ημέρας εις ημέραν και από μηνός εις μήνα, μέχρι του δωδεκάτου μηνός, ούτος είναι ο μην Αδάρ.","Kai en tō prṓtō mēní, oútos eínai o mēn Nisán, en tō dōdekátō étei tou basiléōs Assouḗrou, érripsan phoúr, ḗgoun klḗron, enṓpion tou Amán, apó ēméras eis ēméran kai apó mēnós eis mḗna, méchri tou dōdekátou mēnós, oútos eínai o mēn Adár."],[3,8,"Και είπεν ο Αμάν προς τον βασιλέα Ασσουήρην, Υπάρχει τις λαός διεσπαρμένος και διακεχωρισμένος μεταξύ των λαών κατά πάσας τας επαρχίας του βασιλείου σου· και οι νόμοι αυτών διάφοροι των νόμων πάντων των λαών, και δεν φυλάττουσι τους νόμους του βασιλέως· όθεν δεν αρμόζει εις τον βασιλέα να υποφέρη αυτούς·","Kai eípen o Amán pros ton basiléa Assouḗrēn, Ypárchei tis laós diesparménos kai diakechōrisménos metaxý tōn laṓn katá pásas tas eparchías tou basileíou sou: kai oi nómoi autṓn diáphoroi tōn nómōn pántōn tōn laṓn, kai den phyláttousi tous nómous tou basiléōs: óthen den armózei eis ton basiléa na ypophérē autoús:"],[3,9,"εάν ήναι αρεστόν εις τον βασιλέα, ας γραφή να εξολοθρευθώσι και εγώ θέλω μετρήσει δέκα χιλιάδας ταλάντων αργυρίου εις τας χείρας των οικονόμων διά να φέρωσιν εις τα θησαυροφυλάκια του βασιλέως.","eán ḗnai arestón eis ton basiléa, as graphḗ na exolothreuthṓsi kai egṓ thélō metrḗsei déka chiliádas talántōn argyríou eis tas cheíras tōn oikonómōn diá na phérōsin eis ta thēsaurophylákia tou basiléōs."],[3,10,"Και εκβαλών ο βασιλεύς το δακτυλίδιον αυτού από της χειρός αυτού, έδωκεν αυτό εις τον Αμάν τον υιόν του Αμμεδαθά του Αγαγίτου, τον εχθρόν των Ιουδαίων,","Kai ekbalṓn o basileús to daktylídion autoú apó tēs cheirós autoú, édōken autó eis ton Amán ton yión tou Ammedathá tou Agagítou, ton echthrón tōn Ioudaíōn,"],[3,11,"Και είπεν ο βασιλεύς προς τον Αμάν· το αργύριον δίδεται εις σε, και ο λαός, διά να κάμης εις αυτόν όπως σοι αρέσκει.","Kai eípen o basileús pros ton Amán: to argýrion dídetai eis se, kai o laós, diá na kámēs eis autón ópōs soi aréskei."],[3,12,"Και προσεκλήθησαν οι γραμματείς του βασιλέως την δεκάτην τρίτην ημέραν του πρώτου μηνός, και εγράφη κατά πάντα όσα προσέταξεν ο Αμάν, προς τους σατράπας του βασιλέως και προς τους διοικητάς τους κατά πάσαν επαρχίαν και προς τους άρχοντας εκάστου λαού πάσης επαρχίας κατά το γράφειν αυτών, και προς έκαστον λαόν κατά την γλώσσαν αυτών· εν ονόματι του βασιλέως Ασσουήρου εγράφη και εσφραγίσθη με το δακτυλίδιον του βασιλέως.","Kai proseklḗthēsan oi grammateís tou basiléōs tēn dekátēn trítēn ēméran tou prṓtou mēnós, kai egráphē katá pánta ósa prosétaxen o Amán, pros tous satrápas tou basiléōs kai pros tous dioikētás tous katá pásan eparchían kai pros tous árchontas ekástou laoú pásēs eparchías katá to gráphein autṓn, kai pros ékaston laón katá tēn glṓssan autṓn: en onómati tou basiléōs Assouḗrou egráphē kai esphragísthē me to daktylídion tou basiléōs."],[3,13,"Και εστάλησαν γράμματα διά ταχυδρόμων εις πάσας τας επαρχίας του βασιλέως, διά να αφανίσωσι, να φονεύσωσι και να εξολοθρεύσωσι πάντας τους Ιουδαίους, νέους και γέροντας, νήπια και γυναίκας, εν μιά ημέρα, την δεκάτην τρίτην του δωδεκάτου μηνός, ούτος είναι ο μην Αδάρ, και να διαρπάσωσι τα υπάρχοντα αυτών.","Kai estálēsan grámmata diá tachydrómōn eis pásas tas eparchías tou basiléōs, diá na aphanísōsi, na phoneúsōsi kai na exolothreúsōsi pántas tous Ioudaíous, néous kai gérontas, nḗpia kai gynaíkas, en miá ēméra, tēn dekátēn trítēn tou dōdekátou mēnós, oútos eínai o mēn Adár, kai na diarpásōsi ta ypárchonta autṓn."],[3,14,"Το αντίγραφον της επιστολής, το προς διάδοσιν του προστάγματος κατά πάσαν επαρχίαν, εδημοσιεύθη προς πάντας τους λαούς, διά να ήναι έτοιμοι εν εκείνη τη ημέρα.","To antígraphon tēs epistolḗs, to pros diádosin tou prostágmatos katá pásan eparchían, edēmosieúthē pros pántas tous laoús, diá na ḗnai étoimoi en ekeínē tē ēméra."],[3,15,"Οι ταχυδρόμοι εξήλθον, σπεύδοντες διά την προσταγήν του βασιλέως, και η διαταγή εξεδόθη εν Σούσοις τη βασιλευούση. Ο δε βασιλεύς και ο Αμάν εκάθησαν να συμποσιάσωσιν· η δε πόλις Σούσα ήτο εν αμηχανία.","Oi tachydrómoi exḗlthon, speúdontes diá tēn prostagḗn tou basiléōs, kai ē diatagḗ exedóthē en Soúsois tē basileuoúsē. O de basileús kai o Amán ekáthēsan na symposiásōsin: ē de pólis Soúsa ḗto en amēchanía."],[4,1,"Και μαθών Μαροδοχαίος άπαν το γινόμενον, διέσχισε τα ιμάτια αυτού και ενεδύθη σάκκον εν σποδώ και εξήλθεν εις το μέσον της πόλεως και εβόα μετά βοής μεγάλης και πικράς·","Kai mathṓn Marodochaíos ápan to ginómenon, diéschise ta imátia autoú kai enedýthē sákkon en spodṓ kai exḗlthen eis to méson tēs póleōs kai ebóa metá boḗs megálēs kai pikrás:"],[4,2,"και ήλθεν έως έμπροσθεν της βασιλικής πύλης· διότι ουδείς ηδύνατο να εισέλθη εις την βασιλικήν πύλην ενδεδυμένος σάκκον.","kai ḗlthen éōs émprosthen tēs basilikḗs pýlēs: dióti oudeís ēdýnato na eisélthē eis tēn basilikḗn pýlēn endedyménos sákkon."],[4,3,"Και κατά πάσαν επαρχίαν, όπου έφθασεν η προσταγή του βασιλέως και το διάταγμα αυτού, ήτο μέγα πένθος μεταξύ των Ιουδαίων, και νηστεία και θρήνος και ολολυγμός· πολλοί εκοίτοντο με σάκκον και σποδόν.","Kai katá pásan eparchían, ópou éphthasen ē prostagḗ tou basiléōs kai to diátagma autoú, ḗto méga pénthos metaxý tōn Ioudaíōn, kai nēsteía kai thrḗnos kai ololygmós: polloí ekoítonto me sákkon kai spodón."],[4,4,"Εισήλθον δε αι θεράπαιναι της Εσθήρ και οι ευνούχοι αυτής, και απήγγειλαν τούτο προς αυτήν. Και εταράχθη σφόδρα η βασίλισσα· και έπεμψεν ιμάτια διά να ενδύσωσι τον Μαροδοχαίον και να εκβάλωσι τον σάκκον αυτού απ' αυτού· και δεν εδέχθη.","Eisḗlthon de ai therápainai tēs Esthḗr kai oi eunoúchoi autḗs, kai apḗngeilan toúto pros autḗn. Kai etaráchthē sphódra ē basílissa: kai épempsen imátia diá na endýsōsi ton Marodochaíon kai na ekbálōsi ton sákkon autoú ap' autoú: kai den edéchthē."],[4,5,"Τότε εκάλεσεν η Εσθήρ τον Αθάχ, εκ των ευνούχων του βασιλέως, τον οποίον είχε διορίσει εις την υπηρεσίαν αυτής, και προσέταξεν εις αυτόν περί του Μαροδοχαίου, διά να μάθη τι τούτο, και διά τι τούτο.","Tóte ekálesen ē Esthḗr ton Athách, ek tōn eunoúchōn tou basiléōs, ton opoíon eíche diorísei eis tēn ypēresían autḗs, kai prosétaxen eis autón perí tou Marodochaíou, diá na máthē ti toúto, kai diá ti toúto."],[4,6,"Και εξήλθεν ο Αθάχ προς τον Μαροδοχαίον εις την πλατείαν της πόλεως, την απέναντι της βασιλικής πύλης.","Kai exḗlthen o Athách pros ton Marodochaíon eis tēn plateían tēs póleōs, tēn apénanti tēs basilikḗs pýlēs."],[4,7,"Και εφανέρωσε προς αυτόν ο Μαροδοχαίος άπαν το γεγονός εις αυτόν, και το ποσόν του αργυρίου το οποίον ο Αμάν υπεσχέθη να μετρήση εις τα θησαυροφυλάκια του βασιλέως διά τους Ιουδαίους· διά να απολέση αυτούς.","Kai ephanérōse pros autón o Marodochaíos ápan to gegonós eis autón, kai to posón tou argyríou to opoíon o Amán ypeschéthē na metrḗsē eis ta thēsaurophylákia tou basiléōs diá tous Ioudaíous: diá na apolésē autoús."],[4,8,"Και έδωκεν εις αυτόν το αντίγραφον του γράμματος της διαταγής, της εκδοθείσης εν Σούσοις διά να αφανίσωσιν αυτούς, διά να δείξη αυτό εις την Εσθήρ, και να απαγγείλη προς αυτήν και να παραγγείλη εις αυτήν να εισέλθη προς τον βασιλέα, να παρακαλέση αυτόν και να κάμη αίτησιν προς αυτόν υπέρ του λαού αυτής.","Kai édōken eis autón to antígraphon tou grámmatos tēs diatagḗs, tēs ekdotheísēs en Soúsois diá na aphanísōsin autoús, diá na deíxē autó eis tēn Esthḗr, kai na apangeílē pros autḗn kai na parangeílē eis autḗn na eisélthē pros ton basiléa, na parakalésē autón kai na kámē aítēsin pros autón ypér tou laoú autḗs."],[4,9,"Και ήλθεν ο Αθάχ και απήγγειλε προς την Εσθήρ τους λόγους του Μαροδοχαίου.","Kai ḗlthen o Athách kai apḗngeile pros tēn Esthḗr tous lógous tou Marodochaíou."],[4,10,"Η δε Εσθήρ ελάλησε προς τον Αθάχ και έδωκεν εις αυτόν προσταγήν προς τον Μαροδοχαίον,","Ē de Esthḗr elálēse pros ton Athách kai édōken eis autón prostagḗn pros ton Marodochaíon,"],[4,11,"Πάντες οι δούλοι του βασιλέως, και ο λαός των επαρχιών του βασιλέως, εξεύρουσιν, ότι όστις, ανήρ ή γυνή, εισέλθη προς τον βασιλέα εις την ενδοτέραν αυλήν άκλητος, εις νόμος αυτού είναι να θανατόνηται, εκτός εκείνου προς τον οποίον ο βασιλεύς εκτείνει το χρυσούν σκήπτρον διά να ζήση· αλλ' εγώ δεν προσεκλήθην να εισέλθω προς τον βασιλέα ήδη τριάκοντα ημέρας.","Pántes oi doúloi tou basiléōs, kai o laós tōn eparchiṓn tou basiléōs, exeúrousin, óti óstis, anḗr ḗ gynḗ, eisélthē pros ton basiléa eis tēn endotéran aulḗn áklētos, eis nómos autoú eínai na thanatónētai, ektós ekeínou pros ton opoíon o basileús ekteínei to chrysoún skḗptron diá na zḗsē: all' egṓ den proseklḗthēn na eisélthō pros ton basiléa ḗdē triákonta ēméras."],[4,12,"Και απήγγειλαν προς τον Μαροδοχαίον τους λόγους της Εσθήρ.","Kai apḗngeilan pros ton Marodochaíon tous lógous tēs Esthḗr."],[4,13,"Τότε ο Μαροδοχαίος παρήγγειλε ν' αποκριθώσι προς την Εσθήρ, Μη στοχάζεσαι εν σεαυτή ότι συ εκ πάντων των Ιουδαίων θέλεις σωθή εν τω οίκω του βασιλέως·","Tóte o Marodochaíos parḗngeile n' apokrithṓsi pros tēn Esthḗr, Mē stocházesai en seautḗ óti sy ek pántōn tōn Ioudaíōn théleis sōthḗ en tō oíkō tou basiléōs:"],[4,14,"διότι εάν σιωπήσης διόλου εν τω καιρώ τούτω, θέλει ελθεί άλλοθεν αναψυχή και σωτηρία εις τους Ιουδαίους, συ δε και ο οίκος του πατρός σου θέλετε απολεσθή· και τις εξεύρει εάν συ ήλθες εις την βασιλείαν διά τοιούτον καιρόν οποίος ούτος;","dióti eán siōpḗsēs diólou en tō kairṓ toútō, thélei eltheí állothen anapsychḗ kai sōtēría eis tous Ioudaíous, sy de kai o oíkos tou patrós sou thélete apolesthḗ: kai tis exeúrei eán sy ḗlthes eis tēn basileían diá toioúton kairón opoíos oútos?"],[4,15,"Τότε προσέταξεν η Εσθήρ να αποκριθώσι προς τον Μαροδοχαίον·","Tóte prosétaxen ē Esthḗr na apokrithṓsi pros ton Marodochaíon:"],[4,16,"Ύπαγε, σύναξον πάντας τους Ιουδαίους τους ευρισκομένους εν Σούσοις, και νηστεύσατε υπέρ εμού και μη φάγητε και μη πίητε τρεις ημέρας, νύκτα και ημέραν· και εγώ και αι θεράπαιναί μου θέλομεν νηστεύσει ομοίως· και ούτω θέλω εισέλθει προς τον βασιλέα, το οποίον δεν είναι κατά τον νόμον· και αν απολεσθώ, ας απολεσθώ.","Ýpage, sýnaxon pántas tous Ioudaíous tous euriskoménous en Soúsois, kai nēsteúsate ypér emoú kai mē phágēte kai mē píēte treis ēméras, nýkta kai ēméran: kai egṓ kai ai therápainaí mou thélomen nēsteúsei omoíōs: kai oútō thélō eisélthei pros ton basiléa, to opoíon den eínai katá ton nómon: kai an apolesthṓ, as apolesthṓ."],[4,17,"Και απελθών ο Μαροδοχαίος έκαμε κατά πάντα όσα προσέταξεν εις αυτόν η Εσθήρ.","Kai apelthṓn o Marodochaíos ékame katá pánta ósa prosétaxen eis autón ē Esthḗr."],[5,1,"Την τρίτην δε ημέραν ενδυθείσα η Εσθήρ την βασιλικήν στολήν εστάθη εν τη εσωτέρα αυλή του βασιλικού οίκου, απέναντι του οίκου του βασιλέως· και ο βασιλεύς εκάθητο επί του βασιλικού θρόνου αυτού εν τω βασιλικώ οίκω, απέναντι της πύλης του οίκου.","Tēn trítēn de ēméran endytheísa ē Esthḗr tēn basilikḗn stolḗn estáthē en tē esōtéra aulḗ tou basilikoú oíkou, apénanti tou oíkou tou basiléōs: kai o basileús ekáthēto epí tou basilikoú thrónou autoú en tō basilikṓ oíkō, apénanti tēs pýlēs tou oíkou."],[5,2,"Και ως είδεν ο βασιλεύς την Εσθήρ την βασίλισσαν ισταμένην εν τη αυλή, εύρηκε χάριν ενώπιον αυτού· και εξέτεινεν ο βασιλεύς προς την Εσθήρ το χρυσούν σκήπτρον το εν τη χειρί αυτού· και επλησίασεν η Εσθήρ και ήγγισε το άκρον του σκήπτρου.","Kai ōs eíden o basileús tēn Esthḗr tēn basílissan istaménēn en tē aulḗ, eúrēke chárin enṓpion autoú: kai exéteinen o basileús pros tēn Esthḗr to chrysoún skḗptron to en tē cheirí autoú: kai eplēsíasen ē Esthḗr kai ḗngise to ákron tou skḗptrou."],[5,3,"Και είπε προς αυτήν ο βασιλεύς, Τι θέλεις, βασίλισσα Εσθήρ; και τις η αίτησίς σου; και έως του ημίσεος της βασιλείας θέλει δοθή εις σε.","Kai eípe pros autḗn o basileús, Ti théleis, basílissa Esthḗr? kai tis ē aítēsís sou? kai éōs tou ēmíseos tēs basileías thélei dothḗ eis se."],[5,4,"Και απεκρίθη η Εσθήρ, Εάν ήναι αρεστόν εις τον βασιλέα, ας έλθη ο βασιλεύς και ο Αμάν την ημέραν ταύτην εις το συμπόσιον, το οποίον ητοίμασα δι' αυτόν.","Kai apekríthē ē Esthḗr, Eán ḗnai arestón eis ton basiléa, as élthē o basileús kai o Amán tēn ēméran taútēn eis to sympósion, to opoíon ētoímasa di' autón."],[5,5,"Και είπεν ο βασιλεύς, Επισπεύσατε τον Αμάν, διά να κάμη τον λόγον της Εσθήρ. Και ήλθον ο βασιλεύς και ο Αμάν εις το συμπόσιον, το οποίον έκαμεν η Εσθήρ.","Kai eípen o basileús, Epispeúsate ton Amán, diá na kámē ton lógon tēs Esthḗr. Kai ḗlthon o basileús kai o Amán eis to sympósion, to opoíon ékamen ē Esthḗr."],[5,6,"Και είπεν ο βασιλεύς προς την Εσθήρ επί του συμποσίου του οίνου, Τι το ζήτημά σου; και θέλει δοθή εις σέ· και τις η αίτησίς σου; και έως του ημίσεος της βασιλείας εάν ζητήσης, θέλει γείνει.","Kai eípen o basileús pros tēn Esthḗr epí tou symposíou tou oínou, Ti to zḗtēmá sou? kai thélei dothḗ eis sé: kai tis ē aítēsís sou? kai éōs tou ēmíseos tēs basileías eán zētḗsēs, thélei geínei."],[5,7,"Τότε αποκριθείσα η Εσθήρ είπε, το ζήτημά μου και η αίτησίς μου είναι·","Tóte apokritheísa ē Esthḗr eípe, to zḗtēmá mou kai ē aítēsís mou eínai:"],[5,8,"Εάν εύρηκα χάριν ενώπιον του βασιλέως, και εάν ήναι αρεστόν εις τον βασιλέα να εκτελέση το ζήτημά μου και να κάμη την αίτησίν μου, ας έλθη ο βασιλεύς και ο Αμάν εις το συμπόσιον το οποίον θέλω ετοιμάσει δι' αυτούς· και αύριον θέλω κάμει κατά τον λόγον του βασιλέως.","Eán eúrēka chárin enṓpion tou basiléōs, kai eán ḗnai arestón eis ton basiléa na ektelésē to zḗtēmá mou kai na kámē tēn aítēsín mou, as élthē o basileús kai o Amán eis to sympósion to opoíon thélō etoimásei di' autoús: kai aúrion thélō kámei katá ton lógon tou basiléōs."],[5,9,"Τότε εξήλθεν ο Αμάν την ημέραν εκείνην περιχαρής και εύθυμος την καρδίαν· αλλ' ότε ο Αμάν είδε τον Μαροδοχαίον εν τη πύλη του βασιλέως, ότι δεν εσηκώθη ουδέ εκινήθη δι' αυτόν, ενεπλήσθη ο Αμάν θυμού κατά του Μαροδοχαίου.","Tóte exḗlthen o Amán tēn ēméran ekeínēn pericharḗs kai eúthymos tēn kardían: all' óte o Amán eíde ton Marodochaíon en tē pýlē tou basiléōs, óti den esēkṓthē oudé ekinḗthē di' autón, eneplḗsthē o Amán thymoú katá tou Marodochaíou."],[5,10,"Αλλ' ο Αμάν εκράτησεν εαυτόν· και εισελθών εις τον οίκον αυτού έστειλε και εκάλεσε τους φίλους αυτού και Ζερές την γυναίκα αυτού,","All' o Amán ekrátēsen eautón: kai eiselthṓn eis ton oíkon autoú ésteile kai ekálese tous phílous autoú kai Zerés tēn gynaíka autoú,"],[5,11,"και διηγήθη προς αυτούς ο Αμάν περί της δόξης του πλούτου αυτού και του πλήθους των τέκνων αυτού, και πόσον ο βασιλεύς εμεγάλυνεν αυτόν, και τίνι τρόπω ύψωσεν αυτόν υπεράνω των αρχόντων και των δούλων του βασιλέως.","kai diēgḗthē pros autoús o Amán perí tēs dóxēs tou ploútou autoú kai tou plḗthous tōn téknōn autoú, kai póson o basileús emegálynen autón, kai tíni trópō ýpsōsen autón yperánō tōn archóntōn kai tōn doúlōn tou basiléōs."],[5,12,"Και είπεν ο Αμάν, Μάλιστα η βασίλισσα Εσθήρ δεν προσεκάλεσεν εις το συμπόσιον το οποίον έκαμεν, ειμή εμέ, μετά του βασιλέως· και αύριον έτι είμαι προσκεκλημένος προς αυτήν μετά του βασιλέως·","Kai eípen o Amán, Málista ē basílissa Esthḗr den prosekálesen eis to sympósion to opoíon ékamen, eimḗ emé, metá tou basiléōs: kai aúrion éti eímai proskeklēménos pros autḗn metá tou basiléōs:"],[5,13,"πλην πάντα ταύτα δεν με ωφελούσιν, ενόσω βλέπω τον Μαροδοχαίον τον Ιουδαίον καθήμενον εν τη πύλη του βασιλέως.","plēn pánta taúta den me ōpheloúsin, enósō blépō ton Marodochaíon ton Ioudaíon kathḗmenon en tē pýlē tou basiléōs."],[5,14,"Και είπε προς αυτόν Ζερές η γυνή αυτού και πάντες οι φίλοι αυτού, Ας κατασκευασθή ξύλον πεντήκοντα πηχών το ύψος, και το πρωΐ ειπέ προς τον βασιλέα να κρεμασθή ο Μαροδοχαίος επ' αυτό· τότε ύπαγε περιχαρής μετά του βασιλέως εις το συμπόσιον. Και το πράγμα ήρεσεν εις τον Αμάν, και προσέταξε να ετοιμασθή το ξύλον.","Kai eípe pros autón Zerés ē gynḗ autoú kai pántes oi phíloi autoú, As kataskeuasthḗ xýlon pentḗkonta pēchṓn to ýpsos, kai to prōḯ eipé pros ton basiléa na kremasthḗ o Marodochaíos ep' autó: tóte ýpage pericharḗs metá tou basiléōs eis to sympósion. Kai to prágma ḗresen eis ton Amán, kai prosétaxe na etoimasthḗ to xýlon."],[6,1,"Εν εκείνη τη νυκτί ο ύπνος έφυγεν από του βασιλέως· και προσέταξε να φέρωσι το βιβλίον των υπομνημάτων των χρονικών· και ανεγινώσκοντο ενώπιον του βασιλέως.","En ekeínē tē nyktí o ýpnos éphygen apó tou basiléōs: kai prosétaxe na phérōsi to biblíon tōn ypomnēmátōn tōn chronikṓn: kai aneginṓskonto enṓpion tou basiléōs."],[6,2,"Και ευρέθη γεγραμμένον ότι ο Μαροδοχαίος απήγγειλε περί του Βιχθάν και Θερές, δύο εκ των ευνούχων του βασιλέως, θυρωρών, οίτινες εζήτησαν να επιβάλωσι χείρα επί τον βασιλέα Ασσουήρην.","Kai euréthē gegramménon óti o Marodochaíos apḗngeile perí tou Bichthán kai Therés, dýo ek tōn eunoúchōn tou basiléōs, thyrōrṓn, oítines ezḗtēsan na epibálōsi cheíra epí ton basiléa Assouḗrēn."],[6,3,"Και είπεν ο βασιλεύς, Ποία τιμή και αξιοπρέπεια έγεινεν εις τον Μαροδοχαίον διά τούτο; Και είπον οι δούλοι του βασιλέως οι υπηρετούντες αυτόν, Δεν έγεινεν ουδέν εις αυτόν.","Kai eípen o basileús, Poía timḗ kai axioprépeia égeinen eis ton Marodochaíon diá toúto? Kai eípon oi doúloi tou basiléōs oi ypēretoúntes autón, Den égeinen oudén eis autón."],[6,4,"Και είπεν ο βασιλεύς, Τις είναι εν τη αυλή; είχε δε ελθεί ο Αμάν εις την εξωτέραν αυλήν του βασιλικού οίκου, διά να είπη προς τον βασιλέα να κρεμάση τον Μαροδοχαίον εις το ξύλον το οποίον ητοίμασε δι' αυτόν.","Kai eípen o basileús, Tis eínai en tē aulḗ? eíche de eltheí o Amán eis tēn exōtéran aulḗn tou basilikoú oíkou, diá na eípē pros ton basiléa na kremásē ton Marodochaíon eis to xýlon to opoíon ētoímase di' autón."],[6,5,"Και είπον προς αυτόν οι δούλοι του βασιλέως, Ιδού, ο Αμάν ίσταται εν τη αυλή. Και είπεν ο βασιλεύς, Ας εισέλθη.","Kai eípon pros autón oi doúloi tou basiléōs, Idoú, o Amán ístatai en tē aulḗ. Kai eípen o basileús, As eisélthē."],[6,6,"Και ότε εισήλθεν ο Αμάν, είπε προς αυτόν ο βασιλεύς, Τι πρέπει να γείνη εις τον άνθρωπον, τον οποίον ευαρεστείται ο βασιλεύς να τιμήση; Ο δε Αμάν εστοχάσθη εν τη καρδία αυτού, εις ποίον άλλον ο βασιλεύς ήθελεν ευαρεστηθή να κάμη τιμήν, παρά εις εμέ;","Kai óte eisḗlthen o Amán, eípe pros autón o basileús, Ti prépei na geínē eis ton ánthrōpon, ton opoíon euaresteítai o basileús na timḗsē? O de Amán estochásthē en tē kardía autoú, eis poíon állon o basileús ḗthelen euarestēthḗ na kámē timḗn, pará eis emé?"],[6,7,"Απεκρίθη λοιπόν ο Αμάν προς τον βασιλέα, Περί του ανθρώπου, τον οποίον ο βασιλεύς ευαρεστείται να τιμήση,","Apekríthē loipón o Amán pros ton basiléa, Perí tou anthrṓpou, ton opoíon o basileús euaresteítai na timḗsē,"],[6,8,"ας φέρωσι την βασιλικήν στολήν, την οποίαν ο βασιλεύς ενδύεται, και τον ίππον επί του οποίου ο βασιλεύς ιππεύει, και να τεθή το βασιλικόν διάδημα επί της κεφαλής αυτού·","as phérōsi tēn basilikḗn stolḗn, tēn opoían o basileús endýetai, kai ton íppon epí tou opoíou o basileús ippeúei, kai na tethḗ to basilikón diádēma epí tēs kephalḗs autoú:"],[6,9,"και η στολή αύτη και ο ίππος ας δοθώσιν εις την χείρα τινός εκ των μεγαλητέρων αρχόντων του βασιλέως, διά να στολίση τον άνθρωπον τον οποίον ο βασιλεύς ευαρεστείται να τιμήση· και φέρων αυτόν έφιππον διά των οδών της πόλεως ας κηρύττη έμπροσθεν αυτού, ούτω θέλει γίνεσθαι εις τον άνθρωπον, τον οποίον ο βασιλεύς ευαρεστείται να τιμήση.","kai ē stolḗ aútē kai o íppos as dothṓsin eis tēn cheíra tinós ek tōn megalētérōn archóntōn tou basiléōs, diá na stolísē ton ánthrōpon ton opoíon o basileús euaresteítai na timḗsē: kai phérōn autón éphippon diá tōn odṓn tēs póleōs as kērýttē émprosthen autoú, oútō thélei gínesthai eis ton ánthrōpon, ton opoíon o basileús euaresteítai na timḗsē."],[6,10,"Και είπεν ο βασιλεύς προς τον Αμάν, Σπεύσον, λάβε την στολήν και τον ίππον, ως είπας, και κάμε ούτως εις τον Μαροδοχαίον τον Ιουδαίον τον καθήμενον εν τη βασιλική πύλη· ας μη λείψη μηδέν εκ πάντων όσα είπας.","Kai eípen o basileús pros ton Amán, Speúson, lábe tēn stolḗn kai ton íppon, ōs eípas, kai káme oútōs eis ton Marodochaíon ton Ioudaíon ton kathḗmenon en tē basilikḗ pýlē: as mē leípsē mēdén ek pántōn ósa eípas."],[6,11,"Και έλαβεν ο Αμάν την στολήν και τον ίππον, και εστόλισε τον Μαροδοχαίον και έφερεν αυτόν έφιππον διά των οδών της πόλεως, κηρύττων έμπροσθεν αυτού, ούτω θέλει γίνεσθαι εις τον άνθρωπον, τον οποίον ο βασιλεύς ευαρεστείται να τιμήση.","Kai élaben o Amán tēn stolḗn kai ton íppon, kai estólise ton Marodochaíon kai épheren autón éphippon diá tōn odṓn tēs póleōs, kērýttōn émprosthen autoú, oútō thélei gínesthai eis ton ánthrōpon, ton opoíon o basileús euaresteítai na timḗsē."],[6,12,"Και επανήλθεν ο Μαροδοχαίος εις την πύλην του βασιλέως· ο δε Αμάν έσπευσε προς τον οίκον αυτού περίλυπος και έχων την κεφαλήν αυτού κεκαλυμμένην.","Kai epanḗlthen o Marodochaíos eis tēn pýlēn tou basiléōs: o de Amán éspeuse pros ton oíkon autoú perílypos kai échōn tēn kephalḗn autoú kekalymménēn."],[6,13,"Και διηγήθη ο Αμάν προς Ζερές την γυναίκα αυτού και προς πάντας τους φίλους αυτού παν ό,τι συνέβη εις αυτόν. Και είπον προς αυτόν οι σοφοί αυτού και Ζερές η γυνή αυτού, Εάν ο Μαροδοχαίος, έμπροσθεν του οποίου ήρχισας να εκπίπτης, ήναι εκ του σπέρματος των Ιουδαίων, δεν θέλεις κατισχύσει εναντίον αυτού, αλλ' εξάπαντος θέλεις πέσει έμπροσθεν αυτού.","Kai diēgḗthē o Amán pros Zerés tēn gynaíka autoú kai pros pántas tous phílous autoú pan ó,ti synébē eis autón. Kai eípon pros autón oi sophoí autoú kai Zerés ē gynḗ autoú, Eán o Marodochaíos, émprosthen tou opoíou ḗrchisas na ekpíptēs, ḗnai ek tou spérmatos tōn Ioudaíōn, den théleis katischýsei enantíon autoú, all' exápantos théleis pései émprosthen autoú."],[6,14,"Ενώ ελάλουν έτι μετ' αυτού, έφθασαν οι ευνούχοι του βασιλέως και έσπευσαν να φέρωσι τον Αμάν εις το συμπόσιον, το οποίον ητοίμασεν η Εσθήρ.","Enṓ eláloun éti met' autoú, éphthasan oi eunoúchoi tou basiléōs kai éspeusan na phérōsi ton Amán eis to sympósion, to opoíon ētoímasen ē Esthḗr."],[7,1,"Ήλθον λοιπόν ο βασιλεύς και ο Αμάν να συμποσιάσωσι μετά της Εσθήρ της βασιλίσσης.","Ḗlthon loipón o basileús kai o Amán na symposiásōsi metá tēs Esthḗr tēs basilíssēs."],[7,2,"Και είπε πάλιν ο βασιλεύς προς την Εσθήρ την δευτέραν ημέραν επί του συμποσίου του οίνου, Τι το ζήτημά σου, βασίλισσα Εσθήρ; και θέλει δοθή εις σέ· και τις η αίτησίς σου; και έως του ημίσεος της βασιλείας εάν ζητήσης, θέλει γείνει.","Kai eípe pálin o basileús pros tēn Esthḗr tēn deutéran ēméran epí tou symposíou tou oínou, Ti to zḗtēmá sou, basílissa Esthḗr? kai thélei dothḗ eis sé: kai tis ē aítēsís sou? kai éōs tou ēmíseos tēs basileías eán zētḗsēs, thélei geínei."],[7,3,"Τότε απεκρίθη η Εσθήρ η βασίλισσα και είπεν, Εάν εύρηκα χάριν ενώπιόν σου, βασιλεύ, και εάν ήναι αρεστόν εις τον βασιλέα, η ζωή μου ας μοι δοθή εις το ζήτημά μου και ο λαός μου εις την αίτησίν μου·","Tóte apekríthē ē Esthḗr ē basílissa kai eípen, Eán eúrēka chárin enṓpión sou, basileú, kai eán ḗnai arestón eis ton basiléa, ē zōḗ mou as moi dothḗ eis to zḗtēmá mou kai o laós mou eis tēn aítēsín mou:"],[7,4,"διότι επωλήθημεν, εγώ και ο λαός μου, εις απώλειαν, εις σφαγήν και εις όλεθρον· και εάν ηθέλομεν πωληθή ως δούλοι και δούλαι ήθελον σιωπήσει, αν και ο εχθρός δεν ηδύνατο να αναπληρώση την ζημίαν του βασιλέως.","dióti epōlḗthēmen, egṓ kai o laós mou, eis apṓleian, eis sphagḗn kai eis ólethron: kai eán ēthélomen pōlēthḗ ōs doúloi kai doúlai ḗthelon siōpḗsei, an kai o echthrós den ēdýnato na anaplērṓsē tēn zēmían tou basiléōs."],[7,5,"Τότε απεκρίθη ο βασιλεύς Ασσουήρης και είπε προς την Εσθήρ την βασίλισσαν, Τις είναι αυτός και που είναι εκείνος, όστις ετόλμησε να κάμη ούτω;","Tóte apekríthē o basileús Assouḗrēs kai eípe pros tēn Esthḗr tēn basílissan, Tis eínai autós kai pou eínai ekeínos, óstis etólmēse na kámē oútō?"],[7,6,"Και είπεν η Εσθήρ, Ο εναντίος και εχθρός είναι ούτος ο αχρείος Αμάν. Τότε εταράχθη ο Αμάν ενώπιον του βασιλέως και της βασιλίσσης.","Kai eípen ē Esthḗr, O enantíos kai echthrós eínai oútos o achreíos Amán. Tóte etaráchthē o Amán enṓpion tou basiléōs kai tēs basilíssēs."],[7,7,"Και σηκωθείς ο βασιλεύς από του συμποσίου του οίνου ωργισμένος υπήγεν εις τον κήπον του παλατίου· ο δε Αμάν εστάθη, διά να ζητήση την ζωήν αυτού παρά της Εσθήρ της βασιλίσσης· διότι είδεν ότι κακόν ήτο αποφασισμένον εναντίον αυτού παρά του βασιλέως.","Kai sēkōtheís o basileús apó tou symposíou tou oínou ōrgisménos ypḗgen eis ton kḗpon tou palatíou: o de Amán estáthē, diá na zētḗsē tēn zōḗn autoú pará tēs Esthḗr tēs basilíssēs: dióti eíden óti kakón ḗto apophasisménon enantíon autoú pará tou basiléōs."],[7,8,"Και επέστρεψεν ο βασιλεύς από του κήπου του παλατίου εις τον οίκον του συμποσίου του οίνου· ο δε Αμάν ήτο πεπτωκώς επί της κλίνης εφ' ης ήτο η Εσθήρ. Και είπεν ο βασιλεύς, Θέλει έτι και την βασίλισσαν να βιάση έμπροσθέν μου εν τω οίκω; Ο λόγος εξήλθεν εκ του στόματος του βασιλέως και εσκέπασαν το πρόσωπον του Αμάν.","Kai epéstrepsen o basileús apó tou kḗpou tou palatíou eis ton oíkon tou symposíou tou oínou: o de Amán ḗto peptōkṓs epí tēs klínēs eph' ēs ḗto ē Esthḗr. Kai eípen o basileús, Thélei éti kai tēn basílissan na biásē émprosthén mou en tō oíkō? O lógos exḗlthen ek tou stómatos tou basiléōs kai esképasan to prósōpon tou Amán."],[7,9,"Και είπεν ο Αρβονά, εις εκ των ευνούχων, ενώπιον του βασιλέως, Ιδού, και το ξύλον πεντήκοντα πηχών το ύψος, το οποίον ο Αμάν έκαμε διά τον Μαροδοχαίον, τον λαλήσαντα αγαθά υπέρ του βασιλέως, ίσταται εν τη οικία του Αμάν. Και είπεν ο βασιλεύς, Κρεμάσατε αυτόν επ' αυτού.","Kai eípen o Arboná, eis ek tōn eunoúchōn, enṓpion tou basiléōs, Idoú, kai to xýlon pentḗkonta pēchṓn to ýpsos, to opoíon o Amán ékame diá ton Marodochaíon, ton lalḗsanta agathá ypér tou basiléōs, ístatai en tē oikía tou Amán. Kai eípen o basileús, Kremásate autón ep' autoú."],[7,10,"Και εκρέμασαν τον Αμάν επί του ξύλου, το οποίον ητοίμασε διά τον Μαροδοχαίον. Και κατέπαυσεν ο θυμός του βασιλέως.","Kai ekrémasan ton Amán epí tou xýlou, to opoíon ētoímase diá ton Marodochaíon. Kai katépausen o thymós tou basiléōs."],[8,1,"Εν τη ημέρα εκείνη ο βασιλεύς Ασσουήρης έδωκεν εις την Εσθήρ την βασίλισσαν τον οίκον του Αμάν, του εχθρού των Ιουδαίων. Και ήλθεν ο Μαροδοχαίος ενώπιον του βασιλέως· διότι η Εσθήρ εφανέρωσε τι ήτο αυτής.","En tē ēméra ekeínē o basileús Assouḗrēs édōken eis tēn Esthḗr tēn basílissan ton oíkon tou Amán, tou echthroú tōn Ioudaíōn. Kai ḗlthen o Marodochaíos enṓpion tou basiléōs: dióti ē Esthḗr ephanérōse ti ḗto autḗs."],[8,2,"Και εκβαλών ο βασιλεύς το δακτυλίδιον αυτού, το οποίον αφήρεσεν από του Αμάν, έδωκεν αυτό εις τον Μαροδοχαίον. Και κατέστησεν η Εσθήρ τον Μαροδοχαίον επί τον οίκον του Αμάν.","Kai ekbalṓn o basileús to daktylídion autoú, to opoíon aphḗresen apó tou Amán, édōken autó eis ton Marodochaíon. Kai katéstēsen ē Esthḗr ton Marodochaíon epí ton oíkon tou Amán."],[8,3,"Και ελάλησε πάλιν η Εσθήρ ενώπιον του βασιλέως, και προσέπεσεν εις τους πόδας αυτού και ικέτευσεν αυτόν μετά δακρύων να ακυρώση την κακίαν του Αμάν του Αγαγίτου, και την σκευωρίαν αυτού την οποίαν εσκευώρησε κατά των Ιουδαίων.","Kai elálēse pálin ē Esthḗr enṓpion tou basiléōs, kai prosépesen eis tous pódas autoú kai ikéteusen autón metá dakrýōn na akyrṓsē tēn kakían tou Amán tou Agagítou, kai tēn skeuōrían autoú tēn opoían eskeuṓrēse katá tōn Ioudaíōn."],[8,4,"Και εξέτεινεν ο βασιλεύς το χρυσούν σκήπτρον προς την Εσθήρ. Τότε σηκωθείσα η Εσθήρ εστάθη ενώπιον του βασιλέως,","Kai exéteinen o basileús to chrysoún skḗptron pros tēn Esthḗr. Tóte sēkōtheísa ē Esthḗr estáthē enṓpion tou basiléōs,"],[8,5,"και είπεν, Εάν ήναι αρεστόν εις τον βασιλέα, και εάν εύρηκα χάριν ενώπιον αυτού, και το πράγμα φαίνηται ορθόν εις τον βασιλέα και αρέσκηται εις εμέ, ας γραφή να ανακαλεσθώσι τα γράμματα τα σκευωρηθέντα υπό του Αμάν του υιού Αμμεδαθά του Αγαγίτου, τα οποία έγραψε διά να απολεσθώσιν οι Ιουδαίοι οι εν πάσαις ταις επαρχίαις του βασιλέως·","kai eípen, Eán ḗnai arestón eis ton basiléa, kai eán eúrēka chárin enṓpion autoú, kai to prágma phaínētai orthón eis ton basiléa kai aréskētai eis emé, as graphḗ na anakalesthṓsi ta grámmata ta skeuōrēthénta ypó tou Amán tou yioú Ammedathá tou Agagítou, ta opoía égrapse diá na apolesthṓsin oi Ioudaíoi oi en pásais tais eparchíais tou basiléōs:"],[8,6,"διότι πως δύναμαι να υποφέρω να ίδω το κακόν, το οποίον θέλει ευρεί τον λαόν μου; ή πως δύναμαι να υποφέρω να ίδω τον αφανισμόν της συγγενείας μου;","dióti pōs dýnamai na ypophérō na ídō to kakón, to opoíon thélei eureí ton laón mou? ḗ pōs dýnamai na ypophérō na ídō ton aphanismón tēs syngeneías mou?"],[8,7,"Τότε είπεν ο βασιλεύς Ασσουήρης προς Εσθήρ την βασίλισσαν και προς τον Μαροδοχαίον τον Ιουδαίον, Ιδού, έδωκα εις την Εσθήρ τον οίκον του Αμάν και αυτόν εκρέμασαν επί του ξύλου, διότι εξήπλωσε την χείρα αυτού κατά των Ιουδαίων·","Tóte eípen o basileús Assouḗrēs pros Esthḗr tēn basílissan kai pros ton Marodochaíon ton Ioudaíon, Idoú, édōka eis tēn Esthḗr ton oíkon tou Amán kai autón ekrémasan epí tou xýlou, dióti exḗplōse tēn cheíra autoú katá tōn Ioudaíōn:"],[8,8,"σεις λοιπόν γράψατε υπέρ των Ιουδαίων, όπως φαίνεται εις εσάς καλόν, εν ονόματι του βασιλέως, και σφραγίσατε με το βασιλικόν δακτυλίδιον· διότι το γράμμα το γεγραμμένον εν ονόματι του βασιλέως και εσφραγισμένον με το βασιλικόν δακτυλίδιον, είναι αμετάτρεπτον.","seis loipón grápsate ypér tōn Ioudaíōn, ópōs phaínetai eis esás kalón, en onómati tou basiléōs, kai sphragísate me to basilikón daktylídion: dióti to grámma to gegramménon en onómati tou basiléōs kai esphragisménon me to basilikón daktylídion, eínai ametátrepton."],[8,9,"Και προσεκλήθησαν οι γραμματείς του βασιλέως εν τω καιρώ εκείνω εν τω τρίτω μηνί, ούτος είναι ο μην Σιβάν, την εικοστήν τρίτην αυτού· και εγράφη κατά πάντα όσα ο Μαροδοχαίος προσέταξε, προς τους Ιουδαίους και προς τους σατράπας και διοικητάς και άρχοντας των επαρχιών των από Ινδίας έως Αιθιοπίας, εκατόν εικοσιεπτά επαρχιών, εις πάσαν επαρχίαν κατά το γράφειν αυτής και προς πάντα λαόν κατά την γλώσσαν αυτού και προς τους Ιουδαίους κατά το γράφειν αυτών και κατά την γλώσσαν αυτών.","Kai proseklḗthēsan oi grammateís tou basiléōs en tō kairṓ ekeínō en tō trítō mēní, oútos eínai o mēn Sibán, tēn eikostḗn trítēn autoú: kai egráphē katá pánta ósa o Marodochaíos prosétaxe, pros tous Ioudaíous kai pros tous satrápas kai dioikētás kai árchontas tōn eparchiṓn tōn apó Indías éōs Aithiopías, ekatón eikosieptá eparchiṓn, eis pásan eparchían katá to gráphein autḗs kai pros pánta laón katá tēn glṓssan autoú kai pros tous Ioudaíous katá to gráphein autṓn kai katá tēn glṓssan autṓn."],[8,10,"Και έγραψεν εν ονόματι του βασιλέως Ασσουήρου και εσφράγισεν αυτό με το βασιλικόν δακτυλίδιον και εξαπέστειλε τα γράμματα διά ταχυδρόμων εφίππων, ιππαζόντων επί ταχυπόδων και γενναίων ημιόνων·","Kai égrapsen en onómati tou basiléōs Assouḗrou kai esphrágisen autó me to basilikón daktylídion kai exapésteile ta grámmata diá tachydrómōn ephíppōn, ippazóntōn epí tachypódōn kai gennaíōn ēmiónōn:"],[8,11,"δι' ων επέτρεπεν ο βασιλεύς εις τους Ιουδαίους τους κατά πάσαν πόλιν, να συναχθώσι και να σταθώσιν υπέρ της ζωής αυτών, να απολέσωσι, να φονεύσωσι και να αφανίσωσι πάσαν την δύναμιν του λαού και της επαρχίας των καταθλιβόντων αυτούς, παιδία και γυναίκας, και τα λάφυρα αυτών να διαρπάσωσιν,","di' ōn epétrepen o basileús eis tous Ioudaíous tous katá pásan pólin, na synachthṓsi kai na stathṓsin ypér tēs zōḗs autṓn, na apolésōsi, na phoneúsōsi kai na aphanísōsi pásan tēn dýnamin tou laoú kai tēs eparchías tōn katathlibóntōn autoús, paidía kai gynaíkas, kai ta láphyra autṓn na diarpásōsin,"],[8,12,"εν μιά ημέρα, κατά πάσας τας επαρχίας του βασιλέως Ασσουήρου, τη δεκάτη τρίτη του δωδεκάτου μηνός, ούτος είναι ο μην Αδάρ.","en miá ēméra, katá pásas tas eparchías tou basiléōs Assouḗrou, tē dekátē trítē tou dōdekátou mēnós, oútos eínai o mēn Adár."],[8,13,"Το αντίγραφον της επιστολής, το προς διάδοσιν του προστάγματος κατά πάσαν επαρχίαν, εδημοσιεύθη προς πάντας τους λαούς, διά να ήναι οι Ιουδαίοι έτοιμοι κατ' εκείνην την ημέραν να εκδικηθώσιν εναντίον των εχθρών αυτών.","To antígraphon tēs epistolḗs, to pros diádosin tou prostágmatos katá pásan eparchían, edēmosieúthē pros pántas tous laoús, diá na ḗnai oi Ioudaíoi étoimoi kat' ekeínēn tēn ēméran na ekdikēthṓsin enantíon tōn echthrṓn autṓn."],[8,14,"Και εξήλθον οι ταχυδρόμοι, ιππάζοντες επί ταχυπόδων ημιόνων, σπεύδοντες και κατεπειγόμενοι υπό της προσταγής του βασιλέως. Και η διαταγή εξεδόθη εν Σούσοις τη βασιλευούση.","Kai exḗlthon oi tachydrómoi, ippázontes epí tachypódōn ēmiónōn, speúdontes kai katepeigómenoi ypó tēs prostagḗs tou basiléōs. Kai ē diatagḗ exedóthē en Soúsois tē basileuoúsē."],[8,15,"Ο δε Μαροδοχαίος εξήλθεν απ' έμπροσθεν του βασιλέως εν στολή βασιλική κυανή και λευκή και φορών μέγαν στέφανον χρυσούν και επένδυμα βύσσινον και πορφυρούν· και η πόλις Σούσα έχαιρε και ευφραίνετο.","O de Marodochaíos exḗlthen ap' émprosthen tou basiléōs en stolḗ basilikḗ kyanḗ kai leukḗ kai phorṓn mégan stéphanon chrysoún kai epéndyma býssinon kai porphyroún: kai ē pólis Soúsa échaire kai euphraíneto."],[8,16,"Εις τους Ιουδαίους ήτο φως και αγαλλίασις και χαρά και δόξα.","Eis tous Ioudaíous ḗto phōs kai agallíasis kai chará kai dóxa."],[8,17,"Και εν πάση επαρχία και εν πάση πόλει, όπου ήλθε του βασιλέως το πρόσταγμα και η διαταγή, έγεινεν εις τους Ιουδαίους χαρά και αγαλλίασις, ευωχία και ημέρα αγαθή. Και πολλοί εκ των λαών της γης έγειναν Ιουδαίοι διότι ο φόβος των Ιουδαίων επέπεσεν επ' αυτούς.","Kai en pásē eparchía kai en pásē pólei, ópou ḗlthe tou basiléōs to próstagma kai ē diatagḗ, égeinen eis tous Ioudaíous chará kai agallíasis, euōchía kai ēméra agathḗ. Kai polloí ek tōn laṓn tēs gēs égeinan Ioudaíoi dióti o phóbos tōn Ioudaíōn epépesen ep' autoús."],[9,1,"Εν δε τω δωδεκάτω μηνί, ούτος είναι ο μην Αδάρ, τη δεκάτη τρίτη ημέρα του αυτού, ότε το πρόσταγμα του βασιλέως και η διαταγή αυτού ήτο πλησίον να εκτελεσθή, εν τη ημέρα καθ' ην οι εχθροί των Ιουδαίων ήλπιζον να κατακρατήσωσιν αυτών, αν και ετράπη εις το εναντίον, διότι οι Ιουδαίοι κατεκράτησαν των μισούντων αυτούς,","En de tō dōdekátō mēní, oútos eínai o mēn Adár, tē dekátē trítē ēméra tou autoú, óte to próstagma tou basiléōs kai ē diatagḗ autoú ḗto plēsíon na ektelesthḗ, en tē ēméra kath' ēn oi echthroí tōn Ioudaíōn ḗlpizon na katakratḗsōsin autṓn, an kai etrápē eis to enantíon, dióti oi Ioudaíoi katekrátēsan tōn misoúntōn autoús,"],[9,2,"συνήχθησαν οι Ιουδαίοι εν ταις πόλεσιν αυτών κατά πάσας τας επαρχίας του βασιλέως Ασσουήρου, διά να επιβάλωσι χείρα επί τους ζητούντας το κακόν αυτών· και ουδείς ηδυνήθη να αντισταθή εις αυτούς, διότι ο φόβος αυτών επέπεσεν επί πάντας τους λαούς.","synḗchthēsan oi Ioudaíoi en tais pólesin autṓn katá pásas tas eparchías tou basiléōs Assouḗrou, diá na epibálōsi cheíra epí tous zētoúntas to kakón autṓn: kai oudeís ēdynḗthē na antistathḗ eis autoús, dióti o phóbos autṓn epépesen epí pántas tous laoús."],[9,3,"Και πάντες οι άρχοντες των επαρχιών και οι σατράπαι και οι διοικηταί και οι οικονόμοι του βασιλέως εβοήθουν τους Ιουδαίους· διότι ο φόβος του Μαροδοχαίου επέπεσεν επ' αυτούς·","Kai pántes oi árchontes tōn eparchiṓn kai oi satrápai kai oi dioikētaí kai oi oikonómoi tou basiléōs eboḗthoun tous Ioudaíous: dióti o phóbos tou Marodochaíou epépesen ep' autoús:"],[9,4,"επειδή ο Μαροδοχαίος ήτο μέγας εν τω οίκω του βασιλέως και η φήμη αυτού διεδόθη εις πάσας τας επαρχίας· διότι ο άνθρωπος ο Μαροδοχαίος προέβαινε μεγαλυνόμενος.","epeidḗ o Marodochaíos ḗto mégas en tō oíkō tou basiléōs kai ē phḗmē autoú diedóthē eis pásas tas eparchías: dióti o ánthrōpos o Marodochaíos proébaine megalynómenos."],[9,5,"Και επάταξαν οι Ιουδαίοι πάντας τους εχθρούς αυτών με πάταγμα ρομφαίας και σφαγήν και όλεθρον, και έκαμον εις τους μισούντας αυτούς όπως ήθελον.","Kai epátaxan oi Ioudaíoi pántas tous echthroús autṓn me pátagma romphaías kai sphagḗn kai ólethron, kai ékamon eis tous misoúntas autoús ópōs ḗthelon."],[9,6,"Και εν Σούσοις τη βασιλευούση εφόνευσαν οι Ιουδαίοι και απώλεσαν πεντακοσίους άνδρας.","Kai en Soúsois tē basileuoúsē ephóneusan oi Ioudaíoi kai apṓlesan pentakosíous ándras."],[9,7,"Και τον Φαρσανδαθά και τον Δαλφών και τον Ασπαθά","Kai ton Pharsandathá kai ton Dalphṓn kai ton Aspathá"],[9,8,"και τον Ποραθά και τον Αδαλία και τον Αριδαθά","kai ton Porathá kai ton Adalía kai ton Aridathá"],[9,9,"και τον Φαρμαστά και τον Αρισαΐ και τον Αριδαΐ και τον Βαϊεζαθά,","kai ton Pharmastá kai ton Arisaḯ kai ton Aridaḯ kai ton Baïezathá,"],[9,10,"τους δέκα υιούς του Αμάν υιού του Αμμεδαθά, του εχθρού των Ιουδαίων, εφόνευσαν· επί λάφυρα όμως δεν έβαλον την χείρα αυτών.","tous déka yioús tou Amán yioú tou Ammedathá, tou echthroú tōn Ioudaíōn, ephóneusan: epí láphyra ómōs den ébalon tēn cheíra autṓn."],[9,11,"Εν τη ημέρα εκείνη ο αριθμός των φονευθέντων εν Σούσοις τη βασιλευούση εφέρθη ενώπιον του βασιλέως.","En tē ēméra ekeínē o arithmós tōn phoneuthéntōn en Soúsois tē basileuoúsē ephérthē enṓpion tou basiléōs."],[9,12,"Και είπεν ο βασιλεύς προς Εσθήρ την βασίλισσαν, Εν Σούσοις τη βασιλευούση εφόνευσαν οι Ιουδαίοι και απώλεσαν πεντακοσίους άνδρας και τους δέκα υιούς του Αμάν· εν ταις λοιπαίς επαρχίαις του βασιλέως τι έκαμον; τώρα τι το ζήτημά σου; και θέλει δοθή εις σέ· και τις έτι η αίτησίς σου; και θέλει γείνει.","Kai eípen o basileús pros Esthḗr tēn basílissan, En Soúsois tē basileuoúsē ephóneusan oi Ioudaíoi kai apṓlesan pentakosíous ándras kai tous déka yioús tou Amán: en tais loipaís eparchíais tou basiléōs ti ékamon? tṓra ti to zḗtēmá sou? kai thélei dothḗ eis sé: kai tis éti ē aítēsís sou? kai thélei geínei."],[9,13,"Και είπεν η Εσθήρ, Εάν ήναι αρεστόν εις τον βασιλέα, ας δοθή εις τους Ιουδαίους τους εν Σούσοις, να κάμωσι και αύριον κατά την διαταγήν της ημέρας ταύτης· και τους δέκα υιούς του Αμάν να κρεμάσωσιν επί ξύλων.","Kai eípen ē Esthḗr, Eán ḗnai arestón eis ton basiléa, as dothḗ eis tous Ioudaíous tous en Soúsois, na kámōsi kai aúrion katá tēn diatagḗn tēs ēméras taútēs: kai tous déka yioús tou Amán na kremásōsin epí xýlōn."],[9,14,"Και προσέταξεν ο βασιλεύς να γείνη ούτω· και εξεδόθη διαταγή εν Σούσοις· και εκρέμασαν τους δέκα υιούς του Αμάν.","Kai prosétaxen o basileús na geínē oútō: kai exedóthē diatagḗ en Soúsois: kai ekrémasan tous déka yioús tou Amán."],[9,15,"Και συνήχθησαν οι Ιουδαίοι οι εν Σούσοις και την δεκάτην τετάρτην του μηνός Αδάρ και εφόνευσαν τριακοσίους άνδρας εν Σούσοις· επί λάφυρα όμως δεν έβαλον την χείρα αυτών.","Kai synḗchthēsan oi Ioudaíoi oi en Soúsois kai tēn dekátēn tetártēn tou mēnós Adár kai ephóneusan triakosíous ándras en Soúsois: epí láphyra ómōs den ébalon tēn cheíra autṓn."],[9,16,"Οι δε άλλοι Ιουδαίοι, οι εν ταις επαρχίαις του βασιλέως, συνήχθησαν και εστάθησαν υπέρ της ζωής αυτών, και έλαβον ανάπαυσιν από των εχθρών αυτών και εφόνευσαν εκ των μισούντων αυτούς εβδομήκοντα πέντε χιλιάδας· επί τα λάφυρα όμως δεν έβαλον την χείρα αυτών·","Oi de álloi Ioudaíoi, oi en tais eparchíais tou basiléōs, synḗchthēsan kai estáthēsan ypér tēs zōḗs autṓn, kai élabon anápausin apó tōn echthrṓn autṓn kai ephóneusan ek tōn misoúntōn autoús ebdomḗkonta pénte chiliádas: epí ta láphyra ómōs den ébalon tēn cheíra autṓn:"],[9,17,"την δεκάτην τρίτην ημέραν του μηνός Αδάρ· και την δεκάτην τετάρτην ημέραν του αυτού ανεπαύθησαν και έκαμον ταύτην ημέραν συμποσίου και ευφροσύνης.","tēn dekátēn trítēn ēméran tou mēnós Adár: kai tēn dekátēn tetártēn ēméran tou autoú anepaúthēsan kai ékamon taútēn ēméran symposíou kai euphrosýnēs."],[9,18,"Οι δε Ιουδαίοι οι εν Σούσοις συνήχθησαν την δεκάτην τρίτην αυτού και την δεκάτην τετάρτην αυτού· την δε δεκάτην πέμπτην του αυτού ανεπαύθησαν και έκαμον ταύτην ημέραν συμποσίου και ευφροσύνης.","Oi de Ioudaíoi oi en Soúsois synḗchthēsan tēn dekátēn trítēn autoú kai tēn dekátēn tetártēn autoú: tēn de dekátēn pémptēn tou autoú anepaúthēsan kai ékamon taútēn ēméran symposíou kai euphrosýnēs."],[9,19,"Διά τούτο οι Ιουδαίοι οι χωρικοί οι κατοικούντες εν ταις ατειχίστοις πόλεσιν έκαμνον την δεκάτην τετάρτην ημέραν του μηνός Αδάρ ημέραν ευφροσύνης και συμποσίου και ημέραν αγαθήν, και απέστελλον μερίδας προς αλλήλους.","Diá toúto oi Ioudaíoi oi chōrikoí oi katoikoúntes en tais ateichístois pólesin ékamnon tēn dekátēn tetártēn ēméran tou mēnós Adár ēméran euphrosýnēs kai symposíou kai ēméran agathḗn, kai apéstellon merídas pros allḗlous."],[9,20,"Και έγραψεν ο Μαροδοχαίος τα πράγματα ταύτα και απέστειλεν επιστολάς προς πάντας τους Ιουδαίους τους εν πάσαις ταις επαρχίαις τον βασιλέως Ασσουήρου, τους πλησίον και τους μακράν,","Kai égrapsen o Marodochaíos ta prágmata taúta kai apésteilen epistolás pros pántas tous Ioudaíous tous en pásais tais eparchíais ton basiléōs Assouḗrou, tous plēsíon kai tous makrán,"],[9,21,"προσδιορίζων εις αυτούς να φυλάττωσι την δεκάτην τετάρτην ημέραν του μηνός Αδάρ και την δεκάτην πέμπτην του αυτού καθ' έκαστον έτος,","prosdiorízōn eis autoús na phyláttōsi tēn dekátēn tetártēn ēméran tou mēnós Adár kai tēn dekátēn pémptēn tou autoú kath' ékaston étos,"],[9,22,"ως τας ημέρας καθ' ας οι Ιουδαίοι ανεπαύθησαν από των εχθρών αυτών, και τον μήνα καθ' ον η λύπη αυτών ετράπη εις αυτούς εις χαράν και το πένθος εις ημέραν αγαθήν· ώστε να κάμνωσιν αυτάς ημέρας συμποσίου και ευφροσύνης και να αποστέλλωσι μερίδας προς αλλήλους και δώρα προς τους πτωχούς.","ōs tas ēméras kath' as oi Ioudaíoi anepaúthēsan apó tōn echthrṓn autṓn, kai ton mḗna kath' on ē lýpē autṓn etrápē eis autoús eis charán kai to pénthos eis ēméran agathḗn: ṓste na kámnōsin autás ēméras symposíou kai euphrosýnēs kai na apostéllōsi merídas pros allḗlous kai dṓra pros tous ptōchoús."],[9,23,"Και εδέχθησαν οι Ιουδαίοι εκείνο το οποίον ήρχισαν να κάμνωσι και εκείνο το οποίον έγραψεν ο Μαροδοχαίος προς αυτούς·","Kai edéchthēsan oi Ioudaíoi ekeíno to opoíon ḗrchisan na kámnōsi kai ekeíno to opoíon égrapsen o Marodochaíos pros autoús:"],[9,24,"διότι ο Αμάν ο υιός του Αμμεδαθά, ο Αγαγίτης, ο εχθρός πάντων των Ιουδαίων, εσκευώρησε κατά των Ιουδαίων να απολέση αυτούς, και έρριψε Φούρ, ήγουν κλήρον, διά να αναλώση αυτούς και να αφανίση αυτούς·","dióti o Amán o yiós tou Ammedathá, o Agagítēs, o echthrós pántōn tōn Ioudaíōn, eskeuṓrēse katá tōn Ioudaíōn na apolésē autoús, kai érripse Phoúr, ḗgoun klḗron, diá na analṓsē autoús kai na aphanísē autoús:"],[9,25,"Ότε όμως ήλθεν αυτή η Εσθήρ ενώπιον του βασιλέως, προσέταξε δι' επιστολών να τραπή κατά της κεφαλής αυτού η κακή αυτού σκευωρία, την οποίαν εσκευώρησε κατά των Ιουδαίων, και εκρέμασαν επί του ξύλου αυτόν και τους υιούς αυτού.","Óte ómōs ḗlthen autḗ ē Esthḗr enṓpion tou basiléōs, prosétaxe di' epistolṓn na trapḗ katá tēs kephalḗs autoú ē kakḗ autoú skeuōría, tēn opoían eskeuṓrēse katá tōn Ioudaíōn, kai ekrémasan epí tou xýlou autón kai tous yioús autoú."],[9,26,"Διά τούτο ωνόμασαν τας ημέρας ταύτας Φουρείμ εκ του ονόματος Φούρ. Όθεν διά πάντας τους λόγους της επιστολής ταύτης, και δι' εκείνο το οποίον είδον περί του πράγματος τούτου και το οποίον συνέβη εις αυτούς,","Diá toúto ōnómasan tas ēméras taútas Phoureím ek tou onómatos Phoúr. Óthen diá pántas tous lógous tēs epistolḗs taútēs, kai di' ekeíno to opoíon eídon perí tou prágmatos toútou kai to opoíon synébē eis autoús,"],[9,27,"διέταξαν οι Ιουδαίοι, και εδέχθησαν εφ' εαυτούς και επί το σπέρμα αυτών και επί πάντας τους προστιθεμένους εις αυτούς, να μη λείψωσι ποτέ από του να φυλάττωσι τας δύο ταύτας ημέρας, κατά το γεγραμμένον περί αυτών και κατά τον καιρόν αυτών εκάστου έτους·","diétaxan oi Ioudaíoi, kai edéchthēsan eph' eautoús kai epí to spérma autṓn kai epí pántas tous prostitheménous eis autoús, na mē leípsōsi poté apó tou na phyláttōsi tas dýo taútas ēméras, katá to gegramménon perí autṓn kai katá ton kairón autṓn ekástou étous:"],[9,28,"και αι ημέραι αύται να μνημονεύωνται και να φυλάττωνται εν πάση γενεά, εκάστη συγγενεία, εκάστη επαρχία, και εκάστη πόλει και αι ημέραι αύται Φουρείμ να μη εκλείψωσιν εκ μέσου των Ιουδαίων, και να μη παύση το μνημόσυνον αυτών από του σπέρματος αυτών.","kai ai ēmérai aútai na mnēmoneúōntai kai na phyláttōntai en pásē geneá, ekástē syngeneía, ekástē eparchía, kai ekástē pólei kai ai ēmérai aútai Phoureím na mē ekleípsōsin ek mésou tōn Ioudaíōn, kai na mē paúsē to mnēmósynon autṓn apó tou spérmatos autṓn."],[9,29,"Τότε η Εσθήρ η βασίλισσα, η θυγάτηρ του Αβιχαίλ, και ο Μαροδοχαίος ο Ιουδαίος, έγραψαν εκ δευτέρου μεθ' όλου του κύρους, διά να στερεώσωσι ταύτα τα περί Φουρείμ γεγραμμένα.","Tóte ē Esthḗr ē basílissa, ē thygátēr tou Abichaíl, kai o Marodochaíos o Ioudaíos, égrapsan ek deutérou meth' ólou tou kýrous, diá na stereṓsōsi taúta ta perí Phoureím gegramména."],[9,30,"Και έπεμψεν επιστολάς προς πάντας τους Ιουδαίους, εις τας εκατόν εικοσιεπτά επαρχίας του βασιλείου του Ασσουήρου, με λόγους ειρήνης και αληθείας,","Kai épempsen epistolás pros pántas tous Ioudaíous, eis tas ekatón eikosieptá eparchías tou basileíou tou Assouḗrou, me lógous eirḗnēs kai alētheías,"],[9,31,"διά να στερεώση τας ημέρας ταύτας Φουρείμ εν τοις καιροίς αυτών, καθώς προσδιώρισαν εις αυτούς ο Μαροδοχαίος ο Ιουδαίος και Εσθήρ η βασίλισσα, και καθώς διώρισαν, εφ' εαυτούς και επί το σπέρμα αυτών, την υπόθεσιν των νηστειών και της κραυγής αυτών.","diá na stereṓsē tas ēméras taútas Phoureím en tois kairoís autṓn, kathṓs prosdiṓrisan eis autoús o Marodochaíos o Ioudaíos kai Esthḗr ē basílissa, kai kathṓs diṓrisan, eph' eautoús kai epí to spérma autṓn, tēn ypóthesin tōn nēsteiṓn kai tēs kraugḗs autṓn."],[9,32,"Και διά διαταγής της Εσθήρ εκυρώθη η υπόθεσις αύτη των Φουρείμ, και εγράφη εν βιβλίω.","Kai diá diatagḗs tēs Esthḗr ekyrṓthē ē ypóthesis aútē tōn Phoureím, kai egráphē en biblíō."],[10,1,"Και επέβαλεν ο βασιλεύς Ασσουήρης φόρον επί την γην και τας νήσους της θαλάσσης.","Kai epébalen o basileús Assouḗrēs phóron epí tēn gēn kai tas nḗsous tēs thalássēs."],[10,2,"Πάσαι δε αι πράξεις της δυνάμεως αυτού και της ισχύος αυτού, και η περιγραφή μεγαλειότητος του Μαροδοχαίου, εις ην ο βασιλεύς προεβίβασεν αυτόν, δεν είναι γεγραμμένα εν τω βιβλίω των χρονικών των βασιλέων της Μηδίας και Περσίας;","Pásai de ai práxeis tēs dynámeōs autoú kai tēs ischýos autoú, kai ē perigraphḗ megaleiótētos tou Marodochaíou, eis ēn o basileús proebíbasen autón, den eínai gegramména en tō biblíō tōn chronikṓn tōn basiléōn tēs Mēdías kai Persías?"],[10,3,"Διότι ο Μαροδοχαίος ο Ιουδαίος εστάθη δεύτερος μετά τον βασιλέα Ασσουήρην και μέγας μεταξύ των Ιουδαίων και αγαπώμενος υπό του πλήθους των αδελφών αυτού, ζητών το καλόν του λαού αυτού και λαλών ειρήνην περί παντός του σπέρματος αυτού.","Dióti o Marodochaíos o Ioudaíos estáthē deúteros metá ton basiléa Assouḗrēn kai mégas metaxý tōn Ioudaíōn kai agapṓmenos ypó tou plḗthous tōn adelphṓn autoú, zētṓn to kalón tou laoú autoú kai lalṓn eirḗnēn perí pantós tou spérmatos autoú."]],"grc-swete":[["prologue",1,"ΕΤΟΥΣ δευτέρου βασιλεύοντος Ἀρταξέρξου τοῦ μεγάλου βασιλέως τῇ μιᾷ τοῦ Νεισὰ ἐνύπνιον ἴδεν Μαρδοχαῖος ὁ τοῦ Ἰαείρου τοῦ Σεμεείου τοῦ Κεισαίου ἐκ φυλῆς Βενιαμείν,","ETOUS deutérou basileúontos Artaxérxou toû megálou basiléōs tē̂i miā̂i toû Neisà enýpnion íden Mardochaîos ho toû Iaeírou toû Semeeíou toû Keisaíou ek phylē̂s Beniameín,"],["prologue",2,"ἄνθρωπος Ἰουδαῖος οἰκῶν ἐν Σούσοις τῇ πόλει, ἄνθρωπος μέγας, θεραπεύων ἐν τῇ αὐλῇ τοῦ βασιλέως·","ánthrōpos Ioudaîos oikō̂n en Soúsois tē̂i pólei, ánthrōpos mégas, therapeúōn en tē̂i aulē̂i toû basiléōs:"],["prologue",3,"ἦν δὲ ἐκ τῆς αἰχμαλωσίας ἧς ᾐχμαλώτευσεν Ναβουχοδονοσὸρ βασιλεὺς Βαβυλῶνος ἐξ Ἰερουσαλὴμ μετὰ Ἰεχονίου τοῦ βασιλέως τῆς Ἰουδαίας.","ē̂n dè ek tē̂s aichmalōsías hē̂s ēichmalṓteusen Nabouchodonosòr basileùs Babylō̂nos ex Ierousalḕm metà Iechoníou toû basiléōs tē̂s Ioudaías."],["prologue",4,"καὶ τοῦτο αὐτοῦ τὸ ἐνύπνιον· καὶ ἰδοὺ φωναὶ καὶ θόρυβος, βρονταὶ καὶ σεισμός, τάραχος ἐπὶ τῆς γῆς.","kaì toûto autoû tò enýpnion: kaì idoù phōnaì kaì thórybos, brontaì kaì seismós, tárachos epì tē̂s gē̂s."],["prologue",5,"καὶ ἰδοὺ δύο δράκοντες μέγαλοι ἕτοιμοι προῆλθον ἀμφότεροι παλαίειν· καὶ ἐγένετο ὐτῶν φωνὴ μεγάλη,","kaì idoù dýo drákontes mégaloi hétoimoi proē̂lthon amphóteroi palaíein: kaì egéneto ytō̂n phōnḕ megálē,"],["prologue",6,"καὶ τῇ φωνῇ αὐτῶν ἡτοιμάσθη πᾶν ἔθνος εἰς πόλεμον ὥστε πολεμῆσαι δικαίων ἔθνος.","kaì tē̂i phōnē̂i autō̂n hētoimásthē pân éthnos eis pólemon hṓste polemē̂sai dikaíōn éthnos."],["prologue",7,"καὶ ἰδοὺ ἡμέρα σκότους καὶ γνόφου, θλίψις καὶ στενοχωρία, κάκωσις καὶ τάραχος μέγας ἐπὶ τῆς γῆς·","kaì idoù hēméra skótous kaì gnóphou, thlípsis kaì stenochōría, kákōsis kaì tárachos mégas epì tē̂s gē̂s:"],["prologue",8,"καὶ ἐταράχθη δίκαιον πᾶν ἔθνος, φοβούμενοι τὰ ἑαυτῶν κακά, καὶ ἡτοιμάσθησαν ἀπολέσθαι·","kaì etaráchthē díkaion pân éthnos, phoboúmenoi tà heautō̂n kaká, kaì hētoimásthēsan apolésthai:"],["prologue",9,"καὶ ἐβόησαν πρὸς τὸν θεόν. ἀπὸ δὲ τῆς βοῆς αὐτῶν ἐγένετο ὡσανεὶ ἀπὸ μικρᾶς πηγῆς ποταμὸς μέγας, ὕδωρ πολύ·","kaì ebóēsan pròs tòn theón. apò dè tē̂s boē̂s autō̂n egéneto hōsaneì apò mikrâs pēgē̂s potamòs mégas, hýdōr polý:"],["prologue",10,"φῶς καὶ ὁ ἥλιος ἀνέτειλεν, καὶ οἱ ταπεινοὶ ὑψώθησαν καὶ κατέφαγον τοὺς ἐνδόξους.","phō̂s kaì ho hḗlios anéteilen, kaì hoi tapeinoì hypsṓthēsan kaì katéphagon toùs endóxous."],["prologue",11,"καὶ διεγερθεὶς Μαρδοχαῖος ἑωρακὼς τὸ ἐνύπνιον τοῦτο, καὶ τί ὁ θεὸς βεβούλευται ποιῆσαι, εἶχεν αὐτὸ ἐν τῇ καρδία, καὶ ἐν παντὶ λόγῳ ἤθελεν ἐπιγνῶναι αὐτὸ ἕως τῆς νυκτός.","kaì diegertheìs Mardochaîos heōrakṑs tò enýpnion toûto, kaì tí ho theòs beboúleutai poiē̂sai, eîchen autò en tē̂i kardía, kaì en pantì lógōi ḗthelen epignō̂nai autò héōs tē̂s nyktós."],["prologue",12,"καὶ ἡσύχασεν Μαρδοχαῖος ἐν τῇ αὐλῇ μετὰ Γαβάθα καὶ Θαρρὰ τῶν δύο εὐνούχων τοῦ βασιλέως τῶν φυλασσόντων τὴν αὐλήν,","kaì hēsýchasen Mardochaîos en tē̂i aulē̂i metà Gabátha kaì Tharrà tō̂n dýo eunoúchōn toû basiléōs tō̂n phylassóntōn tḕn aulḗn,"],["prologue",13,"ἤκουσέν τε αὐτῶν τοὺς λογισμοὺς καὶ τὰς μερίμνας αὐτῶν ἐξηραύνησεν, καὶ ἔμαθεν ὅτι ἑτοιμάζουσιν τὰς χεῖρας ἐπιβαλεῖν Ἀρταξέρξῃ τῷ βασιλεῖ καὶ ὑπέδειξεν τῷ βασιλεῖ περὶ αὐτῶν·","ḗkousén te autō̂n toùs logismoùs kaì tàs merímnas autō̂n exēraúnēsen, kaì émathen hóti hetoimázousin tàs cheîras epibaleîn Artaxérxēi tō̂i basileî kaì hypédeixen tō̂i basileî perì autō̂n:"],["prologue",14,"καὶ ἐξήτασεν ὁ βασιλεὺς τοὺς δύο εὐνούχους. καὶ ὁμολογήσαντες ἀπήχθησαν,","kaì exḗtasen ho basileùs toùs dýo eunoúchous. kaì homologḗsantes apḗchthēsan,"],["prologue",15,"καὶ ἔγραψεν ὁ βασιλεὺς τοὺς λόγους τούτους εἰς μνημόσυνον, καὶ Μαρδοχαῖος ἔγραψεν περὶ τῶν λόγων τούτων·","kaì égrapsen ho basileùs toùs lógous toútous eis mnēmósynon, kaì Mardochaîos égrapsen perì tō̂n lógōn toútōn:"],["prologue",16,"καὶ ἐπέταξεν ὁ βασιλεὺς Μαρδοχαίῳ θεραπεύειν ἐν τῇ αὐλῇ, καὶ ἔδωκεν αὐτῷ δόματα περὶ τούτων.","kaì epétaxen ho basileùs Mardochaíōi therapeúein en tē̂i aulē̂i, kaì édōken autō̂i dómata perì toútōn."],["prologue",17,"καὶ ἦν Ἀμὰν Ἀμαδάθου Βουγαῖος ἔνδοξος ἐνώπιον τοῦ βασιλέως, καὶ ἐζήτησεν κακοποιῆσαι τὸν Μαρδοχαῖον καὶ τὸν λαὸν αὐτοῦ ὑπέρ τῶν δύο εὐνούχων τοῦ βασιλέως.","kaì ē̂n Amàn Amadáthou Bougaîos éndoxos enṓpion toû basiléōs, kaì ezḗtēsen kakopoiē̂sai tòn Mardochaîon kaì tòn laòn autoû hypér tō̂n dýo eunoúchōn toû basiléōs."],[1,1,"Καὶ ἐγένετο μετὰ τοὺς λόγους τούτους ἐν ταῖς ἡμέραις Ἀρταξέρξου, οὗτος ὁ Ἀρταξέρξης ἀπὸ τῆς Ἰνδικῆς ἑκατὸν εἴκοσι ἑπτὰ χωρῶν ἐκράτησεν.","Kaì egéneto metà toùs lógous toútous en taîs hēmérais Artaxérxou, hoûtos ho Artaxérxēs apò tē̂s Indikē̂s hekatòn eíkosi heptà chōrō̂n ekrátēsen."],[1,2,"ἐν αὐταῖς ταῖς ἡμέραις ὅτε ἐθρονίσθη ὁ βασιλεὺς Ἀρταξέρξης ἐν Σούσοις τῇ πόλει,","en autaîs taîs hēmérais hóte ethronísthē ho basileùs Artaxérxēs en Soúsois tē̂i pólei,"],[1,3,"ἐν τῷ τρίτῳ ἔτει βασιλεύοντος αὐτοῦ, δοχὴν ἐποίησεν τοῖς φίλοις καὶ τοῖς λοιποῖς ἔθνεσιν καὶ τοῖς ΙΙερσῶν καὶ Μήδων ἐνδόξοις καὶ τοῖς ἄρχουσιν τῶν σατραπῶν.","en tō̂i trítōi étei basileúontos autoû, dochḕn epoíēsen toîs phílois kaì toîs loipoîs éthnesin kaì toîs IIersō̂n kaì Mḗdōn endóxois kaì toîs árchousin tō̂n satrapō̂n."],[1,4,"καὶ μετὰ ταῦτα μετὰ τὸ δεῖξαι αὐτοῖς τὸν πλοῦτον τῆς βασιλείας αὐτοῦ καὶ τὴν δόξαν τῆς εὐφροσύνης τοῦ πλούτου αὐτοῦ ἐν ἡμέραις ἑκατὸν ὀγδοήκοντα·","kaì metà taûta metà tò deîxai autoîs tòn ploûton tē̂s basileías autoû kaì tḕn dóxan tē̂s euphrosýnēs toû ploútou autoû en hēmérais hekatòn ogdoḗkonta:"],[1,5,"ὅτε δὲ ἀνεπληρώθησαν αἱ ἡμέραι τοῦ γάμου, ἐποίησεν ὁ βασιλεὺς πότον τοῖς ἔθνεσιν τοῖς εὑρεθεῖσιν εἰς τὴν πόλιν ἐπὶ ἡμέρας ἓξ ἐν αὐλῇ οἴκου τοῦ βασιλέως,","hóte dè aneplērṓthēsan hai hēmérai toû gámou, epoíēsen ho basileùs póton toîs éthnesin toîs heuretheîsin eis tḕn pólin epì hēméras hèx en aulē̂i oíkou toû basiléōs,"],[1,6,"κεκοσμημένῃ βυσσίνοις καὶ καρπασίνοις τεταμένοις ἐπὶ σχοινίοις βυσσίνοις καὶ πορφυροῖς, ἐπὶ κύβοις χρυσοῖς καὶ ἀργυροῖς, ἐπὶ στύλοις παρίνοις καὶ λιθίνοις· κλίναι χρυσαῖ καὶ ἀργυραῖ ἐπὶ λιθοστρώτου σμαραγδίτου λίθου καὶ πιννίνου καὶ παρίνου λίθου, καὶ στρωμναὶ διαφανεῖς ποικίλως διηνθισμέναι, κύκλῳ ῥόδα πεπασμένα·","kekosmēménēi byssínois kaì karpasínois tetaménois epì schoiníois byssínois kaì porphyroîs, epì kýbois chrysoîs kaì argyroîs, epì stýlois parínois kaì lithínois: klínai chrysaî kaì argyraî epì lithostrṓtou smaragdítou líthou kaì pinnínou kaì parínou líthou, kaì strōmnaì diaphaneîs poikílōs diēnthisménai, kýklōi rhóda pepasména:"],[1,7,"ποτήρια χρυσᾶ καὶ ἀργυρᾶ, καὶ ἀνθράκινον κυλίκιον προκείμενον ἀπὸ ταλάντων τρισμυρίων· οἶνος πολὺς καὶ ἡδύς, ὃν αὐτὸς ὁ βασιλεὺς ἔπινεν.","potḗria chrysâ kaì argyrâ, kaì anthrákinon kylíkion prokeímenon apò talántōn trismyríōn: oînos polỳs kaì hēdýs, hòn autòs ho basileùs épinen."],[1,8,"ὁ δὲ πότος οὗτος οὐ κατὰ προκείμενον νόμον ἐγένετο· οὕτως δὲ ἠθέλησεν ὁ βασιλεύς, καὶ ἐπέταξεν τοῖς οἰκονόμοις ποιῆσαι τὸ θέλημα αὐτοῦ καὶ τῶν ἀνθρώπων.","ho dè pótos hoûtos ou katà prokeímenon nómon egéneto: hoútōs dè ēthélēsen ho basileús, kaì epétaxen toîs oikonómois poiē̂sai tò thélēma autoû kaì tō̂n anthrṓpōn."],[1,9,"καὶ Ἀστιν ἡ βασίλισσα ἐποίησε πότον ταῖς γυναιξὶν ἐν τοῖς βασιλείοις ὅπου ὁ βασιλεὺς Ἀρταξέρξης.","kaì Astin hē basílissa epoíēse póton taîs gynaixìn en toîs basileíois hópou ho basileùs Artaxérxēs."],[1,10,"ἐν δὲ τῇ ἡμέρᾳ τῇ ἑβδόμῃ ἡδέως γενόμενος ὁ βασιλεὺς εἶπεν τῷ Ἀμὰν καὶ Μαζὰν καὶ Φαρρὰ καὶ Βωραζὴ καὶ Ζαθολθὰ καὶ Ἀββαταζὰ καὶ Θαραβά, τοῖς ἑπτὰ εὐνούχοις τοῖς διακόνοις τοῦ βασιλέως Ἀρταξέρξου,","en dè tē̂i hēmérāi tē̂i hebdómēi hēdéōs genómenos ho basileùs eîpen tō̂i Amàn kaì Mazàn kaì Pharrà kaì Bōrazḕ kaì Zatholthà kaì Abbatazà kaì Tharabá, toîs heptà eunoúchois toîs diakónois toû basiléōs Artaxérxou,"],[1,11,"εἰσαγαγεῖν τὴν βασίλισσαν πρὸς αὐτόν, βασιλεύειν αὐτὴν καὶ περιθεῖναι αὐτῇ τὸ διάδημα καὶ δεῖξαι αὐτὴν τοῖς ἄρχουσιν καὶ τοῖς ἔθνεσιν τὸ κάλλος αὐτῆς· ὅτι καλὴ ἦν.","eisagageîn tḕn basílissan pròs autón, basileúein autḕn kaì peritheînai autē̂i tò diádēma kaì deîxai autḕn toîs árchousin kaì toîs éthnesin tò kállos autē̂s: hóti kalḕ ē̂n."],[1,12,"καὶ οὐκ εἰσήκουσεν αὐτοῦ Ἀστὶν ἡ βασίλισσα ἐλθεῖν μετὰ τῶν εὐνούχων. καὶ ἐλυπήθη ὁ βασιλεὺς καὶ ὠργίσθη,","kaì ouk eisḗkousen autoû Astìn hē basílissa eltheîn metà tō̂n eunoúchōn. kaì elypḗthē ho basileùs kaì ōrgísthē,"],[1,13,"καὶ εἶπεν τοῖς φίλοις αὐτοῦ Κατὰ ταῦτα ἐλάλησεν Ἀστιν, ποιήσατε οὖν περὶ τούτου νόμον καὶ κρίσιν.","kaì eîpen toîs phílois autoû Katà taûta elálēsen Astin, poiḗsate oûn perì toútou nómon kaì krísin."],[1,14,"καὶ προσῆλθεν αὐτῷ Ἀρκεσαῖος καὶ Σαρσαθαῖος καὶ Μαλησεὰρ οἱ ἄρχοντες Περσῶν καὶ Μήδων οἱ ἐγγὺς τοῦ βασιλέως, οἱ πρῶτοι παρακαθήμενοι τῷ βασιλεῖ,","kaì prosē̂lthen autō̂i Arkesaîos kaì Sarsathaîos kaì Malēseàr hoi árchontes Persō̂n kaì Mḗdōn hoi engỳs toû basiléōs, hoi prō̂toi parakathḗmenoi tō̂i basileî,"],[1,15,"καὶ ἀπήγγειλαν αὐτῷ κατὰ τοὺς νόμους ὡς δεῖ ποιῆσαι Ἀστιν τῇ βασιλίσσῃ, ὅτι οὐκ ἐποίησεν τὰ ὑπὸ τοῦ βασιλέως προσταχθέντα διὰ τῶν εὐνούχων.","kaì apḗngeilan autō̂i katà toùs nómous hōs deî poiē̂sai Astin tē̂i basilíssēi, hóti ouk epoíēsen tà hypò toû basiléōs prostachthénta dià tō̂n eunoúchōn."],[1,16,"καὶ εἶπεν ὁ Μουχαῖος πρὸς τὸν βασιλέα καὶ τοὺς ἄρχοντας Oὐ τὸν βασιλέα μόνον ἠδίκησεν Ἀστιν ἡ βασίλισσα, ἀλλὰ καὶ πάντας τοὺς ἄρχοντας καὶ τοὺς ἡγουμένους τοῦ βασιλέως.","kaì eîpen ho Mouchaîos pròs tòn basiléa kaì toùs árchontas Ou tòn basiléa mónon ēdíkēsen Astin hē basílissa, allà kaì pántas toùs árchontas kaì toùs hēgouménous toû basiléōs."],[1,17,"καὶ γὰρ διηγήσατο αὐτοῖς τὰ ῥήματα τῆς βασιλίσσης, καὶ ὡς ἀντεῖπεν τῷ βασιλεῖ. ὡς οὖν ἀντεῖπεν τῷ βασιλεῖ Ἀρταξέρξῃ,","kaì gàr diēgḗsato autoîs tà rhḗmata tē̂s basilíssēs, kaì hōs anteîpen tō̂i basileî. hōs oûn anteîpen tō̂i basileî Artaxérxēi,"],[1,18,"οὕτως σήμερον αἱ τυραννίδες αἱ λοιπαὶ τῶν ἀρχόντων Περσῶν καὶ Μήδων ἀκούσασαι τὰ τῷ βασιλεῖ λεχθέντα ὑπʼ αὐτῆς τολμήσουσιν ὁμοίως ἀτιμάσαι τοὺς ἄνδρας αὐτῶν.","hoútōs sḗmeron hai tyrannídes hai loipaì tō̂n archóntōn Persō̂n kaì Mḗdōn akoúsasai tà tō̂i basileî lechthénta hypʼ autē̂s tolmḗsousin homoíōs atimásai toùs ándras autō̂n."],[1,19,"εἰ οὖν δοκεῖ τῷ βασιλεῖ, προσταξάτω βασιλικὸν καὶ γραφήτω κατὰ τοὺς νόμους Μήδων καὶ Περσῶν, καὶ μὴ ἄλλως χρησάσθω, μηδὲ εἰσελθάτω ἔτι ἡ βασίλισσα πρὸς αὐτόν, καὶ τὴν βασιλείαν αὐτῆς δότω ὁ βασιλεὺς γυναικὶ κρείττονι αὐτῆς.","ei oûn dokeî tō̂i basileî, prostaxátō basilikòn kaì graphḗtō katà toùs nómous Mḗdōn kaì Persō̂n, kaì mḕ állōs chrēsásthō, mēdè eiselthátō éti hē basílissa pròs autón, kaì tḕn basileían autē̂s dótō ho basileùs gynaikì kreíttoni autē̂s."],[1,20,"καὶ ἀκουσθήτω ὁ νόμος ὁ ὑπὸ τοῦ βασιλέως ὃν ἐὰν ποιῇ ἐν τῇ βασιλείᾳ αὐτοῦ· καὶ οὕτως πᾶσαι αἱ γυναῖκες περιθήσουσιν τιμὴν τοῖς ἀνδράσιν ἑαυτῶν, ἀπὸ πτωχοῦ ἕως πλουσίου.","kaì akousthḗtō ho nómos ho hypò toû basiléōs hòn eàn poiē̂i en tē̂i basileíāi autoû: kaì hoútōs pâsai hai gynaîkes perithḗsousin timḕn toîs andrásin heautō̂n, apò ptōchoû héōs plousíou."],[1,21,"καὶ ἤρεσεν ὁ λόγος τῷ βασιλε καὶ τοῖς ἄρχουσι· καὶ ἐποίησεν ὁ βασιλεὺς καθὰ ἐλάλησεν ὁ Μουχαίος,","kaì ḗresen ho lógos tō̂i basile kaì toîs árchousi: kaì epoíēsen ho basileùs kathà elálēsen ho Mouchaíos,"],[1,22,"καὶ ἀπέστειλεν εἰς πᾶσαν τὴν βασιλείαν κατὰ χώραν, κατὰ τὴν λέξιν αὐτῶν, ὥστε εἶναι φόβον αὐτοῖς ἐν ταῖς οἰκίαις αὐτῶν.","kaì apésteilen eis pâsan tḕn basileían katà chṓran, katà tḕn léxin autō̂n, hṓste eînai phóbon autoîs en taîs oikíais autō̂n."],[2,1,"Καὶ μετὰ τοὺς λόγους τούτους ἐκόπασεν ὁ βασιλεὺς τοῦ θυμοῦ, καὶ οὐκέτι ἐμνήσθη τῆς Ἀστίν, μνημονεύων οἷα ἐλάλησεν καὶ ὡς κατέκρινεν αὐτήν.","Kaì metà toùs lógous toútous ekópasen ho basileùs toû thymoû, kaì oukéti emnḗsthē tē̂s Astín, mnēmoneúōn hoîa elálēsen kaì hōs katékrinen autḗn."],[2,2,"καὶ εἶπαν οἱ διάκονοι τοῦ βασιλέως Ζητηθήτω τῷ βασιλεῖ κοράσια ἄφθορα καλὰ τῷ εἴδει·","kaì eîpan hoi diákonoi toû basiléōs Zētēthḗtō tō̂i basileî korásia áphthora kalà tō̂i eídei:"],[2,3,"καὶ καταστήσει ὁ βασιλεὺς κωμάρχας ἐν πάσαις ταῖς χώραις τῆς βασιλείας αὐτοῦ, καὶ ἐπιλεξάτωσαν κοράσια παρθενικὰ καλὰ τῷ εἴδει εἰς Σουσὰν τὴν πόλιν εἰς τὸν γυναικῶνα, καὶ παραδοθήτωσαν τῷ εὐνούχῳ τοῦ βασιλέως τῷ φύλακι τῶν γυναικῶν, καὶ δοθήτω σμῆγμα καὶ ἡ λοιπὴ ἐπιμέλεια","kaì katastḗsei ho basileùs kōmárchas en pásais taîs chṓrais tē̂s basileías autoû, kaì epilexátōsan korásia parthenikà kalà tō̂i eídei eis Sousàn tḕn pólin eis tòn gynaikō̂na, kaì paradothḗtōsan tō̂i eunoúchōi toû basiléōs tō̂i phýlaki tō̂n gynaikō̂n, kaì dothḗtō smē̂gma kaì hē loipḕ epiméleia"],[2,4,"καὶ ἡ γυνὴ ἣ ἂν ἀρέσῃ τῷ βασιλεῖ βασιλεύσει ἀντὶ Ἀστιν. καὶ ἤρεσεν τῷ βασιλεῖ τὸ πρόσταγμα, καὶ ἐποίησεν οὕτως.","kaì hē gynḕ hḕ àn arésēi tō̂i basileî basileúsei antì Astin. kaì ḗresen tō̂i basileî tò próstagma, kaì epoíēsen hoútōs."],[2,5,"Καὶ ἄνθρωπος ἦν Ἰουδαῖος ἐν Σούσοις τῇ πόλει, καὶ ὄνομα αὐτῷ Μαρδοχαῖος ὁ τοῦ Ἰαείρου τοῦ Σεμεείου τοῦ Κεισαίου ἐκ φυλῆς Βενιαμείν,","Kaì ánthrōpos ē̂n Ioudaîos en Soúsois tē̂i pólei, kaì ónoma autō̂i Mardochaîos ho toû Iaeírou toû Semeeíou toû Keisaíou ek phylē̂s Beniameín,"],[2,6,"ὃς ἦν αἰχμάλωτος ἐξ Ἰερουσαλὴμ ἣν ᾐχμαλώτευσεν Ναβουχοδονοσὸρ βασιλεὺς Βαβυλῶνος.","hòs ē̂n aichmálōtos ex Ierousalḕm hḕn ēichmalṓteusen Nabouchodonosòr basileùs Babylō̂nos."],[2,7,"καὶ ἦν τούτῳ παῖς θρεπτή, θυγάτηρ Ἀμειναδὰβ ἀδελφοῦ πατρὸς αὐτοῦ, καὶ ὄνομα αὐτῇ Ἐσθήρ· ἐν δὲ τῷ μεταλλάξαι αὐτῆς τοὺς γονεῖς ἐπαίδευσεν αὐτὴν ἑαυτῷ εἰς γυναῖκα· καὶ ἦν τὸ κοράσιον καλὸν τῷ εἴδει.","kaì ē̂n toútōi paîs threptḗ, thygátēr Ameinadàb adelphoû patròs autoû, kaì ónoma autē̂i Esthḗr: en dè tō̂i metalláxai autē̂s toùs goneîs epaídeusen autḕn heautō̂i eis gynaîka: kaì ē̂n tò korásion kalòn tō̂i eídei."],[2,8,"καὶ ὅτε ἠκούσθη τὸ τοῦ βασιλέως πρόσταγμα, συνήχθησαν κοράσια πολλὰ εἰς Σουσὰν τὴν πόλιν ὑπὸ χεῖρα Γαί, καὶ ἤχθη Ἐσθὴρ πρὸς Γαὶ τὸν φύλακα τῶν γυναικῶν.","kaì hóte ēkoústhē tò toû basiléōs próstagma, synḗchthēsan korásia pollà eis Sousàn tḕn pólin hypò cheîra Gaí, kaì ḗchthē Esthḕr pròs Gaì tòn phýlaka tō̂n gynaikō̂n."],[2,9,"καὶ ἤρεσεν αὐτῷ τὸ κοράσιον, καὶ εὗρεν χάριν ἐνώπιον αὐτοῦ· καὶ ἔσπευσεν αὐτῇ δοῦναι τὸ σμῆγμα καὶ τὴν μερίδα καὶ τὰ ἑπτὰ κοράσια τὰ ἀποδεδιγμένα αὐτῇ ἐκ βασιλικοῦ, καὶ ἐχρήσατο αὐτῇ καλῶς καὶ ταῖς ἅβραις αὐτῆς ἐν τῷ γυναικῶνι·","kaì ḗresen autō̂i tò korásion, kaì heûren chárin enṓpion autoû: kaì éspeusen autē̂i doûnai tò smē̂gma kaì tḕn merída kaì tà heptà korásia tà apodedigména autē̂i ek basilikoû, kaì echrḗsato autē̂i kalō̂s kaì taîs hábrais autē̂s en tō̂i gynaikō̂ni:"],[2,10,"καὶ οὐχ ὑπέδειξεν ἑσθὴρ τὸ γένος αὐτῆς οὐδὲ τὴν πατρίδα· ὁ γὰρ Μαρδοχαῖος ἐνετείλατο αὐτῇ μὴ ἀπαγγεῖλαι.","kaì ouch hypédeixen hesthḕr tò génos autē̂s oudè tḕn patrída: ho gàr Mardochaîos eneteílato autē̂i mḕ apangeîlai."],[2,11,"καθʼ ἑκάστην δὲ ἡμέραν ὁ Μαρδοχαῖος περιεπάτει κατὰ τὴν αὐλὴν τὴν γυναικείαν, ἐπισκοπῶν τί Ἐσθὴρ συμβήσεται.","kathʼ hekástēn dè hēméran ho Mardochaîos periepátei katà tḕn aulḕn tḕn gynaikeían, episkopō̂n tí Esthḕr symbḗsetai."],[2,12,"οὗτος δὲ ἦν καιρὸς κορασίου εἰσελθεῖν πρὸς τὸν βασιλέα, ὅταν ἀναπληρώσῃ μῆνας ιβ΄· οὕτως γὰρ ἀναπληροῦνται αἱ ἡμέραι τῆς θεραπείας. μῆνας ἓξ ἀλιφόμεναι ἐν σμυρνίνῳ ἐλαίῳ, καὶ μῆνας ἓξ ἐν τοῖς ἀρώμασιν καὶ ἐν τοῖς σμήγμασιν τῶν γυναικῶν,","hoûtos dè ē̂n kairòs korasíou eiseltheîn pròs tòn basiléa, hótan anaplērṓsēi mē̂nas ib´: hoútōs gàr anaplēroûntai hai hēmérai tē̂s therapeías. mē̂nas hèx aliphómenai en smyrnínōi elaíōi, kaì mē̂nas hèx en toîs arṓmasin kaì en toîs smḗgmasin tō̂n gynaikō̂n,"],[2,13,"καὶ τότε εἰσπορεύεται πρὸς τὸν βασιλέα· καὶ ᾧ ἐὰν εἴπῃ, παραδώσει αὐτὴν συνεισέρχεσθαι αὐτῷ ἀπὸ τοῦ γυναικῶνος ἕως τῶν βασιλείων.","kaì tóte eisporeúetai pròs tòn basiléa: kaì hō̂i eàn eípēi, paradṓsei autḕn syneisérchesthai autō̂i apò toû gynaikō̂nos héōs tō̂n basileíōn."],[2,14,"δείλης εἰσπορεύεται, καὶ πρὸς ἡμέραν ἀποτρέχει εἰς τὸν γυναικῶνα τὸν δεύτερον οὗ Γαὶ ὁ εὐνοῦχος τοῦ βασιλέως ὁ φύλαξ τῶν γυναικῶν, καὶ οὐκέτι εἰσπορεύεται πρὸς τὸν βασιλέα ἐὰν μὴ κληθῇ ὀνόματι.","deílēs eisporeúetai, kaì pròs hēméran apotréchei eis tòn gynaikō̂na tòn deúteron hoû Gaì ho eunoûchos toû basiléōs ho phýlax tō̂n gynaikō̂n, kaì oukéti eisporeúetai pròs tòn basiléa eàn mḕ klēthē̂i onómati."],[2,15,"ἐν δὲ τῷ ἀναπληροῦσθαι τὸν χρόνον Ἐσθὴρ τῆς θυγατρὸς Ἀμειναδὰβ ἀδελφοῦ πατρὸς Μαρδοχαίου εἰσελθεῖν πρὸς τὸν βασιλέα, οὐδὲν ἠθέτησεν ὧν ἐνετείλατο ὁ εὐνοῦχος ὁ φύλαξ τῶν γυναικῶν· ἦν γὰρ Ἐσθὴρ εὑρίσκουσα χάριν παρὰ πάντων τῶν βλεπόντων αὐτήν.","en dè tō̂i anaplēroûsthai tòn chrónon Esthḕr tē̂s thygatròs Ameinadàb adelphoû patròs Mardochaíou eiseltheîn pròs tòn basiléa, oudèn ēthétēsen hō̂n eneteílato ho eunoûchos ho phýlax tō̂n gynaikō̂n: ē̂n gàr Esthḕr heurískousa chárin parà pántōn tō̂n blepóntōn autḗn."],[2,16,"καὶ εἰσῆλθεν Ἐσθὴρ πρὸς Ἀρταξέρξην τὸν βασιλέα τῷ δωδεκάτῳ μηνὶ ὅς ἐστιν Ἀδάρ, τῷ ἑβδόμῳ ἔτει τῆς βασιλείας αὐτοῦ.","kaì eisē̂lthen Esthḕr pròs Artaxérxēn tòn basiléa tō̂i dōdekátōi mēnì hós estin Adár, tō̂i hebdómōi étei tē̂s basileías autoû."],[2,17,"καὶ ἠράσθη ὁ βασιλεὺς Ἐσθὴρ, καὶ εὗρεν χάριν παρὰ πάσας τὰς παρθένους, καὶ ἐπέθηκεν αὐτῇ τὸ διάδημα τὸ γυναικεῖον.","kaì ērásthē ho basileùs Esthḕr, kaì heûren chárin parà pásas tàs parthénous, kaì epéthēken autē̂i tò diádēma tò gynaikeîon."],[2,18,"καὶ ἐποίησεν ὁ βασιλεὺς πότον πᾶσι τοῖς φίλοις αὐτοῦ καὶ ταῖς δυνάμεσιν ἐπὶ ἡμέρας ἑπτά, καὶ ὕψωσεν τοὺς γάμους Ἐσθὴρ, καὶ ἄφεσιν ἐποίησεν τοῖς ὑπὸ τὴν βασιλείαν αὐτοῦ.","kaì epoíēsen ho basileùs póton pâsi toîs phílois autoû kaì taîs dynámesin epì hēméras heptá, kaì hýpsōsen toùs gámous Esthḕr, kaì áphesin epoíēsen toîs hypò tḕn basileían autoû."],[2,19,"ὁ δὲ Μαρδοχαῖος ἐθεράπευεν ἐν τῆ αὐλῇ.","ho dè Mardochaîos etherápeuen en tē̂ aulē̂i."],[2,20,"ἡ δὲ Ἐσθὴρ οὐχ ὑπέδειξεν τὴν πατρίδα αὐτῆς· οὕτως γὰρ ἐνετείλατο αὐτῇ Μαρδοχαῖος, φοβεῖσθαι τὸν θεὸν καὶ ποιεῖν τὰ προστάγματα αὐτοῦ, καθὼς ἦν μετʼ αὐτοῦ· καὶ Ἐσθὴρ οὐ μετήλλαξεν τὴν ἀγωγὴν αὐτῆς.","hē dè Esthḕr ouch hypédeixen tḕn patrída autē̂s: hoútōs gàr eneteílato autē̂i Mardochaîos, phobeîsthai tòn theòn kaì poieîn tà prostágmata autoû, kathṑs ē̂n metʼ autoû: kaì Esthḕr ou metḗllaxen tḕn agōgḕn autē̂s."],[2,21,"καὶ ἐλυπήθησαν οἱ δύο εὐνοῦχοι τοῦ βασιλέως οἱ ἀρχισωματοφύλακες ὅτι προήχθη Μαρδοχαῖος. καὶ ἐζήτουν ἀποκτεῖναι Ἀρταξέρξην τὸν βασιλέα.","kaì elypḗthēsan hoi dýo eunoûchoi toû basiléōs hoi archisōmatophýlakes hóti proḗchthē Mardochaîos. kaì ezḗtoun apokteînai Artaxérxēn tòn basiléa."],[2,22,"καὶ ἐδηλώθη Μαρδοχαίῳ ὁ λόγος, καὶ ἐσήμανεν Ἐσθὴρ, καὶ αὐτὴ ἐνεφάνισεν τῷ βασιλεῖ τὰ τῆς ἐπιβουλῆς.","kaì edēlṓthē Mardochaíōi ho lógos, kaì esḗmanen Esthḕr, kaì autḕ enephánisen tō̂i basileî tà tē̂s epiboulē̂s."],[2,23,"ὁ δὲ βασιλεὺς ἤτασεν τοὺς δύο εὐνούχους καὶ ἐκρέμασεν αὐτούς· καὶ προσέταξεν ὁ βασιλεὺς καταχωρίσαι εἰς μνημόσυνον ἐν τῇ βασιλικῇ βιβλιοθήκῃ ὑπὲρ τῆς εὐνοίας Μαρδοχαίου ἐν ἐγκωμίῳ.","ho dè basileùs ḗtasen toùs dýo eunoúchous kaì ekrémasen autoús: kaì prosétaxen ho basileùs katachōrísai eis mnēmósynon en tē̂i basilikē̂i bibliothḗkēi hypèr tē̂s eunoías Mardochaíou en enkōmíōi."],[3,1,"Μετὰ δὲ ταῦτα ἐδόξασεν ὁ βασιλεὺς Ἀρταξέρξης Ἀμὰν Ἁμαδάθου Βουγαῖον, καὶ ὕψωσεν αὐτὸν καὶ ἐπρωτοβάθρει πάντων τῶν φίλων αὐτοῦ.","Metà dè taûta edóxasen ho basileùs Artaxérxēs Amàn Hamadáthou Bougaîon, kaì hýpsōsen autòn kaì eprōtobáthrei pántōn tō̂n phílōn autoû."],[3,2,"καὶ πάντες οἱ ἐν τῇ αὐλῇ προσεκύνουν αὐτῷ, οὕτως γὰρ προσέταξεν ὁ βασιλεὺς ποιῆσαι· ὁ δὲ Μαρδοχαῖος οὐ προσεκύνει αὐτῷ.","kaì pántes hoi en tē̂i aulē̂i prosekýnoun autō̂i, hoútōs gàr prosétaxen ho basileùs poiē̂sai: ho dè Mardochaîos ou prosekýnei autō̂i."],[3,3,"καὶ ἐλάλησαν οἱ ἐν τῇ αὐλῇ τοῦ βασιλέως τῷ Μαρδοχαίῳ Μαρδοχαῖε, τί παρακούεις τὰ ὑπὸ τοῦ βασιλέως λεγόμενα;","kaì elálēsan hoi en tē̂i aulē̂i toû basiléōs tō̂i Mardochaíōi Mardochaîe, tí parakoúeis tà hypò toû basiléōs legómena?"],[3,4,"καθʼ ἑκάστην ἡμέραν ἐλάλουν αὐτῷ, καὶ οὐχ ὑπήκουεν αὐτῶν· καὶ ὑπέδειξαν τῷ Ἁμὰν Μαρδοχαῖον τοῖς τοῦ βασιλέως λόγοις ἀντιτασσόμενον· καὶ ὑπέδειξεν αὐτοῖς ὁ Μαρδοχαῖος ὅτι Ἰουδαῖός ἐστιν.","kathʼ hekástēn hēméran eláloun autō̂i, kaì ouch hypḗkouen autō̂n: kaì hypédeixan tō̂i Hamàn Mardochaîon toîs toû basiléōs lógois antitassómenon: kaì hypédeixen autoîs ho Mardochaîos hóti Ioudaîós estin."],[3,5,"καὶ ἐπιγνοὺς Ἁμὰν ὅτι οὐ προσκυνεῖ αὐτῷ Μαρδοχαῖος, ἐθυμώθη σφόδρα,","kaì epignoùs Hamàn hóti ou proskyneî autō̂i Mardochaîos, ethymṓthē sphódra,"],[3,6,"καὶ ἐβουλεύσατο ἀφανίσαι πάντας τοὺς ὑπὸ τὴν Ἀρταξέρξου βασιλείαν Ἰουδαίους.","kaì ebouleúsato aphanísai pántas toùs hypò tḕn Artaxérxou basileían Ioudaíous."],[3,7,"καὶ ἐποίησεν ψήφισμα ἐν ἔτει δωδεκάτῳ τῆς βασιλείας Ἀρταξέρξου, καὶ ἔβαλεν κλήρους ἡμέραν ἐξ ἡμέρας καὶ μῆνα ἐκ μηνὸς ὥστε ἀπολέσαι ἐν μιᾷ ἡμέρᾳ τὸ γένος Μαρδοχαίου, καὶ ἔπεσεν","kaì epoíēsen psḗphisma en étei dōdekátōi tē̂s basileías Artaxérxou, kaì ébalen klḗrous hēméran ex hēméras kaì mē̂na ek mēnòs hṓste apolésai en miā̂i hēmérāi tò génos Mardochaíou, kaì épesen"],[3,8,"ὁ κλῆρος εἰς τὴν τεσσαρεσκαιδεκάτην τοῦ μηνὸς ὅς ἐστιν Ἀδάρ. ἐλάλησεν πρὸς τὸν βασιλέα Ἀρταξέρξην λέγων Ὑπάρχει ἔθνος διεσπαρμένον ἐν τοῖς ἔθνεσιν ἐν πάσῃ τῇ βασιλείᾳ σου, οἱ δὲ νόμοι αὐτῶν ἔξαλλοι παρὰ πάντα τὰ ἔθνη, τῶν δὲ νόμων τοῦ βασιλέως παρακούουσιν, καὶ οὐ συμφέρει τῷ βασιλεῖ ἐᾶσαι αὐτούς.","ho klē̂ros eis tḕn tessareskaidekátēn toû mēnòs hós estin Adár. elálēsen pròs tòn basiléa Artaxérxēn légōn Hypárchei éthnos diesparménon en toîs éthnesin en pásēi tē̂i basileíāi sou, hoi dè nómoi autō̂n éxalloi parà pánta tà éthnē, tō̂n dè nómōn toû basiléōs parakoúousin, kaì ou symphérei tō̂i basileî eâsai autoús."],[3,9,"εἰ δοκεῖ τῷ βασιλεῖ, δογματισάτω ἀπολέσαι αὐτούς, κἀγὼ διαγράψω εἰς τὸ γαζοφυλάκιον τοῦ βασιλέως ἀργυρίου τάλαντα μύρια.","ei dokeî tō̂i basileî, dogmatisátō apolésai autoús, kagṑ diagrápsō eis tò gazophylákion toû basiléōs argyríou tálanta mýria."],[3,10,"καὶ περιελόμενος ὁ βασιλεὺς τὸν δακτύλιον ἔδωκεν εἰς χεῖρα τῷ Ἁμάν, σφραγίσαι κατὰ τῶν γεγραμμένων κατὰ τῶν Ἰουδαίων.","kaì perielómenos ho basileùs tòn daktýlion édōken eis cheîra tō̂i Hamán, sphragísai katà tō̂n gegramménōn katà tō̂n Ioudaíōn."],[3,11,"καὶ εἶπεν ὁ βασιλεὺς τῷ Ἁμάν Τὸ μέν ἀργύριον ἔχε, τῷ δὲ ἔθνει χρῶ ὡς βούλει.","kaì eîpen ho basileùs tō̂i Hamán Tò mén argýrion éche, tō̂i dè éthnei chrō̂ hōs boúlei."],[3,12,"καὶ ἐκλήθησαν οἱ γραμματεῖς τοῦ βασιλέως μηνὶ πρώτῳ τῇ τρισκαιδεκάτῃ, καὶ ἔγραψαν ὡς ἐπέταξεν Ἁμὰν τοῖς στρατηγοῖς καὶ τοῖς ἄρχουσιν κατὰ πᾶσαν χώραν ἀπὸ Ἰνδικῆς ἕως τῆς Αἰθιοπίας, ταῖς ἑκατὸν εἴκοσι ἑπτὰ χώραις, τοῖς τε ἄρχουσι τῶν ἐθνῶν κατὰ τὴν αὐτῶν λέξιν, δι᾿ Ἀρταξέρξου τοῦ βασιλέως.","kaì eklḗthēsan hoi grammateîs toû basiléōs mēnì prṓtōi tē̂i triskaidekátēi, kaì égrapsan hōs epétaxen Hamàn toîs stratēgoîs kaì toîs árchousin katà pâsan chṓran apò Indikē̂s héōs tē̂s Aithiopías, taîs hekatòn eíkosi heptà chṓrais, toîs te árchousi tō̂n ethnō̂n katà tḕn autō̂n léxin, di᾿ Artaxérxou toû basiléōs."],[3,13,"καὶ ἀπεστάλη διὰ βιβλιαφόρων εἰς τὴν Ἀρταξέρξου βασιλείαν, ἀφανίσαι τὸ γένος τῶν Ἰουδαίων ἐν ἡμέρᾳ μιᾷ μηνὸς δωδεκάτου, ὅς ἐστιν Ἀδάρ, καὶ διαρπάσαι τὰ ὑπάρχοντα αὐτῶν.","kaì apestálē dià bibliaphórōn eis tḕn Artaxérxou basileían, aphanísai tò génos tō̂n Ioudaíōn en hēmérāi miā̂i mēnòs dōdekátou, hós estin Adár, kaì diarpásai tà hypárchonta autō̂n."],[3,"1a","Τῆς δὲ ἐπιστολῆς ἐστὶν τὸ ἀντίγραφον τόδε Βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἀπὸ τῆς Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑκατὸν εἴκοσι ἑπτὰ χωρῶν ἄρχουσι καὶ τοπάρχαις ὑποτεταγμένοις τάδε γράφει.","Tē̂s dè epistolē̂s estìn tò antígraphon tóde Basileùs mégas Artaxérxēs toîs apò tē̂s Indikē̂s héōs tē̂s Aithiopías hekatòn eíkosi heptà chōrō̂n árchousi kaì topárchais hypotetagménois táde gráphei."],[3,"2a","πολλῶν ἐπάρξας ἐθνῶν καὶ πάσης ἐπικρατήσας οἰκουμένης, ἐβουλήθην, μὴ τῷ θράσει τῆς ἐξουσίας ἐπαιρόμενος ἐπιεικέστερον δὲ καὶ μετὰ ἠπιότητος ἀεὶ διεξάγων, τοὺς τῶν ὑποτεταγμένωυ ἀκυμάτους διὰ παντὸς καταστῆσαι βίους, τήν τε βασιλείαν ἥμερον καὶ πορευτὴν μέχρι περάτων παρεξόμενος ἀνανεώσασθαί τε τὴν ποθουμένην τοῖς πᾶσιν ἀνθρώποις εἰρήνην.","pollō̂n epárxas ethnō̂n kaì pásēs epikratḗsas oikouménēs, eboulḗthēn, mḕ tō̂i thrásei tē̂s exousías epairómenos epieikésteron dè kaì metà ēpiótētos aeì diexágōn, toùs tō̂n hypotetagménōy akymátous dià pantòs katastē̂sai bíous, tḗn te basileían hḗmeron kaì poreutḕn méchri perátōn parexómenos ananeṓsasthaí te tḕn pothouménēn toîs pâsin anthrṓpois eirḗnēn."],[3,"3a","πυθομένου δέ μου τῶν συμβούλων πῶς ἂν ἀχθείη τοῦτο ἐπὶ πέρας, σωφροσύνῃ παρʼ ἡμῖν διενέγκας καὶ ἐν τῇ εὐνοίᾳ ἀπαραλλάκτως καὶ βεβαίᾳ πίστει ἀποδεδιγμένος καὶ δεύτερον τῶν βασιλειῶν γέρας ἀπενηνεγμένος Ἁμὰν","pythoménou dé mou tō̂n symboúlōn pō̂s àn achtheíē toûto epì péras, sōphrosýnēi parʼ hēmîn dienénkas kaì en tē̂i eunoíāi aparalláktōs kaì bebaíāi pístei apodedigménos kaì deúteron tō̂n basileiō̂n géras apenēnegménos Hamàn"],[3,"4a","ἐπέδειξεν ἡμῖν, ἐν πάσαις ταῖς κατὰ τὴν οἰκουμένην φυλαῖς ἀναμεμίχθαι δυσμενῆ λαόν τινα, τοῖς νόμοις ἀντίθετον πρὸς πᾶν ἔθνος, τά τε τῶν βασιλέων παραπέμποντας διηνεκῶς προστάγματα, πρὸς τὸ μὴ κατατίθεσθαι τὴν ὑφʼ ἡμῶν κατευθυνομένην ἀμέμπτως συναρχίαν.","epédeixen hēmîn, en pásais taîs katà tḕn oikouménēn phylaîs anamemíchthai dysmenē̂ laón tina, toîs nómois antítheton pròs pân éthnos, tá te tō̂n basiléōn parapémpontas diēnekō̂s prostágmata, pròs tò mḕ katatíthesthai tḕn hyphʼ hēmō̂n kateuthynoménēn amémptōs synarchían."],[3,"5a","διειληφότες οὖν τόδε τὸ ἔθνος μονώτατον ἐν ἀντιπαραγωγῇ παντὶ διὰ παντὸς ἀνθρώπῳ κείμενον, διαγωγὴν νόμων ξενίζουσαν παραλλάσσον, καὶ δυσνοοῦν τοῖς ἡμετέροις πράγμασιν τὰ χείριστα συντελοῦν κακὰ καὶ πρὸς τὸ μὴ τὴν βασιλείαν εὐσταθίας τυγχάνειν·","dieilēphótes oûn tóde tò éthnos monṓtaton en antiparagōgē̂i pantì dià pantòs anthrṓpōi keímenon, diagōgḕn nómōn xenízousan parallásson, kaì dysnooûn toîs hēmetérois prágmasin tà cheírista synteloûn kakà kaì pròs tò mḕ tḕn basileían eustathías tynchánein:"],[3,"6a","προστετάχαμεν οὖν τοὺς σημαινομένους ὑμῖν ἐν τοῖς γεγραμμένοις ὑπὸ Ἁμὰν τοῦ τεταγμένου ἐπὶ τῶν πραγμάτων καὶ δευτέρου πατρὸς ἡμῶν, πάντας σὺν γυναιξὶ καὶ τέκνοις ἀπολέσαι ὁλορριζεὶ ταῖς τῶν ἐχθρῶν μαχαίραις ἄνευ παντὸς οἴκτου καὶ φειδοῦς τῇ τεσσαρεσκαιδεκάτῃ τοῦ δωδεκάτου μηνὸς Ἀδὰρ τοῦ ἐνεστῶτος ἔτους,","prostetáchamen oûn toùs sēmainoménous hymîn en toîs gegramménois hypò Hamàn toû tetagménou epì tō̂n pragmátōn kaì deutérou patròs hēmō̂n, pántas sỳn gynaixì kaì téknois apolésai holorrizeì taîs tō̂n echthrō̂n machaírais áneu pantòs oíktou kaì pheidoûs tē̂i tessareskaidekátēi toû dōdekátou mēnòs Adàr toû enestō̂tos étous,"],[3,"7a","ὅπως οἱ πάλαι καὶ νῦν δυσμενεῖς ἐν ἡμέρᾳ μιᾷ βιαίως εἰς τὸν ᾅδην κατελθόντες εἰς τὸν μετέπειτα χρόνον εὐσταθῆ καὶ ἀτάραχα παρέχωσιν ἡμῖν διὰ τέλους τὰ πρά γματα.","hópōs hoi pálai kaì nŷn dysmeneîs en hēmérāi miā̂i biaíōs eis tòn hā́idēn katelthóntes eis tòn metépeita chrónon eustathē̂ kaì atáracha paréchōsin hēmîn dià télous tà prá gmata."],[3,14,"τὰ δὲ ἀντίγραφα τῶν ἐπιστολῶν ἐξετίθετο κατὰ χώραν· καὶ προσετάγη πᾶσι τοῖς ἔθνεσιν ἑτοίμους εἶναι εἰς τὴν ἡμέραν ταύτην.","tà dè antígrapha tō̂n epistolō̂n exetítheto katà chṓran: kaì prosetágē pâsi toîs éthnesin hetoímous eînai eis tḕn hēméran taútēn."],[3,15,"ἐσπεύδετο δὲ τὸ πρᾶγμα καὶ εἰς Σουσάν· ὁ δὲ βασιλεὺς καὶ Ἁμὰν ἐκωθωνίζοντο, ἐταράσσετο δὲ ἡ πόλις.","espeúdeto dè tò prâgma kaì eis Sousán: ho dè basileùs kaì Hamàn ekōthōnízonto, etarásseto dè hē pólis."],[4,1,"Ὁ δὲ Μαρδοχαῖος ἐπιγνοὺς τὸ συντελούμενον διέρρηξεν τὰ ἱμάτια ἑαυτοῦ, καὶ ἐνεδύσατο σάκκον καὶ κατεπάσατο σποδόν, καὶ ἐκπηδήσας διὰ τῆς πλατείας τῆς πόλεως ἐβόα φωνῇ μεγάλῃ Αἴρεται ἔθνος μηδὲν ἠδικηκός.","HO dè Mardochaîos epignoùs tò synteloúmenon diérrēxen tà himátia heautoû, kaì enedýsato sákkon kaì katepásato spodón, kaì ekpēdḗsas dià tē̂s plateías tē̂s póleōs ebóa phōnē̂i megálēi Aíretai éthnos mēdèn ēdikēkós."],[4,2,"καὶ ἦλθεν ἕως τῆς πύλης τοῦ βασιλέως, καὶ ἔστη· οὐ γὰρ ἦν ἐξὸν αὐτῷ εἰσελθεῖν εἰς τὴν αὐλὴν σάκκον ἔχοντι καὶ σποδόν.","kaì ē̂lthen héōs tē̂s pýlēs toû basiléōs, kaì éstē: ou gàr ē̂n exòn autō̂i eiseltheîn eis tḕn aulḕn sákkon échonti kaì spodón."],[4,3,"καὶ ἐν πάσῃ χώρᾳ οὗ ἐξετίθετο τὰ γράμματα κραυγὴ καὶ κοπετὸς καὶ πένθος μέγα τοῖς Ἰουδαίοις, σάκκον καὶ σποδὸν ἔστρωσαν ἑαυτοῖς.","kaì en pásēi chṓrāi hoû exetítheto tà grámmata kraugḕ kaì kopetòs kaì pénthos méga toîs Ioudaíois, sákkon kaì spodòn éstrōsan heautoîs."],[4,4,"καὶ εἰσῆλθον αἱ ἅβραι καὶ οἱ εὐνοῦχοι τῆς βασιλίσσης καὶ ἀνήγγειλαν αὐτῇ· καὶ ἐταράχθη ἀκούσασα τὸ γεγονός, καὶ ἀπέστειλεν στολίσαι τὸν Μαρδοχαῖον καὶ ἀφελέσθαι αὐτοῦ τὸν σάκκον· ὁ δὲ οὐκ ἐπείσθη.","kaì eisē̂lthon hai hábrai kaì hoi eunoûchoi tē̂s basilíssēs kaì anḗngeilan autē̂i: kaì etaráchthē akoúsasa tò gegonós, kaì apésteilen stolísai tòn Mardochaîon kaì aphelésthai autoû tòn sákkon: ho dè ouk epeísthē."],[4,5,"ἡ δὲ Ἐσὴρ προσεκαλέσατο Ἁχραθαῖον τὸν εὐνοῦχον αὐτῆς, ὃς παριστήκει αὐτῇ, καὶ ἀπέστειλεν μαθεῖν αὐτῇ παρὰ τοῦ Μαρδοχαίου τὸ ἀκριβές.","hē dè Esḕr prosekalésato Hachrathaîon tòn eunoûchon autē̂s, hòs paristḗkei autē̂i, kaì apésteilen matheîn autē̂i parà toû Mardochaíou tò akribés."],[4,7,"ὁ δὲ Μαρδοχαῖος ὑπέδειξεν αὐτῷ τὸ γεγονὸς καὶ τὴν ἐπαγγελίαν ἣν ἐπηγγείλατο Ἁμὰν τῷ βασιλεῖ εἰς τὴν γάζαν μυρίων ταλάντων, ἵνα ἀπολέσῃ τοὺς Ἰουδαίους.","ho dè Mardochaîos hypédeixen autō̂i tò gegonòs kaì tḕn epangelían hḕn epēngeílato Hamàn tō̂i basileî eis tḕn gázan myríōn talántōn, hína apolésēi toùs Ioudaíous."],[4,8,"καὶ τὸ ἀντίγραφον τὸ ἐν Σούσοις ἐκτεθὲν ὑπέρ τοῦ ἀπολέσθαι αὐτοὺς ἔδωκεν αὐτῷ δεῖξαι τῇ Ἐσθήρ· καὶ εἶπεν αὐτῷ ἐντείλασθαι αὐτῇ εἰσελθούσῃ παραιτήσασθαι τὸν βασιλέα καὶ ἀξιῶσαι αὐτὸν περὶ τοῦ λαοῦ, μνησθεῖσα ἡμερῶν ταπεινώσεώς σου ὡς ἐτράφης ἐν χειρί μου, διότι Ἁμὰν ὁ δευτερεύων τῷ βασιλεῖ ἐλάλησεν καθʼ ἡμῶν εἰς θάνατον· ἐπικάλεσαι τὸν κύριον καὶ λάλησον τῷ βασιλεῖ περὶ ἡμῶν καὶ ῥῦσαι ἡμᾶς ἐκ θανάτου.","kaì tò antígraphon tò en Soúsois ektethèn hypér toû apolésthai autoùs édōken autō̂i deîxai tē̂i Esthḗr: kaì eîpen autō̂i enteílasthai autē̂i eiselthoúsēi paraitḗsasthai tòn basiléa kaì axiō̂sai autòn perì toû laoû, mnēstheîsa hēmerō̂n tapeinṓseṓs sou hōs etráphēs en cheirí mou, dióti Hamàn ho deutereúōn tō̂i basileî elálēsen kathʼ hēmō̂n eis thánaton: epikálesai tòn kýrion kaì lálēson tō̂i basileî perì hēmō̂n kaì rhŷsai hēmâs ek thanátou."],[4,9,"εἰσελθὼν δὲ ὁ Ἁχραθαῖος ἐλάλησεν αὐτῇ πάντας τοὺς λόγους τούτους.","eiselthṑn dè ho Hachrathaîos elálēsen autē̂i pántas toùs lógous toútous."],[4,10,"εἶπεν δὲ Ἐσθὴρ πρὸς Ἁχραθαῖον Πορεύθητι πρὸς Μαρδοχαῖον καὶ εἰπὸν","eîpen dè Esthḕr pròs Hachrathaîon Poreúthēti pròs Mardochaîon kaì eipòn"],[4,11,"ὅτι Τὰ ἔθνη πάντα τῆς βασιλείας γινώσκει, ὅτι πᾶς ἄνθρωπος ἢ γυνὴ ὃς εἰσελεύσεται πρὸς τὸν βασιλέα εἰς τὴν αὐλὴν τὴν ἐσωτέραν ἄκλητος, οὐκ ἔστιν αὐτῷ σωτηρία· πλὴν ᾧ ἐκτείνει ὁ βασιλεὺς τὴν χρυσῆν ῥάβδον, οὗτος σωθήσεται· κἀγὼ οὐ κέκλημαι εἰσελθεῖν πρὸς τὸν βασιλέα, εἰσὶν αὗται ἡμέραι τριάκοντα.","hóti Tà éthnē pánta tē̂s basileías ginṓskei, hóti pâs ánthrōpos ḕ gynḕ hòs eiseleúsetai pròs tòn basiléa eis tḕn aulḕn tḕn esōtéran áklētos, ouk éstin autō̂i sōtēría: plḕn hō̂i ekteínei ho basileùs tḕn chrysē̂n rhábdon, hoûtos sōthḗsetai: kagṑ ou kéklēmai eiseltheîn pròs tòn basiléa, eisìn haûtai hēmérai triákonta."],[4,12,"καὶ ἀπήγγειλεν Ἁχραθαῖος Μαρδοχαίῳ πάντας τοὺς λόγους Ἐσθήρ.","kaì apḗngeilen Hachrathaîos Mardochaíōi pántas toùs lógous Esthḗr."],[4,13,"καὶ εἶπεν Μαρδοχαῖος πρὸς Ἁχραθαῖον Πορεύθητι καὶ εἰπὸν αὐτῇ Ἐσθήρ, μὴ εἴπῃς σεαυτῇ ὅτι σωθήσῃ μόνη ἐν τῇ βασιλείᾳ παρὰ πάντας τοὺς Ἰουδαίους·","kaì eîpen Mardochaîos pròs Hachrathaîon Poreúthēti kaì eipòn autē̂i Esthḗr, mḕ eípēis seautē̂i hóti sōthḗsēi mónē en tē̂i basileíāi parà pántas toùs Ioudaíous:"],[4,14,"ὡς ὅτι ἐὰν παρακούσῃς ἐν τούτῳ τῷ καιρῷ, ἄλλοθεν βοήθεια καὶ σκέπη ἔσται τοῖς Ἰουδαίοις· σὺ δὲ καὶ ὁ οἶκος τοῦ πατρός σου ἀπολεῖσθε. καὶ τίς οἶδεν εἰ εἰς τὸν καιρὸν τοῦτον ἐβασίλευσας;","hōs hóti eàn parakoúsēis en toútōi tō̂i kairō̂i, állothen boḗtheia kaì sképē éstai toîs Ioudaíois: sỳ dè kaì ho oîkos toû patrós sou apoleîsthe. kaì tís oîden ei eis tòn kairòn toûton ebasíleusas?"],[4,15,"καὶ ἐξαπέστειλεν Ἐσθὴρ τὸν ἥκοντα πρὸς αὐτὴν πρὸς Μαρδοχαῖον λέγουσα","kaì exapésteilen Esthḕr tòn hḗkonta pròs autḕn pròs Mardochaîon légousa"],[4,16,"Βαδίσας ἐκκλησίασον τοὺς Ἰουδαίους τοὺς ἐν Σούσοις, καὶ νηστεύσατε ἐπʼ ἐμοί, καὶ μὴ φάγητε μηδὲ πίητε ἐπὶ ἡμέρας τρεῖς νύκτα καὶ ἡμέραν· κἀγὼ δὲ καὶ αἱ ἅβραι μου ἀσιτήσομεν· καὶ τότε εἰσελεύσομαι πρὸς τὸν βασιλέα παρὰ τὸν νόμον, ἐὰν καὶ ἀπολέσθαι με ᾖ.","Badísas ekklēsíason toùs Ioudaíous toùs en Soúsois, kaì nēsteúsate epʼ emoí, kaì mḕ phágēte mēdè píēte epì hēméras treîs nýkta kaì hēméran: kagṑ dè kaì hai hábrai mou asitḗsomen: kaì tóte eiseleúsomai pròs tòn basiléa parà tòn nómon, eàn kaì apolésthai me ē̂i."],[4,17,"Καὶ βαδίσας Μαρδοχαῖος ἐποίησεν ὅσα ἐνετείλατο αὐτῷ Ἐσθῆρ·","Kaì badísas Mardochaîos epoíēsen hósa eneteílato autō̂i Esthē̂r:"],[4,"1a","καὶ ἐδεήθη Κυρίου, μνημονεύων πάντα τὰ ἔργα Κυρίου,","kaì edeḗthē Kyríou, mnēmoneúōn pánta tà érga Kyríou,"],[4,"2a","καὶ εἶπεν Κύριε, κύριε βασιλεῦ πάντων κρατῶν, ὅτι ἐν ἐξουσίᾳ σου τὸ πᾶν ἐστιν, καὶ οὐκ ἔστιν ὁ ἀντιδοξῶν σοι ἐν τῷ θέλειν σε σῶσαι τὸν Ἰσραήλ·","kaì eîpen Kýrie, kýrie basileû pántōn kratō̂n, hóti en exousíāi sou tò pân estin, kaì ouk éstin ho antidoxō̂n soi en tō̂i thélein se sō̂sai tòn Israḗl:"],[4,"3a","ὅτι σὺ ἐποίησας τὸν οὐρανὸν καὶ τὴν γῆν καὶ πᾶν θαυμαζόμενον ἐν τῇ ὑπʼ οὐρανόν,","hóti sỳ epoíēsas tòn ouranòn kaì tḕn gē̂n kaì pân thaumazómenon en tē̂i hypʼ ouranón,"],[4,"4a","καὶ κύριος εἶ πάντων, καὶ οὐκ ἔστιν ὃς ἀντιτάξεταί σοι τῷ κυρίῳ·","kaì kýrios eî pántōn, kaì ouk éstin hòs antitáxetaí soi tō̂i kyríōi:"],[4,"5a","σὺ πάντα γινώσκεις, σὺ οἶδας, Κύριε, ὅτι οὐκ ἐν ὕβρει οὐδὲ ἐν ὑπερηφανίᾳ οὐδὲ ἐν φιλοδοξίᾳ ἐποίησα τοῦτο, τὸ μὴ προσκυνεῖν τὸν ὑπερήφανον Ἀμάν.","sỳ pánta ginṓskeis, sỳ oîdas, Kýrie, hóti ouk en hýbrei oudè en hyperēphaníāi oudè en philodoxíāi epoíēsa toûto, tò mḕ proskyneîn tòn hyperḗphanon Amán."],[4,"6a","ὅτι ηὐδόκουν φιλεῖν πέλματα ποδῶν αὐτοῦ πρὸς σωτηρίαν Ἰσραήλ,","hóti ēydókoun phileîn pélmata podō̂n autoû pròs sōtērían Israḗl,"],[4,"7a","ἀλλὰ ἐποίησα τοῦτο ἵνα μὴ θῶ δόξαν ἀνθρώπου ὑπεράνω δόξης θεοῦ· καὶ οὐ προσκυνήσω οὐδένα πλὴν σοῦ τοῦ κυρίου μου, καὶ οὐ ποιήσω αὐτὰ ἐν ὑπερηφανίᾳ.","allà epoíēsa toûto hína mḕ thō̂ dóxan anthrṓpou hyperánō dóxēs theoû: kaì ou proskynḗsō oudéna plḕn soû toû kyríou mou, kaì ou poiḗsō autà en hyperēphaníāi."],[4,"8a","καὶ νῦν, Κύριε ὁ θεὸς ὁ βασιλεὺς ὁ θεὸς Ἀβραάμ, φεῖσαι τοῦ λαοῦ σου, ὅτι ἐπιβλέπουσιν ἡμῖν εἰς καταφθορὰν καὶ ἐπεθύμησαν ἀπολέσαι τὴν ἐξ ἀρχῆς κληρονομίαν σου·","kaì nŷn, Kýrie ho theòs ho basileùs ho theòs Abraám, pheîsai toû laoû sou, hóti epiblépousin hēmîn eis kataphthoràn kaì epethýmēsan apolésai tḕn ex archē̂s klēronomían sou:"],[4,"9a","μὴ ὑπερίδῃς τὴν μερίδα σου ἣν σεαυτῷ ἐλυτρώσω ἐκ γῆς Αἰγύπτου·","mḕ hyperídēis tḕn merída sou hḕn seautō̂i elytrṓsō ek gē̂s Aigýptou:"],[4,"10a","ἐπάκουσον τῆς δεήσεως μου καὶ ἱλάσθητι τῷ κλήρῳ σου, καὶ στρέψον τὸ πένθος ἡμῶν εἰς εὐωχίαν, ἵνα ζῶντες ὑμνῶμέν σου τὸ ὄνομα, Κὐριε, καὶ μὴ ἀφανίσῃς στόμα αἰνούντων σοι.","epákouson tē̂s deḗseōs mou kaì hilásthēti tō̂i klḗrōi sou, kaì strépson tò pénthos hēmō̂n eis euōchían, hína zō̂ntes hymnō̂mén sou tò ónoma, Kyrie, kaì mḕ aphanísēis stóma ainoúntōn soi."],[4,"1a1","καὶ πᾶς Ἰσραὴλ ἐκέκραξαν ἐξ ἰσχύος αὐτῶν, ὅτι θάνατος αὐτῶν ἐν ὀφθαλμοῖς αὐτόῶν.","kaì pâs Israḕl ekékraxan ex ischýos autō̂n, hóti thánatos autō̂n en ophthalmoîs autóō̂n."],[4,"12a","Καὶ Ἐσθὴρ ἡ βασίλισσα κατέφυγεν ἐπὶ τὸν κύριον ἐν ἀγῶνι θανάτου κατειλημμένη,","Kaì Esthḕr hē basílissa katéphygen epì tòn kýrion en agō̂ni thanátou kateilēmménē,"],[4,"13a","καὶ ἀφελομένη τὰ ἱμάτια τῆς δόξης αὐτῆς ἐνεδύσατο ἱμάτια στενοχαορίας καὶ πένθους, καὶ ἀντὶ τῶν ὑπερηφάνων ἡδυσμάτων σποδοῦ καὶ κοπριῶν ἔπλησεν τὴν κεφαλήν· καὶ τὸ σῶμα ἐταπείνωσεν σφόδρα, καὶ πάντα τόπον κόσμου ἀγαλλιάματος αὐτῆς ἔπλησε στρεπτῶν τριχῶν αὐτῆς·","kaì apheloménē tà himátia tē̂s dóxēs autē̂s enedýsato himátia stenochaorías kaì pénthous, kaì antì tō̂n hyperēphánōn hēdysmátōn spodoû kaì kopriō̂n éplēsen tḕn kephalḗn: kaì tò sō̂ma etapeínōsen sphódra, kaì pánta tópon kósmou agalliámatos autē̂s éplēse streptō̂n trichō̂n autē̂s:"],[4,"14a","καὶ ἐδεῖτο Κυρίου θεοῦ Ἰσραὴλ καὶ εἶπεν Κύριέ μου, ὁ βασιλεὺς ἡμῶν, σὺ εἶ μόνος· βοήθησόν μοι τῇ μόνῃ καὶ μὴ ἐχούσῃ βοηθὸν εἰ μὴ σέ.","kaì edeîto Kyríou theoû Israḕl kaì eîpen Kýrié mou, ho basileùs hēmō̂n, sỳ eî mónos: boḗthēsón moi tē̂i mónēi kaì mḕ echoúsēi boēthòn ei mḕ sé."],[4,"15a","ὅτι κἰνδυνός μου ἐν χερί μου.","hóti kindynós mou en cherí mou."],[4,"16a","ἐγὼ δκουον ἐκ γενετῆς μου ἐν φυλῇ πατριᾶς μου, ὅτι σύ, Κύριε, ἔλαβες τὸν Ἰσραὴλ ἐκ πάντων τῶν ἐθνῶν καὶ τοὺς πατέρας ἡμῶν ἐκ πάντων τῶν προγόνων αὐτῶν εἰς κληρονομίαν αἰώνιον, καὶ ἐποί ησας αὐτοῖς ὅσα ἐλάλησας.","egṑ dkouon ek genetē̂s mou en phylē̂i patriâs mou, hóti sý, Kýrie, élabes tòn Israḕl ek pántōn tō̂n ethnō̂n kaì toùs patéras hēmō̂n ek pántōn tō̂n progónōn autō̂n eis klēronomían aiṓnion, kaì epoí ēsas autoîs hósa elálēsas."],[4,"17a","καὶ νῦν ἡμάρτομεν ἐνώπιόν σου, καὶ παρέδωκας ἡμᾶς εἰς χεῖρας τῶν ἐχθρῶν ἡμῶν·","kaì nŷn hēmártomen enṓpión sou, kaì parédōkas hēmâs eis cheîras tō̂n echthrō̂n hēmō̂n:"],[4,"18a","ἀνθʼ ὧν ἐδοξάσαμεν τοὺς θεοὺς αὐτῶν. δίκαιος εἶ, Κύριε·","anthʼ hō̂n edoxásamen toùs theoùs autō̂n. díkaios eî, Kýrie:"],[4,"19a","καὶ νῦν οὐχ ἱκανώθησαν ἐν πικρασμῷ δουλείας ἡμῶν, ἀλλὰ ἔθηκαν τὰς χεῖρας αὐτῶν,","kaì nŷn ouch hikanṓthēsan en pikrasmō̂i douleías hēmō̂n, allà éthēkan tàs cheîras autō̂n,"],[4,"20a","ἐξᾶραι ὁρισμὸν στόματός σου καὶ ἀφανίσαι κληρονομίαν σου, καὶ ἐμφράξαι στόμα αἰνούντων σοι καὶ σβέσαι δόξαν οἴκου σου καὶ θυσιαστήριόν σου,","exârai horismòn stómatós sou kaì aphanísai klēronomían sou, kaì emphráxai stóma ainoúntōn soi kaì sbésai dóxan oíkou sou kaì thysiastḗrión sou,"],[4,"21a","καὶ ἀνοῖξαι στόμα ἐθνῶν εἰς ἀρετὰς ματαίων καὶ θαυμασθῆναι βασιλέα σάρκινον εἰς αἰῶνα.","kaì anoîxai stóma ethnō̂n eis aretàs mataíōn kaì thaumasthē̂nai basiléa sárkinon eis aiō̂na."],[4,"22a","μὴ παραδῷς, Κύριε, τὸ σκῆπτρόν σου τοῖς μὴ οὖσιν, καὶ μὴ καταγελασάτωσαν ἐν τῇ πτώσει ἡμῶν, ἀλλὰ στρέψον τὴν βουλὴν αὐτῶν ἐπʼ αὐτούς· τὸν δὲ ἀρξάμενον ἐφʼ ἡμᾶς παραδιγμάτισον.","mḕ paradō̂is, Kýrie, tò skē̂ptrón sou toîs mḕ oûsin, kaì mḕ katagelasátōsan en tē̂i ptṓsei hēmō̂n, allà strépson tḕn boulḕn autō̂n epʼ autoús: tòn dè arxámenon ephʼ hēmâs paradigmátison."],[4,"23a","μνήσθητι, Κύριε, γνώσθητι ἐν καιρῷ θλίψεως ἡμῶν, καὶ ἐμὲ θάρσυνον, βασιλεῦ τῶν θεῶν καὶ πάσης ἀρχῆς ἐπικρατῶν·","mnḗsthēti, Kýrie, gnṓsthēti en kairō̂i thlípseōs hēmō̂n, kaì emè thársynon, basileû tō̂n theō̂n kaì pásēs archē̂s epikratō̂n:"],[4,"24a","δὸς λόγον εὔρυθμον εἰς τὸ στόμα μου ἐνώπιον τοῦ λέοντος, καὶ μετάθες τὴν καρδίαν αὐτοῦ εἰς μῖσος τοῦ πολεμοῦντος ἡμᾶς, εἰς συντέλειαν αὐτοῦ καὶ τῶν ὁμονοούντων αὐτῷ·","dòs lógon eúrythmon eis tò stóma mou enṓpion toû léontos, kaì metáthes tḕn kardían autoû eis mîsos toû polemoûntos hēmâs, eis syntéleian autoû kaì tō̂n homonooúntōn autō̂i:"],[4,"25a","ἡμᾶς δὲ ῥῦσαι ἐν χειρί σου, καὶ βοήθησόν μοι τῇ μόνῃ καὶ μὴ ἐχούσῃ εἰ μὴ σέ, Κύριε. πάντων γνῶσιν ἔχεις,","hēmâs dè rhŷsai en cheirí sou, kaì boḗthēsón moi tē̂i mónēi kaì mḕ echoúsēi ei mḕ sé, Kýrie. pántōn gnō̂sin écheis,"],[4,"26a","καὶ οἶδας ὅτι ἐμίσησα δόξαν ἀνόμων, καὶ βδελύσσομαι κοίτην ἀπεριτμήτων καὶ παντὸς ἀλλοτρίου.","kaì oîdas hóti emísēsa dóxan anómōn, kaì bdelýssomai koítēn aperitmḗtōn kaì pantòs allotríou."],[4,"27a","σὺ οἶδας τὴν ἀνάγκην μου, ὅτι βδελύσσομαι τὸ σημεῖον τῆς ὑπερηφανίας μου ὅ ἐστιν ἐπὶ τῆς κεφαλῆς μου ἐν ἡμέραις ὀπτασίας μου· βδελύσσομαι αὐτὸ ὡς ῥάκος καταμηνίων, καὶ οὐ φορῶ αὐτὸ ἐν ἡμέραις ἡσυχίας μου.","sỳ oîdas tḕn anánkēn mou, hóti bdelýssomai tò sēmeîon tē̂s hyperēphanías mou hó estin epì tē̂s kephalē̂s mou en hēmérais optasías mou: bdelýssomai autò hōs rhákos katamēníōn, kaì ou phorō̂ autò en hēmérais hēsychías mou."],[4,"28a","καὶ οὐκ ἔφαγεν ἡ δούλη σου τράπεζαν Ἁμάν, καὶ οὐκ ἐδόξασα συμπόσιον βασιλέως, οὐδὲ ἔπιον οἶνον σπονδῶν·","kaì ouk éphagen hē doúlē sou trápezan Hamán, kaì ouk edóxasa sympósion basiléōs, oudè épion oînon spondō̂n:"],[4,"29a","καὶ οὐκ ηὐφράνθη ἡ δούλη σου ἀφʼ ἡμέρας μεταβολῆς μου μέχρι νῦν πλὴν ἐπὶ σοί, Κύριε ὁ θεὸς Ἁβραάμ.","kaì ouk ēyphránthē hē doúlē sou aphʼ hēméras metabolē̂s mou méchri nŷn plḕn epì soí, Kýrie ho theòs Habraám."],[4,"30a","ὁ θεὸς ὁ ἰσχύων ἐπὶ πάντας, εἰσάκουσον φωνὴν ἀπηλπισμένων καὶ ῥῦσαι ἡμᾶς ἐκ χειρὸς τῶν πονηρευομένων, καὶ ῥῦσαί με ἐκ τοῦ φόβου μου.","ho theòs ho ischýōn epì pántas, eisákouson phōnḕn apēlpisménōn kaì rhŷsai hēmâs ek cheiròs tō̂n ponēreuoménōn, kaì rhŷsaí me ek toû phóbou mou."],[4,"1b","Καὶ ἐγενήθη ἐν τῇ ἡμέρᾳ τῇ τρίτῃ ὡς ἐπαύσατο προσευχομένη, ἐξεδύσατο τὰ ἱμάτια τῆς θεραπείας καὶ περιεβάλετο τὴν δόξαν αὐτῆς·","Kaì egenḗthē en tē̂i hēmérāi tē̂i trítēi hōs epaúsato proseuchoménē, exedýsato tà himátia tē̂s therapeías kaì periebáleto tḕn dóxan autē̂s:"],[4,"2b","καὶ γενηθεῖσα ἐπιφανής, ἐπικαλεσαμένη τὸν πάντων ἐπόπτην θεὸν καὶ σωτῆρα, παρέλαβεν τὰς δύο ἅβρας,","kaì genētheîsa epiphanḗs, epikalesaménē tòn pántōn epóptēn theòn kaì sōtē̂ra, parélaben tàs dýo hábras,"],[4,"3b","καὶ τῇ μὲν μιᾷ ἐπηρείδετο ὡς τρυφερευομένη,","kaì tē̂i mèn miā̂i epēreídeto hōs tryphereuoménē,"],[4,"4b","ἡ δὲ ἑτέρα ἐπηκολούθει κουφίζουσα τὴν ἔνδυσιν αὐτῆς·","hē dè hetéra epēkoloúthei kouphízousa tḕn éndysin autē̂s:"],[4,"5b","καὶ αὐτὴ ἐρυθριῶσα ἀκμῇ κάλλους αὐτῆς, καὶ τὸ πρόσωπον αὐτῆς ἱλαρὸν ὡς προσφιλές, ἡ δὲ καρδία αὐτῆς ἀπεστενωμένη ἀπὸ τοῦ φόβου.","kaì autḕ erythriō̂sa akmē̂i kállous autē̂s, kaì tò prósōpon autē̂s hilaròn hōs prosphilés, hē dè kardía autē̂s apestenōménē apò toû phóbou."],[4,"6b","καὶ εἰσελθοῦσα πάσας τὰς θύρας κατέστη ἐνώπιον τοῦ βασιλέως· καὶ αὐτὸς ἐκάθητο ἐπὶ τοῦ θρόνου τῆς βασιλείας αὐτοῦ, καὶ πᾶσαν στολὴν τῆς ἐπιφανείας αὐτοῦ ἐνεδεδύκει, ὅλος διὰ χρυσοῦ καὶ λίθων πολυτελῶν, καὶ ἦν φοβερὸς σφόδρα.","kaì eiselthoûsa pásas tàs thýras katéstē enṓpion toû basiléōs: kaì autòs ekáthēto epì toû thrónou tē̂s basileías autoû, kaì pâsan stolḕn tē̂s epiphaneías autoû enededýkei, hólos dià chrysoû kaì líthōn polytelō̂n, kaì ē̂n phoberòs sphódra."],[4,"7b","καὶ ἄρας τὸ πρόσαωπον αὐτοῦ πεπυραομένον δόξῃ ἐν ἀκμῇ θυμοῦ ἔβλεψεν· καὶ ἔπεσεν ἡ βασίλισσα καὶ μετέβαλεν τὸ χρῶμα αὐτῆς ἐυ ἐκλύσει, καὶ κατεπέκυψεν ἐπὶ τὴν κεφαλὴν τῆς ἀβρας τῆς προπορευομένης.","kaì áras tò prósaōpon autoû pepyraoménon dóxēi en akmē̂i thymoû éblepsen: kaì épesen hē basílissa kaì metébalen tò chrō̂ma autē̂s eu eklýsei, kaì katepékypsen epì tḕn kephalḕn tē̂s abras tē̂s proporeuoménēs."],[4,"8b","καὶ μετέβαλεν ὁ θεὸς τὸ πνεῦμα τοῦ βασιλέως εἰς πραύτητα, καὶ ἀγωνιάσας ἀνεπήδησεν ἀπὸ τοῦ θρόνου αὐτοῦ, καὶ ἀνέλαβεν αὐτὴν ἐπὶ τὰς ἀγκάλας αὐτοῦ μέχρις οὗ κατέστη, καὶ παρεκάλει αὐτὴν λόγοις εἰρηνικοῖς","kaì metébalen ho theòs tò pneûma toû basiléōs eis praútēta, kaì agōniásas anepḗdēsen apò toû thrónou autoû, kaì anélaben autḕn epì tàs ankálas autoû méchris hoû katéstē, kaì parekálei autḕn lógois eirēnikoîs"],[4,"9b","καὶ εἶπεν αὐτῇ Τί ἐστιν, Ἐσθῆρ; ἐγὼ ὁ ἀδελφός σου, θάρσει,","kaì eîpen autē̂i Tí estin, Esthē̂r? egṑ ho adelphós sou, thársei,"],[4,"10b","οὐ μὴ ἀποθάνῃς· ὅτι κοινὸν τὸ πρόσταγμα ἡμῶν ἐοτὰ·","ou mḕ apothánēis: hóti koinòn tò próstagma hēmō̂n eotà:"],[4,"11b","πρόσελθε.","próselthe."],[4,"12b","καὶ ἄρας τὴν χρυσῆν ῥάβδον ἐπέθηκεν ἐπὶ τὸν τράχηλον αὐτῆς, καὶ ἠσπάσατο αὐτὴν καὶ εἶπεν Λάλησόν μοι.","kaì áras tḕn chrysē̂n rhábdon epéthēken epì tòn tráchēlon autē̂s, kaì ēspásato autḕn kaì eîpen Lálēsón moi."],[4,"13b","καὶ εἶπεν αὐτῷ Εἶδόν σε, κύριε, ὡς ἄγγελον θεοῦ, καὶ ἐταράχθη ἡ καρδία μου ἀπὸ φόβου τῆς δόξης σου.","kaì eîpen autō̂i Eîdón se, kýrie, hōs ángelon theoû, kaì etaráchthē hē kardía mou apò phóbou tē̂s dóxēs sou."],[4,"14b","ὅτι θαυμαστὸς εἶ, κύριε, καὶ τὸ πρόσωπόν σου χαρίτων μεστόν.","hóti thaumastòs eî, kýrie, kaì tò prósōpón sou charítōn mestón."],[4,"15b","ἐν δὲ τῷ διαλέγεσθαι αὐτὴν ἔπεσεν ἀπὸ ἐκλύσεως·","en dè tō̂i dialégesthai autḕn épesen apò eklýseōs:"],[4,"16b","καὶ ὁ βασιλεὺς ἐταράσσετο, καὶ πᾶσα ἡ θεραπεία αὐτοῦ παρεκάλει αὐτήν.","kaì ho basileùs etarásseto, kaì pâsa hē therapeía autoû parekálei autḗn."],[5,3,"καὶ εἶπεν ὁ βασιλεὺς Τί θέλεις, Ἐσθήρ; καὶ τί σού ἐστιν τὸ ἀξίωμα; ἕως τοῦ ἡμίσους τῆς βασιλείας μου, καὶ ἔσται σοι.","kaì eîpen ho basileùs Tí théleis, Esthḗr? kaì tí soú estin tò axíōma? héōs toû hēmísous tē̂s basileías mou, kaì éstai soi."],[5,4,"εἶπεν δὲ Ἐσθήρ Ἡμέρα μου ἐπίσημος σήμερόν ἐστιν· εἰ οὗν δοκεῖ τῷ βασιλεῖ, ἐλθάτω καὶ αὐτὸς καὶ Ἀμὰν εἰς τὴν δοχὴν ἣν ποιήσω σήμερον.","eîpen dè Esthḗr Hēméra mou epísēmos sḗmerón estin: ei hoûn dokeî tō̂i basileî, elthátō kaì autòs kaì Amàn eis tḕn dochḕn hḕn poiḗsō sḗmeron."],[5,5,"καὶ εἶπεν ὁ βασιλεύς Κατασπεύσατε Ἀμὰν ὅπως ποιήσωμεν τὸν λόγον Ἐσθῆρ· καὶ παραγίνονται ἀμφότεροι εἰς τὴν δοχὴν ἣν εἶπεν Ἐσθῆρ.","kaì eîpen ho basileús Kataspeúsate Amàn hópōs poiḗsōmen tòn lógon Esthē̂r: kaì paragínontai amphóteroi eis tḕn dochḕn hḕn eîpen Esthē̂r."],[5,6,"ἐν δὲ τῷ πότῳ εἶπεν ὁ βασιλεὺς πρὸς Ἐσθήρ Τί ἐστιν, βασίλισσα Ἐσθήρ; καὶ ἔσται ὅσα ἀξιοῖς.","en dè tō̂i pótōi eîpen ho basileùs pròs Esthḗr Tí estin, basílissa Esthḗr? kaì éstai hósa axioîs."],[5,7,"καὶ εἶπεν Γὸ αἴτημά μου καὶ τὸ ἀξίωμα·","kaì eîpen Gò aítēmá mou kaì tò axíōma:"],[5,8,"εἰ εὗρον χάριν ἐνώπιον τοῦ βασιλέως, ἐλθάτω ὁ βασιλεὺς καὶ Ἀμὰν ἔτι τὴν αὔριον εἰς τὴν δοχὴν ἣν ποιήσω αὐτοῖς, καὶ αὔριον ποιήσω τὰ αὐτά.","ei heûron chárin enṓpion toû basiléōs, elthátō ho basileùs kaì Amàn éti tḕn aúrion eis tḕn dochḕn hḕn poiḗsō autoîs, kaì aúrion poiḗsō tà autá."],[5,9,"Καὶ ἐξῆλθεν ὁ Ἀμὰν ἀπὸ τοῦ βασιλέως ὑπερχαρὴς εὐφραινόμενος· ἐν δὲ τῷ ἰδεῖν Ἀμὰν Μαρδοχαῖον τὸν Ἰουδαῖον ἐν τῆ αὐλῇ ἐθυμώθη σφόδρα.","Kaì exē̂lthen ho Amàn apò toû basiléōs hypercharḕs euphrainómenos: en dè tō̂i ideîn Amàn Mardochaîon tòn Ioudaîon en tē̂ aulē̂i ethymṓthē sphódra."],[5,10,"καὶ εἰσελθὼν εἰς τὰ ἴδια ἐκάλεσεν τοὺς φίλους καὶ Ζωσάραν τὴν γυναῖκα αὐτοῦ,","kaì eiselthṑn eis tà ídia ekálesen toùs phílous kaì Zōsáran tḕn gynaîka autoû,"],[5,11,"καὶ ὑπέδειξεν αὐτοῖς τὸν πλοῦτον αὐτοῦ καὶ τὴν δόξαν ἣν ὁ βασιλεὺς αὐτῷ περιέθηκεν, καὶ ὡς ἐποίησεν αὐτὸν πρωτεύειν καὶ ἡγεῖσθαι τῆς βασιλείας.","kaì hypédeixen autoîs tòn ploûton autoû kaì tḕn dóxan hḕn ho basileùs autō̂i periéthēken, kaì hōs epoíēsen autòn prōteúein kaì hēgeîsthai tē̂s basileías."],[5,12,"καὶ εἶπεν Ἀμάν Οὐ κέκληκεν ἡ βασίλισσα μετὰ τοῦ βασιλέως οὐδένα εἰς τὴν δοχὴν ἀλλ᾿ ἢ ἐμέκαὶ εἰς τὴν αὔριον κέκλημαι.","kaì eîpen Amán Ou kéklēken hē basílissa metà toû basiléōs oudéna eis tḕn dochḕn all᾿ ḕ emékaì eis tḕn aúrion kéklēmai."],[5,13,"καὶ ταῦτά μοι οὐκ ἀρέσκει, ὅταν ἴδω Μαρδοχαῖον τὸν Ἰουδαῖον ἐν τῇ αὐλῇ.","kaì taûtá moi ouk aréskei, hótan ídō Mardochaîon tòn Ioudaîon en tē̂i aulē̂i."],[5,14,"καὶ εἶπεν πρὸς αὐτὸν Ζωσάρα ἡ γυνὴ αὐτοῦ καὶ οἱ φίλοι Κοπήτω σοι ξύλον πηχῶν πεντήκοντα, ὄρθρου δὲ εἰπὸν τῷ βασιλεῖ καὶ κρεμασθήτω Μαρδοχαῖος ἐπὶ τοῦ ξύλου· σὺ δὲ εἴσελθε εἰς τὴν δοχὴν σὺν τῷ βασιλεῖ καὶ εὐφραίνου. καὶ ἤρεσεν τὸ ῥῆμα τῷ Ἀμάν, καὶ ἡτοιμάσθη τὸ ξύλον.","kaì eîpen pròs autòn Zōsára hē gynḕ autoû kaì hoi phíloi Kopḗtō soi xýlon pēchō̂n pentḗkonta, órthrou dè eipòn tō̂i basileî kaì kremasthḗtō Mardochaîos epì toû xýlou: sỳ dè eíselthe eis tḕn dochḕn sỳn tō̂i basileî kaì euphraínou. kaì ḗresen tò rhē̂ma tō̂i Amán, kaì hētoimásthē tò xýlon."],[6,1,"Ὁ δὲ κύριος ἀπέστησεν τὸν ὕπνον ἀπὸ τοῦ βασιλέως τὴν νύκτα ἐκείνην, καὶ εἶπεν τῷ διδασκάλῳ αὐτοῦ εἰσφέρειν γράμματα μνημόσυνα τῶν ἡμερῶν ἀναγινώσκειν αὐτῷ.","HO dè kýrios apéstēsen tòn hýpnon apò toû basiléōs tḕn nýkta ekeínēn, kaì eîpen tō̂i didaskálōi autoû eisphérein grámmata mnēmósyna tō̂n hēmerō̂n anaginṓskein autō̂i."],[6,2,"εὗρευ δὲ τὰ γράμματα τὰ γραφέντα περὶ Μαρδοχαίου, ὡς ἀπήγγειλεν τῷ βασιλεῖ περὶ τῶν δύο εὐνούχων τοῦ βασιλέως ἐν τῷ φυλάσσειν αὐτοὺς καὶ ζητῆσαι ἐπιβαλεῖλ τὰς χεῖρας Ἀρταξέρξῃ.","heûreu dè tà grámmata tà graphénta perì Mardochaíou, hōs apḗngeilen tō̂i basileî perì tō̂n dýo eunoúchōn toû basiléōs en tō̂i phylássein autoùs kaì zētē̂sai epibaleîl tàs cheîras Artaxérxēi."],[6,3,"εἶπεν δὲ ὁ βασιλεύς Τίνα δόξαν ἢ χάριν ἐποιήσαμεν τῷ Μαρδοχαίηῳ; καὶ εἶπαν οἱ διάκονοι τοῦ βασιλέως Οὐκ ἐποίησας αὐτῷ οὐδέν.","eîpen dè ho basileús Tína dóxan ḕ chárin epoiḗsamen tō̂i Mardochaíēōi? kaì eîpan hoi diákonoi toû basiléōs Ouk epoíēsas autō̂i oudén."],[6,4,"ἐν δὲ τῷ πυνθάνεσθαι τὸν βασιλέα περὶ τῆς εὐνοίας Μαρδοχαίου, ἰδοὺ Ἀμὰν ἐν τῇ αὐλῇ· εἶπεν δὲ ὁ βασιλεύς Τίς ἐν τῇ αὐλῇ; ὁ δὲ Ἀμὰν εἰσῆλθεν εἰπεῖν τῷ βασιλεῖ κρεμάσαι τὸν Μαρδοχαῖον ἐπὶ τῷ ξύλῳ ᾧ ἡτοίμασεν.","en dè tō̂i pynthánesthai tòn basiléa perì tē̂s eunoías Mardochaíou, idoù Amàn en tē̂i aulē̂i: eîpen dè ho basileús Tís en tē̂i aulē̂i? ho dè Amàn eisē̂lthen eipeîn tō̂i basileî kremásai tòn Mardochaîon epì tō̂i xýlōi hō̂i hētoímasen."],[6,5,"καὶ εἶπαν οἱ διάκονοι τοῦ βασλέως Ἰδοὺ Ἁμὰν ἕστηκεν ἐν τῇ αὐλῇ· καὶ εἶπεν ὁ βασιλεὺς Καλέσατε αὐτόν.","kaì eîpan hoi diákonoi toû basléōs Idoù Hamàn héstēken en tē̂i aulē̂i: kaì eîpen ho basileùs Kalésate autón."],[6,6,"εἶπεν δὲ ὁ βασιλεὺς τῷ Ἀμάν Τί ποιήσω τῷ ἀνθρώπῳ ὃν ἐγὼ θέλω δοξάσαι; εἶπεν δὲ ἐν ἑαυτῷ ὁ Ἀμάν Τίνα θέλει ὁ βασιλεὺς δοξάσαι εἰ μὴ ἐμέ;","eîpen dè ho basileùs tō̂i Amán Tí poiḗsō tō̂i anthrṓpōi hòn egṑ thélō doxásai? eîpen dè en heautō̂i ho Amán Tína thélei ho basileùs doxásai ei mḕ emé?"],[6,7,"εἶπεν δὲ πρὸς τὸν βασιλέα Ἄνθρωπον ὃν ὁ βασιλεὺς θέλει δοξάσαι,","eîpen dè pròs tòn basiléa Ánthrōpon hòn ho basileùs thélei doxásai,"],[6,8,"ἐνεγκάτωσαν οἱ παῖδες τοῦ βασιλέως στολὴν βυσσίνην ἣν ὁ βασιλεὺς περιβάλλεται, καὶ ἵππον ἐφʼ ὃν ὁ βασιλεὺς ἐπιβαίνει,","enenkátōsan hoi paîdes toû basiléōs stolḕn byssínēn hḕn ho basileùs peribálletai, kaì híppon ephʼ hòn ho basileùs epibaínei,"],[6,9,"καὶ δότω ἑνὶ τῶν φίλων τοῦ βασιλέως τῶν ἐνδόξων καὶ στολισάτω τὸν ἄνθρωπον ὃν ὁ βασιλεὺς ἀγαπᾷ, καὶ ἀναβιβασάτω αὐτὸν ἐπὶ τὸν ἵππον, καὶ κηρυσσέτω διὰ τῆς πλατείας τῆς πόλεως λέγων Οὕτως ἔσται παντὶ ἀνθρώπῳ ὃν ὁ βασιλεὺς δοξάζει.","kaì dótō henì tō̂n phílōn toû basiléōs tō̂n endóxōn kaì stolisátō tòn ánthrōpon hòn ho basileùs agapā̂i, kaì anabibasátō autòn epì tòn híppon, kaì kēryssétō dià tē̂s plateías tē̂s póleōs légōn Hoútōs éstai pantì anthrṓpōi hòn ho basileùs doxázei."],[6,10,"εἶπεν δὲ ὁ βασιλεὺς τῷ Ἀμάν Καλῶς ἐλάλησας· οὕτως ποίησον τῷ Μαρδοχαίῳ τῷ Ἰουδαίῳ τῷ θεραπεύοντι ἐν τῇ αὐλῇ, καὶ μὴ παραπεσάτω σου λόγος ὧν ἐλάλησας.","eîpen dè ho basileùs tō̂i Amán Kalō̂s elálēsas: hoútōs poíēson tō̂i Mardochaíōi tō̂i Ioudaíōi tō̂i therapeúonti en tē̂i aulē̂i, kaì mḕ parapesátō sou lógos hō̂n elálēsas."],[6,11,"ἔλαβεν δὲ Ἀμὰν τὴν στολὴν καὶ τὸν ἵππον, καὶ ἐστόλμσεν τὸν Μαρδοχαῖον καὶ ἀνεβίβασεν αὐτὸν ἐπὶ τὸν ἵππον, καὶ διῆλθεν διὰ τῆς πλατείας τῆς πόλεως καὶ ἐκήρυσσεν λέγων Οὕτως ἔσται παντὶ ἀνθρώπῳ ὃν ὁ βασιλεὺς θέλει δοξάσαι.","élaben dè Amàn tḕn stolḕn kaì tòn híppon, kaì estólmsen tòn Mardochaîon kaì anebíbasen autòn epì tòn híppon, kaì diē̂lthen dià tē̂s plateías tē̂s póleōs kaì ekḗryssen légōn Hoútōs éstai pantì anthrṓpōi hòn ho basileùs thélei doxásai."],[6,12,"ἐπέστρεψεν δὲ ὁ Μαρδοχαῖος εἰς τὴν αὐλὴν· Ἀμὰν δὲ ὑπέστρεψεν εἰς τὰ ἴδια λυπούμενος κατὰ κεφαλῆς.","epéstrepsen dè ho Mardochaîos eis tḕn aulḕn: Amàn dè hypéstrepsen eis tà ídia lypoúmenos katà kephalē̂s."],[6,13,"καὶ διηγήσατο Ἀμὰν τὰ συμβεβηκότα αὐτῷ Ζωσάρᾳ τῇ γυναικὶ αὐτοῦ καὶ τοῖς φίλοις· καὶ εἶπαν πρὸς αὐτὸν οἱ φίλοι καὶ ἡ γυνή Εἰ ἐκ γένους Ἰουδαίων Μαρδοχαῖος, ἦρξαι ταπεινοῦσθαι ἐνώπιον αὐτοῦ, πεσὼν πεσῇ· οὐ μὴ δύνῃ αὐτὸν ἀμύνασθαι, ὅτι θεὸς ζῶν μετʼ αὐτοῦ. ¹⁴ ἔτι αὐτῶν λαλούντων παραγίνονται οἱ εὐνοῦχοι ἐπισπεύδοντες τὸν Ἀμὰν ἐπὶ τὸν πότον ὃν ἡτοίμασεν Ἐσθῆήρ.","kaì diēgḗsato Amàn tà symbebēkóta autō̂i Zōsárāi tē̂i gynaikì autoû kaì toîs phílois: kaì eîpan pròs autòn hoi phíloi kaì hē gynḗ Ei ek génous Ioudaíōn Mardochaîos, ē̂rxai tapeinoûsthai enṓpion autoû, pesṑn pesē̂i: ou mḕ dýnēi autòn amýnasthai, hóti theòs zō̂n metʼ autoû. ¹⁴ éti autō̂n laloúntōn paragínontai hoi eunoûchoi epispeúdontes tòn Amàn epì tòn póton hòn hētoímasen Esthē̂ḗr."],[7,1,"Ἑἰσῆλθεν δὲ ὁ βασιλεὺς καὶ Ἀμὰν συνπιεῖν τῇ βασιλίσσῃ.","Heisē̂lthen dè ho basileùs kaì Amàn synpieîn tē̂i basilíssēi."],[7,2,"εἶπεν δὲ ὁ βασιλεὺς Ἐσθὴρ τῇ δευτέρᾳ ἡμέρᾳ ἐν τῷ πότῳ Τί ἐστιν, Ἐσθὴρ βασίλισσα, καὶ τί τὸ αἴτημά σου καὶ τί τὸ ἀξίωμά σου; καὶ ἔστω σοι ἕως τοῦ ἡμίσους τῆς βασιλείας μου.","eîpen dè ho basileùs Esthḕr tē̂i deutérāi hēmérāi en tō̂i pótōi Tí estin, Esthḕr basílissa, kaì tí tò aítēmá sou kaì tí tò axíōmá sou? kaì éstō soi héōs toû hēmísous tē̂s basileías mou."],[7,3,"καὶ ἀποκριθεῖσα εἶπεν Εἰ εὗρον χάριν ἐνώπιον τοῦ βασιλέως, δοθήτω ἡ ψυχὴ τῷ αἰτήματί μου, καὶ ὁ λόγος μου τῷ ἀξιώματί μου.","kaì apokritheîsa eîpen Ei heûron chárin enṓpion toû basiléōs, dothḗtō hē psychḕ tō̂i aitḗmatí mou, kaì ho lógos mou tō̂i axiṓmatí mou."],[7,4,"ἐπράθημεν γὰρ ἐγὼ τε καὶ ὁ λαός μου εἰς ἀπωλίαν καὶ διαρπαγὴν καὶ δουλίαν, ἡμεῖς καὶ τὰ τέκνα ἡμῶν εἰς παῖδας καὶ παιδίσκας, καὶ παρήκουσα· οὐ γὰρ ἄξιος ὁ διάβολος τῆς αὐλῆς τοῦ βασιλέως.","epráthēmen gàr egṑ te kaì ho laós mou eis apōlían kaì diarpagḕn kaì doulían, hēmeîs kaì tà tékna hēmō̂n eis paîdas kaì paidískas, kaì parḗkousa: ou gàr áxios ho diábolos tē̂s aulē̂s toû basiléōs."],[7,5,"εἶπεν δὲ ὁ βασιλεὺς Τίς οὗτος ὅστις ἐτόλμησεν ποιῆσαι τὸ πρᾶγμα τοῦτο;","eîpen dè ho basileùs Tís hoûtos hóstis etólmēsen poiē̂sai tò prâgma toûto?"],[7,6,"εἶπεν δὲ Ἐσθῆρ Ἁνθρωπος ἐχθρὸς Ἀμὰν ὁ πονηρὸς οὗτος. Ἀμὰν δὲ ἐταράχθη ἀπὸ τοῦ βασλέως καὶ τῆς βασιλίσσης.","eîpen dè Esthē̂r Hanthrōpos echthròs Amàn ho ponēròs hoûtos. Amàn dè etaráchthē apò toû basléōs kaì tē̂s basilíssēs."],[7,7,"ὁ δὲ βασιλεὺς ἐξαυέστη ἀπὸ τοῦ συμποσίου εἰς τὸν κῆπον· ὁ δὲ Ἀμὰν παρῃτεῖτο τὴν βασίλισσαν, ἑώρα γὰρ ἑαυτὸν ἐν κακοῖς ὄντα.","ho dè basileùs exauéstē apò toû symposíou eis tòn kē̂pon: ho dè Amàn parēiteîto tḕn basílissan, heṓra gàr heautòn en kakoîs ónta."],[7,8,"ἐπέστρεψεν δὲ ὁ βασιλεὺς ἐκ τοῦ κήπου, Ἀμὰν δὲ ἐπιπεπτώκει ἐπὶ τὴν κλίνην ἀξιῶν τὴν βασίλισσαν· εἶπεν δὲ ὁ βασιλεύς Ὡστε καὶ τὴν γυναῖκα βιάζῃ ἐν τῇ οἰκίᾳ μου; Ἀμὰν δὲ ἀκούσας διετράπη τῷ προσώπῳ.","epéstrepsen dè ho basileùs ek toû kḗpou, Amàn dè epipeptṓkei epì tḕn klínēn axiō̂n tḕn basílissan: eîpen dè ho basileús Hōste kaì tḕn gynaîka biázēi en tē̂i oikíāi mou? Amàn dè akoúsas dietrápē tō̂i prosṓpōi."],[7,9,"εἶπεν δὲ Βουγαθὰν εἶς τῶν εὐνούχων πρὸς τὸν βασιλέα Ἰδοὺ καὶ ξύλον ἡτοίμασεν Ἀμὰν Μαρδοχαίῳ τῷ λαλήσαντι περὶ τοῦ βασιλέως, καὶ ὤρθωται ἐν τοῖς Ἀμὰν ξύλον πηχῶν πεντήκοντα. εἶπεν δὲ ὁ βασιλεύς Σταυρωθήτω ἐπʼ αὐτοῦ.","eîpen dè Bougathàn eîs tō̂n eunoúchōn pròs tòn basiléa Idoù kaì xýlon hētoímasen Amàn Mardochaíōi tō̂i lalḗsanti perì toû basiléōs, kaì ṓrthōtai en toîs Amàn xýlon pēchō̂n pentḗkonta. eîpen dè ho basileús Staurōthḗtō epʼ autoû."],[7,10,"καὶ ἐκρεμάσθη Ἀμὰν ἐπὶ τοῦ ξύλου ὃ ἡτοιμάσθη Μαρδοχαίῳ. καὶ τότε ὁ βασιλεὺς ἐκόπασεν τοῦ θυμοῦ.","kaì ekremásthē Amàn epì toû xýlou hò hētoimásthē Mardochaíōi. kaì tóte ho basileùs ekópasen toû thymoû."],[8,1,"Καὶ ἐν αὐτῇ τῇ ἡμέρᾳ ὁ βασιλεὺς Ἀρταξέρξης ἐδωρήσατο Ἐσθὴρ ὅσα ὑπῆρχεν Ἀμὰν τῷ διαβόλῳ, καὶ Μαρδοχαἲος προσεκλήθη ὑπὸ τοῦ βασιλέως· ὑπέδειξεν γὰρ Ἐσθῆρ ὅτι ἐνοικείωται αὐτῇ.","Kaì en autē̂i tē̂i hēmérāi ho basileùs Artaxérxēs edōrḗsato Esthḕr hósa hypē̂rchen Amàn tō̂i diabólōi, kaì Mardochaìos proseklḗthē hypò toû basiléōs: hypédeixen gàr Esthē̂r hóti enoikeíōtai autē̂i."],[8,2,"ἔλαβεν δὲ ὁ βασιλεὺς τὸν δακτύλιον ὃν ἀφείλατο Ἀμὰν καὶ ἔδωκεν αὐτὸν Μαρδοχαίῳ, καὶ κατέστησεν Ἐσθὴρ Μαρδοχαῖον ἐπὶ πάντων τῶν Ἀμάν.","élaben dè ho basileùs tòn daktýlion hòn apheílato Amàn kaì édōken autòn Mardochaíōi, kaì katéstēsen Esthḕr Mardochaîon epì pántōn tō̂n Amán."],[8,3,"καὶ προσθεῖσα ἐλάλησεν πρὸς τὸν βασιλέα, καὶ προσέπεσεν πρὸς τοὺς πόδας αὐτοῦ, καὶ ἠξίου ἀφελεῖν τὴν Ἀμὰν κακίαν καὶ ὅσα ἐποίησεν τοῖς Ἰουδαίοις.","kaì prostheîsa elálēsen pròs tòn basiléa, kaì prosépesen pròs toùs pódas autoû, kaì ēxíou apheleîn tḕn Amàn kakían kaì hósa epoíēsen toîs Ioudaíois."],[8,4,"ἐξέτεινεν δὲ ὁ βασιλεὺς Ἐσθῆρ τὴν ῥάβδον τὴν χρυσῆν· ἐξηγέρθη δὲ Ἐσθὴρ παρεστηκέναι τῷ βασιλεῖ","exéteinen dè ho basileùs Esthē̂r tḕn rhábdon tḕn chrysē̂n: exēgérthē dè Esthḕr parestēkénai tō̂i basileî"],[8,5,"καὶ εἶπεν Ἐσθήρ Εἰ δοκεῖ σοι καὶ εὗρον χάριν. πεμφθήτω ἀποστραφῆναι τὰ γράμματα τὰ ἀπεσταλμένα ὑπὸ Ἀμάν, τὰ γραφέντα ἀπολέσθαι τοὺς Ἰουδαίους οἵ εἰσιν ἐν τῇ βασιλείᾳ σου.","kaì eîpen Esthḗr Ei dokeî soi kaì heûron chárin. pemphthḗtō apostraphē̂nai tà grámmata tà apestalména hypò Amán, tà graphénta apolésthai toùs Ioudaíous hoí eisin en tē̂i basileíāi sou."],[8,6,"πῶς γὰρ δυνήσομαι ἰδεῖυ τὴν κάκωσιν τοῦ λαοῦ μου, καὶ πῶς δυνήσομαι σωθῆναι ἐν τῇ ἀπωλείᾳ τῆς πατρίδος μου;","pō̂s gàr dynḗsomai ideîy tḕn kákōsin toû laoû mou, kaì pō̂s dynḗsomai sōthē̂nai en tē̂i apōleíāi tē̂s patrídos mou?"],[8,7,"καὶ εἶπεν ὁ βασιλεὺς πρὸς Ἐσθήρ Εἰ πάντα τὰ ὑπάρχοντα Ἀμὰν ἔδωκα καὶ ἐχαρισάμην σοι, καὶ αὐτὸν ἐκρέμασα ἐπὶ ξύλου ὅτι τὰς χεῖρας ἐπήνεγκε τοῖς Ἰουδαίοις, τί ἔτι ἐπιζητεῖς;","kaì eîpen ho basileùs pròs Esthḗr Ei pánta tà hypárchonta Amàn édōka kaì echarisámēn soi, kaì autòn ekrémasa epì xýlou hóti tàs cheîras epḗnenke toîs Ioudaíois, tí éti epizēteîs?"],[8,8,"γράψατε καὶ ὑμεῖς ἐκ τοῦ ὀνόματός μου ὡς δοκεῖ ὑμῖν, καὶ σφραγίσατε τῷ δακτυλίῳ μου· ὅσα γὰρ γράφεται τοῦ βασιλέως ἐπιτάξαντος καὶ σφραγισθῇ τῷ δακτυλίῳ μου, οὐκ ἔστιν αὐτοῖς ἀντειπεῖν.","grápsate kaì hymeîs ek toû onómatós mou hōs dokeî hymîn, kaì sphragísate tō̂i daktylíōi mou: hósa gàr gráphetai toû basiléōs epitáxantos kaì sphragisthē̂i tō̂i daktylíōi mou, ouk éstin autoîs anteipeîn."],[8,9,"ἐκλήθησαν δὲ οἱ γραμματεῖς ἐν τῷ πρώτῳ μηνὶ ὅς ἐστι Νισά, τρίτῃ καὶ εἰκάδι τοῦ αὐτοῦ ἔτους, καὶ ἐγράφη τοῖς Ἰουδαίοις ὅσα ἐνετείλατο τοῖς οἰκονόμοις καὶ τοῖς ἄρχουσιν τῶν σατραπῶν ἀπὸ τῆς Ἰνδικῆς ἕως τῆς Αἰθιοπίας, ἑκατὸν εἲκοσι ἑπτὰ σατραπίαις κατὰ χώραν καὶ χώραν, κατὰ τὴν ἑαυτῶν λέξιν.","eklḗthēsan dè hoi grammateîs en tō̂i prṓtōi mēnì hós esti Nisá, trítēi kaì eikádi toû autoû étous, kaì egráphē toîs Ioudaíois hósa eneteílato toîs oikonómois kaì toîs árchousin tō̂n satrapō̂n apò tē̂s Indikē̂s héōs tē̂s Aithiopías, hekatòn eìkosi heptà satrapíais katà chṓran kaì chṓran, katà tḕn heautō̂n léxin."],[8,10,"ἐγράφη δὲ διὰ τοῦ βασιλέως καὶ ἐσφραγίσθη τῷ δακτυλίῳ αὐτοῦ, καὶ ἐξαπέστειλαν τὰ γράμματα διὰ βιβλιαφόρων,","egráphē dè dià toû basiléōs kaì esphragísthē tō̂i daktylíōi autoû, kaì exapésteilan tà grámmata dià bibliaphórōn,"],[8,11,"ὡς ἐπέταξεν αὐτοῖς χρῆσθαι τοῖς νόμοις αὐτῶν ἐν πάσῃ τῇ πόλει, βοηθῆσαί τε αὑτοῖς καὶ χρῆσθαι τοῖς ἀντιδίκοις αὐτῶν καὶ τοῖς ἀντικειμένοις αὐτῶν ὡς βούλονται,","hōs epétaxen autoîs chrē̂sthai toîs nómois autō̂n en pásēi tē̂i pólei, boēthē̂saí te hautoîs kaì chrē̂sthai toîs antidíkois autō̂n kaì toîs antikeiménois autō̂n hōs boúlontai,"],[8,12,"ἐν ἡμέρᾳ μιᾷ ἐν πάσῃ τῇ βασιλείᾳ Ἀρταξέρξου, τῇ τρισκαιδεκάτῃ τοῦ δωδεκάτου μηνὸς ὅς ἐστιν Ἄδαρ.","en hēmérāi miā̂i en pásēi tē̂i basileíāi Artaxérxou, tē̂i triskaidekátēi toû dōdekátou mēnòs hós estin Ádar."],[8,"1a","Ὧν ἐστιν ἀντίγραφον τῆς ἐπιστολῆς τὰ ὑπογεγραμμένα Βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἀπὸ τῆς Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑκατὸν εἴκοσι ἑπτὰ σατραπείαις χαορῶν ἄρχουσι καὶ τοῖς τὰ ἡμέτερα φρονοῦσι χαίρειν.","Hō̂n estin antígraphon tē̂s epistolē̂s tà hypogegramména Basileùs mégas Artaxérxēs toîs apò tē̂s Indikē̂s héōs tē̂s Aithiopías hekatòn eíkosi heptà satrapeíais chaorō̂n árchousi kaì toîs tà hēmétera phronoûsi chaírein."],[8,"2a","πολλοὶ τῇ πλείστῃ τῶν εὐεργετούνταων χρηστότητι πυκνότερον τιμώμενοι μεῖζον ἐφρόνησαν,","polloì tē̂i pleístēi tō̂n euergetoúntaōn chrēstótēti pyknóteron timṓmenoi meîzon ephrónēsan,"],[8,"3a","καὶ οὐ μόνον τοὺς ὑποτεταγμένους ἡμῖν ζητοῦσι κακοποιεῖν, τόν τε κόρον οὐ δυνάμενοι φέρειν καὶ τοῖς ἑαυτῶν εὐεργέταις ἐπιχειροῦσι μηχανᾶσθαι·","kaì ou mónon toùs hypotetagménous hēmîn zētoûsi kakopoieîn, tón te kóron ou dynámenoi phérein kaì toîs heautō̂n euergétais epicheiroûsi mēchanâsthai:"],[8,"4a","καὶ τὴν εὐχαριστίαν οὐ μόνον ἐκ τῶν ἀνθρώπων ἀνταναιροῦντες, ἀλλὰ καὶ τοῖς τῶν ἀπειραγάθων κόμποις ἐπαρθέντες, τοῦ τὰ πάντα κατοπτεύοντος ἀεὶ θεοῦ μισοπόνηρον ὑπολαμβάνουσιν ἐκφεύξεσθαι δίκην.","kaì tḕn eucharistían ou mónon ek tō̂n anthrṓpōn antanairoûntes, allà kaì toîs tō̂n apeiragáthōn kómpois eparthéntes, toû tà pánta katopteúontos aeì theoû misopónēron hypolambánousin ekpheúxesthai díkēn."],[8,"5a","πολλάκις δὲ καὶ πολλοὺς τῶν ἐπʼ ἐξουσίαις τεταγμένων τῶν πιστευθέντων χειρίζειν φίλων τὰ πράγματα παραμυθία μετόχους αἱμάτων ἀθῴων καταστήσασα περιέβαλε συμφοραῖς ἀνηκέστοις,","pollákis dè kaì polloùs tō̂n epʼ exousíais tetagménōn tō̂n pisteuthéntōn cheirízein phílōn tà prágmata paramythía metóchous haimátōn athṓiōn katastḗsasa periébale symphoraîs anēkéstois,"],[8,"6a","τῷ τῆς κακοηθείας ψευδεῖ παραλογισμῷ παραλογισαμένωυ τὴν τῶν ἐπικρατούντων ἀκέραιον εὐγνααωμοσύνην.","tō̂i tē̂s kakoētheías pseudeî paralogismō̂i paralogisaménōy tḕn tō̂n epikratoúntōn akéraion eugnaaōmosýnēn."],[8,"7a","σκοπεῖν δὲ ἔξεστιν, οὐ τοσοῦτον ἐκ τῶν παλαιοτέεων ὡς παρεδώκαμεν ἱστοριῶν, ὅσα ἐστὶν παρὰ πόδας ὑμᾶς ἐκζητοῦντας ἀνοσίως συντετελεσμένα τῆ τῶυ ἀνάξια δυναστευόντων λοιμότητι,","skopeîn dè éxestin, ou tosoûton ek tō̂n palaiotéeōn hōs paredṓkamen historiō̂n, hósa estìn parà pódas hymâs ekzētoûntas anosíōs syntetelesména tē̂ tō̂y anáxia dynasteuóntōn loimótēti,"],[8,"8a","καὶ προσέχειν εἰς τὰ μετὰ ταῦτα, εἰς τὸ τὴν βασιλείαν ἀτάραχον τοῖς πᾶσιν ἀνθρώποις μετʼ εἰρήνης παρεξόμεθα,","kaì proséchein eis tà metà taûta, eis tò tḕn basileían atárachon toîs pâsin anthrṓpois metʼ eirḗnēs parexómetha,"],[8,"9a","χρώμενοι ταῖς μεταβολαῖς, τὰ δὲ ὑπὸ τὴν ὄψιν ἐρχόμενα διακρίνοντες ἀεὶ μετʼ ἐπιεικεστέρας ἀπαντήσεως.","chrṓmenoi taîs metabolaîs, tà dè hypò tḕn ópsin erchómena diakrínontes aeì metʼ epieikestéras apantḗseōs."],[8,"10a","ὡς γὰρ Ἀμὰν Ἀμαδάθου Μακεδὼν ταῖς ἀληθείαις ἀλλότριος τοῦ τῶν Περκῶν αἵματος καὶ πολὺ διεστηκὼς τῆς ἡμετέρας χρηστότητος, ἐπιξενωθεὶς ἡμῖν","hōs gàr Amàn Amadáthou Makedṑn taîs alētheíais allótrios toû tō̂n Perkō̂n haímatos kaì polỳ diestēkṑs tē̂s hēmetéras chrēstótētos, epixenōtheìs hēmîn"],[8,"11a","ἔτυχεν ἧς ἔχομεν πρὸς πᾶν ἔθνος φιλανθρωπίας ἐπὶ τοσοῦτον ὥστε ἀναγορεύεσθαι ἡμῶν πατέρα καὶ προσκυνούμενον ὑπὸ πάντων τὸ δεύτερον τοῦ βασιλικοῦ θρόνου πρόσωπον διατελεῖν·","étychen hē̂s échomen pròs pân éthnos philanthrōpías epì tosoûton hṓste anagoreúesthai hēmō̂n patéra kaì proskynoúmenon hypò pántōn tò deúteron toû basilikoû thrónou prósōpon diateleîn:"],[8,"12a","οὐκ ἐνέγκας δὲ τὴν ὑπερηφονίαν ἐπετήδευσεν τῆς ἀρχῆς στερῆσαι ἡμᾶς καὶ τοῦ πνεύματος,","ouk enénkas dè tḕn hyperēphonían epetḗdeusen tē̂s archē̂s sterē̂sai hēmâs kaì toû pneúmatos,"],[8,"13a","τόν τε ἡμέτερον σαωτῆρα καὶ διὰ παντὸς εὐεργέτην Μαρδοχαῖον καὶ τὴν ἄμεμπτον τῆς βασιλείας κοινωνὸν Ἐσθὴρ σὺν παντὶ τῷ τούτων ἔθνει πολυπλόκοις μεθόδων παραλογισμοῖς αἰτησάμενος εἰς ἀπωλίαν·","tón te hēméteron saōtē̂ra kaì dià pantòs euergétēn Mardochaîon kaì tḕn ámempton tē̂s basileías koinōnòn Esthḕr sỳn pantì tō̂i toútōn éthnei polyplókois methódōn paralogismoîs aitēsámenos eis apōlían:"],[8,"14a","διὰ γὰρ τῶν τρόπων τούτων ᾠἡθη λαβὼν ἡμᾶς ἐρήμους τὴν τῶν Περσῶν ἐπικράτησιν εἰς τοὺς Μακεδόνας μετάξαι.","dià gàr tō̂n trópōn toútōn ōihēthē labṑn hēmâs erḗmous tḕn tō̂n Persō̂n epikrátēsin eis toùs Makedónas metáxai."],[8,"15a","ἡμεῖς δὲ τοὺς ὑπὸ τοῦ τρισαλιτηρίου παραδεδομένους εἰς ἀφανισμὸν Ἰουδαίους εὺρίσκομεν οὐ κακούργους ὄντας, δικαιοτάτοις δὲ πολιτευομένους νόμοις,","hēmeîs dè toùs hypò toû trisalitēríou paradedoménous eis aphanismòn Ioudaíous eùrískomen ou kakoúrgous óntas, dikaiotátois dè politeuoménous nómois,"],[8,"16a","ὄντας δὲ υἱοὺς τοῦ ὑψίστου μεγίστου ζῶντος θεοῦ τοῦ κατευθύνοντος ἡμῖν τε καὶ τοῖς προγόνοις ἡμῶν τὴν βασιλείαν ἐν τῆ καλλίστῃ διαθέσει.","óntas dè hyioùs toû hypsístou megístou zō̂ntos theoû toû kateuthýnontos hēmîn te kaì toîs progónois hēmō̂n tḕn basileían en tē̂ kallístēi diathései."],[8,"17a","καλῶς οὖν ποιήσετε μὴ προσχρησάμενοι τοῖς ὑπὸ Ἀμὰν Ἀμαδάθου ἀποσταλεῖσι γράμμασιν,","kalō̂s oûn poiḗsete mḕ proschrēsámenoi toîs hypò Amàn Amadáthou apostaleîsi grámmasin,"],[8,"18a","διὰ τὸ αὐτὸν τὸν ταῦτα ἐξεργασάμενον πρὸς ταῖς Σούσων πύλαις ἐσταυρῶσθαι σὺν τῇ πανοικίᾳ, τὴν καταξίαν τοῦ τὰ πάντα ἐπικρατοῦντος θεοῦ διὰ τάχους ἀποδόντος αὐτῷ κρίσιν·","dià tò autòn tòn taûta exergasámenon pròs taîs Soúsōn pýlais estaurō̂sthai sỳn tē̂i panoikíāi, tḕn kataxían toû tà pánta epikratoûntos theoû dià táchous apodóntos autō̂i krísin:"],[8,"19a","τὸ δὲ ἀντίγραφον τῆς ἐπιστολῆς ταύτης ἐκθέντες ἐν παντὶ τόπῳ μετὰ παρρησίας, ἐᾷν τοὺς Ἰουδαίους χρῆσθαι τοῖς ἑαυτῶν νομίμοις,","tò dè antígraphon tē̂s epistolē̂s taútēs ekthéntes en pantì tópōi metà parrēsías, eā̂in toùs Ioudaíous chrē̂sthai toîs heautō̂n nomímois,"],[8,"20a","καὶ συνεπισχύειν αὐτοῖς ὅπως τοὺς ἐν καιρῷ θλίψεως ἐπιθεμένους αὐτοῖς ἀμύνωνται τῇ τρισκαιδεκἀτῃ τοῦ δωδεκάτου μηνὸς Αδὰρ τῇ αὐτῇ ἡμέρᾳ·","kaì synepischýein autoîs hópōs toùs en kairō̂i thlípseōs epitheménous autoîs amýnōntai tē̂i triskaidekatēi toû dōdekátou mēnòs Adàr tē̂i autē̂i hēmérāi:"],[8,"21a","ταύτην γὰρ ὁ πάντα δυναστεύων θεὸς ἀντʼ ὀλεθρίας τοῦ ἐκλεκτοῦ γένους ἐποίησεν αὐτοῖς εὐφροσύνην.","taútēn gàr ho pánta dynasteúōn theòs antʼ olethrías toû eklektoû génous epoíēsen autoîs euphrosýnēn."],[8,"22a","καὶ ὑμεῖς οὖν ἐν ταῖς ἐπωνύμοις ὑμῶν ἑορταῖς ἐπί σημον ἡμέραν μετὰ πάσης εὐωχίας ἄγετε,","kaì hymeîs oûn en taîs epōnýmois hymō̂n heortaîs epí sēmon hēméran metà pásēs euōchías ágete,"],[8,"23a","ὅπως καὶ νῦν καὶ μετὰ ταῦτα σωτηρία ἡμῖν καὶ τοῖς εὐνοοῦσιν Πέρσαις, τοῖς δὲ ἡμῖν ἐπιβουλεύουσιν μνημόσυνον τῆς ἀπωλείας.","hópōs kaì nŷn kaì metà taûta sōtēría hēmîn kaì toîs eunooûsin Pérsais, toîs dè hēmîn epibouleúousin mnēmósynon tē̂s apōleías."],[8,"24a","πᾶσα δὲ πόλις ἢ χώρα τὸ σύνολον ἥτις κατὰ ταῦτα μὴ ποιήσῃ δόρατι καὶ πυρὶ καταναλωθήσεται μετʼ ὀργῆς· οὐ μόνον ἀνθρώποις ἄβατος, ἀλλὰ καὶ θηρίοις καὶ πετεινοῖς εἰς τὸν ἀπαντα χρόνον ἔχθιστος κατασταθήσεται.","pâsa dè pólis ḕ chṓra tò sýnolon hḗtis katà taûta mḕ poiḗsēi dórati kaì pyrì katanalōthḗsetai metʼ orgē̂s: ou mónon anthrṓpois ábatos, allà kaì thēríois kaì peteinoîs eis tòn apanta chrónon échthistos katastathḗsetai."],[8,13,"τὰ δὲ ἀντίγραφα ἐκτιθέσθωσαν ὀφθαλμοφανῶς ἐν πάσῃ τῇ βασιλεία, ἑτοίμους τε εἶναι πάντας τοὺς Ἰουδαίους εἰς ταύτην τὴν ἡμέραν πολεμῆσαι αὐτῶν τοὺς ὑπεναντίους.","tà dè antígrapha ektithésthōsan ophthalmophanō̂s en pásēi tē̂i basileía, hetoímous te eînai pántas toùs Ioudaíous eis taútēn tḕn hēméran polemē̂sai autō̂n toùs hypenantíous."],[8,14,"Οἱ μἐν οὖν ἱππεῖς ἐξνῆλθον σπεύδοντες τὰ ὑπὸ τοῦ βασιλέως λεγόμενα ἐπιτελεῖν· ἐξετέθη δὲ τὸ πρόσταγμα καὶ ἐν Σούσοις.","Hoi men oûn hippeîs exnē̂lthon speúdontes tà hypò toû basiléōs legómena epiteleîn: exetéthē dè tò próstagma kaì en Soúsois."],[8,15,"ὁ δὲ Μαρδοχαῖος ἐξῆλθεν ἐστολισμένος τὴν βασιλικὴν στολὴν καὶ στέφανον ἔχων χρυσοῦν καὶ διάδημα βύσσινον πορφυροῦν· ἰδόντες δὲ οἱ ἐν Σούσοις ἐχάρη· σαν.","ho dè Mardochaîos exē̂lthen estolisménos tḕn basilikḕn stolḕn kaì stéphanon échōn chrysoûn kaì diádēma býssinon porphyroûn: idóntes dè hoi en Soúsois echárē: san."],[8,16,"τοῖς δὲ Ἰουδαίοις ἐγένετο φῶς καὶ εὐφροσύνη","toîs dè Ioudaíois egéneto phō̂s kaì euphrosýnē"],[8,17,"κατὰ πόλιν καὶ χὤραν οὗ ἂν ἐξετέθη τὸ πρόσταγμα, οὗ ἂν ἐξετέθη τὸ ἔκθεμα· χαρὰ καὶ εὐφροσύνη τοῖς Ἰουδαίοις, κώθων καὶ εὐφροσύνη· καὶ πολλοὶ τῶν ἐθνῶν περιετέμοντο καὶ ἰουδάιζον διὰ τὸν φόβον τῶν Ἰουδαίων.","katà pólin kaì chṓran hoû àn exetéthē tò próstagma, hoû àn exetéthē tò ékthema: charà kaì euphrosýnē toîs Ioudaíois, kṓthōn kaì euphrosýnē: kaì polloì tō̂n ethnō̂n perietémonto kaì ioudáizon dià tòn phóbon tō̂n Ioudaíōn."],[9,1,"Ἐν γὰρ τῷ δωδεκάτῳ μηνὶ τρισκαιδεκάτῃ τοῦ μηνός, ὅς ἐστιν Ἀδάρ, παρῆν τὰ γράμματα τά γραφέντα ὑπὸ τοῦ βασιλέως.","En gàr tō̂i dōdekátōi mēnì triskaidekátēi toû mēnós, hós estin Adár, parē̂n tà grámmata tá graphénta hypò toû basiléōs."],[9,2,"ἐν αὐτῇ τῇ ἡμέρᾳ ἀπώλοντο οἱ ἀντικείμενοι τοῖς Ἰουδαίοις· οὐδεὶς γὰρ ἀντέστη, φοβούμενος αὐτούς.","en autē̂i tē̂i hēmérāi apṓlonto hoi antikeímenoi toîs Ioudaíois: oudeìs gàr antéstē, phoboúmenos autoús."],[9,3,"οἱ γὰρ ἄρχοντες τῶν σατραπῶν καὶ οἱ τύραννοι καὶ οἱ βασιλικοὶ γραμματεῖς ἐτίμων τοὺς Ἰουδαίους· ὁ γὰρ φοβος Μαρδοχαίου ἐνέκειτο αὐτοῖς.","hoi gàr árchontes tō̂n satrapō̂n kaì hoi týrannoi kaì hoi basilikoì grammateîs etímōn toùs Ioudaíous: ho gàr phobos Mardochaíou enékeito autoîs."],[9,4,"προσέπεσεν γὰρ τὸ πρόσταγμα τοῦ βασιλέως ὀνομασθῆναι ἐν πάσῃ τῇ βασιλείᾳ.","prosépesen gàr tò próstagma toû basiléōs onomasthē̂nai en pásēi tē̂i basileíāi."],[9,6,"καὶ ἐν αὐτῇ τῇ πόλει ἀπέκτειναν οἱ Ἰουδαῖοι ἄνδρας πεντακοσίους,","kaì en autē̂i tē̂i pólei apékteinan hoi Ioudaîoi ándras pentakosíous,"],[9,7,"τόν τε Φαρσὰν καὶ Νεσταὶν καὶ Δελφὼν καὶ Φασγὰ","tón te Pharsàn kaì Nestaìn kaì Delphṑn kaì Phasgà"],[9,8,"καὶ Φαραδάθα καὶ Βαρσά καὶ Σαρβαχὰ","kaì Pharadátha kaì Barsá kaì Sarbachà"],[9,9,"καὶ Μαρμασιμά καὶ Ῥουφαῖον καὶ Ἀρσαῖον καὶ Ζαβουθαῖιν,","kaì Marmasimá kaì Rhouphaîon kaì Arsaîon kaì Zabouthaîin,"],[9,10,"τοὺς δέκα υἱοὺς Ἀμὰν Ἀμαδάθου Βουγαίου τοῦ ἐχθροῦ τῶν Ἰουδαίων, καὶ διήρπασαν","toùs déka hyioùs Amàn Amadáthou Bougaíou toû echthroû tō̂n Ioudaíōn, kaì diḗrpasan"],[9,11,"ἐν αὐτῇ τῇ ἡμέρᾳ· ἐπεδόθη τε ὁ ἀριθμὸς τῷ βασιλεῖ τῶν ἀπολωλότων ἐν Σούσοις.","en autē̂i tē̂i hēmérāi: epedóthē te ho arithmòs tō̂i basileî tō̂n apolōlótōn en Soúsois."],[9,12,"εἶπεν δὲ ὁ βασιλεὺς πρὸς Ἐσθῆρ Ἀπώλεσαν οἱ Ἰουδαῖοι ἐν Σούσοις τῇ πόλει ἄνδρας πεντακοσίους· ἐν δὲ τῇ περιχώρῳ πῶς οἴει ἐχρήσαντο; τί οὖν ἀξιοῖς ἔτι καὶ ἔσται σοι;","eîpen dè ho basileùs pròs Esthē̂r Apṓlesan hoi Ioudaîoi en Soúsois tē̂i pólei ándras pentakosíous: en dè tē̂i perichṓrōi pō̂s oíei echrḗsanto? tí oûn axioîs éti kaì éstai soi?"],[9,13,"καὶ εἶπεν Ἐσθὴρ τῷ βασιλεῖ Δοθήτω τοῖς Ἰουδαίοις χρῆσθαι ὡσαύτως τὴν αὕριον, ὥστε τοὺς δέκα υἱοὺς κρεμάσαι Ἀμάν.","kaì eîpen Esthḕr tō̂i basileî Dothḗtō toîs Ioudaíois chrē̂sthai hōsaútōs tḕn haúrion, hṓste toùs déka hyioùs kremásai Amán."],[9,14,"καὶ ἐπέτρεψεν οὕτως γενέσθαι, καὶ ἐξέθηκε τοῖς Ἰουδαίοις τῆς πόλεως τά σώματα τῶν υἱῶν Ἀμὰν κρεμάσαι.","kaì epétrepsen hoútōs genésthai, kaì exéthēke toîs Ioudaíois tē̂s póleōs tá sṓmata tō̂n hyiō̂n Amàn kremásai."],[9,15,"καὶ συνήχθησαν οἱ Ἰουδαῖοι ἐν Σούσοις τῇ τεσσαρεσκαιδεκάτῃ τοῦ Ἄδὰρ καὶ ἀπέκτειναν ἄνδρας τριακοσίους, καὶ οὐδὲν διήρπασαν.","kaì synḗchthēsan hoi Ioudaîoi en Soúsois tē̂i tessareskaidekátēi toû Ádàr kaì apékteinan ándras triakosíous, kaì oudèn diḗrpasan."],[9,16,"οἱ δὲ λοιποὶ τῶν Ἰουδαίων οἱ ἐν τῇ βασιλείᾳ συνήχθησαν καὶ ἑαυτοῖς ἐβοήθουν, καὶ ἀνεπαύσαντο ἀπὸ τῶν πολεμίων· ἀπώλεσαν γάρ αὐτῶν μυρίους πεντακισχιλίους τῇ τρισκαιδεκάτῃ τοῦ Ἀδάρ, καὶ οὐδὲν διήρπασαν.","hoi dè loipoì tō̂n Ioudaíōn hoi en tē̂i basileíāi synḗchthēsan kaì heautoîs eboḗthoun, kaì anepaúsanto apò tō̂n polemíōn: apṓlesan gár autō̂n myríous pentakischilíous tē̂i triskaidekátēi toû Adár, kaì oudèn diḗrpasan."],[9,17,"καὶ ἀνεπαύσαντο τῇ τεσσαρεσκαιδεκάτῃ τοῦ αὐτοῦ μηνός, καὶ ἦγον αὐτὴν ἡμέραν ἀναπαύσεως μετά χαρᾶς καὶ εὐφροσύνης.","kaì anepaúsanto tē̂i tessareskaidekátēi toû autoû mēnós, kaì ē̂gon autḕn hēméran anapaúseōs metá charâs kaì euphrosýnēs."],[9,18,"οἱ δὲ Ἰουδαῖοι οἱ ἐν Σούσοις τῇ πόλει συνήχθησαν καὶ τῇ τεσσαρεσκαιδεκάτῃ καὶ οὐκ ἀνεπαύσαντο· ἦγον δὲ καὶ τὴν πεντεκαιδεκάτην μετὰ χαρᾶς καὶ εὐφροσύνης.","hoi dè Ioudaîoi hoi en Soúsois tē̂i pólei synḗchthēsan kaì tē̂i tessareskaidekátēi kaì ouk anepaúsanto: ē̂gon dè kaì tḕn pentekaidekátēn metà charâs kaì euphrosýnēs."],[9,19,"διὰ τοῦτο οὗν οἱ Ἰουδαῖοι οἱ διεσπαρμένοι ἐν πάσῃ χώρᾳ τῇ ἔξω ἄγουσιν τὴν τεσσαρεσκαιδεκάτην τοῦ Ἄδαρ ἡμέραν ἀγαθὴν μετ εὐφροσύνης, ἀποστέλλοντες μερίδας ἕκαστος τῷ πλησίον. οἱ δὲ κατοικοῦντες ἐν ταῖς μητροπόλεσιν καὶ τὴν ε' καὶ ι' τοῦ Ἄδὰρ εὐφροσύνην ἀγαθὴν ἄγουσιν ἐξαποστέλλοντες μερίδας καὶ τοῖς πλησίον.","dià toûto hoûn hoi Ioudaîoi hoi diesparménoi en pásēi chṓrāi tē̂i éxō ágousin tḕn tessareskaidekátēn toû Ádar hēméran agathḕn met euphrosýnēs, apostéllontes merídas hékastos tō̂i plēsíon. hoi dè katoikoûntes en taîs mētropólesin kaì tḕn e' kaì i' toû Ádàr euphrosýnēn agathḕn ágousin exapostéllontes merídas kaì toîs plēsíon."],[9,20,"Ἔγραψεν δὲ Μαρδοχαῖος τοὺς λόγους τούτους εἰς βιβλίον, καὶ ἐξαπέστειλεν τοῖς Ἰουδαίοις ὅσοι ἤσαν ἐν τῇ Ἀρταξέρξου βασιλεία, τοῖς ἐγγὺς καὶ τοῖς μακράν,","Égrapsen dè Mardochaîos toùs lógous toútous eis biblíon, kaì exapésteilen toîs Ioudaíois hósoi ḗsan en tē̂i Artaxérxou basileía, toîs engỳs kaì toîs makrán,"],[9,21,"στῆσαι τὰς ἡμέρας ταύτας ἀγαθάς, ἄγειν τε τὴν τεσσαρεσκαιδεκάτην καὶ τὴν πεντεκαιδεκάτην τοῦ Ἀδαρ·","stē̂sai tàs hēméras taútas agathás, ágein te tḕn tessareskaidekátēn kaì tḕn pentekaidekátēn toû Adar:"],[9,22,"ἐν γὰρ ταύταις ταῖς ἡμέραις ἀνεπαύσαντο οἱ Ἰουδαῖοι ἀπὸ τῶν ἐχθρῶν αὐτῶν· καὶ τὸν μῆνα ἐν ᾧ ἐστράφη αὐτοῖς, ὃς ἦν Ἀδάρ, ἀπὸ πένθους εἰς χαρὰν καὶ ἀπὸ ὀδύνης εἰς ἀγαθὴν ἡμέραν, ἄγειν ὅλον ἀγαθὰς ἡμέρας γάμαων καὶ εὐφροσύνης, ἐξαποστέλλοντας μερίδας τοῖς φίλοις καὶ τοῖς πτωχοῖς.","en gàr taútais taîs hēmérais anepaúsanto hoi Ioudaîoi apò tō̂n echthrō̂n autō̂n: kaì tòn mē̂na en hō̂i estráphē autoîs, hòs ē̂n Adár, apò pénthous eis charàn kaì apò odýnēs eis agathḕn hēméran, ágein hólon agathàs hēméras gámaōn kaì euphrosýnēs, exapostéllontas merídas toîs phílois kaì toîs ptōchoîs."],[9,23,"καὶ προσεδέξαντο οἱ Ἰουδαῖοι καθὼς ἔγραψεν αὐτοῖς ὁ Μαρδοχαῖος,","kaì prosedéxanto hoi Ioudaîoi kathṑs égrapsen autoîs ho Mardochaîos,"],[9,24,"πῶς Ἀμὰν Ἀμαδάθου ὁ Μακεδὼν ἐπολέμει αὐτούς, καθὼς ἔθετο ψήφισμα καὶ κλῆρον ἀφανίσαι αὐτούς,","pō̂s Amàn Amadáthou ho Makedṑn epolémei autoús, kathṑs étheto psḗphisma kaì klē̂ron aphanísai autoús,"],[9,25,"καὶ ὡς εἰσῆλθεν πρὸς τὸν βασιλέα λέγων κρεμάσαι τὸν Μαρδοχαῖον· ὅσα δὲ ἐπεχείρησεν ἐπάξαι ἐπὶ τοὺς Ἰουδαίους κακά ἐπʼ αὐτὸν ἐγένοντο, καὶ ἐκρεμάσθη αὐτὸς καὶ τὰ τέκνα αὐτοῦ.","kaì hōs eisē̂lthen pròs tòn basiléa légōn kremásai tòn Mardochaîon: hósa dè epecheírēsen epáxai epì toùs Ioudaíous kaká epʼ autòn egénonto, kaì ekremásthē autòs kaì tà tékna autoû."],[9,26,"διὰ τοῦτο ἐπεκλήθησαν αἱ ἡμέραι αὗται Φρουραὶ διὰ τοὺς κλήρους, ὅτι τῇ διαλέκτῳ αὐτῶν καλοῦνται Φρουραί, διὰ τοὺς λόγους τῆς ἐπιστολῆς ταύτης, καὶ ὅσα πεπόνθασιν διὰ ταῦτα καὶ ὅσα αὐτοῖς ἐγένετο","dià toûto epeklḗthēsan hai hēmérai haûtai Phrouraì dià toùs klḗrous, hóti tē̂i dialéktōi autō̂n kaloûntai Phrouraí, dià toùs lógous tē̂s epistolē̂s taútēs, kaì hósa pepónthasin dià taûta kaì hósa autoîs egéneto"],[9,27,"καὶ ἔστησεν· καὶ προσεδέχοντο οἱ Ἰουδαῖι ἐφʼ ἑαυτοῖς καὶ ἐπὶ τῷ σπέρματι αὐτῶν καὶ ἐπὶ τοῖς προστεθειμένοις ἐπʼ αὐτῶν, οὐδέ μὴν ἄλλως χρήσονται. αἱ δὲ ἡμέραι αὗται μνημόσυνον ἐπιτελούμενον κατὰ γενεὰν καὶ γενεὰν καὶ πόλιν καὶ πατριάν καὶ χώραν.","kaì éstēsen: kaì prosedéchonto hoi Ioudaîi ephʼ heautoîs kaì epì tō̂i spérmati autō̂n kaì epì toîs prostetheiménois epʼ autō̂n, oudé mḕn állōs chrḗsontai. hai dè hēmérai haûtai mnēmósynon epiteloúmenon katà geneàn kaì geneàn kaì pólin kaì patrián kaì chṓran."],[9,28,"αἰ δὲ ἡμέραι αὗται τῶν Φρουραὶ ἀχθήσονται εἰς τὸν ἃπαντα χρόνον, καὶ τὸ μνημόσυνον αὐτῶν οὐ μὴ ἐκλίπῃ ἐκ τῶν γενεῶν.","ai dè hēmérai haûtai tō̂n Phrouraì achthḗsontai eis tòn hàpanta chrónon, kaì tò mnēmósynon autō̂n ou mḕ eklípēi ek tō̂n geneō̂n."],[9,29,"καὶ ἔγραψεν Ἐσθῆρ ἡ βασίλισσα θυγάτηρ Ἀμιναδὰβ καὶ Μαρδοχαῖος ὁ Ἰουδαῖος ὅσα ἐποίησαν τό τε στερέωμα τῆς ἐπιστολῆς τῶν Φρουραί.","kaì égrapsen Esthē̂r hē basílissa thygátēr Aminadàb kaì Mardochaîos ho Ioudaîos hósa epoíēsan tó te steréōma tē̂s epistolē̂s tō̂n Phrouraí."],[9,30,"καὶ Μαρδοχαῖος καὶ Ἐσθὴρ ἡ βασίλισσα ἔστησαν ἑαυτοῖς καθʼ ἑαυτῶν, καὶ τότε στήσαντες κατὰ τῆς ὑγιείας ἑαυτῶν καὶ τὴν βουλὴν αὐτῶν.","kaì Mardochaîos kaì Esthḕr hē basílissa éstēsan heautoîs kathʼ heautō̂n, kaì tóte stḗsantes katà tē̂s hygieías heautō̂n kaì tḕn boulḕn autō̂n."],[9,31,"καὶ Ἐσθὴρ λόγῳ ἔστησεν εἰς τὸν αἰῶνα, καὶ ἐγράφη εἰς μνημόσυνον.","kaì Esthḕr lógōi éstēsen eis tòn aiō̂na, kaì egráphē eis mnēmósynon."],[10,"1a","Ἔγραψεν δὲ ὁ βασιλεὺς ἐπὶ τὴν βασιλείαν τῆς γῆς καὶ τῆς θαλασσης.","Égrapsen dè ho basileùs epì tḕn basileían tē̂s gē̂s kaì tē̂s thalassēs."],[10,"2a","καὶ τὴν ἰσχὺν αὐτοῦ καὶ ἀνδραγαθίαν, πλοῦτόν τε καὶ δόξαν τῆς βασιλείας αὐτοῦ, ἰδοὺ γέγραπται ἐν βιβλίῳ βασιλέων Ιερσῶν καὶ Μήδων εἰς μνημόσυνον.","kaì tḕn ischỳn autoû kaì andragathían, ploûtón te kaì dóxan tē̂s basileías autoû, idoù gégraptai en biblíōi basiléōn Iersō̂n kaì Mḗdōn eis mnēmósynon."],[10,"3a","ὁ δὲ Μαρδοχαῖος διεδέχετο τὸν βασιλέα Ἀρταξέρξην, καὶ μέγας ἦν ἐν τῇ βασιλείᾳ καὶ δεδοξασμένος ὑπὸ τῶν Ἰουδαίων· καὶ φιλούμενος διηγεῖτο τὴν ἀγωγὴν παντὶ τῷ ἔθνει αὐτοῦ.","ho dè Mardochaîos diedécheto tòn basiléa Artaxérxēn, kaì mégas ē̂n en tē̂i basileíāi kaì dedoxasménos hypò tō̂n Ioudaíōn: kaì philoúmenos diēgeîto tḕn agōgḕn pantì tō̂i éthnei autoû."],[10,1,"Καὶ εἶπεν Μαρδοχαῖς Παρὰ τοῦ θεοῦ ἐγένετο ταῦτα.","Kaì eîpen Mardochaîs Parà toû theoû egéneto taûta."],[10,2,"ἐμνήσθην γὰρ περὶ τοῦ ἐνυπνίου οὗ κἶδον περὶ τῶν λόγων τούτων, οὐδέ γὰρ παρῆλθευ ἀπʼ αὐτῶν λόγος·","emnḗsthēn gàr perì toû enypníou hoû kîdon perì tō̂n lógōn toútōn, oudé gàr parē̂ltheu apʼ autō̂n lógos:"],[10,3,"ἡ μικρὰ πηγὴ ἣ ἐγένετο ποταμός. καὶ ἦν φῶς καὶ ἥλιος καὶ ὕδωρ πολύ. Ἐσθήρ ἐστιν ὁ ποταμός, ἣν ἐγάμησεν ὁ βασιλεὺς καὶ ἐποίησεν βασίλισσαν·","hē mikrà pēgḕ hḕ egéneto potamós. kaì ē̂n phō̂s kaì hḗlios kaì hýdōr polý. Esthḗr estin ho potamós, hḕn egámēsen ho basileùs kaì epoíēsen basílissan:"],[10,4,"οἱ δὲ δύο δράκοντες, ἐγώ εἰμι καὶ Ἁμάν·","hoi dè dýo drákontes, egṓ eimi kaì Hamán:"],[10,5,"τὰ δὲ ἔθνη, τὰ ἐπισυναχθέντα ἀπολέσαι τὸ ὄνομα τῶν Ἰουδαίων·","tà dè éthnē, tà episynachthénta apolésai tò ónoma tō̂n Ioudaíōn:"],[10,6,"τὸ δὲ ἔθνος τὸ ἐμόν, οὗτός ἐστιν Ἰσραὴλ οἱ βοήσαντες πρὸς τὸν θεὸν καὶ σωθέντες. καὶ ἔσωσεν Κύριος τὸν λαὸν αὐτοῦ, καὶ ἐρρύσατο Κύριος ἡμᾶς ἐκ πάντων τῶν κακῶν τούτων· καὶ ἐποίησεν ὁ θεὸς τὰ σημεῖα καὶ τὰ τέρατα τὰ μεγάλα ἃ οὐ γέγονεν ἐν τοῖς ἔθνεσιν.","tò dè éthnos tò emón, hoûtós estin Israḕl hoi boḗsantes pròs tòn theòn kaì sōthéntes. kaì ésōsen Kýrios tòn laòn autoû, kaì errýsato Kýrios hēmâs ek pántōn tō̂n kakō̂n toútōn: kaì epoíēsen ho theòs tà sēmeîa kaì tà térata tà megála hà ou gégonen en toîs éthnesin."],[10,7,"διὰ τοῦτο ἐποίησεν κλήρους δύο, ἕνα τῷ λαῷ τοῦ θεοῦ καὶ ἕνα πᾶσι τοῖς ἔθνεσιν·","dià toûto epoíēsen klḗrous dýo, héna tō̂i laō̂i toû theoû kaì héna pâsi toîs éthnesin:"],[10,8,"καὶ ᾖλθον οἱ δύο κλῆροι οὗτοι εἰς ὥραν καὶ καιρὸν καὶ εἰς ἡμέραν κρίσεως ἐνώπιον τοῦ θεοῦ καὶ πᾶσι τοῖς ἔθνεσιν,","kaì ē̂ilthon hoi dýo klē̂roi hoûtoi eis hṓran kaì kairòn kaì eis hēméran kríseōs enṓpion toû theoû kaì pâsi toîs éthnesin,"],[10,9,"καὶ ἐμνήσθη ὁ θεὸς τοῦ λαοῦ αὐτοῦ, καὶ ἐδικαίωσεν τὴν κληρονομίαν ἑαυτοῦ.","kaì emnḗsthē ho theòs toû laoû autoû, kaì edikaíōsen tḕn klēronomían heautoû."],[10,10,"καὶ ἔσονται αὐτοῖς αἱ ἡμέραι αὗται ἐν μηνὶ Ἀδάρ, τῇ τεσσαρεσκαιδεκάτῃ καὶ τῇ πεντεκαιδεκάτῃ τοῦ αὐτοῦ μηνός, μετὰ συναγωγῆς καὶ χαρᾶς καὶ εὐφροσύνης ἐνώπιον τοῦ θεοῦ κατὰ γενεὰς εἰς τὸν αἰῶνα ἐν τῷ λαῷ αὐτοῦ Ἰσραήλ.","kaì ésontai autoîs hai hēmérai haûtai en mēnì Adár, tē̂i tessareskaidekátēi kaì tē̂i pentekaidekátēi toû autoû mēnós, metà synagōgē̂s kaì charâs kaì euphrosýnēs enṓpion toû theoû katà geneàs eis tòn aiō̂na en tō̂i laō̂i autoû Israḗl."],[10,11,"Ἔτους τετάρτου βασιλεύοντος Πτολεμαίου καὶ Κλεοπάτρας εἰσήνεγκεν Δοσίθεος, ὃς ἔφη εἶναι ἱερεὺς καὶ Λευείτης, καὶ Πτολεμαῖος ὁ υἱὸς αὐτοῦ τὴν προκειμένην ἐπιστολὴν τῶν Φρουραί, ἣν ἔφασαν εἶναι καὶ ἑρμηνευκέναι Λυσίμαχον Πτολεμαίου τῶν ἐν Ἰερουσαλήμ.","Étous tetártou basileúontos Ptolemaíou kaì Kleopátras eisḗnenken Dosítheos, hòs éphē eînai hiereùs kaì Leueítēs, kaì Ptolemaîos ho hyiòs autoû tḕn prokeiménēn epistolḕn tō̂n Phrouraí, hḕn éphasan eînai kaì hermēneukénai Lysímachon Ptolemaíou tō̂n en Ierousalḗm."]],"chu-elizabeth":[[1,1,"И бысть по словесех сих во днех Артаксеркса: сей Артаксеркс от Индии обладаше сто двадесять седмию странами (даже до Ефиопии):","I bystʹ po sloveseh sih vo dneh Artakserksa: sej Artakserks ot Indii obladaše sto dvadesâtʹ sedmiû stranami (daže do Efiopii):"],[1,2,"во дни же тыя, егда седе на престоле царь Артаксеркс в Сусех граде,","vo dni že tyâ, egda sede na prestole carʹ Artakserks v Suseh grade,"],[1,3,"в третие лето царства своего, сотвори пир другом и прочым языком, и Персским и Мидским славным, и началным сатрапом,","v tretie leto carstva svoego, sotvori pir drugom i pročym âzykom, i Persskim i Midskim slavnym, i načalnym satrapom,"],[1,4,"и по сих, егда показа им богатство царства своего и славу веселия своего, во сто осмьдесят дний.","i po sih, egda pokaza im bogatstvo carstva svoego i slavu veseliâ svoego, vo sto osmʹdesât dnij."],[1,5,"И егда исполнишася дние пира, сотвори царь пиршество языком обретшымся во граде (Сусех) на дний шесть во дворе дому царева,","I egda ispolnišasâ dnie pira, sotvori carʹ piršestvo âzykom obretšymsâ vo grade (Suseh) na dnij šestʹ vo dvore domu careva,"],[1,6,"украшеннем виссонными и зелеиыми завесами, простертыми на ужах виссонных и червленичных, на колцах златых и сребряных, на столпех мраморных и каменных:","ukrašennem vissonnymi i zeleiymi zavesami, prostertymi na užah vissonnyh i červleničnyh, na kolcah zlatyh i srebrânyh, na stolpeh mramornyh i kamennyh:"],[1,7,"ложа злата и сребряна, на помосте камене смарагдова, и пиннинска и паринска мрамора, и плащаницы пестротами различными разцвечены, окрест шипцы разсеяни:","loža zlata i srebrâna, na pomoste kamene smaragdova, i pinninska i parinska mramora, i plaŝanicy pestrotami različnymi razcvečeny, okrest šipcy razseâni:"],[1,8,"сосуди злати и сребряни, и чаша анфракса (камене) предложенная, ценою талант тридесять тысящ: вино много и сладко, еже сам царь пияше: питие же сие не по уставленному закону бысть, тако бо восхоте царь и заповеда икономом сотворити волю свою и мужей.","sosudi zlati i srebrâni, i čaša anfraksa (kamene) predložennaâ, cenoû talant tridesâtʹ tysâŝ: vino mnogo i sladko, eže sam carʹ piâše: pitie že sie ne po ustavlennomu zakonu bystʹ, tako bo voshote carʹ i zapoveda ikonomom sotvoriti volû svoû i mužej."],[1,9,"И Астинь царица сотвори пир женам в дому цареве, идеже царь Артаксеркс.","I Astinʹ carica sotvori pir ženam v domu careve, ideže carʹ Artakserks."],[1,10,"В день же седмый развеселився царь, рече Аману и Вазану, и Фарре и Варазу, и Зафолфану и Аватазу и Фараву, седмим евнухом, иже служаху пред царем Артаксерксом,","V denʹ že sedmyj razveselivsâ carʹ, reče Amanu i Vazanu, i Farre i Varazu, i Zafolfanu i Avatazu i Faravu, sedmim evnuhom, iže služahu pred carem Artakserksom,"],[1,11,"привести (Астинь) царицу пред него, еже воцарити ю и возложити на ню венец царский и показати ю всем началствующым и языком красоту ея, зане прекрасна бе.","privesti (Astinʹ) caricu pred nego, eže vocariti û i vozložiti na nû venec carskij i pokazati û vsem načalstvuûŝym i âzykom krasotu eâ, zane prekrasna be."],[1,12,"И не послуша его Астинь царица приити со евнухи.","I ne posluša ego Astinʹ carica priiti so evnuhi."],[1,13,"И опечалися царь, и разгневася, и рече ближним своим: сице рече Астинь: сотворите убо о сем закон и суд.","I opečalisâ carʹ, i razgnevasâ, i reče bližnim svoim: sice reče Astinʹ: sotvorite ubo o sem zakon i sud."],[1,14,"И приступиша к нему Аркесей и Сарсофей и Малисеар, началницы Персстии и Мидстии, иже близ царя, первии седящии при цари,","I pristupiša k nemu Arkesej i Sarsofej i Malisear, načalnicy Persstii i Midstii, iže bliz carâ, pervii sedâŝii pri cari,"],[1,15,"и возвестиша ему по законом, како подобает сотворити царице Астини, яко не сотвори повеленных от царя чрез евнухи.","i vozvestiša emu po zakonom, kako podobaet sotvoriti carice Astini, âko ne sotvori povelennyh ot carâ črez evnuhi."],[1,16,"И рече Мухей ко царю и к боляром: не царя единаго обиде Астинь царица, но и вся князи и началники царевы,","I reče Muhej ko carû i k bolârom: ne carâ edinago obide Astinʹ carica, no i vsâ knâzi i načalniki carevy,"],[1,17,"ибо поведа им словеса царицы, и како противорече царю:","ibo poveda im slovesa caricy, i kako protivoreče carû:"],[1,18,"якоже убо противно рече царю Артаксерксу, сице и днесь госпожи жены прочыя князей Персских и Мидских, услышавшя царю реченная от нея, дерзнут такожде безчествовати мужеи своих:","âkože ubo protivno reče carû Artakserksu, sice i dnesʹ gospoži ženy pročyâ knâzej Persskih i Midskih, uslyšavšâ carû rečennaâ ot neâ, derznut takožde bezčestvovati mužei svoih:"],[1,19,"аще убо угодно царю, да повелит царским повелением, и да напишется по законом Мидским и Персским, и инако да не будет, ниже да внидет ктому царица к нему, и царство ея да предаст царь жене лучшей ея:","aŝe ubo ugodno carû, da povelit carskim poveleniem, i da napišetsâ po zakonom Midskim i Persskim, i inako da ne budet, niže da vnidet ktomu carica k nemu, i carstvo eâ da predast carʹ žene lučšej eâ:"],[1,20,"и да будет услышан закон, иже от царя, егоже сотворит во царствии своем, и сице вся жены возложат честь на мужы своя от богата даже до убога.","i da budet uslyšan zakon, iže ot carâ, egože sotvorit vo carstvii svoem, i sice vsâ ženy vozložat čestʹ na mužy svoâ ot bogata daže do uboga."],[1,21,"И угодно бысть слово пред царем и началники, и сотвори царь, якоже рече ему Мухей,","I ugodno bystʹ slovo pred carem i načalniki, i sotvori carʹ, âkože reče emu Muhej,"],[1,22,"и посла царь книги во все царство по странам по языку их, да будет страх им в жилищих их.","i posla carʹ knigi vo vse carstvo po stranam po âzyku ih, da budet strah im v žiliŝih ih."],[2,1,"И по словесех сих утолися царь от гнева, и не воспомяну ктому Астини, воспоминая, елика глагола и како осуди ея.","I po sloveseh sih utolisâ carʹ ot gneva, i ne vospomânu ktomu Astini, vospominaâ, elika glagola i kako osudi eâ."],[2,2,"И реша слуги царевы: да изыщутся царю девицы нерастленны, красны зраком, и да поставит царь взыскатели во всех странах царствия своего,","I reša slugi carevy: da izyŝutsâ carû devicy nerastlenny, krasny zrakom, i da postavit carʹ vzyskateli vo vseh stranah carstviâ svoego,"],[2,3,"и да изберут отроковиц девственных доброзрачных в Сусы град, в чертог женский, и да отдадутся евнухови цареву стражу жен, и да дадутся масти и прочыя потребы:","i da izberut otrokovic devstvennyh dobrozračnyh v Susy grad, v čertog ženskij, i da otdadutsâ evnuhovi carevu stražu žen, i da dadutsâ masti i pročyâ potreby:"],[2,4,"и жена, юже возлюбит царь, да будет царицею вместо Астини. И угодно бе царю слово, и сотвори тако.","i žena, ûže vozlûbit carʹ, da budet cariceû vmesto Astini. I ugodno be carû slovo, i sotvori tako."],[2,5,"И муж бе Иудеанин во граде Сусех, и имя ему Мардохей сын Иаиров, сына Семеина, сына Кисеова, от племене Вениаминя,","I muž be Iudeanin vo grade Suseh, i imâ emu Mardohej syn Iairov, syna Semeina, syna Kiseova, ot plemene Veniaminâ,"],[2,6,"иже бяше пленен от Иерусалима Навуходоносором царем Вавилонским:","iže bâše plenen ot Ierusalima Navuhodonosorom carem Vavilonskim:"],[2,7,"и бяше ему отроковица воспитана, дщерь Аминадава брата отцу его, и имя ей Есфирь. По преставлении же родителей ея, прия ю Мардохей во дщере место: и бяше девица красна и доброзрачна.","i bâše emu otrokovica vospitana, dŝerʹ Aminadava brata otcu ego, i imâ ej Esfirʹ. Po prestavlenii že roditelej eâ, priâ û Mardohej vo dŝere mesto: i bâše devica krasna i dobrozračna."],[2,8,"И егда услышано бысть повеление царево, собраны быша девицы многи во град Сусы, под руку Гаиеву, и приведена бысть Есфирь ко Гаию хранителю жен:","I egda uslyšano bystʹ povelenie carevo, sobrany byša devicy mnogi vo grad Susy, pod ruku Gaievu, i privedena bystʹ Esfirʹ ko Gaiû hranitelû žen:"],[2,9,"и угодна бысть ему отроковица и окрете благодать пред ним: и потщася дати ей масти и участие, и седмь девиц пристави к ней из дому царева, и снабдеваше ю и рабынь ея добре в дому женстем.","i ugodna bystʹ emu otrokovica i okrete blagodatʹ pred nim: i potŝasâ dati ej masti i učastie, i sedmʹ devic pristavi k nej iz domu careva, i snabdevaše û i rabynʹ eâ dobre v domu ženstem."],[2,10,"И не поведа Есфирь рода своего, ниже отечества, Мардохей бо заповеда ей не возвещати.","I ne poveda Esfirʹ roda svoego, niže otečestva, Mardohej bo zapoveda ej ne vozveŝati."],[2,11,"На всяк же день хождаше Мардохей по двору женскому, назирая, что Есфири случится.","Na vsâk že denʹ hoždaše Mardohej po dvoru ženskomu, naziraâ, čto Esfiri slučitsâ."],[2,12,"Сие же бе время девиц входити ко царю, егда исполнятся дванадесять месяцей: тако бо наполняхуся дние украшения, шесть месяц во ароматех и в мастех женских, и шесть месяц намазующяся смирновым елеем,","Sie že be vremâ devic vhoditi ko carû, egda ispolnâtsâ dvanadesâtʹ mesâcej: tako bo napolnâhusâ dnie ukrašeniâ, šestʹ mesâc vo aromateh i v masteh ženskih, i šestʹ mesâc namazuûŝâsâ smirnovym eleem,"],[2,13,"и тогда вхождаху ко цареви: и емуже аще речет привести ю, входит с ним купно из дому женскаго даже до дому царева:","i togda vhoždahu ko carevi: i emuže aŝe rečet privesti û, vhodit s nim kupno iz domu ženskago daže do domu careva:"],[2,14,"на вечер вхождаше и заутра возвращашеся в дом женский вторый, идеже Гай евнух царев хранитель жен, и не вхождаше паки ко царю, аще не будет позвана именем.","na večer vhoždaše i zautra vozvraŝašesâ v dom ženskij vtoryj, ideže Gaj evnuh carev hranitelʹ žen, i ne vhoždaše paki ko carû, aŝe ne budet pozvana imenem."],[2,15,"Егда же исполнися время Есфири дщери Аминадава, брата отца Мардохеова, (иже поял ю себе в дщере место,) внити ко цареви, ничтоже преступи от сих, яже заповеда ей евнух хранитель жен: бе бо Есфирь обретающая благодать пред всеми зрящими ю.","Egda že ispolnisâ vremâ Esfiri dŝeri Aminadava, brata otca Mardoheova, (iže poâl û sebe v dŝere mesto,) vniti ko carevi, ničtože prestupi ot sih, âže zapoveda ej evnuh hranitelʹ žen: be bo Esfirʹ obretaûŝaâ blagodatʹ pred vsemi zrâŝimi û."],[2,16,"И вниде Есфирь ко царю Артаксерксу во вторыйнадесять месяц, иже есть Адар, в лето седмое царства его.","I vnide Esfirʹ ko carû Artakserksu vo vtoryjnadesâtʹ mesâc, iže estʹ Adar, v leto sedmoe carstva ego."],[2,17,"И возлюби царь Есфирь, и обрете благодать паче всех девиц, и возложи венец женский на главу ея.","I vozlûbi carʹ Esfirʹ, i obrete blagodatʹ pače vseh devic, i vozloži venec ženskij na glavu eâ."],[2,18,"И сотвори царь пир всем другом своим и силам седмь дний, и вознесе брак Есфирин, и сотвори отраду сущым во царствии его.","I sotvori carʹ pir vsem drugom svoim i silam sedmʹ dnij, i voznese brak Esfirin, i sotvori otradu suŝym vo carstvii ego."],[2,19,"Мардохей же служаше во дворе (цареве).","Mardohej že služaše vo dvore (careve)."],[2,20,"Есфирь же не поведа рода своего, (ни людий своих): сице бо заповеда ей Мардохей боятися Бога и творити заповеди Его, якоже бе с ним, Есфирь же не измени обычая своего.","Esfirʹ že ne poveda roda svoego, (ni lûdij svoih): sice bo zapoveda ej Mardohej boâtisâ Boga i tvoriti zapovedi Ego, âkože be s nim, Esfirʹ že ne izmeni obyčaâ svoego."],[2,21,"И опечалистася два евнуха царева началнейшии стражы тела его, яко предпочтен бысть Мардохей, и искаста убити Артаксеркса царя.","I opečalistasâ dva evnuha careva načalnejšii stražy tela ego, âko predpočten bystʹ Mardohej, i iskasta ubiti Artakserksa carâ."],[2,22,"И возвестися слово Мардохею, и сказа Есфири: она же поведа царю, яже наветуют.","I vozvestisâ slovo Mardoheû, i skaza Esfiri: ona že poveda carû, âže navetuût."],[2,23,"Царь же испыта дву евнуху, (и исповедаста,) и обеси их. И повеле царь вписати на память в царстей книгохранителнице о благодеянии Мардохеове в похвалу.","Carʹ že ispyta dvu evnuhu, (i ispovedasta,) i obesi ih. I povele carʹ vpisati na pamâtʹ v carstej knigohranitelnice o blagodeânii Mardoheove v pohvalu."],[3,1,"И по сих прослави царь Артаксеркс Амана сына Амадафуина Вугеанина и вознесе его, и председяше вышше всех другов его:","I po sih proslavi carʹ Artakserks Amana syna Amadafuina Vugeanina i voznese ego, i predsedâše vyšše vseh drugov ego:"],[3,2,"и вси, иже во дворе (цареве), покланяхуся Аману: сице бо повеле царь творити. Мардохей же не кланяшеся ему.","i vsi, iže vo dvore (careve), poklanâhusâ Amanu: sice bo povele carʹ tvoriti. Mardohej že ne klanâšesâ emu."],[3,3,"И глаголаша сущии во дворе цареве Мардохею: мардохее, чесо ради не слушаеши глаголемых от царя?","I glagolaša suŝii vo dvore careve Mardoheû: mardohee, česo radi ne slušaeši glagolemyh ot carâ?"],[3,4,"По вся же дни глаголаху ему, и не послушаше их. И возвестиша Аману, яко Мардохей сопротивляется повелению цареву, и поведа им Мардохей, яко Иудеанин есть.","Po vsâ že dni glagolahu emu, i ne poslušaše ih. I vozvestiša Amanu, âko Mardohej soprotivlâetsâ poveleniû carevu, i poveda im Mardohej, âko Iudeanin estʹ."],[3,5,"И уведав Аман, яко не кланяется ему Мардохеи, разгневася зело","I uvedav Aman, âko ne klanâetsâ emu Mardohei, razgnevasâ zelo"],[3,6,"и умысли погубити вся Иудеи, иже в царстве Артаксерксове:","i umysli pogubiti vsâ Iudei, iže v carstve Artakserksove:"],[3,7,"и сотвори совет в лето второенадесять царства Артаксерксова, и меташе жребия день от дне и месяц от месяца, яко погубити во един день род Мардохеев: и паде жребий на четвертыйнадесять день месяца, иже есть Адар.","i sotvori sovet v leto vtoroenadesâtʹ carstva Artakserksova, i metaše žrebiâ denʹ ot dne i mesâc ot mesâca, âko pogubiti vo edin denʹ rod Mardoheev: i pade žrebij na četvertyjnadesâtʹ denʹ mesâca, iže estʹ Adar."],[3,8,"И рече (Аман) ко царю Артаксерксу, глаголя: есть язык разсеянный во языцех во всем царстве твоем: законы же их странни паче всех язык, и законов царских не слушают, и не пользует царю оставити их:","I reče (Aman) ko carû Artakserksu, glagolâ: estʹ âzyk razseânnyj vo âzyceh vo vsem carstve tvoem: zakony že ih stranni pače vseh âzyk, i zakonov carskih ne slušaût, i ne polʹzuet carû ostaviti ih:"],[3,9,"и аще годе есть цареви, да повелит погубити я: аз же запишу в сокровище царево десять тысящ талант сребра.","i aŝe gode estʹ carevi, da povelit pogubiti â: az že zapišu v sokroviŝe carevo desâtʹ tysâŝ talant srebra."],[3,10,"И снем царь перстень (с руки своея), даде в руце Аману, да запечатает писания написанная на Иудей.","I snem carʹ perstenʹ (s ruki svoeâ), dade v ruce Amanu, da zapečataet pisaniâ napisannaâ na Iudej."],[3,11,"И рече царь Аману: сребро убо имей ты себе, людем же твори, якоже хощеши.","I reče carʹ Amanu: srebro ubo imej ty sebe, lûdem že tvori, âkože hoŝeši."],[3,12,"И призвани быша писцы царевы в третийнадесять день месяца перваго, и написаша, якоже повеле Аман, к воеводам и началником по всем странам, от Индийския области даже и до Ефиопии, сто двадесяти седми странам, началствующым над языки по их языку, именем Артаксеркса царя.","I prizvani byša piscy carevy v tretijnadesâtʹ denʹ mesâca pervago, i napisaša, âkože povele Aman, k voevodam i načalnikom po vsem stranam, ot Indijskiâ oblasti daže i do Efiopii, sto dvadesâti sedmi stranam, načalstvuûŝym nad âzyki po ih âzyku, imenem Artakserksa carâ."],[3,13,"И посла с писмоносцы писания в царство Артаксерксово, да побиют род Жидовский в день един месяца вторагонадесять, иже есть Адар, и да расхитят имения их. Списание же епистолии сицево бе: царь великий Артаксеркс началствующым от Индии даже до Ефиопии над сто двадесять седмию странами и местоначалником подданным. Над многими царствующь языки и обдержав всю вселенную, восхотех, не дерзостию области возносимь, но кротостию и тихостию всегда правя, безмятежно житие всегда устрояти подручных (наших), и царствие (свое) безмолвно и проходимо даже до конец соблюдая, обновити желаемый всем человеком мир. Вопросившу же ми советники моя, како бы возможно сие совершити, иже у нас целомудрием пресловутый и во благоволении неизменный и твердою верностию утвержденный и вторую честь по цари получивый Аман сказа нам, яко во всех по вселенней коленех смесися враждебный некий народ, законами сопротивный ко всякому языку и повеления царская всегда небрегущь, дабы не устроялося от нас благоуправляемое непорочно сообладание. Уразумевше убо, яко сей язык един сопротивляется всегда всякому человеку, уставление законов иностранное изменяет, и противяся нашым делом, горшая совершает злая, дабы царствие наше не получило благостояния: повелехом убо написанными к вам грамотами от Амана учиненаго над вещьми (царскими) и втораго отца нашего, всех со женами и чады погубити всекоренне вражиими мечьми без всякия милости и пощадения, в четвертыйнадесять день вторагонадесять месяца Адара, настоящаго лета, яко да бывшии древле и ныне врази во единем дни горько во ад сошедше, в прочее время тихо и безмолвно житие дадят нам до конца проходити.","I posla s pismonoscy pisaniâ v carstvo Artakserksovo, da pobiût rod Židovskij v denʹ edin mesâca vtoragonadesâtʹ, iže estʹ Adar, i da rashitât imeniâ ih. Spisanie že epistolii sicevo be: carʹ velikij Artakserks načalstvuûŝym ot Indii daže do Efiopii nad sto dvadesâtʹ sedmiû stranami i mestonačalnikom poddannym. Nad mnogimi carstvuûŝʹ âzyki i obderžav vsû vselennuû, voshoteh, ne derzostiû oblasti voznosimʹ, no krotostiû i tihostiû vsegda pravâ, bezmâtežno žitie vsegda ustroâti područnyh (naših), i carstvie (svoe) bezmolvno i prohodimo daže do konec soblûdaâ, obnoviti želaemyj vsem čelovekom mir. Voprosivšu že mi sovetniki moâ, kako by vozmožno sie soveršiti, iže u nas celomudriem preslovutyj i vo blagovolenii neizmennyj i tverdoû vernostiû utverždennyj i vtoruû čestʹ po cari polučivyj Aman skaza nam, âko vo vseh po vselennej koleneh smesisâ vraždebnyj nekij narod, zakonami soprotivnyj ko vsâkomu âzyku i poveleniâ carskaâ vsegda nebreguŝʹ, daby ne ustroâlosâ ot nas blagoupravlâemoe neporočno soobladanie. Urazumevše ubo, âko sej âzyk edin soprotivlâetsâ vsegda vsâkomu čeloveku, ustavlenie zakonov inostrannoe izmenâet, i protivâsâ našym delom, goršaâ soveršaet zlaâ, daby carstvie naše ne polučilo blagostoâniâ: povelehom ubo napisannymi k vam gramotami ot Amana učinenago nad veŝʹmi (carskimi) i vtorago otca našego, vseh so ženami i čady pogubiti vsekorenne vražiimi mečʹmi bez vsâkiâ milosti i poŝadeniâ, v četvertyjnadesâtʹ denʹ vtoragonadesâtʹ mesâca Adara, nastoâŝago leta, âko da byvšii drevle i nyne vrazi vo edinem dni gorʹko vo ad sošedše, v pročee vremâ tiho i bezmolvno žitie dadât nam do konca prohoditi."],[3,14,"Списания же епистолии посылахуся по странам, и повелено бысть всем языком готовым быти в нареченный день.","Spisaniâ že epistolii posylahusâ po stranam, i poveleno bystʹ vsem âzykom gotovym byti v narečennyj denʹ."],[3,15,"Приспе же дело и в Сусы: и царь убо и Аман пирующа наслаждастася, град же (Сусы) мятяшеся.","Prispe že delo i v Susy: i carʹ ubo i Aman piruûŝa naslaždastasâ, grad že (Susy) mâtâšesâ."],[4,1,"Мардохей же разумев замышляемое, раздра ризы своя и облечеся во вретище и посыпася пепелом: и скочив в пространную улицу града, возопи воплем великим и горьким: взимается род ничтоже преступивый.","Mardohej že razumev zamyšlâemoe, razdra rizy svoâ i oblečesâ vo vretiŝe i posypasâ pepelom: i skočiv v prostrannuû ulicu grada, vozopi voplem velikim i gorʹkim: vzimaetsâ rod ničtože prestupivyj."],[4,2,"И прииде даже до врат царевых и ста: не леть бо бе ему внити во двор во вретище облечену и пепелом осыпану сущу.","I priide daže do vrat carevyh i sta: ne letʹ bo be emu vniti vo dvor vo vretiŝe oblečenu i pepelom osypanu suŝu."],[4,3,"И во всяцей стране, идеже показовахуся писания (царева), вопль бе и плачь и рыдание превелие Иудеом, вретище и пепел постилаху себе.","I vo vsâcej strane, ideže pokazovahusâ pisaniâ (careva), voplʹ be i plačʹ i rydanie prevelie Iudeom, vretiŝe i pepel postilahu sebe."],[4,4,"И внидоща рабыни и евнуси царицыны и возвестиша ей. И смятеся услышавши бывшее: и посла ризы облещи Мардохеа и сняти вретище его. И не послуша.","I vnidoŝa rabyni i evnusi caricyny i vozvestiša ej. I smâtesâ uslyšavši byvšee: i posla rizy obleŝi Mardohea i snâti vretiŝe ego. I ne posluša."],[4,5,"Есфирь же призва Ахрафеа скопца своего, предстоящаго ей,","Esfirʹ že prizva Ahrafea skopca svoego, predstoâŝago ej,"],[4,6,"и посла его уведати от Мардохеа истину.","i posla ego uvedati ot Mardohea istinu."],[4,7,"Мардохей же сказа ему бывшее, и обещание, еже обеша Аман царю в сокровищный дом (положити) десять тысящ талант сребра, да погубит Иудей:","Mardohej že skaza emu byvšee, i obeŝanie, eže obeša Aman carû v sokroviŝnyj dom (položiti) desâtʹ tysâŝ talant srebra, da pogubit Iudej:"],[4,8,"и списание (повеления) изданнаго в Сусех (граде) на погубление их даде ему, да покажет Есфири: и рече ему, заповедати ей ити молити царя и просити его о людех, поминаюши дни смирения твоего, како воспитана еси в руце моей, зане Аман вторый по цари глагола противу нам на смерть: призови Господа и глаголи царю о нас, да избавит нас от смерти.","i spisanie (poveleniâ) izdannago v Suseh (grade) na pogublenie ih dade emu, da pokažet Esfiri: i reče emu, zapovedati ej iti moliti carâ i prositi ego o lûdeh, pominaûši dni smireniâ tvoego, kako vospitana esi v ruce moej, zane Aman vtoryj po cari glagola protivu nam na smertʹ: prizovi Gospoda i glagoli carû o nas, da izbavit nas ot smerti."],[4,9,"Вшед же Ахрафей, поведа Есфири вся глаголы сия.","Všed že Ahrafej, poveda Esfiri vsâ glagoly siâ."],[4,10,"И рече Есфирь ко Ахрафею: иди к Мардохею и рцы:","I reče Esfirʹ ko Ahrafeû: idi k Mardoheû i rcy:"],[4,11,"понеже вси языцы царствия ведят, яко всяк муж или жена, иже аще внидет ко царвеи во внутренний дом не призван, несть ему спасения, точию к немуже аще прострет царь златый жезл, сей спасен будет: аз же несмь звана внити ко царю се уже тридесять дний.","poneže vsi âzycy carstviâ vedât, âko vsâk muž ili žena, iže aŝe vnidet ko carvei vo vnutrennij dom ne prizvan, nestʹ emu spaseniâ, točiû k nemuže aŝe prostret carʹ zlatyj žezl, sej spasen budet: az že nesmʹ zvana vniti ko carû se uže tridesâtʹ dnij."],[4,12,"И возвести Ахрафей Мардохею вся глаголы Есфирины.","I vozvesti Ahrafej Mardoheû vsâ glagoly Esfiriny."],[4,13,"И рече Мардохей ко Ахрафею: иди и рцы ей: Есфире, да не речеши в себе, яко ты едина спасешися во царствии паче всех Иудей:","I reče Mardohej ko Ahrafeû: idi i rcy ej: Esfire, da ne rečeši v sebe, âko ty edina spasešisâ vo carstvii pače vseh Iudej:"],[4,14,"зане аще преслушаеши в сие время, отинуду помощь и покров будет Иудеом, ты же и дом отца твоего погибнете: и кто весть, аще на сие время воцарилася еси?","zane aŝe preslušaeši v sie vremâ, otinudu pomoŝʹ i pokrov budet Iudeom, ty že i dom otca tvoego pogibnete: i kto vestʹ, aŝe na sie vremâ vocarilasâ esi?"],[4,15,"И посла Есфирь пришедшаго к ней ко Мардохею, глаголющи:","I posla Esfirʹ prišedšago k nej ko Mardoheû, glagolûŝi:"],[4,16,"шед собери Иудеи иже в Сусех, и поститеся о мне, и не ядите ниже пийте три дни день и нощь: аз же и служебницы моя (такожде) не имамы ясти: и тогда вниду ко царю кроме закона, аще и погибнути ми приключится.","šed soberi Iudei iže v Suseh, i postitesâ o mne, i ne âdite niže pijte tri dni denʹ i noŝʹ: az že i služebnicy moâ (takožde) ne imamy âsti: i togda vnidu ko carû krome zakona, aŝe i pogibnuti mi priklûčitsâ."],[4,17,"И шед Мардохей сотвори, елика заповеда ему Есфирь, и помолися Господеви поминая вся дела Господня и рече: Господи, Господи Царю Вседержителю, яко во власти Твоей сие все есть, и несть противомудрствуяй Тебе, внегда восхощеши спасти Израиля: яко Ты сотворил еси небо и землю и все удивляемое в поднебесней и Господь еси всех, и несть, иже воспротивится Тебе Господеви: Ты вся веси, Ты знаеши, Господи, яко не в укоризне ни в гордости, ниже во тщелавии сотворих сие, еже не покланятися прегордому Аману, понеже благоволим бых лобзати и следы ног его спасения ради Израилева, но сие сотворих, да не воздам славы человеку паче славы Божя, и не поклонюся ни комуже, кроме Тебе Господа моего, и не сотворю сия в гордости: и ныне, Господи Боже, Царю, Боже Авраамов, пощади люди Твоя, яко назирают нам в погибель и вожделеша погубити еже из начала наследие Твое: не презри достояния Твоего, еже избавил еси Тебе от земли Египетския: услыши молитву мою, и умилосердися над жребием Твоим, и обрати рыдание наше в веселие, да живуще восхвалим имя Твое, Господи, и не погуби уст восхваляющих Тя, Господи. И весь Израиль возопи от крепости своея, яко смерть их пред очима их: и Есфирь царица притече ко Господу в подвизе смерти обдержима, и снемши ризы славы своея, облечеся в ризы тесноты и плача, и вместо многоценных мастей и благовонных пепелом и гноем посыпа главу свою, и плоть свою смири зело, и кождо место украшения веселия своего исполни растерзанными власы своими, и моляшеся Господу Богу Израилеву и рече: Господи мой, Царю наш, Ты еси един, помози ми единый и не имеющей помощи разве Тебе, яко беда моя в руце моей: аз слышах, Господи, от отца моего в племени отечества моего, яко Ты Господи, приял еси Израиля от всех язык и отцы нашя от всех праотец их в наследие вечное, и сотворил еси им, елика глаголал еси: и ныне согрешихом пред Тобою, и предал еси нас в руки враг наших, занеже славихом боги их: праведен еси, Господи: и ныне не доволни быша горестию работы нашея, но положиша руки своя на руки идол своих, исторгнути заповедь уст Твоих и погубити наследие Твое, и заградити уста хвалящих Тя и угасити славу храма Твоего и олтаря Твоего, и отверзти уста языком во угождения суетных и удивитися цареви плотскому во веки: не предаждь, Господи, скиптра Твоего сим, иже не суть, и да не посмеются в падении нашем, но обрати совет их на ня, наченшаго же на нас в притчу положи: помяни, Господи, познан буди во время скорби нашея и мене сподоби дерзновения: Царю богов и всякаго началства Содержителю, даждь слово благоугодно во уста моя пред львом, и премени сердце его в ненавидение воюющаго ны, во истребление его и с ним советующих: нас же изми рукою Твоею и помози ми единей и не имеющей ни когоже, токмо Тебе, Господи: всех разум имаши и веси, яко возненавидех славу беззаконных и гнушаюся ложа необрезанных и всякаго иноплеменника: Ты веси нужду мою, яко гнушаюся знамения гордости моея, еже есть на главе моей во днех видения моего, гнушаюся его, яко рубищ оскверненных, и не ношу его в день молчания моего: и не яде раба Твоя от трапезы Амановы, и не прославлях пира царева, ниже пиях вино требищ (идолских): и не возвеселися раба Твоя от дне пременения моего даже доныне, точию о Тебе, Господи Боже Авраамов: Боже, могий над всеми, услыши глас безнадежных, и избави нас от руки лукавнующих и изми мя от страха моего.","I šed Mardohej sotvori, elika zapoveda emu Esfirʹ, i pomolisâ Gospodevi pominaâ vsâ dela Gospodnâ i reče: Gospodi, Gospodi Carû Vsederžitelû, âko vo vlasti Tvoej sie vse estʹ, i nestʹ protivomudrstvuâj Tebe, vnegda voshoŝeši spasti Izrailâ: âko Ty sotvoril esi nebo i zemlû i vse udivlâemoe v podnebesnej i Gospodʹ esi vseh, i nestʹ, iže vosprotivitsâ Tebe Gospodevi: Ty vsâ vesi, Ty znaeši, Gospodi, âko ne v ukorizne ni v gordosti, niže vo tŝelavii sotvorih sie, eže ne poklanâtisâ pregordomu Amanu, poneže blagovolim byh lobzati i sledy nog ego spaseniâ radi Izraileva, no sie sotvorih, da ne vozdam slavy čeloveku pače slavy Božâ, i ne poklonûsâ ni komuže, krome Tebe Gospoda moego, i ne sotvorû siâ v gordosti: i nyne, Gospodi Bože, Carû, Bože Avraamov, poŝadi lûdi Tvoâ, âko naziraût nam v pogibelʹ i voždeleša pogubiti eže iz načala nasledie Tvoe: ne prezri dostoâniâ Tvoego, eže izbavil esi Tebe ot zemli Egipetskiâ: uslyši molitvu moû, i umiloserdisâ nad žrebiem Tvoim, i obrati rydanie naše v veselie, da živuŝe voshvalim imâ Tvoe, Gospodi, i ne pogubi ust voshvalâûŝih Tâ, Gospodi. I vesʹ Izrailʹ vozopi ot kreposti svoeâ, âko smertʹ ih pred očima ih: i Esfirʹ carica priteče ko Gospodu v podvize smerti obderžima, i snemši rizy slavy svoeâ, oblečesâ v rizy tesnoty i plača, i vmesto mnogocennyh mastej i blagovonnyh pepelom i gnoem posypa glavu svoû, i plotʹ svoû smiri zelo, i koždo mesto ukrašeniâ veseliâ svoego ispolni rasterzannymi vlasy svoimi, i molâšesâ Gospodu Bogu Izrailevu i reče: Gospodi moj, Carû naš, Ty esi edin, pomozi mi edinyj i ne imeûŝej pomoŝi razve Tebe, âko beda moâ v ruce moej: az slyšah, Gospodi, ot otca moego v plemeni otečestva moego, âko Ty Gospodi, priâl esi Izrailâ ot vseh âzyk i otcy našâ ot vseh praotec ih v nasledie večnoe, i sotvoril esi im, elika glagolal esi: i nyne sogrešihom pred Toboû, i predal esi nas v ruki vrag naših, zaneže slavihom bogi ih: praveden esi, Gospodi: i nyne ne dovolni byša gorestiû raboty našeâ, no položiša ruki svoâ na ruki idol svoih, istorgnuti zapovedʹ ust Tvoih i pogubiti nasledie Tvoe, i zagraditi usta hvalâŝih Tâ i ugasiti slavu hrama Tvoego i oltarâ Tvoego, i otverzti usta âzykom vo ugoždeniâ suetnyh i udivitisâ carevi plotskomu vo veki: ne predaždʹ, Gospodi, skiptra Tvoego sim, iže ne sutʹ, i da ne posmeûtsâ v padenii našem, no obrati sovet ih na nâ, načenšago že na nas v pritču položi: pomâni, Gospodi, poznan budi vo vremâ skorbi našeâ i mene spodobi derznoveniâ: Carû bogov i vsâkago načalstva Soderžitelû, daždʹ slovo blagougodno vo usta moâ pred lʹvom, i premeni serdce ego v nenavidenie voûûŝago ny, vo istreblenie ego i s nim sovetuûŝih: nas že izmi rukoû Tvoeû i pomozi mi edinej i ne imeûŝej ni kogože, tokmo Tebe, Gospodi: vseh razum imaši i vesi, âko voznenavideh slavu bezzakonnyh i gnušaûsâ loža neobrezannyh i vsâkago inoplemennika: Ty vesi nuždu moû, âko gnušaûsâ znameniâ gordosti moeâ, eže estʹ na glave moej vo dneh videniâ moego, gnušaûsâ ego, âko rubiŝ oskvernennyh, i ne nošu ego v denʹ molčaniâ moego: i ne âde raba Tvoâ ot trapezy Amanovy, i ne proslavlâh pira careva, niže piâh vino trebiŝ (idolskih): i ne vozveselisâ raba Tvoâ ot dne premeneniâ moego daže donyne, točiû o Tebe, Gospodi Bože Avraamov: Bože, mogij nad vsemi, uslyši glas beznadežnyh, i izbavi nas ot ruki lukavnuûŝih i izmi mâ ot straha moego."],[5,1,"И бысть по триех днех, егда преста молитися, совлечеся из риз прискорбных и облечеся в ризы славы своея: и бысть доброзрачна, призывающи всевидца Бога и Спасителя, и взя две рабыни с собою, и о едину убо опирашеся аки сладостьми обилующи, другая же последоваше, да облегчает ризы ея: и сия червленеющися добротою красоты своея, и лице ея осклабляющееся аки прелюбивейше, сердце же ея стеняше от страха. И прошедши вся двери, ста пред царем. Он же седяше на престоле царства своего, оболчен во все одеяние славы своея, весь во злате и камениих многоцвеных, и бяше страше зело: и возвед лице свое огневидно славою, зелною яростию воззре. И паде царица, и изменися лице ея со ослабленмем, и преклонися на главу рабыни предидущия. И премени Бог дух царев на кротость, и потщався сниде со престола своего и восприят ю во овятия своя, дондеже прииде в себе, и утеши ю глаголы мирными и рече ей: что ти есть, Есфире? Аз есмь брат твой, дерзай, не умреши: яко общее повеление наше есть, приступи.","I bystʹ po trieh dneh, egda presta molitisâ, sovlečesâ iz riz priskorbnyh i oblečesâ v rizy slavy svoeâ: i bystʹ dobrozračna, prizyvaûŝi vsevidca Boga i Spasitelâ, i vzâ dve rabyni s soboû, i o edinu ubo opirašesâ aki sladostʹmi obiluûŝi, drugaâ že posledovaše, da oblegčaet rizy eâ: i siâ červleneûŝisâ dobrotoû krasoty svoeâ, i lice eâ osklablâûŝeesâ aki prelûbivejše, serdce že eâ stenâše ot straha. I prošedši vsâ dveri, sta pred carem. On že sedâše na prestole carstva svoego, obolčen vo vse odeânie slavy svoeâ, vesʹ vo zlate i kameniih mnogocvenyh, i bâše straše zelo: i vozved lice svoe ognevidno slavoû, zelnoû ârostiû vozzre. I pade carica, i izmenisâ lice eâ so oslablenmem, i preklonisâ na glavu rabyni prediduŝiâ. I premeni Bog duh carev na krotostʹ, i potŝavsâ snide so prestola svoego i vospriât û vo ovâtiâ svoâ, dondeže priide v sebe, i uteši û glagoly mirnymi i reče ej: čto ti estʹ, Esfire? Az esmʹ brat tvoj, derzaj, ne umreši: âko obŝee povelenie naše estʹ, pristupi."],[5,2,"И взем златый жезл (царь) возложи на выю ея и облобыза ю и рече: глаголи ми. И рече ему: видех тя, господине, яко Ангела Божия, и смятеся сердце мое от страха славы твоея, яко дивен еси, господине, и лице твое благодатей исполнено. Беседующи же она к нему, паде от ослабления. Царь же смятеся, и вси раби его утешаху ея.","I vzem zlatyj žezl (carʹ) vozloži na vyû eâ i oblobyza û i reče: glagoli mi. I reče emu: videh tâ, gospodine, âko Angela Božiâ, i smâtesâ serdce moe ot straha slavy tvoeâ, âko diven esi, gospodine, i lice tvoe blagodatej ispolneno. Beseduûŝi že ona k nemu, pade ot oslableniâ. Carʹ že smâtesâ, i vsi rabi ego utešahu eâ."],[5,3,"И рече ей царь: что хощеши, Есфире? И что прошение твое? Будет ти даже и до полуцарства моего.","I reče ej carʹ: čto hoŝeši, Esfire? I čto prošenie tvoe? Budet ti daže i do polucarstva moego."],[5,4,"И рече Есфирь: день моего празднования днесь есть: аще убо угодно есть цареви, да приидет царь и Аман на пир, егоже сотворю днесь.","I reče Esfirʹ: denʹ moego prazdnovaniâ dnesʹ estʹ: aŝe ubo ugodno estʹ carevi, da priidet carʹ i Aman na pir, egože sotvorû dnesʹ."],[5,5,"И рече царь: ускорите ити по Амана, да сотворим слово Есфирино. И приидоста оба на пир, егоже сотвори Есфирь.","I reče carʹ: uskorite iti po Amana, da sotvorim slovo Esfirino. I priidosta oba na pir, egože sotvori Esfirʹ."],[5,6,"На пиру же рече царь ко Есфири: что есть, Есфире царице? (и кая есть мысль прошения твоего? Дам ти и до полуцарства моего,) и будет елико просиши.","Na piru že reče carʹ ko Esfiri: čto estʹ, Esfire carice? (i kaâ estʹ myslʹ prošeniâ tvoego? Dam ti i do polucarstva moego,) i budet eliko prosiši."],[5,7,"И рече Есфирь: прошение мое и моление:","I reče Esfirʹ: prošenie moe i molenie:"],[5,8,"аще обретох благодать пред царем, да приидет царь и Аман еще заутра на пир, егоже сотворю има, и заутра сотворю сие прошение.","aŝe obretoh blagodatʹ pred carem, da priidet carʹ i Aman eŝe zautra na pir, egože sotvorû ima, i zautra sotvorû sie prošenie."],[5,9,"И изыде Аман от царя зело радостен и весел: видев же Мардохеа Иудеанина во дворе (цареве не подвигнувшася и не кланяющатя пред ним), возярися зело:","I izyde Aman ot carâ zelo radosten i vesel: videv že Mardohea Iudeanina vo dvore (careve ne podvignuvšasâ i ne klanâûŝatâ pred nim), vozârisâ zelo:"],[5,10,"и вшед в дом свой, призва други своя и Зосару жену свою","i všed v dom svoj, prizva drugi svoâ i Zosaru ženu svoû"],[5,11,"и показа им богатство свое и славу, еюже возвеличи его царь, и яко сотвори его перваго быти и правити царствие.","i pokaza im bogatstvo svoe i slavu, eûže vozveliči ego carʹ, i âko sotvori ego pervago byti i praviti carstvie."],[5,12,"И рече Аман: не зва царица ни единаго на пир со царем, но точию мене, и наутрие зваше мя:","I reče Aman: ne zva carica ni edinago na pir so carem, no točiû mene, i nautrie zvaše mâ:"],[5,13,"но сия не суть ми угодна, егда вижду Мардохеа Иудеанина во дворе (цареве).","no siâ ne sutʹ mi ugodna, egda viždu Mardohea Iudeanina vo dvore (careve)."],[5,14,"И рече ему Зосара жена его и друзие: приготови древо лакот пятьдесят, и заутра речеши цареви, и да повешен будет Мардохей на древе: ты же вниди со царем на пир и веселися. И угоден бысть Аману глагол сей, и уготова древо.","I reče emu Zosara žena ego i druzie: prigotovi drevo lakot pâtʹdesât, i zautra rečeši carevi, i da povešen budet Mardohej na dreve: ty že vnidi so carem na pir i veselisâ. I ugoden bystʹ Amanu glagol sej, i ugotova drevo."],[6,1,"Господь же отя сон от царя в нощи оней. И повеле рабу своему принести книги памятныя дний прочитати ему:","Gospodʹ že otâ son ot carâ v noŝi onej. I povele rabu svoemu prinesti knigi pamâtnyâ dnij pročitati emu:"],[6,2,"и обрете писания написанная о Мардохеи, како поведа царю о двою евнуху царскую, внегда стрещи има, и умыслиста убити (царя) Артаксеркса.","i obrete pisaniâ napisannaâ o Mardohei, kako poveda carû o dvoû evnuhu carskuû, vnegda streŝi ima, i umyslista ubiti (carâ) Artakserksa."],[6,3,"И рече царь: кую славу или благодать сотворихом Мардохею? И рекоша отроцы царевы: ничтоже сотворил еси ему?","I reče carʹ: kuû slavu ili blagodatʹ sotvorihom Mardoheû? I rekoša otrocy carevy: ničtože sotvoril esi emu?"],[6,4,"Вопрошающу же царю о благодеянии Мардохеове, се, Аман прииде во двор, и рече царь: кто есть во дворе? Аман же прииде рещи цареви, да повесит Мардохеа на древе, еже уготова.","Voprošaûŝu že carû o blagodeânii Mardoheove, se, Aman priide vo dvor, i reče carʹ: kto estʹ vo dvore? Aman že priide reŝi carevi, da povesit Mardohea na dreve, eže ugotova."],[6,5,"И рекоша отроцы царевы: се, Аман стоит во дворе. И рече царь: призовите его.","I rekoša otrocy carevy: se, Aman stoit vo dvore. I reče carʹ: prizovite ego."],[6,6,"И рече царь Аману: что сотворю мужу, егоже аз хощу прославити? Рече же в себе Аман: кого хощет царь прославити, разве мене?","I reče carʹ Amanu: čto sotvorû mužu, egože az hoŝu proslaviti? Reče že v sebe Aman: kogo hoŝet carʹ proslaviti, razve mene?"],[6,7,"Рече же царю: мужа, егоже хощет царь прославити,","Reče že carû: muža, egože hoŝet carʹ proslaviti,"],[6,8,"да принесут отроцы царевы одежду виссонную, еюже царь облачается, и коня, на немже царь ездит,","da prinesut otrocy carevy odeždu vissonnuû, eûže carʹ oblačaetsâ, i konâ, na nemže carʹ ezdit,"],[6,9,"и да дастся единому от другов царевых славных, и да облечет мужа, егоже царь любит, и да посадит его на коня и проповесть на улицах града, глаголя: тако будет всякому человеку, егоже царь прославит.","i da dastsâ edinomu ot drugov carevyh slavnyh, i da oblečet muža, egože carʹ lûbit, i da posadit ego na konâ i propovestʹ na ulicah grada, glagolâ: tako budet vsâkomu čeloveku, egože carʹ proslavit."],[6,10,"И рече царь Аману: добре рекл еси: тако сотвори Мардохею Иудеанину, угодно служащему во дворе (нашем), и да не изменится слово твое от сих, яже рекл еси.","I reče carʹ Amanu: dobre rekl esi: tako sotvori Mardoheû Iudeaninu, ugodno služaŝemu vo dvore (našem), i da ne izmenitsâ slovo tvoe ot sih, âže rekl esi."],[6,11,"И взя Аман одежду и коня, и облече Мардохеа, и возведе его на коня, и пройде по улицам града, и проповедаше (пред ним), глаголя: сице будет всякому человеку, егоже хощет цар прославити.","I vzâ Aman odeždu i konâ, i obleče Mardohea, i vozvede ego na konâ, i projde po ulicam grada, i propovedaše (pred nim), glagolâ: sice budet vsâkomu čeloveku, egože hoŝet car proslaviti."],[6,12,"И возвратися Мардохеи во двор (царев): Аман же иде в дом свой скорбя преклонив главу.","I vozvratisâ Mardohei vo dvor (carev): Aman že ide v dom svoj skorbâ prekloniv glavu."],[6,13,"И сказа Аман случившаяся ему Зосаре жене своей и другом своим. И реша ему друзие его и жена: аще от племене Иудейскаго Мардохей, начал еси смирятися пред ним, падая падеши, и не возможеши ему отмстити, яко Бог живый есть с ним.","I skaza Aman slučivšaâsâ emu Zosare žene svoej i drugom svoim. I reša emu druzie ego i žena: aŝe ot plemene Iudejskago Mardohej, načal esi smirâtisâ pred nim, padaâ padeši, i ne vozmožeši emu otmstiti, âko Bog živyj estʹ s nim."],[6,14,"И еще глаголющым им, приидоша евнуси, спешно зовуще Амана на пир, егоже уготова Есфирь.","I eŝe glagolûŝym im, priidoša evnusi, spešno zovuŝe Amana na pir, egože ugotova Esfirʹ."],[7,1,"Вниде же царь и Аман пировати со царицею.","Vnide že carʹ i Aman pirovati so cariceû."],[7,2,"И рече царь Есфири во вторый день на пиру: что есть, Есфире царице? И что прошение твое? И что моление твое? И будет тебе до полуцарствия моего.","I reče carʹ Esfiri vo vtoryj denʹ na piru: čto estʹ, Esfire carice? I čto prošenie tvoe? I čto molenie tvoe? I budet tebe do polucarstviâ moego."],[7,3,"И отвещавши (Есфирь царица) рече: аще обретох благодать пред очима твоима, царю, да дастся душа моя прошению моему и людие мои молению моему:","I otveŝavši (Esfirʹ carica) reče: aŝe obretoh blagodatʹ pred očima tvoima, carû, da dastsâ duša moâ prošeniû moemu i lûdie moi moleniû moemu:"],[7,4,"продани бо есмы, аз же и людие мои, на погибель и расхищение и в работу, мы же и чада наша в рабы и рабыни, и небрегох: несть бо достоин клеветник двора царева.","prodani bo esmy, az že i lûdie moi, na pogibelʹ i rashiŝenie i v rabotu, my že i čada naša v raby i rabyni, i nebregoh: nestʹ bo dostoin klevetnik dvora careva."],[7,5,"И рече царь: кто есть сей, иже дерзну сотворити вещь сию?","I reče carʹ: kto estʹ sej, iže derznu sotvoriti veŝʹ siû?"],[7,6,"И рече Есфирь: человек враг, Аман лукавый сей. Аман же смятеся от царя и царицы.","I reče Esfirʹ: čelovek vrag, Aman lukavyj sej. Aman že smâtesâ ot carâ i caricy."],[7,7,"Царь же воста со гневом от пира (и иде) в вертоград: Аман же моляше царицу, видяше бо себе в бедах суща.","Carʹ že vosta so gnevom ot pira (i ide) v vertograd: Aman že molâše caricu, vidâše bo sebe v bedah suŝa."],[7,8,"Возвратися же царь из вертограда, и Аман припаде к ложу, на немже бе Есфирь, моля царицу. И рече царь: егда и жену насилует в дому моем? Аман же слышав изменися лицем.","Vozvratisâ že carʹ iz vertograda, i Aman pripade k ložu, na nemže be Esfirʹ, molâ caricu. I reče carʹ: egda i ženu nasiluet v domu moem? Aman že slyšav izmenisâ licem."],[7,9,"Рече же Вугафан един от скопцев, сей же ведяше о том древе, видев е в дому Аманове, егда призываше его на обед царский, и о сем испытав единаго от отрок, уразумев замышляемое, и рече ко царю: се, и древо уготова Аман Мардохею глаголавшему благая о цари, и стоит в дому Аманове возвышено на лакот пятьдесят. И рече царь: да повесится (Аман) на нем.","Reče že Vugafan edin ot skopcev, sej že vedâše o tom dreve, videv e v domu Amanove, egda prizyvaše ego na obed carskij, i o sem ispytav edinago ot otrok, urazumev zamyšlâemoe, i reče ko carû: se, i drevo ugotova Aman Mardoheû glagolavšemu blagaâ o cari, i stoit v domu Amanove vozvyšeno na lakot pâtʹdesât. I reče carʹ: da povesitsâ (Aman) na nem."],[7,10,"И повешен бысть Аман на древе, еже уготова Мардохею. И тогда царь утолися от ярости.","I povešen bystʹ Aman na dreve, eže ugotova Mardoheû. I togda carʹ utolisâ ot ârosti."],[8,1,"И в той день царь Артаксеркс дарова Есфири, елика бяху Амана клеветника (Иудейска): и Мардохеи призван бысть от царя, поведа бо Есфирь, яко сродник есть ей.","I v toj denʹ carʹ Artakserks darova Esfiri, elika bâhu Amana klevetnika (Iudejska): i Mardohei prizvan bystʹ ot carâ, poveda bo Esfirʹ, âko srodnik estʹ ej."],[8,2,"И сня царь перстень свой, егоже отя у Амана, и даде Мардохееви. И постави Есфирь Мардохеа над всем имением Амановым,","I snâ carʹ perstenʹ svoj, egože otâ u Amana, i dade Mardoheevi. I postavi Esfirʹ Mardohea nad vsem imeniem Amanovym,"],[8,3,"и приложи глаголати ко царю, и припаде пред ногама его (и восплака), и моляше его отвратити злобу Аманову и мысль его, еюже помысли на Иудеи.","i priloži glagolati ko carû, i pripade pred nogama ego (i vosplaka), i molâše ego otvratiti zlobu Amanovu i myslʹ ego, eûže pomysli na Iudei."],[8,4,"И простре царь Есфири жезл злат: воста же Есфирь и ста пред царем.","I prostre carʹ Esfiri žezl zlat: vosta že Esfirʹ i sta pred carem."],[8,5,"И рече Есфирь: аще угодно ти есть, и обретох благодать пред тобою, посли возвратити писания посланная от Амана, писаная на погубление Иудеов, иже обитают во (всем) царствии твоем:","I reče Esfirʹ: aŝe ugodno ti estʹ, i obretoh blagodatʹ pred toboû, posli vozvratiti pisaniâ poslannaâ ot Amana, pisanaâ na pogublenie Iudeov, iže obitaût vo (vsem) carstvii tvoem:"],[8,6,"како бо возмогу видети озлобление людий моих и како возмогу спастися в погибели отечества моего?","kako bo vozmogu videti ozloblenie lûdij moih i kako vozmogu spastisâ v pogibeli otečestva moego?"],[8,7,"И рече царь Есфири: аще вся имения Аманова дах и даровах тебе, и того повесих на древе, яко руце вознесе на Иудеи, что еще просиши?","I reče carʹ Esfiri: aŝe vsâ imeniâ Amanova dah i darovah tebe, i togo povesih na dreve, âko ruce voznese na Iudei, čto eŝe prosiši?"],[8,8,"Напишите и вы именем моим, якоже угодно есть вам, и запечатайте перстнем моим: елика бо писана бывают царевым повелением и запечатаются перстнем моим, не возможно им противорещи.","Napišite i vy imenem moim, âkože ugodno estʹ vam, i zapečatajte perstnem moim: elika bo pisana byvaût carevym poveleniem i zapečataûtsâ perstnem moim, ne vozmožno im protivoreŝi."],[8,9,"И призвани быша писцы (царевы) в первый месяц, иже есть Нисан, в двадесять третий день тогожде месяца, и написаша о Иудеех, елика заповеда Мардохей, ко управителем и ко началником воевод от Индийския страны даже до Ефиопии, сто двадесять седми воеводам, во всякую страну по своему их языку.","I prizvani byša piscy (carevy) v pervyj mesâc, iže estʹ Nisan, v dvadesâtʹ tretij denʹ togožde mesâca, i napisaša o Iudeeh, elika zapoveda Mardohej, ko upravitelem i ko načalnikom voevod ot Indijskiâ strany daže do Efiopii, sto dvadesâtʹ sedmi voevodam, vo vsâkuû stranu po svoemu ih âzyku."],[8,10,"Написана же быша велением царевым и запечатлешася перстнем его: и послаша писания чрез писмоносцы,","Napisana že byša veleniem carevym i zapečatlešasâ perstnem ego: i poslaša pisaniâ črez pismonoscy,"],[8,11,"яко повеле им жити по законом их во всяцем граде, и да помогают им, и да сотворят соперником их и противником их, якоже хотят,","âko povele im žiti po zakonom ih vo vsâcem grade, i da pomogaût im, i da sotvorât sopernikom ih i protivnikom ih, âkože hotât,"],[8,12,"в день един по всему царству Артаксерксову, в третийнадесять день вторагонадесять месяца, иже есть Адар.","v denʹ edin po vsemu carstvu Artakserksovu, v tretijnadesâtʹ denʹ vtoragonadesâtʹ mesâca, iže estʹ Adar."],[8,13,"Списание же епистолии сице бе: царь великий Артаксеркс сущым от Индии даже до Ефиопии сто двадесяти и седмим началством странами обладающым и властелем нам доброжелателствующым, радоватися. Мнози множайшею благодетелствующих благостию частее чествуеми паче меры возгордешася, и не точию подчиненных нам ищут озлобити, но доволства не могуще снести, и своим благодетелем начинают коварствовати: и благодарение не токмо от человек отемлюще, но еще (по обычаю) не приявших благодеяний киченьми вознесшеся, вся присно назирающаго Бога ненавидящаго зла мнят избежати суда. Многажды же и многих от поставленных на властех, имже уверися другов устрояти дела, ласкателство кровей неповинных виновными поставляя, подверже неуврачеванным злым, злонравия ложным прельщением тех, иже прельщают незлобивое благосердие владеющих. Видети же леть есть нам взыскующым не толико от древних, якоже предахом, историй, елико от тех, яже суть при ногах непреподобно соделанная губителством недостойно владеющих. Сего ради внимати надлежит по сих, во еже царство безмятежно всем человеком с миром устроити, не употребляюще пременений, приходящая же пред очеса всегда с приличным предварением разсуждающе. Егда бо Аман Амадафуев Македонянин, истинно чуждь Персския крове и много отстоящь от нашея благости, страннолюбно приятый от нас, толикое человеколюбие, еже ко всякому языку имеем, получи, яко нарицатися ему отцем нашим, и покланяемому от всех, второе царскаго престола лице содержати: неумерителен же в гордости прилежно искал, како бы нас области и живота лишити, купно же нашего блюстителя и всегдашняго благодетеля Мардохеа и непорочную царства сообщницу Есфирь со всем их племенем многоплетенными хитростей прельщеньми ищущь на погубление: сими бо образы возмне нас лишив блюстителей взяти, и власть Персскую ко Македоняном пренести. Мы же Иудеов, от трегубителнаго сего в погубление преданных, обретаем не злотворных, но праведнейшими управляемых законы, и сущих сынов Вышняго, превеличайнаго живаго Бога, управляющаго нам же и прародителем нашым царствие в добрейшем состоянии. Добре убо сотворите не употребляюще от Амана Амадафуева посланных Писаний, понеже он сия соделавый при вратех Сусских со всем домом своим повешен есть, достойный ему вскоре суд воздавшему всеми владеющему Богу. Списание же епистолии сея предложивше на всяцем месте со дерзновением, оставите Иудеов употребляти своя законы, спомоществующе им, яко да во время скорби воставшым на них отмстят в третийнадесять день вторагонадесять месяца Адара в самый той день: в сей бо (день) всемогущий Бог вместо погубления избраннаго рода сотвори им веселие. И вы убо во именитых ваших праздницех знаменитый день со всякою радостию провождайте, да и ныне, и по сих спасение нам убо и доброжелателным Персом будет, наветующым же нас в память погубления. Всяк же град или страна, яже по сим не сотворит, всячески мечем и огнем с толиким потребится гневом, яко не токмо человеком непроходна, но и зверем и птицам во всякое время мерзостнейша оставится. И списания сия да предложатся очевидно во всем царстве, еже готовым быти всем Иудеом на сей день ратовати своих противных.","Spisanie že epistolii sice be: carʹ velikij Artakserks suŝym ot Indii daže do Efiopii sto dvadesâti i sedmim načalstvom stranami obladaûŝym i vlastelem nam dobroželatelstvuûŝym, radovatisâ. Mnozi množajšeû blagodetelstvuûŝih blagostiû častee čestvuemi pače mery vozgordešasâ, i ne točiû podčinennyh nam iŝut ozlobiti, no dovolstva ne moguŝe snesti, i svoim blagodetelem načinaût kovarstvovati: i blagodarenie ne tokmo ot čelovek otemlûŝe, no eŝe (po obyčaû) ne priâvših blagodeânij kičenʹmi voznesšesâ, vsâ prisno naziraûŝago Boga nenavidâŝago zla mnât izbežati suda. Mnogaždy že i mnogih ot postavlennyh na vlasteh, imže uverisâ drugov ustroâti dela, laskatelstvo krovej nepovinnyh vinovnymi postavlââ, podverže neuvračevannym zlym, zlonraviâ ložnym prelʹŝeniem teh, iže prelʹŝaût nezlobivoe blagoserdie vladeûŝih. Videti že letʹ estʹ nam vzyskuûŝym ne toliko ot drevnih, âkože predahom, istorij, eliko ot teh, âže sutʹ pri nogah neprepodobno sodelannaâ gubitelstvom nedostojno vladeûŝih. Sego radi vnimati nadležit po sih, vo eže carstvo bezmâtežno vsem čelovekom s mirom ustroiti, ne upotreblâûŝe premenenij, prihodâŝaâ že pred očesa vsegda s priličnym predvareniem razsuždaûŝe. Egda bo Aman Amadafuev Makedonânin, istinno čuždʹ Persskiâ krove i mnogo otstoâŝʹ ot našeâ blagosti, strannolûbno priâtyj ot nas, tolikoe čelovekolûbie, eže ko vsâkomu âzyku imeem, poluči, âko naricatisâ emu otcem našim, i poklanâemomu ot vseh, vtoroe carskago prestola lice soderžati: neumeritelen že v gordosti priležno iskal, kako by nas oblasti i života lišiti, kupno že našego blûstitelâ i vsegdašnâgo blagodetelâ Mardohea i neporočnuû carstva soobŝnicu Esfirʹ so vsem ih plemenem mnogopletennymi hitrostej prelʹŝenʹmi iŝuŝʹ na pogublenie: simi bo obrazy vozmne nas lišiv blûstitelej vzâti, i vlastʹ Persskuû ko Makedonânom prenesti. My že Iudeov, ot tregubitelnago sego v pogublenie predannyh, obretaem ne zlotvornyh, no pravednejšimi upravlâemyh zakony, i suŝih synov Vyšnâgo, preveličajnago živago Boga, upravlâûŝago nam že i praroditelem našym carstvie v dobrejšem sostoânii. Dobre ubo sotvorite ne upotreblâûŝe ot Amana Amadafueva poslannyh Pisanij, poneže on siâ sodelavyj pri vrateh Susskih so vsem domom svoim povešen estʹ, dostojnyj emu vskore sud vozdavšemu vsemi vladeûŝemu Bogu. Spisanie že epistolii seâ predloživše na vsâcem meste so derznoveniem, ostavite Iudeov upotreblâti svoâ zakony, spomoŝestvuûŝe im, âko da vo vremâ skorbi vostavšym na nih otmstât v tretijnadesâtʹ denʹ vtoragonadesâtʹ mesâca Adara v samyj toj denʹ: v sej bo (denʹ) vsemoguŝij Bog vmesto pogubleniâ izbrannago roda sotvori im veselie. I vy ubo vo imenityh vaših prazdniceh znamenityj denʹ so vsâkoû radostiû provoždajte, da i nyne, i po sih spasenie nam ubo i dobroželatelnym Persom budet, navetuûŝym že nas v pamâtʹ pogubleniâ. Vsâk že grad ili strana, âže po sim ne sotvorit, vsâčeski mečem i ognem s tolikim potrebitsâ gnevom, âko ne tokmo čelovekom neprohodna, no i zverem i pticam vo vsâkoe vremâ merzostnejša ostavitsâ. I spisaniâ siâ da predložatsâ očevidno vo vsem carstve, eže gotovym byti vsem Iudeom na sej denʹ ratovati svoih protivnyh."],[8,14,"Конницы убо изыдоша спешно повеленная от царя совершити. Предлагашеся же повеление и в Сусех.","Konnicy ubo izydoša spešno povelennaâ ot carâ soveršiti. Predlagašesâ že povelenie i v Suseh."],[8,15,"И Мардохей изыде облечен в царскую одежду и венец имущь златый, диадиму виссонную, червленую. Видевше же сущии в Сусех возрадовашася,","I Mardohej izyde oblečen v carskuû odeždu i venec imuŝʹ zlatyj, diadimu vissonnuû, červlenuû. Videvše že suŝii v Suseh vozradovašasâ,"],[8,16,"яко Иудеом бысть свет и веселие:","âko Iudeom bystʹ svet i veselie:"],[8,17,"во (всяцем) граде и стране, идеже аще предлагашеся повеление радость и веселие бе Иудеом, пирование и утешение. И мнози от язык обрезовахуся и закон Иудейский приимаху, страха ради Иудейскаго.","vo (vsâcem) grade i strane, ideže aŝe predlagašesâ povelenie radostʹ i veselie be Iudeom, pirovanie i utešenie. I mnozi ot âzyk obrezovahusâ i zakon Iudejskij priimahu, straha radi Iudejskago."],[9,1,"Во вторыйнадесять месяц, иже есть Адар, в третийнадесять день месяца приидоша писания от царя.","Vo vtoryjnadesâtʹ mesâc, iže estʹ Adar, v tretijnadesâtʹ denʹ mesâca priidoša pisaniâ ot carâ."],[9,2,"В той же день погибоша супостаты Иудеев: ни един бо сопротивися им бояся их.","V toj že denʹ pogiboša supostaty Iudeev: ni edin bo soprotivisâ im boâsâ ih."],[9,3,"Началствующии бо странам и властителие и царстии книгочия почитаху Иудей:","Načalstvuûŝii bo stranam i vlastitelie i carstii knigočiâ počitahu Iudej:"],[9,4,"страх бо Мардохеев належаше на них.","strah bo Mardoheev naležaše na nih."],[9,5,"Приложися бо повеление царево именоватися ему по всему царствию.","Priložisâ bo povelenie carevo imenovatisâ emu po vsemu carstviû."],[9,6,"И в Сусех граде избиша Иудее пять сот мужей:","I v Suseh grade izbiša Iudee pâtʹ sot mužej:"],[9,7,"Фарсана, нестанна и Делфона, и Фасгана","Farsana, nestanna i Delfona, i Fasgana"],[9,8,"и Фардафана, и Вареа и Сарвакана,","i Fardafana, i Varea i Sarvakana,"],[9,9,"и Мармасима и Руфеа, и Арсеа и Завуфефама,","i Marmasima i Rufea, i Arsea i Zavufefama,"],[9,10,"десять сынов Амана Амадафуева Вугеанина врага Иудеом, иже от Фармафеа, и разграбиша в той день (имения их):","desâtʹ synov Amana Amadafueva Vugeanina vraga Iudeom, iže ot Farmafea, i razgrabiša v toj denʹ (imeniâ ih):"],[9,11,"и сказаша число избиенных царю в Сусех граде.","i skazaša čislo izbiennyh carû v Suseh grade."],[9,12,"И рече царь ко Есфири: избиша Иудее в Сусе граде пять сот мужей, по окрестным же странам колико, мниши, погубиша? И чесого еще просиши, и будет ти?","I reče carʹ ko Esfiri: izbiša Iudee v Suse grade pâtʹ sot mužej, po okrestnym že stranam koliko, mniši, pogubiša? I česogo eŝe prosiši, i budet ti?"],[9,13,"И рече Есфирь ко царю: да дастся такожде Иудеом творити заутра, яко да повесят десять сынов Амановых.","I reče Esfirʹ ko carû: da dastsâ takožde Iudeom tvoriti zautra, âko da povesât desâtʹ synov Amanovyh."],[9,14,"И повеле царь тако быти, и попусти Иудеом вне града повесити телеса сынов Амановых.","I povele carʹ tako byti, i popusti Iudeom vne grada povesiti telesa synov Amanovyh."],[9,15,"И собрашася Иудее, иже в Сусех, в четвертыйнадесять деень Адара, и избиша мужей триста, и ничтоже разграбиша.","I sobrašasâ Iudee, iže v Suseh, v četvertyjnadesâtʹ deenʹ Adara, i izbiša mužej trista, i ničtože razgrabiša."],[9,16,"Прочии же Иудее, иже во царствии, собрашася и себе помогаху и почиша от браней: избиша бо от них пятьнадесять тысящ в третийнадесять Адара, и ничтоже расхитиша.","Pročii že Iudee, iže vo carstvii, sobrašasâ i sebe pomogahu i počiša ot branej: izbiša bo ot nih pâtʹnadesâtʹ tysâŝ v tretijnadesâtʹ Adara, i ničtože rashitiša."],[9,17,"И почиша в четвертыйнадесять день тогожде месяца и провождаху той день упокоения с радостию и веселием.","I počiša v četvertyjnadesâtʹ denʹ togožde mesâca i provoždahu toj denʹ upokoeniâ s radostiû i veseliem."],[9,18,"Иудее же в Сусех граде собрашася и в четвертыйнадесять почиша: проводиша же и пятыйнадесять с радостию и веселием.","Iudee že v Suseh grade sobrašasâ i v četvertyjnadesâtʹ počiša: provodiša že i pâtyjnadesâtʹ s radostiû i veseliem."],[9,19,"Сего ради Иудее разсеяннии во всяцей стране внешней провождают четвертыйнадесять день Адара благ с веселием, посылающе части кийждо ближнему: живущий же в митрополиях и в пятыйнадесять день Адара веселия благий провождают, посылающе части ближним.","Sego radi Iudee razseânnii vo vsâcej strane vnešnej provoždaût četvertyjnadesâtʹ denʹ Adara blag s veseliem, posylaûŝe časti kijždo bližnemu: živuŝij že v mitropoliâh i v pâtyjnadesâtʹ denʹ Adara veseliâ blagij provoždaût, posylaûŝe časti bližnim."],[9,20,"Написа же Мардохей словеса сия в книгу и посла Иудеом, елицы беша в царствии Артаксерксове, близ и далече сущым,","Napisa že Mardohej slovesa siâ v knigu i posla Iudeom, elicy beša v carstvii Artakserksove, bliz i daleče suŝym,"],[9,21,"уставити дни сия благи, еже провождати четвертыйнадесять и пятыйнадесять день Адара:","ustaviti dni siâ blagi, eže provoždati četvertyjnadesâtʹ i pâtyjnadesâtʹ denʹ Adara:"],[9,22,"в сих бо днех почиша Иудее от враг своих: и месяц Адар, иже обратися им от плача в радость и от болезни во благий день, провождати весь во благих днех радости и веселия, посылающе части ко другом и нищым.","v sih bo dneh počiša Iudee ot vrag svoih: i mesâc Adar, iže obratisâ im ot plača v radostʹ i ot bolezni vo blagij denʹ, provoždati vesʹ vo blagih dneh radosti i veseliâ, posylaûŝe časti ko drugom i niŝym."],[9,23,"И прияша Иудее, якоже написа им Мардохей:","I priâša Iudee, âkože napisa im Mardohej:"],[9,24,"како Аман Амадафуев Македонянин ратоваше Иудеев, и како изнесе суд и жребий, еже погубити их,","kako Aman Amadafuev Makedonânin ratovaše Iudeev, i kako iznese sud i žrebij, eže pogubiti ih,"],[9,25,"и яко вниде ко царю, глаголя, да повесит Мардохеа: елика нача наводити на Иудеи злая, на него быша, и повешен бысть сам и чада его.","i âko vnide ko carû, glagolâ, da povesit Mardohea: elika nača navoditi na Iudei zlaâ, na nego byša, i povešen bystʹ sam i čada ego."],[9,26,"Сего ради нарекошася дние сии Фурим ради жребий, зане диалектом их жребии нарицаются фурим, ради словес епистолии сея, и елика пострадаша сих ради, и елика им приключишася.","Sego radi narekošasâ dnie sii Furim radi žrebij, zane dialektom ih žrebii naricaûtsâ furim, radi sloves epistolii seâ, i elika postradaša sih radi, i elika im priklûčišasâ."],[9,27,"Устави убо, и тако прияша Иудее на себе и на семя свое и на ириложившихся к ним, ниже иначе да употребляют: дние же сии памяти совершаеми по роду и роду, и граду и отечеству и стране.","Ustavi ubo, i tako priâša Iudee na sebe i na semâ svoe i na iriloživšihsâ k nim, niže inače da upotreblâût: dnie že sii pamâti soveršaemi po rodu i rodu, i gradu i otečestvu i strane."],[9,28,"Дние же сии Фурим да провождают во всякое лето, и память да не оскудеет от родов.","Dnie že sii Furim da provoždaût vo vsâkoe leto, i pamâtʹ da ne oskudeet ot rodov."],[9,29,"И написа Есфирь царица дщи Аминадавля и Мардохей Иудеанин, елика сотвориша во утверждение епистолии о днех Фурим.","I napisa Esfirʹ carica dŝi Aminadavlâ i Mardohej Iudeanin, elika sotvoriša vo utverždenie epistolii o dneh Furim."],[9,30,"И Мардохей и Есфирь царица устависта себе сами, и тогда устависта в посте своем совет свой.","I Mardohej i Esfirʹ carica ustavista sebe sami, i togda ustavista v poste svoem sovet svoj."],[9,31,"И Есфирь слово постави во веки, и написано бысть в память.","I Esfirʹ slovo postavi vo veki, i napisano bystʹ v pamâtʹ."],[10,1,"Написа же царь по всему царствию своему, еже на земли и на мори,","Napisa že carʹ po vsemu carstviû svoemu, eže na zemli i na mori,"],[10,2,"и силу свою, и мужественная исправления, богатство же и славу царствия своего: се, писана суть в книзе царей Персских и Мидских, на память.","i silu svoû, i mužestvennaâ ispravleniâ, bogatstvo že i slavu carstviâ svoego: se, pisana sutʹ v knize carej Persskih i Midskih, na pamâtʹ."],[10,3,"Мардохей бо вторый бе по цари Артаксерксе, и велик бе во царствии и прославлен от Иудей и любимь, поведаше содеянная всему языку своему. И рече Мардохей: от Бога быша сия: помянух бо о сонии, еже видех о словесех сих, ниже бо премину от сих слово: малый источник, иже бысть река, и бе свет, и солнце, и вода многа. Есфирь есть река, юже поя царь и сотвори царицу: два же змиа, аз есмь и Аман: языцы же (суть), иже собрашася истребити имя Иудеов: язык же мой сей есть Израиль, вопивший ко Богу, и спасошася: и спасе Господь люди Своя и избави нас Господь от всех зол сих: и сотвори Бог знамения и чудеса велия, яже не быша во языцех. Сего ради сотвори два жребия, един людем Божиим и един всем языком: и изыдоста два жребия сия в час и время и в день суда пред Богом во всех языцех: и помяну Господь Бог люди Своя и оправда достояние Свое: и будут им дние сии (праздничнии) в месяц Адар, в четвертыйнадесять и пятыйнадесять день месяца тогожде, с собором и радостию и с веселием пред Богом, в род во веки в людех Своих Израили. В лето четвертое царствия Птоломеева и Клеопатры, внесе Досифей, иже глаголашеся быти священник и левит, и Птоломей сын его, предлежащую епистолию о (днех) Фурим, юже сказоваху, яко истолкова Лисимах сын Птоломеев, живый во Иерусалиме.","Mardohej bo vtoryj be po cari Artakserkse, i velik be vo carstvii i proslavlen ot Iudej i lûbimʹ, povedaše sodeânnaâ vsemu âzyku svoemu. I reče Mardohej: ot Boga byša siâ: pomânuh bo o sonii, eže videh o sloveseh sih, niže bo preminu ot sih slovo: malyj istočnik, iže bystʹ reka, i be svet, i solnce, i voda mnoga. Esfirʹ estʹ reka, ûže poâ carʹ i sotvori caricu: dva že zmia, az esmʹ i Aman: âzycy že (sutʹ), iže sobrašasâ istrebiti imâ Iudeov: âzyk že moj sej estʹ Izrailʹ, vopivšij ko Bogu, i spasošasâ: i spase Gospodʹ lûdi Svoâ i izbavi nas Gospodʹ ot vseh zol sih: i sotvori Bog znameniâ i čudesa veliâ, âže ne byša vo âzyceh. Sego radi sotvori dva žrebiâ, edin lûdem Božiim i edin vsem âzykom: i izydosta dva žrebiâ siâ v čas i vremâ i v denʹ suda pred Bogom vo vseh âzyceh: i pomânu Gospodʹ Bog lûdi Svoâ i opravda dostoânie Svoe: i budut im dnie sii (prazdničnii) v mesâc Adar, v četvertyjnadesâtʹ i pâtyjnadesâtʹ denʹ mesâca togožde, s soborom i radostiû i s veseliem pred Bogom, v rod vo veki v lûdeh Svoih Izraili. V leto četvertoe carstviâ Ptolomeeva i Kleopatry, vnese Dosifej, iže glagolašesâ byti svâŝennik i levit, i Ptolomej syn ego, predležaŝuû epistoliû o (dneh) Furim, ûže skazovahu, âko istolkova Lisimah syn Ptolomeev, živyj vo Ierusalime."]],"eng-thomson-partial":[[1,1,"After these things, in the days of Artaxerxes the same who reigned from India, over a hundred and twenty seven provinces,","After these things, in the days of Artaxerxes the same who reigned from India, over a hundred and twenty seven provinces,"],[1,2,"when Artaxerxes was settled on his throne in the city Susoi,","when Artaxerxes was settled on his throne in the city Susoi,"],[1,3,"in the third year of his reign, he made an entertainment for his friends, both for other nations, and for the nobles of the Persians and Medes, and for the governors.","in the third year of his reign, he made an entertainment for his friends, both for other nations, and for the nobles of the Persians and Medes, and for the governors."],[1,4,"And having after this displayed to them the riches of his kingdom, and the transporting glory of his riches, for a hundred and eighty days,","And having after this displayed to them the riches of his kingdom, and the transporting glory of his riches, for a hundred and eighty days,"],[1,5,"when the days of his marriage were fulfilled, the king made an entertainment for all the nations who were in the city, for six days, in the court of the royal palace,","when the days of his marriage were fulfilled, the king made an entertainment for all the nations who were in the city, for six days, in the court of the royal palace,"],[1,6,"which was adorned with painted hangings of cotton, extended with cords of cotton, and purple yarn, to capitals of gold and silver, on pillars of parian marble and alabaster. The couches were of gold and silver, on a pavement of smaragdine, pinine, and parian stone and their covers were of gause, painted with a variety of flowers; and roses were scattered all around.","which was adorned with painted hangings of cotton, extended with cords of cotton, and purple yarn, to capitals of gold and silver, on pillars of parian marble and alabaster. The couches were of gold and silver, on a pavement of smaragdine, pinine, and parian stone and their covers were of gause, painted with a variety of flowers; and roses were scattered all around."],[1,7,"The goblets of gold and silver, with a small carbuncled cup to each, amounted in value to thirty thousand talents. There was wine in abundance and of a sweet quality, such as the king himself drank.","The goblets of gold and silver, with a small carbuncled cup to each, amounted in value to thirty thousand talents. There was wine in abundance and of a sweet quality, such as the king himself drank."],[1,8,"Now this entertainment was not according to an established custom; but the king would have it so, and he commanded the stewards to comply with his pleasure, and that of the guests.","Now this entertainment was not according to an established custom; but the king would have it so, and he commanded the stewards to comply with his pleasure, and that of the guests."],[1,9,"Astin the queen also made an entertainment for the women in the royal palace, where king Artaxerxes was.","Astin the queen also made an entertainment for the women in the royal palace, where king Artaxerxes was."],[1,10,"And on the seventh day, the king, in high good humour, ordered Anian and Basan and Tharra and Barazi and Zatholtha and Abataza and Tharaba, the seven chamberlains, who waited on king Artaxerxes,","And on the seventh day, the king, in high good humour, ordered Anian and Basan and Tharra and Barazi and Zatholtha and Abataza and Tharaba, the seven chamberlains, who waited on king Artaxerxes,"],[1,11,"to bring the queen to him to proclaim her queen, and crown her with a diadem, and shew her to the chiefs, and her beauty to the nations; for she was beautiful.","to bring the queen to him to proclaim her queen, and crown her with a diadem, and shew her to the chiefs, and her beauty to the nations; for she was beautiful."],[1,12,"But queen Astin hearkened not to him to come with the chamberlain, at which the king was greatly offended and inflamed with anger","But queen Astin hearkened not to him to come with the chamberlain, at which the king was greatly offended and inflamed with anger"],[1,13,"and he said to his friends, Astin hath spoken so and so; do you therefore execute law and judgment, touching this matter.","and he said to his friends, Astin hath spoken so and so; do you therefore execute law and judgment, touching this matter."],[1,14,"Thereupon there came before him, Arkesaius and Sarsathaius and Malisear the chiefs of the Persians and Medes, who were near the king, and had the first seats next him;","Thereupon there came before him, Arkesaius and Sarsathaius and Malisear the chiefs of the Persians and Medes, who were near the king, and had the first seats next him;"],[1,15,"and told him according to the laws what ought to be done to queen Astin, because she had not done what the king had commanded by the chamberlains.","and told him according to the laws what ought to be done to queen Astin, because she had not done what the king had commanded by the chamberlains."],[1,16,"And Muchaius said to the king and to the chiefs, Queen Astin hath wronged, not the king only, but also all the king's chiefs and leaders;","And Muchaius said to the king and to the chiefs, Queen Astin hath wronged, not the king only, but also all the king's chiefs and leaders;"],[1,17,"for he hath told them the queen's conduct and how she hath contradicted the king. Therefore as she hath contradicted the king Artaxerxes,","for he hath told them the queen's conduct and how she hath contradicted the king. Therefore as she hath contradicted the king Artaxerxes,"],[1,18,"so will the rest of the ladies now, the wives of the Persian and Medean princes, upon hearing what she hath said to the king, presume in like manner to dishonour their husbands.","so will the rest of the ladies now, the wives of the Persian and Medean princes, upon hearing what she hath said to the king, presume in like manner to dishonour their husbands."],[1,19,"If therefore it seemeth good to the king, let him pass a royal decree and let it be written according to the laws of the Medes and Persians, and let him not alter it nor suffer the queen any more to approach him; but let the king give her royalty to another woman, better than her.","If therefore it seemeth good to the king, let him pass a royal decree and let it be written according to the laws of the Medes and Persians, and let him not alter it nor suffer the queen any more to approach him; but let the king give her royalty to another woman, better than her."],[1,20,"And let this edict of the king be proclaimed, which if he cause to be done throughout his kingdom, then will all the women both rich and poor, pay respect to their husbands.","And let this edict of the king be proclaimed, which if he cause to be done throughout his kingdom, then will all the women both rich and poor, pay respect to their husbands."],[1,21,"And the speech pleased the king and the princes; and the king did as Muchaius had spoken,","And the speech pleased the king and the princes; and the king did as Muchaius had spoken,"],[1,22,"and sent the decree throughout the whole kingdom, into every province in the language and writing thereof, that men might be feared by their own families.","and sent the decree throughout the whole kingdom, into every province in the language and writing thereof, that men might be feared by their own families."],[2,1,"After this when the king's wrath was appeased and he no more remembered Astin, nor made any mention of what she had spoken, and how he had condemned her;","After this when the king's wrath was appeased and he no more remembered Astin, nor made any mention of what she had spoken, and how he had condemned her;"],[2,2,"the king's servants said, Let there be sought for the king a virgin of unblemished chastity, and beautiful;","the king's servants said, Let there be sought for the king a virgin of unblemished chastity, and beautiful;"],[2,3,"and let the king appoint officers in all the provinces of his kingdom, and let them select and send to the city Susoi to the house of the women, virgins remarkable for beauty; and let them be delivered to the king's chamberlain, the keeper of the women; and let the things necessary for purification be given them.","and let the king appoint officers in all the provinces of his kingdom, and let them select and send to the city Susoi to the house of the women, virgins remarkable for beauty; and let them be delivered to the king's chamberlain, the keeper of the women; and let the things necessary for purification be given them."],[2,4,"And let the woman who shall please the king be made queen in the room of Astin. And the proposal pleased the king, and he did so.","And let the woman who shall please the king be made queen in the room of Astin. And the proposal pleased the king, and he did so."],[2,5,"Now there was at the city of Susoi, a man, a Jew, whose name was Mordecai. He was the son of Jairus, the son of Semeias, the son of Kisaius, of the tribe of Benjamin.","Now there was at the city of Susoi, a man, a Jew, whose name was Mordecai. He was the son of Jairus, the son of Semeias, the son of Kisaius, of the tribe of Benjamin."],[2,6,"He had been carried away captive from Jerusalem among them whom Nabuchodonosar king of Babylon had captivated.","He had been carried away captive from Jerusalem among them whom Nabuchodonosar king of Babylon had captivated."],[2,7,"And this man had a foster child, a daughter of Aminadab, his father's brother; and her name was Esther. On the decease of her parents he educated her to be a wife for himself.","And this man had a foster child, a daughter of Aminadab, his father's brother; and her name was Esther. On the decease of her parents he educated her to be a wife for himself."],[2,8,"But as the girl was beautiful, when the decree of the king was published, and many young women were brought to the city Susoi and put under the care of Gai, Esther also was brought to Gai the keeper of the women.","But as the girl was beautiful, when the decree of the king was published, and many young women were brought to the city Susoi and put under the care of Gai, Esther also was brought to Gai the keeper of the women."],[2,9,"And the young woman pleased him and found favour in his sight, so that he hastened to give her the things for purification and the allotted portion; and seven waiting maids were assigned to her out of the king's house: and he treated her and her maids courteously in the house of the women.","And the young woman pleased him and found favour in his sight, so that he hastened to give her the things for purification and the allotted portion; and seven waiting maids were assigned to her out of the king's house: and he treated her and her maids courteously in the house of the women."],[2,10,"Now Esther did not disclose her family, nor her country; for Mordecai had charged her not to tell.","Now Esther did not disclose her family, nor her country; for Mordecai had charged her not to tell."],[2,11,"But Mordecai walked every day before the court of the womens' house to see what would happen to Esther.","But Mordecai walked every day before the court of the womens' house to see what would happen to Esther."],[2,12,"Now the time for every young woman to go to the king was when she had compleated twelve months; for thus were the days of their purification fulfilled. Six months they were anointed with oil of myrrh, and six months with aromatics and lotions used by women.","Now the time for every young woman to go to the king was when she had compleated twelve months; for thus were the days of their purification fulfilled. Six months they were anointed with oil of myrrh, and six months with aromatics and lotions used by women."],[2,13,"Then she goeth in to the king. The keeper is to deliver her to whomsoever the king ordereth to go with her from the womens' apartment to the king's house.","Then she goeth in to the king. The keeper is to deliver her to whomsoever the king ordereth to go with her from the womens' apartment to the king's house."],[2,14,"In the evening she goeth in, and in the morning goeth with all speed to the second house of the women, which is under the care of Gai the king's chamberlain, the keeper of the women, and no more cometh to the king unless called for by name.","In the evening she goeth in, and in the morning goeth with all speed to the second house of the women, which is under the care of Gai the king's chamberlain, the keeper of the women, and no more cometh to the king unless called for by name."],[2,15,"So when the time was fulfilled for Esther the daughter of Aminadab, Mordecai's uncle, to go to the king, she neglected nothing which the chamberlain the keeper of the women ordered her; for Esther found favour with all who saw her.","So when the time was fulfilled for Esther the daughter of Aminadab, Mordecai's uncle, to go to the king, she neglected nothing which the chamberlain the keeper of the women ordered her; for Esther found favour with all who saw her."],[2,16,"And Esther went in to Artaxerxes the king, in the twelfth month which is the month Adar in the seventh year of his reign.","And Esther went in to Artaxerxes the king, in the twelfth month which is the month Adar in the seventh year of his reign."],[2,17,"And the king was enamoured of Esther, and she found favour above all the virgins, so that he set the queen's crown on her head","And the king was enamoured of Esther, and she found favour above all the virgins, so that he set the queen's crown on her head"],[2,18,"and made an entertainment for all his friends and potentates for seven days, and to celebrate the marriage of Esther he made a release to those under his government.","and made an entertainment for all his friends and potentates for seven days, and to celebrate the marriage of Esther he made a release to those under his government."],[2,19,"Now Mordecai performed service in the court,","Now Mordecai performed service in the court,"],[2,20,"and Esther had not yet declared her family, for Mordecai having charged her in this manner to fear God and execute his commands as when she was with him, Esther did not alter her conduct.","and Esther had not yet declared her family, for Mordecai having charged her in this manner to fear God and execute his commands as when she was with him, Esther did not alter her conduct."],[2,21,"And two of the king's chamberlains, who were captains of his life guard, being displeased because Mordecai was promoted, sought to kill king Artaxerxes.","And two of the king's chamberlains, who were captains of his life guard, being displeased because Mordecai was promoted, sought to kill king Artaxerxes."],[2,22,"But the matter being made known to Mordecai, he informed Esther and she disclosed the conspiracy to the king;","But the matter being made known to Mordecai, he informed Esther and she disclosed the conspiracy to the king;"],[2,23,"whereupon the king having examined the chamberlains, caused them to be hanged, and ordered a record to be made in the royal library with an encomium on Mordecai's fidelity.","whereupon the king having examined the chamberlains, caused them to be hanged, and ordered a record to be made in the royal library with an encomium on Mordecai's fidelity."],[3,1,"After these things king Artaxerxes honoured Haman of Amadathus the Bougaian, and promoted him, and seated him first of all his friends,","After these things king Artaxerxes honoured Haman of Amadathus the Bougaian, and promoted him, and seated him first of all his friends,"],[3,2,"so that all the court bowed down to him for so the king had commanded to be done. But Mordecai did not bow down to him;","so that all the court bowed down to him for so the king had commanded to be done. But Mordecai did not bow down to him;"],[3,3,"whereupon they who were in the king's court said to him, Mordecai, Why trangressest thou the king's commands.","whereupon they who were in the king's court said to him, Mordecai, Why trangressest thou the king's commands."],[3,4,"And when they spoke to him daily and he hearkened not to them, they told Haman, that Mordecai disobeyed the king's commands. Now Mordecai had told them that he was a Jew.","And when they spoke to him daily and he hearkened not to them, they told Haman, that Mordecai disobeyed the king's commands. Now Mordecai had told them that he was a Jew."],[3,5,"So when Haman understood that Mordecai did not bow down to him, he was greatly inflamed with wrath,","So when Haman understood that Mordecai did not bow down to him, he was greatly inflamed with wrath,"],[3,6,"and determined to destroy all the Jews throughout the whole kingdom of Artaxerxes.","and determined to destroy all the Jews throughout the whole kingdom of Artaxerxes."],[3,7,"And having drawn up a decree in the twelfth year of the reign of Artaxerxes, he cast lots for one day after another and for one month after another so as to destroy the whole race of Mordecai in one day. And the lot having fallen on the fourteenth day of the month Adar,","And having drawn up a decree in the twelfth year of the reign of Artaxerxes, he cast lots for one day after another and for one month after another so as to destroy the whole race of Mordecai in one day. And the lot having fallen on the fourteenth day of the month Adar,"],[3,8,"he spoke to king Artaxerxes, saying, There is a nation scattered among the nations throughout thy whole kingdom, whose laws differ from all the nations. And as they disobey the king's laws and it is not expedient for the king to let them alone;","he spoke to king Artaxerxes, saying, There is a nation scattered among the nations throughout thy whole kingdom, whose laws differ from all the nations. And as they disobey the king's laws and it is not expedient for the king to let them alone;"],[3,9,"if it seemeth good to the king, let him pass a decree to destroy them and I will subscribe ten thousand talents of silver to the king's treasury.","if it seemeth good to the king, let him pass a decree to destroy them and I will subscribe ten thousand talents of silver to the king's treasury."],[3,10,"Thereupon the king taking off his ring gave it to Haman to seal the writings against the Jews.","Thereupon the king taking off his ring gave it to Haman to seal the writings against the Jews."],[3,11,"And the king said to Haman, Keep the money, and do with the nation what thou pleasest.","And the king said to Haman, Keep the money, and do with the nation what thou pleasest."],[3,12,"So the king's secretaries were convened on the thirteenth day of the first month, and they wrote as Haman directed to the generals and the governors in every province, from India to Ethiopia a hundred and twenty seven provinces, and to the chiefs of the nations according to their dialect in the name of king Artaxerxes,","So the king's secretaries were convened on the thirteenth day of the first month, and they wrote as Haman directed to the generals and the governors in every province, from India to Ethiopia a hundred and twenty seven provinces, and to the chiefs of the nations according to their dialect in the name of king Artaxerxes,"],[3,13,"and the decree was despatched by posts throughout the whole kingdom of Artaxerxes, to destroy the race of the Jews on a certain day of the twelfth month which is Adar, and to make spoil of their goods.","and the decree was despatched by posts throughout the whole kingdom of Artaxerxes, to destroy the race of the Jews on a certain day of the twelfth month which is Adar, and to make spoil of their goods."],[3,14,"And copies of the decree were to be sent through every province and all the nations were ordered to be ready against that day.","And copies of the decree were to be sent through every province and all the nations were ordered to be ready against that day."],[3,15,"And when the business was despatched at Susoi, the king and Haman sat down to revel, but the city was struck with consternation.","And when the business was despatched at Susoi, the king and Haman sat down to revel, but the city was struck with consternation."],[4,1,"Now when Mordecai knew what was done, he rent his clothes and put on sackcloth and strewed himself with ashes, and running through the street of the city, he cried with a loud voice, A nation is to be cut off, which hath committed no fault.","Now when Mordecai knew what was done, he rent his clothes and put on sackcloth and strewed himself with ashes, and running through the street of the city, he cried with a loud voice, A nation is to be cut off, which hath committed no fault."],[4,2,"But when he came to the king's gate, he stopped; for it was not lawful for him to enter the court in sackcloth and ashes.","But when he came to the king's gate, he stopped; for it was not lawful for him to enter the court in sackcloth and ashes."],[4,3,"And in every country where the writings were published there was a cry with lamentation and great grief among the Jews, and they put on sackcloth and ashes.","And in every country where the writings were published there was a cry with lamentation and great grief among the Jews, and they put on sackcloth and ashes."],[4,4,"When the queen's maids and chamberlains came in and told her, she was troubled at the news, and sent to clothe Mordecai and to take away his sackcloth from him; but he would not be persuaded.","When the queen's maids and chamberlains came in and told her, she was troubled at the news, and sent to clothe Mordecai and to take away his sackcloth from him; but he would not be persuaded."],[4,5,"Then Esther called Achrathaius her chamberlain, who attended her, and sent him to learn from Mordecai an exact state of the matter.","Then Esther called Achrathaius her chamberlain, who attended her, and sent him to learn from Mordecai an exact state of the matter."],[4,7,"Whereupon Mordecai told him what was done and the promise which Haman had made to the king of ten thousand talents to the royal treasury, that he might destroy the Jews;","Whereupon Mordecai told him what was done and the promise which Haman had made to the king of ten thousand talents to the royal treasury, that he might destroy the Jews;"],[4,8,"and he gave him a copy of the decree for their destruction, which was published among the Susians to shew it to Esther, and told him that he charged her to go in and supplicate the king and to entreat him for the people, calling to mind the days of thy humiliation when thou wast brought up by my bounty. Seeing Haman who is second to the king, hath spoken against us to destroy us, call thou upon the Lord and speak to the king for us, to deliver us from death.","and he gave him a copy of the decree for their destruction, which was published among the Susians to shew it to Esther, and told him that he charged her to go in and supplicate the king and to entreat him for the people, calling to mind the days of thy humiliation when thou wast brought up by my bounty. Seeing Haman who is second to the king, hath spoken against us to destroy us, call thou upon the Lord and speak to the king for us, to deliver us from death."],[4,9,"Accordingly Achrathaius went in and told her all these words.","Accordingly Achrathaius went in and told her all these words."],[4,10,"Thereupon Esther said to him, Go to Mordecai and tell him,","Thereupon Esther said to him, Go to Mordecai and tell him,"],[4,11,"that all the nations of the kingdom know, that no man or woman who shall go to the king into the inner court without being sent for, hath any security for life: he only can be saved to whom the king shall stretch forth the golden sceptre. Now I have not been called to go to the king these thirty days.","that all the nations of the kingdom know, that no man or woman who shall go to the king into the inner court without being sent for, hath any security for life: he only can be saved to whom the king shall stretch forth the golden sceptre. Now I have not been called to go to the king these thirty days."],[4,12,"When Achrathaius delivered this message of Esther to Mordecai,","When Achrathaius delivered this message of Esther to Mordecai,"],[4,13,"Mordecai said to him, Go say to her, Esther, do not flatter thyself that thou alone of all the Jews in the kingdom shall escape.","Mordecai said to him, Go say to her, Esther, do not flatter thyself that thou alone of all the Jews in the kingdom shall escape."],[4,14,"Be assured, that if thou neglectest the present opportunity, help and protection will come to the Jews from some other quarter; but thou and thy father's house shall be destroyed. Who knoweth but that for this very occasion thou hast been made queen.","Be assured, that if thou neglectest the present opportunity, help and protection will come to the Jews from some other quarter; but thou and thy father's house shall be destroyed. Who knoweth but that for this very occasion thou hast been made queen."],[4,15,"Then Esther sent back the messenger to Mordecai, saying,","Then Esther sent back the messenger to Mordecai, saying,"],[4,16,"Go and assemble the Jews who are at Susoi and fast for me. You must neither eat nor drink for three days; night nor day; and as for me, I and my maids will fast likewise, and then I will go to the king contrary to law, though perhaps I must die.","Go and assemble the Jews who are at Susoi and fast for me. You must neither eat nor drink for three days; night nor day; and as for me, I and my maids will fast likewise, and then I will go to the king contrary to law, though perhaps I must die."],[4,17,"So Mordecai went and did as Esther commanded him.","So Mordecai went and did as Esther commanded him."],[5,1,"And on the third day Esther put on her royal apparel and stood in the inner court of the king's palace over against the king's house, when the king was sitting on his royal throne, in the royal house, over against the gate.","And on the third day Esther put on her royal apparel and stood in the inner court of the king's palace over against the king's house, when the king was sitting on his royal throne, in the royal house, over against the gate."],[5,2,"And when the king saw Esther standing in the court, she obtained favour in his sight, and the king held out to Esther the golden sceptre which was in his hand, and Esther drew near and touched the top of the sceptre.","And when the king saw Esther standing in the court, she obtained favour in his sight, and the king held out to Esther the golden sceptre which was in his hand, and Esther drew near and touched the top of the sceptre."],[5,3,"And the king said, What would queen Esther? And what is thy petition? To the half of my kingdom it shall be granted thee.","And the king said, What would queen Esther? And what is thy petition? To the half of my kingdom it shall be granted thee."],[5,4,"Thereupon Esther said, To-day is my set day, if therefore it seemeth good to the king, let him come with Haman to the banquet which I will this day prepare.","Thereupon Esther said, To-day is my set day, if therefore it seemeth good to the king, let him come with Haman to the banquet which I will this day prepare."],[5,5,"And the king said, Call Haman quickly that we may do as Esther hath said. So they both went to the banquet which Esther had ordered.","And the king said, Call Haman quickly that we may do as Esther hath said. So they both went to the banquet which Esther had ordered."],[5,6,"And at the banquet the king said to Esther, What would queen Esther? Whatever thou askest shall be granted.","And at the banquet the king said to Esther, What would queen Esther? Whatever thou askest shall be granted."],[5,7,"To which she replied,","To which she replied,"],[5,8,"If I have found favour in the sight of the king, Let the king come again with Haman to-morrow to the banquet which I will prepare for them, and to-morrow I will make my request and my petition.","If I have found favour in the sight of the king, Let the king come again with Haman to-morrow to the banquet which I will prepare for them, and to-morrow I will make my request and my petition."],[5,9,"Then Haman went out from the king overjoyed and gladdened, but upon seeing Mordecai the Jew in the court, he was inflamed with great indignation.","Then Haman went out from the king overjoyed and gladdened, but upon seeing Mordecai the Jew in the court, he was inflamed with great indignation."],[5,10,"So going home, he called his friends and his wife Zosara,","So going home, he called his friends and his wife Zosara,"],[5,11,"and having displayed to them his riches and the honour which the king had conferred on him; how he had promoted him to the highest rank and made him ruler of the kingdom,","and having displayed to them his riches and the honour which the king had conferred on him; how he had promoted him to the highest rank and made him ruler of the kingdom,"],[5,12,"the queen, said he, invited none to the banquet with the king, but only me: and to-morrow I am invited:","the queen, said he, invited none to the banquet with the king, but only me: and to-morrow I am invited:"],[5,13,"but these things give me no pleasure, when I see Mordecai the Jew in the court.","but these things give me no pleasure, when I see Mordecai the Jew in the court."],[5,14,"Thereupon Zosara his wife and his friends said to him, Let a gallows fifty cubits high be made for thee, and early in the morning speak to the king and let Mordecai be hanged thereon, then go to the banquet with the king and take thy fill of joy. And the thing pleased Haman. So the gallows was got ready.","Thereupon Zosara his wife and his friends said to him, Let a gallows fifty cubits high be made for thee, and early in the morning speak to the king and let Mordecai be hanged thereon, then go to the banquet with the king and take thy fill of joy. And the thing pleased Haman. So the gallows was got ready."],[6,1,"Now on that night the Lord removed sleep from the king, therefore he ordered his attendant to bring the book of daily records, and read to him;","Now on that night the Lord removed sleep from the king, therefore he ordered his attendant to bring the book of daily records, and read to him;"],[6,2,"and finding what was written concerning Mordecai, how he had informed the king of the king's two chamberlains, when they commanded the guard, and sought to lay hands on Artaxerxes,","and finding what was written concerning Mordecai, how he had informed the king of the king's two chamberlains, when they commanded the guard, and sought to lay hands on Artaxerxes,"],[6,3,"the king said, What honour or favour did we confer on Mordecai? To which the king's servants replied, Thou hast conferred none.","the king said, What honour or favour did we confer on Mordecai? To which the king's servants replied, Thou hast conferred none."],[6,4,"And while the king was making inquiry concerning Mordecai's fidelity behold Haman was in the court. And the king said, Who is in the court? Now Haman had come to speak to the king, that he might order Mordecai to be hanged on the gallows which he had prepared.","And while the king was making inquiry concerning Mordecai's fidelity behold Haman was in the court. And the king said, Who is in the court? Now Haman had come to speak to the king, that he might order Mordecai to be hanged on the gallows which he had prepared."],[6,5,"So the king's servants said, Behold Haman is standing in the court, and the king said, Call him in.","So the king's servants said, Behold Haman is standing in the court, and the king said, Call him in."],[6,6,"And the king said to Haman, What shall I do to the man whom I wish to honour? Upon this Haman said to himself, Whom doth the king wish to honour but me?","And the king said to Haman, What shall I do to the man whom I wish to honour? Upon this Haman said to himself, Whom doth the king wish to honour but me?"],[6,7,"So he said to the king, With regard to the man whom the king wisheth to honour,","So he said to the king, With regard to the man whom the king wisheth to honour,"],[6,8,"Let the king's servants bring out the royal robes with which the king is arrayed, and the horse on which the king rideth,","Let the king's servants bring out the royal robes with which the king is arrayed, and the horse on which the king rideth,"],[6,9,"and give them to one of the most honourable of the king's friends, and let him array the man whom the king loveth, and mount him on the horse, and make proclamation through the street of the city saying, Thus shall it be done to every man whom the king honoureth.","and give them to one of the most honourable of the king's friends, and let him array the man whom the king loveth, and mount him on the horse, and make proclamation through the street of the city saying, Thus shall it be done to every man whom the king honoureth."],[6,10,"Then the king said to Haman, Thou hast spoken well, Do thou so to Mordecai the Jew, who is an attendant in the court. Let nothing be omitted of what thou hast spoken.","Then the king said to Haman, Thou hast spoken well, Do thou so to Mordecai the Jew, who is an attendant in the court. Let nothing be omitted of what thou hast spoken."],[6,11,"So Haman took the robe and the horse, and having arrayed Mordecai he mounted him on the horse, and went through the street of the city and made proclamation saying, Thus shall it be done to every man whom the king wisheth to honour.","So Haman took the robe and the horse, and having arrayed Mordecai he mounted him on the horse, and went through the street of the city and made proclamation saying, Thus shall it be done to every man whom the king wisheth to honour."],[6,12,"Then Mordecai returned to the court, and Haman went home in grief with his head covered.","Then Mordecai returned to the court, and Haman went home in grief with his head covered."],[6,13,"And when Haman told his wife and his friends all that had happened to him; his friends and his wife said, If Mordecai be of the race of the Jews thy humiliation before him is begun. Thou shalt continue falling and shalt not be able to have thy revenge of him; for with him is the living God.","And when Haman told his wife and his friends all that had happened to him; his friends and his wife said, If Mordecai be of the race of the Jews thy humiliation before him is begun. Thou shalt continue falling and shalt not be able to have thy revenge of him; for with him is the living God."],[6,14,"And while they were speaking the chamberlains came to hasten Haman to the banquet which Esther had prepared.","And while they were speaking the chamberlains came to hasten Haman to the banquet which Esther had prepared."],[7,1,"And when the king came with Haman to banquet with the queen,","And when the king came with Haman to banquet with the queen,"],[7,2,"the king said to Esther the second day at the banquet, What is it queen Esther? What is thy request, and what thy petition? to the half of my kingdom it shall be granted thee.","the king said to Esther the second day at the banquet, What is it queen Esther? What is thy request, and what thy petition? to the half of my kingdom it shall be granted thee."],[7,3,"Thereupon she in reply said, If I have found favour in the sight of the king, let my life be granted at my request, and my people at my petition;","Thereupon she in reply said, If I have found favour in the sight of the king, let my life be granted at my request, and my people at my petition;"],[7,4,"for I and my people are sold to be destroyed. Had it been to be plundered and reduced to slavery—that we and our children should be bondmen and bondwomen, I would have dissembled hearing it, for the accuser is not worthy of the king's court.","for I and my people are sold to be destroyed. Had it been to be plundered and reduced to slavery—that we and our children should be bondmen and bondwomen, I would have dissembled hearing it, for the accuser is not worthy of the king's court."],[7,5,"And the king said, Who is he who hath dared to do such a thing?","And the king said, Who is he who hath dared to do such a thing?"],[7,6,"To which Esther replied, The adversary is Haman, this bad man. At this Haman was struck with consternation for fear of the king and the queen.","To which Esther replied, The adversary is Haman, this bad man. At this Haman was struck with consternation for fear of the king and the queen."],[7,7,"Then the king rising from the banquet went into the garden, and Haman supplicated the queen, for he saw himself in a desperate situation.","Then the king rising from the banquet went into the garden, and Haman supplicated the queen, for he saw himself in a desperate situation."],[7,8,"And on the king's returning out of the garden as Haman had prostrated himself on the sopha to supplicate the queen, the king said, What! would he offer violence to my wife in my house? Upon hearing this Haman was confounded.","And on the king's returning out of the garden as Haman had prostrated himself on the sopha to supplicate the queen, the king said, What! would he offer violence to my wife in my house? Upon hearing this Haman was confounded."],[7,9,"Then Bugathan one of the chamberlains said to the king, Behold Haman hath prepared a gallows for Mordecai who spoke for the king. There is at Haman's house a gallows actually erected fifty cubits high.","Then Bugathan one of the chamberlains said to the king, Behold Haman hath prepared a gallows for Mordecai who spoke for the king. There is at Haman's house a gallows actually erected fifty cubits high."],[7,10,"Thereupon the king said, Let him be hanged thereon. So Haman was hanged on the gallows which he had prepared for Mordecai, and the king's anger was appeased.","Thereupon the king said, Let him be hanged thereon. So Haman was hanged on the gallows which he had prepared for Mordecai, and the king's anger was appeased."],[8,1,"And on that same day the king made a present to Esther of all that belonged to Haman the accuser. And the king sent for Mordecai; (for Esther told him that he was her kinsman;)","And on that same day the king made a present to Esther of all that belonged to Haman the accuser. And the king sent for Mordecai; (for Esther told him that he was her kinsman;)"],[8,2,"and the king took the ring which he had taken back from Haman and gave it to Mordecai, and Esther set him over all that belonged to Haman.","and the king took the ring which he had taken back from Haman and gave it to Mordecai, and Esther set him over all that belonged to Haman."],[8,3,"Then she spoke to the king again and fell at his feet and besought him to avert the mischief of Haman, and what he had devised against the Jews.","Then she spoke to the king again and fell at his feet and besought him to avert the mischief of Haman, and what he had devised against the Jews."],[8,4,"And when the king stretched forth the golden sceptre to Esther,","And when the king stretched forth the golden sceptre to Esther,"],[8,5,"she arose and stood near the king and said, If it seemeth good to thee, and I have found favour, let despatches be sent to reverse the letters sent by Haman, which were written to destroy the Jews who are in thy kingdom.","she arose and stood near the king and said, If it seemeth good to thee, and I have found favour, let despatches be sent to reverse the letters sent by Haman, which were written to destroy the Jews who are in thy kingdom."],[8,6,"For how can I see the calamity of my people? or how can I survive the destruction of my kindred?","For how can I see the calamity of my people? or how can I survive the destruction of my kindred?"],[8,7,"Thereupon the king said to Esther, If I have given thee all the substance of Haman; and to gratify thee have caused him to be hanged on a gallows, because he laid his hands on the Jews, what more dost thou desire?","Thereupon the king said to Esther, If I have given thee all the substance of Haman; and to gratify thee have caused him to be hanged on a gallows, because he laid his hands on the Jews, what more dost thou desire?"],[8,8,"Write ye yourselves what you please in my name, and seal it with my ring. For what is written by the king's order, and sealed with my ring cannot be reversed.","Write ye yourselves what you please in my name, and seal it with my ring. For what is written by the king's order, and sealed with my ring cannot be reversed."],[8,9,"So the secretaries were convened in the first month which is Nisan, on the three and twentieth day thereof in the same year, and a letter was written to the Jews reciting all that had been given in charge to the lieutenants and to the chief governors of the provinces from India to Ethiopia, a hundred and twenty seven provinces, to every province as they could read it,","So the secretaries were convened in the first month which is Nisan, on the three and twentieth day thereof in the same year, and a letter was written to the Jews reciting all that had been given in charge to the lieutenants and to the chief governors of the provinces from India to Ethiopia, a hundred and twenty seven provinces, to every province as they could read it,"],[8,10,"then it was written by the king's command and sealed with his ring, (and these letters were sent by posts)","then it was written by the king's command and sealed with his ring, (and these letters were sent by posts)"],[8,11,"that he ordered them to use their own laws in every city, and to assist each other, and to use their adversaries, and them who assaulted them as they pleased,","that he ordered them to use their own laws in every city, and to assist each other, and to use their adversaries, and them who assaulted them as they pleased,"],[8,12,"on a certain day, the thirteenth of the twelfth month Adar, throughout the whole kingdom of Artaxerxes—that these subsequent writings were to counterbalance the former letter;","on a certain day, the thirteenth of the twelfth month Adar, throughout the whole kingdom of Artaxerxes—that these subsequent writings were to counterbalance the former letter;"],[8,13,"and that these counterbalancing writings should be exposed to publick view throughout the whole kingdom, that the Jews might be ready against that day to combat their adversaries.","and that these counterbalancing writings should be exposed to publick view throughout the whole kingdom, that the Jews might be ready against that day to combat their adversaries."],[8,14,"So the horsemen set out in all haste to execute the king's orders. And when the decree was published at Susoi,","So the horsemen set out in all haste to execute the king's orders. And when the decree was published at Susoi,"],[8,15,"Mordecai went forth, arrayed in a royal robe, wearing a crown of gold and a turban of purple cotton. And upon seeing him the inhabitants of Susoi rejoiced.","Mordecai went forth, arrayed in a royal robe, wearing a crown of gold and a turban of purple cotton. And upon seeing him the inhabitants of Susoi rejoiced."],[8,16,"And among the Jews, there was light and joy in every city and province where the decree was published.","And among the Jews, there was light and joy in every city and province where the decree was published."],[8,17,"Wherever proclamation was made, there was joy and gladness among the Jews, feasting and mirth; so that many of the nations were circumcised and became Jews, for fear of the Jews.","Wherever proclamation was made, there was joy and gladness among the Jews, feasting and mirth; so that many of the nations were circumcised and became Jews, for fear of the Jews."],[9,1,"For in the twelfth month, on the thirteenth of the month Adar, the letters of the king having arrived, they who assaulted the Jews on that day were destroyed.","For in the twelfth month, on the thirteenth of the month Adar, the letters of the king having arrived, they who assaulted the Jews on that day were destroyed."],[9,2,"For none withstood them and the terror of them continued;","For none withstood them and the terror of them continued;"],[9,3,"for the great lords and petty princes, and the king's secretaries, honoured the Jews; for the dread of Mordecai fell upon them;","for the great lords and petty princes, and the king's secretaries, honoured the Jews; for the dread of Mordecai fell upon them;"],[9,4,"for the decree of the king had caused his name to be known throughout the whole kingdom.","for the decree of the king had caused his name to be known throughout the whole kingdom."],[9,6,"Now in the city Susoi, the Jews slew five hundred men,","Now in the city Susoi, the Jews slew five hundred men,"],[9,7,"including Pharsanes and Delphon, and Phasga","including Pharsanes and Delphon, and Phasga"],[9,8,"and Pharadatha, and Barea and Sarbaka,","and Pharadatha, and Barea and Sarbaka,"],[9,9,"and Marmasima and Kuphaias, and Arsaius and Zabuthaias,","and Marmasima and Kuphaias, and Arsaius and Zabuthaias,"],[9,10,"the ten sons of Haman of Amadathu the Bugaian, the enemy of the Jews, and rifled them.","the ten sons of Haman of Amadathu the Bugaian, the enemy of the Jews, and rifled them."],[9,11,"On that very day, when a return was made to the king of the number slain at Susoi,","On that very day, when a return was made to the king of the number slain at Susoi,"],[9,12,"the king said to Esther, The Jews have slain in the city Susoi five hundred men, how then, thinkest thou, have they behaved in the rest of the kingdom! What therefore dost thou request farther, and it shall be granted thee?","the king said to Esther, The Jews have slain in the city Susoi five hundred men, how then, thinkest thou, have they behaved in the rest of the kingdom! What therefore dost thou request farther, and it shall be granted thee?"],[9,13,"Thereupon Esther said to the king, Let the Jews be allowed to use to-morrow in like manner, that they may hang up the ten sons of Haman.","Thereupon Esther said to the king, Let the Jews be allowed to use to-morrow in like manner, that they may hang up the ten sons of Haman."],[9,14,"Accordingly he granted them leave to do so, and ordered the bodies of the ten sons of Haman, to be thrown out to the Jews to be hanged up.","Accordingly he granted them leave to do so, and ordered the bodies of the ten sons of Haman, to be thrown out to the Jews to be hanged up."],[9,15,"So the Jews at Susoi assembled on the fourteenth day of the month Adar, and slew three hundred men, but took no spoil.","So the Jews at Susoi assembled on the fourteenth day of the month Adar, and slew three hundred men, but took no spoil."],[9,16,"Now the rest of the Jews who were in the kingdom, assembled and assisted each other, and had rest from their enemies, for they slew fifteen thousand of them on the thirteenth of the month Adar, but took no spoil.","Now the rest of the Jews who were in the kingdom, assembled and assisted each other, and had rest from their enemies, for they slew fifteen thousand of them on the thirteenth of the month Adar, but took no spoil."],[9,17,"And having rested on the fourteenth of the month, they kept it as a day of rest with joy and gladness.","And having rested on the fourteenth of the month, they kept it as a day of rest with joy and gladness."],[9,18,"But the Jews of Susoi having assembled on the fourteenth and then rested, kept the fifteenth with joy and gladness.","But the Jews of Susoi having assembled on the fourteenth and then rested, kept the fifteenth with joy and gladness."],[9,19,"Therefore because the Jews, who were scattered through all the distant provinces, keep the fourteenth of the month Adar, as a holy day, with joy, sending portions to one another,","Therefore because the Jews, who were scattered through all the distant provinces, keep the fourteenth of the month Adar, as a holy day, with joy, sending portions to one another,"],[9,20,"Mordecai wrote an account of these matters in a book, and sent it to all the Jews who were in the kingdom of Artaxerxes far and near,","Mordecai wrote an account of these matters in a book, and sent it to all the Jews who were in the kingdom of Artaxerxes far and near,"],[9,21,"to set apart as holy days and to keep both the fourteenth and the fifteenth of the month Adar,","to set apart as holy days and to keep both the fourteenth and the fifteenth of the month Adar,"],[9,22,"for in those days the Jews had rest from their enemies: And with regard to the month Adar, in which they had a change from grief to joy and from sorrow to gladness, to keep the whole month as good days of weddings and joy, sending portions to their friends and to the poor.","for in those days the Jews had rest from their enemies: And with regard to the month Adar, in which they had a change from grief to joy and from sorrow to gladness, to keep the whole month as good days of weddings and joy, sending portions to their friends and to the poor."],[9,23,"And the Jews took this upon them. As Mordecai wrote to them","And the Jews took this upon them. As Mordecai wrote to them"],[9,24,"how Haman of Amadathu, the Macedonian, warred against them—as he made calculations and cast lots to destroy them,","how Haman of Amadathu, the Macedonian, warred against them—as he made calculations and cast lots to destroy them,"],[9,25,"and as he went to the king with an intention to hang Mordecai, but all the evils he endeavoured to bring on the Jews, fell upon himself, and he and his sons were hanged;","and as he went to the king with an intention to hang Mordecai, but all the evils he endeavoured to bring on the Jews, fell upon himself, and he and his sons were hanged;"],[9,26,"therefore these days were called Phrouri, because of the lots, which in their language are called Phrouri. On the account of the things contained in that letter and of all that they suffered in consequence thereof, and all that happened to them, as he instituted,","therefore these days were called Phrouri, because of the lots, which in their language are called Phrouri. On the account of the things contained in that letter and of all that they suffered in consequence thereof, and all that happened to them, as he instituted,"],[9,27,"so the Jews took upon themselves and their posterity, and upon all that joined them, never to use them in any other manner.","so the Jews took upon themselves and their posterity, and upon all that joined them, never to use them in any other manner."],[9,28,"Therefore let these days be a lasting memorial from generation to generation, in every city, country and province; and let these days of Phrouri be kept forever; and let the memorial of them never perish from among their generations.","Therefore let these days be a lasting memorial from generation to generation, in every city, country and province; and let these days of Phrouri be kept forever; and let the memorial of them never perish from among their generations."],[9,29,"Then Esther the queen, the daughter of Aminadab, and Mordecai the Jew, wrote all that they did, and a confirmation of the letter respecting the Phrouri,","Then Esther the queen, the daughter of Aminadab, and Mordecai the Jew, wrote all that they did, and a confirmation of the letter respecting the Phrouri,"],[9,31,"which Mordecai and Esther the queen enjoined on themselves, to their own prejudice, having at that time established their counsel against their health.","which Mordecai and Esther the queen enjoined on themselves, to their own prejudice, having at that time established their counsel against their health."],[9,32,"Thus did Esther actually establish it, and it was written to be kept in remembrance.","Thus did Esther actually establish it, and it was written to be kept in remembrance."],[10,1,"Then the king laid a tribute upon the dominion both of the land and the sea.","Then the king laid a tribute upon the dominion both of the land and the sea."],[10,2,"But with regard to his power and his valour and the riches and the glory of his kingdom, behold they are written in the book of the kings of the Persians and the Medes to be kept in remembrance.","But with regard to his power and his valour and the riches and the glory of his kingdom, behold they are written in the book of the kings of the Persians and the Medes to be kept in remembrance."],[10,3,"Now Mordecai was viceroy of king Artaxerxes, and was great in the kingdom, and being honoured by the Jews and beloved, he enforced the observance of their religion on all his nation.","Now Mordecai was viceroy of king Artaxerxes, and was great in the kingdom, and being honoured by the Jews and beloved, he enforced the observance of their religion on all his nation."]]}};